INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#8','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C26',1,'blank','auto','[생각을 펼쳐요]에서는 대륙마다 가 보고 싶은 나라를 (    ) 정해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u3-X42']::text[],false,'{"seq":8,"concept":"SO6-1-u3-C26","difficulty":1,"kind":"blank","stem":"[생각을 펼쳐요]에서는 대륙마다 가 보고 싶은 나라를 (    ) 정해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"하나씩","correct":true},{"t":"둘씩","mis":"SO6-1-u3-X42"},{"t":"모두","mis":"SO6-1-u3-X42"},{"t":"한 대륙에서만","mis":"SO6-1-u3-X42"}],"explanation":["표의 한 줄이에요.","대륙마다예요.","하나씩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#9','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C6',2,'mc','auto','모둠 다가 그 거리가 세계의 어느 쪽에 있는지 먼저 알아보려 할 때 알맞은 방법은 어느 것인가요?',ARRAY['SO6-1-u3-X08','SO6-1-u3-X07','SO6-1-u3-X09']::text[],false,'{"seq":9,"concept":"SO6-1-u3-C6","difficulty":2,"kind":"mc","stem":"모둠 다가 그 거리가 세계의 어느 쪽에 있는지 먼저 알아보려 할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"화면을 줄여 넓게 본다","correct":true},{"t":"화면을 크게 늘린다","mis":"SO6-1-u3-X08"},{"t":"거리 측정만 누른다","mis":"SO6-1-u3-X07"},{"t":"화면을 끄고 기억에 맡긴다","mis":"SO6-1-u3-X09"}],"explanation":["어느 쪽인지 알려면요?","넓게 봐야 해요.","줄여요."],"asset":{"type":"passage","lines":["모둠 가 — 세계의 모습을 한눈에 보고 싶다.","모둠 나 — 두 나라의 면적을 비교적 정확하게 견주고 싶다.","모둠 다 — 가 보고 싶은 거리의 실제 모습을 사진으로 보고 싶다."],"title":"일지 ① — 모둠마다 고른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#10','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C9',2,'match','auto','두 기준선과 방향을 나타내는 낱말을 뜻과 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u3-C9","difficulty":2,"kind":"match","stem":"두 기준선과 방향을 나타내는 낱말을 뜻과 알맞게 이으세요.","pairs":[{"l":"적도","r":"위도 0° 선"},{"l":"본초 자오선","r":"경도 0° 선"},{"l":"남위","r":"적도를 기준으로 남쪽"},{"l":"서경","r":"본초 자오선을 기준으로 서쪽"}],"mis":"SO6-1-u3-X13","explanation":["두 기준선이에요.","남쪽이에요.","서쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#11','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C11',2,'error','auto','탐험 깃발을 꽂으며 위치를 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X18','SO6-1-u3-X19']::text[],false,'{"seq":11,"concept":"SO6-1-u3-C11","difficulty":2,"kind":"error","stem":"탐험 깃발을 꽂으며 위치를 나타내는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「경선 하나만 말해도 자리는 하나로 정해져.」","correct":true,"mis_target":"SO6-1-u3-X18"},{"t":"친구 나 — 「위선과 경선이 만나는 지점으로 나타내.」","mis":"SO6-1-u3-X18"},{"t":"친구 다 — 「어느 선을 먼저 그어도 만나는 지점은 같아.」","mis":"SO6-1-u3-X19"}],"explanation":["경선 위의 자리를 세어요.","여럿이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#12','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C15',2,'ox','auto','모든 대륙을 합쳐도 태평양보다 면적이 작아요.',ARRAY['SO6-1-u3-X25']::text[],false,'{"seq":12,"concept":"SO6-1-u3-C15","difficulty":2,"kind":"ox","stem":"모든 대륙을 합쳐도 태평양보다 면적이 작아요.","answer":"O","reason_options":[{"t":"태평양은 그만큼 넓은 대양이기 때문에","correct":true},{"t":"태평양은 가장 작은 대양이기 때문에","mis":"SO6-1-u3-X25"}],"mis":"SO6-1-u3-X25","explanation":["태평양을 떠올려요.","가장 넓어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#13','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C19',2,'error','auto','외교관이 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u3-X32']::text[],false,'{"seq":13,"concept":"SO6-1-u3-C19","difficulty":2,"kind":"error","stem":"외교관이 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「외교관은 다른 나라와 의견을 주고받지 않아.」","correct":true,"mis_target":"SO6-1-u3-X32"},{"t":"친구 가 — 「우리나라를 대표해 여러 나라와 협력해.」","mis":"SO6-1-u3-X32"},{"t":"친구 나 — 「외교 문제를 해결하는 일을 해.」","mis":"SO6-1-u3-X32"}],"explanation":["외교관은 무엇을 할까요?","의견을 주고받아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#14','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C20',2,'ox','auto','스위스는 바다에 접하지 않은 나라예요.',ARRAY['SO6-1-u3-X34']::text[],false,'{"seq":14,"concept":"SO6-1-u3-C20","difficulty":2,"kind":"ox","stem":"스위스는 바다에 접하지 않은 나라예요.","answer":"O","reason_options":[{"t":"스위스는 여러 나라에 둘러싸여 있기 때문에","correct":true},{"t":"스위스는 바다로 둘러싸인 섬나라이기 때문에","mis":"SO6-1-u3-X34"}],"mis":"SO6-1-u3-X34","explanation":["지도에서 찾아요.","바다가 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#15','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C24',2,'ox','auto','남아메리카는 북아메리카의 남쪽에 있어요.',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":15,"concept":"SO6-1-u3-C24","difficulty":2,"kind":"ox","stem":"남아메리카는 북아메리카의 남쪽에 있어요.","answer":"O","reason_options":[{"t":"두 대륙은 파나마 지협으로 위아래로 이어져 있기 때문에","correct":true},{"t":"남아메리카는 북아메리카의 북쪽에 있기 때문에","mis":"SO6-1-u3-X27"}],"mis":"SO6-1-u3-X27","explanation":["이름을 떠올려요.","남쪽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#16','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C26',2,'ox','auto','일지 ⑧의 경로는 여섯 대륙 가운데 다섯 대륙의 나라를 들러요.',ARRAY['SO6-1-u3-X27']::text[],false,'{"seq":16,"concept":"SO6-1-u3-C26","difficulty":2,"kind":"ox","stem":"일지 ⑧의 경로는 여섯 대륙 가운데 다섯 대륙의 나라를 들러요.","answer":"O","reason_options":[{"t":"아시아·아프리카·유럽·남아메리카·오세아니아의 나라를 들르기 때문에","correct":true},{"t":"여섯 대륙의 나라를 모두 들르기 때문에","mis":"SO6-1-u3-X27"}],"mis":"SO6-1-u3-X27","explanation":["대륙을 세어요.","북아메리카가 빠졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["새봄반 경로: 대한민국 출발 → 중국 → 이집트 → 영국","→ 브라질 → 오스트레일리아","한 친구가 「아직 길이 닫히지 않았어.」라고 말했다."],"title":"일지 ⑧ — 새봄반이 만든 여행 경로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#17','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C6',3,'mc','auto','디지털 영상 지도로 탐험할 나라를 살펴본 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X09']::text[],false,'{"seq":17,"concept":"SO6-1-u3-C6","difficulty":3,"kind":"mc","stem":"디지털 영상 지도로 탐험할 나라를 살펴본 뒤 해야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"알게 된 것을 일지에 적어 두고 다른 자료와도 견준다","correct":true},{"t":"화면에 다 있으니 적지 않는다","mis":"SO6-1-u3-X09"},{"t":"디지털 영상 지도만 믿고 다른 자료는 버린다","mis":"SO6-1-u3-X09"},{"t":"본 것은 바로 잊어도 된다","mis":"SO6-1-u3-X09"}],"explanation":["화면은 지금 것만 보여 줘요.","적어야 남아요.","다른 자료와도 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#18','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C12',3,'mc','auto','「북위 30°~40°, 서경 90°~100°」 범위를 찾을 때 맞는 방향은 어느 것인가요?',ARRAY['SO6-1-u3-X13']::text[],false,'{"seq":18,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「북위 30°~40°, 서경 90°~100°」 범위를 찾을 때 맞는 방향은 어느 것인가요?","options":[{"t":"적도의 북쪽, 본초 자오선의 서쪽","correct":true},{"t":"적도의 남쪽, 본초 자오선의 서쪽","mis":"SO6-1-u3-X13"},{"t":"적도의 북쪽, 본초 자오선의 동쪽","mis":"SO6-1-u3-X13"},{"t":"적도의 남쪽, 본초 자오선의 동쪽","mis":"SO6-1-u3-X13"}],"explanation":["북위예요.","서경이에요.","북쪽과 서쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#19','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C14',3,'mc','auto','세계의 대륙을 나누는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X23']::text[],false,'{"seq":19,"concept":"SO6-1-u3-C14","difficulty":3,"kind":"mc","stem":"세계의 대륙을 나누는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"주로 대양을 기준으로 나누고, 높은 산맥 등을 경계로 나누기도 한다","correct":true},{"t":"나라의 수로 나눈다","mis":"SO6-1-u3-X23"},{"t":"사람이 사는지로만 나눈다","mis":"SO6-1-u3-X23"},{"t":"위도와 경도의 크기로만 나눈다","mis":"SO6-1-u3-X23"}],"explanation":["바다를 떠올려요.","산맥도 있어요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#20','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C18',3,'mc','auto','오세아니아에 대한 설명으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X27','SO6-1-u3-X28','SO6-1-u3-X26']::text[],false,'{"seq":20,"concept":"SO6-1-u3-C18","difficulty":3,"kind":"mc","stem":"오세아니아에 대한 설명으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"오스트레일리아 대륙 하나만으로 이루어져 있다","correct":true},{"t":"대부분 남반구에 있다","mis":"SO6-1-u3-X27"},{"t":"세계에서 가장 작은 대륙이다","mis":"SO6-1-u3-X28"},{"t":"동쪽에 태평양, 서쪽에 인도양이 있다","mis":"SO6-1-u3-X26"}],"explanation":["「알맞지 않은」 것을 골라요.","섬도 많아요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#21','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C24',3,'mc','auto','남아메리카에서 바다에 접하지 않은 나라끼리 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u3-X40']::text[],false,'{"seq":21,"concept":"SO6-1-u3-C24","difficulty":3,"kind":"mc","stem":"남아메리카에서 바다에 접하지 않은 나라끼리 짝지은 것은 어느 것인가요?","options":[{"t":"볼리비아, 파라과이","correct":true},{"t":"칠레, 아르헨티나","mis":"SO6-1-u3-X40"},{"t":"브라질, 에콰도르","mis":"SO6-1-u3-X40"},{"t":"페루, 칠레","mis":"SO6-1-u3-X40"}],"explanation":["바다에 닿지 않아요.","두 나라예요.","볼리비아와 파라과이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#22','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C12',3,'mc','auto','「남위 20°~30°, 동경 120°~130°」 범위가 속한 나라는 어디인가요?',ARRAY['SO6-1-u3-X21','SO6-1-u3-X20']::text[],false,'{"seq":22,"concept":"SO6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「남위 20°~30°, 동경 120°~130°」 범위가 속한 나라는 어디인가요?","options":[{"t":"오스트레일리아","correct":true},{"t":"브라질","mis":"SO6-1-u3-X21"},{"t":"미국","mis":"SO6-1-u3-X21"},{"t":"케냐","mis":"SO6-1-u3-X20"}],"explanation":["남위예요.","동경이에요.","오스트레일리아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#23','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C15',4,'essay','teacher','일지 ④의 수수께끼 ㉠~㉣의 답을 쓰고, 그 가운데 둘의 위치와 특징을 이어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SO6-1-u3-C15","difficulty":4,"kind":"essay","stem":"일지 ④의 수수께끼 ㉠~㉣의 답을 쓰고, 그 가운데 둘의 위치와 특징을 이어 설명하세요.","answer_guide":{"answer":"예: ㉠은 태평양, ㉡은 남극해, ㉢은 북극해, ㉣은 남극 대륙이다. 태평양은 가장 넓은 대양으로 아시아·오세아니아·북아메리카·남아메리카 사이에 있고, 남극해는 남극 대륙을 둘러싼 바다로 둘레의 대륙이 남극 대륙 하나뿐이다.","scoring_points":["네 답을 바르게 썼는가","고른 둘의 위치를 썼는가","고른 둘의 특징을 썼는가"]},"explanation":["가장 넓은 바다예요.","두 극의 바다예요.","얼음 대륙이에요."],"asset":{"type":"passage","lines":["㉠ 가장 넓은 대양","㉡ 남극 대륙을 둘러싼 바다","㉢ 아시아·유럽·북아메리카에 둘러싸인 바다","㉣ 얼음으로 덮여 사람이 살기 어려운 대륙"],"title":"일지 ④ — 지구본 수수께끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#24','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C21',4,'essay','teacher','아프리카가 다른 대륙과 다른 점을 위치와 관련지어 쓰고, 아프리카 나라를 두 무리로 나누는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u3-C21","difficulty":4,"kind":"essay","stem":"아프리카가 다른 대륙과 다른 점을 위치와 관련지어 쓰고, 아프리카 나라를 두 무리로 나누는 방법을 쓰세요.","answer_guide":{"answer":"예: 아프리카는 유럽의 남쪽에 있으며 적도를 기준으로 북반구와 남반구에 걸쳐 있어, 북반구에 있는 나라도 남반구에 있는 나라도 있다. 그래서 적도를 선으로 그어 그것을 기준으로 북쪽에 있는 나라와 남쪽에 있는 나라로 나눌 수 있다.","scoring_points":["아프리카의 위치를 썼는가","두 반구에 걸쳐 있음을 썼는가","적도를 기준으로 나눈다고 썼는가"]},"explanation":["유럽의 남쪽이에요.","적도가 지나요.","적도로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u3_review_d#25','soc',6,1,'u3','','g6_1_soc_u3_review_d','unit_review','SO6-1-u3-C14',4,'essay','teacher','이 단원에서 배운 대륙 일곱과 대양 다섯을 쓰고, 대륙과 대양이 서로 맞닿아 있다는 것을 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u3-C14","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 대륙 일곱과 대양 다섯을 쓰고, 대륙과 대양이 서로 맞닿아 있다는 것을 예를 들어 설명하세요.","answer_guide":{"answer":"예: 대륙은 아시아, 오세아니아, 유럽, 아프리카, 북아메리카, 남아메리카, 남극 대륙이고, 대양은 태평양, 대서양, 인도양, 북극해, 남극해이다. 아시아는 동쪽의 태평양, 남쪽의 인도양, 북쪽의 북극해와 맞닿아 있고, 남극 대륙은 남극해에 둘러싸여 있다.","scoring_points":["대륙 일곱을 썼는가","대양 다섯을 썼는가","맞닿은 예를 들었는가"]},"explanation":["육지 일곱이에요.","바다 다섯이에요.","아시아를 예로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C1','kor',6,2,'u1',2,'작가의 의도 알기 — 작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 작가의 의도라 하고, 같은 작품도 근거가 있으면 서로 다르게 읽을 수 있음을 알기',ARRAY['6국05 문학(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C2','kor',6,2,'u1',2,'되풀이하거나 힘준 표현에서 뜻 찾기 — 작품에서 되풀이한 말, 물음으로 끝맺는 등 힘준 표현을 찾아 그 표현이 주는 느낌과 담긴 뜻을 생각하기(시조는 세 줄이라 고르고 고른 말이 실마리)',ARRAY['6국05 문학(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C3','kor',6,2,'u1',2,'작가의 삶을 실마리로 작품 다시 읽기 — 작가가 살아온 삶을 알아보아 작품을 다시 보되, 삶만으로 뜻을 하나로 정하지 않고 작품으로 돌아와 근거를 찾기',ARRAY['6국05 문학(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C4','kor',6,2,'u1',4,'시어의 뜻을 짐작하며 시 읽기 — 길·담·닫힌 문·발자국처럼 여러 뜻을 품은 시어가 무엇을 나타내는지 앞뒤 연을 근거로 짐작하고, 여러 번 읽으며 스스로 느낀 것과 짐작한 의도를 근거와 한 묶음으로 말하기',ARRAY['6국05 문학(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C5','kor',6,2,'u1',7,'이야기 구조 알기 — 이야기를 발단(시작)·전개(사건이 본격적으로 생김)·절정(긴장감이 높아지거나 갈등이 두드러짐)·결말(마무리)로 나누고, 경계는 까닭을 말할 수 있으면 사람마다 다를 수 있음을 알기',ARRAY['6국02 읽기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C6','kor',6,2,'u1',7,'이야기의 줄거리 간추리기 — 부분마다 중요한 사건을 골라, 덜 중요한 것은 덜어 내고, 무슨 일이 왜 일어났는지 이어지도록 짧게 적기(늘어놓기·통째 옮기기·뭉뚱그리기 피하기)',ARRAY['6국02 읽기(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C7','kor',6,2,'u1',9,'인물의 마음과 시간 표현 읽기 — 앞뒤 사건을 근거로 인물의 마음을 짐작하고, 지난여름·여름내·사흘째·이튿날 같은 시간을 나타내는 표현으로 일의 차례를 가려 읽으며, 이야기 속 낱말의 뜻 알기',ARRAY['6국02 읽기(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C8','kor',6,2,'u1',12,'문학 작품 소개하기 — 처음(제목·작가·고른 까닭)·가운데(간추린 줄거리·짐작한 의도와 근거)·끝(내 생각·권할 사람)으로 소개하고, 광고처럼 쓰지 않으며, 찾은 글은 간추려 내 말로 쓰고 출처를 적고, 친구에게 근거를 묻는 물음 하기',ARRAY['6국05 문학(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C9','kor',6,2,'u1',12,'여러 뜻을 지닌 낱말 — 차다·눈·쓰다·타다처럼 글자가 같아도 뜻이 다른 낱말을 앞뒤 문장을 보고 알맞은 뜻으로 가려 읽기(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X01','kor',6,'u1',ARRAY['K6-2-u1-C1']::text[],'작가의 의도를 모두가 똑같이 내야 하는 정답이나 작가가 살던 때의 기록으로 여긴다','쓴 사람 쪽에서 — 「왜 썼을까, 무엇을 느끼길 바랐을까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X02','kor',6,'u1',ARRAY['K6-2-u1-C2','K6-2-u1-C4','K6-2-u1-C6','K6-2-u1-C7']::text[],'작품에 없는 내용(내 짐작·바깥 정보)을 작품에 나온 것으로 고른다','작품에 적힌 말에 밑줄부터 — 적혀 있지 않으면 근거가 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X03','kor',6,'u1',ARRAY['K6-2-u1-C2']::text[],'되풀이하거나 힘준 표현을 그냥 지나가는 말로 여기거나 글자 그대로만 받아들인다(백 번 = 정확히 백 번)','두 번 나온 말, 물음으로 끝난 말에 동그라미 — 왜 힘을 줬을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X04','kor',6,'u1',ARRAY['K6-2-u1-C1','K6-2-u1-C3']::text[],'작가의 삶만 보고 작품의 뜻을 하나로 정해 버리고 작품에서 근거를 찾지 않는다','작가의 삶은 실마리 — 「그렇다면 시의 어느 줄이?」로 돌아가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X05','kor',6,'u1',ARRAY['K6-2-u1-C3']::text[],'작가의 삶은 작품과 상관없다고 여겨 아예 알아보지 않는다','작가를 알면 그냥 지나친 말이 다시 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X06','kor',6,'u1',ARRAY['K6-2-u1-C1','K6-2-u1-C4','K6-2-u1-C7','K6-2-u1-C8']::text[],'근거 없이 느낌만 말하거나, 근거가 있는 다른 읽기를 틀렸다고 한다','맞고 틀림이 아니라 근거가 있고 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X07','kor',6,'u1',ARRAY['K6-2-u1-C1']::text[],'작품을 감상하는 대신 어느 쪽이 옳은지 내 결론을 말한다','「작가는 무엇을 전하려 했나?」만 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X08','kor',6,'u1',ARRAY['K6-2-u1-C4']::text[],'시어를 겉뜻으로만 읽는다(담 = 집의 생김새, 발자국 = 더러운 자국)','그 낱말이 나온 연에서 인물이 어떤 처지인지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X09','kor',6,'u1',ARRAY['K6-2-u1-C5']::text[],'발단·전개·절정·결말을 헷갈리거나 경계가 하나로만 정해진다고 여긴다','긴장감이 가장 높은 곳(절정)부터 찾고 앞뒤를 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X10','kor',6,'u1',ARRAY['K6-2-u1-C6']::text[],'사건을 늘어놓기만 해서 무슨 일이 왜 일어났는지 이어지지 않는 줄거리를 쓴다','「~해서 ~하자 ~했다」처럼 이음말로 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X11','kor',6,'u1',ARRAY['K6-2-u1-C6','K6-2-u1-C8']::text[],'덜 중요한 것까지 통째로 옮기거나, 반대로 중요한 사건을 빼고 한 문장으로 뭉뚱그린다','부분마다 중요한 사건 하나씩 — 네 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X12','kor',6,'u1',ARRAY['K6-2-u1-C7']::text[],'인물의 마음을 앞뒤 사건 근거 없이 엉뚱하게 짐작한다','「바로 앞에 무슨 일이 있었지? 곁에 누가 있었지?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X13','kor',6,'u1',ARRAY['K6-2-u1-C8']::text[],'작품 소개를 광고하는 말(대박·별 다섯)이나 책값·쪽수처럼 작품과 상관없는 것으로 채운다','읽는 사람이 「어떤 작품인지」 알 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X14','kor',6,'u1',ARRAY['K6-2-u1-C8']::text[],'찾은 글을 그대로 옮겨 붙이고 어디에서 찾았는지 적지 않는다','두세 줄로 간추려 내 말로 + 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X15','kor',6,'u1',ARRAY['K6-2-u1-C7','K6-2-u1-C9']::text[],'낱말만 보고 뜻을 정해 앞뒤 문장에 맞지 않는 뜻을 고른다','그 문장이 무엇에 대한 말인지 먼저 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X16','kor',6,'u1',ARRAY['K6-2-u1-C7']::text[],'시간을 나타내는 표현을 놓쳐 일의 차례나 때를 뒤바꾼다','지난여름·여름내·사흘째·이튿날에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X17','kor',6,'u1',ARRAY['K6-2-u1-C2','K6-2-u1-C4']::text[],'시조·시의 짜임(시조는 세 줄, 시는 연과 행)을 모르거나 표현을 형식 맞추기로만 여긴다','시조 세 줄 · 시는 연(덩어리)과 행(줄)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#1','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C1',1,'mc','auto','작가의 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X02']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작가의 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것","correct":true},{"t":"작품을 읽고 모두가 똑같이 내야 하는 답","mis":"K6-2-u1-X01"},{"t":"작가가 살던 때에 있었던 일의 기록","mis":"K6-2-u1-X01"},{"t":"작품에 나오는 어려운 낱말의 뜻","mis":"K6-2-u1-X02"}],"explanation":["작가의 의도는 쓴 사람 쪽에서 생각해요.","작가가 왜 썼는지, 읽는 사람이 무엇을 느끼기를 바랐는지가 의도예요.","모두가 똑같이 내야 하는 정답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#2','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','시조 「같이 건너세」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조 「같이 건너세」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"또 한","correct":true},{"t":"길이 되고","mis":"K6-2-u1-X03"},{"t":"한 마을로","mis":"K6-2-u1-X03"},{"t":"건너오면","mis":"K6-2-u1-X03"}],"explanation":["「또 한 돌을」, 「또 한 사람」에 「또 한」이 두 번 나와요.","되풀이된 말은 그냥 지나가는 말이 아니라 눈여겨볼 표시예요.","작은 것이 하나씩 쌓이는 모습이 드러나요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#3','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'sa','auto','시조 「나루를 지켜」 첫째 줄에서 두 번 되풀이된 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u1-C2","difficulty":1,"kind":"sa","stem":"시조 「나루를 지켜」 첫째 줄에서 두 번 되풀이된 말을 쓰세요.","answer":["백 번","백번"],"explanation":["「이 나루 백 번 고쳐 백 번을 다시 매도」예요.","「백 번」이 두 번 나와요.","몇 번이 되어도 지키겠다는 뜻을 힘주어 말한 거예요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"},"mis":"K6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#4','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','시조는 모두 몇 줄로 짓나요?',ARRAY['K6-2-u1-X17']::text[],false,'{"seq":4,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조는 모두 몇 줄로 짓나요?","options":[{"t":"세 줄","correct":true},{"t":"두 줄","mis":"K6-2-u1-X17"},{"t":"네 줄","mis":"K6-2-u1-X17"},{"t":"정해진 줄 수가 없어요","mis":"K6-2-u1-X17"}],"explanation":["시조는 고려 말부터 이어 온 우리 고유의 시예요.","정해진 글자 수에 맞추어 세 줄로 지어요.","줄 수가 정해져 있어 하고 싶은 말을 고르고 골라 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#5','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'mc','auto','「백 번 고쳐 백 번을 다시 매도」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":5,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「백 번 고쳐 백 번을 다시 매도」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몇 번이 되어도 나루를 계속 지키겠다는 뜻","correct":true},{"t":"나루를 정확히 백 번 고쳤다는 기록","mis":"K6-2-u1-X03"},{"t":"나루가 자주 고장 나서 불편하다는 불평","mis":"K6-2-u1-X02"},{"t":"나루를 헐고 새로 짓자는 부탁","mis":"K6-2-u1-X02"}],"explanation":["「백 번」을 두 번 되풀이해 힘을 주었어요.","실제 횟수가 아니라 「아무리 여러 번이라도」라는 뜻이에요.","나루를 지키려는 마음을 힘주어 드러냈어요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#6','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'mc','auto','「나루를 지켜」가 「변할 줄이 있으랴」처럼 묻는 말로 끝맺은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X06','K6-2-u1-X17']::text[],false,'{"seq":6,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「나루를 지켜」가 「변할 줄이 있으랴」처럼 묻는 말로 끝맺은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 바라는 물음이 아니라 「변하지 않는다」는 뜻을 힘주어 말하려고","correct":true},{"t":"읽는 사람에게 답을 알려 달라고 하려고","mis":"K6-2-u1-X03"},{"t":"작가도 자기 마음을 몰라서","mis":"K6-2-u1-X06"},{"t":"시조는 언제나 물음으로 끝나야 해서","mis":"K6-2-u1-X17"}],"explanation":["「변할 줄이 있으랴」는 「변할 리가 없다」는 뜻이에요.","묻는 꼴로 끝맺어 오히려 뜻을 세게 말해요.","힘주어 끝맺은 말은 작가의 뜻을 찾는 좋은 실마리예요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#7','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'match','auto','시조의 표현과 그 표현에 담긴 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C2","difficulty":2,"kind":"match","stem":"시조의 표현과 그 표현에 담긴 뜻을 알맞게 이으세요.","pairs":[{"l":"돌 하나 또 한 돌을","r":"작은 것이 쌓여 큰 것이 된다"},{"l":"건너오면 이웃이라","r":"길이 이어지면 사람이 이어진다"},{"l":"변할 줄이 있으랴","r":"내 마음은 바뀌지 않는다"}],"mis":"K6-2-u1-X03","explanation":["되풀이하거나 힘준 표현에는 뜻이 담겨 있어요.","「또 한」의 되풀이는 쌓임, 「이웃」은 사람의 이어짐이에요.","「있으랴」는 묻는 꼴로 마음이 바뀌지 않음을 힘주어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#8','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C3',2,'ox','auto','「한도경은 다리 놓는 사람이었으니까 이 시조는 다리를 놓자는 뜻이다. 끝.」 이렇게 읽으면 충분해요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":2,"kind":"ox","stem":"「한도경은 다리 놓는 사람이었으니까 이 시조는 다리를 놓자는 뜻이다. 끝.」 이렇게 읽으면 충분해요.","answer":"X","reason_options":[{"t":"작가의 삶은 실마리일 뿐, 다시 작품으로 돌아와 근거를 찾아야 하기 때문에","correct":true},{"t":"작가의 직업이 곧 작품의 뜻이기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["작가의 삶을 알면 작품이 다시 보여요.","그렇다고 삶만 보고 뜻을 하나로 정하면 안 돼요.","「왜 ‘이웃’이라고 했을까?」처럼 작품으로 돌아와야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#9','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C1',2,'mc','auto','두 시조를 읽은 뒤 이 시간에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X07','K6-2-u1-X06','K6-2-u1-X05']::text[],false,'{"seq":9,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"두 시조를 읽은 뒤 이 시간에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"각 작가가 무엇을 전하려 했는지 근거를 들어 짐작하기","correct":true},{"t":"다리를 놓는 것과 나루를 지키는 것 가운데 누가 옳은지 겨루기","mis":"K6-2-u1-X07"},{"t":"더 좋은 시조 하나만 골라 외우기","mis":"K6-2-u1-X06"},{"t":"작가의 이름만 외우기","mis":"K6-2-u1-X05"}],"explanation":["두 시조는 같은 일을 두고 서로 다른 뜻을 담았어요.","누가 옳은지 겨루면 작품이 아니라 내 결론을 말하게 돼요.","각자 무엇을 전하려 했는지 근거로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#10','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C3',3,'error','auto','작가 한도경이 여러 마을을 다니며 다리 놓는 일을 했다는 것을 알고 「같이 건너세」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06']::text[],false,'{"seq":10,"concept":"K6-2-u1-C3","difficulty":3,"kind":"error","stem":"작가 한도경이 여러 마을을 다니며 다리 놓는 일을 했다는 것을 알고 「같이 건너세」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예강 — 「작가가 다리 놓는 일을 했대. 그러니 이 시조는 더 읽지 않아도 돼.」","correct":true,"mis_target":"K6-2-u1-X04"},{"t":"슬찬 — 「작가의 삶을 알고 나니 ‘또 한 사람’이 다시 보여.」","mis":"K6-2-u1-X06"},{"t":"온새 — 「‘이웃’이라는 말을 보면 다리보다 사람 이야기를 하고 싶었던 것 같아.」","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 읽기를 시작하게 하는 실마리예요.","슬찬과 온새는 삶을 알고 다시 작품의 말로 돌아왔어요.","예강은 삶만 보고 작품 읽기를 멈추었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#1','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',2,'sa','auto','작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 무엇이라고 하나요? 「작가의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":2,"kind":"sa","stem":"작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 무엇이라고 하나요? 「작가의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["의도"],"explanation":["글에는 쓴 사람이 있어요.","쓴 까닭과 바란 것을 작품에 담아요.","이것을 작가의 의도라고 해요."],"mis":"K6-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#2','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',2,'mc','auto','시 「창문」에서 두 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"시 「창문」에서 두 번 나온 말은 어느 것인가요?","options":[{"t":"같은","correct":true},{"t":"창문 앞에","mis":"K6-2-u1-X03"},{"t":"밤이 되자","mis":"K6-2-u1-X03"},{"t":"바뀐다","mis":"K6-2-u1-X03"}],"explanation":["「같은 유리 / 같은 자리」에 「같은」이 두 번 나와요.","달라진 것이 없다는 것을 힘주어 말해요.","그런데도 보이는 것이 바뀐다는 데에 눈길이 가요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#3','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C3',3,'mc','auto','윤채겸은 나루에서 배를 젓던 사공의 딸이에요. 이것을 알고 「노 젓던 저 물길이 어디로 가겠는가」를 다시 읽었을 때 가장 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X04']::text[],false,'{"seq":3,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"윤채겸은 나루에서 배를 젓던 사공의 딸이에요. 이것을 알고 「노 젓던 저 물길이 어디로 가겠는가」를 다시 읽었을 때 가장 알맞은 짐작은 어느 것인가요?","options":[{"t":"나루에서 이어져 온 삶과 일이 쉽게 사라지지 않기를 바라는 마음","correct":true},{"t":"물길이 어디로 흐르는지 몰라 길을 묻는 마음","mis":"K6-2-u1-X08"},{"t":"사공의 딸이니 무조건 다리에 반대한다는 뜻","mis":"K6-2-u1-X04"},{"t":"노 젓는 방법을 알려 주려는 마음","mis":"K6-2-u1-X08"}],"explanation":["작가는 나루에서 마을 사람들의 사정을 들으며 자랐어요.","「노 젓던 저 물길」은 그 삶을 가리켜요.","「어디로 가겠는가」는 사라지지 않는다는 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#4','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',3,'ox','auto','같은 시를 읽고 친구와 생각이 다르면 둘 가운데 하나는 틀린 읽기예요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":4,"concept":"K6-2-u1-C1","difficulty":3,"kind":"ox","stem":"같은 시를 읽고 친구와 생각이 다르면 둘 가운데 하나는 틀린 읽기예요.","answer":"X","reason_options":[{"t":"둘 다 작품에서 근거를 댔다면 둘 다 좋은 읽기이기 때문에","correct":true},{"t":"작품의 뜻은 하나로 정해져 있기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["예강은 「밤마다」, 「오래」를 근거로 외롭게 읽었어요.","슬찬은 「나를 보여 준다」를 근거로 반갑게 읽었어요.","근거가 있으면 서로 달라도 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#5','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',3,'mc','auto','「창문」에서 「밤이 되자 / 나를 보여 준다」가 주는 느낌으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08']::text[],false,'{"seq":5,"concept":"K6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「창문」에서 「밤이 되자 / 나를 보여 준다」가 주는 느낌으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻밖의 것을 알아차린 느낌","correct":true},{"t":"한 번이 아니라 되풀이해 온 느낌","mis":"K6-2-u1-X03"},{"t":"창문이 깨질까 봐 걱정되는 느낌","mis":"K6-2-u1-X08"},{"t":"밖이 잘 보여 시원한 느낌","mis":"K6-2-u1-X08"}],"explanation":["낮에는 밖을 보여 주던 창문이에요.","밤이 되자 유리에 내가 비쳐 보여요.","같은 창문에서 뜻밖의 것을 알아차린 느낌이 들어요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#6','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',3,'match','auto','「창문」을 읽은 두 친구의 생각과 그 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C1","difficulty":3,"kind":"match","stem":"「창문」을 읽은 두 친구의 생각과 그 근거를 알맞게 이으세요.","pairs":[{"l":"예강 — 혼자라서 외로운 시","r":"「밤마다」, 「오래 서 있는다」"},{"l":"슬찬 — 드디어 나를 보게 된 반가운 시","r":"「나를 보여 준다」"},{"l":"두 읽기 모두","r":"시에서 근거를 들어 좋은 읽기"}],"mis":"K6-2-u1-X06","explanation":["같은 시를 읽고도 생각이 갈릴 수 있어요.","두 친구 모두 시에 적힌 말을 근거로 댔어요.","근거가 있으면 둘 다 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#7','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',3,'error','auto','「나루를 지켜」의 「백 번」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X06']::text[],false,'{"seq":7,"concept":"K6-2-u1-C2","difficulty":3,"kind":"error","stem":"「나루를 지켜」의 「백 번」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「백 번은 나루를 실제로 고친 횟수를 적은 기록이야.」","correct":true,"mis_target":"K6-2-u1-X03"},{"t":"준희 — 「몇 번이 되어도 지키겠다는 뜻이야.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「같은 말을 되풀이해서 힘을 준 거야.」","mis":"K6-2-u1-X06"}],"explanation":["「백 번」은 두 번 되풀이되어 힘을 주는 말이에요.","실제 횟수가 아니라 「아무리 여러 번이라도」라는 뜻이에요.","서아는 글자 그대로만 받아들였어요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#8','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C3',4,'mc','auto','작가의 삶과 작품 읽기의 관계로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":4,"kind":"mc","stem":"작가의 삶과 작품 읽기의 관계로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작가의 삶을 실마리로 얻고, 다시 작품으로 돌아와 근거를 찾는다","correct":true},{"t":"작가의 삶을 알면 작품은 다시 읽지 않아도 된다","mis":"K6-2-u1-X04"},{"t":"작가의 삶은 작품과 상관없으니 알아보지 않는다","mis":"K6-2-u1-X05"},{"t":"작가의 삶과 다르게 읽으면 틀린 읽기이다","mis":"K6-2-u1-X06"}],"explanation":["작가를 아는 것과 작품을 읽는 것은 둘 다 필요해요.","삶은 실마리, 근거는 작품 안에서 찾아요.","둘 가운데 하나만 쓰면 감상이 얕아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#9','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',4,'mc','auto','두 시조에 담긴 작가의 의도를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C1","difficulty":4,"kind":"mc","stem":"두 시조에 담긴 작가의 의도를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"「같이 건너세」 — 마을과 마을이 이어지기를 바람 / 「나루를 지켜」 — 이어져 온 삶을 쉽게 지우지 말자","correct":true},{"t":"「같이 건너세」 — 이어져 온 삶을 쉽게 지우지 말자 / 「나루를 지켜」 — 마을과 마을이 이어지기를 바람","mis":"K6-2-u1-X04"},{"t":"「같이 건너세」 — 나루를 새로 고치자 / 「나루를 지켜」 — 다리를 빨리 놓자","mis":"K6-2-u1-X08"},{"t":"두 시조 모두 — 강을 건너는 일은 위험하다","mis":"K6-2-u1-X02"}],"explanation":["「같이 건너세」의 근거는 「또 한」의 되풀이, 「이웃」, 「한 마을로 살리라」예요.","「나루를 지켜」의 근거는 「백 번」의 되풀이, 「변할 줄이 있으랴」예요.","근거를 들 수 있으면 좋은 짐작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#10','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',4,'essay','teacher','시조 「같이 건너세」와 「나루를 지켜」 가운데 하나를 골라, 작가의 의도를 짐작하고 시조에서 근거가 되는 표현을 두 가지 들어 쓰세요. 작가의 삶이 짐작에 어떻게 도움이 되었는지도 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"시조 「같이 건너세」와 「나루를 지켜」 가운데 하나를 골라, 작가의 의도를 짐작하고 시조에서 근거가 되는 표현을 두 가지 들어 쓰세요. 작가의 삶이 짐작에 어떻게 도움이 되었는지도 한 문장으로 쓰세요.","answer_guide":{"answer":"예(「같이 건너세」): 다리를 놓아 마을과 마을, 사람과 사람이 이어지기를 바라는 마음을 전하려 한 것 같다. 「돌 하나 또 한 돌을」, 「또 한 사람」처럼 「또 한」을 되풀이해 작은 것이 쌓이는 모습을 보여 주었고, 「건너오면 이웃이라」, 「한 마을로 살리라」라고 힘주어 끝맺었기 때문이다. 작가가 다리 놓는 일을 하며 물에 막힌 아이들을 보았다는 것을 알고 나니 「이웃」이라는 말이 사람 이야기로 다시 보였다.","scoring_points":["작가의 의도를 한 문장으로 짐작했는가","시조에서 근거가 되는 표현을 두 가지 들었는가","작가의 삶을 실마리로 쓰고 다시 작품의 말로 돌아왔는가"]},"explanation":["짐작 + 근거를 한 묶음으로 써요.","되풀이한 말과 힘준 끝맺음이 좋은 근거예요.","작가의 삶은 실마리로만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#1','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','「돌아오는 길」에서 여러 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":1,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「돌아오는 길」에서 여러 번 나온 말은 어느 것인가요?","options":[{"t":"걷는다","correct":true},{"t":"바다","mis":"K6-2-u1-X02"},{"t":"노래","mis":"K6-2-u1-X02"},{"t":"창문","mis":"K6-2-u1-X02"}],"explanation":["2연 「담을 따라 걷는다」, 4연 「걷는 것이 아니다」, 「길을 내려고 걷는다」예요.","「걷는다」가 되풀이되어 시의 뼈대가 돼요.","바다·노래·창문은 이 시에 없는 말이에요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#2','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'mc','auto','「돌아오는 길」 2연의 「담」과 「닫힌 문」은 무엇을 나타낸다고 볼 수 있나요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":2,"concept":"K6-2-u1-C4","difficulty":1,"kind":"mc","stem":"「돌아오는 길」 2연의 「담」과 「닫힌 문」은 무엇을 나타낸다고 볼 수 있나요?","options":[{"t":"나아가려는 사람을 막고 있는 것","correct":true},{"t":"사람이 사는 집의 생김새","mis":"K6-2-u1-X08"},{"t":"누군가 잃어버린 열쇠가 있는 곳","mis":"K6-2-u1-X08"},{"t":"비를 피할 수 있는 곳","mis":"K6-2-u1-X08"}],"explanation":["「담은 길고 문은 닫혀 있다」 — 둘이 나란히 놓였어요.","걷는 사람 앞이 막혀 있는 처지예요.","시어는 겉뜻보다 넓은 뜻을 품어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#3','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'ox','auto','시는 여러 번 읽을수록 처음에는 안 보이던 말이 보이기도 해요.',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":3,"concept":"K6-2-u1-C4","difficulty":1,"kind":"ox","stem":"시는 여러 번 읽을수록 처음에는 안 보이던 말이 보이기도 해요.","answer":"O","reason_options":[{"t":"되풀이해 읽으면 낱말과 연 사이의 관계가 새로 보이기 때문에","correct":true},{"t":"시는 한 번 읽으면 뜻이 모두 드러나기 때문에","mis":"K6-2-u1-X08"}],"mis":"K6-2-u1-X08","explanation":["한 연씩 소리 내어 읽어 보아요.","두 번째 읽을 때 되풀이된 말이 들려요.","여러 번 읽는 것이 감상의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#4','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'sa','auto','「돌아오는 길」은 모두 몇 연인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u1-C4","difficulty":1,"kind":"sa","stem":"「돌아오는 길」은 모두 몇 연인가요? 숫자로 쓰세요.","answer":["4","네"],"explanation":["연은 시에서 한 덩어리로 묶인 줄들이에요.","1연부터 4연까지 있어요.","연마다 걷는 사람의 처지가 조금씩 달라져요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"},"mis":"K6-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#5','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'match','auto','시구와 그렇게 읽은 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u1-C4","difficulty":2,"kind":"match","stem":"시구와 그렇게 읽은 근거를 알맞게 이으세요.","pairs":[{"l":"만져지는 것이 없다","r":"앞 줄에서 잃어버린 것을 세어 보았다"},{"l":"하늘만 넓다","r":"담은 길고 문은 닫혀 위밖에 열린 곳이 없다"},{"l":"남은 발자국이 길이 된다","r":"뒤를 돌아본 자리에 남은 것이 있었다"}],"mis":"K6-2-u1-X02","explanation":["시구의 뜻은 그 앞뒤 줄에서 근거를 찾아요.","1연은 잃은 것, 2연은 막힘, 3연은 남은 것이에요.","근거를 들면 짐작이 단단해져요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#6','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C3',2,'mc','auto','문해원은 어릴 때 집을 자주 옮겨 한 학교에 오래 다니지 못했고, 옮길 때마다 낯선 골목을 혼자 걸었으며 짐을 쌀 때마다 무언가를 두고 왔어요. 어른이 되어서는 오래 살 곳을 정하고 같은 골목을 날마다 걸으며 걷는 일에 대한 시를 썼어요. 이것을 알고 다시 읽을 때 새로 보이는 시구와 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":6,"concept":"K6-2-u1-C3","difficulty":2,"kind":"mc","stem":"문해원은 어릴 때 집을 자주 옮겨 한 학교에 오래 다니지 못했고, 옮길 때마다 낯선 골목을 혼자 걸었으며 짐을 쌀 때마다 무언가를 두고 왔어요. 어른이 되어서는 오래 살 곳을 정하고 같은 골목을 날마다 걸으며 걷는 일에 대한 시를 썼어요. 이것을 알고 다시 읽을 때 새로 보이는 시구와 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잃어버린 것」 — 이사할 때마다 두고 온 것들이 떠올라서","correct":true},{"t":"「하늘」 — 작가가 하늘 사진을 즐겨 찍어서","mis":"K6-2-u1-X02"},{"t":"「담」 — 작가의 집에는 담이 없어서","mis":"K6-2-u1-X02"},{"t":"「발자국」 — 작가가 달리기 선수여서","mis":"K6-2-u1-X02"}],"explanation":["작가는 짐을 쌀 때마다 무언가를 두고 왔어요.","그래서 「잃어버린 것을 세어 본다」가 그냥 나온 말이 아니겠구나 싶어요.","다른 보기는 작가의 삶에 나오지 않는 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#7','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C3',2,'mc','auto','「문해원이 이사를 자주 다녔대. 그러니까 이 시는 이사에 대한 시야. 다 풀렸어.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":7,"concept":"K6-2-u1-C3","difficulty":2,"kind":"mc","stem":"「문해원이 이사를 자주 다녔대. 그러니까 이 시는 이사에 대한 시야. 다 풀렸어.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"작가의 삶은 실마리일 뿐이야. 시의 어느 줄이 그렇게 읽히는지 근거를 함께 들어야 해.","correct":true},{"t":"맞아. 작가의 삶을 알았으니 이제 시는 더 읽지 않아도 돼.","mis":"K6-2-u1-X04"},{"t":"작가의 삶은 시와 상관없으니 아예 알아보지 않는 게 좋아.","mis":"K6-2-u1-X05"},{"t":"이사가 아니라 여행에 대한 시라고 정해 두자.","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 시를 다시 보게 하는 실마리예요.","실마리를 얻은 뒤에는 내가 읽고 느낀 것과 견주어요.","근거는 언제나 시 안에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#8','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'ox','auto','「나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다」에서 「나」는 잃은 것을 찾으려고 걸어요.',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C4","difficulty":2,"kind":"ox","stem":"「나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다」에서 「나」는 잃은 것을 찾으려고 걸어요.","answer":"X","reason_options":[{"t":"「찾으려고 걷는 것이 아니다」라고 하고 길을 내려고 걷는다고 했기 때문에","correct":true},{"t":"1연에서 잃어버린 것을 세어 보았기 때문에","mis":"K6-2-u1-X02"}],"mis":"K6-2-u1-X02","explanation":["4연은 「~이 아니다」로 앞의 생각을 뒤집어요.","걷는 까닭은 「길을 내려고」예요.","1연만 보고 판단하면 시의 흐름을 놓쳐요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#9','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'mc','auto','「남은 발자국이 길이 된다」를 읽은 것으로 시에서 근거를 댈 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「남은 발자국이 길이 된다」를 읽은 것으로 시에서 근거를 댈 수 있는 것은 어느 것인가요?","options":[{"t":"걸어온 자국이 다음에 걸을 길이 된다","correct":true},{"t":"발자국이 지저분하게 남아 있다는 불평","mis":"K6-2-u1-X08"},{"t":"길을 잃어서 되돌아가야 한다는 걱정","mis":"K6-2-u1-X02"},{"t":"작가가 발자국 화석을 좋아했다는 뜻","mis":"K6-2-u1-X02"}],"explanation":["3연에서 걸어온 뒤를 돌아보니 발자국이 남아 있어요.","그 발자국이 길이 된다고 했어요.","잃기만 한 것이 아니라 남은 것도 있다는 뜻으로 읽을 수 있어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#10','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C1',3,'mc','auto','시를 읽고 짐작한 작가의 의도를 말하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X06','K6-2-u1-X04']::text[],false,'{"seq":10,"concept":"K6-2-u1-C1","difficulty":3,"kind":"mc","stem":"시를 읽고 짐작한 작가의 의도를 말하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"짐작한 의도와 그 근거가 된 시구를 한 묶음으로 말한다","correct":true},{"t":"근거 없이 느낌만 짧게 말한다","mis":"K6-2-u1-X06"},{"t":"작가의 삶만 말하고 시의 말은 들지 않는다","mis":"K6-2-u1-X04"},{"t":"친구가 말한 짐작을 그대로 따라 한다","mis":"K6-2-u1-X06"}],"explanation":["짐작 + 근거를 한 묶음으로 말하면 다른 사람도 내 짐작을 따라올 수 있어요.","근거는 되풀이된 말이나 힘준 시구에서 찾아요.","작가의 삶은 실마리로 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#1','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',2,'sa','auto','시에 쓰인 말을 무엇이라고 하나요? 두 글자로 쓰세요. (예: 「길」, 「담」, 「발자국」)','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C4","difficulty":2,"kind":"sa","stem":"시에 쓰인 말을 무엇이라고 하나요? 두 글자로 쓰세요. (예: 「길」, 「담」, 「발자국」)","answer":["시어"],"explanation":["시에 쓰인 말을 시어라고 해요.","시어는 여러 뜻을 품는 일이 많아요.","「길」은 걷는 길도, 살아가는 날들도 될 수 있어요."],"mis":"K6-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#2','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C2',2,'mc','auto','「돌아오는 길」 4연에서 「걷는다」를 되풀이해 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X17','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「돌아오는 길」 4연에서 「걷는다」를 되풀이해 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걷는 일에 담긴 다짐을 힘주어 드러내려고","correct":true},{"t":"시의 글자 수를 맞추려고","mis":"K6-2-u1-X17"},{"t":"걷기 운동을 하자고 권하려고","mis":"K6-2-u1-X08"},{"t":"작가가 걷는 것을 싫어해서","mis":"K6-2-u1-X02"}],"explanation":["마지막 연에서 「걷는 것이 아니다」, 「걷는다」가 이어져요.","같은 말을 되풀이해 걷는 까닭을 또렷이 해요.","되풀이는 힘을 주는 표현이에요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#3','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C1',3,'error','auto','「길을 내려고 걷는다」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":3,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「길을 내려고 걷는다」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지호 — 「둘이 다르게 읽었으니 둘 다 틀렸어. 작가에게 물어봐야 알아.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"온새 — 「뒤에 오는 사람이 이 발자국을 밟을 테니 남은 사람들을 위한 말 같아.」","mis":"K6-2-u1-X06"},{"t":"예강 — 「잃은 걸 붙잡지 말고 앞으로 가자는 자기 다짐으로 읽었어.」","mis":"K6-2-u1-X06"}],"explanation":["온새와 예강은 서로 다르게 읽었어요.","두 사람 모두 시에서 근거를 들었어요.","시를 읽는 일에는 맞고 틀림이 아니라 근거가 있고 없음이 있어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#4','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C3',3,'ox','auto','작가의 의도를 짐작한다는 것은 작가가 생각한 대로만 읽어야 한다는 뜻이에요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":4,"concept":"K6-2-u1-C3","difficulty":3,"kind":"ox","stem":"작가의 의도를 짐작한다는 것은 작가가 생각한 대로만 읽어야 한다는 뜻이에요.","answer":"X","reason_options":[{"t":"작가의 의도는 실마리이고, 내가 읽고 느낀 것과 견주어 근거가 있으면 좋은 읽기이기 때문에","correct":true},{"t":"작가와 다르게 읽으면 틀린 것이기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["짐작하는 것과 그대로 따르는 것은 달라요.","작가의 삶은 다시 보게 하는 실마리예요.","둘이 달라도 근거만 있으면 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#5','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',3,'mc','auto','「닫힌 문 위로 하늘만 넓다」를 그렇게 읽은 근거로 알맞은 것은 어느 것인가요? (하늘만 넓다 = 열린 곳이 위뿐이다)',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":5,"concept":"K6-2-u1-C4","difficulty":3,"kind":"mc","stem":"「닫힌 문 위로 하늘만 넓다」를 그렇게 읽은 근거로 알맞은 것은 어느 것인가요? (하늘만 넓다 = 열린 곳이 위뿐이다)","options":[{"t":"담은 길고 문은 닫혀 있어 열린 곳이 위밖에 없다","correct":true},{"t":"앞 연에서 잃어버린 것을 세어 보았다","mis":"K6-2-u1-X02"},{"t":"뒤를 돌아본 자리에 남은 것이 있었다","mis":"K6-2-u1-X02"},{"t":"비가 그쳐 날씨가 맑았다","mis":"K6-2-u1-X02"}],"explanation":["같은 연의 앞 줄이 근거예요.","옆은 담, 앞은 닫힌 문이에요.","그래서 「하늘만」 넓게 보여요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#6','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C2',3,'mc','auto','「돌아오는 길」 1연과 3연을 견주어 읽을 때 드러나는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":6,"concept":"K6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「돌아오는 길」 1연과 3연을 견주어 읽을 때 드러나는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"잃은 것만 있는 줄 알았는데 남은 것도 있다는 마음의 바뀜","correct":true},{"t":"1연과 3연은 서로 상관없는 이야기","mis":"K6-2-u1-X03"},{"t":"잃은 것을 모두 되찾았다는 기쁨","mis":"K6-2-u1-X02"},{"t":"발자국 때문에 길을 잃었다는 걱정","mis":"K6-2-u1-X02"}],"explanation":["1연 — 주머니에 만져지는 것이 없어요.","3연 — 뒤를 돌아보니 발자국이 남아 있어요.","두 연을 나란히 놓으면 마음이 바뀌는 흐름이 보여요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#7','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',3,'match','auto','「돌아오는 길」의 시어와 그 시어가 나타낸다고 볼 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C4","difficulty":3,"kind":"match","stem":"「돌아오는 길」의 시어와 그 시어가 나타낸다고 볼 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"담 · 닫힌 문","r":"나아가려는 사람을 막는 것"},{"l":"하늘","r":"위로 열려 있는 곳"},{"l":"발자국","r":"걸어온 날들이 남긴 자국"}],"mis":"K6-2-u1-X08","explanation":["시어는 겉뜻보다 넓은 뜻을 품어요.","시어가 나온 연에서 걷는 사람의 처지를 보아요.","처지와 이어 읽으면 시어의 뜻이 드러나요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#8','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C3',4,'mc','auto','문해원의 삶(어릴 때 이사를 자주 함 · 어른이 되어 같은 골목을 날마다 걸음)과 시를 함께 읽고 짐작한 의도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":4,"kind":"mc","stem":"문해원의 삶(어릴 때 이사를 자주 함 · 어른이 되어 같은 골목을 날마다 걸음)과 시를 함께 읽고 짐작한 의도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잃은 것이 있어도 걸어온 자국은 남고, 그 자국이 다음 길이 된다는 것","correct":true},{"t":"이사는 나쁜 일이니 하지 말자는 것","mis":"K6-2-u1-X04"},{"t":"골목길을 깨끗하게 쓰자는 것","mis":"K6-2-u1-X08"},{"t":"잃어버린 물건을 꼭 되찾자는 것","mis":"K6-2-u1-X02"}],"explanation":["작가의 삶은 「잃어버린 것」, 「걷는다」를 다시 보게 해요.","시의 근거는 「남은 발자국이 길이 된다」, 「길을 내려고 걷는다」예요.","삶과 시의 근거가 함께 가리키는 짐작이 가장 단단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#9','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',4,'blank','auto','짐작과 근거를 한 묶음으로 쓴 문장을 완성하세요. 「잃은 것이 있어도 걸어온 자국은 남는다는 것을 전하려 한 것 같다. 왜냐하면 (  ) 때문이다.」 빈칸에 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06','K6-2-u1-X17']::text[],false,'{"seq":9,"concept":"K6-2-u1-C4","difficulty":4,"kind":"blank","stem":"짐작과 근거를 한 묶음으로 쓴 문장을 완성하세요. 「잃은 것이 있어도 걸어온 자국은 남는다는 것을 전하려 한 것 같다. 왜냐하면 (  ) 때문이다.」 빈칸에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「남은 발자국이 길이 된다」라는 시구가 있기","correct":true},{"t":"작가가 유명한 사람이기","mis":"K6-2-u1-X04"},{"t":"내가 이 시를 좋아하기","mis":"K6-2-u1-X06"},{"t":"시가 네 연으로 되어 있기","mis":"K6-2-u1-X17"}],"explanation":["「왜냐하면」 뒤에는 시에서 찾은 근거가 와야 해요.","「남은 발자국이 길이 된다」는 짐작을 바로 받쳐 줘요.","좋아하는 마음이나 연의 수는 근거가 되지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#10','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',4,'essay','teacher','「돌아오는 길」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 근거가 되는 시구를 두 가지 드세요. 그리고 작가의 삶을 알고 나서 다르게 보인 시어 하나를 골라 어떻게 다르게 보였는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":4,"kind":"essay","stem":"「돌아오는 길」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 근거가 되는 시구를 두 가지 드세요. 그리고 작가의 삶을 알고 나서 다르게 보인 시어 하나를 골라 어떻게 다르게 보였는지 쓰세요.","answer_guide":{"answer":"예: 잃은 것이 있어도 걸어온 자국은 남으며 그 자국이 다음 길이 된다는 것을 전하려 한 것 같다. 근거는 「남은 발자국이 길이 된다」와 마지막 연의 「길을 내려고 걷는다」이다. 작가가 어릴 때 이사를 자주 다니며 짐을 쌀 때마다 무언가를 두고 왔다는 것을 알고 나니, 1연의 「잃어버린 것」이 그냥 물건이 아니라 두고 온 학교와 친구처럼 보였다.","scoring_points":["의도를 한 문장으로 짐작했는가","근거 시구를 두 가지 들었는가","작가의 삶과 이어 다르게 보인 시어를 설명했는가"]},"explanation":["의도 + 근거 두 가지를 써요.","작가의 삶은 시어를 다시 보게 하는 실마리예요.","마지막에는 다시 시의 말로 돌아와요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#1','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',1,'match','auto','이야기 구조와 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C5","difficulty":1,"kind":"match","stem":"이야기 구조와 설명을 알맞게 이으세요.","pairs":[{"l":"발단","r":"이야기가 시작되는 부분"},{"l":"전개","r":"사건이 본격적으로 생기는 부분"},{"l":"절정","r":"긴장감이 높아지거나 갈등이 두드러지는 부분"},{"l":"결말","r":"이야기가 마무리되는 부분"}],"mis":"K6-2-u1-X09","explanation":["이야기는 시작되고 · 커지고 · 부딪히고 · 마무리되는 차례를 지녀요.","이것을 이야기 구조라고 해요.","발단 → 전개 → 절정 → 결말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#2','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',1,'mc','auto','이야기에서 긴장감이 높아지거나 갈등이 두드러지는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":2,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기에서 긴장감이 높아지거나 갈등이 두드러지는 부분은 어느 것인가요?","options":[{"t":"절정","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","긴장감이 가장 높은 곳이 절정이에요.","결말은 이야기가 마무리되는 부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#3','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',1,'mc','auto','「종을 잃은 마을」 둘째 부분에서 일어난 중요한 사건은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":3,"concept":"K6-2-u1-C6","difficulty":1,"kind":"mc","stem":"「종을 잃은 마을」 둘째 부분에서 일어난 중요한 사건은 어느 것인가요?","options":[{"t":"겨울에 종에 금이 가 마을이 어긋나기 시작했다","correct":true},{"t":"덕곤 할아버지가 종을 팔았다","mis":"K6-2-u1-X02"},{"t":"늘봄이 마을을 떠났다","mis":"K6-2-u1-X02"},{"t":"마을에 시계를 모두 나누어 주었다","mis":"K6-2-u1-X02"}],"explanation":["둘째 부분은 「그해 겨울 어느 새벽, 종에 금이 갔다」로 시작해요.","어른들이 미루는 사이 마을이 어긋났어요.","다른 보기는 이야기에 없는 일이에요."],"asset":{"type":"passage","lines":["그해 겨울 어느 새벽, 종에 금이 갔다.","새 종을 만들려면 큰돈이 든다고 했다.","어른들은 봄에, 다시 여름에 이야기하자며 미루었다.","그사이 마을은 어긋났다. 반만 모이는 날이 잦았고 서로 탓했다."],"title":"「종을 잃은 마을」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#4','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',1,'ox','auto','줄거리를 간추릴 때는 이야기에 나온 모든 문장을 차례대로 옮겨 적어요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추릴 때는 이야기에 나온 모든 문장을 차례대로 옮겨 적어요.","answer":"X","reason_options":[{"t":"중요한 사건만 골라 흐름이 이어지게 짧게 적기 때문에","correct":true},{"t":"한 문장이라도 빠지면 줄거리가 틀리기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["긴 이야기를 다 외울 수는 없어요.","중요한 사건을 골라 흐름이 이어지게 적어요.","덜 중요한 것은 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#5','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',2,'mc','auto','「종을 잃은 마을」에서 긴장감이 가장 높은 곳은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":5,"concept":"K6-2-u1-C5","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」에서 긴장감이 가장 높은 곳은 어느 것인가요?","options":[{"t":"늘봄이 나무판을 두드리다 나무람을 듣고도 열이레 동안 올라간 곳","correct":true},{"t":"덕곤 할아버지가 새벽마다 종을 울리던 곳","mis":"K6-2-u1-X09"},{"t":"이듬해 봄에 새 종이 걸린 곳","mis":"K6-2-u1-X09"},{"t":"늘봄이 이불 속에서 하나, 둘, 셋을 세던 곳","mis":"K6-2-u1-X09"}],"explanation":["인물이 가장 크게 부딪히고 그만둘까 망설이는 곳을 찾아요.","늘봄은 나무람을 듣고 얼굴이 뜨거워졌지만 다시 올라갔어요.","그래서 셋째 부분이 절정이에요."],"asset":{"type":"passage","lines":["가을 끝 무렵 덕곤 할아버지가 앓아누웠다.","그날 새벽 늘봄은 언덕에 올라 나무판을 두드렸다. 딱, 딱, 딱.","「그게 무슨 종소리냐.」 아랫집 어른이 나와 나무랐다.","늘봄은 얼굴이 뜨거워져 내려왔지만 이튿날 또 올라갔다.","손바닥이 부르터도 열이레 동안 새벽마다 두드렸다."],"title":"「종을 잃은 마을」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#6','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',2,'mc','auto','「종을 잃은 마을」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":6,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"종이 깨져 마을이 어긋나자 늘봄이 나무판으로 새벽을 알렸고, 사람들이 다시 모여 새 종을 걸었다","correct":true},{"t":"겨울이었다. 종이 있었다. 아이가 있었다. 눈이 왔다.","mis":"K6-2-u1-X10"},{"t":"산 밑 마을 언덕에 오래된 종이 하나 있었다. 종지기 덕곤 할아버지는 새벽마다…(처음부터 끝까지 그대로)","mis":"K6-2-u1-X11"},{"t":"정말 감동적인 이야기였다.","mis":"K6-2-u1-X11"}],"explanation":["잘 간추린 줄거리는 사건끼리 이어져 있어요.","무슨 일이 왜 일어났는지 알 수 있어요.","늘어놓기·통째 옮기기·느낌만 쓰기는 간추린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#7','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',2,'sa','auto','이야기 구조에서 이야기가 마무리되는 부분을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C5","difficulty":2,"kind":"sa","stem":"이야기 구조에서 이야기가 마무리되는 부분을 두 글자로 쓰세요.","answer":["결말"],"explanation":["발단 — 시작이에요.","전개·절정을 지나요.","이야기가 마무리되는 부분이 결말이에요."],"mis":"K6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#8','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',2,'mc','auto','간추린 줄거리가 사건을 늘어놓기만 하면 생기는 문제는 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X16']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"간추린 줄거리가 사건을 늘어놓기만 하면 생기는 문제는 어느 것인가요?","options":[{"t":"무슨 일이 왜 일어났는지 알 수 없다","correct":true},{"t":"글이 너무 짧아진다","mis":"K6-2-u1-X10"},{"t":"인물의 이름이 빠진다","mis":"K6-2-u1-X11"},{"t":"시간을 나타내는 말이 없어진다","mis":"K6-2-u1-X16"}],"explanation":["「아이가 나갔다. 비가 왔다. 돌을 옮겼다.」처럼 늘어놓으면","사건 사이의 까닭이 보이지 않아요.","사건을 많이 적는 것보다 이어지게 적는 것이 잘 간추린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#9','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',2,'ox','auto','이야기를 네 부분으로 나눌 때 경계는 언제나 하나로 딱 정해져요.',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":9,"concept":"K6-2-u1-C5","difficulty":2,"kind":"ox","stem":"이야기를 네 부분으로 나눌 때 경계는 언제나 하나로 딱 정해져요.","answer":"X","reason_options":[{"t":"까닭을 말할 수 있으면 전개를 어디부터로 볼지 사람마다 다를 수 있기 때문에","correct":true},{"t":"책에 정답이 적혀 있기 때문에","mis":"K6-2-u1-X09"}],"mis":"K6-2-u1-X09","explanation":["종에 금이 간 곳부터 전개로 볼 수도 있어요.","마을이 어긋나기 시작한 곳부터 전개로 볼 수도 있어요.","중요한 것은 경계를 맞히는 일이 아니라 흐름을 알아보는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#10','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',3,'mc','auto','「종을 잃은 마을」 넷째 부분(결말)을 한 문장으로 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":3,"kind":"mc","stem":"「종을 잃은 마을」 넷째 부분(결말)을 한 문장으로 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"늘봄의 소리에 마을 사람들이 다시 모여 돈을 모았고, 이듬해 봄 새 종이 걸렸다","correct":true},{"t":"새 종이 걸렸다.","mis":"K6-2-u1-X11"},{"t":"눈이 그친 어느 아침 사람들이 모였고 늘봄은 놀라 나무판을 내려놓았고 아랫집 어른이 말했고 그 어른은 화를 냈던 어른이었다.","mis":"K6-2-u1-X11"},{"t":"늘봄이 처음으로 나무판을 두드렸다.","mis":"K6-2-u1-X09"}],"explanation":["결말의 중요한 사건은 사람들이 모여 새 종을 건 일이에요.","「늘봄의 소리에」를 넣어 앞 사건과 이어요.","너무 짧으면 까닭이 빠지고, 너무 길면 통째 옮기기가 돼요."],"asset":{"type":"passage","lines":["눈이 그친 어느 아침, 언덕에 사람들이 모여 있었다.","「네 소리 듣고 나온 지 벌써 여러 날이다.」","처음에 나무랐던 아랫집 어른의 말이었다.","그날 마을 사람들은 돈을 모으기로 했다.","이듬해 봄 새 종이 걸렸고, 첫 소리는 늘봄이 울렸다."],"title":"「종을 잃은 마을」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#1','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C5',2,'sa','auto','이야기 구조에서 이야기가 시작되는 부분을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C5","difficulty":2,"kind":"sa","stem":"이야기 구조에서 이야기가 시작되는 부분을 두 글자로 쓰세요.","answer":["발단"],"explanation":["이야기는 발단에서 시작해요.","인물과 배경이 소개되는 곳이 많아요.","「종을 잃은 마을」에서는 종소리에 맞추어 하루를 시작하는 마을이 나와요."],"mis":"K6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#2','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',2,'mc','auto','「종을 잃은 마을」 셋째 부분에서 중요한 사건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":2,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」 셋째 부분에서 중요한 사건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아무도 종을 울리지 못하게 되자 늘봄이 나무판을 두드려 새벽을 알리기 시작했다","correct":true},{"t":"늘봄의 손바닥이 부르텄다","mis":"K6-2-u1-X11"},{"t":"아랫집 어른이 나와 나무랐다","mis":"K6-2-u1-X11"},{"t":"헛간에 마른 나무판이 있었다","mis":"K6-2-u1-X11"}],"explanation":["부분마다 이야기의 흐름을 바꾸는 사건을 골라요.","손바닥·나무람·나무판은 그 사건에 딸린 내용이에요.","중심 사건 하나에 「왜」를 붙여 적어요."],"asset":{"type":"passage","lines":["가을 끝 무렵 덕곤 할아버지가 앓아누웠다.","그날 새벽 늘봄은 언덕에 올라 나무판을 두드렸다. 딱, 딱, 딱.","「그게 무슨 종소리냐.」 아랫집 어른이 나와 나무랐다.","늘봄은 얼굴이 뜨거워져 내려왔지만 이튿날 또 올라갔다.","손바닥이 부르터도 열이레 동안 새벽마다 두드렸다."],"title":"「종을 잃은 마을」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#3','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C5',3,'error','auto','「종을 잃은 마을」의 전개가 어디부터인지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「종을 잃은 마을」의 전개가 어디부터인지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「전개가 어디부터인지는 정답이 하나뿐이니 둘 가운데 하나는 틀렸어.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"준희 — 「종에 금이 간 곳부터 전개야. 사건이 그때 생겼거든.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「마을이 어긋나기 시작한 곳부터 전개야. 진짜 문제는 그때 생겼거든.」","mis":"K6-2-u1-X06"}],"explanation":["준희와 이현은 서로 다른 곳을 골랐어요.","둘 다 까닭을 말했어요.","경계는 까닭을 말할 수 있으면 사람마다 달라도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#4','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C7',3,'mc','auto','아랫집 어른이 「네 소리 듣고 나온 지 벌써 여러 날이다.」라고 했어요. 이 어른의 마음이 바뀐 것을 알 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12','K6-2-u1-X02']::text[],false,'{"seq":4,"concept":"K6-2-u1-C7","difficulty":3,"kind":"mc","stem":"아랫집 어른이 「네 소리 듣고 나온 지 벌써 여러 날이다.」라고 했어요. 이 어른의 마음이 바뀐 것을 알 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"처음에는 「그게 무슨 종소리냐.」 하며 나무랐던 어른이기 때문에","correct":true},{"t":"어른이 종을 만드는 사람이기 때문에","mis":"K6-2-u1-X12"},{"t":"늘봄의 아버지이기 때문에","mis":"K6-2-u1-X02"},{"t":"그날 눈이 그쳤기 때문에","mis":"K6-2-u1-X12"}],"explanation":["셋째 부분에서 이 어른은 늘봄을 나무랐어요.","넷째 부분에서는 그 소리에 맞추어 나왔다고 말해요.","앞뒤 말을 견주면 마음이 바뀐 것을 알 수 있어요."],"asset":{"type":"passage","lines":["눈이 그친 어느 아침, 언덕에 사람들이 모여 있었다.","「네 소리 듣고 나온 지 벌써 여러 날이다.」","처음에 나무랐던 아랫집 어른의 말이었다.","그날 마을 사람들은 돈을 모으기로 했다.","이듬해 봄 새 종이 걸렸고, 첫 소리는 늘봄이 울렸다."],"title":"「종을 잃은 마을」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#5','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',3,'ox','auto','「종을 잃은 마을」을 「늘봄이 종을 울렸다.」 한 문장으로 간추리면 잘 간추린 거예요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C6","difficulty":3,"kind":"ox","stem":"「종을 잃은 마을」을 「늘봄이 종을 울렸다.」 한 문장으로 간추리면 잘 간추린 거예요.","answer":"X","reason_options":[{"t":"종이 깨짐 → 마을이 어긋남 → 나무판 → 새 종으로 이어지는 중요한 사건이 빠져 뭉뚱그려졌기 때문에","correct":true},{"t":"문장이 짧을수록 잘 간추린 것이기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["사건만 고르고 흐름을 잇지 않으면 나열이 돼요.","흐름만 말하고 사건을 고르지 않으면 뭉뚱그림이 돼요.","부분마다 중요한 사건 하나씩, 이어지게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#6','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C5',3,'match','auto','이야기 구조와 「종을 잃은 마을」의 사건을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C5","difficulty":3,"kind":"match","stem":"이야기 구조와 「종을 잃은 마을」의 사건을 알맞게 이으세요.","pairs":[{"l":"발단","r":"종소리에 맞추어 마을이 하루를 시작했다"},{"l":"전개","r":"종에 금이 가고 마을이 어긋났다"},{"l":"절정","r":"늘봄이 나무람을 듣고도 나무판을 두드렸다"},{"l":"결말","r":"사람들이 돈을 모아 새 종을 걸었다"}],"mis":"K6-2-u1-X09","explanation":["발단은 처음 모습, 전개는 문제가 생기는 곳이에요.","절정은 늘봄이 가장 크게 부딪히는 곳이에요.","결말에서 문제가 풀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#7','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',3,'mc','auto','줄거리를 간추리는 차례 가운데 「간추린 문장을 이어 읽어 보고 말이 되는지 확인한다」는 몇째 단계인가요?',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":7,"concept":"K6-2-u1-C6","difficulty":3,"kind":"mc","stem":"줄거리를 간추리는 차례 가운데 「간추린 문장을 이어 읽어 보고 말이 되는지 확인한다」는 몇째 단계인가요?","options":[{"t":"넷째","correct":true},{"t":"첫째","mis":"K6-2-u1-X10"},{"t":"둘째","mis":"K6-2-u1-X10"},{"t":"셋째","mis":"K6-2-u1-X10"}],"explanation":["① 네 부분으로 나누기 ② 부분마다 중요한 사건 고르기","③ 고른 사건을 이어지도록 한두 문장으로 적기","④ 이어 읽어 말이 되는지 확인하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#8','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',4,'mc','auto','「없어지고 나서야 그 값을 알게 된 것」이라는 이 이야기의 흐름을 줄거리에 살린 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X02','K6-2-u1-X11']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「없어지고 나서야 그 값을 알게 된 것」이라는 이 이야기의 흐름을 줄거리에 살린 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"종이 깨지자 마을이 어긋났고, 그제야 사람들은 종소리가 마을을 하나로 맞춰 주고 있었음을 알았다","correct":true},{"t":"종은 오래되어 금이 가기 쉬웠다.","mis":"K6-2-u1-X10"},{"t":"마을 사람들은 시계를 사기로 했다.","mis":"K6-2-u1-X02"},{"t":"늘봄은 종소리를 좋아해서 하나, 둘, 셋을 세었다.","mis":"K6-2-u1-X11"}],"explanation":["이야기의 흐름은 「없어짐 → 어긋남 → 값을 앎」이에요.","이 흐름을 잇는 사건이 종이 깨지고 마을이 어긋난 일이에요.","덜 중요한 것이나 이야기에 없는 일은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#9','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',4,'blank','auto','「종이 깨져 마을이 어긋나자 (  ) 사람들이 다시 모여 새 종을 만들었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X09','K6-2-u1-X11']::text[],false,'{"seq":9,"concept":"K6-2-u1-C6","difficulty":4,"kind":"blank","stem":"「종이 깨져 마을이 어긋나자 (  ) 사람들이 다시 모여 새 종을 만들었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"늘봄이 나무판을 두드려 새벽을 알렸고, 그 소리에 맞추어","correct":true},{"t":"겨울이 와서 눈이 많이 내렸고,","mis":"K6-2-u1-X10"},{"t":"덕곤 할아버지가 새벽마다 종을 울렸고,","mis":"K6-2-u1-X09"},{"t":"늘봄은 이불 속에서 셋을 세었고,","mis":"K6-2-u1-X11"}],"explanation":["빈칸은 전개와 결말 사이 — 절정의 사건이 들어가요.","「그 소리에 맞추어」가 결말과 이어 줘요.","발단의 일이나 덜 중요한 일은 흐름을 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#10','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',4,'essay','teacher','「종을 잃은 마을」을 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지도록 이음말을 넣어 다시 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":4,"kind":"essay","stem":"「종을 잃은 마을」을 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지도록 이음말을 넣어 다시 써 보세요.","answer_guide":{"answer":"예: 발단 — 산 밑 마을 사람들은 덕곤 할아버지의 종소리에 맞추어 하루를 시작했다. 전개 — 그런데 겨울에 종에 금이 가고 새 종 만들기를 미루는 사이 마을이 어긋났다. 절정 — 할아버지마저 앓아눕자 늘봄이 나무판을 두드려 새벽을 알렸고, 나무람을 듣고도 열이레 동안 그만두지 않았다. 결말 — 그 소리에 다시 모인 사람들이 돈을 모았고 이듬해 봄 새 종이 걸렸다.","scoring_points":["네 부분으로 나누었는가","부분마다 중요한 사건을 한 문장으로 골랐는가","「그런데·~자·그 소리에」처럼 사건이 이어지게 썼는가"]},"explanation":["부분마다 중요한 사건 하나씩이에요.","이음말로 까닭과 흐름을 이어요.","네 문장을 이어 읽어 말이 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#1','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',1,'mc','auto','「사흘 걸린 다리」에 나오는 「징검다리」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":1,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「사흘 걸린 다리」에 나오는 「징검다리」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"물 위에 돌을 띄엄띄엄 놓아 건너다니게 만든 다리","correct":true},{"t":"나무로 길게 이어 만든 다리","mis":"K6-2-u1-X15"},{"t":"배를 여러 척 이어 만든 다리","mis":"K6-2-u1-X15"},{"t":"높은 곳에 매단 출렁다리","mis":"K6-2-u1-X15"}],"explanation":["「냇물은 깊지 않아서, 사람들은 징검다리를 밟고 건너다녔습니다.」","돌 열두 개를 하나씩 세며 건넜다고 했어요.","앞뒤 문장이 낱말의 뜻을 알려 줘요."],"asset":{"type":"passage","lines":["냇물 건너에 할머니의 밭이 있었다.","사람들은 징검다리를 밟고 냇물을 건너다녔다.","태건은 방학이면 할머니를 따라 돌 열두 개를 세며 건넜다.","여덟 번째 돌은 흔들려서, 할머니는 늘 그 앞에서 멈추었다."],"title":"「사흘 걸린 다리」 하나"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#2','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C6',1,'mc','auto','「사흘 걸린 다리」 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":2,"concept":"K6-2-u1-C6","difficulty":1,"kind":"mc","stem":"「사흘 걸린 다리」 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰비에 징검돌이 떠내려갔다","correct":true},{"t":"할머니가 밭을 팔았다","mis":"K6-2-u1-X02"},{"t":"어른들이 처음부터 함께 나와 돌을 옮겼다","mis":"K6-2-u1-X02"},{"t":"다리 대신 배를 띄웠다","mis":"K6-2-u1-X02"}],"explanation":["둘째 부분에 큰비로 징검돌이 떠내려간 일이 나와요.","어른들은 처음에는 가을로 미루었어요.","이야기에 적힌 일만 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#3','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',1,'sa','auto','「사흘 걸린 다리」에서 지난여름 큰비는 며칠 동안 내렸나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u1-C7","difficulty":1,"kind":"sa","stem":"「사흘 걸린 다리」에서 지난여름 큰비는 며칠 동안 내렸나요? 두 글자로 쓰세요.","answer":["사흘","3일","삼일"],"explanation":["「지난여름 큰비가 사흘 동안 내려」예요.","사흘은 세 날이에요.","시간을 나타내는 말은 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"},"mis":"K6-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#4','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u1-C7","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"지게","r":"짐을 얹어 등에 지는 나무 도구"},{"l":"거들다","r":"남이 하는 일을 옆에서 도와주다"},{"l":"여름내","r":"여름 한철 동안 내내"},{"l":"한나절","r":"하루 낮의 절반쯤 되는 동안"}],"mis":"K6-2-u1-X15","explanation":["낱말이 나온 문장을 떠올려요.","「지게를 지고」, 「거드는 사람도 없었다」, 「여름내」, 「돌 하나에 한나절」이에요.","앞뒤 문장이 뜻을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#5','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',2,'mc','auto','젖은 모래밭에 주저앉은 태건의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":5,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"젖은 모래밭에 주저앉은 태건의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"애써 한 일이 무너지고 혼자라는 생각이 든 막막한 마음","correct":true},{"t":"비가 와서 쉬게 되어 홀가분한 마음","mis":"K6-2-u1-X12"},{"t":"할머니가 도와주지 않아 서운하고 미운 마음","mis":"K6-2-u1-X12"},{"t":"돌이 많아져서 신나는 마음","mis":"K6-2-u1-X12"}],"explanation":["바로 앞에 사흘 쌓은 돌이 비에 흩어졌어요.","거드는 사람도 없이 혼자였어요.","앞뒤 사건이 인물의 마음을 짐작하는 근거예요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#6','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',2,'mc','auto','「지난여름」, 「여름내」, 「사흘째 되던 날」, 「이튿날 아침」 같은 말은 무엇을 나타내나요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":6,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「지난여름」, 「여름내」, 「사흘째 되던 날」, 「이튿날 아침」 같은 말은 무엇을 나타내나요?","options":[{"t":"시간","correct":true},{"t":"장소","mis":"K6-2-u1-X16"},{"t":"인물의 기분","mis":"K6-2-u1-X16"},{"t":"날씨","mis":"K6-2-u1-X16"}],"explanation":["이 말들은 언제 일이 일어났는지 알려 줘요.","시간을 나타내는 표현으로 지난 일과 지금 일을 가려 읽어요.","줄거리를 간추릴 때 일의 차례를 지키는 데 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#7','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C5',2,'mc','auto','태건이 사흘 동안 쌓은 돌이 무너진 날 상우 아저씨가 나타난 부분은 이야기 구조에서 어디인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":7,"concept":"K6-2-u1-C5","difficulty":2,"kind":"mc","stem":"태건이 사흘 동안 쌓은 돌이 무너진 날 상우 아저씨가 나타난 부분은 이야기 구조에서 어디인가요?","options":[{"t":"절정","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["태건이 가장 크게 부딪히고 주저앉은 곳이에요.","그때 흐름이 바뀌어요.","긴장감이 가장 높은 이곳이 절정이에요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#8','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C6',2,'ox','auto','「태건이 돌을 옮겼다. 비가 왔다. 아저씨가 왔다. 다리를 놓았다.」는 사건이 서로 이어지게 잘 간추린 거예요.',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":2,"kind":"ox","stem":"「태건이 돌을 옮겼다. 비가 왔다. 아저씨가 왔다. 다리를 놓았다.」는 사건이 서로 이어지게 잘 간추린 거예요.","answer":"X","reason_options":[{"t":"사건을 늘어놓기만 해서 왜 그런 일이 일어났는지가 드러나지 않기 때문에","correct":true},{"t":"사건을 차례대로 다 적었기 때문에","mis":"K6-2-u1-X10"}],"mis":"K6-2-u1-X10","explanation":["사건 사이에 까닭이 없어요.","「할머니가 먼 길을 돌아다니자」, 「쌓은 돌이 무너진 날」처럼 이어 주는 말이 필요해요.","이어지게 적어야 잘 간추린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#9','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',2,'mc','auto','「이튿날 아침 나가 보니 쌓아 둔 돌이 흩어져 있었다」에서 「이튿날」은 어느 날의 다음 날인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":9,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「이튿날 아침 나가 보니 쌓아 둔 돌이 흩어져 있었다」에서 「이튿날」은 어느 날의 다음 날인가요?","options":[{"t":"다시 비가 온 사흘째 되던 날","correct":true},{"t":"큰비가 그친 날","mis":"K6-2-u1-X16"},{"t":"할머니가 다리를 건넌 날","mis":"K6-2-u1-X16"},{"t":"어른 여섯이 나온 날","mis":"K6-2-u1-X16"}],"explanation":["「사흘째 되던 날 다시 비가 왔고」 바로 뒤에 나와요.","이튿날은 그다음 날이에요.","시간을 나타내는 말이 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#10','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C6',3,'mc','auto','「사흘 걸린 다리」의 결말을 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":3,"kind":"mc","stem":"「사흘 걸린 다리」의 결말을 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"이튿날 어른들이 함께 나와 다리를 놓았고, 할머니는 새 돌을 밟으며 멈추지 않고 건넜다","correct":true},{"t":"다리가 놓였다.","mis":"K6-2-u1-X11"},{"t":"태건이 혼자 돌을 굴려 올리기 시작했다.","mis":"K6-2-u1-X09"},{"t":"냇물 건너에 할머니의 밭이 있었다.","mis":"K6-2-u1-X09"}],"explanation":["결말에서는 문제가 풀려요 — 다리가 다시 놓였어요.","할머니가 멈추지 않고 건넌 것이 마무리예요.","너무 짧으면 흐름이 빠지고, 다른 부분의 사건은 결말이 아니에요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#1','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',2,'sa','auto','「사흘 걸린 다리」에서 징검다리를 다시 놓았을 때 돌은 모두 몇 개였나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C7","difficulty":2,"kind":"sa","stem":"「사흘 걸린 다리」에서 징검다리를 다시 놓았을 때 돌은 모두 몇 개였나요? 숫자로 쓰세요.","answer":["14","열네"],"explanation":["「돌은 열두 개가 아니라 열네 개였다.」","처음보다 두 개 더 놓였어요.","작은 말 하나가 장면의 뜻을 바꾸기도 해요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"},"mis":"K6-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#2','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C6',2,'mc','auto','「사흘 걸린 다리」의 전개를 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X09']::text[],false,'{"seq":2,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「사흘 걸린 다리」의 전개를 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰비에 징검돌이 떠내려갔지만 어른들이 가을로 미루자, 할머니는 여름내 한 시간을 돌아 밭에 다녔다","correct":true},{"t":"비가 왔다. 돌이 없었다. 길이 멀었다.","mis":"K6-2-u1-X10"},{"t":"태건은 방학이면 할머니를 따라 돌 열두 개를 세며 건넜다.","mis":"K6-2-u1-X09"},{"t":"할머니가 새 다리를 건넜다.","mis":"K6-2-u1-X09"}],"explanation":["전개는 사건이 본격적으로 생기는 부분이에요.","징검돌이 떠내려가고 어른들이 미루었어요.","그 때문에 할머니가 먼 길을 돌아다녔어요 — 까닭이 이어져요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#3','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'error','auto','「사흘 걸린 다리」에서 인상 깊었던 곳을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":3,"concept":"K6-2-u1-C7","difficulty":3,"kind":"error","stem":"「사흘 걸린 다리」에서 인상 깊었던 곳을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「인상 깊은 곳은 누구나 같아야 하니까 온새가 틀렸어.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"예강 — 「상우 아저씨가 ‘나도 좀 하자’라고 한 곳. 도와준다는 말보다 그 말이 더 좋았어.」","mis":"K6-2-u1-X06"},{"t":"온새 — 「마지막 줄. 할머니가 멈추지 않고 건너간 게 다 나은 것 같았어.」","mis":"K6-2-u1-X06"}],"explanation":["인상 깊은 곳은 저마다 달라요.","중요한 것은 장면이 아니라 그렇게 생각한 까닭이에요.","예강과 온새는 까닭을 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#4','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'mc','auto','할머니가 「여덟 번째 돌에서 한 번 멈추었다가, 이번에는 멈추지 않고 건너갔다」에서 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12','K6-2-u1-X02']::text[],false,'{"seq":4,"concept":"K6-2-u1-C7","difficulty":3,"kind":"mc","stem":"할머니가 「여덟 번째 돌에서 한 번 멈추었다가, 이번에는 멈추지 않고 건너갔다」에서 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 다리가 튼튼하게 놓였고, 할머니의 걸음과 마음도 가벼워졌다","correct":true},{"t":"여덟 번째 돌이 또 흔들렸다","mis":"K6-2-u1-X12"},{"t":"할머니가 다리를 건너기 싫어졌다","mis":"K6-2-u1-X12"},{"t":"돌이 열두 개뿐이었다","mis":"K6-2-u1-X02"}],"explanation":["처음에 여덟 번째 돌은 흔들려서 할머니가 늘 멈추었어요.","이번에는 한 번 멈추었다가 멈추지 않고 건넜어요.","처음 장면과 견주면 달라진 것이 보여요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#5','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'mc','auto','상우 아저씨가 「혼자 사흘을 했다며. 나도 좀 하자.」라고 한 말에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":5,"concept":"K6-2-u1-C7","difficulty":3,"kind":"mc","stem":"상우 아저씨가 「혼자 사흘을 했다며. 나도 좀 하자.」라고 한 말에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"태건이 혼자 애쓴 것을 알아주고 함께하겠다는 마음","correct":true},{"t":"태건이 일을 못해서 대신해 주겠다는 마음","mis":"K6-2-u1-X12"},{"t":"태건에게 그만두라고 나무라는 마음","mis":"K6-2-u1-X12"},{"t":"돌을 가져가려는 마음","mis":"K6-2-u1-X12"}],"explanation":["「혼자 사흘을 했다며」 — 태건의 수고를 알고 있었어요.","「나도 좀 하자」 — 도와준다기보다 함께하겠다는 말이에요.","그다음 날 어른 여섯이 나온 것과도 이어져요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#6','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C5',3,'match','auto','이야기 구조와 「사흘 걸린 다리」의 간추린 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C5","difficulty":3,"kind":"match","stem":"이야기 구조와 「사흘 걸린 다리」의 간추린 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"징검다리를 밟고 할머니 밭에 다녔다"},{"l":"전개","r":"돌이 떠내려가 먼 길로 돌아다녔다"},{"l":"절정","r":"혼자 쌓은 돌이 무너진 날 거들 사람이 왔다"},{"l":"결말","r":"여럿이 나와 다리를 다시 놓았다"}],"mis":"K6-2-u1-X09","explanation":["「그러나」, 「그때」처럼 흐름이 꺾이는 말을 살펴요.","절정은 태건이 주저앉은 날이에요.","결말에서 다리가 다시 놓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#7','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'ox','auto','「돌은 열두 개가 아니라 열네 개였다」는 처음보다 다리가 더 넉넉하게 놓였음을 짐작하게 해요.',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":3,"kind":"ox","stem":"「돌은 열두 개가 아니라 열네 개였다」는 처음보다 다리가 더 넉넉하게 놓였음을 짐작하게 해요.","answer":"O","reason_options":[{"t":"처음 다리보다 돌이 두 개 더 놓였다고 했기 때문에","correct":true},{"t":"할머니가 돌을 셀 줄 몰랐기 때문에","mis":"K6-2-u1-X12"}],"mis":"K6-2-u1-X12","explanation":["처음 다리는 돌 열두 개였어요.","여럿이 함께 놓으니 열네 개가 되었어요.","작은 차이가 함께한 힘을 보여 줘요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#8','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C6',4,'mc','auto','「사흘 걸린 다리」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「사흘 걸린 다리」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"큰비에 징검다리가 떠내려가 할머니가 먼 길을 돌아다니자 태건이 혼자 돌을 옮기기 시작했다. 쌓은 돌이 무너진 날 상우 아저씨가 거들었고, 이튿날 마을 어른들이 함께 다리를 다시 놓았다.","correct":true},{"t":"태건이 있었다. 할머니가 있었다. 돌이 있었다. 비가 왔다.","mis":"K6-2-u1-X10"},{"t":"태건은 돌을 옮겼다. 정말 대단한 아이다.","mis":"K6-2-u1-X11"},{"t":"징검다리는 물 위에 돌을 놓은 다리이다. 지게는 짐을 지는 도구이다.","mis":"K6-2-u1-X02"}],"explanation":["두 문장 안에 발단·전개·절정·결말의 중요한 사건이 다 들어가요.","「~자」, 「~날」로 사건이 이어져요.","느낌이나 낱말 뜻은 줄거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#9','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',4,'blank','auto','「(  ) 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.」 빈칸에 들어갈 시간을 나타내는 표현으로 이야기와 맞는 것은 어느 것인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":9,"concept":"K6-2-u1-C7","difficulty":4,"kind":"blank","stem":"「(  ) 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.」 빈칸에 들어갈 시간을 나타내는 표현으로 이야기와 맞는 것은 어느 것인가요?","options":[{"t":"지난여름","correct":true},{"t":"이듬해 봄","mis":"K6-2-u1-X16"},{"t":"사흘째 되던 날","mis":"K6-2-u1-X16"},{"t":"그다음 날 아침","mis":"K6-2-u1-X16"}],"explanation":["이야기는 「지난여름」에 큰비가 내렸다고 해요.","「사흘째 되던 날」은 태건이 돌을 옮긴 지 사흘째예요.","시간 표현을 바꾸면 일의 차례가 뒤엉켜요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#10','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C6',4,'essay','teacher','「사흘 걸린 다리」를 네 부분으로 나누어 부분마다 한 문장씩 간추리세요. 그리고 간추릴 때 도움이 된 시간을 나타내는 표현을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":4,"kind":"essay","stem":"「사흘 걸린 다리」를 네 부분으로 나누어 부분마다 한 문장씩 간추리세요. 그리고 간추릴 때 도움이 된 시간을 나타내는 표현을 두 가지 쓰세요.","answer_guide":{"answer":"예: 발단 — 태건은 방학이면 할머니를 따라 징검다리를 건너 밭에 다녔다. 전개 — 지난여름 큰비에 징검돌이 떠내려가고 어른들이 가을로 미루자, 할머니는 여름내 먼 길을 돌아다녔다. 절정 — 태건이 혼자 돌을 옮기다 사흘째 비에 무너졌을 때 상우 아저씨가 지게를 지고 왔다. 결말 — 그다음 날 어른들이 함께 나와 다리를 다시 놓았고, 할머니는 멈추지 않고 건넜다. 도움이 된 시간 표현: 「지난여름」, 「사흘째 되던 날」(「여름내」, 「이튿날」, 「그다음 날」도 됨).","scoring_points":["네 부분으로 나누어 중요한 사건을 한 문장씩 썼는가","사건이 까닭으로 이어지게 썼는가","시간을 나타내는 표현을 두 가지 들었는가"]},"explanation":["부분마다 중요한 사건 하나씩 — 네 문장이에요.","「~자」, 「그때」로 흐름을 이어요.","시간 표현은 일의 차례를 지켜 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#1','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'match','auto','작품 소개하는 글의 짜임과 넣을 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C8","difficulty":1,"kind":"match","stem":"작품 소개하는 글의 짜임과 넣을 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"작품 제목 · 작가 · 이 작품을 고른 까닭"},{"l":"가운데","r":"간추린 줄거리와 짐작한 작가의 의도"},{"l":"끝","r":"읽고 난 내 생각과 권하고 싶은 사람"}],"mis":"K6-2-u1-X11","explanation":["듣는 사람은 무엇에 대한 작품인지부터 알아야 해요.","가운데에는 이 단원에서 배운 두 가지 — 줄거리와 의도 — 가 들어가요.","끝에는 내 생각과 권할 사람을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#2','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'mc','auto','작품을 소개하는 글에 넣으면 좋은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":2,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작품을 소개하는 글에 넣으면 좋은 것은 어느 것인가요?","options":[{"t":"간추린 줄거리","correct":true},{"t":"책값과 쪽수","mis":"K6-2-u1-X13"},{"t":"결말까지 이야기 전체를 그대로 옮긴 것","mis":"K6-2-u1-X11"},{"t":"읽지 않은 다른 책의 제목","mis":"K6-2-u1-X13"}],"explanation":["소개에는 작품·작가·짐작한 의도·간추린 줄거리·고른 까닭이 들어가요.","책값과 쪽수는 작품이 어떤 작품인지 알려 주지 않아요.","줄거리는 간추려서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#3','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'ox','auto','「진짜 재미있어요! 안 읽으면 후회함! 별 다섯 개!」만으로도 좋은 작품 소개예요.',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":3,"concept":"K6-2-u1-C8","difficulty":1,"kind":"ox","stem":"「진짜 재미있어요! 안 읽으면 후회함! 별 다섯 개!」만으로도 좋은 작품 소개예요.","answer":"X","reason_options":[{"t":"읽는 사람이 작품이 어떤 작품인지 알 수 없는 광고에 가깝기 때문에","correct":true},{"t":"재미있었다는 마음이 잘 드러나기 때문에","mis":"K6-2-u1-X13"}],"mis":"K6-2-u1-X13","explanation":["소개는 광고가 아니에요.","재미있었다는 말은 한 줄이면 충분해요.","나머지는 작품이 어떤 작품인지로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#4','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'mc','auto','작가를 알아보고 정리해 학급 게시판에 올릴 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u1-X14','K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작가를 알아보고 정리해 학급 게시판에 올릴 때 알맞은 방법은 어느 것인가요?","options":[{"t":"찾은 글을 읽고 두세 줄로 간추려 내 말로 쓰고, 어디에서 찾았는지 적는다","correct":true},{"t":"찾은 글을 통째로 복사해 붙인다","mis":"K6-2-u1-X14"},{"t":"찾은 곳은 적지 않아도 된다","mis":"K6-2-u1-X14"},{"t":"작가의 이름만 적는다","mis":"K6-2-u1-X11"}],"explanation":["찾은 글을 그대로 옮기면 남의 글을 내 것처럼 내놓는 일이 돼요.","줄거리를 간추리던 방법을 그대로 써서 내 말로 적어요.","어디에서 찾았는지도 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#5','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'mc','auto','「종을 잃은 마을」을 소개하는 글에 알맞은 문장은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」을 소개하는 글에 알맞은 문장은 어느 것인가요?","options":[{"t":"종이 깨진 마을에서 한 아이가 새벽을 알리는 이야기로, 혼자 시작한 일이 여럿을 움직입니다","correct":true},{"t":"진짜 완전 대박이고 제 인생 책입니다. 무조건 읽으세요","mis":"K6-2-u1-X13"},{"t":"마지막에 새 종이 걸리고 주인공이 첫 소리를 울리며 이야기가 끝납니다","mis":"K6-2-u1-X11"},{"t":"이 이야기는 다섯 쪽이고 그림이 세 장 있습니다","mis":"K6-2-u1-X13"}],"explanation":["읽는 사람이 작품을 고를 수 있게 해 주는 문장이 좋아요.","무엇에 대한 이야기인지, 무엇을 전하는지가 드러나요.","결말을 다 말해 버리면 읽는 즐거움을 빼앗아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#6','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'mc','auto','친구의 작품 소개를 읽고 하기 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":6,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"친구의 작품 소개를 읽고 하기 좋은 물음은 어느 것인가요?","options":[{"t":"어느 부분을 보고 그렇게 짐작했어?","correct":true},{"t":"이 책 몇 쪽이야?","mis":"K6-2-u1-X13"},{"t":"이거 글씨 큰 책이야?","mis":"K6-2-u1-X13"},{"t":"그 책 얼마야?","mis":"K6-2-u1-X13"}],"explanation":["근거를 묻는 물음이 좋은 물음이에요.","묻는 사람도 답하는 사람도 작품을 한 번 더 읽게 돼요.","쪽수·글씨·값은 작품으로 돌아가게 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#7','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'sa','auto','작품 소개하는 글의 짜임(처음·가운데·끝)에서 간추린 줄거리와 짐작한 작가의 의도는 어디에 넣나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C8","difficulty":2,"kind":"sa","stem":"작품 소개하는 글의 짜임(처음·가운데·끝)에서 간추린 줄거리와 짐작한 작가의 의도는 어디에 넣나요? 세 글자로 쓰세요.","answer":["가운데"],"explanation":["처음 — 제목·작가·고른 까닭이에요.","가운데 — 간추린 줄거리와 짐작한 의도예요.","끝 — 내 생각과 권할 사람이에요."],"mis":"K6-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#8','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'mc','auto','소개하는 글의 「처음」에 넣을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":8,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 글의 「처음」에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품 제목과 작가, 이 작품을 고른 까닭","correct":true},{"t":"결말까지의 자세한 줄거리","mis":"K6-2-u1-X11"},{"t":"권하고 싶은 사람","mis":"K6-2-u1-X11"},{"t":"책을 산 가게 이름","mis":"K6-2-u1-X13"}],"explanation":["처음에는 무슨 작품인지와 왜 골랐는지를 밝혀요.","「저는 그만둔 일을 아까워한 적이 있어서 이 시를 골랐습니다.」처럼요.","권할 사람은 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#9','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'ox','auto','작품 소개에서 짐작한 작가의 의도를 말할 때는 어디를 보고 그렇게 생각했는지 함께 써요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":9,"concept":"K6-2-u1-C8","difficulty":2,"kind":"ox","stem":"작품 소개에서 짐작한 작가의 의도를 말할 때는 어디를 보고 그렇게 생각했는지 함께 써요.","answer":"O","reason_options":[{"t":"근거가 있어야 읽는 사람도 작품을 다시 보며 판단할 수 있기 때문에","correct":true},{"t":"작가의 의도는 하나뿐이라 근거가 없어도 되기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["짐작 + 근거를 한 묶음으로 써요.","「‘걷는다’가 되풀이되는 것으로 보아」처럼 근거를 밝혀요.","근거가 있으면 친구와 생각을 나누기도 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#10','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',3,'error','auto','작품 소개하는 글을 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13','K6-2-u1-X14']::text[],false,'{"seq":10,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개하는 글을 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「줄거리는 결말까지 한 문장도 빼지 않고 다 적어야 해.」","correct":true,"mis_target":"K6-2-u1-X11"},{"t":"준희 — 「재미있었다는 말은 한 줄이면 충분해.」","mis":"K6-2-u1-X13"},{"t":"이현 — 「찾은 글은 간추려 내 말로 쓰고 출처를 적어.」","mis":"K6-2-u1-X14"}],"explanation":["줄거리는 간추려서 써요.","결말을 다 적으면 통째 옮기기이고 읽는 즐거움도 빼앗아요.","준희와 이현은 이 단원에서 배운 대로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#1','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',2,'mc','auto','「약속한 날이 다 찼다.」에서 「찼다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":1,"concept":"K6-2-u1-C9","difficulty":2,"kind":"mc","stem":"「약속한 날이 다 찼다.」에서 「찼다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"정해진 만큼 되었다","correct":true},{"t":"발을 뻗어 세게 내질렀다","mis":"K6-2-u1-X15"},{"t":"몸에 닿는 것이 차가웠다","mis":"K6-2-u1-X15"},{"t":"허리에 매달았다","mis":"K6-2-u1-X15"}],"explanation":["글자가 같아도 뜻이 다른 낱말이 있어요.","「약속한 날이」와 함께 쓰였으니 날짜가 다 되었다는 뜻이에요.","앞뒤 문장을 보아야 어느 뜻인지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#2','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',2,'mc','auto','소개하는 방법(소개하는 글 · 광고지 · 작가 알아보기 · 말로 소개)이 달라도 같아야 하는 것은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":2,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 방법(소개하는 글 · 광고지 · 작가 알아보기 · 말로 소개)이 달라도 같아야 하는 것은 어느 것인가요?","options":[{"t":"담을 내용 — 작품·작가·짐작한 의도·간추린 줄거리·고른 까닭","correct":true},{"t":"글씨 크기와 색깔","mis":"K6-2-u1-X13"},{"t":"작품의 값","mis":"K6-2-u1-X13"},{"t":"그림의 개수","mis":"K6-2-u1-X13"}],"explanation":["방법은 고를 수 있어요.","하지만 담을 내용은 같아요.","작품이 어떤 작품인지 알 수 있게 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#3','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',3,'mc','auto','「돌아오는 길」을 소개하는 글의 「가운데」로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X14']::text[],false,'{"seq":3,"concept":"K6-2-u1-C8","difficulty":3,"kind":"mc","stem":"「돌아오는 길」을 소개하는 글의 「가운데」로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가운데 — 잃어버린 것을 세던 사람이 담을 따라 걷다가 뒤에 남은 발자국을 보고 그것이 길이 되었음을 알아차리는 시입니다. 「걷는다」가 되풀이되는 것으로 보아, 잃은 것이 있어도 걸어온 자국은 남는다는 것을 전하려 한 것 같습니다.","correct":true},{"t":"가운데 — 저는 이 시를 별 다섯 개로 추천합니다. 꼭 읽으세요!","mis":"K6-2-u1-X13"},{"t":"가운데 — 누리집에 있던 작가 소개 글을 그대로 붙여 넣었습니다.","mis":"K6-2-u1-X14"},{"t":"가운데 — 이 시는 네 연이고 제목은 다섯 글자입니다.","mis":"K6-2-u1-X13"}],"explanation":["가운데에는 간추린 내용과 짐작한 의도가 들어가요.","「‘걷는다’가 되풀이되는 것으로 보아」처럼 근거도 밝혀요.","광고·통째 옮기기·겉모습 설명은 가운데가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#4','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',3,'ox','auto','작가를 알아본 글을 학급 게시판에 올릴 때 찾은 글을 그대로 옮기면 남의 글을 내 것처럼 내놓는 일이 돼요.',ARRAY['K6-2-u1-X14']::text[],false,'{"seq":4,"concept":"K6-2-u1-C8","difficulty":3,"kind":"ox","stem":"작가를 알아본 글을 학급 게시판에 올릴 때 찾은 글을 그대로 옮기면 남의 글을 내 것처럼 내놓는 일이 돼요.","answer":"O","reason_options":[{"t":"내가 무엇을 알게 되었는지 드러나지 않고 쓴 사람의 노력을 내 것처럼 쓰는 일이기 때문에","correct":true},{"t":"누리집에 있는 글은 누구나 제 것처럼 써도 되기 때문에","mis":"K6-2-u1-X14"}],"mis":"K6-2-u1-X14","explanation":["찾은 것은 읽고 두세 줄로 간추려 내 말로 적어요.","어디에서 찾았는지 함께 적어요.","간추려 쓰는 방법은 이 단원에서 이미 배웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#5','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',3,'match','auto','문장과 밑줄 친 낱말의 뜻을 알맞게 이으세요. (밑줄: 찼다, 찼다, 눈, 눈)','{}'::text[],false,'{"seq":5,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"문장과 밑줄 친 낱말의 뜻을 알맞게 이으세요. (밑줄: 찼다, 찼다, 눈, 눈)","pairs":[{"l":"동생이 공을 세게 찼다","r":"발을 뻗어 세게 내질렀다"},{"l":"약속한 날이 다 찼다","r":"정해진 만큼 되었다"},{"l":"밤새 눈이 내렸다","r":"하늘에서 내리는 하얗고 찬 것"},{"l":"할머니는 눈이 밝으시다","r":"사물을 보는 몸의 한 부분"}],"mis":"K6-2-u1-X15","explanation":["같은 글자인데 뜻이 갈려요.","낱말만 보면 알 수 없어요.","그 문장이 무엇에 대한 말인지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#6','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',3,'error','auto','친구들이 작품 소개를 읽고 물었어요. 작품으로 돌아가게 하지 않는 물음을 한 친구는 누구인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":6,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"친구들이 작품 소개를 읽고 물었어요. 작품으로 돌아가게 하지 않는 물음을 한 친구는 누구인가요?","options":[{"t":"서아 — 「이 책 글씨 커?」","correct":true,"mis_target":"K6-2-u1-X13"},{"t":"준희 — 「어느 부분을 보고 그렇게 짐작했어?」","mis":"K6-2-u1-X13"},{"t":"이현 — 「가장 인상 깊었던 구절은 어디야?」","mis":"K6-2-u1-X13"}],"explanation":["근거나 구절을 묻는 물음은 작품을 다시 보게 해요.","글씨 크기는 작품과 상관없어요.","서로 근거를 물으면 작품이 더 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#7','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',3,'mc','auto','「할머니는 눈이 밝으시다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C9","difficulty":3,"kind":"mc","stem":"「할머니는 눈이 밝으시다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"동생은 눈이 좋아 멀리 있는 글씨도 읽는다","correct":true},{"t":"밤새 눈이 내려 길이 하얗다","mis":"K6-2-u1-X15"},{"t":"운동장에서 눈사람을 만들었다","mis":"K6-2-u1-X15"},{"t":"지붕의 눈이 녹아 물이 되었다","mis":"K6-2-u1-X15"}],"explanation":["「눈이 밝으시다」는 잘 본다는 뜻이에요.","사물을 보는 몸의 한 부분인 「눈」이에요.","하늘에서 내리는 눈과 글자는 같지만 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#8','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',4,'mc','auto','「종을 잃은 마을」을 소개하는 글의 「끝」으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":8,"concept":"K6-2-u1-C8","difficulty":4,"kind":"mc","stem":"「종을 잃은 마을」을 소개하는 글의 「끝」으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 시작한 일이 망설여지는 친구에게 권하고 싶습니다. 늘봄이 나무람을 듣고도 다시 언덕에 오른 장면에서 저도 용기가 났습니다.","correct":true},{"t":"끝으로 이 책은 정말 최고이니 무조건 사세요.","mis":"K6-2-u1-X13"},{"t":"끝에 새 종이 걸리고 늘봄이 첫 소리를 울리며 이야기가 끝납니다.","mis":"K6-2-u1-X11"},{"t":"이 이야기를 쓴 작가의 다른 책 제목은 모릅니다.","mis":"K6-2-u1-X11"}],"explanation":["끝에는 읽고 난 내 생각과 권하고 싶은 사람을 써요.","내 생각에도 작품의 장면을 근거로 들면 좋아요.","결말을 다 말하거나 광고처럼 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#9','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',4,'blank','auto','「동생이 공을 세게 (  ).」와 「약속한 날이 다 (  ).」에 똑같이 들어갈 낱말은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":9,"concept":"K6-2-u1-C9","difficulty":4,"kind":"blank","stem":"「동생이 공을 세게 (  ).」와 「약속한 날이 다 (  ).」에 똑같이 들어갈 낱말은 어느 것인가요?","options":[{"t":"찼다","correct":true},{"t":"던졌다","mis":"K6-2-u1-X15"},{"t":"채웠다","mis":"K6-2-u1-X15"},{"t":"넘었다","mis":"K6-2-u1-X15"}],"explanation":["「차다」에는 여러 뜻이 있어요.","발로 내지르다 · 정해진 만큼 되다 — 두 뜻 모두 「찼다」예요.","앞뒤 문장이 어느 뜻인지 정해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#10','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',4,'essay','teacher','이 단원에서 읽은 작품(「창문」·「돌아오는 길」·「우산」·「같이 건너세」·「나루를 지켜」·「종을 잃은 마을」·「사흘 걸린 다리」) 가운데 하나를 골라, 처음·가운데·끝의 짜임으로 소개하는 글을 쓰세요. 가운데에는 간추린 줄거리(또는 시의 내용)와 짐작한 작가의 의도를 근거와 함께 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C8","difficulty":4,"kind":"essay","stem":"이 단원에서 읽은 작품(「창문」·「돌아오는 길」·「우산」·「같이 건너세」·「나루를 지켜」·「종을 잃은 마을」·「사흘 걸린 다리」) 가운데 하나를 골라, 처음·가운데·끝의 짜임으로 소개하는 글을 쓰세요. 가운데에는 간추린 줄거리(또는 시의 내용)와 짐작한 작가의 의도를 근거와 함께 넣으세요.","answer_guide":{"answer":"예(「사흘 걸린 다리」): 처음 — 「사흘 걸린 다리」는 떠내려간 징검다리를 다시 놓는 이야기입니다. 저도 혼자 시작했다가 그만둔 일이 있어서 골랐습니다. 가운데 — 큰비에 징검돌이 떠내려가 할머니가 먼 길을 돌아다니자 태건이 혼자 돌을 옮겼고, 쌓은 돌이 무너진 날 아저씨가 거들어 마을 사람들이 함께 다리를 놓았습니다. 돌이 열두 개가 아니라 열네 개가 된 것으로 보아, 한 사람이 시작한 일이 여럿의 힘을 모은다는 것을 전하려 한 것 같습니다. 끝 — 혼자 하는 일이 막막한 친구에게 권하고 싶습니다.","scoring_points":["처음·가운데·끝의 짜임을 갖추었는가","가운데에 간추린 줄거리(내용)와 짐작한 의도·근거를 넣었는가","광고처럼 쓰지 않고 고른 까닭·권할 사람을 밝혔는가"]},"explanation":["처음 — 제목·작가·고른 까닭이에요.","가운데 — 간추린 줄거리 + 의도와 근거예요.","끝 — 내 생각과 권할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#1','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',1,'mc','auto','작가의 의도에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X11']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작가의 의도에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"작가가 작품에 담은 생각과 바람이다","correct":true},{"t":"읽는 사람마다 똑같아야 하는 답이다","mis":"K6-2-u1-X01"},{"t":"작품에 나온 사건을 차례대로 적은 것이다","mis":"K6-2-u1-X11"},{"t":"작가가 쓴 책의 수이다","mis":"K6-2-u1-X01"}],"explanation":["작가의 의도는 쓴 사람 쪽에서 생각해요.","작품에 담은 생각과 바람이에요.","읽는 사람이 근거를 들어 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#2','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C2',1,'mc','auto','「우산」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「우산」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"덮는다","correct":true},{"t":"어깨는","mis":"K6-2-u1-X03"},{"t":"구석에서","mis":"K6-2-u1-X03"},{"t":"젖는다","mis":"K6-2-u1-X03"}],"explanation":["1연 「남을 덮는다」, 2연 「덮는 동안」, 3연 「덮는 일」, 4연 「또 남을 덮는다」예요.","「덮는다」가 처음과 끝에 되풀이돼요.","되풀이된 말은 눈여겨볼 표시예요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#3','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 사건이 본격적으로 생기는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 사건이 본격적으로 생기는 부분은 어느 것인가요?","options":[{"t":"전개","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#4','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',1,'ox','auto','줄거리를 간추릴 때는 덜 중요한 내용을 덜어 내요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추릴 때는 덜 중요한 내용을 덜어 내요.","answer":"O","reason_options":[{"t":"중요한 사건만 남겨야 흐름이 잘 보이기 때문에","correct":true},{"t":"글자 수를 줄이는 것만이 목적이기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["중요한 사건을 골라요.","덜 중요한 것은 덜어 내요.","고른 사건을 이어지게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#5','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',1,'mc','auto','작품 소개하는 글에 넣지 않아도 되는 것은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작품 소개하는 글에 넣지 않아도 되는 것은 어느 것인가요?","options":[{"t":"책값과 쪽수","correct":true},{"t":"간추린 줄거리","mis":"K6-2-u1-X13"},{"t":"짐작한 작가의 의도","mis":"K6-2-u1-X13"},{"t":"이 작품을 고른 까닭","mis":"K6-2-u1-X13"}],"explanation":["소개에는 작품이 어떤 작품인지가 들어가요.","줄거리·의도·고른 까닭은 꼭 필요해요.","책값과 쪽수는 작품을 알려 주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#6','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C9',1,'mc','auto','「모자를 쓰다」의 「쓰다」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「모자를 쓰다」의 「쓰다」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"안경을 쓰고 책을 읽었다","correct":true},{"t":"편지를 쓰다","mis":"K6-2-u1-X15"},{"t":"약이 쓰다","mis":"K6-2-u1-X15"},{"t":"용돈을 쓰다","mis":"K6-2-u1-X15"}],"explanation":["「모자를 쓰다」는 머리나 얼굴에 얹는다는 뜻이에요.","「안경을 쓰다」도 같은 뜻이에요.","앞뒤 말을 보아야 뜻을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#7','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',1,'mc','auto','「거들다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「거들다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"남이 하는 일을 옆에서 도와주다","correct":true},{"t":"남의 일을 방해하다","mis":"K6-2-u1-X15"},{"t":"혼자 끝까지 하다","mis":"K6-2-u1-X15"},{"t":"일을 뒤로 미루다","mis":"K6-2-u1-X15"}],"explanation":["「거드는 사람도 말리는 사람도 없었다」에 나와요.","돕는다는 뜻이에요.","앞뒤 문장이 뜻을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#8','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶을 알면 작품의 뜻이 하나로 정해져요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶을 알면 작품의 뜻이 하나로 정해져요.","answer":"X","reason_options":[{"t":"작가의 삶은 실마리일 뿐이고 근거는 작품에서 찾아야 하기 때문에","correct":true},{"t":"작가가 쓴 대로만 읽어야 하기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["작가의 삶은 읽기를 시작하게 하는 실마리예요.","뜻을 하나로 정해 주지 않아요.","작품으로 돌아와 근거를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#9','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C2',2,'mc','auto','「우산」에서 「덮는다」가 처음과 끝에 되풀이되어 생기는 효과로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「우산」에서 「덮는다」가 처음과 끝에 되풀이되어 생기는 효과로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번이 아니라 되풀이해 온 일임이 드러난다","correct":true},{"t":"시를 읽는 데 걸리는 시간이 길어진다","mis":"K6-2-u1-X03"},{"t":"우산의 색깔을 자세히 알려 준다","mis":"K6-2-u1-X02"},{"t":"비가 그쳤음을 알려 준다","mis":"K6-2-u1-X02"}],"explanation":["1연과 4연에 「남을 덮는다」가 나와요.","4연에는 「또」가 붙어요.","비가 올 때마다 되풀이되는 일임이 드러나요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#10','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C4',2,'mc','auto','「우산」의 「네 어깨는 젖는다」가 나타낸다고 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「우산」의 「네 어깨는 젖는다」가 나타낸다고 볼 수 있는 것은 어느 것인가요?","options":[{"t":"남을 위하느라 자기는 힘들고 손해를 보는 것","correct":true},{"t":"우산이 고장 났다는 것","mis":"K6-2-u1-X08"},{"t":"비가 그쳤다는 것","mis":"K6-2-u1-X08"},{"t":"어깨가 아픈 병이 있다는 것","mis":"K6-2-u1-X08"}],"explanation":["우산은 남을 덮어 주어요.","그동안 자기 어깨는 젖어요.","남을 돕느라 자기는 힘든 모습을 떠올리게 해요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#11','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',2,'mc','auto','「우산」을 읽고 예강은 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」, 슬찬은 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」라고 했어요. 두 읽기에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「우산」을 읽고 예강은 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」, 슬찬은 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」라고 했어요. 두 읽기에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 시에서 근거를 들었으니 둘 다 좋은 읽기다","correct":true},{"t":"작가는 하나만 생각했을 테니 하나는 틀렸다","mis":"K6-2-u1-X06"},{"t":"시에 「부모님」이라는 말이 없으니 예강이 틀렸다","mis":"K6-2-u1-X06"},{"t":"둘 다 느낌일 뿐 근거가 없다","mis":"K6-2-u1-X06"}],"explanation":["예강은 「남을 덮는다」, 「어깨는 젖는다」를 근거로 댔어요.","슬찬은 「구석에서 마른다」를 근거로 댔어요.","근거가 있으면 서로 달라도 좋은 읽기예요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#12','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「마지막 버스」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「마지막 버스」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"하루 세 번 다니는 버스와 경적을 울리던 아저씨"},{"l":"전개","r":"마지막 버스가 없어져 하은이 한 시간을 걸었다"},{"l":"절정","r":"어른들이 고개를 저어도 하은이 한 달 동안 사람 수를 적었다"},{"l":"결말","r":"편지에 이름이 모여 마지막 버스가 다시 다녔다"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#13','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',2,'mc','auto','「마지막 버스」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「마지막 버스」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"마지막 버스가 없어져 마을 사람들이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적어 함께 편지를 쓰자고 했고, 어른들이 이름을 적어 버스가 다시 다니게 되었다","correct":true},{"t":"버스가 있었다. 봄이었다. 공책이 있었다. 편지를 썼다.","mis":"K6-2-u1-X10"},{"t":"하은은 정말 착한 아이다.","mis":"K6-2-u1-X11"},{"t":"산골 마을에서 읍내로 가는 버스는 하루 세 번 다녔다. 봉식 아저씨는…(처음부터 그대로)","mis":"K6-2-u1-X11"}],"explanation":["잘 간추린 줄거리는 사건끼리 이어져 있어요.","「~자 ~했고 ~해」처럼 까닭이 보여요.","늘어놓기·느낌·통째 옮기기는 간추린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#14','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 마지막 버스가 없어진 때는 언제인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 마지막 버스가 없어진 때는 언제인가요?","options":[{"t":"그해 봄","correct":true},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"},{"t":"하루 세 번","mis":"K6-2-u1-X16"}],"explanation":["「그해 봄, 버스 회사는 … 마지막 버스를 없앴다.」","「이듬달 첫날」은 다시 다닌 날이에요.","시간을 나타내는 표현으로 일의 차례를 가려요."],"asset":{"type":"passage","lines":["그해 봄, 버스 회사는 손님이 적다며 마지막 버스를 없앴다.","읍내에서 늦게 끝나는 하은은 한 시간을 걸어 돌아왔다.","장 보러 간 어른들도 해 지기 전에 서둘러야 했다."],"title":"「마지막 버스」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#15','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',2,'mc','auto','「그런다고 회사가 들어주겠니.」라는 말을 듣고도 하은이 계속 적은 데서 알 수 있는 마음은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「그런다고 회사가 들어주겠니.」라는 말을 듣고도 하은이 계속 적은 데서 알 수 있는 마음은 어느 것인가요?","options":[{"t":"마을 사람들의 불편을 꼭 바꾸고 싶은 굳은 마음","correct":true},{"t":"어른들을 골탕 먹이려는 마음","mis":"K6-2-u1-X12"},{"t":"공책을 빨리 다 쓰고 싶은 마음","mis":"K6-2-u1-X12"},{"t":"버스 기사가 되고 싶은 마음","mis":"K6-2-u1-X12"}],"explanation":["하은은 자기도, 어른들도 불편해진 것을 겪었어요.","반대하는 말을 듣고도 한 달 동안 적었어요.","앞뒤 사건이 마음을 짐작하는 근거예요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#16','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',2,'mc','auto','「마지막 버스」를 소개하는 글의 「처음」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「마지막 버스」를 소개하는 글의 「처음」으로 알맞은 것은 어느 것인가요?","options":[{"t":"「마지막 버스」는 없어진 버스를 다시 다니게 한 아이의 이야기입니다. 저도 버스로 학원에 다녀서 이 이야기를 골랐습니다.","correct":true},{"t":"완전 강추! 무조건 읽으세요!","mis":"K6-2-u1-X13"},{"t":"이 책은 150쪽이고 값은 8000원입니다.","mis":"K6-2-u1-X13"},{"t":"결국 버스가 다시 다니고 아저씨가 경적을 두 번 울리며 끝납니다.","mis":"K6-2-u1-X11"}],"explanation":["처음에는 무슨 작품인지와 고른 까닭을 써요.","광고나 값은 작품을 알려 주지 않아요.","결말을 다 말하면 읽는 즐거움을 빼앗아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#17','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C3',3,'mc','auto','정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 알고 「다 닳은 연필을 / 버리지 못하고」를 다시 읽을 때 가장 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X04','K6-2-u1-X02']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 알고 「다 닳은 연필을 / 버리지 못하고」를 다시 읽을 때 가장 알맞은 짐작은 어느 것인가요?","options":[{"t":"어려운 때를 함께한 작은 것을 소중히 여기는 마음을 전하려 한 것 같다","correct":true},{"t":"연필을 많이 사 두자는 뜻이다","mis":"K6-2-u1-X08"},{"t":"작가가 선생님이니 공부를 열심히 하라는 뜻이다. 끝.","mis":"K6-2-u1-X04"},{"t":"연필은 다 쓰면 바로 버려야 한다는 뜻이다","mis":"K6-2-u1-X02"}],"explanation":["작가는 연필 한 자루를 오래 아껴 썼어요.","그래서 「버리지 못하고」가 그냥 나온 말이 아니겠구나 싶어요.","삶은 실마리, 근거는 「필통 맨 앞에 둔다」 같은 시구예요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#18','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',3,'error','auto','「연필」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「연필」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「작가가 생각한 뜻은 하나뿐이니 우리는 그 정답을 맞혀야 해.」","correct":true,"mis_target":"K6-2-u1-X01"},{"t":"준희 — 「‘손안에서 작아진다’를 보면 자기를 내어 주는 이야기 같아.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「‘필통 맨 앞에 둔다’를 보면 고마운 마음이 느껴져.」","mis":"K6-2-u1-X06"}],"explanation":["작가의 의도는 맞혀야 하는 정답이 아니에요.","준희와 이현은 시구를 근거로 댔어요.","근거가 있으면 좋은 읽기예요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#19','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',3,'blank','auto','「마지막 버스가 없어져 마을 사람들이 불편해지자 (  ) 어른들이 함께 편지에 이름을 적어 버스가 다시 다니게 되었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X11','K6-2-u1-X10']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「마지막 버스가 없어져 마을 사람들이 불편해지자 (  ) 어른들이 함께 편지에 이름을 적어 버스가 다시 다니게 되었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"하은이 한 달 동안 기다리는 사람 수를 적어 함께 편지를 쓰자고 했고,","correct":true},{"t":"봉식 아저씨가 경적을 한 번 더 울렸고,","mis":"K6-2-u1-X09"},{"t":"하은은 한 시간을 걸어 돌아왔고,","mis":"K6-2-u1-X11"},{"t":"그해 봄이 왔고,","mis":"K6-2-u1-X10"}],"explanation":["빈칸에는 절정의 사건이 들어가요.","하은의 공책이 어른들의 이름으로 이어져요.","다른 보기는 흐름을 잇지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#20','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',3,'error','auto','「마지막 버스」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「마지막 버스」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「버스가 다시 다니는 곳이 절정이야. 가장 기쁘니까.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"준희 — 「어른들이 고개를 저어도 하은이 한 달을 적은 곳이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「마지막 버스가 없어진 곳부터 전개야.」","mis":"K6-2-u1-X06"}],"explanation":["절정은 가장 기쁜 곳이 아니라 갈등이 가장 두드러지는 곳이에요.","버스가 다시 다니는 곳은 결말이에요.","준희와 이현은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#21','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C9',3,'match','auto','「쓰다」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「쓰다」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"편지를 쓰다","r":"글씨로 적다"},{"l":"모자를 쓰다","r":"머리에 얹다"},{"l":"약이 쓰다","r":"맛이 달지 않고 혀가 아리다"},{"l":"용돈을 쓰다","r":"돈을 들이다"}],"mis":"K6-2-u1-X15","explanation":["글자는 같지만 뜻이 네 가지예요.","함께 쓰인 말(편지·모자·약·용돈)이 뜻을 정해요.","앞뒤 말을 보고 가려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#22','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06','K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「짐작한 의도는 근거 없이 써도 돼.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"준희 — 「처음에는 고른 까닭을 써.」","mis":"K6-2-u1-X13"},{"t":"이현 — 「가운데에는 간추린 줄거리를 써.」","mis":"K6-2-u1-X11"}],"explanation":["짐작한 의도에는 근거를 함께 써요.","처음 — 고른 까닭, 가운데 — 줄거리와 의도예요.","준희와 이현은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#23','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',4,'mc','auto','「마지막 버스」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「마지막 버스」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 버스가 없어져 마을 사람들이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적었다. 그 공책을 본 어른들이 함께 편지에 이름을 적어 이듬달 첫날 버스가 다시 다니게 되었다.","correct":true},{"t":"하은이 있었다. 버스가 있었다. 공책이 있었다. 편지가 있었다.","mis":"K6-2-u1-X10"},{"t":"하은은 착하고, 봉식 아저씨는 친절하다.","mis":"K6-2-u1-X11"},{"t":"버스는 하루 세 번 다녔다. 아저씨는 경적을 울렸다.","mis":"K6-2-u1-X09"}],"explanation":["두 문장 안에 네 부분의 중요한 사건이 다 들어가요.","「~자」, 「그 공책을 본」이 사건을 이어요.","「이듬달 첫날」로 때도 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#24','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',4,'essay','teacher','「우산」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 그렇게 짐작한 근거가 되는 시구를 두 가지 드세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"「우산」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 그렇게 짐작한 근거가 되는 시구를 두 가지 드세요.","answer_guide":{"answer":"예: 티 나지 않게 남을 돕는 사람의 마음과 그 고마움을 전하려 한 것 같다. 근거는 「너는 남을 덮는다」·「네 어깨는 젖는다」로 남을 위해 자기가 젖는 모습을 그린 것과, 「접힌 채로 구석에서 마른다」로 일이 끝나면 눈에 띄지 않는 곳에 놓이는 모습을 그린 것이다. 「덮는다」가 처음과 끝에 되풀이되어 이런 일이 계속됨을 드러낸다.","scoring_points":["의도를 한 문장으로 짐작했는가","근거 시구를 두 가지 들었는가","되풀이한 표현의 효과를 근거로 썼는가"]},"explanation":["짐작 + 근거가 한 묶음이에요.","「덮는다」의 되풀이가 좋은 근거예요.","근거가 있으면 다르게 읽어도 좋아요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#25','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',4,'essay','teacher','「마지막 버스」에서 시간을 나타내는 표현을 세 가지 찾아 쓰고, 그 표현을 써서 일이 일어난 차례대로 이야기를 세 문장으로 간추리세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C7","difficulty":4,"kind":"essay","stem":"「마지막 버스」에서 시간을 나타내는 표현을 세 가지 찾아 쓰고, 그 표현을 써서 일이 일어난 차례대로 이야기를 세 문장으로 간추리세요.","answer_guide":{"answer":"예: 시간 표현 — 「하루 세 번」, 「그해 봄」, 「한 달 동안」, 「이듬달 첫날」 가운데 세 가지. 간추리기 — 그해 봄 버스 회사가 마지막 버스를 없앴다. 하은은 한 달 동안 정류장에서 기다리는 사람 수를 적어 같이 편지를 쓰자고 했다. 어른들이 편지에 이름을 적었고 이듬달 첫날 마지막 버스가 다시 다니기 시작했다.","scoring_points":["시간을 나타내는 표현을 세 가지 찾았는가","시간 표현을 써서 차례대로 간추렸는가","사건이 이어지게 썼는가"]},"explanation":["시간 표현은 일의 차례를 알려 줘요.","그해 봄 → 한 달 동안 → 이듬달 첫날이에요.","차례를 지키면 흐름이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#1','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',1,'mc','auto','같은 작품을 서로 다르게 읽었을 때 좋은 읽기인지 가리는 기준은 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"같은 작품을 서로 다르게 읽었을 때 좋은 읽기인지 가리는 기준은 어느 것인가요?","options":[{"t":"작품에서 근거를 들었는가","correct":true},{"t":"작가와 똑같이 읽었는가","mis":"K6-2-u1-X06"},{"t":"더 많은 친구가 그렇게 읽었는가","mis":"K6-2-u1-X06"},{"t":"더 길게 말했는가","mis":"K6-2-u1-X06"}],"explanation":["작품의 주제는 한 사람의 답으로 정해지지 않아요.","맞고 틀림이 아니라 근거가 있고 없음이에요.","근거가 있으면 서로 달라도 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#2','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C2',1,'mc','auto','「연필」 1연에서 두 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「연필」 1연에서 두 번 나온 말은 어느 것인가요?","options":[{"t":"짧아","correct":true},{"t":"깎을","mis":"K6-2-u1-X03"},{"t":"글씨","mis":"K6-2-u1-X03"},{"t":"길어","mis":"K6-2-u1-X03"}],"explanation":["「짧아진다 / 짧아질수록」에 「짧아」가 두 번 나와요.","「짧아」와 「길어」가 맞서 있어요.","되풀이와 맞섬이 시의 뜻을 가리켜요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#3','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 이야기가 마무리되는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 이야기가 마무리되는 부분은 어느 것인가요?","options":[{"t":"결말","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#4','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',1,'ox','auto','사건을 많이 적을수록 잘 간추린 줄거리예요.',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"사건을 많이 적을수록 잘 간추린 줄거리예요.","answer":"X","reason_options":[{"t":"사건이 이어지게 적는 것이 잘 간추린 것이기 때문에","correct":true},{"t":"빠진 사건이 하나도 없어야 하기 때문에","mis":"K6-2-u1-X10"}],"mis":"K6-2-u1-X10","explanation":["사건을 많이 적는 것이 잘 간추린 것이 아니에요.","사건이 이어지게 적어야 해요.","무슨 일이 왜 일어났는지 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#5','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C8',1,'mc','auto','작품 소개하는 글의 「끝」에 넣을 내용은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작품 소개하는 글의 「끝」에 넣을 내용은 어느 것인가요?","options":[{"t":"읽고 난 내 생각과 권하고 싶은 사람","correct":true},{"t":"작품 제목과 작가","mis":"K6-2-u1-X11"},{"t":"간추린 줄거리","mis":"K6-2-u1-X11"},{"t":"책값","mis":"K6-2-u1-X13"}],"explanation":["처음 — 제목·작가·고른 까닭이에요.","가운데 — 줄거리와 의도예요.","끝 — 내 생각과 권할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#6','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C9',1,'mc','auto','「버스를 타다」의 「타다」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「버스를 타다」의 「타다」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"기차를 타고 할머니 댁에 갔다","correct":true},{"t":"장작이 활활 타다","mis":"K6-2-u1-X15"},{"t":"설탕을 물에 타다","mis":"K6-2-u1-X15"},{"t":"글짓기 대회에서 상을 타다","mis":"K6-2-u1-X15"}],"explanation":["「버스를 타다」는 탈것에 오른다는 뜻이에요.","「기차를 타다」도 같은 뜻이에요.","「타다」는 불이 붙다·섞다·받다라는 뜻도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#7','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C7',1,'mc','auto','「여름내」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「여름내」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"여름 한철 동안 내내","correct":true},{"t":"여름이 끝날 때","mis":"K6-2-u1-X15"},{"t":"여름의 첫날","mis":"K6-2-u1-X15"},{"t":"여름에 나는 냄새","mis":"K6-2-u1-X15"}],"explanation":["「여름내 할머니의 걸음은 느려졌다」에 나와요.","「-내」는 「그 동안 내내」라는 뜻을 더해요.","시간을 나타내는 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#8','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C3',1,'ox','auto','작가가 어떤 삶을 살았는지 알면 작품의 말이 다시 보이기도 해요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가가 어떤 삶을 살았는지 알면 작품의 말이 다시 보이기도 해요.","answer":"O","reason_options":[{"t":"그냥 지나쳤던 말이 작가의 삶과 이어져 새로 보이기 때문에","correct":true},{"t":"작가의 삶이 곧 작품의 정답이기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["「또 한 사람」, 「노 젓던 저 물길」도 그냥 나온 말이 아니었어요.","작가의 삶이 말을 다시 보게 해요.","그래도 근거는 작품 안에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#9','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C2',2,'mc','auto','「연필」 1연에서 「짧아진다」와 「길어진다」를 나란히 놓아 드러내는 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「연필」 1연에서 「짧아진다」와 「길어진다」를 나란히 놓아 드러내는 것은 어느 것인가요?","options":[{"t":"연필이 줄어드는 만큼 글이 늘어난다는 것","correct":true},{"t":"연필과 글씨의 길이는 상관없다는 것","mis":"K6-2-u1-X03"},{"t":"연필을 깎으면 안 된다는 것","mis":"K6-2-u1-X08"},{"t":"글씨를 크게 써야 한다는 것","mis":"K6-2-u1-X08"}],"explanation":["연필은 깎을수록 짧아져요.","그럴수록 글씨는 길어져요.","맞서는 두 말을 나란히 놓아 뜻을 또렷이 해요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#10','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C4',2,'mc','auto','「연필」 3연에서 다 닳은 연필은 무엇을 나타낸다고 볼 수 있나요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「연필」 3연에서 다 닳은 연필은 무엇을 나타낸다고 볼 수 있나요?","options":[{"t":"나와 함께 시간을 보내며 자기를 내어 준 소중한 것","correct":true},{"t":"새로 사야 할 물건","mis":"K6-2-u1-X08"},{"t":"쓸모없어 귀찮은 것","mis":"K6-2-u1-X08"},{"t":"필통을 채우는 장식","mis":"K6-2-u1-X08"}],"explanation":["연필은 손안에서 작아지며 공책을 두껍게 했어요.","다 닳았는데도 버리지 못하고 맨 앞에 둬요.","함께한 시간과 고마움이 담긴 것으로 읽을 수 있어요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#11','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',2,'mc','auto','「연필」을 읽고 짐작한 것 가운데 시에서 근거를 들 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X02','K6-2-u1-X06']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「연필」을 읽고 짐작한 것 가운데 시에서 근거를 들 수 있는 것은 어느 것인가요?","options":[{"t":"「연필은 손안에서 작아진다」고 했으니 자기를 내어 주는 것에 대한 시 같아","correct":true},{"t":"작가가 선생님이니 공부를 열심히 하라는 시야. 끝.","mis":"K6-2-u1-X04"},{"t":"연필 값이 비싸니 아껴 쓰자는 시야","mis":"K6-2-u1-X02"},{"t":"그냥 슬픈 시야","mis":"K6-2-u1-X06"}],"explanation":["짐작은 시에 적힌 말에서 근거를 찾아요.","「작아진다」와 「두꺼워지고」가 맞서 있어요.","시에 없는 내용이나 근거 없는 느낌은 짐작이 되지 못해요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#12','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「종을 잃은 마을」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「종을 잃은 마을」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"종소리로 하루를 맞추던 마을"},{"l":"전개","r":"금 간 종과 미룬 어른들, 어긋난 마을"},{"l":"절정","r":"나무람 속에서도 열이레 동안 두드린 나무판"},{"l":"결말","r":"다시 모인 사람들과 이듬해 봄의 새 종"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#13','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',2,'mc','auto','「사흘 걸린 다리」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「사흘 걸린 다리」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"징검돌이 떠내려가 할머니가 먼 길을 돌자 태건이 혼자 돌을 옮겼고, 쌓은 돌이 무너진 날 아저씨가 거들러 온 것을 시작으로 어른들이 함께 다리를 다시 놓았다","correct":true},{"t":"돌. 비. 아저씨. 다리.","mis":"K6-2-u1-X10"},{"t":"태건은 할머니를 무척 사랑한다.","mis":"K6-2-u1-X11"},{"t":"할머니는 여덟 번째 돌에서 늘 멈추었다.","mis":"K6-2-u1-X09"}],"explanation":["중요한 사건이 차례대로 이어져요.","까닭(떠내려가 · 무너진 날)이 드러나요.","한 장면만 적거나 느낌만 적으면 줄거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#14','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 마지막 버스가 다시 다니기 시작한 때는 언제인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 마지막 버스가 다시 다니기 시작한 때는 언제인가요?","options":[{"t":"이듬달 첫날","correct":true},{"t":"그해 봄","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"},{"t":"해 지기 전","mis":"K6-2-u1-X16"}],"explanation":["「이듬달 첫날, 마지막 버스가 다시 다니기 시작했다.」","이듬달은 그다음 달이에요.","시간 표현이 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["공책을 본 어른들이 하나둘 편지에 이름을 적었다.","이듬달 첫날, 마지막 버스가 다시 다니기 시작했다.","그날 봉식 아저씨는 정류장마다 경적을 두 번 울렸다."],"title":"「마지막 버스」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#15','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C7',2,'mc','auto','마지막 버스가 다시 다니던 날 봉식 아저씨가 경적을 두 번 울린 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"마지막 버스가 다시 다니던 날 봉식 아저씨가 경적을 두 번 울린 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 버스를 다시 몰게 되어 기쁘고 고마운 마음","correct":true},{"t":"사람들에게 화가 난 마음","mis":"K6-2-u1-X12"},{"t":"운전이 서툴러 실수한 마음","mis":"K6-2-u1-X12"},{"t":"버스가 고장 나 걱정되는 마음","mis":"K6-2-u1-X12"}],"explanation":["처음에는 경적을 한 번 더 울렸어요.","다시 다니게 된 날에는 두 번 울렸어요.","처음 장면과 견주면 달라진 마음이 보여요."],"asset":{"type":"passage","lines":["공책을 본 어른들이 하나둘 편지에 이름을 적었다.","이듬달 첫날, 마지막 버스가 다시 다니기 시작했다.","그날 봉식 아저씨는 정류장마다 경적을 두 번 울렸다."],"title":"「마지막 버스」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#16','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C8',2,'mc','auto','「우산」을 소개하는 글의 「가운데」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X14']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「우산」을 소개하는 글의 「가운데」로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 오면 남을 덮고 그동안 자기 어깨는 젖는 우산을 그린 시입니다. 「덮는다」가 처음과 끝에 되풀이되는 것으로 보아, 티 나지 않게 남을 돕는 마음을 전하려 한 것 같습니다.","correct":true},{"t":"우산은 빨간색이 예쁩니다.","mis":"K6-2-u1-X13"},{"t":"누리집에서 찾은 작가 소개를 그대로 붙였습니다.","mis":"K6-2-u1-X14"},{"t":"최고의 시! 별 다섯!","mis":"K6-2-u1-X13"}],"explanation":["가운데에는 시의 내용과 짐작한 의도가 들어가요.","「되풀이되는 것으로 보아」처럼 근거를 밝혀요.","겉모습·통째 옮기기·광고는 가운데가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#17','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C3',3,'mc','auto','「우산」은 「돌아오는 길」을 쓴 문해원의 시예요. 문해원은 어릴 때 이사를 자주 다녔고 어른이 되어 같은 골목을 날마다 걸었어요. 이것을 실마리로 「우산」을 읽을 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"「우산」은 「돌아오는 길」을 쓴 문해원의 시예요. 문해원은 어릴 때 이사를 자주 다녔고 어른이 되어 같은 골목을 날마다 걸었어요. 이것을 실마리로 「우산」을 읽을 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"작가의 삶을 실마리로 삼되, 「덮는다」·「젖는다」 같은 시의 말에서 근거를 찾는다","correct":true},{"t":"이사를 다닌 작가이니 이 시도 이사 이야기라고 정한다","mis":"K6-2-u1-X04"},{"t":"「우산」은 작가의 삶과 상관없으니 작가는 생각하지 않는다","mis":"K6-2-u1-X05"},{"t":"「돌아오는 길」과 같은 뜻이라고 그대로 옮겨 쓴다","mis":"K6-2-u1-X04"}],"explanation":["같은 작가라도 작품마다 담은 뜻은 달라요.","작가의 삶은 실마리로 쓰고","근거는 그 작품의 말에서 찾아요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#18','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',3,'error','auto','「우산」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「우산」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지호 — 「시에 ‘부모님’이라는 말이 안 나오니 부모님 이야기로 읽으면 틀려.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"서호 — 「남을 덮느라 자기는 젖으니 부모님 이야기로도 읽혀.」","mis":"K6-2-u1-X06"},{"t":"수아 — 「구석에서 마른다는 게 티 나지 않게 돕는 사람 같아.」","mis":"K6-2-u1-X06"}],"explanation":["시에 그 낱말이 없어도 근거가 있으면 그렇게 읽을 수 있어요.","서호와 수아는 시구를 근거로 댔어요.","지호는 근거 있는 다른 읽기를 틀렸다고 했어요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#19','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',3,'blank','auto','「징검돌이 떠내려가 할머니가 먼 길을 돌아다니자 (  ) 마을 어른들이 함께 다리를 다시 놓았다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X16','K6-2-u1-X11']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「징검돌이 떠내려가 할머니가 먼 길을 돌아다니자 (  ) 마을 어른들이 함께 다리를 다시 놓았다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"태건이 혼자 돌을 옮기기 시작했고, 쌓은 돌이 무너진 날 아저씨가 거들러 오자","correct":true},{"t":"할머니가 여덟 번째 돌에서 멈추었고,","mis":"K6-2-u1-X09"},{"t":"큰비가 사흘 동안 내렸고,","mis":"K6-2-u1-X16"},{"t":"태건이 돌을 하나씩 세었고,","mis":"K6-2-u1-X11"}],"explanation":["빈칸에는 전개 뒤 절정의 사건이 들어가요.","「무너진 날 거들러 오자」가 결말과 이어져요.","앞부분의 일이나 덜 중요한 일은 흐름을 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#20','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',3,'error','auto','「사흘 걸린 다리」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「사흘 걸린 다리」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「발단은 할머니가 새 다리를 건너는 곳이야.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"서호 — 「쌓은 돌이 무너진 날이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"지호 — 「징검돌이 떠내려간 곳부터 전개야.」","mis":"K6-2-u1-X06"}],"explanation":["할머니가 새 다리를 건너는 곳은 결말이에요.","발단은 징검다리를 건너다니던 처음 모습이에요.","서호와 지호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#21','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C9',3,'match','auto','「타다」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「타다」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"버스를 타다","r":"탈것에 오르다"},{"l":"장작이 타다","r":"불이 붙어 번지다"},{"l":"설탕을 물에 타다","r":"다른 것에 넣어 섞다"},{"l":"상을 타다","r":"주는 것을 받다"}],"mis":"K6-2-u1-X15","explanation":["「타다」에는 여러 뜻이 있어요.","함께 쓰인 말이 어느 뜻인지 알려 줘요.","낱말만 보면 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#22','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C8',3,'error','auto','작가를 알아보고 소개하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X14','K6-2-u1-X13']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작가를 알아보고 소개하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「작가 소개는 누리집 글을 그대로 붙이면 돼.」","correct":true,"mis_target":"K6-2-u1-X14"},{"t":"서호 — 「작가가 쓴 다른 작품 제목도 찾아 적어.」","mis":"K6-2-u1-X13"},{"t":"지호 — 「알아본 것을 바탕으로 작품을 쓴 의도를 짐작해 적어.」","mis":"K6-2-u1-X13"}],"explanation":["찾은 글은 간추려 내 말로 쓰고 출처를 적어요.","그대로 붙이면 남의 글을 내 것처럼 내놓는 일이 돼요.","서호와 지호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#23','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',4,'mc','auto','「종을 잃은 마을」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「종을 잃은 마을」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"종에 금이 가고 새 종 만들기를 미루는 사이 마을이 어긋났고, 할아버지마저 앓아눕자 늘봄이 나무판으로 새벽을 알렸다. 나무람을 듣고도 열이레 동안 두드린 소리에 사람들이 다시 모였고, 이듬해 봄 새 종이 걸렸다.","correct":true},{"t":"종이 있었다. 겨울이었다. 나무판이 있었다. 봄이 왔다.","mis":"K6-2-u1-X10"},{"t":"늘봄은 용감하다. 정말 감동적이다.","mis":"K6-2-u1-X11"},{"t":"늘봄은 종소리를 좋아해 하나, 둘, 셋을 세었다. 셋까지 세면 두 번째 소리가 울렸다.","mis":"K6-2-u1-X09"}],"explanation":["네 부분의 중요한 사건이 두 문장에 이어져 있어요.","까닭(미루는 사이 · 앓아눕자 · 그 소리에)이 드러나요.","늘어놓기·느낌·발단만 쓰기는 간추린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#24','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C3',4,'essay','teacher','정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 실마리로 「연필」에 담긴 작가의 의도를 짐작하고, 시에서 근거가 되는 시구를 두 가지 들어 쓰세요. 작가의 삶만으로 짐작하지 않고 시로 돌아와 확인한 점이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C3","difficulty":4,"kind":"essay","stem":"정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 실마리로 「연필」에 담긴 작가의 의도를 짐작하고, 시에서 근거가 되는 시구를 두 가지 들어 쓰세요. 작가의 삶만으로 짐작하지 않고 시로 돌아와 확인한 점이 드러나게 쓰세요.","answer_guide":{"answer":"예: 어려운 때를 함께해 준 작은 것을 소중히 여기는 마음을 전하려 한 것 같다. 작가가 연필 한 자루를 오래 아껴 썼다는 것을 알고 나니, 「다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다」가 그냥 나온 말이 아니라고 생각되었다. 시로 돌아와 보면 「연필은 / 손안에서 작아진다」와 「공책은 두꺼워지고」가 맞서 있어, 연필이 자기를 내어 주어 내 글이 자랐다는 고마움이 드러난다.","scoring_points":["의도를 짐작했는가","작가의 삶을 실마리로 썼는가","시구 두 가지로 다시 확인했는가"]},"explanation":["삶은 실마리예요.","근거는 시구에서 찾아요.","두 가지가 같은 쪽을 가리키면 짐작이 단단해요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#25','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',4,'essay','teacher','「우산」을 읽은 두 친구의 생각이에요. 예강 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」 슬찬 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」 두 읽기가 각각 시의 어느 구절을 근거로 했는지 쓰고, 두 읽기를 어떻게 평가하면 좋을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"「우산」을 읽은 두 친구의 생각이에요. 예강 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」 슬찬 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」 두 읽기가 각각 시의 어느 구절을 근거로 했는지 쓰고, 두 읽기를 어떻게 평가하면 좋을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 예강은 「너는 남을 덮는다」와 「네 어깨는 젖는다」를, 슬찬은 「접힌 채로 구석에서 마른다」를 근거로 했다. 두 사람은 서로 다르게 읽었지만 둘 다 시에서 근거를 들었으므로 둘 다 좋은 읽기이다. 작품의 주제는 한 사람의 답으로 정해지지 않으니, 서로의 근거를 물으며 나누면 시를 더 넓게 읽을 수 있다.","scoring_points":["두 친구의 근거 구절을 바르게 찾았는가","둘 다 근거가 있어 좋은 읽기라고 평가했는가","서로 다른 읽기를 나누는 태도를 썼는가"]},"explanation":["예강 — 덮는다·젖는다, 슬찬 — 구석에서 마른다예요.","근거가 있으면 둘 다 좋은 읽기예요.","서로 근거를 물으면 작품이 넓어져요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#1','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C1',1,'mc','auto','작품을 감상할 때 할 일이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작품을 감상할 때 할 일이 아닌 것은 어느 것인가요?","options":[{"t":"작품 속 두 생각 가운데 누가 옳은지 가려 내 결론을 말하기","correct":true},{"t":"되풀이한 표현 찾기","mis":"K6-2-u1-X03"},{"t":"작가의 삶 알아보기","mis":"K6-2-u1-X05"},{"t":"근거를 들어 의도 짐작하기","mis":"K6-2-u1-X06"}],"explanation":["감상은 작가가 무엇을 전하려 했는지 짐작하는 일이에요.","누가 옳은지 겨루면 내 결론을 말하게 돼요.","표현·작가의 삶·근거가 감상의 도구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#2','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C2',1,'mc','auto','「돌아오는 길」 3연과 4연에 모두 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「돌아오는 길」 3연과 4연에 모두 나온 말은 어느 것인가요?","options":[{"t":"길","correct":true},{"t":"발자국","mis":"K6-2-u1-X03"},{"t":"담","mis":"K6-2-u1-X03"},{"t":"주머니","mis":"K6-2-u1-X03"}],"explanation":["3연 「발자국이 길이 된다」, 4연 「길을 내려고 걷는다」예요.","「길」은 제목에도 있어요.","되풀이된 낱말이 시의 뼈대예요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#3','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 이야기가 시작되는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 이야기가 시작되는 부분은 어느 것인가요?","options":[{"t":"발단","correct":true},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#4','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',1,'ox','auto','줄거리를 간추린 뒤에는 이어 읽어 보고 말이 되는지 확인해요.',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추린 뒤에는 이어 읽어 보고 말이 되는지 확인해요.","answer":"O","reason_options":[{"t":"사건이 서로 이어지는지 확인해야 하기 때문에","correct":true},{"t":"맞춤법만 확인하면 되기 때문에","mis":"K6-2-u1-X10"}],"mis":"K6-2-u1-X10","explanation":["간추리기의 마지막 단계예요.","네 문장을 이어 읽어 봐요.","말이 되지 않으면 이음말을 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#5','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C8',1,'mc','auto','「소개는 광고가 아니다」라는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"「소개는 광고가 아니다」라는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"재미있다는 말보다 작품이 어떤 작품인지 알려 주어야 한다","correct":true},{"t":"작품을 소개하면 안 된다","mis":"K6-2-u1-X13"},{"t":"재미있다는 말을 길게 써야 한다","mis":"K6-2-u1-X13"},{"t":"결말을 꼭 밝혀야 한다","mis":"K6-2-u1-X11"}],"explanation":["광고 같은 말로는 작품을 알 수 없어요.","재미있었다는 말은 한 줄이면 돼요.","나머지는 작품이 어떤 작품인지로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#6','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C9',1,'mc','auto','「배가 아프다」의 「배」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「배가 아프다」의 「배」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"밥을 많이 먹어 배가 부르다","correct":true},{"t":"배를 타고 섬에 갔다","mis":"K6-2-u1-X15"},{"t":"배가 달고 시원하다","mis":"K6-2-u1-X15"},{"t":"키가 두 배로 자랐다","mis":"K6-2-u1-X15"}],"explanation":["「배가 아프다」의 배는 몸의 한 부분이에요.","「배가 부르다」도 같은 뜻이에요.","탈것·과일·곱절의 「배」와는 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#7','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',1,'mc','auto','「나루」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「나루」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"강에서 배가 사람을 태우고 건너다니는 곳","correct":true},{"t":"강을 건너는 다리","mis":"K6-2-u1-X15"},{"t":"배를 만드는 곳","mis":"K6-2-u1-X15"},{"t":"강물의 깊이","mis":"K6-2-u1-X15"}],"explanation":["「나루에서 배를 타고 강을 건넜습니다.」","나루는 배가 닿고 떠나는 곳이에요.","다리가 놓이면 나루가 없어질 참이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#8','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶은 작품과 상관없으니 알아볼 필요가 없어요.',ARRAY['K6-2-u1-X05']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶은 작품과 상관없으니 알아볼 필요가 없어요.","answer":"X","reason_options":[{"t":"작가의 삶은 작품을 다시 보게 하는 실마리이기 때문에","correct":true},{"t":"작품만 읽으면 언제나 다 알 수 있기 때문에","mis":"K6-2-u1-X05"}],"mis":"K6-2-u1-X05","explanation":["작가를 아는 것과 작품을 읽는 것은 둘 다 필요해요.","둘 가운데 하나만 쓰면 감상이 얕아져요.","작가의 삶은 좋은 실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#9','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C2',2,'mc','auto','「나루를 지켜」의 「어디로 가겠는가」를 묻는 꼴로 쓴 효과로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X17']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「나루를 지켜」의 「어디로 가겠는가」를 묻는 꼴로 쓴 효과로 알맞은 것은 어느 것인가요?","options":[{"t":"「사라지지 않는다」는 뜻을 더 세게 드러낸다","correct":true},{"t":"물길이 어디로 가는지 정말 궁금하다는 뜻이다","mis":"K6-2-u1-X03"},{"t":"답을 몰라 읽는 사람에게 묻는 것이다","mis":"K6-2-u1-X03"},{"t":"시조의 글자 수를 줄이려는 것이다","mis":"K6-2-u1-X17"}],"explanation":["답을 바라는 물음이 아니에요.","「어디로 가겠는가 = 어디로도 가지 않는다」예요.","묻는 꼴로 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#10','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C4',2,'mc','auto','「창문」의 「같은 유리 / 같은 자리에 서 있는데 / 보이는 것이 바뀐다」가 생각하게 하는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「창문」의 「같은 유리 / 같은 자리에 서 있는데 / 보이는 것이 바뀐다」가 생각하게 하는 것은 어느 것인가요?","options":[{"t":"같은 것도 때와 마음에 따라 다르게 보인다는 것","correct":true},{"t":"유리를 자주 닦아야 한다는 것","mis":"K6-2-u1-X08"},{"t":"밤에는 창문을 닫아야 한다는 것","mis":"K6-2-u1-X08"},{"t":"창문이 깨졌다는 것","mis":"K6-2-u1-X02"}],"explanation":["창문은 그대로예요.","낮에는 밖이, 밤에는 내가 보여요.","같은 것이 다르게 보이는 데에서 생각이 열려요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#11','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C1',2,'mc','auto','「돌아오는 길」을 읽고 근거를 들어 의도를 짐작한 말은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06','K6-2-u1-X08']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「돌아오는 길」을 읽고 근거를 들어 의도를 짐작한 말은 어느 것인가요?","options":[{"t":"「길을 내려고 걷는다」를 보면 앞으로 나아가려는 다짐을 전하려 한 것 같아","correct":true},{"t":"작가가 이사를 다녔으니 이사에 대한 시야. 끝.","mis":"K6-2-u1-X04"},{"t":"왠지 모르게 쓸쓸해","mis":"K6-2-u1-X06"},{"t":"걷기 운동을 하자는 시야","mis":"K6-2-u1-X08"}],"explanation":["짐작 + 근거가 한 묶음이에요.","마지막 연의 시구가 근거예요.","작가의 삶만이나 느낌만으로는 부족해요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#12','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「사흘 걸린 다리」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「사흘 걸린 다리」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"돌 열두 개를 세며 건너던 징검다리"},{"l":"전개","r":"떠내려간 돌과 한 시간 돌아가는 길"},{"l":"절정","r":"흩어진 돌 앞에 주저앉은 날 찾아온 아저씨"},{"l":"결말","r":"열네 개 돌로 다시 놓인 다리"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#13','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',2,'mc','auto','「종을 잃은 마을」을 한 문장으로 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X02']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」을 한 문장으로 잘 간추린 것은 어느 것인가요?","options":[{"t":"종이 깨져 마을이 어긋나자 늘봄이 나무판으로 새벽을 알렸고, 그 소리에 다시 모인 사람들이 새 종을 걸었다","correct":true},{"t":"종, 겨울, 나무판, 봄.","mis":"K6-2-u1-X10"},{"t":"늘봄은 이불 속에서 하나, 둘, 셋을 세었다.","mis":"K6-2-u1-X11"},{"t":"새 종은 아주 비쌌다.","mis":"K6-2-u1-X02"}],"explanation":["중요한 사건 셋이 이어져요.","「~자 ~했고, 그 소리에」가 흐름을 이어요.","낱말만 늘어놓거나 덜 중요한 장면만 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#14','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 하은이 사람 수를 적은 기간은 얼마 동안인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 하은이 사람 수를 적은 기간은 얼마 동안인가요?","options":[{"t":"한 달 동안","correct":true},{"t":"하루 세 번","mis":"K6-2-u1-X16"},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"그해 봄 하루","mis":"K6-2-u1-X16"}],"explanation":["「한 달 동안 하루도 빼지 않고 적었다.」","오랫동안 꾸준히 했음을 알려 줘요.","시간 표현은 인물의 끈기도 보여 줘요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#15','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',2,'mc','auto','나무람을 듣고 얼굴이 뜨거워져 내려온 늘봄의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"나무람을 듣고 얼굴이 뜨거워져 내려온 늘봄의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"부끄럽고 속상한 마음","correct":true},{"t":"자랑스러운 마음","mis":"K6-2-u1-X12"},{"t":"졸린 마음","mis":"K6-2-u1-X12"},{"t":"배고픈 마음","mis":"K6-2-u1-X12"}],"explanation":["「그게 무슨 종소리냐.」 하는 나무람을 들었어요.","잠을 깨운다고 화내는 집도 있었어요.","얼굴이 뜨거워진 것은 부끄럽고 속상해서예요."],"asset":{"type":"passage","lines":["가을 끝 무렵 덕곤 할아버지가 앓아누웠다.","그날 새벽 늘봄은 언덕에 올라 나무판을 두드렸다. 딱, 딱, 딱.","「그게 무슨 종소리냐.」 아랫집 어른이 나와 나무랐다.","늘봄은 얼굴이 뜨거워져 내려왔지만 이튿날 또 올라갔다.","손바닥이 부르터도 열이레 동안 새벽마다 두드렸다."],"title":"「종을 잃은 마을」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#16','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C8',2,'mc','auto','「연필」을 소개하는 글의 「끝」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「연필」을 소개하는 글의 「끝」으로 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓴 물건을 쉽게 버리는 친구에게 권하고 싶습니다. 「필통 맨 앞에 둔다」에서 저도 오래 쓴 물건이 떠올랐습니다.","correct":true},{"t":"끝. 다음에는 다른 시를 소개하겠습니다.","mis":"K6-2-u1-X11"},{"t":"연필은 문방구에서 삽니다.","mis":"K6-2-u1-X13"},{"t":"이 시는 세 연이고 제목은 두 글자입니다.","mis":"K6-2-u1-X13"}],"explanation":["끝에는 내 생각과 권할 사람을 써요.","내 생각에도 시구를 근거로 들면 좋아요.","작품과 상관없는 말은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#17','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C3',3,'mc','auto','한도경은 물에 막혀 학교에 가지 못하는 아이들을 보아 왔어요. 이것을 알고 「그 길로 또 한 사람 건너오면 이웃이라」를 다시 읽었을 때 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"한도경은 물에 막혀 학교에 가지 못하는 아이들을 보아 왔어요. 이것을 알고 「그 길로 또 한 사람 건너오면 이웃이라」를 다시 읽었을 때 알맞은 짐작은 어느 것인가요?","options":[{"t":"길이 이어져 사람과 사람이 만나기를 바라는 마음","correct":true},{"t":"다리 공사로 돈을 벌고 싶은 마음","mis":"K6-2-u1-X04"},{"t":"강 건너 사람이 못 오게 막고 싶은 마음","mis":"K6-2-u1-X08"},{"t":"아이들에게 헤엄을 가르치자는 마음","mis":"K6-2-u1-X08"}],"explanation":["작가는 길이 이어지면 사람도 이어진다고 생각했어요.","「건너오면 이웃이라」가 그 생각과 맞닿아요.","삶과 시구가 함께 가리키는 짐작이 단단해요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#18','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',3,'error','auto','시조 두 편을 읽고 친구들이 말했어요. 감상이 아닌 말을 한 친구는 누구인가요?',ARRAY['K6-2-u1-X07','K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C7","difficulty":3,"kind":"error","stem":"시조 두 편을 읽고 친구들이 말했어요. 감상이 아닌 말을 한 친구는 누구인가요?","options":[{"t":"서아 — 「다리를 놓는 게 당연히 옳으니 ‘같이 건너세’가 더 좋은 시조야.」","correct":true,"mis_target":"K6-2-u1-X07"},{"t":"가온 — 「‘백 번’을 되풀이한 걸 보면 나루를 지키려는 마음이 강해.」","mis":"K6-2-u1-X06"},{"t":"나린 — 「‘한 마을로 살리라’를 보면 두 마을이 이어지길 바랐어.」","mis":"K6-2-u1-X06"}],"explanation":["감상은 각 작가가 무엇을 전하려 했는지 짐작하는 일이에요.","가온과 나린은 표현을 근거로 의도를 짐작했어요.","서아는 작품이 아니라 내 결론을 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#19','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',3,'blank','auto','「종이 깨져 (  ) 늘봄이 나무판을 두드려 새벽을 알렸다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X16','K6-2-u1-X11']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「종이 깨져 (  ) 늘봄이 나무판을 두드려 새벽을 알렸다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"마을이 어긋나고 덕곤 할아버지마저 앓아눕자","correct":true},{"t":"새 종이 걸리자","mis":"K6-2-u1-X16"},{"t":"사람들이 모두 모이자","mis":"K6-2-u1-X16"},{"t":"늘봄이 셋을 세자","mis":"K6-2-u1-X11"}],"explanation":["빈칸은 전개와 절정 사이예요.","할아버지마저 앓아누워 아무도 언덕에 오르지 못하게 되었어요.","새 종·사람들이 모임은 결말의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#20','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C5',3,'error','auto','「종을 잃은 마을」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「종을 잃은 마을」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「결말은 종에 금이 간 곳이야.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"가온 — 「늘봄이 나무람을 듣고도 다시 올라간 곳이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"나린 — 「새 종이 걸린 곳이 결말이야.」","mis":"K6-2-u1-X06"}],"explanation":["종에 금이 간 것은 전개의 사건이에요.","결말은 새 종이 걸린 곳이에요.","가온과 나린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#21','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C9',3,'match','auto','「배」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「배」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"배가 고프다","r":"사람 몸의 한 부분"},{"l":"배를 타고 섬에 가다","r":"물 위로 다니는 탈것"},{"l":"배를 깎아 먹다","r":"물이 많고 단 과일"},{"l":"두 배로 늘다","r":"같은 수를 거듭 더한 만큼"}],"mis":"K6-2-u1-X15","explanation":["「배」는 글자는 같아도 뜻이 갈려요.","고프다·타다·깎다·늘다가 뜻을 정해요.","앞뒤 말을 꼭 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#22','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개에서 줄거리를 다루는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개에서 줄거리를 다루는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「결말을 다 말해 줘야 친절한 소개야.」","correct":true,"mis_target":"K6-2-u1-X11"},{"t":"가온 — 「재미있었다는 말은 한 줄이면 충분해.」","mis":"K6-2-u1-X13"},{"t":"나린 — 「권하고 싶은 사람을 끝에 써.」","mis":"K6-2-u1-X11"}],"explanation":["결말까지 다 말하면 읽는 즐거움을 빼앗아요.","줄거리는 간추려 소개해요.","가온과 나린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#23','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',4,'mc','auto','「사흘 걸린 다리」를 한 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X10','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「사흘 걸린 다리」를 한 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"징검다리가 떠내려가 할머니가 힘들어지자 태건이 혼자 돌을 옮기기 시작했고, 그 모습에 움직인 마을 사람들이 함께 다리를 다시 놓았다","correct":true},{"t":"태건이 다리를 놓았다.","mis":"K6-2-u1-X11"},{"t":"비가 오고, 돌이 떠내려가고, 돌을 옮기고, 비가 오고, 아저씨가 오고, 어른들이 오고, 다리를 놓았다.","mis":"K6-2-u1-X10"},{"t":"할머니는 여덟 번째 돌 앞에서 늘 멈추었다.","mis":"K6-2-u1-X09"}],"explanation":["한 문장이어도 흐름(문제 → 노력 → 함께 해결)이 보여야 해요.","너무 짧으면 뭉뚱그림, 쉼표로 늘어놓으면 나열이에요.","한 장면만 쓰면 줄거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#24','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',4,'essay','teacher','「마지막 버스」를 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지게 다시 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C6","difficulty":4,"kind":"essay","stem":"「마지막 버스」를 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지게 다시 써 보세요.","answer_guide":{"answer":"예: 발단 — 산골 마을에는 하루 세 번 읍내로 가는 버스가 다녔고, 봉식 아저씨는 마지막 버스 때 경적을 한 번 더 울렸다. 전개 — 그해 봄 회사가 마지막 버스를 없애자 하은과 마을 사람들이 불편해졌다. 절정 — 어른들이 소용없다고 해도 하은은 한 달 동안 기다리는 사람 수를 적고 같이 편지를 쓰자고 했다. 결말 — 공책을 본 어른들이 편지에 이름을 적었고, 이듬달 첫날 버스가 다시 다녀 아저씨는 경적을 두 번 울렸다.","scoring_points":["네 부분으로 나누었는가","부분마다 중요한 사건을 한 문장으로 골랐는가","사건이 까닭으로 이어지게 썼는가"]},"explanation":["부분마다 중요한 사건 하나씩이에요.","「~자」, 「그래도」로 이어요.","시간 표현으로 차례를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#25','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C4',4,'essay','teacher','「연필」의 시어 「짧아진다」·「길어진다」·「작아진다」·「두꺼워지고」를 두 묶음으로 나누고, 그렇게 나눈 까닭과 이 시어들이 함께 드러내는 뜻을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C4","difficulty":4,"kind":"essay","stem":"「연필」의 시어 「짧아진다」·「길어진다」·「작아진다」·「두꺼워지고」를 두 묶음으로 나누고, 그렇게 나눈 까닭과 이 시어들이 함께 드러내는 뜻을 쓰세요.","answer_guide":{"answer":"예: 「짧아진다」·「작아진다」는 연필 쪽, 「길어진다」·「두꺼워지고」는 글씨와 공책 쪽이다. 연필은 줄어드는데 내가 쓴 것은 늘어나서 서로 맞서기 때문이다. 이 시어들은 연필이 자기를 내어 주는 만큼 내 글과 공부가 자란다는 뜻을 함께 드러낸다.","scoring_points":["시어를 연필 쪽·글(공책) 쪽으로 나누었는가","줄어듦과 늘어남이 맞선다는 까닭을 썼는가","함께 드러내는 뜻을 짐작해 썼는가"]},"explanation":["줄어드는 말과 늘어나는 말로 나눠요.","두 묶음이 맞서요.","맞섬이 연필이 내어 준 것을 보여 줘요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#1','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C1',1,'mc','auto','「작가의 의도를 짐작한다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X06','K6-2-u1-X11']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"「작가의 의도를 짐작한다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품에 담긴 작가의 생각과 바람을 근거를 들어 미루어 생각하는 것","correct":true},{"t":"작가에게 직접 물어 정답을 듣는 것","mis":"K6-2-u1-X01"},{"t":"작가가 생각한 대로만 읽는 것","mis":"K6-2-u1-X06"},{"t":"작품의 줄거리를 외우는 것","mis":"K6-2-u1-X11"}],"explanation":["짐작은 근거를 들어 미루어 생각하는 거예요.","작가가 생각한 대로만 읽으라는 뜻이 아니에요.","내가 읽은 것과 견주며 근거를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#2','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C2',1,'mc','auto','시조 「나루를 지켜」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조 「나루를 지켜」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"백 번","correct":true},{"t":"물길","mis":"K6-2-u1-X03"},{"t":"한마음","mis":"K6-2-u1-X03"},{"t":"노 젓던","mis":"K6-2-u1-X03"}],"explanation":["「백 번 고쳐 백 번을 다시 매도」예요.","「백 번」이 두 번 나와요.","몇 번이라도 지키겠다는 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#3','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"발단 → 전개 → 절정 → 결말","correct":true},{"t":"발단 → 절정 → 전개 → 결말","mis":"K6-2-u1-X09"},{"t":"전개 → 발단 → 결말 → 절정","mis":"K6-2-u1-X09"},{"t":"결말 → 절정 → 전개 → 발단","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#4','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',1,'ox','auto','줄거리를 간추릴 때 「재미있었다」 같은 내 느낌을 꼭 넣어야 해요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추릴 때 「재미있었다」 같은 내 느낌을 꼭 넣어야 해요.","answer":"X","reason_options":[{"t":"줄거리는 사건의 흐름을 간추린 것이기 때문에","correct":true},{"t":"느낌이 없으면 줄거리가 아니기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["줄거리는 사건의 흐름이에요.","느낌은 소개하는 글의 끝에 써요.","줄거리에는 중요한 사건이 이어지게 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#5','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',1,'mc','auto','작가를 알아볼 때 찾은 글을 다루는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X14','K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작가를 알아볼 때 찾은 글을 다루는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두세 줄로 간추려 내 말로 쓰고 출처를 적는다","correct":true},{"t":"그대로 복사해 붙인다","mis":"K6-2-u1-X14"},{"t":"찾은 곳을 적지 않는다","mis":"K6-2-u1-X14"},{"t":"작가의 이름만 적는다","mis":"K6-2-u1-X11"}],"explanation":["찾은 글을 그대로 옮기지 않아요.","간추려 내 말로 써요.","어디에서 찾았는지 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#6','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C9',1,'mc','auto','「오래 걸어 다리가 아프다」의 「다리」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「오래 걸어 다리가 아프다」의 「다리」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"달리기를 했더니 다리가 저렸다","correct":true},{"t":"냇물에 다리를 놓았다","mis":"K6-2-u1-X15"},{"t":"다리를 건너 학교에 갔다","mis":"K6-2-u1-X15"},{"t":"다리 밑으로 강물이 흐른다","mis":"K6-2-u1-X15"}],"explanation":["「다리가 아프다」의 다리는 몸을 받치고 걷는 부분이에요.","「다리가 저리다」도 같은 뜻이에요.","건너다니는 「다리」와는 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#7','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C7',1,'mc','auto','「열이레 동안」은 며칠 동안인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「열이레 동안」은 며칠 동안인가요?","options":[{"t":"17일 동안","correct":true},{"t":"10일 동안","mis":"K6-2-u1-X15"},{"t":"12일 동안","mis":"K6-2-u1-X15"},{"t":"27일 동안","mis":"K6-2-u1-X15"}],"explanation":["「이레」는 7일이에요.","「열이레」는 10일 + 7일이에요.","늘봄은 17일 동안 새벽마다 나무판을 두드렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#8','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶을 알아본 뒤에는 다시 작품으로 돌아와 근거를 찾아요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶을 알아본 뒤에는 다시 작품으로 돌아와 근거를 찾아요.","answer":"O","reason_options":[{"t":"삶은 실마리이고 근거는 작품 안에 있기 때문에","correct":true},{"t":"작가의 삶을 알면 작품을 다시 읽지 않아도 되기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["실마리를 얻은 뒤에는 작품으로 돌아와요.","어떤 말이 되풀이되는지, 어떤 장면이 나오는지 확인해요.","그래야 짐작이 단단해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#9','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C2',2,'mc','auto','「창문」의 「밤마다」와 「오래」가 주는 느낌으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「창문」의 「밤마다」와 「오래」가 주는 느낌으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번이 아니라 날마다 되풀이되는 느낌","correct":true},{"t":"잠깐 스쳐 지나가는 느낌","mis":"K6-2-u1-X03"},{"t":"밝고 시끄러운 느낌","mis":"K6-2-u1-X08"},{"t":"창문이 새것이라는 느낌","mis":"K6-2-u1-X02"}],"explanation":["「밤마다」는 밤이 올 때마다예요.","「오래」는 짧지 않은 시간이에요.","창문 앞에 서는 일이 되풀이되는 느낌이 들어요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#10','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C4',2,'mc','auto','「돌아오는 길」에서 「길」이 품은 뜻으로 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「돌아오는 길」에서 「길」이 품은 뜻으로 볼 수 있는 것은 어느 것인가요?","options":[{"t":"걸어가는 길이면서 앞으로 살아갈 날들","correct":true},{"t":"자동차가 다니는 큰길","mis":"K6-2-u1-X08"},{"t":"학교에 가는 지름길","mis":"K6-2-u1-X08"},{"t":"길을 잃은 곳","mis":"K6-2-u1-X02"}],"explanation":["「길을 내려고 걷는다」의 길은 땅 위의 길만이 아니에요.","걸어온 발자국이 길이 된다고 했어요.","시어는 여러 뜻을 품어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#11','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C1',2,'mc','auto','「같이 건너세」를 읽고 근거가 있는 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X02','K6-2-u1-X04','K6-2-u1-X08']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「같이 건너세」를 읽고 근거가 있는 짐작은 어느 것인가요?","options":[{"t":"「한 마을로 살리라」로 끝맺은 것을 보면 두 마을이 하나 되기를 바란 것 같아","correct":true},{"t":"다리는 위험하니 놓지 말자는 뜻이야","mis":"K6-2-u1-X02"},{"t":"작가가 다리 놓는 사람이니 자기 일 자랑이야","mis":"K6-2-u1-X04"},{"t":"돌을 많이 모아 두자는 뜻이야","mis":"K6-2-u1-X08"}],"explanation":["힘주어 끝맺은 말은 좋은 근거예요.","「또 한」의 되풀이와 「이웃」도 같은 쪽을 가리켜요.","시조에 없는 내용은 근거가 되지 못해요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#12','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「마지막 버스」의 장면을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「마지막 버스」의 장면을 알맞게 이으세요.","pairs":[{"l":"발단","r":"읍내 가는 버스와 마지막 경적"},{"l":"전개","r":"그해 봄 없어진 마지막 버스"},{"l":"절정","r":"한 달 동안 적은 공책과 「같이 편지를 써 주세요」"},{"l":"결말","r":"다시 다니는 버스와 두 번 울린 경적"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#13','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',2,'mc','auto','「마지막 버스」 셋째 부분(절정)을 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「마지막 버스」 셋째 부분(절정)을 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어른들이 소용없다고 해도 하은은 한 달 동안 기다리는 사람 수를 적고 함께 편지를 쓰자고 했다","correct":true},{"t":"하은은 공책을 한 권 샀다.","mis":"K6-2-u1-X11"},{"t":"봉식 아저씨가 경적을 두 번 울렸다.","mis":"K6-2-u1-X09"},{"t":"버스 회사가 마지막 버스를 없앴다.","mis":"K6-2-u1-X09"}],"explanation":["절정은 갈등이 가장 두드러지는 곳이에요.","어른들의 반대에도 하은이 그만두지 않았어요.","다른 보기는 덜 중요하거나 다른 부분의 일이에요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#14','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에 나온 말 가운데 시간을 나타내는 표현이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에 나온 말 가운데 시간을 나타내는 표현이 아닌 것은 어느 것인가요?","options":[{"t":"정류장마다","correct":true},{"t":"그해 봄","mis":"K6-2-u1-X16"},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"}],"explanation":["「정류장마다」는 곳을 나타내요.","「그해 봄·이듬달 첫날·한 달 동안」은 때를 나타내요.","시간 표현에 동그라미하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#15','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C7',2,'mc','auto','「여름내 할머니의 걸음은 눈에 띄게 느려졌다」에서 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X12','K6-2-u1-X16','K6-2-u1-X02']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「여름내 할머니의 걸음은 눈에 띄게 느려졌다」에서 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"먼 길을 돌아다니느라 할머니가 지치고 힘들었다","correct":true},{"t":"할머니가 산책을 즐겼다","mis":"K6-2-u1-X12"},{"t":"징검다리가 다시 놓였다","mis":"K6-2-u1-X16"},{"t":"할머니가 밭일을 그만두었다","mis":"K6-2-u1-X02"}],"explanation":["징검돌이 떠내려가 한 시간을 돌아다녔어요.","그 일이 여름내 이어졌어요.","그래서 걸음이 느려졌다고 짐작할 수 있어요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#16','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',2,'mc','auto','친구의 작품 소개를 읽고 근거를 묻는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"친구의 작품 소개를 읽고 근거를 묻는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「의도를 그렇게 짐작한 근거가 된 구절은 어디야?」","correct":true},{"t":"「이 책 비싸?」","mis":"K6-2-u1-X13"},{"t":"「그림 많아?」","mis":"K6-2-u1-X13"},{"t":"「몇 쪽짜리야?」","mis":"K6-2-u1-X13"}],"explanation":["근거를 묻는 물음이 좋은 물음이에요.","묻는 사람도 답하는 사람도 작품을 다시 봐요.","값·그림·쪽수는 작품으로 돌아가게 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#17','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C3',3,'mc','auto','문해원이 어릴 때 낯선 골목을 혼자 걸었다는 것을 알고 「창문」을 다시 읽었어요. 알맞지 않은 읽기는 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"문해원이 어릴 때 낯선 골목을 혼자 걸었다는 것을 알고 「창문」을 다시 읽었어요. 알맞지 않은 읽기는 어느 것인가요?","options":[{"t":"작가가 외로웠으니 이 시는 외로움에 대한 시로 정해져 있다","correct":true},{"t":"「밤마다 … 오래 서 있는다」가 혼자 지낸 시간과 이어져 보인다","mis":"K6-2-u1-X06"},{"t":"「나를 보여 준다」에서 혼자 자신을 들여다보는 모습이 떠오른다","mis":"K6-2-u1-X06"},{"t":"작가의 삶을 알고 나니 같은 시가 조금 다르게 보인다","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 시를 다시 보게 해요.","하지만 뜻을 하나로 정해 주지는 않아요.","「정해져 있다」고 하면 다른 근거 있는 읽기를 막아요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#18','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C1',3,'error','auto','「돌아오는 길」을 읽고 친구들이 말했어요. 근거를 들지 않은 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「돌아오는 길」을 읽고 친구들이 말했어요. 근거를 들지 않은 친구는 누구인가요?","options":[{"t":"준희 — 「이 시는 그냥 슬퍼. 왜 그런지는 몰라도 돼.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"여울 — 「‘만져지는 것이 없다’를 보면 1연은 쓸쓸해.」","mis":"K6-2-u1-X06"},{"t":"라온 — 「‘남은 발자국이 길이 된다’를 보면 3연에서 마음이 놓여.」","mis":"K6-2-u1-X06"}],"explanation":["느낌도 근거가 있어야 나눌 수 있어요.","여울과 라온은 시구를 들었어요.","준희는 까닭을 말하지 않았어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#19','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',3,'blank','auto','「하은의 공책을 본 어른들이 편지에 이름을 적자 (  ).」 빈칸에 들어갈 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X16','K6-2-u1-X09']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「하은의 공책을 본 어른들이 편지에 이름을 적자 (  ).」 빈칸에 들어갈 말로 알맞은 것은 어느 것인가요?","options":[{"t":"이듬달 첫날 마지막 버스가 다시 다니기 시작했다","correct":true},{"t":"그해 봄 마지막 버스가 없어졌다","mis":"K6-2-u1-X16"},{"t":"하은은 한 시간을 걸어 돌아왔다","mis":"K6-2-u1-X16"},{"t":"봉식 아저씨가 경적을 한 번 더 울렸다","mis":"K6-2-u1-X09"}],"explanation":["결말의 사건이 들어가요.","「이듬달 첫날」이 차례를 알려 줘요.","앞부분의 일을 넣으면 차례가 뒤엉켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#20','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C5',3,'error','auto','이야기 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"이야기 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「절정은 언제나 이야기의 맨 마지막 문장이야.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"여울 — 「절정은 갈등이 가장 두드러지는 곳이야.」","mis":"K6-2-u1-X06"},{"t":"라온 — 「경계는 까닭을 말할 수 있으면 사람마다 조금 달라도 돼.」","mis":"K6-2-u1-X06"}],"explanation":["절정은 맨 끝이 아니라 결말 바로 앞에 오는 일이 많아요.","갈등이 가장 두드러지는 곳을 찾아요.","여울과 라온은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#21','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C9',3,'match','auto','「손」이 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「손」이 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"손을 깨끗이 씻다","r":"팔목 끝에 달린 몸의 부분"},{"l":"일손이 모자라 손이 부족하다","r":"일을 할 사람"},{"l":"손이 많이 가는 음식","r":"일에 드는 수고"}],"mis":"K6-2-u1-X15","explanation":["「손」은 몸의 부분만 뜻하지 않아요.","「손이 부족하다」는 사람이 모자라다는 뜻이에요.","「손이 많이 가다」는 수고가 든다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#22','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개 광고지를 만드는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개 광고지를 만드는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「‘대박·별 다섯’만 크게 쓰면 돼.」","correct":true,"mis_target":"K6-2-u1-X13"},{"t":"여울 — 「광고지에도 짐작한 의도를 한 줄 넣어.」","mis":"K6-2-u1-X13"},{"t":"라온 — 「인상 깊은 구절을 하나 골라 넣어.」","mis":"K6-2-u1-X13"}],"explanation":["광고지도 소개예요 — 담을 내용은 같아요.","작품이 어떤 작품인지 알 수 있어야 해요.","여울과 라온은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#23','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',4,'mc','auto','「마지막 버스」를 간추린 글 가운데 「뭉뚱그림」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「마지막 버스」를 간추린 글 가운데 「뭉뚱그림」에 해당하는 것은 어느 것인가요?","options":[{"t":"어떤 아이 덕분에 일이 잘 풀렸다.","correct":true},{"t":"버스가 있었다. 봄이 왔다. 공책을 썼다. 버스가 왔다.","mis":"K6-2-u1-X10"},{"t":"마지막 버스가 없어지자 하은이 사람 수를 적어 편지를 쓰자고 했고, 어른들이 함께해 버스가 다시 다녔다.","mis":"K6-2-u1-X11"},{"t":"산골 마을에서 읍내로 가는 버스는 하루 세 번 다녔다. 봉식 아저씨는…(처음부터 그대로)","mis":"K6-2-u1-X11"}],"explanation":["뭉뚱그림은 흐름만 말하고 사건을 고르지 않은 것이에요.","무엇이, 어떻게 풀렸는지 사건이 하나도 없어요.","늘어놓기는 나열, 처음부터 그대로는 통째 옮기기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#24','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',4,'essay','teacher','「마지막 버스」를 친구에게 소개하는 글을 처음·가운데·끝의 짜임으로 쓰세요. 가운데에는 간추린 줄거리와 짐작한 작가의 의도를 근거와 함께 넣으세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C8","difficulty":4,"kind":"essay","stem":"「마지막 버스」를 친구에게 소개하는 글을 처음·가운데·끝의 짜임으로 쓰세요. 가운데에는 간추린 줄거리와 짐작한 작가의 의도를 근거와 함께 넣으세요.","answer_guide":{"answer":"예: 처음 — 「마지막 버스」는 없어진 버스를 다시 다니게 한 아이의 이야기입니다. 저도 버스를 타고 다녀서 골랐습니다. 가운데 — 마지막 버스가 없어져 마을이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적었고, 그 공책을 본 어른들이 함께 편지를 써 버스가 다시 다니게 됩니다. 어른들이 고개를 저어도 하은이 그만두지 않은 장면으로 보아, 작은 기록과 끈기가 여럿의 마음을 움직인다는 것을 전하려 한 것 같습니다. 끝 — 무언가를 바꾸고 싶지만 혼자라 망설이는 친구에게 권하고 싶습니다.","scoring_points":["처음·가운데·끝의 짜임을 갖추었는가","가운데에 간추린 줄거리와 의도·근거를 넣었는가","고른 까닭과 권할 사람을 밝히고 광고처럼 쓰지 않았는가"]},"explanation":["처음 — 제목·고른 까닭이에요.","가운데 — 줄거리 + 의도와 근거예요.","끝 — 내 생각과 권할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#25','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C9',4,'essay','teacher','「쓰다」의 서로 다른 뜻 두 가지가 드러나게 짧은 문장을 하나씩 만들고, 글을 읽다가 여러 뜻을 지닌 낱말을 만났을 때 뜻을 가려 읽는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C9","difficulty":4,"kind":"essay","stem":"「쓰다」의 서로 다른 뜻 두 가지가 드러나게 짧은 문장을 하나씩 만들고, 글을 읽다가 여러 뜻을 지닌 낱말을 만났을 때 뜻을 가려 읽는 방법을 쓰세요.","answer_guide":{"answer":"예: 「동생에게 편지를 썼다.」(글씨로 적다) 「햇볕이 뜨거워 모자를 썼다.」(머리에 얹다) 여러 뜻을 지닌 낱말을 만나면 낱말만 보지 않고 함께 쓰인 말과 앞뒤 문장을 보아 그 문장이 무엇에 대한 말인지 따져 알맞은 뜻을 고른다.","scoring_points":["「쓰다」의 서로 다른 뜻 두 가지로 문장을 만들었는가","각 문장의 뜻을 바르게 밝혔는가","앞뒤 문장(함께 쓰인 말)으로 뜻을 가린다는 방법을 썼는가"]},"explanation":["함께 쓰인 말이 뜻을 정해요.","편지를 쓰다 · 모자를 쓰다 · 약이 쓰다 · 돈을 쓰다예요.","낱말만 보면 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C1','kor',6,2,'u2',2,'면담의 뜻과 특성 — 면담은 정보를 얻으려고 면담 대상자와 주고받는 대화이고, 정보·준비·예의가 함께 있어야 하며, 찾으면 나오는 것이 아니라 그분이 겪은 일과 생각처럼 면담이라야 들을 수 있는 것을 얻는다(일상 대화와 다름: 목적·차례·답하는 쪽이 더 많이 말함)',ARRAY['6국01 듣기·말하기(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C2','kor',6,2,'u2',2,'면담 요청하기와 물어서는 안 되는 것 — 직접·전화·전자 우편·누리집 등 어느 방법이든 먼저 허락을 구하고, 우리가 누구인지·목적·걸리는 시간·바라는 날짜와 장소를 밝혀 대상자의 사정에 맞추어 정하며, 사는 곳·나이·가족·버는 돈 같은 개인 정보와 곤란한 물음은 덜어 내기',ARRAY['6국01 듣기·말하기(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C3','kor',6,2,'u2',3,'면담의 절차 — 면담 준비하기(모둠·목적·대상자·방식·자료·질문·역할·요청과 허락, 목적이 맨 먼저) → 면담 진행하기(면담 열기·질문하기·면담 마무리하기) → 면담 정리하기(내용 정리·과정 성찰·보고서 쓰기), 면담은 들은 것을 쓸 수 있게 남길 때 끝남',ARRAY['6국01 듣기·말하기(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C4','kor',6,2,'u2',3,'질문 세 갈래와 목적에 맞는 질문 — 구체적인 사실·생각이나 느낌·앞으로의 계획이나 당부에 대한 질문을 골고루 만들고, 면담 목적과 이어지지 않는 질문은 덜어 내며, 미리 찾은 자료를 바탕으로 더 깊이 묻기',ARRAY['6국01 듣기·말하기(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C5','kor',6,2,'u2',5,'면담 자료 읽기와 후속 질문 — 면담 자료에서 열기·질문하기·마무리 단계를 짚어 읽고, 답을 끝까지 듣고 그 안의 말을 붙들어 더 자세히 알려고 이어서 묻는 후속 질문을 하기(질문지는 지도이지 대본이 아님)',ARRAY['6국01 듣기·말하기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C6','kor',6,2,'u2',5,'면담 예절과 질문 점검 — 인사·감사·목적 밝히기·동의 구하기, 말씀 도중에 끊지 않고 질문은 짧게, 고개를 끄덕이며 듣기, 만든 질문을 목적에 맞는가·예의를 갖추었는가·뜻이 분명한가로 점검하고, 자료는 누가·언제 만들었는지 밝혀진 믿을 만한 출처에서 찾기',ARRAY['6국01 듣기·말하기(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C7','kor',6,2,'u2',7,'매체를 고려하여 면담하기 — 매체는 소통을 이어 주는 도구와 환경이고 절차마다 쓰임이 다르며(준비 — 누리집·책, 진행 — 녹음기·영상 통화, 정리 — 다시 들으며 간추리기), 대면·비대면을 대상자의 사정에 맞추어 정하고, 담기 전에 허락받아 보고서에만 쓰고 밖으로 내보내지 않기',ARRAY['6국06 매체(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C8','kor',6,2,'u2',7,'모둠 역할과 면담 내용 간추리기 — 진행·약속·질문·매체·정리 담당이 하는 일을 알고, 면담 내용을 삭제·대체·선택·구성으로 간추려 내 말로 다시 세우되 답변의 뜻은 바꾸지 않기(통째 옮기기·뭉뚱그리기 피하기)',ARRAY['6국06 매체(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C9','kor',6,2,'u2',9,'면담 성찰과 면담 보고서 — 잘한 점·보완할 점·더 알고 싶은 점(+ 다음 면담에서 실천할 점)으로 절차마다 되돌아보되 사람 탓이 아니라 다음 약속으로 바꾸고, 보고서를 앞부분(목적·대상자·준비)·가운데 부분(새롭게 안 사실을 갈래로)·뒷부분(깨달은 점·달라진 생각)으로 쓰고 알려도 되는 것만 나누기',ARRAY['6국03 쓰기(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C10','kor',6,2,'u2',11,'작품 속 인물과 면담하기와 바람직한 질문 — 인물에게 세 갈래로 묻고, 인물이 되어 답할 때는 작품 속 사건·말·행동만 근거로 하며(없으면 「이야기에 나오지 않습니다」), 모자란 곳을 파고들거나 억지로 답하게 하는 불쾌한 질문을 상대의 마음을 헤아리는 바람직한 질문으로 고치기',ARRAY['6국01 듣기·말하기(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C11','kor',6,2,'u2',11,'겹받침의 발음 — 받침에 자음이 두 개 있는 겹받침은 낱말 하나로 있을 때 하나만 소리 나고(맑다[막따]·넓다[널따]), 뒤에 모음으로 시작하는 말이 붙으면 앞 자음은 받침으로 남고 뒤 자음이 넘어가 소리 남(맑아[말가]·넓은[널븐])(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X01','kor',6,'u2',ARRAY['K6-2-u2-C1']::text[],'면담을 친해지려고 나누는 일상 대화나 누가 옳은지 가리는 겨루기로 여긴다','「무엇을 알고 싶어서 만나나?」 — 목적이 있는 대화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X02','kor',6,'u2',ARRAY['K6-2-u2-C1','K6-2-u2-C4','K6-2-u2-C5']::text[],'찾아보면 나오는 것(사전 뜻·수·기록)을 면담에서 묻거나, 면담을 검색을 사람으로 바꾼 일로 여긴다','그분이 아니면 답할 수 없는 물음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X03','kor',6,'u2',ARRAY['K6-2-u2-C2']::text[],'면담을 요청할 때 누구인지·목적·시간·날짜를 빠뜨리거나, 날짜를 정해 통보하고 허락을 구하지 않는다','누구 · 왜 · 얼마나 · 언제가 괜찮으신지 — 여쭈어 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X04','kor',6,'u2',ARRAY['K6-2-u2-C2','K6-2-u2-C9']::text[],'궁금하면 사는 곳·나이·가족·버는 돈 같은 개인 정보도 묻거나 보고서에 적어도 된다고 여긴다','「이 질문을 내가 받으면 어떨까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X05','kor',6,'u2',ARRAY['K6-2-u2-C3']::text[],'면담의 절차(준비·진행·정리)나 진행 단계(열기·질문하기·마무리)의 차례와 할 일을 섞는다(목적보다 날짜·역할을 먼저 정하기 등)','만나기 전 · 만나는 동안 · 만난 뒤로 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X06','kor',6,'u2',ARRAY['K6-2-u2-C3','K6-2-u2-C5']::text[],'질문지를 대본처럼 차례대로 읽기만 하고 답을 끝까지 듣지 않아 후속 질문을 하지 못한다','질문지는 지도 — 답 속의 말을 붙들어 이어서 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X07','kor',6,'u2',ARRAY['K6-2-u2-C3','K6-2-u2-C4','K6-2-u2-C5']::text[],'준비 없이 떠오르는 대로 묻거나 면담 목적에서 벗어난 질문을 한다','목적과 하나씩 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X08','kor',6,'u2',ARRAY['K6-2-u2-C4','K6-2-u2-C10']::text[],'질문의 세 갈래(사실·생각이나 느낌·계획이나 당부)를 헷갈리거나 사실만 묻는다','있었던 일? 마음? 앞일과 당부?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X09','kor',6,'u2',ARRAY['K6-2-u2-C4','K6-2-u2-C6']::text[],'자료를 재미·사진·검색 순서로 고르고 누가·언제 만들었는지 출처를 확인하지 않는다','누가 만들었나 · 언제 만들었나 · 목적과 이어지나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X10','kor',6,'u2',ARRAY['K6-2-u2-C6']::text[],'면담 예절을 놓친다(말씀 도중에 끊기·다시 답하게 하기·길게 묻기·감사 인사 없이 나오기)','시간을 내어 주신 분 쪽에서 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X11','kor',6,'u2',ARRAY['K6-2-u2-C7','K6-2-u2-C9']::text[],'허락 없이 담거나, 담아 둔 목소리·영상을 누리집·친구에게 내보내거나 다른 일에 쓴다','담아 둔 것은 빌려 온 것 — 허락 · 보고서에만 · 밖으로 안 내보내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X12','kor',6,'u2',ARRAY['K6-2-u2-C7']::text[],'매체의 뜻·절차마다의 쓰임·대면과 비대면을 헷갈린다','준비 — 찾기 · 진행 — 담기·영상 통화 · 정리 — 다시 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X13','kor',6,'u2',ARRAY['K6-2-u2-C8','K6-2-u2-C9']::text[],'면담 내용을 들은 그대로 통째로 옮기거나, 뭉뚱그려 남는 것이 없게 하거나, 답변의 뜻을 바꾸어 적는다','고르고 덜고 묶어 내 말로 — 뜻은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X14','kor',6,'u2',ARRAY['K6-2-u2-C9']::text[],'성찰을 사람 탓·잘잘못 가리기나 막연한 기분, 목소리·옷차림 같은 겉모습으로 한다','절차마다 무엇을 했나 → 다음에 무엇을 할까') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X15','kor',6,'u2',ARRAY['K6-2-u2-C9']::text[],'면담 보고서의 앞부분·가운데 부분·뒷부분이 담는 내용을 헷갈리거나 느낌·시각만 적는다','앞 — 왜·누구·준비 · 가운데 — 새로 안 사실 · 뒤 — 달라진 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X16','kor',6,'u2',ARRAY['K6-2-u2-C10']::text[],'인물이 되어 답할 때 작품에 없는 내용을 지어내거나 내 이야기를 대신한다','이야기 속 사건·말·행동에 밑줄 — 없으면 「나오지 않습니다」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X17','kor',6,'u2',ARRAY['K6-2-u2-C10']::text[],'모자란 곳을 파고들거나 깎아내리거나 억지로 답하게 하는 불쾌한 질문을 그대로 한다','궁금함 + 상대의 마음 헤아리기 + 고를 여지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X18','kor',6,'u2',ARRAY['K6-2-u2-C11']::text[],'겹받침을 모음 앞에서도 하나만 소리 내거나, 낱말 하나일 때 둘 다 소리 낸다','모음이 붙으면 뒤 자음이 넘어가요 — 맑아[말가]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X19','kor',6,'u2',ARRAY['K6-2-u2-C8']::text[],'모둠 역할(진행·약속·질문·매체·정리)이 하는 일을 헷갈리거나, 면담이 두려운 친구는 빠져야 한다고 여긴다','누가 시간을 · 누가 기기를 · 누가 글로 남기나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#1','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'mc','auto','면담의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"면담의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"정보를 얻으려고 면담 대상자와 주고받는 대화","correct":true},{"t":"친해지려고 가볍게 나누는 이야기","mis":"K6-2-u2-X01"},{"t":"누구의 말이 더 옳은지 가려내는 겨루기","mis":"K6-2-u2-X01"},{"t":"책이나 누리집에서 정보를 찾아 읽는 일","mis":"K6-2-u2-X02"}],"explanation":["면담은 대화이지만 목적이 있어요.","정보를 얻으려고 면담 대상자와 묻고 답해요.","찾아 읽는 일이나 겨루기와는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#2','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'ox','auto','면담은 갑자기 찾아가 그때그때 묻는 일이 아니라 미리 준비하는 일이에요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":1,"kind":"ox","stem":"면담은 갑자기 찾아가 그때그때 묻는 일이 아니라 미리 준비하는 일이에요.","answer":"O","reason_options":[{"t":"대상자를 정하고 자료를 모아 질문을 만드는 준비가 필요하기 때문에","correct":true},{"t":"궁금한 것이 생기면 바로 찾아가 묻는 것이 면담이기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["시후와 가람은 무엇을 여쭐지 먼저 정하기로 했어요.","시간이 되시는지도 여쭈어보기로 했어요.","면담은 준비에서 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#3','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'sa','auto','정보를 얻으려고 면담 대상자와 주고받는 대화를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C1","difficulty":1,"kind":"sa","stem":"정보를 얻으려고 면담 대상자와 주고받는 대화를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["면담"],"explanation":["궁금한 것을 책에서만 찾는 것은 아니에요.","그 일을 하는 사람을 만나 묻고 답을 들을 수 있어요.","이 대화를 면담이라고 해요."],"mis":"K6-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#4','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',1,'mc','auto','면담을 부탁드리는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":4,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"면담을 부탁드리는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"직접 찾아가거나 전화·전자 우편·누리집 글로 할 수 있고, 어느 방법이든 먼저 허락을 구한다","correct":true},{"t":"반드시 직접 찾아가서만 부탁드려야 한다","mis":"K6-2-u2-X03"},{"t":"전화로 부탁드릴 때는 허락을 구하지 않아도 된다","mis":"K6-2-u2-X03"},{"t":"날짜를 정해 알려 드리면 허락을 구한 것이다","mis":"K6-2-u2-X03"}],"explanation":["면담을 부탁드리는 방법은 하나가 아니에요.","찾아가기·전화·전자 우편·누리집 글이 모두 돼요.","어떤 방법이든 먼저 허락을 구하는 것은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#5','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'mc','auto','문화재를 고치는 주희란 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":5,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"문화재를 고치는 주희란 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?","options":[{"t":"처음 이 일을 배우실 때 가장 어려웠던 점은 무엇인가요?","correct":true},{"t":"문화재라는 낱말의 사전 뜻은 무엇인가요?","mis":"K6-2-u2-X02"},{"t":"우리나라에 지정된 문화재는 모두 몇 건인가요?","mis":"K6-2-u2-X02"},{"t":"가장 오래된 문화재는 언제 만들어졌나요?","mis":"K6-2-u2-X02"}],"explanation":["사전 뜻·수·만든 때는 찾아보면 나와요.","그분이 겪은 일과 느낀 것은 그분에게서만 들을 수 있어요.","면담이라야 얻는 것이 생생한 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#6','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',2,'mc','auto','소식지 모둠의 면담 요청에 들어 있는 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X03']::text[],false,'{"seq":6,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"소식지 모둠의 면담 요청에 들어 있는 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"우리가 누구인지 · 면담 목적 · 바라는 날짜 · 걸리는 시간","correct":true},{"t":"우리가 누구인지 · 선생님의 나이 · 선생님이 사시는 곳","mis":"K6-2-u2-X04"},{"t":"면담 목적 하나만","mis":"K6-2-u2-X03"},{"t":"바라는 날짜만 알리고 목적은 만나서 말씀드림","mis":"K6-2-u2-X03"}],"explanation":["하온은 「학급 소식지를 만드는 모둠」이라고 누구인지 밝혔어요.","단우는 목적과 「다음 주 수요일 오후」·「삼십 분 정도」를 말했어요.","이만큼 밝혀야 상대가 응할지 정할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"하온","text":"안녕하세요? 저희는 학급 소식지를 만드는 모둠입니다. 소식지에 오래된 물건을 고쳐 쓰는 일에 대한 글을 싣고 싶습니다."},{"who":"주희란","text":"반갑습니다. 어떤 이야기가 필요한가요?"},{"who":"단우","text":"문화재를 고치는 일이 어떤 일인지 여쭙고 싶습니다. 다음 주 수요일 오후에 삼십 분 정도 시간을 내어 주실 수 있을까요?"},{"who":"주희란","text":"좋습니다. 그날 작업실에서 만나기로 하지요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#7','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'match','auto','면담의 세 가지 특성과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C1","difficulty":2,"kind":"match","stem":"면담의 세 가지 특성과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"정보","r":"묻고 답하는 가운데 그분만 아는 생생한 것을 얻는다"},{"l":"준비","r":"대상자를 정하고 자료를 모아 질문을 만들어 둔다"},{"l":"예의","r":"약속을 정하고 인사와 감사를 갖추어 말한다"}],"mis":"K6-2-u2-X01","explanation":["정보는 만나서 얻는 것이에요.","준비는 만나기 전에, 예의는 만나는 동안 지켜요.","셋 가운데 하나만 빠져도 면담이 잘 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#8','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',2,'ox','auto','면담 대상자가 사는 곳이나 버는 돈도 궁금하면 물어볼 수 있어요.',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":8,"concept":"K6-2-u2-C2","difficulty":2,"kind":"ox","stem":"면담 대상자가 사는 곳이나 버는 돈도 궁금하면 물어볼 수 있어요.","answer":"X","reason_options":[{"t":"알리고 싶지 않을 수 있는 개인 정보이고 면담 목적과 이어지지 않기 때문에","correct":true},{"t":"궁금한 것은 무엇이든 묻는 것이 면담이기 때문에","mis":"K6-2-u2-X04"}],"mis":"K6-2-u2-X04","explanation":["사는 곳·나이·가족·버는 돈은 개인 정보예요.","물어도 되는 것은 하시는 일·어려운 점·보람처럼 목적과 이어진 것이에요.","궁금하다고 다 물어도 되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#9','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'mc','auto','일상 대화와 견준 면담의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X07','K6-2-u2-X06']::text[],false,'{"seq":9,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"일상 대화와 견준 면담의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"답하는 쪽이 훨씬 많이 말하고, 면담자는 잘 묻고 잘 듣는다","correct":true},{"t":"두 사람이 주고받는 말의 양이 늘 비슷하다","mis":"K6-2-u2-X01"},{"t":"정해진 차례 없이 떠오르는 대로 묻는다","mis":"K6-2-u2-X07"},{"t":"면담자가 가장 많이 말해야 잘한 면담이다","mis":"K6-2-u2-X06"}],"explanation":["일상 대화는 친해지려고 나누고 차례가 없어요.","면담은 목적이 있고 준비·진행·정리의 차례가 있어요.","면담자는 많이 말하는 사람이 아니라 잘 듣는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#10','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',3,'error','auto','면담을 부탁드리는 첫마디를 친구들이 말해 보았어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":10,"concept":"K6-2-u2-C2","difficulty":3,"kind":"error","stem":"면담을 부탁드리는 첫마디를 친구들이 말해 보았어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은결 — 「지금 바로 시간 되시죠? 금방 끝나니까 몇 개만 물어볼게요.」","correct":true,"mis_target":"K6-2-u2-X03"},{"t":"다솜 — 「저희는 6학년 학생입니다. 하시는 일이 궁금해 몇 가지 여쭙고 싶은데 언제가 괜찮으실까요?」","mis":"K6-2-u2-X03"},{"t":"로운 — 「학급 신문에 실을 글을 쓰려고 하는데, 삼십 분쯤 시간을 내어 주실 수 있을까요?」","mis":"K6-2-u2-X03"}],"explanation":["다솜은 누구인지·왜·언제가 괜찮은지 여쭈었어요.","로운은 목적과 걸리는 시간을 밝혔어요.","은결은 상대의 사정을 묻지 않고 지금 하자고 정해 버렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#1','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',2,'sa','auto','면담의 세 가지 특성은 「정보 · 준비 · ○○」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":2,"kind":"sa","stem":"면담의 세 가지 특성은 「정보 · 준비 · ○○」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["예의"],"explanation":["정보는 면담으로 얻는 것이에요.","준비는 만나기 전에 하는 일이에요.","시간을 내어 주신 분께는 예의를 지켜요."],"mis":"K6-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#2','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',2,'mc','auto','면담 질문을 만든 뒤 개인 정보나 곤란한 질문이 없는지 되짚을 때 쓰면 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"면담 질문을 만든 뒤 개인 정보나 곤란한 질문이 없는지 되짚을 때 쓰면 좋은 물음은 어느 것인가요?","options":[{"t":"「이 질문을 내가 받으면 어떨까?」","correct":true},{"t":"「이 질문이 가장 길까?」","mis":"K6-2-u2-X04"},{"t":"「이 질문을 하면 면담이 빨리 끝날까?」","mis":"K6-2-u2-X04"},{"t":"「이 질문을 들으면 친구들이 웃을까?」","mis":"K6-2-u2-X04"}],"explanation":["질문을 받는 사람 쪽에서 생각해 보아요.","내가 받아서 불편한 질문은 그분도 불편해요.","그런 질문은 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#3','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'mc','auto','주희란 선생님의 답 「어디가 어떻게 상했는지 오래 들여다봅니다. 그 시간이 가장 깁니다.」가 면담이라야 얻을 수 있는 정보인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X01']::text[],false,'{"seq":3,"concept":"K6-2-u2-C1","difficulty":3,"kind":"mc","stem":"주희란 선생님의 답 「어디가 어떻게 상했는지 오래 들여다봅니다. 그 시간이 가장 깁니다.」가 면담이라야 얻을 수 있는 정보인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 일을 직접 해 온 사람이 겪은 일과 느낀 것이 담겨 있어서","correct":true},{"t":"사전에 그대로 적혀 있는 풀이여서","mis":"K6-2-u2-X02"},{"t":"누구나 아는 사실을 다시 말해서","mis":"K6-2-u2-X02"},{"t":"짧게 답해서 받아 적기 쉬워서","mis":"K6-2-u2-X01"}],"explanation":["「그 시간이 가장 깁니다」는 해 본 사람만 알아요.","책에는 일의 이름은 나와도 하루의 모습은 잘 나오지 않아요.","면담은 그런 생생한 정보를 얻어요."],"asset":{"type":"speech","turns":[{"who":"하온","text":"면담에 응해 주셔서 감사합니다. 미리 찾아본 자료를 바탕으로 질문을 준비했습니다."},{"who":"단우","text":"문화재를 고칠 때 가장 먼저 하시는 일은 무엇인가요?"},{"who":"주희란","text":"고치기 전에 먼저 어디가 어떻게 상했는지 오래 들여다봅니다. 그 시간이 가장 깁니다."},{"who":"하온","text":"오늘 귀한 말씀 감사합니다. 소식지가 나오면 가져다 드리겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#4','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'ox','auto','면담은 누리집에서 찾을 수 있는 것을 사람에게 대신 물어보는 일이에요.',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":4,"concept":"K6-2-u2-C1","difficulty":3,"kind":"ox","stem":"면담은 누리집에서 찾을 수 있는 것을 사람에게 대신 물어보는 일이에요.","answer":"X","reason_options":[{"t":"찾으면 나오는 것은 찾아 두고, 그것을 바탕으로 그분이 아니면 들을 수 없는 것을 묻기 때문에","correct":true},{"t":"사람에게 물으면 검색보다 빨리 답을 얻을 수 있기 때문에","mis":"K6-2-u2-X02"}],"mis":"K6-2-u2-X02","explanation":["찾으면 나오는 것만 물으면 들어도 새로운 것이 없어요.","면담은 한 사람의 겪은 일과 그 뜻을 함께 들어요.","찾아 둔 것을 바탕으로 더 깊이 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#5','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'mc','auto','면담 날짜와 장소를 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X07']::text[],false,'{"seq":5,"concept":"K6-2-u2-C2","difficulty":3,"kind":"mc","stem":"면담 날짜와 장소를 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"바라는 때를 말씀드리고 면담 대상자의 사정에 맞추어 함께 정한다","correct":true},{"t":"우리가 정한 날짜를 알려 드리고 그대로 찾아간다","mis":"K6-2-u2-X03"},{"t":"날짜는 정하지 않고 아무 때나 찾아간다","mis":"K6-2-u2-X07"},{"t":"장소는 언제나 우리 교실로 오시게 한다","mis":"K6-2-u2-X03"}],"explanation":["면담 대상자는 시간을 내어 주시는 분이에요.","날짜·시간·장소는 우리가 통보하지 않아요.","그분과 맞추어 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#6','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'error','auto','면담에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X02','K6-2-u2-X01']::text[],false,'{"seq":6,"concept":"K6-2-u2-C1","difficulty":3,"kind":"error","stem":"면담에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시아 — 「질문을 열 개 만들어 갔으니 차례대로 읽고 오면 면담이 끝나.」","correct":true,"mis_target":"K6-2-u2-X06"},{"t":"도윤 — 「찾아보면 나오는 것은 미리 찾아 두고 가야 해.」","mis":"K6-2-u2-X02"},{"t":"하린 — 「답하시는 분이 더 많이 말씀하시도록 잘 들어야 해.」","mis":"K6-2-u2-X01"}],"explanation":["질문지는 길을 잃지 않게 하는 지도예요.","답을 끝까지 듣고 궁금하면 이어서 물어요.","읽기만 하면 면담이 아니라 낭독이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#7','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'match','auto','면담 질문과 그 질문을 다루는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C2","difficulty":3,"kind":"match","stem":"면담 질문과 그 질문을 다루는 방법을 알맞게 이으세요.","pairs":[{"l":"이 일을 하게 된 까닭은 무엇인가요?","r":"목적과 이어져 물어도 된다"},{"l":"댁은 어느 동네에 있나요?","r":"개인 정보라 덜어 낸다"},{"l":"말씀하기 싫으셔도 꼭 대답해 주셔야 해요.","r":"억지로 답하게 해 덜어 낸다"}],"mis":"K6-2-u2-X04","explanation":["하는 일·까닭·보람은 목적과 이어진 질문이에요.","사는 곳은 알리고 싶지 않을 수 있는 개인 정보예요.","답하기 어려운데 억지로 답하게 하는 질문도 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#8','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',4,'mc','auto','「면담」과 「일상 대화」를 가르는 기준을 바르게 모두 든 것은 어느 것인가요?',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":8,"concept":"K6-2-u2-C1","difficulty":4,"kind":"mc","stem":"「면담」과 「일상 대화」를 가르는 기준을 바르게 모두 든 것은 어느 것인가요?","options":[{"t":"정보를 얻으려는 목적이 있는가 · 준비·진행·정리의 차례가 있는가 · 답하는 쪽이 더 많이 말하는가","correct":true},{"t":"누구와 이야기하는가 · 몇 분 동안 이야기하는가","mis":"K6-2-u2-X01"},{"t":"이야기가 재미있는가 · 웃음이 많았는가","mis":"K6-2-u2-X01"},{"t":"어디에서 만났는가 · 무엇을 입었는가","mis":"K6-2-u2-X01"}],"explanation":["면담은 목적이 있는 대화예요.","차례가 있고, 답하는 쪽이 훨씬 많이 말해요.","누구와·얼마나·어디서는 가르는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#9','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',4,'essay','teacher','내가 만나고 싶은 분께 면담을 부탁드리는 말을 써 보세요. 우리가 누구인지, 면담 목적, 걸리는 시간, 바라는 날짜를 넣고, 날짜를 정해서 알려 드리는 말이 되지 않게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C2","difficulty":4,"kind":"essay","stem":"내가 만나고 싶은 분께 면담을 부탁드리는 말을 써 보세요. 우리가 누구인지, 면담 목적, 걸리는 시간, 바라는 날짜를 넣고, 날짜를 정해서 알려 드리는 말이 되지 않게 쓰세요.","answer_guide":{"answer":"예: 안녕하세요? 저희는 금성초등학교 6학년 학생들입니다. 학급 신문에 도서관에서 하시는 일을 알리는 글을 싣고 싶어 몇 가지 여쭙고 싶습니다. 삼십 분 정도 걸릴 것 같은데, 다음 주 목요일 오후나 금요일 오후 가운데 괜찮으신 때가 있으실까요? 어려우시면 편하신 때를 말씀해 주시면 맞추겠습니다.","scoring_points":["우리가 누구인지와 면담 목적을 밝혔는가","걸리는 시간과 바라는 날짜를 넣었는가","상대의 사정을 여쭈어 함께 정하는 말로 썼는가"]},"explanation":["누구 · 왜 · 얼마나 · 언제가 들어가요.","「괜찮으실까요?」처럼 여쭈어요.","정해서 알리면 허락을 구한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#10','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',4,'essay','teacher','「면담은 검색을 사람으로 바꾼 일이다.」라는 말이 왜 알맞지 않은지 쓰고, 문화재를 고치는 주희란 선생님께 면담이라야 답을 들을 수 있는 질문을 두 가지 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C1","difficulty":4,"kind":"essay","stem":"「면담은 검색을 사람으로 바꾼 일이다.」라는 말이 왜 알맞지 않은지 쓰고, 문화재를 고치는 주희란 선생님께 면담이라야 답을 들을 수 있는 질문을 두 가지 만들어 쓰세요.","answer_guide":{"answer":"예: 면담은 찾으면 나오는 것을 대신 묻는 일이 아니라, 그분이 겪은 일과 그 일을 하며 느낀 것처럼 그분이 아니면 들을 수 없는 것을 듣는 일이기 때문이다. 질문 1 — 고치기 어려웠던 물건을 앞에 두고 어떤 생각을 하셨나요? 질문 2 — 이 일을 하시면서 가장 보람 있었던 때는 언제인가요?","scoring_points":["검색과 다른 까닭(그분만 아는 겪은 일·생각)을 썼는가","면담이라야 답할 수 있는 질문을 두 가지 만들었는가","찾으면 나오는 질문(사전 뜻·수)을 넣지 않았는가"]},"explanation":["찾으면 나오는 것은 미리 찾아 두어요.","그분의 경험·마음을 물어요.","그래야 면담이 생생해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#1','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'mc','auto','면담의 세 절차를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":1,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담의 세 절차를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"면담 준비하기 → 면담 진행하기 → 면담 정리하기","correct":true},{"t":"면담 진행하기 → 면담 준비하기 → 면담 정리하기","mis":"K6-2-u2-X05"},{"t":"면담 정리하기 → 면담 준비하기 → 면담 진행하기","mis":"K6-2-u2-X05"},{"t":"면담 준비하기 → 면담 정리하기 → 면담 진행하기","mis":"K6-2-u2-X05"}],"explanation":["만나기 전에 준비해요.","만나서 진행해요.","만난 뒤에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#2','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'mc','auto','시후네 모둠이 면담을 준비하며 맨 먼저 분명히 해야 할 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"시후네 모둠이 면담을 준비하며 맨 먼저 분명히 해야 할 것은 어느 것인가요?","options":[{"t":"면담으로 무엇을 알고 싶은지 하는 목적","correct":true},{"t":"녹음을 맡을 사람","mis":"K6-2-u2-X05"},{"t":"면담할 날짜","mis":"K6-2-u2-X05"},{"t":"보고서의 제목","mis":"K6-2-u2-X05"}],"explanation":["목적이 정해져야 누구를 만날지 정해져요.","목적이 있어야 질문도 만들 수 있어요.","역할과 날짜는 그다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#3','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',1,'mc','auto','「하루에 관측을 몇 번 하시나요?」는 어느 갈래의 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"「하루에 관측을 몇 번 하시나요?」는 어느 갈래의 질문인가요?","options":[{"t":"구체적인 사실에 대한 질문","correct":true},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 마무리하는 인사","mis":"K6-2-u2-X05"}],"explanation":["몇 번 하는지는 있는 그대로의 일이에요.","그래서 구체적인 사실에 대한 질문이에요.","마음을 묻거나 앞일을 묻는 질문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#4','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'ox','auto','면담은 면담 대상자와 헤어지는 순간에 끝나요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C3","difficulty":1,"kind":"ox","stem":"면담은 면담 대상자와 헤어지는 순간에 끝나요.","answer":"X","reason_options":[{"t":"들은 것을 간추리고 되돌아보아 쓸 수 있는 형태로 남겨야 끝나기 때문에","correct":true},{"t":"만나서 묻고 답하는 것이 면담의 전부이기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["헤어진 뒤에도 면담 정리하기가 남아 있어요.","내용 정리 · 과정 성찰 · 보고서 쓰기를 해요.","들은 것을 남길 때 면담이 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#5','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'match','auto','시후네 모둠의 질문과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C4","difficulty":2,"kind":"match","stem":"시후네 모둠의 질문과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"비가 많이 오는 날에는 관측을 어떻게 하시나요?","r":"구체적인 사실에 대한 질문"},{"l":"예보가 맞았을 때 어떤 마음이 드시나요?","r":"생각이나 느낌에 대한 질문"},{"l":"기상 관측사가 되고 싶은 학생에게 해 주실 말씀이 있나요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["있었던 일·하는 일을 묻는지 보아요.","마음을 묻는지 보아요.","뒷사람에게 줄 말이나 앞일을 묻는지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#6','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'mc','auto','시후네 모둠의 면담 목적은 날씨를 살피는 일을 알리는 것이에요. 목적과 이어진 질문은 어느 것인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":6,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"시후네 모둠의 면담 목적은 날씨를 살피는 일을 알리는 것이에요. 목적과 이어진 질문은 어느 것인가요?","options":[{"t":"관측한 값이 예보로 바뀌기까지 어떤 과정을 거치나요?","correct":true},{"t":"가장 좋아하시는 계절은 무엇인가요?","mis":"K6-2-u2-X07"},{"t":"요즘 즐겨 보시는 영화는 무엇인가요?","mis":"K6-2-u2-X07"},{"t":"어렸을 때 별명은 무엇이었나요?","mis":"K6-2-u2-X07"}],"explanation":["목적은 날씨를 살피는 일을 알리는 것이에요.","관측 값이 예보로 바뀌는 과정이 알리려는 내용이에요.","나머지는 재미있어도 하시는 일을 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#7','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','면담 진행하기의 세 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"면담 진행하기의 세 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"면담 열기 → 질문하기 → 면담 마무리하기","correct":true},{"t":"질문하기 → 면담 열기 → 면담 마무리하기","mis":"K6-2-u2-X05"},{"t":"면담 열기 → 면담 마무리하기 → 질문하기","mis":"K6-2-u2-X05"},{"t":"면담 마무리하기 → 질문하기 → 면담 열기","mis":"K6-2-u2-X05"}],"explanation":["막 만났을 때 면담을 열어요.","한창 이야기할 때 질문해요.","헤어지기 전에 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#8','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','면담 열기에서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X07']::text[],false,'{"seq":8,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"면담 열기에서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인사하고 목적을 설명하고 담아도 될지 여쭙는다","correct":true},{"t":"알게 된 것을 확인하고 감사 인사를 드린다","mis":"K6-2-u2-X05"},{"t":"면담 보고서를 쓴다","mis":"K6-2-u2-X05"},{"t":"그때 처음으로 질문을 만들기 시작한다","mis":"K6-2-u2-X07"}],"explanation":["면담 열기는 진행의 첫 단계예요.","인사 · 목적 설명 · 동의 구하기를 해요.","확인과 감사는 마무리에서 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#9','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'ox','auto','사실을 묻는 질문만 골라 만들면 면담이 가장 알차요.',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":9,"concept":"K6-2-u2-C4","difficulty":2,"kind":"ox","stem":"사실을 묻는 질문만 골라 만들면 면담이 가장 알차요.","answer":"X","reason_options":[{"t":"사실만 물으면 자료를 읽는 것과 다르지 않아 세 갈래를 골고루 만들어야 하기 때문에","correct":true},{"t":"생각이나 느낌은 면담에서 물으면 안 되기 때문에","mis":"K6-2-u2-X08"}],"mis":"K6-2-u2-X08","explanation":["사실은 찾아봐도 나오는 것이 많아요.","생각이나 느낌, 앞일과 당부도 함께 물어요.","세 갈래를 골고루 만들면 치우치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#10','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',3,'error','auto','시후네 모둠이 면담 준비를 하며 말했어요. 차례에 맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X09']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":3,"kind":"error","stem":"시후네 모둠이 면담 준비를 하며 말했어요. 차례에 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"가람 — 「목적은 나중에 정하고, 일단 녹음 맡을 사람부터 정하자.」","correct":true,"mis_target":"K6-2-u2-X05"},{"t":"단우 — 「목적이 정해졌으니 그 일을 하시는 분을 대상자로 정하자.」","mis":"K6-2-u2-X05"},{"t":"하온 — 「만나기 전에 관측에 대한 자료를 먼저 찾아보자.」","mis":"K6-2-u2-X09"}],"explanation":["준비하기는 목적을 정하는 데서 시작해요.","목적 → 대상자 → 방식 → 자료 → 질문 → 역할 → 요청이에요.","가람은 목적보다 역할을 먼저 정하려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#1','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',2,'sa','auto','면담 진행하기의 세 단계 가운데 가장 긴 단계는 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C3","difficulty":2,"kind":"sa","stem":"면담 진행하기의 세 단계 가운데 가장 긴 단계는 무엇인가요? 네 글자로 쓰세요.","answer":["질문하기"],"explanation":["면담 열기 · 질문하기 · 면담 마무리하기가 있어요.","질문에 따라 대화의 방향과 얻는 정보가 달라져요.","그래서 질문하기가 가장 길어요."],"mis":"K6-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#2','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',2,'mc','auto','「예보가 빗나갔을 때 어떤 마음이 드시나요?」는 어느 갈래의 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"「예보가 빗나갔을 때 어떤 마음이 드시나요?」는 어느 갈래의 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적을 밝히는 말","mis":"K6-2-u2-X05"}],"explanation":["「어떤 마음」을 묻고 있어요.","그래서 생각이나 느낌에 대한 질문이에요.","이런 질문으로 그분의 마음까지 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#3','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',3,'mc','auto','면담 준비하기에서 하는 일이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"면담 준비하기에서 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"들은 내용을 간추리고 잘한 점을 되돌아보기","correct":true},{"t":"면담 방식 정하기","mis":"K6-2-u2-X05"},{"t":"면담 역할 정하기","mis":"K6-2-u2-X05"},{"t":"면담을 요청하고 허락 구하기","mis":"K6-2-u2-X05"}],"explanation":["준비하기에는 여덟 가지 일이 있어요.","방식·역할·요청과 허락도 만나기 전에 해요.","간추리고 되돌아보는 것은 면담 정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#4','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',3,'mc','auto','자료를 찾아 둔 시후가 「무슨 일 하세요?」 대신 여쭙기로 한 질문은 어느 것인가요?',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":3,"kind":"mc","stem":"자료를 찾아 둔 시후가 「무슨 일 하세요?」 대신 여쭙기로 한 질문은 어느 것인가요?","options":[{"t":"「재신 값이 예보에 어떻게 쓰이나요?」","correct":true},{"t":"「기상 관측사는 무엇을 하는 사람인가요?」","mis":"K6-2-u2-X02"},{"t":"「날씨는 왜 바뀌나요?」","mis":"K6-2-u2-X02"},{"t":"「기온은 무엇으로 재나요?」","mis":"K6-2-u2-X02"}],"explanation":["가람은 기상 관측이 기온·바람·비의 양을 재는 일임을 찾아 두었어요.","찾아 둔 것을 바탕으로 한 걸음 더 깊이 물었어요.","다른 보기는 찾아보면 나오는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#5','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C2',3,'ox','auto','하온은 면담 날짜와 장소를 모둠이 정해서 오세중 선생님께 알려 드렸어요.',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":5,"concept":"K6-2-u2-C2","difficulty":3,"kind":"ox","stem":"하온은 면담 날짜와 장소를 모둠이 정해서 오세중 선생님께 알려 드렸어요.","answer":"X","reason_options":[{"t":"선생님이 날짜를 말씀하시고 하온이 장소를 여쭈어 함께 맞추어 정했기 때문에","correct":true},{"t":"하온이 「관측소로 찾아뵈어도」라고 장소를 먼저 말했기 때문에","mis":"K6-2-u2-X03"}],"mis":"K6-2-u2-X03","explanation":["「다음 주 화요일 오후는 어떤가요?」는 선생님 말씀이에요.","하온은 「찾아뵈어도 괜찮을까요?」라고 여쭈었어요.","날짜와 장소는 대상자와 맞추어 정해요."],"asset":{"type":"speech","turns":[{"who":"하온","text":"안녕하세요? 저희는 학급 신문을 만드는 6학년 학생들입니다. 날씨를 살피는 일을 알리는 글을 쓰고 싶어 몇 가지 여쭙고 싶습니다."},{"who":"오세중","text":"좋은 주제네요. 다음 주 화요일 오후는 어떤가요?"},{"who":"하온","text":"네, 감사합니다. 삼십 분 정도면 될 것 같습니다. 관측소로 찾아뵈어도 괜찮을까요?"},{"who":"오세중","text":"그러지요. 그때 뵙겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#6','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',3,'error','auto','시후네 모둠이 만든 질문을 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X08']::text[],false,'{"seq":6,"concept":"K6-2-u2-C4","difficulty":3,"kind":"error","stem":"시후네 모둠이 만든 질문을 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"시후 — 「재미있으니까 ‘좋아하시는 노래’ 질문도 꼭 넣자.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"가람 — 「기온을 잴 때 조심하시는 점은 날씨 일과 이어지니 넣자.」","mis":"K6-2-u2-X07"},{"t":"단우 — 「사실 질문만 있으니 느낌을 묻는 질문도 하나 넣자.」","mis":"K6-2-u2-X08"}],"explanation":["질문은 면담 목적과 견주어 골라요.","좋아하는 노래는 날씨를 살피는 일과 이어지지 않아요.","가람과 단우는 목적과 갈래를 살폈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#7','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',3,'match','auto','면담 정리하기에서 하는 일과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":3,"kind":"match","stem":"면담 정리하기에서 하는 일과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"면담 내용 정리하기","r":"담아 둔 것과 메모를 보며 간추린다"},{"l":"면담 과정 성찰하기","r":"잘한 점과 보완할 점을 되돌아본다"},{"l":"면담 보고서 쓰기","r":"알게 된 것을 글로 정리해 나눈다"}],"mis":"K6-2-u2-X05","explanation":["면담은 헤어지는 순간에 끝나지 않아요.","간추리고 · 되돌아보고 · 써서 나눠요.","그래야 들은 것을 쓸 수 있게 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#8','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',4,'mc','auto','면담 질문을 세 갈래로 골고루 만들어야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":8,"concept":"K6-2-u2-C4","difficulty":4,"kind":"mc","stem":"면담 질문을 세 갈래로 골고루 만들어야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사실·마음·앞일을 함께 물어야 그분의 일과 생각을 고루 듣고 면담이 한쪽으로 치우치지 않기 때문에","correct":true},{"t":"질문 수를 꼭 셋으로 맞추어야 하기 때문에","mis":"K6-2-u2-X08"},{"t":"사실을 묻는 질문은 면담에서 하면 안 되기 때문에","mis":"K6-2-u2-X08"},{"t":"갈래가 많을수록 면담 시간이 짧아지기 때문에","mis":"K6-2-u2-X08"}],"explanation":["갈래가 다르면 얻는 것도 달라요.","사실만 물으면 자료를 읽는 것과 같아요.","세 갈래를 고루 물으면 일과 마음이 함께 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#9','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',4,'essay','teacher','내가 만나고 싶은 분을 정해 면담 목적을 한 문장으로 쓰고, 그 목적에 맞는 질문을 세 갈래로 하나씩 만드세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C4","difficulty":4,"kind":"essay","stem":"내가 만나고 싶은 분을 정해 면담 목적을 한 문장으로 쓰고, 그 목적에 맞는 질문을 세 갈래로 하나씩 만드세요.","answer_guide":{"answer":"예: 만날 분 — 우리 동네 소방관. 목적 — 소방관이 하루에 하는 일과 이 일을 하려면 무엇이 필요한지 알아보려고. 사실 — 출동이 없을 때는 주로 어떤 일을 하시나요? 생각이나 느낌 — 처음 불을 끄러 나가셨을 때 어떤 마음이 드셨나요? 계획이나 당부 — 소방관이 되고 싶은 학생에게 해 주실 말씀이 있나요?","scoring_points":["면담 목적을 분명하게 한 문장으로 썼는가","사실·생각이나 느낌·계획이나 당부의 세 갈래로 질문을 만들었는가","세 질문이 모두 목적과 이어지는가"]},"explanation":["목적이 분명하면 질문이 저절로 나와요.","세 갈래를 하나씩 만들어요.","목적과 이어지는지 다시 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#10','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',4,'essay','teacher','면담의 세 절차를 차례대로 쓰고, 절차마다 하는 일을 두 가지씩 쓰세요. 면담이 언제 끝나는지도 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":4,"kind":"essay","stem":"면담의 세 절차를 차례대로 쓰고, 절차마다 하는 일을 두 가지씩 쓰세요. 면담이 언제 끝나는지도 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 면담 준비하기 — 목적과 대상자를 정하고, 자료를 찾아 질문을 만든다. 면담 진행하기 — 인사하고 목적을 밝힌 뒤 세 갈래로 묻고, 알게 된 것을 확인하고 감사 인사를 드린다. 면담 정리하기 — 담아 둔 것과 메모로 내용을 간추리고, 과정을 되돌아보아 보고서를 쓴다. 면담은 헤어질 때가 아니라 들은 것을 보고서처럼 쓸 수 있는 형태로 남길 때 끝난다.","scoring_points":["세 절차를 차례대로 썼는가","절차마다 하는 일을 두 가지씩 바르게 썼는가","면담이 끝나는 때를 바르게 썼는가"]},"explanation":["준비 → 진행 → 정리예요.","절차마다 할 일이 달라요.","남길 때 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#1','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'mc','auto','진로 정보를 얻는 방법을 함께 쓸 때 가장 좋은 차례는 어느 것인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X02','K6-2-u2-X11']::text[],false,'{"seq":1,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"진로 정보를 얻는 방법을 함께 쓸 때 가장 좋은 차례는 어느 것인가요?","options":[{"t":"누리집과 책으로 바탕을 쌓고, 거기서 생긴 궁금함을 면담으로 푼다","correct":true},{"t":"아무것도 찾지 않고 바로 면담부터 한다","mis":"K6-2-u2-X07"},{"t":"누리집만 보고 면담은 하지 않는다","mis":"K6-2-u2-X02"},{"t":"면담에서 들은 것을 누리집에 그대로 올린다","mis":"K6-2-u2-X11"}],"explanation":["검색과 책은 바탕을 쌓는 데 좋아요.","그 일을 하는 분께 들으면 하루의 모습과 마음까지 알 수 있어요.","찾아 둔 것 위에서 면담하면 더 깊어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#2','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'mc','auto','은새와 솔찬이 노윤재 선생님과 면담한 목적은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X04']::text[],false,'{"seq":2,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"은새와 솔찬이 노윤재 선생님과 면담한 목적은 어느 것인가요?","options":[{"t":"수어 통역사가 하는 일과 이 일을 하려면 무엇이 필요한지 알아보려고","correct":true},{"t":"수어를 배워 바로 써 보려고","mis":"K6-2-u2-X01"},{"t":"어느 직업이 더 좋은지 가려내려고","mis":"K6-2-u2-X01"},{"t":"선생님의 가족 이야기를 들으려고","mis":"K6-2-u2-X04"}],"explanation":["솔찬이 면담 열기에서 목적을 분명히 밝혔어요.","「하시는 일과 … 무엇이 필요한지 여쭙고자 합니다.」","목적은 열기에서 학생이 직접 말해요."],"asset":{"type":"speech","turns":[{"who":"은새","text":"안녕하세요? 만나 뵙게 되어 반갑습니다. 바쁘신데 시간 내어 주셔서 감사합니다."},{"who":"솔찬","text":"요청드릴 때 말씀드린 것처럼, 오늘은 수어 통역사가 하시는 일과 이 일을 하려면 무엇이 필요한지 여쭙고자 합니다."},{"who":"은새","text":"답변을 정확히 정리하려고 녹음을 하고 싶은데 괜찮으실까요?"},{"who":"노윤재","text":"네, 괜찮습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#3','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'sa','auto','면담 대상자의 답을 듣고 더 자세히 알려고 이어서 하는 질문을 무엇이라고 하나요? 「○○ 질문」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C5","difficulty":1,"kind":"sa","stem":"면담 대상자의 답을 듣고 더 자세히 알려고 이어서 하는 질문을 무엇이라고 하나요? 「○○ 질문」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["후속"],"explanation":["답을 듣다가 생긴 물음이에요.","미리 만들어 갈 수 없고 듣고 있어야만 나와요.","이것을 후속 질문이라고 해요."],"mis":"K6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#4','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',1,'ox','auto','면담 대상자가 말씀하시는 도중에 떠오른 물음은 바로 끼어들어 여쭈어야 해요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":4,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담 대상자가 말씀하시는 도중에 떠오른 물음은 바로 끼어들어 여쭈어야 해요.","answer":"X","reason_options":[{"t":"말씀을 끊지 않고 메모해 두었다가 뒤에 여쭈는 것이 예의이기 때문에","correct":true},{"t":"잊어버리기 전에 묻는 것이 더 중요하기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["말씀 도중에 끊지 않아요.","떠오른 물음은 메모해 두어요.","말씀이 끝나면 그때 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#5','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',2,'mc','auto','은새의 「방금 ‘다시 짜야 한다’고 하셨는데, 그럴 때는 어떻게 하시나요?」가 후속 질문인 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X05','K6-2-u2-X07']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"은새의 「방금 ‘다시 짜야 한다’고 하셨는데, 그럴 때는 어떻게 하시나요?」가 후속 질문인 까닭은 어느 것인가요?","options":[{"t":"앞선 답에 나온 말을 붙들고 더 자세히 알려고 이어서 물었기 때문에","correct":true},{"t":"질문지에 미리 적어 간 첫 질문이기 때문에","mis":"K6-2-u2-X06"},{"t":"면담을 마무리하는 인사이기 때문에","mis":"K6-2-u2-X05"},{"t":"면담 목적과 상관없는 질문이기 때문에","mis":"K6-2-u2-X07"}],"explanation":["「다시 짜야 한다」는 바로 앞 답에 나온 말이에요.","은새는 그 말을 붙들고 이어서 물었어요.","그 덕분에 「함께 만드는 일」이라는 가장 중요한 답이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"수어 통역사는 하루에 주로 어떤 일을 하시나요?"},{"who":"노윤재","text":"회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다. 들은 말을 손으로 옮기고, 손으로 하신 말을 소리로 옮깁니다."},{"who":"은새","text":"말을 옮기실 때 가장 어려운 점은 무엇인가요?"},{"who":"노윤재","text":"낱말을 그대로 옮기는 것으로는 뜻이 전해지지 않을 때가 있습니다. 그럴 때는 뜻이 살아나도록 다시 짜야 합니다."},{"who":"은새","text":"방금 「다시 짜야 한다」고 하셨는데, 그럴 때는 어떻게 하시나요?"},{"who":"노윤재","text":"말한 분께 무엇을 전하고 싶으신지 한 번 더 여쭙습니다. 통역은 혼자 하는 일이 아니라 함께 만드는 일입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#6','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',2,'match','auto','면담 자료 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C5","difficulty":2,"kind":"match","stem":"면담 자료 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.","pairs":[{"l":"녹음을 하고 싶은데 괜찮으실까요?","r":"면담 열기"},{"l":"말을 옮기실 때 가장 어려운 점은 무엇인가요?","r":"질문하기"},{"l":"말씀이 인상 깊었습니다. 오늘 감사합니다.","r":"면담 마무리하기"}],"mis":"K6-2-u2-X05","explanation":["동의를 구하는 말은 면담 열기에 나와요.","세 갈래 질문은 질문하기에 나와요.","알게 된 것 확인과 감사는 마무리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#7','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','면담에서 지켜야 할 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X11']::text[],false,'{"seq":7,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"면담에서 지켜야 할 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 끝까지 귀 기울여 듣고, 끝난 뒤 감사 인사를 드린다","correct":true},{"t":"답이 길면 도중에 끊고 다음 질문으로 간다","mis":"K6-2-u2-X10"},{"t":"답이 마음에 안 들면 다시 답하게 한다","mis":"K6-2-u2-X10"},{"t":"녹음은 말씀드리지 않고 몰래 한다","mis":"K6-2-u2-X11"}],"explanation":["예의가 있어야 답이 깊어져요.","끝까지 듣고, 담기 전에 동의를 구하고, 감사 인사를 드려요.","끊기·다시 답하게 하기는 예절이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#8','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','면담에서 질문을 짧게 해야 하는 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X08','K6-2-u2-X13']::text[],false,'{"seq":8,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"면담에서 질문을 짧게 해야 하는 까닭은 어느 것인가요?","options":[{"t":"설명이 길면 무엇을 묻는지 흐려지기 때문에","correct":true},{"t":"면담 시간을 일부러 줄이려고","mis":"K6-2-u2-X10"},{"t":"짧은 질문은 사실만 묻기 때문에","mis":"K6-2-u2-X08"},{"t":"답도 짧게 받아 적기 쉽게 하려고","mis":"K6-2-u2-X13"}],"explanation":["질문이 길면 듣는 분이 무엇을 묻는지 헷갈려요.","짧고 분명하게 물어요.","그래야 답하시는 분이 편하게 말씀하실 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#9','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','진로 자료를 찾을 때 믿을 만한 출처는 어느 것인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":9,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"진로 자료를 찾을 때 믿을 만한 출처는 어느 것인가요?","options":[{"t":"누가 만든 자료인지 밝혀져 있고 언제 만든 것인지 적혀 있는 자료","correct":true},{"t":"검색하면 맨 위에 나오는 자료","mis":"K6-2-u2-X09"},{"t":"사진이 많아 보기 좋은 자료","mis":"K6-2-u2-X09"},{"t":"누가 썼는지 알 수 없지만 재미있는 자료","mis":"K6-2-u2-X09"}],"explanation":["자료를 찾을 때는 출처를 꼭 확인해요.","누가·언제 만들었는지가 밝혀져야 믿을 수 있어요.","순서·사진·재미는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#10','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',3,'error','auto','노윤재 선생님 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":10,"concept":"K6-2-u2-C5","difficulty":3,"kind":"error","stem":"노윤재 선생님 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서진 — 「후속 질문도 미리 질문지에 다 적어 가야 해.」","correct":true,"mis_target":"K6-2-u2-X06"},{"t":"유나 — 「후속 질문은 답을 잘 듣고 있어야만 나와.」","mis":"K6-2-u2-X06"},{"t":"태오 — 「그 한 번의 물음 덕분에 가장 중요한 답이 나왔어.」","mis":"K6-2-u2-X06"}],"explanation":["후속 질문은 답을 듣고 나서 생기는 물음이에요.","그래서 미리 적어 갈 수 없어요.","유나와 태오는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#1','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',2,'sa','auto','만든 질문을 점검하는 세 가지 물음은 「목적에 맞는가 · 예의를 갖추었는가 · 이해할 수 있게 ○○한가」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C6","difficulty":2,"kind":"sa","stem":"만든 질문을 점검하는 세 가지 물음은 「목적에 맞는가 · 예의를 갖추었는가 · 이해할 수 있게 ○○한가」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["명료"],"explanation":["질문은 만든 뒤 스스로 점검해요.","목적·예의·명료함을 살펴요.","명료하다는 것은 뜻이 분명하다는 말이에요."],"mis":"K6-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#2','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',2,'mc','auto','노윤재 선생님의 답 「손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X02']::text[],false,'{"seq":2,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"노윤재 선생님의 답 「손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?","options":[{"t":"「끝까지 듣는 연습은 어떻게 하면 좋을까요?」","correct":true},{"t":"「다음 질문입니다. 이 일은 언제부터 하셨나요?」","mis":"K6-2-u2-X06"},{"t":"「점심은 보통 몇 시에 드시나요?」","mis":"K6-2-u2-X07"},{"t":"「수어의 손 모양은 모두 몇 가지인가요?」","mis":"K6-2-u2-X02"}],"explanation":["후속 질문은 앞선 답에 나온 말을 붙들어요.","「끝까지 듣는 연습」을 붙들고 더 자세히 물었어요.","다른 보기는 앞의 답을 듣지 않아도 할 수 있는 물음이에요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"이 일을 하고 싶은 학생에게 해 주고 싶으신 말씀이 있나요?"},{"who":"노윤재","text":"손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다. 끝까지 들어야 무엇을 옮길지 알 수 있습니다."},{"who":"은새","text":"통역이 낱말을 바꾸는 일이 아니라 뜻을 함께 만드는 일이라는 말씀이 인상 깊었습니다. 오늘 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#3','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'mc','auto','「선생님 하시는 일 그거 힘든 거 맞죠? 그리고 그때 그거는 어떻게 된 거고 또 다른 건요?」를 점검할 때 가장 먼저 고칠 점은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X04','K6-2-u2-X08']::text[],false,'{"seq":3,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「선생님 하시는 일 그거 힘든 거 맞죠? 그리고 그때 그거는 어떻게 된 거고 또 다른 건요?」를 점검할 때 가장 먼저 고칠 점은 어느 것인가요?","options":[{"t":"여러 가지를 한꺼번에 흐리게 물어 뜻이 분명하지 않다","correct":true},{"t":"질문이 너무 짧다","mis":"K6-2-u2-X10"},{"t":"개인 정보를 물었다","mis":"K6-2-u2-X04"},{"t":"사실을 묻는 질문이라 쓸 수 없다","mis":"K6-2-u2-X08"}],"explanation":["「그거」, 「그때」가 무엇을 가리키는지 알 수 없어요.","한 번에 여러 가지를 묻고 있어요.","하나씩 짧고 분명하게 고쳐 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#4','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',3,'ox','auto','좋은 면담은 준비한 질문 없이 그 자리에서 떠오르는 대로 묻는 면담이에요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":4,"concept":"K6-2-u2-C5","difficulty":3,"kind":"ox","stem":"좋은 면담은 준비한 질문 없이 그 자리에서 떠오르는 대로 묻는 면담이에요.","answer":"X","reason_options":[{"t":"준비한 질문으로 길을 잡고, 듣다가 생긴 물음으로 깊이 들어가야 하기 때문에","correct":true},{"t":"미리 준비하면 후속 질문을 할 수 없기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["준비 없이 가면 목적에서 벗어난 이야기로 흘러가요.","준비한 질문만 읽으면 후속 질문이 없어요.","둘 다 해야 좋은 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#5','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',3,'mc','auto','준비한 질문 열 개를 차례대로 읽기만 하고 나온 면담에서 생기는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X06']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":3,"kind":"mc","stem":"준비한 질문 열 개를 차례대로 읽기만 하고 나온 면담에서 생기는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 듣지 않아 후속 질문이 없고 자료에 이미 있는 것만 남는다","correct":true},{"t":"목적에서 벗어난 이야기로만 흘러간다","mis":"K6-2-u2-X07"},{"t":"면담 대상자가 더 깊은 이야기를 해 준다","mis":"K6-2-u2-X06"},{"t":"가장 알찬 면담이 된다","mis":"K6-2-u2-X06"}],"explanation":["읽기만 하면 답을 듣지 않게 돼요.","그러면 이어서 물을 것이 생기지 않아요.","한쪽으로 치우친 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#6','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'error','auto','면담하며 듣는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":6,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"면담하며 듣는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「말씀이 길어지면 끊고 내가 궁금한 걸 먼저 여쭤.」","correct":true,"mis_target":"K6-2-u2-X10"},{"t":"수빈 — 「떠오른 물음은 메모해 두었다가 말씀이 끝나면 여쭈어.」","mis":"K6-2-u2-X10"},{"t":"건우 — 「고개를 끄덕이며 듣고 있다는 걸 보여 드려.」","mis":"K6-2-u2-X10"}],"explanation":["답의 깊이를 정하는 것은 듣는 태도예요.","말씀 도중에 끊지 않아요.","수빈과 건우는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#7','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'match','auto','면담 열기에서 한 말과 그 말에 담긴 예의를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C6","difficulty":3,"kind":"match","stem":"면담 열기에서 한 말과 그 말에 담긴 예의를 알맞게 이으세요.","pairs":[{"l":"만나 뵙게 되어 반갑습니다.","r":"반갑게 인사하기"},{"l":"바쁘신데 시간 내어 주셔서 감사합니다.","r":"시간을 내어 주신 데 감사하기"},{"l":"오늘은 하시는 일을 여쭙고자 합니다.","r":"면담 목적 밝히기"},{"l":"녹음을 해도 괜찮으실까요?","r":"담기 전에 동의 구하기"}],"mis":"K6-2-u2-X10","explanation":["면담 열기의 말에는 예의가 담겨 있어요.","인사 · 감사 · 목적 · 동의를 갖추어요.","그래야 그분이 편안하게 말씀하실 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#8','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',4,'mc','auto','노윤재 선생님의 말씀과 은새의 마무리 말로 보아, 이 면담에서 얻은 가장 중요한 정보는 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":8,"concept":"K6-2-u2-C5","difficulty":4,"kind":"mc","stem":"노윤재 선생님의 말씀과 은새의 마무리 말로 보아, 이 면담에서 얻은 가장 중요한 정보는 어느 것인가요?","options":[{"t":"통역은 낱말을 바꾸는 일이 아니라 사람의 말을 끝까지 듣고 뜻을 함께 만드는 일이다","correct":true},{"t":"통역사는 무엇보다 손 모양을 많이 외워야 한다","mis":"K6-2-u2-X13"},{"t":"통역은 혼자 빨리 해내야 하는 일이다","mis":"K6-2-u2-X13"},{"t":"수어 통역사가 되기는 너무 어려우니 하지 않는 것이 좋다","mis":"K6-2-u2-X13"}],"explanation":["선생님은 끝까지 듣는 연습이 먼저라고 하셨어요.","앞에서 통역은 함께 만드는 일이라고도 하셨어요.","은새도 그 말씀을 확인하며 마무리했어요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"이 일을 하고 싶은 학생에게 해 주고 싶으신 말씀이 있나요?"},{"who":"노윤재","text":"손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다. 끝까지 들어야 무엇을 옮길지 알 수 있습니다."},{"who":"은새","text":"통역이 낱말을 바꾸는 일이 아니라 뜻을 함께 만드는 일이라는 말씀이 인상 깊었습니다. 오늘 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#9','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',4,'essay','teacher','노윤재 선생님의 답 「회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다.」를 들었다고 할 때, 할 수 있는 후속 질문을 두 가지 만들고 그 질문이 후속 질문이라고 할 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":4,"kind":"essay","stem":"노윤재 선생님의 답 「회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다.」를 들었다고 할 때, 할 수 있는 후속 질문을 두 가지 만들고 그 질문이 후속 질문이라고 할 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 후속 질문 1 — 진료하는 자리에서 통역하실 때는 무엇을 가장 조심하시나요? 후속 질문 2 — 말이 오가는 자리마다 통역하는 방법이 달라지나요? 두 질문 모두 앞선 답에 나온 「진료」, 「말이 오가는 자리」를 붙들고 더 자세히 알려고 이어서 물은 것이어서, 답을 듣지 않았다면 만들 수 없는 후속 질문이다.","scoring_points":["앞선 답에 나온 말을 붙든 질문을 두 가지 만들었는가","더 자세히 알려는 질문인가","답을 들어야만 나오는 질문이라는 까닭을 썼는가"]},"explanation":["후속 질문은 앞선 답의 말에서 나와요.","그 말을 붙들어 더 자세히 물어요.","미리 만들어 갈 수 없어요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"수어 통역사는 하루에 주로 어떤 일을 하시나요?"},{"who":"노윤재","text":"회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다. 들은 말을 손으로 옮기고, 손으로 하신 말을 소리로 옮깁니다."},{"who":"은새","text":"말을 옮기실 때 가장 어려운 점은 무엇인가요?"},{"who":"노윤재","text":"낱말을 그대로 옮기는 것으로는 뜻이 전해지지 않을 때가 있습니다. 그럴 때는 뜻이 살아나도록 다시 짜야 합니다."},{"who":"은새","text":"방금 「다시 짜야 한다」고 하셨는데, 그럴 때는 어떻게 하시나요?"},{"who":"노윤재","text":"말한 분께 무엇을 전하고 싶으신지 한 번 더 여쭙습니다. 통역은 혼자 하는 일이 아니라 함께 만드는 일입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#10','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',4,'essay','teacher','면담 목적이 「수어 통역사가 하는 일 알아보기」일 때, 다음 두 질문을 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」로 점검하고 고쳐 쓰세요. ① 「돈은 얼마나 버세요?」 ② 「그 일 힘들어요 안 힘들어요 그리고 언제 쉬어요?」','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C6","difficulty":4,"kind":"essay","stem":"면담 목적이 「수어 통역사가 하는 일 알아보기」일 때, 다음 두 질문을 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」로 점검하고 고쳐 쓰세요. ① 「돈은 얼마나 버세요?」 ② 「그 일 힘들어요 안 힘들어요 그리고 언제 쉬어요?」","answer_guide":{"answer":"예: ①은 버는 돈이라는 개인 정보를 묻고 목적과도 이어지지 않으므로 「이 일을 하며 가장 보람 있었던 때는 언제인가요?」로 고친다. ②는 여러 가지를 한꺼번에 묻고 높임도 갖추지 않아 뜻이 흐리므로 「통역하실 때 가장 힘든 점은 무엇인가요?」처럼 하나만 예의 바르게 묻는다.","scoring_points":["①의 문제(개인 정보·목적과 무관)를 찾았는가","②의 문제(여러 가지를 한꺼번에·예의 부족·뜻이 흐림)를 찾았는가","두 질문을 목적에 맞고 예의 바르고 분명하게 고쳐 썼는가"]},"explanation":["목적에 맞는지 먼저 봐요.","높임과 예의를 갖추었는지 봐요.","하나씩 분명하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#1','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'mc','auto','대면 면담의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":1,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"대면 면담의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담 대상자를 직접 만나 얼굴을 마주 보고 하는 면담","correct":true},{"t":"영상 통화나 전자 우편으로 주고받는 면담","mis":"K6-2-u2-X12"},{"t":"질문지를 보내 두고 답만 받아 오는 면담","mis":"K6-2-u2-X12"},{"t":"친구끼리 짝을 지어 연습하는 면담","mis":"K6-2-u2-X12"}],"explanation":["대면은 얼굴을 마주한다는 뜻이에요.","표정과 몸짓까지 볼 수 있어요.","영상 통화·전자 우편은 비대면 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#2','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'mc','auto','매체의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X08','K6-2-u2-X15']::text[],false,'{"seq":2,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"매체의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"소통을 이어 주는 도구와 환경","correct":true},{"t":"면담 대상자에게 드리는 선물","mis":"K6-2-u2-X12"},{"t":"면담에서 묻는 질문의 갈래","mis":"K6-2-u2-X08"},{"t":"면담이 끝나고 쓰는 글","mis":"K6-2-u2-X15"}],"explanation":["책·텔레비전·스마트폰·컴퓨터·누리집이 모두 매체예요.","사람과 사람의 소통을 이어 줘요.","면담에서는 절차마다 쓸모 있는 매체가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#3','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'ox','auto','말씀을 놓칠까 봐 걱정되면 허락을 받지 않고 녹음해도 괜찮아요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":3,"concept":"K6-2-u2-C7","difficulty":1,"kind":"ox","stem":"말씀을 놓칠까 봐 걱정되면 허락을 받지 않고 녹음해도 괜찮아요.","answer":"X","reason_options":[{"t":"담기 전에 먼저 여쭈어보고 허락을 받아야 하기 때문에","correct":true},{"t":"정확히 남기는 것이 무엇보다 중요하기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["담는 일에는 먼저 허락이 필요해요.","말없이 녹음하면 안 돼요.","그분의 허락 안에서만 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#4','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',1,'mc','auto','모둠 역할 가운데 기기를 준비하고 허락을 받아 담아 모둠과 나누는 사람은 누구인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":4,"concept":"K6-2-u2-C8","difficulty":1,"kind":"mc","stem":"모둠 역할 가운데 기기를 준비하고 허락을 받아 담아 모둠과 나누는 사람은 누구인가요?","options":[{"t":"매체 담당","correct":true},{"t":"진행 담당","mis":"K6-2-u2-X19"},{"t":"약속 담당","mis":"K6-2-u2-X19"},{"t":"정리 담당","mis":"K6-2-u2-X19"}],"explanation":["기기를 다루는 사람은 매체 담당이에요.","진행 담당은 시간을, 약속 담당은 날짜를 맡아요.","정리 담당은 메모와 보고서 자료를 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#5','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'match','auto','면담 절차와 그때 쓰는 매체의 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C7","difficulty":2,"kind":"match","stem":"면담 절차와 그때 쓰는 매체의 쓰임을 알맞게 이으세요.","pairs":[{"l":"면담 준비하기","r":"누리집과 책으로 필요한 자료를 찾는다"},{"l":"면담 진행하기","r":"녹음기로 담거나 영상 통화로 만난다"},{"l":"면담 정리하기","r":"담아 둔 것을 다시 들으며 중요한 것을 간추린다"}],"mis":"K6-2-u2-X12","explanation":["만나기 전에는 찾는 데 써요.","만나는 동안에는 담거나 이어 주는 데 써요.","만난 뒤에는 다시 들으며 간추리는 데 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#6','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'mc','auto','비대면 면담을 할 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X10']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"비대면 면담을 할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"기기 연결을 미리 확인하고, 말할 때는 렌즈를 보며, 말하지 않을 때는 마이크를 꺼 둔다","correct":true},{"t":"화면 속 내 얼굴만 보며 말한다","mis":"K6-2-u2-X12"},{"t":"마이크를 늘 켜 두고 다른 일을 한다","mis":"K6-2-u2-X10"},{"t":"연결은 면담이 시작된 뒤에 확인한다","mis":"K6-2-u2-X12"}],"explanation":["비대면은 기기를 거쳐 만나요.","연결을 미리 확인하고 렌즈를 보며 말해요.","말하지 않을 때는 마이크를 꺼 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#7','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','시후네 모둠이 정한 면담 목적 가운데 분명한 목적은 어느 것인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X01']::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"시후네 모둠이 정한 면담 목적 가운데 분명한 목적은 어느 것인가요?","options":[{"t":"우리 학교 식단이 정해지는 과정과 영양 교사가 하는 일을 알아보자","correct":true},{"t":"급식에 대해 이것저것 알아보자","mis":"K6-2-u2-X07"},{"t":"급식실에 한번 가 보자","mis":"K6-2-u2-X07"},{"t":"맛있는 반찬을 늘려 달라고 부탁하자","mis":"K6-2-u2-X01"}],"explanation":["목적이 흐리면 무엇을 물을지 정해지지 않아요.","「과정」과 「하는 일」처럼 알고 싶은 것을 콕 집어요.","분명한 목적이면 질문이 저절로 만들어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#8','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'mc','auto','배소윤 선생님이 「학교 과제에만 써 주면 좋겠어요」라고 하셨어요. 모둠이 지켜야 할 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":8,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"배소윤 선생님이 「학교 과제에만 써 주면 좋겠어요」라고 하셨어요. 모둠이 지켜야 할 것은 어느 것인가요?","options":[{"t":"담아 둔 것은 면담 보고서를 쓸 때만 쓰고 모둠 안에서만 나눈다","correct":true},{"t":"재미있는 부분을 잘라 친구에게 보낸다","mis":"K6-2-u2-X11"},{"t":"학교 누리집에 올려 모두 듣게 한다","mis":"K6-2-u2-X11"},{"t":"다른 과제에도 가져다 쓴다","mis":"K6-2-u2-X11"}],"explanation":["선생님은 담는 것을 허락하시며 쓰임을 정해 주셨어요.","담아 둔 것은 그 허락 안에서만 써요.","밖으로 내보내거나 다른 일에 쓰지 않아요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#9','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',2,'mc','auto','배소윤 선생님 면담을 정리 담당이 간추렸어요. 가장 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"배소윤 선생님 면담을 정리 담당이 간추렸어요. 가장 잘 간추린 것은 어느 것인가요?","options":[{"t":"영양을 먼저 놓고 그날 재료를 보아 식단을 짜며, 많이 남는 반찬은 재료보다 조리 방법을 바꾼다","correct":true},{"t":"들은 말을 처음부터 끝까지 한 마디도 빼지 않고 그대로 옮겨 적었다","mis":"K6-2-u2-X13"},{"t":"좋은 말씀을 많이 해 주셨다. 여러 가지를 생각하신다고 한다","mis":"K6-2-u2-X13"},{"t":"식단은 그날 들어오는 재료로만 정한다","mis":"K6-2-u2-X13"}],"explanation":["중요한 것이 남고 뜻이 이어져야 해요.","통째 옮기기나 뭉뚱그리기는 간추린 것이 아니에요.","「재료로만」은 답변의 뜻을 바꾼 것이에요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#10','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',3,'error','auto','매체를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":10,"concept":"K6-2-u2-C7","difficulty":3,"kind":"error","stem":"매체를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「허락은 녹음을 다 하고 나서 받아도 돼.」","correct":true,"mis_target":"K6-2-u2-X11"},{"t":"준서 — 「담기 전에 먼저 여쭈어보고 허락을 받아.」","mis":"K6-2-u2-X11"},{"t":"예린 — 「보고서를 다 쓴 뒤에는 밖으로 내보내지 않아.」","mis":"K6-2-u2-X11"}],"explanation":["허락은 담기 전에 받아요.","담아 둔 것은 보고서를 쓸 때만 써요.","준서와 예린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#1','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',2,'sa','auto','면담 내용을 간추리는 방법 가운데, 많은 내용에서 중요한 것을 고르는 방법을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C8","difficulty":2,"kind":"sa","stem":"면담 내용을 간추리는 방법 가운데, 많은 내용에서 중요한 것을 고르는 방법을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["선택"],"explanation":["간추리기에는 삭제·대체·선택·구성이 있어요.","중요한 것을 고르는 것이 선택이에요.","덜어 내는 것은 삭제예요."],"mis":"K6-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#2','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',2,'mc','auto','대면 면담과 비대면 면담 가운데 무엇으로 할지 정하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X19']::text[],false,'{"seq":2,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"대면 면담과 비대면 면담 가운데 무엇으로 할지 정하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담 대상자의 사정에 맞추어 정한다","correct":true},{"t":"대면이 언제나 더 좋으니 대면으로만 한다","mis":"K6-2-u2-X12"},{"t":"비대면이 편하니 언제나 비대면으로 한다","mis":"K6-2-u2-X12"},{"t":"모둠에서 목소리가 가장 큰 사람이 정한다","mis":"K6-2-u2-X19"}],"explanation":["둘 가운데 무엇이 더 좋다고 정해져 있지 않아요.","직접 뵐 수 있으면 대면, 어려우면 비대면이에요.","그분의 사정이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#3','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'match','auto','면담 내용을 간추리는 방법과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C8","difficulty":3,"kind":"match","stem":"면담 내용을 간추리는 방법과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"삭제","r":"중요하지 않은 것을 덜어 낸다"},{"l":"대체","r":"잘게 나뉜 내용을 하나로 묶는 말로 바꾼다"},{"l":"선택","r":"많은 내용 가운데 중요한 것을 고른다"},{"l":"구성","r":"흐릿한 것을 알아볼 수 있는 문장으로 새로 쓴다"}],"mis":"K6-2-u2-X13","explanation":["정리는 들은 말을 다 옮기는 것이 아니에요.","내가 이해한 것을 내 말로 다시 세워요.","네 방법을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#4','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C5',3,'mc','auto','하온의 「남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?」에서 알 수 있는 하온의 면담 태도는 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X10']::text[],false,'{"seq":4,"concept":"K6-2-u2-C5","difficulty":3,"kind":"mc","stem":"하온의 「남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?」에서 알 수 있는 하온의 면담 태도는 어느 것인가요?","options":[{"t":"답을 끝까지 듣고 그 안의 말을 붙들어 이어서 물었다","correct":true},{"t":"질문지에 적힌 차례대로 읽기만 했다","mis":"K6-2-u2-X06"},{"t":"면담 목적에서 벗어난 것을 물었다","mis":"K6-2-u2-X07"},{"t":"말씀 도중에 끼어들어 물었다","mis":"K6-2-u2-X10"}],"explanation":["「남기는 반찬」은 바로 앞 답에 나온 말이에요.","하온은 끝까지 듣고 그 말을 붙들었어요.","그래서 「조리 방법」이라는 중요한 답이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#5','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',3,'mc','auto','면담을 진행할 때 매체 담당이 할 일을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":5,"concept":"K6-2-u2-C7","difficulty":3,"kind":"mc","stem":"면담을 진행할 때 매체 담당이 할 일을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"기기를 준비한다 → 담아도 될지 여쭈어 허락을 받는다 → 담아 둔 것을 모둠과 나눈다","correct":true},{"t":"담는다 → 모둠과 나눈다 → 허락을 받는다","mis":"K6-2-u2-X11"},{"t":"허락을 받는다 → 누리집에 올린다 → 기기를 준비한다","mis":"K6-2-u2-X11"},{"t":"기기를 준비한다 → 담는다 → 친구들에게 퍼뜨린다","mis":"K6-2-u2-X11"}],"explanation":["기기는 미리 준비해요.","담기 전에 허락을 받아요.","담아 둔 것은 모둠 안에서만 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#6','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'error','auto','모둠 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":6,"concept":"K6-2-u2-C8","difficulty":3,"kind":"error","stem":"모둠 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「정리 담당은 면담 날짜와 장소를 정해 모둠에 알려.」","correct":true,"mis_target":"K6-2-u2-X19"},{"t":"소이 — 「진행 담당은 전 과정을 살피고 시간을 조절해.」","mis":"K6-2-u2-X19"},{"t":"이안 — 「질문 담당은 질문을 모아 다듬고 함께 물어.」","mis":"K6-2-u2-X19"}],"explanation":["날짜·시간·장소를 정하는 것은 약속 담당이에요.","정리 담당은 핵심을 메모하고 보고서 자료를 정리해요.","소이와 이안은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#7','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'ox','auto','면담이 두려운 친구는 면담 모둠에서 빠지는 것이 좋아요.',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":7,"concept":"K6-2-u2-C8","difficulty":3,"kind":"ox","stem":"면담이 두려운 친구는 면담 모둠에서 빠지는 것이 좋아요.","answer":"X","reason_options":[{"t":"지켜보기, 질문지 보며 읽기, 메모나 정리 맡기처럼 할 수 있는 만큼부터 함께하면 되기 때문에","correct":true},{"t":"모르는 어른께 말을 걸기 어려워하는 것은 잘못이기 때문에","mis":"K6-2-u2-X19"}],"mis":"K6-2-u2-X19","explanation":["말 걸기를 어려워하는 것은 잘못이 아니에요.","할 수 있는 만큼부터 시작하면 돼요.","다음번에는 질문 하나만 직접 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#8','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',4,'mc','auto','담아 둔 자료를 「내 것이 아니라 빌려 온 것」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":8,"concept":"K6-2-u2-C7","difficulty":4,"kind":"mc","stem":"담아 둔 자료를 「내 것이 아니라 빌려 온 것」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그분의 목소리와 말씀이 들어 있어 그분이 허락한 범위 안에서만 쓸 수 있기 때문에","correct":true},{"t":"녹음기를 다른 사람에게 빌렸기 때문에","mis":"K6-2-u2-X11"},{"t":"담아 둔 것은 곧 저절로 지워지기 때문에","mis":"K6-2-u2-X11"},{"t":"누리집에 올리면 모두의 것이 되기 때문에","mis":"K6-2-u2-X11"}],"explanation":["담아 둔 자료에는 그분의 목소리와 말씀이 있어요.","그래서 허락한 쓰임 안에서만 써요.","보고서를 쓸 때만 쓰고 밖으로 내보내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#9','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',4,'essay','teacher','우리 동네 도서관 사서 선생님과 면담한다고 할 때, 준비·진행·정리 절차마다 매체를 어떻게 쓸지 한 가지씩 쓰고, 녹음할 때 지켜야 할 것을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C7","difficulty":4,"kind":"essay","stem":"우리 동네 도서관 사서 선생님과 면담한다고 할 때, 준비·진행·정리 절차마다 매체를 어떻게 쓸지 한 가지씩 쓰고, 녹음할 때 지켜야 할 것을 두 가지 쓰세요.","answer_guide":{"answer":"예: 준비 — 도서관 누리집과 책에서 사서가 하는 일을 찾아 질문을 만든다. 진행 — 허락을 받아 녹음기로 담고, 직접 뵙기 어려우면 영상 통화로 면담한다. 정리 — 담아 둔 것을 다시 들으며 중요한 내용을 간추린다. 녹음할 때는 담기 전에 먼저 여쭈어 허락을 받고, 담아 둔 것은 보고서를 쓸 때만 쓰며 누리집이나 친구에게 내보내지 않는다.","scoring_points":["절차마다 알맞은 매체 쓰임을 한 가지씩 썼는가","담기 전에 허락을 받는다는 것을 썼는가","보고서에만 쓰고 밖으로 내보내지 않는다는 것을 썼는가"]},"explanation":["절차마다 매체 쓰임이 달라요.","허락이 먼저예요.","담아 둔 것은 빌려 온 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#10','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',4,'essay','teacher','배소윤 선생님 면담 장면을 읽고, 정리 담당이 되어 들은 내용을 두 문장으로 간추리세요. 간추릴 때 쓴 방법을 삭제·대체·선택·구성 가운데 두 가지 들어 밝히세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C8","difficulty":4,"kind":"essay","stem":"배소윤 선생님 면담 장면을 읽고, 정리 담당이 되어 들은 내용을 두 문장으로 간추리세요. 간추릴 때 쓴 방법을 삭제·대체·선택·구성 가운데 두 가지 들어 밝히세요.","answer_guide":{"answer":"예: 영양 교사는 자라는 나이에 필요한 영양을 먼저 놓고 그날 들어오는 재료를 보아 식단을 짠다. 많이 남는 반찬은 재료를 바꾸기보다 조리 방법을 바꾸는데, 남기는 까닭이 방법일 때가 많기 때문이다. 녹음 허락처럼 면담 내용과 상관없는 부분은 삭제하고, 여러 답 가운데 식단 짜는 차례와 남는 반찬 다루는 법을 선택했다.","scoring_points":["두 문장으로 중요한 내용을 간추렸는가","답변의 뜻을 바꾸지 않았는가","간추리기 방법 두 가지를 바르게 밝혔는가"]},"explanation":["중요한 것을 고르고 덜어 내요.","내 말로 다시 세워요.","뜻은 바꾸지 않아요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#1','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'mc','auto','면담 과정을 되돌아볼 때 나누어 적는 세 가지로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X15']::text[],false,'{"seq":1,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 과정을 되돌아볼 때 나누어 적는 세 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"잘한 점 · 보완할 점 · 더 알고 싶은 점","correct":true},{"t":"잘한 사람 · 못한 사람 · 늦은 사람","mis":"K6-2-u2-X14"},{"t":"재미있던 점 · 지루했던 점 · 배고팠던 점","mis":"K6-2-u2-X14"},{"t":"면담 날짜 · 시간 · 장소","mis":"K6-2-u2-X15"}],"explanation":["성찰은 세 가지로 나누어 적어요.","잘한 점, 보완할 점, 더 알고 싶은 점이에요.","사람을 가리거나 기분만 적지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#2','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'mc','auto','면담 보고서 앞부분에 담는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X11']::text[],false,'{"seq":2,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서 앞부분에 담는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담 목적과 대상자를 밝히고 준비 과정을 돌아본다","correct":true},{"t":"면담으로 새롭게 안 사실을 답변 중심으로 소개한다","mis":"K6-2-u2-X15"},{"t":"면담을 마친 뒤 깨달은 점을 밝힌다","mis":"K6-2-u2-X15"},{"t":"담아 둔 목소리 파일을 붙인다","mis":"K6-2-u2-X11"}],"explanation":["앞부분은 면담 전 이야기예요.","왜·누구를·어떻게 준비했는지 써요.","새로 안 사실은 가운데, 깨달은 점은 뒷부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#3','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'ox','auto','면담 과정을 되돌아보는 일은 누가 잘못했는지 가리는 일이에요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":3,"concept":"K6-2-u2-C9","difficulty":1,"kind":"ox","stem":"면담 과정을 되돌아보는 일은 누가 잘못했는지 가리는 일이에요.","answer":"X","reason_options":[{"t":"보완할 점을 다음 면담에서 실천할 약속으로 바꾸는 일이기 때문에","correct":true},{"t":"잘못한 사람을 알아야 다음에 그 사람을 빼고 할 수 있기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["사람을 가리키면 다음에 할 일이 남지 않아요.","「놓친 말이 있었다 → 둘이 나누어 메모하자」처럼 바꿔요.","끝은 「다음에 우리가 무엇을 할까」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#4','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'sa','auto','면담 보고서에서 면담으로 새롭게 알게 된 것을 소개하는 부분은 앞부분·가운데 부분·뒷부분 가운데 어디인가요?','{}'::text[],false,'{"seq":4,"concept":"K6-2-u2-C9","difficulty":1,"kind":"sa","stem":"면담 보고서에서 면담으로 새롭게 알게 된 것을 소개하는 부분은 앞부분·가운데 부분·뒷부분 가운데 어디인가요?","answer":["가운데 부분","가운데","가운데부분"],"explanation":["앞부분은 목적과 준비예요.","가운데 부분은 새롭게 안 사실이에요.","뒷부분은 깨달은 점과 달라진 생각이에요."],"mis":"K6-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#5','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'match','auto','면담 보고서의 부분과 담는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C9","difficulty":2,"kind":"match","stem":"면담 보고서의 부분과 담는 내용을 알맞게 이으세요.","pairs":[{"l":"앞부분","r":"왜 면담했는지, 누구를 만났는지, 어떻게 준비했는지"},{"l":"가운데 부분","r":"첫째·둘째·셋째로 나눈 새롭게 안 사실"},{"l":"뒷부분","r":"깨달은 점과 달라진 생각, 다음 약속"}],"mis":"K6-2-u2-X15","explanation":["세 부분이 하는 일이 달라요.","면담 전 이야기 → 들은 내용 → 면담 뒤 마음이에요.","차례대로 읽으면 면담이 한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#6','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','「따뜻한 밥상을 짓는 사람」 뒷부분의 「다음에는 급식을 남기기 전에 왜 남기는지 한 번 생각해 보려 합니다」가 하는 일은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":6,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"「따뜻한 밥상을 짓는 사람」 뒷부분의 「다음에는 급식을 남기기 전에 왜 남기는지 한 번 생각해 보려 합니다」가 하는 일은 어느 것인가요?","options":[{"t":"면담으로 달라진 내 생각과 실천을 밝힌다","correct":true},{"t":"모둠원이 맡은 역할을 알린다","mis":"K6-2-u2-X15"},{"t":"면담한 날짜와 시각을 기록한다","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 개인 정보를 알린다","mis":"K6-2-u2-X04"}],"explanation":["뒷부분은 면담 뒤의 마음을 써요.","무엇 때문에 무엇이 달라졌는지 밝혀요.","조리 방법 말씀 → 남기기 전에 생각하기예요."],"asset":{"type":"passage","lines":["급식이 그날 아침에 정해지는 것이 아니라","오래 앞서 준비되는 일이라는 것을 알았습니다.","남기는 반찬의 조리 방법을 다시 살피신다는 말씀이 가장 기억에 남습니다.","다음에는 급식을 남기기 전에 왜 남기는지 한 번 생각해 보려 합니다.","우리 모둠은 다음 면담에서 감사 인사를 끝까지 드리고 나오기로 약속했습니다."],"title":"「따뜻한 밥상을 짓는 사람」 뒷부분 — 새벽 모둠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#7','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','면담 과정을 되돌아볼 때 기준이 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담 과정을 되돌아볼 때 기준이 되는 것은 어느 것인가요?","options":[{"t":"예의를 지키며 답변을 끝까지 들었는가","correct":true},{"t":"누가 말을 더 많이 했는가","mis":"K6-2-u2-X14"},{"t":"목소리가 누가 더 컸는가","mis":"K6-2-u2-X14"},{"t":"옷차림이 단정했는가","mis":"K6-2-u2-X14"}],"explanation":["되돌아볼 때는 절차마다 무엇을 했는지 짚어요.","역할 실천 · 예의와 듣기 · 매체와 정리가 기준이에요.","겉모습은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#8','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C8',2,'mc','auto','보고서는 들은 말을 옮겨 적는 글이 아니에요. 그렇다고 해서 하면 안 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15']::text[],false,'{"seq":8,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"보고서는 들은 말을 옮겨 적는 글이 아니에요. 그렇다고 해서 하면 안 되는 것은 어느 것인가요?","options":[{"t":"답변의 뜻을 바꾸어 적는 것","correct":true},{"t":"덜 중요한 것을 덜어 내는 것","mis":"K6-2-u2-X13"},{"t":"중요한 것을 골라 내 말로 다시 세우는 것","mis":"K6-2-u2-X13"},{"t":"새로 안 사실을 첫째·둘째·셋째로 나누는 것","mis":"K6-2-u2-X15"}],"explanation":["줄이는 것과 바꾸는 것은 달라요.","덜어 내고 골라 내 말로 써도 돼요.","하지만 그분 말씀의 뜻을 바꾸면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#9','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','면담 보고서에 넣어도 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X11']::text[],false,'{"seq":9,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담 보고서에 넣어도 되는 것은 어느 것인가요?","options":[{"t":"면담을 마친 뒤 느낀 점","correct":true},{"t":"면담 대상자의 집 주소","mis":"K6-2-u2-X04"},{"t":"동의 없이 담아 둔 목소리 파일","mis":"K6-2-u2-X11"},{"t":"면담 대상자의 전화번호","mis":"K6-2-u2-X04"}],"explanation":["보고서에는 목적과 이어지고 알려도 되는 것만 넣어요.","목적·준비·새로 안 사실·느낀 점이 들어가요.","개인 정보와 동의 없는 자료는 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#10','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',3,'error','auto','모둠이 면담 과정을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":10,"concept":"K6-2-u2-C9","difficulty":3,"kind":"error","stem":"모둠이 면담 과정을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은재 — 「단우가 메모를 못 해서 면담을 망쳤어.」","correct":true,"mis_target":"K6-2-u2-X14"},{"t":"시온 — 「메모가 늦어 놓친 말이 있었으니 다음에는 둘이 나누어 메모하자.」","mis":"K6-2-u2-X14"},{"t":"다율 — 「담기 전에 허락을 받은 건 잘한 점이야.」","mis":"K6-2-u2-X14"}],"explanation":["성찰은 잘잘못을 가리는 일이 아니에요.","시온은 보완할 점을 다음 약속으로 바꾸었어요.","은재는 사람을 탓했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#1','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',2,'sa','auto','모둠 성찰에서는 세 가지에 하나를 더해 「다음 면담에서 ○○할 점」을 정해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C9","difficulty":2,"kind":"sa","stem":"모둠 성찰에서는 세 가지에 하나를 더해 「다음 면담에서 ○○할 점」을 정해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["실천"],"explanation":["잘한 점·보완할 점·더 알고 싶은 점에 하나를 더해요.","다음 면담에서 실천할 점이에요.","우리 모둠의 약속이 돼요."],"mis":"K6-2-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#2','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',2,'mc','auto','면담 보고서를 나누는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X15']::text[],false,'{"seq":2,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담 보고서를 나누는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"간추린 보고서를 알림판에 붙이고 면담 대상자께도 보여 드린다","correct":true},{"t":"담아 둔 목소리를 반 누리집에 함께 올린다","mis":"K6-2-u2-X11"},{"t":"우리 모둠만 보고 아무에게도 보여 주지 않는다","mis":"K6-2-u2-X15"},{"t":"다른 모둠 보고서는 읽지 않는다","mis":"K6-2-u2-X15"}],"explanation":["알게 된 것을 나누면 면담하지 않은 친구도 알게 돼요.","면담 대상자께 완성된 보고서를 보여 드려요.","담아 둔 목소리와 영상은 올리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#3','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'mc','auto','「따뜻한 밥상을 짓는 사람」 가운데 부분에서 새롭게 안 사실을 「첫째·둘째·셋째」로 나누어 쓴 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X08','K6-2-u2-X15']::text[],false,'{"seq":3,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"「따뜻한 밥상을 짓는 사람」 가운데 부분에서 새롭게 안 사실을 「첫째·둘째·셋째」로 나누어 쓴 까닭은 어느 것인가요?","options":[{"t":"들은 것이 많아도 한눈에 들어오게 하려고","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K6-2-u2-X13"},{"t":"면담에서 질문을 세 개만 했기 때문에","mis":"K6-2-u2-X08"},{"t":"보고서는 언제나 세 문단이어야 하기 때문에","mis":"K6-2-u2-X15"}],"explanation":["들은 것을 그대로 늘어놓으면 읽기 어려워요.","갈래로 나누어 적으면 한눈에 들어와요.","하는 일 · 어려운 점 · 보람처럼 나눌 수 있어요."],"asset":{"type":"passage","lines":["면담으로 새롭게 알게 된 것은 세 가지입니다.","첫째, 필요한 영양을 먼저 놓고 그다음에 그날 재료를 본다고 하셨습니다.","둘째, 많이 남는 반찬은 재료보다 조리 방법을 바꾼다고 하셨습니다.","남기는 까닭이 방법일 때가 많기 때문이라고 하셨습니다.","셋째, 모두의 입맛이 달라 한 끼로 모두를 맞출 수는 없고,","한 주 전체를 놓고 고르게 맞춘다고 하셨습니다."],"title":"「따뜻한 밥상을 짓는 사람」 가운데 부분 — 새벽 모둠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#4','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'mc','auto','「따뜻한 밥상을 짓는 사람」 가운데 부분의 셋째 사실로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":4,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"「따뜻한 밥상을 짓는 사람」 가운데 부분의 셋째 사실로 알맞은 것은 어느 것인가요?","options":[{"t":"모두의 입맛이 달라 한 주 전체를 놓고 고르게 맞춘다","correct":true},{"t":"많이 남는 반찬은 재료를 바꾼다","mis":"K6-2-u2-X13"},{"t":"식단은 그날 아침에 정한다","mis":"K6-2-u2-X13"},{"t":"한 끼로 모두의 입맛을 맞춘다","mis":"K6-2-u2-X13"}],"explanation":["셋째는 이 일에서 가장 어려운 점이에요.","한 끼로는 모두를 맞출 수 없어요.","그래서 한 주 전체를 놓고 맞춰요."],"asset":{"type":"passage","lines":["면담으로 새롭게 알게 된 것은 세 가지입니다.","첫째, 필요한 영양을 먼저 놓고 그다음에 그날 재료를 본다고 하셨습니다.","둘째, 많이 남는 반찬은 재료보다 조리 방법을 바꾼다고 하셨습니다.","남기는 까닭이 방법일 때가 많기 때문이라고 하셨습니다.","셋째, 모두의 입맛이 달라 한 끼로 모두를 맞출 수는 없고,","한 주 전체를 놓고 고르게 맞춘다고 하셨습니다."],"title":"「따뜻한 밥상을 짓는 사람」 가운데 부분 — 새벽 모둠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#5','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C8',3,'error','auto','면담 보고서를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15']::text[],false,'{"seq":5,"concept":"K6-2-u2-C8","difficulty":3,"kind":"error","stem":"면담 보고서를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「담아 둔 걸 처음부터 끝까지 그대로 옮겨 쓰면 가장 좋은 보고서야.」","correct":true,"mis_target":"K6-2-u2-X13"},{"t":"예솔 — 「중요한 것을 골라 내 말로 다시 세우되 뜻은 바꾸지 않아.」","mis":"K6-2-u2-X13"},{"t":"주원 — 「새롭게 안 사실은 갈래로 나누어 써.」","mis":"K6-2-u2-X15"}],"explanation":["통째로 옮기면 길기만 하고 무엇이 중요한지 몰라요.","골라서 덜어 내 말로 다시 세워요.","예솔과 주원은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#6','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'ox','auto','「아주 재미있었다. 다음에도 또 하고 싶다.」만 쓰면 보고서 뒷부분으로 충분해요.',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":6,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"「아주 재미있었다. 다음에도 또 하고 싶다.」만 쓰면 보고서 뒷부분으로 충분해요.","answer":"X","reason_options":[{"t":"무엇 때문에 무엇이 달라졌는지 적어야 읽는 사람에게 남는 것이 있기 때문에","correct":true},{"t":"뒷부분은 느낌만 짧게 적는 곳이기 때문에","mis":"K6-2-u2-X15"}],"mis":"K6-2-u2-X15","explanation":["느낌만 적은 글은 남는 것이 적어요.","어떤 말씀 때문에 생각이 어떻게 달라졌는지 써요.","다음에 실천할 것도 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#7','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'match','auto','새벽 모둠 친구들의 성찰 말과 성찰 항목을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":3,"kind":"match","stem":"새벽 모둠 친구들의 성찰 말과 성찰 항목을 알맞게 이으세요.","pairs":[{"l":"책과 누리집을 함께 찾아 질문을 만들었다","r":"잘한 점"},{"l":"감사 인사를 제대로 못 드리고 나왔다","r":"보완할 점"},{"l":"한 주 식단은 언제 짜시는지 궁금해졌다","r":"더 알고 싶은 점"}],"mis":"K6-2-u2-X14","explanation":["절차대로 해낸 것은 잘한 점이에요.","놓친 것은 보완할 점이에요.","답을 듣고 새로 생긴 궁금함은 더 알고 싶은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#8','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'mc','auto','성찰의 「보완할 점」을 「다음 면담에서 실천할 점」으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":8,"concept":"K6-2-u2-C9","difficulty":4,"kind":"mc","stem":"성찰의 「보완할 점」을 「다음 면담에서 실천할 점」으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"보완할 점: 질문지만 보고 읽었다 → 실천할 점: 답을 끝까지 듣고 궁금하면 이어서 묻자","correct":true},{"t":"보완할 점: 질문지만 보고 읽었다 → 실천할 점: 질문지를 읽은 사람은 다음에 빠지자","mis":"K6-2-u2-X14"},{"t":"보완할 점: 시간이 모자랐다 → 실천할 점: 다음에는 열심히 하자","mis":"K6-2-u2-X14"},{"t":"보완할 점: 감사 인사를 못 했다 → 실천할 점: 아쉬웠다","mis":"K6-2-u2-X14"}],"explanation":["실천할 점은 다음에 할 행동으로 써요.","사람을 빼거나 「열심히」처럼 막연하면 남지 않아요.","기분은 실천할 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#9','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'essay','teacher','내가 면담하고 싶은 분을 떠올려 면담 보고서 앞부분을 한 문단 쓰세요. 왜 면담하려는지, 누구를 만나려는지, 어떻게 준비할 것인지가 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"내가 면담하고 싶은 분을 떠올려 면담 보고서 앞부분을 한 문단 쓰세요. 왜 면담하려는지, 누구를 만나려는지, 어떻게 준비할 것인지가 드러나게 쓰세요.","answer_guide":{"answer":"예: 우리 모둠은 동네 도서관이 어떤 책을 들여오는지 알고 싶어, 도서관에서 일하시는 사서 선생님과 면담하기로 했습니다. 도서관에 자주 가는 제가 약속 담당을 맡아 먼저 찾아뵙고 허락을 구하려 합니다. 면담 전에 도서관 누리집과 책에서 사서가 하는 일을 찾아 두고, 그것을 바탕으로 질문을 세 갈래로 만들 것입니다.","scoring_points":["면담 목적을 밝혔는가","면담 대상자를 밝혔는가","준비 과정(허락·자료·질문·역할)을 썼는가"]},"explanation":["앞부분은 면담 전 이야기예요.","왜 · 누구 · 어떻게 준비가 드러나야 해요.","새로 안 사실은 가운데에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#10','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'essay','teacher','면담 보고서의 앞부분·가운데 부분·뒷부분이 각각 무엇을 담는지 쓰고, 보고서를 친구들과 나눌 때 나누어도 되는 것과 나누면 안 되는 것을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"면담 보고서의 앞부분·가운데 부분·뒷부분이 각각 무엇을 담는지 쓰고, 보고서를 친구들과 나눌 때 나누어도 되는 것과 나누면 안 되는 것을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 앞부분은 면담 목적과 대상자, 준비 과정을 담고, 가운데 부분은 면담으로 새롭게 안 사실을 갈래로 나누어 답변 중심으로 담고, 뒷부분은 면담을 마친 뒤 깨달은 점과 달라진 생각을 담는다. 내가 간추려 쓴 보고서는 나누어도 되지만, 동의 없이 담아 둔 목소리나 면담 대상자의 개인 정보는 나누면 안 된다.","scoring_points":["세 부분이 담는 내용을 바르게 썼는가","나누어도 되는 것을 바르게 들었는가","나누면 안 되는 것을 바르게 들었는가"]},"explanation":["앞 · 가운데 · 뒤가 하는 일이 달라요.","간추려 쓴 보고서는 함께 읽어요.","목소리 파일과 개인 정보는 나누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#1','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',1,'mc','auto','작품 속 인물이 되어 답할 때 근거로 삼아야 할 것은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":1,"concept":"K6-2-u2-C10","difficulty":1,"kind":"mc","stem":"작품 속 인물이 되어 답할 때 근거로 삼아야 할 것은 어느 것인가요?","options":[{"t":"작품 속 사건과 인물의 말과 행동","correct":true},{"t":"작품에 없어도 재미있을 것 같은 상상","mis":"K6-2-u2-X16"},{"t":"인물이 아닌 내 이야기","mis":"K6-2-u2-X16"},{"t":"친구가 듣고 싶어 하는 말","mis":"K6-2-u2-X16"}],"explanation":["답은 작품 안에서 나와야 해요.","사건·말·행동이 그대로 근거가 돼요.","마음대로 지어낸 답은 인물의 답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#2','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C4',1,'mc','auto','늘봄에게 하는 질문 「사람들이 처음 웃었을 때 그만두고 싶지는 않았나요?」는 어느 갈래의 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"늘봄에게 하는 질문 「사람들이 처음 웃었을 때 그만두고 싶지는 않았나요?」는 어느 갈래의 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 여는 인사","mis":"K6-2-u2-X05"}],"explanation":["그만두고 싶은 마음이 있었는지 묻고 있어요.","마음을 묻는 질문이에요.","인물에게도 세 갈래로 물을 수 있어요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#3','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',1,'ox','auto','늘봄이 되어 「사실 저는 종을 고치는 기술자였습니다.」라고 답해도 돼요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":3,"concept":"K6-2-u2-C10","difficulty":1,"kind":"ox","stem":"늘봄이 되어 「사실 저는 종을 고치는 기술자였습니다.」라고 답해도 돼요.","answer":"X","reason_options":[{"t":"이야기 어디에도 그런 말이 없어 인물의 답이 될 수 없기 때문에","correct":true},{"t":"재미있으면 인물의 답이 될 수 있기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["인물이 되어 답할 때는 이야기 안에서만 말해요.","이야기에 없는 것은 지어내지 않아요.","「그건 이야기에 나오지 않습니다」라고 해도 돼요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#4','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',1,'mc','auto','받침에 자음이 두 개 있는 것을 무엇이라고 하나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":4,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"받침에 자음이 두 개 있는 것을 무엇이라고 하나요?","options":[{"t":"겹받침","correct":true},{"t":"된소리","mis":"K6-2-u2-X18"},{"t":"모음","mis":"K6-2-u2-X18"},{"t":"높임말","mis":"K6-2-u2-X18"}],"explanation":["「맑다」의 ㄺ, 「넓다」의 ㄼ처럼 받침에 자음이 둘 있어요.","이것을 겹받침이라고 해요.","낱말 하나로 있을 때는 하나만 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#5','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','불쾌한 질문을 바람직한 질문으로 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":5,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"불쾌한 질문을 바람직한 질문으로 바르게 고친 것은 어느 것인가요?","options":[{"t":"「아무도 안 알아줘서 창피하지 않았어요?」 → 「사람들이 알아주지 않을 때 어떤 마음이 드셨나요?」","correct":true},{"t":"「그런 것도 몰랐던 거예요?」 → 「그런 것도 모르셨어요?」","mis":"K6-2-u2-X17"},{"t":"「왜 그렇게 바보 같은 짓을 했나요?」 → 「왜 그렇게 어리석은 짓을 하셨나요?」","mis":"K6-2-u2-X17"},{"t":"「창피했죠?」 → 「창피했다고 말해 주세요.」","mis":"K6-2-u2-X17"}],"explanation":["바람직한 질문은 궁금함과 배려를 함께 담아요.","깎아내리는 뜻을 빼고 마음을 헤아려 물어요.","높임만 바꾸거나 억지로 답하게 하면 고친 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#6','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','늘봄에게 「소리를 대신 내기로 마음먹은 까닭이 있었나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":6,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"늘봄에게 「소리를 대신 내기로 마음먹은 까닭이 있었나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?","options":[{"t":"종소리가 없어 마을 사람들의 시간이 어긋나는 것이 마음에 걸렸습니다","correct":true},{"t":"마을에서 상을 준다고 해서 시작했습니다","mis":"K6-2-u2-X16"},{"t":"종을 제가 깨뜨려서 혼날까 봐 그랬습니다","mis":"K6-2-u2-X16"},{"t":"나무판 두드리는 소리가 그냥 좋아서였습니다","mis":"K6-2-u2-X16"}],"explanation":["이야기에 종이 깨져 시간이 어긋났다고 나와요.","그 사건이 늘봄의 답을 받쳐 줘요.","상·깨뜨림은 이야기에 없는 내용이에요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#7','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'match','auto','늘봄에게 할 질문과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C10","difficulty":2,"kind":"match","stem":"늘봄에게 할 질문과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"나무판은 며칠 동안 두드리셨나요?","r":"구체적인 사실에 대한 질문"},{"l":"사람들이 다시 그 소리에 맞추어 하루를 열었을 때 어떠셨나요?","r":"생각이나 느낌에 대한 질문"},{"l":"남이 알아주지 않아도 무언가를 하려는 친구에게 해 줄 말이 있나요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["한 일을 묻는지 보아요.","마음을 묻는지 보아요.","남에게 줄 말을 묻는지 보아요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#8','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',2,'mc','auto','「비가 그치니 하늘이 맑아 보인다」에서 「맑아」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":2,"kind":"mc","stem":"「비가 그치니 하늘이 맑아 보인다」에서 「맑아」는 어떻게 소리 나나요?","options":[{"t":"[말가]","correct":true},{"t":"[마가]","mis":"K6-2-u2-X18"},{"t":"[막따]","mis":"K6-2-u2-X18"},{"t":"[말까]","mis":"K6-2-u2-X18"}],"explanation":["뒤에 모음 「아」가 붙었어요.","앞의 ㄹ은 받침으로 남고 뒤의 ㄱ이 넘어가 소리 나요.","그래서 [말가]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#9','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','바람직한 질문의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":9,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"바람직한 질문의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"궁금한 것을 묻되 상대의 마음을 헤아리고 답할 사람이 고를 여지를 남긴다","correct":true},{"t":"모자란 곳을 파고들어 묻는다","mis":"K6-2-u2-X17"},{"t":"말하고 싶지 않은 것도 꼭 답하게 한다","mis":"K6-2-u2-X17"},{"t":"깎아내리는 말로 재미있게 묻는다","mis":"K6-2-u2-X17"}],"explanation":["불쾌한 질문은 모자란 곳을 파고들거나 깎아내려요.","억지로 답하게 하는 것도 불쾌한 질문이에요.","바람직한 질문은 마음을 헤아리고 여지를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#10','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',3,'error','auto','짝과 늘봄 면담 놀이를 했어요. 늘봄이 되어 작품에 근거하지 않고 답한 친구는 누구인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":10,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"짝과 늘봄 면담 놀이를 했어요. 늘봄이 되어 작품에 근거하지 않고 답한 친구는 누구인가요?","options":[{"t":"하준 — 「(늘봄이 되어) 마을 사람들이 저에게 큰 상을 주었어요.」","correct":true,"mis_target":"K6-2-u2-X16"},{"t":"보미 — 「(늘봄이 되어) 처음에는 사람들이 웃었지만 사흘을 이어 갔어요.」","mis":"K6-2-u2-X16"},{"t":"지우 — 「(늘봄이 되어) 그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X16"}],"explanation":["이야기에 상을 받았다는 말은 없어요.","보미는 이야기 속 행동으로 답했어요.","지우처럼 없는 것은 없다고 말해도 돼요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#1','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',2,'sa','auto','「달이 밝은 밤」에서 「밝은」을 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C11","difficulty":2,"kind":"sa","stem":"「달이 밝은 밤」에서 「밝은」을 소리 나는 대로 쓰세요.","answer":["발근","[발근]"],"explanation":["「밝」 뒤에 모음 「은」이 붙었어요.","ㄹ은 받침으로 남고 ㄱ이 넘어가요.","그래서 [발근]으로 소리 나요."],"mis":"K6-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#2','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',2,'mc','auto','사람들 앞에서 묻고 답하는 것이 어려운 친구가 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X16']::text[],false,'{"seq":2,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"사람들 앞에서 묻고 답하는 것이 어려운 친구가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"먼저 지켜보거나, 질문지를 보며 읽거나, 질문을 만들어 주는 일을 맡는다","correct":true},{"t":"활동에서 빠지고 아무것도 하지 않는다","mis":"K6-2-u2-X19"},{"t":"부끄러운 일이니 억지로 크게 말한다","mis":"K6-2-u2-X19"},{"t":"인물 역할을 맡아 마음대로 답을 지어낸다","mis":"K6-2-u2-X16"}],"explanation":["어렵게 느끼는 것은 부끄러운 일이 아니에요.","할 수 있는 만큼부터 함께해요.","다음번에는 질문 하나만 직접 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#3','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',3,'mc','auto','밑줄 친 말의 발음이 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":3,"concept":"K6-2-u2-C11","difficulty":3,"kind":"mc","stem":"밑줄 친 말의 발음이 알맞은 것은 어느 것인가요?","options":[{"t":"「밑동이 굵은 편이다」의 「굵은」 → [굴근]","correct":true},{"t":"「해가 짧아 금방 어둡다」의 「짧아」 → [짜바]","mis":"K6-2-u2-X18"},{"t":"「운동장이 넓은 것 같다」의 「넓은」 → [너븐]","mis":"K6-2-u2-X18"},{"t":"「하늘이 맑아 보인다」의 「맑아」 → [마가]","mis":"K6-2-u2-X18"}],"explanation":["모음이 붙으면 앞 자음은 받침으로 남아요.","뒤 자음만 넘어가 소리 나요.","짧아[짤바] · 넓은[널븐] · 맑아[말가]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#4','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'mc','auto','인물이 되어 답해 보면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":4,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"인물이 되어 답해 보면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"답할 근거를 찾으려 이야기를 다시 읽게 되어 지나쳤던 작은 행동이 보인다","correct":true},{"t":"이야기를 다시 읽지 않아도 된다","mis":"K6-2-u2-X16"},{"t":"이야기에 없는 내용을 마음껏 지을 수 있다","mis":"K6-2-u2-X16"},{"t":"인물의 마음은 몰라도 된다","mis":"K6-2-u2-X16"}],"explanation":["은새는 「아무에게도 말하지 않고」가 눈에 들어왔다고 했어요.","그 한 마디로 늘봄의 마음을 짐작했어요.","인물이 되어 답하려면 작품을 다시 읽게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#5','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'error','auto','바람직한 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":5,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"바람직한 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"누리 — 「궁금하면 아무리 곤란한 것도 꼭 답하게 해야 해.」","correct":true,"mis_target":"K6-2-u2-X17"},{"t":"찬희 — 「답할 사람이 고를 여지를 남겨야 해.」","mis":"K6-2-u2-X17"},{"t":"하늘 — 「모자란 곳을 파고드는 질문은 고쳐 써야 해.」","mis":"K6-2-u2-X17"}],"explanation":["억지로 답하게 하는 질문은 불쾌한 질문이에요.","찬희와 하늘은 바르게 말했어요.","궁금함과 배려를 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#6','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'ox','auto','은새는 「아무에게도 말하지 않고」라는 말에서 늘봄의 마음을 짐작했어요. 이처럼 작은 표현도 인물이 되어 답하는 근거가 돼요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":6,"concept":"K6-2-u2-C10","difficulty":3,"kind":"ox","stem":"은새는 「아무에게도 말하지 않고」라는 말에서 늘봄의 마음을 짐작했어요. 이처럼 작은 표현도 인물이 되어 답하는 근거가 돼요.","answer":"O","reason_options":[{"t":"이야기 속 말과 행동이 인물의 답을 받쳐 주는 근거이기 때문에","correct":true},{"t":"인물의 답은 작품과 상관없이 정하기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["그냥 읽을 때는 작은 행동을 지나치기 쉬워요.","답하려고 보면 그 말이 근거로 살아나요.","근거는 언제나 작품 안에 있어요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#7','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',3,'match','auto','낱말과 그 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C11","difficulty":3,"kind":"match","stem":"낱말과 그 발음을 알맞게 이으세요.","pairs":[{"l":"맑다","r":"[막따]"},{"l":"맑아","r":"[말가]"},{"l":"넓다","r":"[널따]"},{"l":"넓은","r":"[널븐]"}],"mis":"K6-2-u2-X18","explanation":["낱말 하나로 있을 때는 하나만 소리 나요.","모음이 붙으면 뒤 자음이 넘어가요.","같은 겹받침도 뒤에 무엇이 오느냐에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#8','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',4,'mc','auto','「아무도 안 알아줘서 창피하지 않았어요?」를 바람직한 질문으로 고치고 늘봄이 되어 작품을 근거로 답한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X16']::text[],false,'{"seq":8,"concept":"K6-2-u2-C10","difficulty":4,"kind":"mc","stem":"「아무도 안 알아줘서 창피하지 않았어요?」를 바람직한 질문으로 고치고 늘봄이 되어 작품을 근거로 답한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"질문 「처음에 사람들이 웃었을 때 어떤 마음이 드셨나요?」 — 답 「서운했지만 아침이 어긋나는 게 더 마음에 걸려 사흘을 이어 갔어요.」","correct":true},{"t":"질문 「창피했다고 솔직히 말해 주세요.」 — 답 「네, 창피했어요.」","mis":"K6-2-u2-X17"},{"t":"질문 「처음에 사람들이 웃었을 때 어떤 마음이 드셨나요?」 — 답 「저는 종을 고치는 기술자라 괜찮았어요.」","mis":"K6-2-u2-X16"},{"t":"질문 「왜 그렇게 바보 같은 짓을 했나요?」 — 답 「상을 받고 싶었어요.」","mis":"K6-2-u2-X17"}],"explanation":["질문은 마음을 헤아려 고쳐요.","답은 「처음에는 웃었지만」, 「사흘이 지나자」 같은 이야기 속 사건에서 나와요.","둘 다 갖추어야 좋은 인물 면담이에요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#9','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',4,'essay','teacher','「종을 잃은 마을」의 늘봄에게 할 질문을 세 갈래로 하나씩 만들고, 그 가운데 하나를 골라 늘봄이 되어 작품을 근거로 답해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"「종을 잃은 마을」의 늘봄에게 할 질문을 세 갈래로 하나씩 만들고, 그 가운데 하나를 골라 늘봄이 되어 작품을 근거로 답해 보세요.","answer_guide":{"answer":"예: 사실 — 아침 소리를 내려고 무엇을 하셨나요? 생각이나 느낌 — 사람들이 처음에 웃었을 때 어떤 마음이 드셨나요? 계획이나 당부 — 혼자 무언가를 시작하려는 친구에게 해 줄 말이 있나요? 답(생각이나 느낌) — 처음에는 서운했어요. 그래도 종이 깨진 뒤 마을 사람들의 시간이 어긋나는 게 더 마음에 걸려서 아무에게도 말하지 않고 나무판을 계속 두드렸어요.","scoring_points":["세 갈래로 질문을 하나씩 만들었는가","질문이 불쾌하지 않고 바람직한가","작품 속 사건·행동을 근거로 답했는가"]},"explanation":["인물에게도 세 갈래로 물어요.","마음을 헤아리는 질문으로 써요.","답은 이야기 안에서만 찾아요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#10','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',4,'essay','teacher','「맑다」와 「넓다」를 낱말 하나로 읽을 때와 뒤에 모음으로 시작하는 말이 붙을 때 발음이 어떻게 달라지는지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C11","difficulty":4,"kind":"essay","stem":"「맑다」와 「넓다」를 낱말 하나로 읽을 때와 뒤에 모음으로 시작하는 말이 붙을 때 발음이 어떻게 달라지는지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 낱말 하나로 읽을 때는 겹받침 가운데 하나만 소리 나서 「맑다」는 [막따], 「넓다」는 [널따]로 읽는다. 뒤에 모음으로 시작하는 말이 붙으면 앞 자음은 받침으로 남고 뒤 자음이 넘어가 소리 나서 「맑아」는 [말가], 「넓은」은 [널븐]으로 읽는다.","scoring_points":["낱말 하나로 읽을 때 하나만 소리 남을 예와 함께 썼는가","모음이 붙을 때 뒤 자음이 넘어감을 예와 함께 썼는가","두 낱말의 발음을 바르게 적었는가"]},"explanation":["홀로 있을 때는 하나만 소리 나요.","모음이 오면 뒤 자음이 넘어가요.","맑아[말가] · 넓은[널븐]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#1','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C1',1,'mc','auto','면담에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"면담에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"정보를 얻으려는 목적이 있고 준비·진행·정리의 차례가 있는 대화이다","correct":true},{"t":"차례 없이 떠오르는 대로 나누는 이야기이다","mis":"K6-2-u2-X01"},{"t":"누가 더 많이 아는지 겨루는 대화이다","mis":"K6-2-u2-X01"},{"t":"누리집 글을 소리 내어 읽는 일이다","mis":"K6-2-u2-X02"}],"explanation":["면담은 목적이 있는 대화예요.","준비·진행·정리의 차례가 있어요.","겨루기나 낭독이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#2','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C2',1,'mc','auto','면담을 요청할 때 밝혀야 할 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"면담을 요청할 때 밝혀야 할 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"상대가 한 달에 버는 돈","correct":true},{"t":"우리가 누구인지","mis":"K6-2-u2-X03"},{"t":"면담을 하려는 목적","mis":"K6-2-u2-X03"},{"t":"걸리는 시간","mis":"K6-2-u2-X03"}],"explanation":["누구·목적·시간·날짜와 장소를 밝혀요.","그래야 상대가 응할지 정할 수 있어요.","버는 돈은 개인 정보라 묻지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#3','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',1,'mc','auto','면담 진행하기의 마지막 단계는 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담 진행하기의 마지막 단계는 어느 것인가요?","options":[{"t":"면담 마무리하기","correct":true},{"t":"면담 열기","mis":"K6-2-u2-X05"},{"t":"질문하기","mis":"K6-2-u2-X05"},{"t":"면담 보고서 쓰기","mis":"K6-2-u2-X05"}],"explanation":["진행하기는 열기 → 질문하기 → 마무리하기예요.","마무리에서 알게 된 것을 확인하고 감사 인사를 드려요.","보고서 쓰기는 정리하기에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#4','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',1,'mc','auto','소미의 질문 「책방에서 하루에 가장 많이 하시는 일은 무엇인가요?」는 어느 갈래인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"소미의 질문 「책방에서 하루에 가장 많이 하시는 일은 무엇인가요?」는 어느 갈래인가요?","options":[{"t":"구체적인 사실에 대한 질문","correct":true},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 마무리하는 말","mis":"K6-2-u2-X05"}],"explanation":["하루에 하는 일은 있는 그대로의 일이에요.","구체적인 사실에 대한 질문이에요.","마음이나 당부를 묻지 않았어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#5','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C6',1,'ox','auto','면담 대상자의 답이 마음에 들지 않으면 다시 답하게 해도 돼요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담 대상자의 답이 마음에 들지 않으면 다시 답하게 해도 돼요.","answer":"X","reason_options":[{"t":"시간을 내어 주신 분께 예의를 지키고 말씀을 존중해야 하기 때문에","correct":true},{"t":"원하는 답을 들어야 보고서를 쓸 수 있기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["답은 그분의 생각이에요.","다시 답하게 하는 것은 예의가 아니에요.","궁금하면 후속 질문으로 더 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#6','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',1,'mc','auto','비대면 면담의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"비대면 면담의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"직접 만나지 않고 영상 통화나 전자 우편으로 하는 면담","correct":true},{"t":"얼굴을 마주 보고 하는 면담","mis":"K6-2-u2-X12"},{"t":"면담 대상자 없이 혼자 질문만 써 보는 일","mis":"K6-2-u2-X12"},{"t":"녹음 없이 하는 면담","mis":"K6-2-u2-X12"}],"explanation":["비대면은 마주하지 않는다는 뜻이에요.","영상 통화·전자 우편으로 해요.","멀리 계신 분과도 면담할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#7','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',1,'mc','auto','면담 보고서 뒷부분에 담는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서 뒷부분에 담는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담을 마친 뒤 깨달은 점과 달라진 생각","correct":true},{"t":"면담 목적과 대상자","mis":"K6-2-u2-X15"},{"t":"면담으로 새롭게 안 사실","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 연락처","mis":"K6-2-u2-X04"}],"explanation":["뒷부분은 면담 뒤의 마음이에요.","목적·대상자는 앞부분, 새로 안 사실은 가운데예요.","연락처는 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#8','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C11',1,'mc','auto','「맑다」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「맑다」는 어떻게 소리 나나요?","options":[{"t":"[막따]","correct":true},{"t":"[말따]","mis":"K6-2-u2-X18"},{"t":"[말가]","mis":"K6-2-u2-X18"},{"t":"[맑따]","mis":"K6-2-u2-X18"}],"explanation":["낱말 하나로 있을 때 겹받침은 하나만 소리 나요.","「맑다」는 ㄱ이 소리 나요.","그래서 [막따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#9','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',2,'mc','auto','「책방을 꾸리는 사람」 면담에서 후속 질문은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X05']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"「책방을 꾸리는 사람」 면담에서 후속 질문은 어느 것인가요?","options":[{"t":"「방금 ‘우리 동네 사람들이 읽을 만한 책’이라고 하셨는데, 그건 어떻게 아시나요?」","correct":true},{"t":"「책방에서 하루에 가장 많이 하시는 일은 무엇인가요?」","mis":"K6-2-u2-X06"},{"t":"「책방을 하시며 가장 보람 있었던 때는 언제인가요?」","mis":"K6-2-u2-X06"},{"t":"「말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?」","mis":"K6-2-u2-X05"}],"explanation":["후속 질문은 앞선 답에 나온 말을 붙들어요.","예준은 「읽을 만한 책」을 붙들고 이어서 물었어요.","다른 질문은 미리 준비해 갈 수 있는 것이에요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#10','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',2,'match','auto','「책방을 꾸리는 사람」 면담 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C5","difficulty":2,"kind":"match","stem":"「책방을 꾸리는 사람」 면담 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.","pairs":[{"l":"녹음하고 싶은데 괜찮으실까요?","r":"면담 열기"},{"l":"하루에 가장 많이 하시는 일은 무엇인가요?","r":"질문하기"},{"l":"보고서가 나오면 보여 드리겠습니다. 감사합니다.","r":"면담 마무리하기"}],"mis":"K6-2-u2-X05","explanation":["동의 구하기는 면담 열기예요.","세 갈래 질문은 질문하기예요.","확인과 감사는 마무리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#11','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',2,'mc','auto','진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"담아 둔 녹음은 보고서를 쓸 때만 쓰고 모둠 밖으로 내보내지 않는다","correct":true},{"t":"재미있는 부분을 잘라 반 누리집에 올린다","mis":"K6-2-u2-X11"},{"t":"다른 반 친구에게도 들려준다","mis":"K6-2-u2-X11"},{"t":"다음 학년 과제에도 가져다 쓴다","mis":"K6-2-u2-X11"}],"explanation":["선생님은 허락하시며 쓰임을 정해 주셨어요.","담아 둔 것은 그 범위 안에서만 써요.","밖으로 내보내지 않아요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#12','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',2,'mc','auto','아침별 모둠의 면담 목적은 「동네 책방을 꾸려 가는 일과 그 일의 보람」을 알아보는 것이에요. 목적에서 벗어난 질문은 어느 것인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"아침별 모둠의 면담 목적은 「동네 책방을 꾸려 가는 일과 그 일의 보람」을 알아보는 것이에요. 목적에서 벗어난 질문은 어느 것인가요?","options":[{"t":"「가장 좋아하시는 음식은 무엇인가요?」","correct":true},{"t":"「책을 고르실 때 무엇을 가장 먼저 보시나요?」","mis":"K6-2-u2-X07"},{"t":"「책방을 하시며 힘들었던 때는 언제인가요?」","mis":"K6-2-u2-X07"},{"t":"「손님이 찾는 책이 없을 때는 어떻게 하시나요?」","mis":"K6-2-u2-X07"}],"explanation":["목적은 책방을 꾸리는 일과 보람이에요.","좋아하는 음식은 그 일을 알 수 있는 내용이 아니에요.","나머지는 목적과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#13','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C8',2,'mc','auto','「책방을 꾸리는 사람」 질문하기 부분을 가장 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"「책방을 꾸리는 사람」 질문하기 부분을 가장 잘 간추린 것은 어느 것인가요?","options":[{"t":"책방 주인은 손님의 모습을 보고 못 찾은 책을 적어 두어 동네 사람들이 읽을 만한 책을 고르고, 어릴 때 손님이 아이와 올 때 보람을 느낀다","correct":true},{"t":"소미가 묻고 선생님이 답하고 예준이 묻고 선생님이 답하고 소미가 또 물었다","mis":"K6-2-u2-X13"},{"t":"책방 이야기를 많이 해 주셨다. 여러 가지를 하신다","mis":"K6-2-u2-X13"},{"t":"책방 주인은 들어오는 책을 모두 놓는다","mis":"K6-2-u2-X13"}],"explanation":["중요한 것이 남고 뜻이 이어져야 해요.","순서 늘어놓기·뭉뚱그리기는 간추린 것이 아니에요.","「모두 놓는다」는 답변의 뜻을 바꾼 것이에요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#14','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C10',2,'mc','auto','「사흘 걸린 다리」의 태건에게 할 불쾌한 질문을 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"「사흘 걸린 다리」의 태건에게 할 불쾌한 질문을 바르게 고친 것은 어느 것인가요?","options":[{"t":"「혼자 돌 옮기는 거 바보 같지 않았어요?」 → 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」","correct":true},{"t":"「쌓은 돌이 무너졌을 때 울었죠?」 → 「울었다고 솔직히 말해 주세요.」","mis":"K6-2-u2-X17"},{"t":"「그것도 못 쌓았어요?」 → 「그것도 못 쌓으셨어요?」","mis":"K6-2-u2-X17"},{"t":"「왜 그렇게 쓸데없는 일을 했어요?」 → 「왜 그렇게 쓸모없는 일을 하셨어요?」","mis":"K6-2-u2-X17"}],"explanation":["깎아내리는 뜻을 빼고 까닭을 여쭈어요.","억지로 답하게 하면 안 돼요.","높임만 바꾸면 고친 것이 아니에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#15','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C2',2,'ox','auto','진다해 선생님께 「선생님 댁은 책방에서 가까운가요?」라고 여쭈어도 돼요.',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"ox","stem":"진다해 선생님께 「선생님 댁은 책방에서 가까운가요?」라고 여쭈어도 돼요.","answer":"X","reason_options":[{"t":"사는 곳은 알리고 싶지 않을 수 있는 개인 정보이기 때문에","correct":true},{"t":"책방과 집이 가까운지는 책방 일과 관련 있기 때문에","mis":"K6-2-u2-X04"}],"mis":"K6-2-u2-X04","explanation":["사는 곳은 개인 정보예요.","궁금해도 묻지 않아요.","하시는 일·보람처럼 목적과 이어진 것을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#16','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C8',2,'match','auto','모둠 역할과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"match","stem":"모둠 역할과 하는 일을 알맞게 이으세요.","pairs":[{"l":"약속 담당","r":"예의를 갖추어 날짜·시간·장소를 정하고 모둠에 알린다"},{"l":"질문 담당","r":"질문을 모아 다듬고 진행 담당을 도와 묻는다"},{"l":"정리 담당","r":"핵심을 메모하고 보고서에 쓸 자료를 정리한다"}],"mis":"K6-2-u2-X19","explanation":["날짜를 정하는 것은 약속 담당이에요.","질문을 다듬는 것은 질문 담당이에요.","글로 남기는 것은 정리 담당이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#17','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',3,'error','auto','「책방을 꾸리는 사람」 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":17,"concept":"K6-2-u2-C5","difficulty":3,"kind":"error","stem":"「책방을 꾸리는 사람」 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「예준은 질문지에 없는 걸 물었으니 면담 순서를 어긴 거야.」","correct":true,"mis_target":"K6-2-u2-X06"},{"t":"여울 — 「예준은 답을 끝까지 듣고 그 말을 붙들어 물었어.」","mis":"K6-2-u2-X06"},{"t":"하랑 — 「그 덕분에 책을 고르는 방법이라는 중요한 답이 나왔어.」","mis":"K6-2-u2-X06"}],"explanation":["질문지는 지도이지 대본이 아니에요.","듣다가 궁금해지면 이어서 물어도 돼요.","여울과 하랑은 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#18','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C10',3,'mc','auto','태건에게 「사흘째 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"태건에게 「사흘째 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?","options":[{"t":"「힘이 빠져 모래밭에 주저앉았어요.」","correct":true},{"t":"「바로 새 다리를 사러 읍내에 갔어요.」","mis":"K6-2-u2-X16"},{"t":"「돌이 흩어져서 오히려 기뻤어요.」","mis":"K6-2-u2-X16"},{"t":"「저는 원래 다리를 놓는 기술자라 괜찮았어요.」","mis":"K6-2-u2-X16"}],"explanation":["이야기에 「젖은 모래밭에 주저앉았다」가 나와요.","그 행동이 마음을 짐작하는 근거예요.","다른 보기는 이야기에 없는 내용이에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#19','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',3,'error','auto','아침별 모둠이 면담을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"error","stem":"아침별 모둠이 면담을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예준 — 「소미 목소리가 작아서 면담이 별로였어.」","correct":true,"mis_target":"K6-2-u2-X14"},{"t":"다온 — 「녹음 허락을 먼저 받은 건 잘한 점이야.」","mis":"K6-2-u2-X14"},{"t":"소미 — 「다음에는 질문을 더 짧게 하기로 하자.」","mis":"K6-2-u2-X14"}],"explanation":["성찰은 사람 탓이 아니에요.","목소리 크기 같은 겉모습은 기준이 아니에요.","다온과 소미는 절차와 약속을 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#20','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C6',3,'mc','auto','「책방 그거 장사 잘돼요? 손님 많아요 적어요 그리고 쉬는 날은요?」를 점검할 때 고칠 점을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X07','K6-2-u2-X08']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「책방 그거 장사 잘돼요? 손님 많아요 적어요 그리고 쉬는 날은요?」를 점검할 때 고칠 점을 바르게 모은 것은 어느 것인가요?","options":[{"t":"여러 가지를 한꺼번에 물어 뜻이 흐리고 높임을 갖추지 않았다","correct":true},{"t":"질문이 너무 짧고 공손하다","mis":"K6-2-u2-X10"},{"t":"목적과 이어지지 않는 날씨를 물었다","mis":"K6-2-u2-X07"},{"t":"사실을 물어서 쓸 수 없다","mis":"K6-2-u2-X08"}],"explanation":["한 번에 세 가지를 묻고 있어요.","「잘돼요?」처럼 높임도 부족해요.","하나씩 짧고 공손하게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#21','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',3,'error','auto','면담 절차를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"error","stem":"면담 절차를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「동의를 구하는 일은 면담을 다 마치고 마무리할 때 해.」","correct":true,"mis_target":"K6-2-u2-X05"},{"t":"승우 — 「동의는 면담 열기에서 구해.」","mis":"K6-2-u2-X05"},{"t":"보람 — 「알게 된 것 확인은 마무리에서 해.」","mis":"K6-2-u2-X05"}],"explanation":["담기 전에 동의를 구해야 하니 면담 열기에서 해요.","확인과 감사는 마무리에서 해요.","승우와 보람은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#22','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 보고서 가운데 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 보고서 가운데 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"첫째, 책은 손님이 내려놓는 모습과 못 찾은 책을 적어 둔 것을 보고 고른다고 하셨습니다.","correct":true},{"t":"우리 모둠은 책방 일이 궁금해 진다해 선생님과 면담하기로 했습니다.","mis":"K6-2-u2-X15"},{"t":"면담을 하며 책방이 사람을 오래 보는 곳이라는 것을 깨달았습니다.","mis":"K6-2-u2-X15"},{"t":"선생님 댁은 책방 바로 위층이라고 하셨습니다.","mis":"K6-2-u2-X04"}],"explanation":["가운데 부분은 새롭게 안 사실이에요.","첫째·둘째로 나누어 답변 중심으로 써요.","목적은 앞부분, 깨달은 점은 뒷부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#23','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C1',4,'mc','auto','「책방을 꾸리는 사람」 면담이 면담의 세 특성(정보·준비·예의)을 모두 갖춘 근거를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X02','K6-2-u2-X06']::text[],false,'{"seq":23,"concept":"K6-2-u2-C1","difficulty":4,"kind":"mc","stem":"「책방을 꾸리는 사람」 면담이 면담의 세 특성(정보·준비·예의)을 모두 갖춘 근거를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"정보 — 책을 고르는 방법과 보람을 들었다 / 준비 — 목적을 정하고 질문을 세 갈래로 만들었다 / 예의 — 감사·목적·동의로 열고 감사로 마무리했다","correct":true},{"t":"정보 — 선생님 나이를 알았다 / 준비 — 날짜를 정해 알려 드렸다 / 예의 — 녹음을 몰래 했다","mis":"K6-2-u2-X04"},{"t":"정보 — 책방 수를 알았다 / 준비 — 아무것도 찾지 않았다 / 예의 — 답을 끊고 물었다","mis":"K6-2-u2-X02"},{"t":"정보 — 재미있었다 / 준비 — 질문을 열 개 읽었다 / 예의 — 인사 없이 나왔다","mis":"K6-2-u2-X06"}],"explanation":["정보는 면담이라야 얻는 것이에요.","준비는 목적·질문, 예의는 열기와 마무리의 말이에요.","셋 다 면담 장면에서 근거를 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#24','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',4,'essay','teacher','내가 다니는 학교의 도서관 사서 선생님과 면담한다고 할 때, 면담 목적을 한 문장으로 쓰고 질문을 세 갈래로 하나씩 만드세요. 그중 한 질문에 선생님이 답하셨다고 생각하고 할 수 있는 후속 질문도 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C4","difficulty":4,"kind":"essay","stem":"내가 다니는 학교의 도서관 사서 선생님과 면담한다고 할 때, 면담 목적을 한 문장으로 쓰고 질문을 세 갈래로 하나씩 만드세요. 그중 한 질문에 선생님이 답하셨다고 생각하고 할 수 있는 후속 질문도 하나 쓰세요.","answer_guide":{"answer":"예: 목적 — 학교 도서관에 어떤 책을 어떻게 들여오는지 알아보려고. 사실 — 새 책은 한 해에 몇 번 들여오시나요? 생각이나 느낌 — 학생들이 빌려 간 책을 돌려주지 않을 때 어떤 마음이 드시나요? 계획이나 당부 — 앞으로 도서관에서 해 보고 싶은 일이 있으신가요? 후속 질문 — (「학생들이 신청한 책을 먼저 들여온다」는 답을 듣고) 신청한 책이 많을 때는 무엇을 보고 고르시나요?","scoring_points":["면담 목적을 분명하게 썼는가","세 갈래 질문을 목적에 맞게 하나씩 만들었는가","앞선 답을 붙든 후속 질문을 썼는가"]},"explanation":["목적이 분명하면 질문이 저절로 나와요.","세 갈래를 고루 만들어요.","후속 질문은 답의 말을 붙들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#25','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',4,'essay','teacher','「책방을 꾸리는 사람」 면담을 면담 진행하기의 세 단계로 나누어, 단계마다 아침별 모둠이 한 일을 면담 장면에서 찾아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C3","difficulty":4,"kind":"essay","stem":"「책방을 꾸리는 사람」 면담을 면담 진행하기의 세 단계로 나누어, 단계마다 아침별 모둠이 한 일을 면담 장면에서 찾아 쓰세요.","answer_guide":{"answer":"예: 면담 열기 — 다온이 바쁘신데 시간 내어 주셔서 감사하다고 인사하고, 예준이 책방을 꾸려 가는 일과 보람을 여쭙겠다고 목적을 밝혔으며, 다온이 녹음해도 괜찮은지 동의를 구했다. 질문하기 — 소미가 하루에 가장 많이 하는 일과 보람 있었던 때를 묻고, 예준이 「읽을 만한 책」을 어떻게 아는지 이어서 물었다. 면담 마무리하기 — 다온이 책을 고르는 일이 손님을 오래 보는 일이라는 말씀을 확인하고 감사 인사를 드렸다.","scoring_points":["세 단계로 바르게 나누었는가","단계마다 한 일을 면담 장면에서 찾아 썼는가","열기의 인사·목적·동의와 마무리의 확인·감사를 빠뜨리지 않았는가"]},"explanation":["열기 · 질문하기 · 마무리하기로 나눠요.","장면 속 말을 근거로 써요.","단계마다 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#1','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C1',1,'mc','auto','책방 주인 진다해 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"책방 주인 진다해 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?","options":[{"t":"책방을 하시며 가장 보람 있었던 때는 언제인가요?","correct":true},{"t":"「책방」이라는 낱말의 사전 뜻은 무엇인가요?","mis":"K6-2-u2-X02"},{"t":"우리나라에 책방은 모두 몇 곳인가요?","mis":"K6-2-u2-X02"},{"t":"올해 가장 많이 팔린 책의 제목은 무엇인가요?","mis":"K6-2-u2-X02"}],"explanation":["보람 있었던 때는 그분만 아는 겪은 일이에요.","사전 뜻·수·판매 순위는 찾아보면 나와요.","면담이라야 얻는 것이 생생한 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#2','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C2',1,'mc','auto','면담 대상자께 물어도 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"면담 대상자께 물어도 되는 것은 어느 것인가요?","options":[{"t":"그 일을 하게 된 까닭","correct":true},{"t":"사시는 곳","mis":"K6-2-u2-X04"},{"t":"나이","mis":"K6-2-u2-X04"},{"t":"가족이 몇 명인지","mis":"K6-2-u2-X04"}],"explanation":["물어도 되는 것은 목적과 이어진 것이에요.","하시는 일·까닭·어려운 점·보람 같은 것이에요.","사는 곳·나이·가족은 개인 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#3','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',1,'mc','auto','면담 정리하기에서 하는 일은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담 정리하기에서 하는 일은 어느 것인가요?","options":[{"t":"담아 둔 것과 메모로 내용을 간추리고 과정을 성찰해 보고서를 쓴다","correct":true},{"t":"목적에 알맞은 자료를 찾고 질문을 만든다","mis":"K6-2-u2-X05"},{"t":"동의를 구하고 목적에 맞게 묻는다","mis":"K6-2-u2-X05"},{"t":"대상자에게 면담을 요청한다","mis":"K6-2-u2-X05"}],"explanation":["정리하기는 만난 뒤에 해요.","간추리기 · 성찰하기 · 보고서 쓰기예요.","자료 찾기와 요청은 준비, 묻기는 진행이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#4','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C4',1,'mc','auto','예준의 질문 「책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?」는 어느 갈래인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"예준의 질문 「책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?」는 어느 갈래인가요?","options":[{"t":"앞으로의 계획이나 당부에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적을 밝히는 말","mis":"K6-2-u2-X05"}],"explanation":["뒷사람에게 해 줄 말을 묻고 있어요.","당부에 대한 질문이에요.","면담 끝 무렵에 묻기 좋아요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#5','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',1,'ox','auto','면담을 마친 뒤에는 알게 된 것을 확인하고 감사 인사를 드려요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담을 마친 뒤에는 알게 된 것을 확인하고 감사 인사를 드려요.","answer":"O","reason_options":[{"t":"면담 마무리하기에서 결과를 확인하고 감사 인사를 하기 때문에","correct":true},{"t":"감사 인사는 보고서에만 쓰면 되기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["마무리에서 알게 된 것을 확인해요.","시간을 내어 주신 데 감사드려요.","다온도 그렇게 마무리했어요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#6','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',1,'mc','auto','면담 준비하기에서 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X11']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"면담 준비하기에서 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"누리집과 책에서 필요한 자료를 찾는다","correct":true},{"t":"담아 둔 것을 다시 들으며 간추린다","mis":"K6-2-u2-X12"},{"t":"녹음기로 대답을 담는다","mis":"K6-2-u2-X12"},{"t":"보고서를 누리집에 올린다","mis":"K6-2-u2-X11"}],"explanation":["준비할 때는 자료를 찾는 데 써요.","담기는 진행, 다시 듣기는 정리에서 해요.","절차마다 쓰임이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#7','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',1,'mc','auto','「다음에는 감사 인사를 끝까지 드리고 나오자.」는 성찰의 어느 항목인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X15']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"「다음에는 감사 인사를 끝까지 드리고 나오자.」는 성찰의 어느 항목인가요?","options":[{"t":"다음 면담에서 실천할 점","correct":true},{"t":"잘한 점","mis":"K6-2-u2-X14"},{"t":"더 알고 싶은 점","mis":"K6-2-u2-X14"},{"t":"면담 목적","mis":"K6-2-u2-X15"}],"explanation":["다음에 할 행동을 정했어요.","보완할 점을 바꾼 실천할 점이에요.","모둠의 약속이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#8','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C11',1,'mc','auto','「넓다」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「넓다」는 어떻게 소리 나나요?","options":[{"t":"[널따]","correct":true},{"t":"[넙따]","mis":"K6-2-u2-X18"},{"t":"[널븐]","mis":"K6-2-u2-X18"},{"t":"[너따]","mis":"K6-2-u2-X18"}],"explanation":["「넓다」는 낱말 하나로 있어요.","겹받침 ㄼ 가운데 ㄹ만 소리 나요.","그래서 [널따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#9','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C5',2,'mc','auto','진다해 선생님의 답 「무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X02']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"진다해 선생님의 답 「무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?","options":[{"t":"「공책에 적어 두신 것은 책을 고를 때 어떻게 쓰이나요?」","correct":true},{"t":"「다음 질문입니다. 책방 이름은 누가 지었나요?」","mis":"K6-2-u2-X06"},{"t":"「점심은 어디서 드시나요?」","mis":"K6-2-u2-X07"},{"t":"「우리나라 사람들은 한 해에 책을 몇 권 읽나요?」","mis":"K6-2-u2-X02"}],"explanation":["앞선 답의 「공책에 적어 두지요」를 붙들었어요.","더 자세히 알려고 이어서 물었어요.","답을 듣지 않았다면 만들 수 없는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#10','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',2,'mc','auto','다온과 예준이 면담 열기에서 한 일을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X06','K6-2-u2-X04']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"다온과 예준이 면담 열기에서 한 일을 바르게 모은 것은 어느 것인가요?","options":[{"t":"인사와 감사 · 면담 목적 밝히기 · 녹음 동의 구하기","correct":true},{"t":"인사와 감사 · 알게 된 것 확인하기 · 보고서 쓰기","mis":"K6-2-u2-X05"},{"t":"녹음 동의 구하기 · 질문 열 개 읽기 · 헤어지기","mis":"K6-2-u2-X06"},{"t":"목적 밝히기 · 선생님 나이 여쭙기 · 사는 곳 여쭙기","mis":"K6-2-u2-X04"}],"explanation":["다온이 인사와 감사를 드렸어요.","예준이 목적을 밝히고 다온이 녹음 동의를 구했어요.","면담 열기의 세 가지를 모두 갖추었어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#11','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',2,'mc','auto','진다해 선생님이 멀리 이사 가셔서 직접 뵙기 어렵다면 알맞은 면담 방식은 어느 것인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X02','K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"진다해 선생님이 멀리 이사 가셔서 직접 뵙기 어렵다면 알맞은 면담 방식은 어느 것인가요?","options":[{"t":"영상 통화로 하는 비대면 면담","correct":true},{"t":"허락 없이 책방 앞에서 기다리는 대면 면담","mis":"K6-2-u2-X03"},{"t":"면담을 하지 않고 누리집 글만 옮기기","mis":"K6-2-u2-X02"},{"t":"전화를 걸어 바로 녹음부터 하기","mis":"K6-2-u2-X11"}],"explanation":["대면이 어려우면 비대면으로 정해요.","영상 통화나 전자 우편으로 할 수 있어요.","그분의 사정에 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#12','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C4',2,'mc','auto','아침별 모둠이 미리 찾은 자료가 「동네 책방은 주인이 고른 책을 놓는다」였어요. 이 자료를 바탕으로 더 깊이 물은 질문은 어느 것인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X07']::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"아침별 모둠이 미리 찾은 자료가 「동네 책방은 주인이 고른 책을 놓는다」였어요. 이 자료를 바탕으로 더 깊이 물은 질문은 어느 것인가요?","options":[{"t":"「책을 고르실 때 어떤 기준으로 고르시나요?」","correct":true},{"t":"「책방은 무엇을 하는 곳인가요?」","mis":"K6-2-u2-X02"},{"t":"「책방에는 책이 있나요?」","mis":"K6-2-u2-X02"},{"t":"「책방은 몇 시에 문을 닫나요?」","mis":"K6-2-u2-X07"}],"explanation":["찾아 둔 자료로 「주인이 고른다」는 것을 알았어요.","그래서 「무슨 일 하세요?」 대신 고르는 기준을 물었어요.","자료를 찾으면 한 걸음 더 깊이 물을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#13','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',2,'mc','auto','면담 내용을 간추리다가 「책을 다 놓을 수는 없어서」를 「책을 다 놓는다」로 적었다면 무엇이 잘못되었나요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"면담 내용을 간추리다가 「책을 다 놓을 수는 없어서」를 「책을 다 놓는다」로 적었다면 무엇이 잘못되었나요?","options":[{"t":"줄인 것이 아니라 답변의 뜻을 바꾸었다","correct":true},{"t":"너무 짧게 줄였다","mis":"K6-2-u2-X13"},{"t":"중요하지 않은 것을 덜어 냈다","mis":"K6-2-u2-X13"},{"t":"내 말로 다시 세웠다","mis":"K6-2-u2-X13"}],"explanation":["줄이는 것과 바꾸는 것은 달라요.","「다 놓을 수는 없어서」와 「다 놓는다」는 뜻이 반대예요.","간추려도 뜻은 그대로여야 해요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#14','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C10',2,'mc','auto','태건에게 하는 질문 가운데 바람직한 질문은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"태건에게 하는 질문 가운데 바람직한 질문은 어느 것인가요?","options":[{"t":"「쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요?」","correct":true},{"t":"「돌이 흩어진 건 쌓는 방법이 엉터리라서죠?」","mis":"K6-2-u2-X17"},{"t":"「주저앉은 거 창피하지 않았어요?」","mis":"K6-2-u2-X17"},{"t":"「아무도 안 도와준 건 친구가 없어서예요?」","mis":"K6-2-u2-X17"}],"explanation":["바람직한 질문은 마음을 헤아려요.","모자란 곳을 파고들지 않아요.","답할 사람이 고를 여지를 남겨요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#15','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C2',2,'mc','auto','아침별 모둠이 진다해 선생님께 면담을 부탁드리는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X04']::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"아침별 모둠이 진다해 선생님께 면담을 부탁드리는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「저희는 6학년 아침별 모둠입니다. 책방을 꾸리는 일을 여쭙고 싶은데, 삼십 분쯤 다음 주에 괜찮으신 때가 있을까요?」","correct":true},{"t":"「내일 세 시에 갈게요. 그때 몇 가지 물어볼게요.」","mis":"K6-2-u2-X03"},{"t":"「뭐 좀 물어보려고요. 아무 때나 알아서 말씀해 주세요.」","mis":"K6-2-u2-X03"},{"t":"「선생님 나이랑 사시는 곳도 여쭤봐도 되죠?」","mis":"K6-2-u2-X04"}],"explanation":["누구·목적·시간·날짜를 밝혀요.","정해서 알리지 않고 여쭈어 맞추어요.","개인 정보는 묻지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#16','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',2,'mc','auto','면담의 전 과정을 살피고 시간을 조절하는 역할은 어느 것인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"면담의 전 과정을 살피고 시간을 조절하는 역할은 어느 것인가요?","options":[{"t":"진행 담당","correct":true},{"t":"매체 담당","mis":"K6-2-u2-X19"},{"t":"약속 담당","mis":"K6-2-u2-X19"},{"t":"정리 담당","mis":"K6-2-u2-X19"}],"explanation":["진행 담당은 면담 전체의 흐름을 맡아요.","시간이 모자라거나 넘치지 않게 조절해요.","기기는 매체 담당이 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#17','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',3,'error','auto','면담 예절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":17,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"면담 예절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「설명을 길게 붙여 물어야 상대가 잘 알아들어.」","correct":true,"mis_target":"K6-2-u2-X10"},{"t":"민호 — 「질문은 짧고 분명하게 해.」","mis":"K6-2-u2-X10"},{"t":"지안 — 「말씀 도중에는 끊지 말고 메모해 둬.」","mis":"K6-2-u2-X10"}],"explanation":["설명이 길면 무엇을 묻는지 흐려져요.","질문은 짧게 해요.","민호와 지안은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#18','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C10',3,'mc','auto','상우 아저씨에게 「왜 지게를 지고 오셨나요?」라고 물었을 때 작품에 근거한 답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"상우 아저씨에게 「왜 지게를 지고 오셨나요?」라고 물었을 때 작품에 근거한 답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「혼자 돌을 옮기던 태건이 주저앉은 것을 보고 함께하려고 왔어요.」","correct":true},{"t":"「나라에서 다리를 놓으라고 시켜서 왔어요.」","mis":"K6-2-u2-X16"},{"t":"「제 밭에 가는 길이 막혀서 화가 나서 왔어요.」","mis":"K6-2-u2-X16"},{"t":"「돈을 받기로 해서 왔어요.」","mis":"K6-2-u2-X16"}],"explanation":["태건이 주저앉은 「그때」 아저씨가 왔어요.","「나도 좀 하자.」에 함께하려는 마음이 보여요.","나라·돈은 이야기에 없어요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#19','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 성찰 가운데 「더 알고 싶은 점」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 성찰 가운데 「더 알고 싶은 점」으로 알맞은 것은 어느 것인가요?","options":[{"t":"공책에 적은 못 찾은 책을 실제로 들여놓으시는지 궁금해졌다","correct":true},{"t":"녹음 허락을 먼저 받았다","mis":"K6-2-u2-X14"},{"t":"감사 인사를 서둘러 드렸다","mis":"K6-2-u2-X14"},{"t":"예준이 질문을 너무 많이 했다","mis":"K6-2-u2-X14"}],"explanation":["더 알고 싶은 점은 답을 듣고 새로 생긴 궁금함이에요.","허락은 잘한 점, 서두른 인사는 보완할 점이에요.","사람을 가리키는 말은 성찰이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#20','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',3,'mc','auto','「손님 줄면 망하는 거 아니에요?」를 점검해 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X04']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「손님 줄면 망하는 거 아니에요?」를 점검해 바르게 고친 것은 어느 것인가요?","options":[{"t":"「손님이 줄었을 때는 어떻게 하시나요?」","correct":true},{"t":"「손님 줄면 망하시는 거 아니에요?」","mis":"K6-2-u2-X17"},{"t":"「망하면 어떡하실 거예요? 꼭 말해 주세요.」","mis":"K6-2-u2-X17"},{"t":"「손님은 하루에 몇 명이에요? 돈은요?」","mis":"K6-2-u2-X04"}],"explanation":["「망하는」은 깎아내리는 말이에요.","예의를 갖추고 목적에 맞게 고쳐요.","어떻게 하시는지 여쭈면 그분의 일을 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#21','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',3,'mc','auto','아침별 모둠의 준비 과정을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"아침별 모둠의 준비 과정을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"목적 정하기 → 대상자 정하기 → 자료 찾기 → 질문 만들기 → 요청하고 허락 구하기","correct":true},{"t":"질문 만들기 → 목적 정하기 → 자료 찾기 → 대상자 정하기 → 요청하기","mis":"K6-2-u2-X05"},{"t":"요청하기 → 목적 정하기 → 질문 만들기 → 대상자 정하기 → 자료 찾기","mis":"K6-2-u2-X05"},{"t":"자료 찾기 → 요청하기 → 목적 정하기 → 대상자 정하기 → 질문 만들기","mis":"K6-2-u2-X05"}],"explanation":["목적이 맨 먼저예요.","대상자를 정하고 자료를 찾아 질문을 만들어요.","그다음 요청하고 허락을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#22','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 보고서 앞부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X11']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 보고서 앞부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 모둠은 동네 책방을 꾸리는 일이 궁금해, 책방 주인 진다해 선생님과 면담을 했습니다.","correct":true},{"t":"어릴 때 오던 손님이 아이와 왔을 때 보람을 느끼신다고 하셨습니다.","mis":"K6-2-u2-X15"},{"t":"다음에는 책을 살 때 주인이 고른 까닭을 생각해 보려 합니다.","mis":"K6-2-u2-X15"},{"t":"녹음 파일은 반 누리집에서 들을 수 있습니다.","mis":"K6-2-u2-X11"}],"explanation":["앞부분은 왜·누구를·어떻게 준비했는지예요.","보람은 가운데, 다음 다짐은 뒷부분이에요.","녹음 파일은 나누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#23','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C5',4,'mc','auto','아침별 모둠이 「책을 고른다」는 답을 듣고 후속 질문을 하지 않고 바로 다음 질문으로 넘어갔다면 어떻게 되었을까요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X11']::text[],false,'{"seq":23,"concept":"K6-2-u2-C5","difficulty":4,"kind":"mc","stem":"아침별 모둠이 「책을 고른다」는 답을 듣고 후속 질문을 하지 않고 바로 다음 질문으로 넘어갔다면 어떻게 되었을까요?","options":[{"t":"손님의 모습을 보고 못 찾은 책을 적어 둔다는 가장 중요한 답을 듣지 못했을 것이다","correct":true},{"t":"면담 시간이 짧아져 더 좋은 면담이 되었을 것이다","mis":"K6-2-u2-X06"},{"t":"목적에서 벗어난 이야기로 흘러갔을 것이다","mis":"K6-2-u2-X07"},{"t":"녹음 허락을 받지 못했을 것이다","mis":"K6-2-u2-X11"}],"explanation":["후속 질문은 질문지에 없는 물음이에요.","예준의 후속 질문 덕분에 중요한 답이 나왔어요.","답을 끝까지 듣고 이어서 묻는 것이 면담의 깊이를 정해요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#24','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',4,'essay','teacher','「책방을 꾸리는 사람」 면담을 바탕으로 아침별 모둠의 면담 보고서 가운데 부분을 쓰세요. 새롭게 안 사실을 「첫째·둘째」로 나누어 답변 중심으로 쓰되 답변의 뜻을 바꾸지 마세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"「책방을 꾸리는 사람」 면담을 바탕으로 아침별 모둠의 면담 보고서 가운데 부분을 쓰세요. 새롭게 안 사실을 「첫째·둘째」로 나누어 답변 중심으로 쓰되 답변의 뜻을 바꾸지 마세요.","answer_guide":{"answer":"예: 면담으로 새롭게 알게 된 것은 두 가지입니다. 첫째, 책방에서 하루에 가장 많이 하시는 일은 책을 고르는 일입니다. 들어오는 책을 다 놓을 수는 없어서, 손님이 책을 고르다 내려놓는 모습을 보고 못 찾은 책을 여쭈어 공책에 적어 두었다가 동네 사람들이 읽을 만한 책을 고른다고 하셨습니다. 둘째, 가장 보람 있었던 때는 어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때라고 하셨습니다.","scoring_points":["새롭게 안 사실을 첫째·둘째로 나누어 썼는가","면담 답변을 중심으로 간추려 썼는가","답변의 뜻을 바꾸지 않았는가"]},"explanation":["가운데 부분은 새롭게 안 사실이에요.","갈래로 나누면 한눈에 들어와요.","줄이되 뜻은 바꾸지 않아요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#25','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',4,'essay','teacher','「책방을 꾸리는 사람」 질문하기 부분을 두 문장으로 간추리고, 간추리면서 덜어 낸 것과 고른 것을 각각 하나씩 밝히세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C8","difficulty":4,"kind":"essay","stem":"「책방을 꾸리는 사람」 질문하기 부분을 두 문장으로 간추리고, 간추리면서 덜어 낸 것과 고른 것을 각각 하나씩 밝히세요.","answer_guide":{"answer":"예: 책방 주인은 들어오는 책을 다 놓을 수 없어서, 손님이 내려놓는 모습과 못 찾은 책을 적어 둔 것을 보고 동네 사람들이 읽을 만한 책을 고른다. 가장 보람 있었던 때는 어릴 때 오던 손님이 커서 자기 아이와 왔을 때이다. 누가 어떤 차례로 물었는지는 덜어 냈고(삭제), 여러 답 가운데 책을 고르는 방법과 보람을 골랐다(선택).","scoring_points":["두 문장으로 중요한 내용을 간추렸는가","답변의 뜻을 바꾸지 않았는가","덜어 낸 것과 고른 것을 바르게 밝혔는가"]},"explanation":["중요한 것을 골라요.","덜 중요한 것은 덜어 내요.","뜻은 그대로 내 말로 써요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#1','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C1',1,'ox','auto','면담에서는 면담하는 사람이 답하는 사람보다 훨씬 많이 말해야 해요.',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"ox","stem":"면담에서는 면담하는 사람이 답하는 사람보다 훨씬 많이 말해야 해요.","answer":"X","reason_options":[{"t":"답하는 쪽이 훨씬 많이 말하고 면담자는 잘 묻고 잘 듣는 사람이기 때문에","correct":true},{"t":"묻는 사람이 많이 말해야 면담을 이끌 수 있기 때문에","mis":"K6-2-u2-X01"}],"mis":"K6-2-u2-X01","explanation":["일상 대화는 주고받는 양이 비슷해요.","면담은 답하는 쪽이 훨씬 많이 말해요.","면담자는 잘 묻고 잘 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#2','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C2',1,'ox','auto','면담을 부탁드릴 때 「아무 때나 괜찮으니까 알아서 말씀해 주세요.」라고만 하면 충분해요.',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"ox","stem":"면담을 부탁드릴 때 「아무 때나 괜찮으니까 알아서 말씀해 주세요.」라고만 하면 충분해요.","answer":"X","reason_options":[{"t":"누구인지·목적·걸리는 시간·바라는 날짜를 함께 밝혀야 상대가 정할 수 있기 때문에","correct":true},{"t":"날짜를 상대가 정하게 했으니 예의를 다 갖춘 것이기 때문에","mis":"K6-2-u2-X03"}],"mis":"K6-2-u2-X03","explanation":["무엇을 물을지, 얼마나 걸릴지 모르면 정하기 어려워요.","누구 · 왜 · 얼마나 · 언제를 넣어요.","그다음 상대의 사정에 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#3','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',1,'ox','auto','면담 준비하기에서는 목적을 정한 뒤에 대상자를 정해요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"ox","stem":"면담 준비하기에서는 목적을 정한 뒤에 대상자를 정해요.","answer":"O","reason_options":[{"t":"무엇을 알고 싶은지가 정해져야 누구를 만날지 정할 수 있기 때문에","correct":true},{"t":"대상자를 먼저 정해야 목적을 아무렇게나 정할 수 있기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["목적이 맨 먼저예요.","목적에 맞는 분을 대상자로 정해요.","그다음 방식·자료·질문·역할·요청이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#4','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C4',1,'mc','auto','소미의 질문 「책방을 하시며 가장 보람 있었던 때는 언제인가요?」는 어느 갈래인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"소미의 질문 「책방을 하시며 가장 보람 있었던 때는 언제인가요?」는 어느 갈래인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 여는 인사","mis":"K6-2-u2-X05"}],"explanation":["보람은 그 일을 하며 느낀 마음이에요.","생각이나 느낌에 대한 질문이에요.","그분의 마음까지 들을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#5','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C6',1,'mc','auto','면담 열기에서 다온이 한 말 「바쁘신데 시간 내어 주셔서 감사합니다.」에 담긴 예의는 어느 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X11']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"mc","stem":"면담 열기에서 다온이 한 말 「바쁘신데 시간 내어 주셔서 감사합니다.」에 담긴 예의는 어느 것인가요?","options":[{"t":"시간을 내어 주신 데 감사하기","correct":true},{"t":"면담 목적 밝히기","mis":"K6-2-u2-X05"},{"t":"담기 전에 동의 구하기","mis":"K6-2-u2-X11"},{"t":"알게 된 것 확인하기","mis":"K6-2-u2-X05"}],"explanation":["면담 열기에는 인사·감사·목적·동의가 들어가요.","다온은 시간을 내어 주신 데 감사드렸어요.","목적은 예준이 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#6','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',1,'ox','auto','담아 둔 면담 녹음은 친구들이 궁금해하면 나누어 주어도 돼요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"ox","stem":"담아 둔 면담 녹음은 친구들이 궁금해하면 나누어 주어도 돼요.","answer":"X","reason_options":[{"t":"담아 둔 것은 보고서를 쓸 때만 쓰고 밖으로 내보내지 않기 때문에","correct":true},{"t":"친구들도 면담 내용을 알면 좋기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["담아 둔 자료는 빌려 온 것이에요.","그분의 허락 안에서만 써요.","친구들과는 간추린 보고서를 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#7','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',1,'ox','auto','면담 과정을 되돌아볼 때는 막연한 기분보다 절차마다 무엇을 했는지 짚어 봐요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"ox","stem":"면담 과정을 되돌아볼 때는 막연한 기분보다 절차마다 무엇을 했는지 짚어 봐요.","answer":"O","reason_options":[{"t":"절차마다 한 일을 짚어야 잘한 점과 보완할 점이 드러나기 때문에","correct":true},{"t":"기분이 좋았으면 잘한 면담이기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["「좋았다」, 「별로였다」로는 다음에 할 일이 남지 않아요.","준비·진행·정리마다 짚어요.","그래야 보완할 점이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#8','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C11',1,'mc','auto','「짧다」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「짧다」는 어떻게 소리 나나요?","options":[{"t":"[짤따]","correct":true},{"t":"[짭따]","mis":"K6-2-u2-X18"},{"t":"[짤바]","mis":"K6-2-u2-X18"},{"t":"[짜따]","mis":"K6-2-u2-X18"}],"explanation":["낱말 하나로 있을 때는 하나만 소리 나요.","「짧다」는 ㄹ이 소리 나요.","그래서 [짤따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#9','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C5',2,'ox','auto','예준의 「그건 어떻게 아시나요?」는 질문지에 미리 적어 간 질문이에요.',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"ox","stem":"예준의 「그건 어떻게 아시나요?」는 질문지에 미리 적어 간 질문이에요.","answer":"X","reason_options":[{"t":"앞선 답에 나온 「우리 동네 사람들이 읽을 만한 책」을 듣고 이어서 물은 후속 질문이기 때문에","correct":true},{"t":"「어떻게」로 묻는 질문은 모두 미리 준비하는 질문이기 때문에","mis":"K6-2-u2-X06"}],"mis":"K6-2-u2-X06","explanation":["예준은 답을 끝까지 들었어요.","그 안의 말을 붙들어 이어서 물었어요.","후속 질문은 듣고 있어야만 나와요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#10','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',2,'mc','auto','다온이 마무리에서 「책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다.」라고 한 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"다온이 마무리에서 「책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다.」라고 한 까닭은 어느 것인가요?","options":[{"t":"면담 결과를 확인하려고","correct":true},{"t":"새로운 질문을 시작하려고","mis":"K6-2-u2-X05"},{"t":"녹음 동의를 구하려고","mis":"K6-2-u2-X05"},{"t":"면담 목적을 처음 밝히려고","mis":"K6-2-u2-X05"}],"explanation":["마무리에서는 알게 된 것을 확인해요.","그다음 감사 인사를 드려요.","목적·동의는 면담 열기에서 해요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#11','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',2,'mc','auto','아침별 모둠이 면담을 정리할 때 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X12','K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"아침별 모둠이 면담을 정리할 때 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"담아 둔 녹음을 다시 들으며 중요한 내용을 간추린다","correct":true},{"t":"녹음을 그대로 보고서에 붙인다","mis":"K6-2-u2-X13"},{"t":"누리집에서 책방 자료를 처음 찾는다","mis":"K6-2-u2-X12"},{"t":"녹음을 친구에게 보내 대신 정리하게 한다","mis":"K6-2-u2-X11"}],"explanation":["정리할 때는 담아 둔 것을 다시 들어요.","중요한 것을 골라 간추려요.","자료 찾기는 준비할 때 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#12','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C4',2,'ox','auto','「책방 하시면 돈은 많이 버시나요?」는 아침별 모둠이 물어도 되는 질문이에요.',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"ox","stem":"「책방 하시면 돈은 많이 버시나요?」는 아침별 모둠이 물어도 되는 질문이에요.","answer":"X","reason_options":[{"t":"버는 돈은 알리고 싶지 않을 수 있는 개인 정보이고 목적과 이어지지 않기 때문에","correct":true},{"t":"책방을 꾸리는 일과 관련 있는 질문이기 때문에","mis":"K6-2-u2-X04"}],"mis":"K6-2-u2-X04","explanation":["목적과 이어진 듯해도 개인 정보예요.","「이 질문을 내가 받으면 어떨까?」 되짚어 봐요.","보람이나 어려운 점을 묻는 것으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#13','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C8',2,'mc','auto','간추리기 방법 가운데 「잘게 나뉜 내용을 하나로 묶는 말로 바꾸기」는 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"간추리기 방법 가운데 「잘게 나뉜 내용을 하나로 묶는 말로 바꾸기」는 어느 것인가요?","options":[{"t":"대체","correct":true},{"t":"삭제","mis":"K6-2-u2-X13"},{"t":"선택","mis":"K6-2-u2-X13"},{"t":"구성","mis":"K6-2-u2-X13"}],"explanation":["삭제는 덜어 내기, 선택은 고르기예요.","구성은 알아볼 수 있는 문장으로 새로 쓰기예요.","하나로 묶는 말로 바꾸는 것이 대체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#14','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C10',2,'ox','auto','「그런 것도 몰랐던 거예요?」는 상대의 마음을 헤아린 바람직한 질문이에요.',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"ox","stem":"「그런 것도 몰랐던 거예요?」는 상대의 마음을 헤아린 바람직한 질문이에요.","answer":"X","reason_options":[{"t":"모자란 곳을 파고들어 깎아내리는 뜻이 드러나는 불쾌한 질문이기 때문에","correct":true},{"t":"궁금한 것을 솔직하게 물었기 때문에","mis":"K6-2-u2-X17"}],"mis":"K6-2-u2-X17","explanation":["「그런 것도」에 깎아내리는 뜻이 있어요.","상대가 불쾌해져 답이 깊어지지 않아요.","「그때는 어떻게 아셨나요?」처럼 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#15','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C2',2,'mc','auto','면담 질문을 만든 뒤 「이 질문을 내가 받으면 어떨까」 되짚어 보는 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"면담 질문을 만든 뒤 「이 질문을 내가 받으면 어떨까」 되짚어 보는 까닭은 어느 것인가요?","options":[{"t":"상대가 알리고 싶지 않거나 답하기 곤란한 질문을 덜어 내려고","correct":true},{"t":"질문을 더 길게 늘이려고","mis":"K6-2-u2-X04"},{"t":"질문 수를 셋으로 맞추려고","mis":"K6-2-u2-X08"},{"t":"질문을 재미있게 바꾸려고","mis":"K6-2-u2-X07"}],"explanation":["궁금하다고 다 물어도 되는 것은 아니에요.","받는 사람 쪽에서 생각해 보아요.","불편한 질문은 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#16','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C8',2,'ox','auto','아침별 모둠에서 녹음 기기를 준비하고 허락을 받아 담는 일은 정리 담당이 맡아요.',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"ox","stem":"아침별 모둠에서 녹음 기기를 준비하고 허락을 받아 담는 일은 정리 담당이 맡아요.","answer":"X","reason_options":[{"t":"기기를 준비하고 허락받아 담아 모둠과 나누는 것은 매체 담당이 하는 일이기 때문에","correct":true},{"t":"녹음한 것을 정리하니까 정리 담당이 맡기 때문에","mis":"K6-2-u2-X19"}],"mis":"K6-2-u2-X19","explanation":["매체 담당이 기기와 담기를 맡아요.","정리 담당은 메모와 보고서 자료를 맡아요.","역할이 나뉘어야 면담이 흘러가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#17','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C5',3,'error','auto','좋은 면담을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X06']::text[],false,'{"seq":17,"concept":"K6-2-u2-C5","difficulty":3,"kind":"error","stem":"좋은 면담을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도담 — 「준비는 필요 없어. 가서 떠오르는 대로 물으면 돼.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"이서 — 「준비한 질문으로 길을 잡아야 해.」","mis":"K6-2-u2-X07"},{"t":"윤호 — 「듣다가 생긴 물음으로 깊이 들어가야 해.」","mis":"K6-2-u2-X06"}],"explanation":["준비 없이 가면 목적에서 벗어난 이야기로 흘러가요.","준비한 질문으로 길을 잡고 후속 질문으로 깊이 들어가요.","이서와 윤호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#18','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C10',3,'ox','auto','태건이 되어 「할머니가 시켜서 돌을 옮겼어요.」라고 답하는 것은 작품에 근거한 답이에요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"ox","stem":"태건이 되어 「할머니가 시켜서 돌을 옮겼어요.」라고 답하는 것은 작품에 근거한 답이에요.","answer":"X","reason_options":[{"t":"이야기에는 태건이 「혼자」 돌을 굴려 올렸다고만 나오고 할머니가 시켰다는 말이 없기 때문에","correct":true},{"t":"할머니의 밭에 가는 길이니 할머니가 시켰을 것이기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["이야기 안에서만 답해요.","「어느 날 아침 태건은 혼자」라고 나와요.","없는 내용을 짐작으로 지어내지 않아요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#19','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',3,'mc','auto','「질문을 길게 해서 선생님이 다시 물으셨다.」를 다음 면담에서 실천할 점으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X10']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"「질문을 길게 해서 선생님이 다시 물으셨다.」를 다음 면담에서 실천할 점으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"다음에는 질문을 하나씩 짧고 분명하게 하자","correct":true},{"t":"다음에는 질문을 길게 한 사람은 빠지자","mis":"K6-2-u2-X14"},{"t":"다음에는 열심히 하자","mis":"K6-2-u2-X14"},{"t":"다음에도 길게 묻되 더 빨리 말하자","mis":"K6-2-u2-X10"}],"explanation":["실천할 점은 다음에 할 행동이에요.","사람을 빼거나 막연하면 남지 않아요.","짧고 분명하게 묻는 것이 약속이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#20','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C6',3,'ox','auto','질문을 점검할 때는 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」를 살펴요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"ox","stem":"질문을 점검할 때는 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」를 살펴요.","answer":"O","reason_options":[{"t":"이 세 가지가 맞아야 상대가 편하게 알아듣고 목적에 맞는 답을 줄 수 있기 때문에","correct":true},{"t":"질문 개수가 열 개를 넘는지가 가장 중요하기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["개수나 재미는 기준이 아니에요.","목적 · 예의 · 명료함을 봐요.","점검한 뒤 고쳐서 가져가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#21','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',3,'match','auto','면담 절차와 그때 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"match","stem":"면담 절차와 그때 할 일을 알맞게 이으세요.","pairs":[{"l":"면담 준비하기","r":"목적에 알맞은 자료를 찾고 질문을 만들며 약속을 잡는다"},{"l":"면담 진행하기","r":"동의를 구하고 목적에 맞게 물으며 답변을 예의 바르게 듣는다"},{"l":"면담 정리하기","r":"담아 둔 것과 메모로 간추리고 과정을 성찰해 보고서를 쓴다"}],"mis":"K6-2-u2-X05","explanation":["만나기 전에는 준비해요.","만나는 동안에는 진행해요.","만난 뒤에는 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#22','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 보고서 뒷부분을 가장 잘 쓴 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X14']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 보고서 뒷부분을 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"책을 고르는 일이 손님을 오래 보는 일이라는 말씀을 듣고, 앞으로는 책방에서 주인이 고른 까닭을 생각하며 책을 보기로 했다","correct":true},{"t":"아주 재미있었다. 또 가고 싶다.","mis":"K6-2-u2-X15"},{"t":"면담은 네 시에 시작해 네 시 반에 끝났다.","mis":"K6-2-u2-X15"},{"t":"소미가 질문을 잘 못해서 아쉬웠다.","mis":"K6-2-u2-X14"}],"explanation":["뒷부분은 무엇 때문에 무엇이 달라졌는지 써요.","느낌·시각만 적으면 남는 것이 적어요.","사람 탓은 보고서에 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#23','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',4,'mc','auto','아침별 모둠이 매체를 고려하여 면담했다고 할 수 있는 근거를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X13','K6-2-u2-X12']::text[],false,'{"seq":23,"concept":"K6-2-u2-C7","difficulty":4,"kind":"mc","stem":"아침별 모둠이 매체를 고려하여 면담했다고 할 수 있는 근거를 바르게 모은 것은 어느 것인가요?","options":[{"t":"준비할 때 자료를 찾고, 진행할 때 허락을 받아 녹음하고, 정리할 때 다시 들으며 간추리고 녹음은 모둠 과제에만 쓴다","correct":true},{"t":"허락 없이 녹음하고, 녹음을 누리집에 올려 모두 듣게 한다","mis":"K6-2-u2-X11"},{"t":"자료는 찾지 않고, 녹음을 그대로 보고서에 붙인다","mis":"K6-2-u2-X13"},{"t":"대면이 더 좋으니 선생님이 멀리 계셔도 꼭 찾아간다","mis":"K6-2-u2-X12"}],"explanation":["매체는 절차마다 쓰임이 달라요.","담기 전에 허락, 쓰임은 허락 안에서예요.","정리할 때 다시 들으며 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#24','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',4,'essay','teacher','진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 녹음을 담기 전·담은 뒤·보고서를 나눌 때 각각 지켜야 할 것을 쓰고, 그렇게 해야 하는 까닭을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C7","difficulty":4,"kind":"essay","stem":"진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 녹음을 담기 전·담은 뒤·보고서를 나눌 때 각각 지켜야 할 것을 쓰고, 그렇게 해야 하는 까닭을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 담기 전에는 먼저 여쭈어 허락을 받는다. 담은 뒤에는 녹음을 보고서를 쓸 때만 쓰고 모둠 안에서만 나눈다. 보고서를 나눌 때는 간추려 쓴 보고서만 나누고 녹음 파일은 올리지 않는다. 담아 둔 녹음에는 선생님의 목소리와 말씀이 들어 있어 내 것이 아니라 빌려 온 것이므로 선생님이 허락한 범위 안에서만 써야 하기 때문이다.","scoring_points":["담기 전 허락을 썼는가","담은 뒤 보고서에만 쓰고 밖으로 내보내지 않음을 썼는가","빌려 온 것이라는 까닭을 썼는가"]},"explanation":["허락이 먼저예요.","보고서에만 쓰고 밖으로 내보내지 않아요.","담아 둔 것은 빌려 온 것이에요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#25','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',4,'essay','teacher','아침별 모둠이 면담을 되돌아본다고 할 때, 면담 장면을 근거로 잘한 점·보완할 점·더 알고 싶은 점을 하나씩 쓰고, 보완할 점을 다음 면담에서 실천할 점으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"아침별 모둠이 면담을 되돌아본다고 할 때, 면담 장면을 근거로 잘한 점·보완할 점·더 알고 싶은 점을 하나씩 쓰고, 보완할 점을 다음 면담에서 실천할 점으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 면담 열기에서 녹음 동의를 먼저 구했고, 예준이 답을 듣고 후속 질문을 했다. 보완할 점 — 진다해 선생님이 하신 당부를 메모로 남기지 못했다. 더 알고 싶은 점 — 공책에 적은 못 찾은 책을 실제로 들여놓으시는지 궁금하다. 실천할 점 — 다음 면담에서는 정리 담당과 질문 담당이 나누어 메모하자.","scoring_points":["면담 장면을 근거로 세 항목을 하나씩 썼는가","사람 탓이 아니라 절차를 짚어 썼는가","보완할 점을 구체적인 실천할 점으로 바꾸었는가"]},"explanation":["절차마다 무엇을 했는지 짚어요.","사람이 아니라 일을 봐요.","보완할 점은 다음 약속이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#1','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C1',1,'sa','auto','면담의 세 가지 특성 「○○ · 준비 · 예의」에서 ○○에 알맞은 두 글자를 쓰세요. (대화를 주고받는 과정에서 얻는 것)','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"sa","stem":"면담의 세 가지 특성 「○○ · 준비 · 예의」에서 ○○에 알맞은 두 글자를 쓰세요. (대화를 주고받는 과정에서 얻는 것)","answer":["정보"],"explanation":["면담으로 얻는 것은 정보예요.","만나기 전에는 준비, 만나는 동안에는 예의예요.","셋이 함께 있어야 면담이에요."],"mis":"K6-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#2','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C2',1,'sa','auto','면담을 부탁드릴 때 어느 방법이든 먼저 상대에게 구해야 하는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"sa","stem":"면담을 부탁드릴 때 어느 방법이든 먼저 상대에게 구해야 하는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["허락"],"explanation":["찾아가기·전화·전자 우편·누리집 글이 있어요.","방법은 달라도 먼저 허락을 구해요.","허락 없이 찾아가면 면담이 시작되지 않아요."],"mis":"K6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#3','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',1,'sa','auto','면담의 세 절차는 「면담 준비하기 → 면담 ○○하기 → 면담 정리하기」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"sa","stem":"면담의 세 절차는 「면담 준비하기 → 면담 ○○하기 → 면담 정리하기」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["진행"],"explanation":["만나기 전에 준비해요.","만나는 동안 진행해요.","만난 뒤에 정리해요."],"mis":"K6-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#4','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C4',1,'ox','auto','면담 질문은 사실·생각이나 느낌·앞으로의 계획이나 당부의 세 갈래로 골고루 만드는 것이 좋아요.',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"ox","stem":"면담 질문은 사실·생각이나 느낌·앞으로의 계획이나 당부의 세 갈래로 골고루 만드는 것이 좋아요.","answer":"O","reason_options":[{"t":"갈래가 다르면 얻는 것이 달라 면담이 한쪽으로 치우치지 않기 때문에","correct":true},{"t":"질문 수를 꼭 셋으로 맞추어야 하기 때문에","mis":"K6-2-u2-X08"}],"mis":"K6-2-u2-X08","explanation":["사실만 물으면 자료 읽기와 같아요.","마음과 앞일도 함께 물어요.","세 갈래가 고루 있어야 알찬 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#5','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',1,'mc','auto','진로 자료를 고를 때 먼저 확인할 것은 어느 것인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"mc","stem":"진로 자료를 고를 때 먼저 확인할 것은 어느 것인가요?","options":[{"t":"누가 언제 만든 자료인지","correct":true},{"t":"사진이 몇 장 있는지","mis":"K6-2-u2-X09"},{"t":"검색했을 때 몇 번째로 나오는지","mis":"K6-2-u2-X09"},{"t":"글씨가 얼마나 큰지","mis":"K6-2-u2-X09"}],"explanation":["믿을 만한 출처인지가 먼저예요.","누가·언제 만들었는지 밝혀져야 해요.","사진·순서·글씨 크기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#6','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',1,'sa','auto','소통을 이어 주는 도구와 환경을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"sa","stem":"소통을 이어 주는 도구와 환경을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["매체"],"explanation":["책·스마트폰·누리집이 모두 이것이에요.","면담에서도 절차마다 써요.","이것을 매체라고 해요."],"mis":"K6-2-u2-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#7','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',1,'sa','auto','면담 과정을 되돌아볼 때 「잘한 점 · ○○할 점 · 더 알고 싶은 점」으로 나누어 적어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"sa","stem":"면담 과정을 되돌아볼 때 「잘한 점 · ○○할 점 · 더 알고 싶은 점」으로 나누어 적어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["보완"],"explanation":["잘한 점과 놓친 점을 나누어요.","놓친 것, 다음에 다르게 할 것은 보완할 점이에요.","보완할 점은 다음 약속으로 바꿔요."],"mis":"K6-2-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#8','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C11',1,'mc','auto','「운동장이 넓은 것 같다」에서 「넓은」은 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「운동장이 넓은 것 같다」에서 「넓은」은 어떻게 소리 나나요?","options":[{"t":"[널븐]","correct":true},{"t":"[너븐]","mis":"K6-2-u2-X18"},{"t":"[널은]","mis":"K6-2-u2-X18"},{"t":"[넙븐]","mis":"K6-2-u2-X18"}],"explanation":["뒤에 모음 「은」이 붙었어요.","ㄹ은 받침으로 남고 ㅂ이 넘어가요.","그래서 [널븐]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#9','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C5',2,'mc','auto','예준의 후속 질문 덕분에 얻은 정보로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"예준의 후속 질문 덕분에 얻은 정보로 알맞은 것은 어느 것인가요?","options":[{"t":"손님이 책을 고르다 내려놓는 모습을 보고, 못 찾은 책을 여쭈어 적어 둔다","correct":true},{"t":"책방에서 하루에 가장 많이 하는 일은 책 고르기이다","mis":"K6-2-u2-X06"},{"t":"어릴 때 오던 손님이 아이와 왔을 때 보람을 느낀다","mis":"K6-2-u2-X06"},{"t":"책방 주인은 책을 많이 읽어야 한다","mis":"K6-2-u2-X13"}],"explanation":["예준의 질문 바로 뒤의 답을 보아요.","「내려놓는 모습」, 「공책에 적어」가 새로 나온 정보예요.","질문지에 없던 물음으로 중요한 답이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#10','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',2,'ox','auto','「책방을 꾸리는 사람」 면담은 열기 → 질문하기 → 마무리하기의 차례를 갖추었어요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":2,"kind":"ox","stem":"「책방을 꾸리는 사람」 면담은 열기 → 질문하기 → 마무리하기의 차례를 갖추었어요.","answer":"O","reason_options":[{"t":"인사·목적·동의로 열고, 세 갈래로 묻고, 확인과 감사로 마무리했기 때문에","correct":true},{"t":"질문이 세 개뿐이어서 차례가 필요 없기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["다온·예준이 열기를 했어요.","소미·예준이 묻고 이어서 물었어요.","다온이 확인하고 감사드렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#11','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',2,'error','auto','아침별 모둠이 녹음을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"error","stem":"아침별 모둠이 녹음을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소미 — 「허락받았으니까 녹음 파일을 누리집에 올려도 돼.」","correct":true,"mis_target":"K6-2-u2-X11"},{"t":"다온 — 「담기 전에 먼저 여쭈어 허락을 받았어.」","mis":"K6-2-u2-X11"},{"t":"예준 — 「보고서를 다 쓰면 밖으로 내보내지 않을 거야.」","mis":"K6-2-u2-X11"}],"explanation":["허락은 모둠 과제에만 쓰라는 것이었어요.","누리집에 올리는 것은 허락 밖의 일이에요.","다온과 예준은 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#12','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C4',2,'match','auto','아침별 모둠의 질문과 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"match","stem":"아침별 모둠의 질문과 갈래를 알맞게 이으세요.","pairs":[{"l":"하루에 책이 몇 권쯤 들어오나요?","r":"구체적인 사실에 대한 질문"},{"l":"손님이 책을 내려놓고 갈 때 어떤 마음이 드시나요?","r":"생각이나 느낌에 대한 질문"},{"l":"앞으로 책방에서 해 보고 싶은 일이 있으신가요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["몇 권은 있는 그대로의 일이에요.","어떤 마음은 느낌이에요.","해 보고 싶은 일은 앞으로의 계획이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#13','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'ox','auto','면담 내용을 정리할 때 들은 말을 한 마디도 빠뜨리지 않고 그대로 옮겨 적는 것이 가장 좋아요.',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"ox","stem":"면담 내용을 정리할 때 들은 말을 한 마디도 빠뜨리지 않고 그대로 옮겨 적는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"정리는 내가 듣고 이해한 것을 골라 내 말로 다시 세우는 일이기 때문에","correct":true},{"t":"그대로 옮겨야 뜻이 바뀌지 않기 때문에","mis":"K6-2-u2-X13"}],"mis":"K6-2-u2-X13","explanation":["통째로 옮기면 무엇이 중요한지 몰라요.","삭제·대체·선택·구성으로 간추려요.","뜻만 바꾸지 않으면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#14','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',2,'error','auto','태건에게 할 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"error","stem":"태건에게 할 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「곤란해해도 꼭 답하게 해야 진짜 면담이야.」","correct":true,"mis_target":"K6-2-u2-X17"},{"t":"도경 — 「답할 사람이 고를 여지를 남겨 두어야 해.」","mis":"K6-2-u2-X17"},{"t":"채원 — 「깎아내리는 말은 빼고 까닭을 여쭈어야 해.」","mis":"K6-2-u2-X17"}],"explanation":["억지로 답하게 하는 질문은 불쾌한 질문이에요.","도경과 채원은 바르게 말했어요.","궁금함과 배려를 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#15','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C2',2,'match','auto','면담을 요청할 때 밝히는 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"match","stem":"면담을 요청할 때 밝히는 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"우리가 누구인지","r":"6학년 아침별 모둠입니다"},{"l":"면담 목적","r":"책방을 꾸리는 일을 알리는 글을 쓰려고 합니다"},{"l":"걸리는 시간","r":"삼십 분 정도면 될 것 같습니다"},{"l":"바라는 날짜","r":"다음 주 목요일 오후는 괜찮으실까요?"}],"mis":"K6-2-u2-X03","explanation":["이 네 가지를 밝혀야 상대가 정할 수 있어요.","날짜는 「괜찮으실까요?」로 여쭈어요.","정해서 알리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#16','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'mc','auto','말 걸기를 어려워하는 친구가 모둠 면담에서 처음 맡기 좋은 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X11']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"말 걸기를 어려워하는 친구가 모둠 면담에서 처음 맡기 좋은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"메모나 정리를 맡아 함께한다","correct":true},{"t":"모둠에서 빠져 혼자 기다린다","mis":"K6-2-u2-X19"},{"t":"억지로 첫 질문을 크게 한다","mis":"K6-2-u2-X19"},{"t":"녹음 허락 없이 담는 일을 맡는다","mis":"K6-2-u2-X11"}],"explanation":["어려워하는 것은 잘못이 아니에요.","할 수 있는 만큼부터 함께해요.","메모·정리를 맡거나 지켜보는 것부터 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#17','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'error','auto','진로 면담 자료를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":17,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"진로 면담 자료를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「검색하면 맨 위에 나오는 자료가 가장 믿을 만해.」","correct":true,"mis_target":"K6-2-u2-X09"},{"t":"주호 — 「누가 만든 자료인지 확인해야 해.」","mis":"K6-2-u2-X09"},{"t":"서아 — 「언제 만든 자료인지도 살펴봐.」","mis":"K6-2-u2-X09"}],"explanation":["검색 순서는 믿을 만한지와 상관없어요.","누가·언제 만들었는지 확인해요.","주호와 서아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#18','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',3,'error','auto','짝과 태건 면담 놀이를 했어요. 작품에 근거하지 않고 답한 친구는 누구인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"짝과 태건 면담 놀이를 했어요. 작품에 근거하지 않고 답한 친구는 누구인가요?","options":[{"t":"하윤 — 「(태건이 되어) 마을에서 상을 준다고 해서 돌을 옮겼어요.」","correct":true,"mis_target":"K6-2-u2-X16"},{"t":"지호 — 「(태건이 되어) 할머니가 한 시간을 돌아 다니시는 게 마음에 걸렸어요.」","mis":"K6-2-u2-X16"},{"t":"나은 — 「(태건이 되어) 그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X16"}],"explanation":["상을 준다는 말은 이야기에 없어요.","지호는 이야기 속 사건으로 답했어요.","나은처럼 없는 것은 없다고 말해도 돼요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#19','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'ox','auto','「면담이 재미있었다.」는 면담 과정을 성찰하는 말로 충분해요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"「면담이 재미있었다.」는 면담 과정을 성찰하는 말로 충분해요.","answer":"X","reason_options":[{"t":"절차마다 무엇을 했는지 짚어 잘한 점·보완할 점·더 알고 싶은 점으로 나누어야 하기 때문에","correct":true},{"t":"재미있었으면 잘한 면담이기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["막연한 기분으로는 다음에 할 일이 남지 않아요.","절차마다 짚어요.","세 항목으로 나누어 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#20','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'error','auto','아침별 모둠이 질문을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"아침별 모둠이 질문을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「질문이 열 개를 넘으면 점검은 안 해도 돼.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"다온 — 「목적에 맞는지부터 살펴보자.」","mis":"K6-2-u2-X07"},{"t":"소미 — 「‘그거’, ‘그때’ 같은 말은 뜻이 분명하게 바꾸자.」","mis":"K6-2-u2-X07"}],"explanation":["개수는 점검의 기준이 아니에요.","목적·예의·명료함을 살펴요.","다온과 소미는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#21','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',3,'ox','auto','아침별 모둠은 진다해 선생님께 감사 인사를 드리고 헤어졌으니 면담이 모두 끝났어요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"ox","stem":"아침별 모둠은 진다해 선생님께 감사 인사를 드리고 헤어졌으니 면담이 모두 끝났어요.","answer":"X","reason_options":[{"t":"들은 것을 간추리고 성찰해 보고서로 남기는 면담 정리하기가 남았기 때문에","correct":true},{"t":"감사 인사가 면담의 마지막 일이기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["헤어진 뒤에도 할 일이 있어요.","내용 정리 · 성찰 · 보고서 쓰기예요.","다온도 「보고서가 나오면 보여 드리겠습니다」라고 했어요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#22','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'ox','auto','아침별 모둠이 보고서를 반 알림판에 붙이고 진다해 선생님께도 보여 드리는 것은 알맞아요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"아침별 모둠이 보고서를 반 알림판에 붙이고 진다해 선생님께도 보여 드리는 것은 알맞아요.","answer":"O","reason_options":[{"t":"간추려 쓴 보고서는 함께 읽어도 되고 면담 대상자께 보여 드리는 것이 좋기 때문에","correct":true},{"t":"보고서에 녹음 파일을 함께 붙이면 더 좋기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["간추려 쓴 보고서는 나눠도 돼요.","면담 대상자께 보여 드리기로 약속했어요.","담아 둔 목소리는 나누지 않아요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#23','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',4,'mc','auto','태건과의 인물 면담에서 바람직한 질문과 작품에 근거한 답을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X16']::text[],false,'{"seq":23,"concept":"K6-2-u2-C10","difficulty":4,"kind":"mc","stem":"태건과의 인물 면담에서 바람직한 질문과 작품에 근거한 답을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"질문 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」 — 답 「할머니가 한 시간을 돌아 다니시는 게 마음에 걸렸어요.」","correct":true},{"t":"질문 「혼자 하는 거 바보 같지 않았어요?」 — 답 「네, 바보 같았어요.」","mis":"K6-2-u2-X17"},{"t":"질문 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」 — 답 「상을 받으려고요.」","mis":"K6-2-u2-X16"},{"t":"질문 「왜 친구가 하나도 없었어요?」 — 답 「그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X17"}],"explanation":["질문은 마음을 헤아려 까닭을 여쭈어요.","답은 「할머니는 … 한 시간을 돌아」 같은 이야기 속 사건에서 나와요.","둘 다 갖추어야 좋은 인물 면담이에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#24','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',4,'essay','teacher','「사흘 걸린 다리」의 태건에게 할 질문을 세 갈래로 하나씩 만들고, 그중 하나에 태건이 되어 작품을 근거로 답해 보세요. 불쾌한 질문이 되지 않게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"「사흘 걸린 다리」의 태건에게 할 질문을 세 갈래로 하나씩 만들고, 그중 하나에 태건이 되어 작품을 근거로 답해 보세요. 불쾌한 질문이 되지 않게 쓰세요.","answer_guide":{"answer":"예: 사실 — 떠내려간 돌을 며칠 동안 옮기셨나요? 생각이나 느낌 — 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요? 계획이나 당부 — 혼자 무언가를 시작하려는 친구에게 해 줄 말이 있나요? 답(생각이나 느낌) — 사흘 동안 쌓은 돌이 흩어져 힘이 빠졌고 젖은 모래밭에 주저앉았어요. 그런데 그때 상우 아저씨가 지게를 지고 와 「나도 좀 하자.」라고 하셔서 다시 힘이 났어요.","scoring_points":["세 갈래로 질문을 하나씩 만들었는가","질문이 상대의 마음을 헤아리는 바람직한 질문인가","작품 속 사건·행동을 근거로 답했는가"]},"explanation":["인물에게도 세 갈래로 물어요.","깎아내리지 않고 마음을 헤아려요.","답은 이야기 안에서만 찾아요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#25','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C11',4,'essay','teacher','「밝다」와 「굵다」에 모음으로 시작하는 말을 붙여 문장을 하나씩 만들고, 밑줄 친 말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C11","difficulty":4,"kind":"essay","stem":"「밝다」와 「굵다」에 모음으로 시작하는 말을 붙여 문장을 하나씩 만들고, 밑줄 친 말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「보름달이 밝아서 길이 잘 보인다.」에서 「밝아」는 [발가], 「나무 밑동이 굵어 안을 수 없다.」에서 「굵어」는 [굴거]로 소리 난다. 뒤에 모음으로 시작하는 말이 붙으면 겹받침의 앞 자음 ㄹ은 받침으로 남고 뒤 자음 ㄱ이 넘어가 소리 나기 때문이다.","scoring_points":["두 낱말에 모음으로 시작하는 말을 붙여 문장을 만들었는가","발음을 바르게 썼는가","앞 자음은 남고 뒤 자음이 넘어간다는 까닭을 썼는가"]},"explanation":["모음이 붙으면 뒤 자음이 넘어가요.","밝아[발가] · 굵어[굴거]예요.","낱말 하나일 때는 [박따] · [국따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C1','kor',6,2,'u3',1,'주장 · 이유 · 근거 — 주장은 어떤 주제에 대한 자신의 의견을 드러내는 말, 이유는 왜 그렇게 주장하는지를 설명하는 말, 근거는 이유를 뒷받침하는 자료나 사실이며, 셋의 자리를 갈라야 평가할 수 있다',ARRAY['6국01 듣기·말하기(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C2','kor',6,2,'u3',1,'비판적으로 보고 듣기 — 무조건 믿거나 무조건 의심하는 것이 아니라 옳고 그른지를 제대로 따져 보는 것(맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하기), 따져 보지 않으면 사실이 아닌 것을 믿고 옮기게 되고, 따져 보면 믿을 만한 정보를 골라 쓰고 내 생각과 견주어 볼 수 있다',ARRAY['6국01 듣기·말하기(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C3','kor',6,2,'u3',2,'주장하는 말을 듣는 방법 — 말은 되감을 수 없으므로 메모하며 듣기(이유·근거 적기)·요약하며 듣기(주장·이유·근거로 간추리기)·견주며 듣기(내 생각과 견주기)를 하고, 지나치게 감정에 호소하지는 않는지 태도까지 살핀다',ARRAY['6국01 듣기·말하기(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C4','kor',6,2,'u3',2,'주장의 타당성 판단 기준 — 주장이 가치 있고 중요한지는 문제를 해결하거나 생활하는 데 도움이 되는가, 실천 가능한가(언제 무엇을 할지 정해져 있는가)로 판단한다',ARRAY['6국01 듣기·말하기(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C5','kor',6,2,'u3',2,'이유의 타당성 판단 기준 — 이유가 주장과 관련 있는가, 많은 사람이 받아들일 만한가(혼자만의 느낌·사정이 아닌가) 두 물음을 함께 통과해야 한다',ARRAY['6국01 듣기·말하기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C6','kor',6,2,'u3',2,'근거의 타당성 판단 기준과 근거 자료 — 근거가 이유와 관련 있는가, 객관적인 사실이나 정보인가로 판단하고, 근거 자료의 유형(표·그래프·면담 자료·사례)을 알며, 근거가 사실인지 책·기사·기관 누리집·어른께 여쭈어 확인하고 출처가 믿을 만한지 다시 살핀다',ARRAY['6국01 듣기·말하기(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C7','kor',6,2,'u3',4,'주장하는 말의 내용을 평가하며 듣기 — 타당한 점을 먼저 찾고 보완할 점을 찾으며(평가는 이긴 쪽을 고르는 일이 아니라 더 나아지게 하는 일), 평가 기준표에 ◎·○·△로 판단하고 그렇게 판단한 까닭(어떤 기준을 더 무겁게 보았는지)을 말한다',ARRAY['6국01 듣기·말하기(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C8','kor',6,2,'u3',4,'객관적인 근거와 출처 밝히기 — 누가 보아도 그러한 객관적인 근거와 혼자만의 느낌·짐작인 주관적인 말을 가르고, 주관적인 근거는 더 힘주어 말하거나 감정에 호소하지 않고 확인할 수 있는 자료로 고치며, 가져다 쓴 자료는 어디에서 나왔는지 밝힌다',ARRAY['6국01 듣기·말하기(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C9','kor',6,2,'u3',7,'영상의 주장 파악하기 — 알려 주는 영상·보여 주는 영상·주장하는 영상을 가르고, 영상은 주장을 직접 말하지 않는 경우가 많으므로 제목(그렇게 정한 까닭)·제시한 자료(무엇을 보여 주려고 넣었는지)·강조하는 장면이나 표현(되풀이·음악이 멈추는 자리·글자만 남는 화면)을 합쳐 주장을 한 문장으로 세운다',ARRAY['6국06 매체(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C10','kor',6,2,'u3',7,'강조와 타당성 가르기 — 음악·되풀이 자막 같은 강조는 만든 사람이 무엇을 가장 하고 싶은 말로 여기는지 알려 주는 실마리일 뿐 그 말이 타당한지·사실인지는 알려 주지 못하며, 주장을 찾는 일과 타당한지 따지는 일은 다르다(끝까지 한 번 보고 두 번째에 적으며 보기)',ARRAY['6국06 매체(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C11','kor',6,2,'u3',9,'카드 뉴스 내용을 평가하며 보기 — 카드 뉴스는 첫 장의 제목과 굵은 글씨에 주장이, 가운데 장에 이유와 근거가 한 쌍씩 놓이며, 짧을수록 빠진 것이 잘 보이지 않으므로 이유마다 「그래서 왜?」, 근거마다 「이게 그 이유를 보여 주나?」를 물으며 같은 세 기준으로 평가한다',ARRAY['6국06 매체(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C12','kor',6,2,'u3',9,'약한 자리 짚기와 부분 평가 — 잘 세워진 자리를 먼저 세고, 문제의 규모(많다·늘고 있다)만 말하는 이유나 이유를 보여 주지 않고 해결 방안(제도)을 말하는 근거를 약한 자리로 짚되, 하나가 약하다고 주장 전체가 틀린 것은 아니며 고칠 자리를 짚어 준다',ARRAY['6국06 매체(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C13','kor',6,2,'u3',12,'영상을 골라 타당성을 평가하고 설명하기 — 여러 사람이 함께 생각해 볼 만한 주제를 정해 구체적인 말로 찾고, 자세히 보기·알아낸 것 말하기·생각하기·궁금해하기 차례로 보며, 주장이 없는 영상은 평가표에서 가려내고, 내용의 타당성을 먼저·표현은 그다음에 보고, 제목·주장·이유·근거·판단·까닭을 넣어 설명한다',ARRAY['6국06 매체(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C14','kor',6,2,'u3',12,'받침 ㅎ의 발음 — 받침 ㅎ 뒤에 ㄱ·ㄷ·ㅈ이 오면 합쳐서 ㅋ·ㅌ·ㅊ으로(넣고[너코]·빨갛다[빨가타]·그렇지[그러치]), ㄴ이 오면 ㄴ으로(넣는[넌는]), 모음이 오면 ㅎ 소리를 내지 않는다(좋아[조아])(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X01','kor',6,'u3',ARRAY['K6-2-u3-C1','K6-2-u3-C9','K6-2-u3-C11']::text[],'주장 · 이유 · 근거의 자리를 섞는다(이유를 주장으로, 주장을 근거로 여기는 등)','하자는 말? 왜 그런지? 받쳐 주는 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X02','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C7','K6-2-u3-C12']::text[],'비판적으로 보기를 무조건 의심하기·말한 사람 깎아내리기·어딘가 잘못이 있다고 미리 정하기로 여긴다','따져 보기 = 맞는 것은 맞다고, 부족한 것은 부족하다고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X03','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C11']::text[],'말을 잘하거나 짧고 보기 좋거나 많이 퍼진 주장을 따져 보지 않고 그대로 믿는다','「이 말, 무엇이 받쳐 주지?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X04','kor',6,'u3',ARRAY['K6-2-u3-C3']::text[],'메모하거나 간추리지 않고 들어 평가할 거리를 남기지 못하거나, 결론을 미리 정하고 목소리·말솜씨로 판단한다','말은 되감을 수 없어요 — 적고 간추리며 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X05','kor',6,'u3',ARRAY['K6-2-u3-C4']::text[],'말만 크고 무엇부터 할지 알 수 없는 주장도 가치 있다고 여긴다(실천 가능성을 보지 않음)','언제 · 무엇을 할지 정해져 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X06','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'주장과 관련 없는 이유를 받아들이거나, 관련 있는 이유를 관련 없다고 여긴다','이 이유가 주장이 말하는 일과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X07','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'혼자만의 느낌이나 사정인 이유도 많은 사람이 받아들일 만한 이유로 여긴다','나만 그런가, 많은 사람이 고개를 끄덕일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X08','kor',6,'u3',ARRAY['K6-2-u3-C6','K6-2-u3-C8']::text[],'말한 사람의 느낌이나 짐작을 근거로 여기거나, 근거는 길고 많을수록 좋다고 여긴다','누가 보아도 그러한가, 확인할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X09','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거가 사실인지 확인하지 않거나, 검색해 나온 것·많이 퍼진 글을 출처 확인 없이 믿는다','책 · 기사 · 기관 누리집 · 어른께 — 그리고 출처 한 번 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X10','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거 자료의 유형(표·그래프·면담 자료·사례)과 그 쓰임을 헷갈린다','나란히 견주기? 흐름? 사람의 말? 있었던 일?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X11','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C12']::text[],'평가를 흠부터 찾는 일이나 이긴 쪽을 고르는 일로 여겨 타당한 점을 먼저 찾지 않는다','살릴 것 먼저, 고칠 것은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X12','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C13']::text[],'까닭 없이 표시만 하거나 「그냥 그렇게 느꼈다」로 판단하고, 판단이 갈릴 때 어떤 기준을 무겁게 보았는지 말하지 않는다','「나는 ○○을 가장 무겁게 보았어. 그래서 …」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X13','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'가져다 쓴 자료의 출처를 밝히지 않아 확인할 길을 막거나 남의 자료를 내 것처럼 쓴다','어디에서 · 언제 나온 자료인지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X14','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'약한 근거를 고칠 때 더 힘주어 되풀이하거나 듣는 사람의 감정에 호소한다','느낌을 키우지 말고 확인할 수 있는 자료로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X15','kor',6,'u3',ARRAY['K6-2-u3-C9','K6-2-u3-C13']::text[],'영상의 주장을 한 요소(제목만·분위기만)로 정하거나, 주장과 관계없는 것(길이·벽 색)을 실마리로 삼거나, 알려 주는 영상과 주장하는 영상을 헷갈린다','제목 + 자료 + 강조 → 한 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X16','kor',6,'u3',ARRAY['K6-2-u3-C9']::text[],'영상도 주장을 문장으로 직접 말할 것이라 여겨, 직접 말하지 않으면 주장이 없다고 본다','「그래서 나더러 무엇을 하라는 걸까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X17','kor',6,'u3',ARRAY['K6-2-u3-C10']::text[],'음악이 커지고 자막이 되풀이될수록, 곧 강조가 셀수록 주장이 옳거나 사실이라고 여긴다','강조는 「무엇을」 말하고 싶은지만 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X18','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제의 규모(많다·늘고 있다)만으로 문제가 되는 까닭을 말했다고 여긴다','많아서 → 무엇이 어떻게 나빠지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X19','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제에 대한 해결 방안(제도·규칙·대책)을 그 문제가 있다는 이유를 보여 주는 근거로 여긴다','이 근거는 문제를 보여 주나, 그 뒤의 일을 말하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X20','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'이유나 근거 하나가 약하면 주장 전체가 틀렸다거나 믿을 수 없다고 여긴다','약한 자리는 고칠 자리 — 주장 전체와 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X21','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'주장이 없는 영상도 평가표로 재거나, 음악·편집·말투 같은 표현과 재미로 타당성을 판단한다','먼저 평가할 수 있는 영상인지 · 내용 먼저, 표현은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X22','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'영상을 찾고 보는 차례를 지키지 않는다(두루뭉술하거나 자극적인 검색어, 본 것과 짐작한 것을 섞기)','구체적인 말로 찾기 · 본 것 → 생각 → 물음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X23','kor',6,'u3',ARRAY['K6-2-u3-C14']::text[],'받침 ㅎ을 뒤 소리와 상관없이 그대로 소리 내거나, ㄱ·ㄷ·ㅈ과 합치지 않고 ㄷ으로 끊어 소리 낸다','ㄱ·ㄷ·ㅈ → ㅋ·ㅌ·ㅊ · ㄴ → ㄴ · 모음 → 소리 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#1','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'mc','auto','「주장」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"「주장」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 주제에 대한 자신의 의견을 드러내는 말","correct":true},{"t":"왜 그렇게 주장하는지를 설명하는 말","mis":"K6-2-u3-X01"},{"t":"이유를 뒷받침하는 자료나 사실","mis":"K6-2-u3-X01"},{"t":"다른 사람의 말을 그대로 옮긴 말","mis":"K6-2-u3-X01"}],"explanation":["주장은 「무엇을 하자」는 의견이에요.","왜 그런지 밝히는 말은 이유예요.","이유를 받쳐 주는 자료는 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#2','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'sa','auto','이유를 뒷받침하는 자료나 사실을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"이유를 뒷받침하는 자료나 사실을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["근거"],"explanation":["주장은 의견, 이유는 까닭이에요.","이유가 사실인지 보여 주는 자료가 있어야 해요.","그 자료나 사실을 근거라고 해요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#3','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'ox','auto','비판적으로 본다는 것은 무조건 믿지 않는 것이에요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":3,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"비판적으로 본다는 것은 무조건 믿지 않는 것이에요.","answer":"X","reason_options":[{"t":"옳고 그른지를 제대로 따져 보는 것이기 때문에","correct":true},{"t":"어떤 말이든 먼저 의심해야 속지 않기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["무조건 믿지 않는 것은 따져 보기 전에 정해 버리는 것이에요.","비판적으로 보기는 까닭을 들어 따지는 것이에요.","맞는 것은 맞다고, 부족한 것은 부족하다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#4','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'mc','auto','주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일은 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X02']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일은 어느 것인가요?","options":[{"t":"사실이 아닌 것을 사실로 알게 된다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"K6-2-u3-X03"},{"t":"말한 사람을 깎아내리게 된다","mis":"K6-2-u3-X02"},{"t":"글을 더 빨리 읽게 된다","mis":"K6-2-u3-X03"}],"explanation":["따져 보지 않으면 사실이 아닌 것도 그대로 믿게 돼요.","그 말을 다른 사람에게 옮길 수도 있어요.","그래서 한 번 더 따져 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#5','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','서담이가 본 영상이 하려던 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"서담이가 본 영상이 하려던 주장은 무엇인가요?","options":[{"t":"아침에 물을 두 컵 마시자","correct":true},{"t":"자는 동안 몸에서 물이 빠져나간다","mis":"K6-2-u3-X01"},{"t":"짧은 영상을 자주 보자","mis":"K6-2-u3-X01"},{"t":"물에 대한 자료를 찾아보자","mis":"K6-2-u3-X01"}],"explanation":["영상이 보는 사람에게 하라고 한 일이 주장이에요.","「물이 빠져나가기 때문」은 왜 그런지 밝힌 이유예요.","주장과 이유의 자리가 달라요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#6','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','서담이가 본 영상에 빠져 있던 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":6,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"서담이가 본 영상에 빠져 있던 것은 어느 것인가요?","options":[{"t":"근거 — 이유가 사실이라는 자료","correct":true},{"t":"주장 — 무엇을 하자는 말","mis":"K6-2-u3-X01"},{"t":"이유 — 그렇게 말한 까닭","mis":"K6-2-u3-X01"},{"t":"주장과 이유 모두","mis":"K6-2-u3-X01"}],"explanation":["영상에는 「물을 두 컵 마시자」는 주장이 있었어요.","「물이 빠져나가기 때문」이라는 이유도 있었어요.","그 말이 사실이라는 자료는 없었어요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#7','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'match','auto','주장 · 이유 · 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":2,"kind":"match","stem":"주장 · 이유 · 근거를 알맞게 이으세요.","pairs":[{"l":"주장","r":"복도에서는 걸어 다닙시다"},{"l":"이유","r":"뛰면 부딪칠 수 있기 때문입니다"},{"l":"근거","r":"복도에서 부딪친 일이 여러 번 있었다는 보건실 기록"}],"mis":"K6-2-u3-X01","explanation":["무엇을 하자는 말이 주장이에요.","「~ 때문입니다」로 까닭을 밝히면 이유예요.","이유를 받쳐 주는 기록이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#8','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'mc','auto','비판적으로 듣는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"비판적으로 듣는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유와 근거가 주장과 잘 맞는지 따져 본다","correct":true},{"t":"일단 틀린 곳이 있다고 생각하고 듣는다","mis":"K6-2-u3-X02"},{"t":"말을 잘하는 사람의 말이면 그대로 받아들인다","mis":"K6-2-u3-X03"},{"t":"말한 사람이 마음에 들지 않으면 듣지 않는다","mis":"K6-2-u3-X02"}],"explanation":["믿거나 믿지 않거나 둘 중 하나로 정해 버리지 않아요.","이유와 근거가 주장과 맞는지 따져요.","말솜씨나 사람이 아니라 내용을 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#9','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'ox','auto','주장을 따져 보면 믿을 만한 정보를 골라 쓸 수 있어요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":9,"concept":"K6-2-u3-C2","difficulty":2,"kind":"ox","stem":"주장을 따져 보면 믿을 만한 정보를 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"내용을 제대로 이해하고 내 생각과 견주어 볼 수 있기 때문에","correct":true},{"t":"따져 보면 모든 주장이 틀렸다는 것을 알게 되기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["따져 보면 내용을 제대로 이해할 수 있어요.","내 생각과 견주어 볼 수 있어요.","따져 본다고 모든 주장이 틀린 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#10','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',3,'error','auto','비판적으로 보는 것에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X11']::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":3,"kind":"error","stem":"비판적으로 보는 것에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「어느 영상이든 잘못이 있게 마련이니 틀린 곳부터 찾으면 돼.」","correct":true,"mis_target":"K6-2-u3-X02"},{"t":"지호 — 「맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하는 거야.」","mis":"K6-2-u3-X02"},{"t":"라온 — 「타당한 점을 먼저 찾고 그다음에 보완할 점을 찾아.」","mis":"K6-2-u3-X11"}],"explanation":["지호와 라온은 따져 보기를 바르게 말했어요.","은솔은 잘못이 있다고 미리 정해 두었어요.","그것은 비판이 아니라 의심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#1','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',2,'mc','auto','주장이 우리를 만나는 자리에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"주장이 우리를 만나는 자리에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"발표 · 영상 · 카드 뉴스 · 광고 · 누리 소통망 글 어디에나 주장이 담길 수 있다","correct":true},{"t":"발표와 연설 같은 말에만 주장이 들어 있다","mis":"K6-2-u3-X03"},{"t":"영상과 카드 뉴스는 사실만 전하므로 주장이 없다","mis":"K6-2-u3-X03"},{"t":"광고는 물건을 보여 줄 뿐 주장이 없다","mis":"K6-2-u3-X03"}],"explanation":["담는 그릇은 여러 가지예요.","영상·카드 뉴스·광고에도 주장이 담겨요.","찾는 방법은 같아요 — 주장·이유·근거."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#2','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',2,'sa','auto','이유는 왜 그렇게 주장하는지를 ○○하는 말이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":2,"kind":"sa","stem":"이유는 왜 그렇게 주장하는지를 ○○하는 말이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["설명"],"explanation":["주장은 의견을 드러내는 말이에요.","이유는 그 의견의 까닭을 설명해요.","근거는 이유를 뒷받침해요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#3','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'mc','auto','하리가 「그 말이 사실이라는 자료도 보여 주었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":3,"concept":"K6-2-u3-C1","difficulty":3,"kind":"mc","stem":"하리가 「그 말이 사실이라는 자료도 보여 주었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유를 뒷받침하는 근거가 있는지 따져 보려고","correct":true},{"t":"서담이의 말을 믿지 않기로 미리 정해서","mis":"K6-2-u3-X02"},{"t":"영상의 주장이 무엇인지 몰라서","mis":"K6-2-u3-X01"},{"t":"영상이 얼마나 길었는지 궁금해서","mis":"K6-2-u3-X03"}],"explanation":["하리는 먼저 이유가 있었는지 물었어요.","그다음 이유를 받쳐 줄 자료를 물었어요.","믿지 않으려는 것이 아니라 따져 보려는 물음이에요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#4','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'mc','auto','「비판적으로 보기」와 「무조건 의심하기」를 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":3,"kind":"mc","stem":"「비판적으로 보기」와 「무조건 의심하기」를 바르게 가른 것은 어느 것인가요?","options":[{"t":"비판적으로 보기는 까닭을 들어 옳고 그름을 따지고, 무조건 의심하기는 따지기 전에 믿지 않기로 정한다","correct":true},{"t":"둘은 같은 말이다","mis":"K6-2-u3-X02"},{"t":"비판적으로 보기는 말한 사람을 깎아내리는 것이다","mis":"K6-2-u3-X02"},{"t":"의심하지 않고 그대로 믿는 것이 비판적으로 보기이다","mis":"K6-2-u3-X03"}],"explanation":["의심은 따지기 전에 정해 버려요.","비판은 까닭을 들어 따져요.","그래서 맞는 것은 맞다고도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#5','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'ox','auto','「복도에서 뛰면 부딪칠 수 있다」는 주장이에요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":3,"kind":"ox","stem":"「복도에서 뛰면 부딪칠 수 있다」는 주장이에요.","answer":"X","reason_options":[{"t":"왜 걸어 다녀야 하는지를 밝힌 이유이기 때문에","correct":true},{"t":"무엇을 하자는 말이 들어 있기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["「복도에서는 걸어 다닙시다」가 주장이에요.","「부딪칠 수 있다」는 그 까닭이에요.","그래서 이 말은 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#6','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'match','auto','주장을 대하는 태도와 그 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C2","difficulty":3,"kind":"match","stem":"주장을 대하는 태도와 그 결과를 알맞게 이으세요.","pairs":[{"l":"그대로 믿는다","r":"사실이 아닌 것을 다른 사람에게 옮길 수 있다"},{"l":"무조건 의심한다","r":"맞는 말도 받아들이지 못한다"},{"l":"까닭을 들어 따진다","r":"믿을 만한 정보를 골라 쓸 수 있다"}],"mis":"K6-2-u3-X02","explanation":["그대로 믿으면 잘못된 정보도 옮겨요.","무조건 의심하면 맞는 말도 놓쳐요.","따져 보아야 골라 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#7','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'error','auto','「급식을 남기지 맙시다」의 이유와 근거를 친구들이 말했어요. 자리를 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":3,"kind":"error","stem":"「급식을 남기지 맙시다」의 이유와 근거를 친구들이 말했어요. 자리를 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「근거는 ‘음식을 남기지 맙시다’야.」","correct":true,"mis_target":"K6-2-u3-X01"},{"t":"준서 — 「이유는 ‘남은 음식은 버려지기 때문이다’야.」","mis":"K6-2-u3-X01"},{"t":"가윤 — 「근거는 ‘하루에 남은 음식을 잰 우리 학교 기록’이야.」","mis":"K6-2-u3-X01"}],"explanation":["준서는 까닭을 이유로 바르게 말했어요.","가윤은 이유를 받쳐 주는 기록을 근거로 말했어요.","태린이 말한 것은 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#8','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'mc','auto','주장 · 이유 · 근거가 모두 갖추어진 말은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":8,"concept":"K6-2-u3-C1","difficulty":4,"kind":"mc","stem":"주장 · 이유 · 근거가 모두 갖추어진 말은 어느 것인가요?","options":[{"t":"「계단 손잡이를 잡고 내려갑시다. 발을 헛디뎌도 버틸 수 있기 때문입니다. 손잡이를 잡은 날 덜 미끄러졌다고 답한 우리 반 조사가 있습니다.」","correct":true},{"t":"「계단 손잡이를 잡고 내려갑시다. 꼭 그렇게 합시다.」","mis":"K6-2-u3-X01"},{"t":"「계단 손잡이를 잡고 내려갑시다. 발을 헛디뎌도 버틸 수 있기 때문입니다.」","mis":"K6-2-u3-X08"},{"t":"「우리 반 조사가 있습니다. 손잡이는 차갑습니다.」","mis":"K6-2-u3-X01"}],"explanation":["첫째 보기는 주장을 되풀이했을 뿐이에요.","둘째 보기는 이유까지만 있고 근거가 없어요.","정답은 하자는 말·까닭·조사 자료를 모두 갖추었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#9','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'essay','teacher','서담이가 본 영상의 내용을 주장 · 이유 · 근거로 나누어 쓰고, 빠진 것이 무엇인지 밝히세요. 그리고 빠진 자리를 채우려면 어떤 자료가 있으면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"서담이가 본 영상의 내용을 주장 · 이유 · 근거로 나누어 쓰고, 빠진 것이 무엇인지 밝히세요. 그리고 빠진 자리를 채우려면 어떤 자료가 있으면 좋을지 쓰세요.","answer_guide":{"answer":"예: 주장 — 아침에 물을 두 컵 마시자. 이유 — 자는 동안 몸에서 물이 빠져나가기 때문이다. 근거 — 없다. 그 말이 사실이라는 자료를 보여 주지 않았다. 자는 동안 몸에서 물이 빠져나간다는 것을 다룬 책이나 건강 기관의 안내 자료를 보여 주면 이유가 힘을 얻을 것이다.","scoring_points":["주장과 이유를 바르게 갈라 썼는가","근거가 빠졌다는 것을 밝혔는가","확인할 수 있는 자료(책·기관 안내 등)를 들었는가"]},"explanation":["하자는 말과 까닭을 먼저 갈라요.","하리가 물은 것이 바로 빠진 자리예요.","근거는 확인할 수 있는 자료여야 해요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#10','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',4,'essay','teacher','「비판적으로 본다는 것은 무조건 의심하는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"「비판적으로 본다는 것은 무조건 의심하는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 비판적으로 본다는 것은 무조건 믿지 않는 것이 아니라 옳고 그른지를 제대로 따져 보는 것이다. 맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하는 것이기 때문이다. 그대로 믿으면 사실이 아닌 것을 사실로 알게 되고, 그 잘못된 정보를 다른 사람에게 옮길 수 있다.","scoring_points":["따져 보기와 무조건 의심하기를 바르게 갈랐는가","맞는 것은 맞다고도 말한다는 점을 썼는가","그대로 믿었을 때의 문제를 두 가지 썼는가"]},"explanation":["의심은 따지기 전에 정해요.","비판은 까닭을 들어 따져요.","그대로 믿으면 잘못된 정보가 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#1','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',1,'mc','auto','주장하는 말을 들을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말을 들을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"이유와 근거를 메모하며 듣는다","correct":true},{"t":"말이 끝나기 전에 결론을 미리 정해 둔다","mis":"K6-2-u3-X04"},{"t":"말하는 사람의 목소리 크기만 보고 판단한다","mis":"K6-2-u3-X04"},{"t":"주장만 듣고 나머지는 흘려듣는다","mis":"K6-2-u3-X04"}],"explanation":["말은 되감을 수 없어요.","이유와 근거를 적어 두어야 평가할 거리가 남아요.","결론은 다 들은 뒤에 내려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#2','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'sa','auto','실제로 있었던 일 하나를 들어 보이는 근거 자료를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C6","difficulty":1,"kind":"sa","stem":"실제로 있었던 일 하나를 들어 보이는 근거 자료를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["사례"],"explanation":["표는 값을 나란히 놓아요.","그래프는 흐름을, 면담 자료는 사람의 말을 보여 줘요.","있었던 일 하나를 들면 사례예요."],"mis":"K6-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#3','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',1,'ox','auto','실천 가능한 주장이어야 가치 있는 주장이라고 할 수 있어요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":3,"concept":"K6-2-u3-C4","difficulty":1,"kind":"ox","stem":"실천 가능한 주장이어야 가치 있는 주장이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 언제 할지 알아야 생활에서 해 볼 수 있기 때문에","correct":true},{"t":"말이 크고 멋있을수록 가치 있는 주장이기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["주장은 문제 해결에 도움이 되어야 해요.","그리고 실천할 수 있어야 해요.","말만 크면 무엇부터 할지 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#4','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'mc','auto','근거의 타당성을 판단하는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":1,"kind":"mc","stem":"근거의 타당성을 판단하는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거가 이유와 관련 있고 객관적인 사실이나 정보인가?","correct":true},{"t":"근거가 말한 사람의 느낌을 잘 드러내는가?","mis":"K6-2-u3-X08"},{"t":"근거가 길고 어려운 말로 되어 있는가?","mis":"K6-2-u3-X08"},{"t":"근거가 주장보다 먼저 나오는가?","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주어야 해요.","느낌이나 짐작은 근거가 되지 못해요.","누가 보아도 그러한 사실이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#5','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',2,'mc','auto','민율이의 말을 주장 · 이유 · 근거로 나누어 간추릴 때, 주장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X04']::text[],false,'{"seq":5,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"민율이의 말을 주장 · 이유 · 근거로 나누어 간추릴 때, 주장으로 알맞은 것은 어느 것인가요?","options":[{"t":"모르는 것은 그날 안에 물어보자","correct":true},{"t":"모르는 것을 그대로 두면 다음에 배울 것까지 막힌다","mis":"K6-2-u3-X01"},{"t":"예담이는 분수의 뜻을 몰라 여러 단원에서 어려워했다","mis":"K6-2-u3-X01"},{"t":"묻는 일은 부끄러운 일이다","mis":"K6-2-u3-X04"}],"explanation":["「그날 안에 물어보자」가 하자는 말이에요.","「막히기 때문」은 이유, 예담이 이야기는 근거예요.","「부끄러운 일이다」는 민율이가 한 말과 반대예요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#6','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'mc','auto','「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X06']::text[],false,'{"seq":6,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"다음에 배울 것까지 막히기 때문이다","correct":true},{"t":"나는 손을 드는 것이 재미있기 때문이다","mis":"K6-2-u3-X07"},{"t":"수업 시간은 사십 분이기 때문이다","mis":"K6-2-u3-X06"},{"t":"선생님 목소리가 크기 때문이다","mis":"K6-2-u3-X06"}],"explanation":["이유는 주장과 이어져야 해요.","많은 사람이 받아들일 만해야 해요.","「막히기 때문」은 누구에게나 해당하고 주장과 곧바로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#7','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',2,'match','auto','근거 자료의 유형과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C6","difficulty":2,"kind":"match","stem":"근거 자료의 유형과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"표","r":"여러 값을 나란히 놓아 견주게 해 준다"},{"l":"그래프","r":"늘고 주는 흐름을 한눈에 보여 준다"},{"l":"면담 자료","r":"그 일을 겪은 사람의 말을 그대로 옮긴다"},{"l":"사례","r":"실제로 있었던 일 하나를 들어 보인다"}],"mis":"K6-2-u3-X10","explanation":["표는 나란히, 그래프는 흐름이에요.","면담 자료는 사람의 말이에요.","사례는 있었던 일 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#8','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',2,'mc','auto','더 실천 가능한 주장은 어느 것인가요?',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":8,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"더 실천 가능한 주장은 어느 것인가요?","options":[{"t":"잠자기 전에 열 쪽씩 책을 읽읍시다","correct":true},{"t":"우리 모두 훌륭한 사람이 됩시다","mis":"K6-2-u3-X05"},{"t":"세상을 더 좋게 만듭시다","mis":"K6-2-u3-X05"},{"t":"언젠가는 책을 많이 읽읍시다","mis":"K6-2-u3-X05"}],"explanation":["언제 무엇을 할지 정해져 있어야 실천할 수 있어요.","「잠자기 전에 열 쪽씩」은 오늘 바로 할 수 있어요.","말이 크면 무엇부터 할지 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#9','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'ox','auto','「학교 도서관에 책을 더 사자. 내가 읽고 싶은 책이 아직 없기 때문이다.」의 이유는 많은 사람이 받아들일 만해요.',ARRAY['K6-2-u3-X07']::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":2,"kind":"ox","stem":"「학교 도서관에 책을 더 사자. 내가 읽고 싶은 책이 아직 없기 때문이다.」의 이유는 많은 사람이 받아들일 만해요.","answer":"X","reason_options":[{"t":"주장과 관련은 있지만 한 사람의 사정이라 많은 사람이 고개를 끄덕이기 어렵기 때문에","correct":true},{"t":"주장과 관련이 있으면 타당한 이유이기 때문에","mis":"K6-2-u3-X07"}],"mis":"K6-2-u3-X07","explanation":["이 이유는 주장과 관련은 있어요.","그러나 한 사람이 읽고 싶은 책 이야기예요.","두 물음 가운데 하나만 통과했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#10','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',3,'error','auto','근거로 나온 말이 사실인지 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":10,"concept":"K6-2-u3-C6","difficulty":3,"kind":"error","stem":"근거로 나온 말이 사실인지 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하엘 — 「누리집에서 한 번 검색해서 나온 기사면 그대로 믿으면 돼.」","correct":true,"mis_target":"K6-2-u3-X09"},{"t":"도하 — 「그 내용을 다룬 책이나 기사를 찾아보고 출처도 살펴봐.」","mis":"K6-2-u3-X09"},{"t":"세아 — 「그 일을 맡은 기관의 누리집에서 확인하거나 어른께 여쭈어.」","mis":"K6-2-u3-X09"}],"explanation":["책·기사·기관 누리집·어른께 여쭙기가 모두 방법이에요.","찾은 기사도 어디에서 나왔는지 한 번 더 살펴요.","검색 한 번으로 끝내면 확인한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#1','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',2,'sa','auto','주장 · 이유 · 근거로 나누어 간추리며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":2,"kind":"sa","stem":"주장 · 이유 · 근거로 나누어 간추리며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["요약"],"explanation":["메모하며 듣기는 적으며 들어요.","요약하며 듣기는 간추리며 들어요.","견주며 듣기는 내 생각과 견주어요."],"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#2','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',2,'mc','auto','주장이 가치 있고 중요한지 판단하는 두 물음을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":2,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"주장이 가치 있고 중요한지 판단하는 두 물음을 바르게 모은 것은 어느 것인가요?","options":[{"t":"문제를 해결하거나 생활하는 데 도움이 되는가 · 실천 가능한가","correct":true},{"t":"말이 멋있는가 · 길이가 적당한가","mis":"K6-2-u3-X05"},{"t":"주장과 관련 있는가 · 객관적인가","mis":"K6-2-u3-X01"},{"t":"말한 사람이 유명한가 · 목소리가 큰가","mis":"K6-2-u3-X03"}],"explanation":["주장은 도움이 되는지와 실천 가능한지로 재요.","「관련 있는가」는 이유와 근거를 재는 물음이에요.","말한 사람이나 말솜씨는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#3','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'mc','auto','「그날의 물음」의 근거를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":3,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"「그날의 물음」의 근거를 바르게 모은 것은 어느 것인가요?","options":[{"t":"예담이의 사례와 우리 반 조사 결과","correct":true},{"t":"묻는 일은 부끄러운 일이 아니라는 말","mis":"K6-2-u3-X08"},{"t":"배움은 앞의 것 위에 뒤의 것이 쌓인다는 말","mis":"K6-2-u3-X01"},{"t":"오늘부터 그날 안에 물어보자는 말","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주는 자료나 사실이에요.","예담이 이야기는 사례, 반 조사는 조사 결과예요.","「쌓이는 일」은 이유를 풀어 준 설명이에요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#4','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'mc','auto','민율이가 근거를 「우리 반 친구의 사례」와 「우리 반에서 조사한 결과」로 든 것이 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X14','K6-2-u3-X09']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"민율이가 근거를 「우리 반 친구의 사례」와 「우리 반에서 조사한 결과」로 든 것이 좋은 까닭은 어느 것인가요?","options":[{"t":"듣는 사람이 확인할 수 있는 객관적인 사실이어서","correct":true},{"t":"말한 사람의 느낌이 잘 드러나서","mis":"K6-2-u3-X08"},{"t":"듣는 사람의 마음을 세게 움직여서","mis":"K6-2-u3-X14"},{"t":"확인할 수 없어서 따질 수 없어서","mis":"K6-2-u3-X09"}],"explanation":["같은 반 친구는 예담이에게 물어볼 수 있어요.","반 조사 결과도 다시 확인할 수 있어요.","확인할 수 있어야 객관적인 근거예요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#5','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',3,'ox','auto','이유가 주장과 관련만 있으면 타당한 이유라고 할 수 있어요.',ARRAY['K6-2-u3-X07']::text[],false,'{"seq":5,"concept":"K6-2-u3-C5","difficulty":3,"kind":"ox","stem":"이유가 주장과 관련만 있으면 타당한 이유라고 할 수 있어요.","answer":"X","reason_options":[{"t":"많은 사람이 받아들일 만한지도 함께 따져야 하기 때문에","correct":true},{"t":"이유는 주장과 이어지기만 하면 되기 때문에","mis":"K6-2-u3-X07"}],"mis":"K6-2-u3-X07","explanation":["이유를 재는 물음은 두 가지예요.","주장과 관련 있는가, 많은 사람이 받아들일 만한가.","하나만 통과하면 약한 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#6','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',3,'match','auto','무엇의 타당성인지와 그것을 재는 물음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C4","difficulty":3,"kind":"match","stem":"무엇의 타당성인지와 그것을 재는 물음을 알맞게 이으세요.","pairs":[{"l":"주장","r":"문제 해결에 도움이 되고 실천 가능한가"},{"l":"이유","r":"주장과 관련 있고 많은 사람이 받아들일 만한가"},{"l":"근거","r":"이유와 관련 있고 객관적인 사실이나 정보인가"}],"mis":"K6-2-u3-X01","explanation":["주장은 가치와 실천 가능성을 보아요.","이유는 주장과의 관련과 받아들일 만함을 보아요.","근거는 이유와의 관련과 객관성을 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#7','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',3,'error','auto','주장하는 말을 듣는 태도를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":7,"concept":"K6-2-u3-C3","difficulty":3,"kind":"error","stem":"주장하는 말을 듣는 태도를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"나린 — 「말은 다시 들을 수 없으니 그냥 느낌만 기억하면 돼.」","correct":true,"mis_target":"K6-2-u3-X04"},{"t":"유찬 — 「말은 되감을 수 없으니 이유와 근거를 메모하며 들어.」","mis":"K6-2-u3-X04"},{"t":"보미 — 「지나치게 감정에 호소하지는 않는지도 살피며 들어.」","mis":"K6-2-u3-X04"}],"explanation":["말은 한 번 듣고 지나가요.","그래서 적고 간추리며 들어야 평가할 거리가 남아요.","느낌만 남기면 따질 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#8','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',4,'mc','auto','「동네 놀이터에 그늘막을 세우자. 여름 한낮에 놀이 기구가 뜨거워지기 때문이다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X06']::text[],false,'{"seq":8,"concept":"K6-2-u3-C6","difficulty":4,"kind":"mc","stem":"「동네 놀이터에 그늘막을 세우자. 여름 한낮에 놀이 기구가 뜨거워지기 때문이다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여름 한낮에 놀이 기구의 뜨거운 정도를 시간마다 재어 적은 표","correct":true},{"t":"나는 그늘에서 노는 것을 좋아한다는 말","mis":"K6-2-u3-X08"},{"t":"그늘막은 예쁜 색이 많다는 말","mis":"K6-2-u3-X06"},{"t":"이웃 동네 놀이터가 더 넓다는 사례","mis":"K6-2-u3-X06"}],"explanation":["이유는 「놀이 기구가 뜨거워진다」예요.","그것을 보여 주는 자료가 근거예요.","시간마다 잰 표는 이유와 관련 있고 객관적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#9','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',4,'essay','teacher','「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유를 하나 더 만들어 쓰고, 그 이유가 이유를 재는 두 물음을 통과하는지 하나씩 따져 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유를 하나 더 만들어 쓰고, 그 이유가 이유를 재는 두 물음을 통과하는지 하나씩 따져 쓰세요.","answer_guide":{"answer":"예: 이유 — 궁금한 것을 바로 물어보면 그날 배운 내용이 머릿속에 또렷하게 남기 때문이다. 이 이유는 「물어보자」는 주장과 곧바로 이어지므로 주장과 관련 있다. 또 나 혼자만의 사정이 아니라 수업을 듣는 누구에게나 해당하므로 많은 사람이 받아들일 만하다.","scoring_points":["주장과 이어지는 이유를 새로 만들었는가","주장과 관련 있는지 따졌는가","많은 사람이 받아들일 만한지 따졌는가"]},"explanation":["이유는 주장과 이어져야 해요.","나만의 느낌이 아니어야 해요.","두 물음을 하나씩 대어 보아요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#10','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',4,'essay','teacher','「그날의 물음」의 근거 가운데 하나를 골라 근거의 유형을 쓰고, 그 근거가 사실인지 확인하는 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C6","difficulty":4,"kind":"essay","stem":"「그날의 물음」의 근거 가운데 하나를 골라 근거의 유형을 쓰고, 그 근거가 사실인지 확인하는 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「궁금한 것을 물어본 날에는 다음 날 수업이 더 쉬웠다고 답한 사람이 많았다」는 우리 반 조사 결과로, 표로 나타낼 수 있는 자료이다. 사실인지 확인하려면 조사한 종이나 표를 직접 보여 달라고 하거나, 반 친구들에게 다시 물어 조사해 볼 수 있다.","scoring_points":["근거를 하나 골라 유형을 바르게 썼는가","확인 방법을 두 가지 썼는가","확인 방법이 그 근거에 알맞은가"]},"explanation":["조사 결과는 표나 그래프로 보여 줄 수 있어요.","사례는 겪은 사람에게 물어볼 수 있어요.","확인할 수 있어야 믿을 수 있어요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#1','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',1,'mc','auto','주장하는 말을 평가하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X11','K6-2-u3-X12']::text[],false,'{"seq":1,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"주장하는 말을 평가하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"타당한 점을 먼저 찾고 그다음에 보완할 점을 찾는다","correct":true},{"t":"흠부터 찾고 타당한 점은 찾지 않는다","mis":"K6-2-u3-X11"},{"t":"이긴 쪽을 고르고 끝낸다","mis":"K6-2-u3-X11"},{"t":"표시만 하고 까닭은 말하지 않는다","mis":"K6-2-u3-X12"}],"explanation":["흠부터 찾으면 어느 발표에나 잘못이 있다고 여기게 돼요.","타당한 점을 먼저 찾아요.","그래야 무엇을 살리고 고칠지 함께 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#2','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',1,'sa','auto','자기 생각이 아니라 누가 보아도 그러한 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C8","difficulty":1,"kind":"sa","stem":"자기 생각이 아니라 누가 보아도 그러한 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["객관적"],"explanation":["자기 혼자만의 느낌에 치우친 것은 주관적이에요.","누가 보아도 그러한 것은 객관적이에요.","근거는 객관적이어야 해요."],"mis":"K6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#3','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',1,'ox','auto','조사한 자료를 근거로 쓸 때에는 어디에서 나온 자료인지 밝혀야 해요.',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":3,"concept":"K6-2-u3-C8","difficulty":1,"kind":"ox","stem":"조사한 자료를 근거로 쓸 때에는 어디에서 나온 자료인지 밝혀야 해요.","answer":"O","reason_options":[{"t":"듣는 사람이 사실인지 확인할 수 있고 남의 자료를 내 것처럼 쓰지 않게 되기 때문에","correct":true},{"t":"출처를 밝히면 말이 길어져 설득력이 떨어지기 때문에","mis":"K6-2-u3-X13"}],"mis":"K6-2-u3-X13","explanation":["출처를 밝히지 않으면 확인할 길이 없어요.","남이 만든 자료를 내 것처럼 쓰게 돼요.","「○○에서 조사한 표입니다」처럼 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#4','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',1,'mc','auto','다경이와 세온이가 학교 도서관에 대해 발표한 목적은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X11']::text[],false,'{"seq":4,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"다경이와 세온이가 학교 도서관에 대해 발표한 목적은 무엇인가요?","options":[{"t":"학교 도서관을 바꾸자고 듣는 사람을 설득하려고","correct":true},{"t":"자기가 읽은 책을 소개하려고","mis":"K6-2-u3-X01"},{"t":"도서관이 어디에 있는지 알려 주려고","mis":"K6-2-u3-X01"},{"t":"누가 더 말을 잘하는지 겨루려고","mis":"K6-2-u3-X11"}],"explanation":["두 발표는 모두 도서관을 더 낫게 만들자는 말이에요.","설득하려는 말이니 주장하는 말이에요.","겨루기가 아니라 설득이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#5','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','다경이의 발표에서 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"다경이의 발표에서 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"수업이 끝난 뒤에는 책을 볼 시간이 있는 학생이 적기 때문이다","correct":true},{"t":"점심시간에도 도서관을 열어야 한다","mis":"K6-2-u3-X01"},{"t":"이용하고 싶은 시간을 조사한 표","mis":"K6-2-u3-X01"},{"t":"이웃 학교 소식지에 실린 내용","mis":"K6-2-u3-X01"}],"explanation":["「열어야 한다」는 주장이에요.","「~ 때문입니다」로 밝힌 까닭이 이유예요.","조사한 표와 소식지 내용은 근거예요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#6','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',2,'mc','auto','세온이의 근거가 객관적이지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X05','K6-2-u3-X06']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"세온이의 근거가 객관적이지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 책 냄새를 좋아한다는 느낌과 사람이 많아 보였다는 짐작에 머물러 있어서","correct":true},{"t":"근거가 너무 짧아서","mis":"K6-2-u3-X08"},{"t":"주장이 학생들에게 도움이 되지 않아서","mis":"K6-2-u3-X05"},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"}],"explanation":["「좋아합니다」는 세온이의 느낌이에요.","「많아 보였습니다」는 짐작이에요.","누가 보아도 그러한 것이 아니에요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#7','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',2,'match','auto','평가할 때 쓰는 말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C8","difficulty":2,"kind":"match","stem":"평가할 때 쓰는 말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"타당하다","r":"일의 이치로 보아 옳다"},{"l":"주관적","r":"자기 혼자만의 생각이나 느낌에 치우친 것"},{"l":"뒷받침하다","r":"뒤에서 받쳐 힘이 되어 주다"},{"l":"설득하다","r":"잘 알아듣도록 말하여 마음을 움직이다"}],"mis":"K6-2-u3-X08","explanation":["타당하다는 이치로 보아 옳다는 뜻이에요.","주관적은 객관적과 반대예요.","근거는 이유를 뒷받침해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#8','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',2,'mc','auto','세온이의 발표에서 타당한 점은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X11']::text[],false,'{"seq":8,"concept":"K6-2-u3-C7","difficulty":2,"kind":"mc","stem":"세온이의 발표에서 타당한 점은 어느 것인가요?","options":[{"t":"이유가 주장과 관련이 있다","correct":true},{"t":"근거로 조사한 자료를 보여 주었다","mis":"K6-2-u3-X08"},{"t":"다른 학교의 사례를 들었다","mis":"K6-2-u3-X08"},{"t":"타당한 점은 하나도 없다","mis":"K6-2-u3-X11"}],"explanation":["새 책이 많아야 온다는 이유는 새 책을 사자는 주장과 이어져요.","조사 자료와 사례는 다경이가 든 근거예요.","약한 발표에도 타당한 점은 있어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#9','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',2,'ox','auto','같은 발표를 두고 사람마다 판단이 다를 때에는 「그냥 그렇게 느꼈어.」라고 말하면 돼요.',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":9,"concept":"K6-2-u3-C7","difficulty":2,"kind":"ox","stem":"같은 발표를 두고 사람마다 판단이 다를 때에는 「그냥 그렇게 느꼈어.」라고 말하면 돼요.","answer":"X","reason_options":[{"t":"어떤 기준을 더 무겁게 보았는지 까닭을 말해야 하기 때문에","correct":true},{"t":"판단은 사람마다 다르니 까닭은 없어도 되기 때문에","mis":"K6-2-u3-X12"}],"mis":"K6-2-u3-X12","explanation":["판단은 갈릴 수 있어요.","그러나 까닭은 반드시 있어야 해요.","「나는 ○○을 가장 무겁게 보았어」처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#10','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',3,'mc','auto','세온이의 근거를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X08']::text[],false,'{"seq":10,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"세온이의 근거를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"새 책이 들어온 달과 그렇지 않은 달의 대출 수를 견주어 보여 준다","correct":true},{"t":"새 책이 좋다고 더 힘주어 여러 번 말한다","mis":"K6-2-u3-X14"},{"t":"새 책이 없으면 너무 속상하다고 마음에 호소한다","mis":"K6-2-u3-X14"},{"t":"새 책 냄새가 얼마나 좋은지 자세히 그려 말한다","mis":"K6-2-u3-X08"}],"explanation":["느낌을 키우는 것은 고치는 것이 아니에요.","누가 보아도 그러한 자료로 바꾸어요.","대출 수를 견주면 확인할 수 있어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#1','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',2,'sa','auto','평가 기준표에 ◎ · ○ · △로 표시만 하고 끝내지 않고, 그렇게 판단한 ○○을 함께 말해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C7","difficulty":2,"kind":"sa","stem":"평가 기준표에 ◎ · ○ · △로 표시만 하고 끝내지 않고, 그렇게 판단한 ○○을 함께 말해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["까닭"],"explanation":["표시만으로는 왜 그런지 알 수 없어요.","판단한 까닭을 말해야 해요.","그래야 듣는 사람이 따라올 수 있어요."],"mis":"K6-2-u3-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#2','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',2,'mc','auto','다경이와 세온이의 발표를 견줄 때 더 타당하다고 볼 수 있는 쪽과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X12']::text[],false,'{"seq":2,"concept":"K6-2-u3-C7","difficulty":2,"kind":"mc","stem":"다경이와 세온이의 발표를 견줄 때 더 타당하다고 볼 수 있는 쪽과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다경 — 주장 · 이유 · 근거가 자연스럽게 이어지고 객관적인 자료를 썼다","correct":true},{"t":"세온 — 새 책 냄새를 좋아한다는 말이 솔직하다","mis":"K6-2-u3-X08"},{"t":"세온 — 발표가 더 짧고 쉽다","mis":"K6-2-u3-X12"},{"t":"다경 — 발표 시간이 더 길다","mis":"K6-2-u3-X12"}],"explanation":["다경이는 조사한 표와 소식지 내용을 근거로 들었어요.","세온이의 근거는 느낌과 짐작이에요.","길이나 솔직함은 타당성의 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#3','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',3,'mc','auto','다경이가 「학교 소식지에 실린 내용입니다.」라고 덧붙인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X13','K6-2-u3-X02']::text[],false,'{"seq":3,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"다경이가 「학교 소식지에 실린 내용입니다.」라고 덧붙인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거의 출처를 밝혀 듣는 사람이 사실인지 확인할 수 있게 하려고","correct":true},{"t":"말을 더 길게 하려고","mis":"K6-2-u3-X13"},{"t":"소식지를 자랑하려고","mis":"K6-2-u3-X13"},{"t":"이웃 학교를 깎아내리려고","mis":"K6-2-u3-X02"}],"explanation":["어디에서 나온 자료인지 밝혔어요.","듣는 사람은 소식지를 찾아 확인할 수 있어요.","출처는 근거를 믿을 수 있게 해 줘요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#4','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'ox','auto','세온이의 발표에 보완할 점이 있으니 세온이의 주장은 틀린 주장이에요.',ARRAY['K6-2-u3-X20']::text[],false,'{"seq":4,"concept":"K6-2-u3-C7","difficulty":3,"kind":"ox","stem":"세온이의 발표에 보완할 점이 있으니 세온이의 주장은 틀린 주장이에요.","answer":"X","reason_options":[{"t":"주장은 학생들에게 도움이 되는 내용이고, 근거를 객관적인 자료로 고치면 되기 때문에","correct":true},{"t":"보완할 점이 하나라도 있으면 주장 전체가 틀린 것이기 때문에","mis":"K6-2-u3-X20"}],"mis":"K6-2-u3-X20","explanation":["새 책을 사자는 주장은 학생들에게 도움이 돼요.","약한 것은 근거예요.","약한 자리를 고치면 더 나아져요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#5','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C5',3,'mc','auto','세온이의 이유가 많은 사람이 받아들이기에 부족한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X08','K6-2-u3-X12']::text[],false,'{"seq":5,"concept":"K6-2-u3-C5","difficulty":3,"kind":"mc","stem":"세온이의 이유가 많은 사람이 받아들이기에 부족한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"학생들이 도서관에 오는 까닭은 새 책 말고도 여러 가지여서","correct":true},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"},{"t":"이유에 숫자가 없어서","mis":"K6-2-u3-X08"},{"t":"이유가 너무 짧아서","mis":"K6-2-u3-X12"}],"explanation":["이유는 주장과 관련은 있어요.","그러나 도서관에 오는 까닭은 여러 가지예요.","그래서 많은 사람이 받아들이기에 부족해요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#6','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'match','auto','세온이의 발표를 평가 기준표 세 항목으로 판단한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C7","difficulty":3,"kind":"match","stem":"세온이의 발표를 평가 기준표 세 항목으로 판단한 내용을 알맞게 이으세요.","pairs":[{"l":"주장은 가치 있고 중요한가","r":"학생들에게 도움이 되는 주장이다"},{"l":"이유는 주장을 뒷받침하는가","r":"관련은 있지만 많은 사람이 받아들이기에 부족하다"},{"l":"근거는 이유를 뒷받침하는가","r":"느낌과 짐작에 머물러 있다"}],"mis":"K6-2-u3-X01","explanation":["주장은 가치 있는 내용이에요.","이유는 관련은 있으나 받아들이기에 부족해요.","근거는 객관적이지 않아요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#7','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',3,'error','auto','우리 반 생각 발표회에서 근거를 말했어요. 출처를 밝히지 않은 친구는 누구인가요?',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":7,"concept":"K6-2-u3-C8","difficulty":3,"kind":"error","stem":"우리 반 생각 발표회에서 근거를 말했어요. 출처를 밝히지 않은 친구는 누구인가요?","options":[{"t":"도율 — 「어떤 조사를 보니 대부분 찬성했대요.」","correct":true,"mis_target":"K6-2-u3-X13"},{"t":"채이 — 「우리 학교 보건실에서 지난달에 정리한 기록입니다.」","mis":"K6-2-u3-X13"},{"t":"윤후 — 「우리 반이 지난주에 손을 들어 조사한 결과입니다.」","mis":"K6-2-u3-X13"}],"explanation":["채이와 윤후는 어디에서 언제 나온 자료인지 밝혔어요.","도율의 「어떤 조사」는 어디에서 나왔는지 알 수 없어요.","확인할 길이 없으면 믿기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#8','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',4,'mc','auto','우리 반 생각 발표회를 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08','K6-2-u3-X12']::text[],false,'{"seq":8,"concept":"K6-2-u3-C7","difficulty":4,"kind":"mc","stem":"우리 반 생각 발표회를 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"고치고 싶은 일 떠올리기 → 주장 정하고 스스로 점검하기 → 이유와 근거 모으기 → 친구 발표를 기준표로 판단하고 까닭 적기","correct":true},{"t":"근거 모으기 → 고치고 싶은 일 떠올리기 → 주장 정하기 → 발표하기","mis":"K6-2-u3-X01"},{"t":"주장 정하기 → 근거 없이 바로 발표하기 → 친구 발표 듣기","mis":"K6-2-u3-X08"},{"t":"고치고 싶은 일 떠올리기 → 주장 정하기 → 이유와 근거 모으기 → 친구 발표에 표시만 하기","mis":"K6-2-u3-X12"}],"explanation":["고칠 일이 있어야 주장이 생겨요.","주장을 정한 뒤 이유와 근거를 모아요.","친구 발표는 기준표로 판단하고 까닭을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#9','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',4,'essay','teacher','세온이의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 근거를 객관적인 자료로 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C8","difficulty":4,"kind":"essay","stem":"세온이의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 근거를 객관적인 자료로 고쳐 쓰세요.","answer_guide":{"answer":"예: 타당한 점 — 새 책을 사자는 주장은 학생들에게 도움이 되고, 새 책이 많아야 학생들이 온다는 이유는 주장과 관련이 있다. 보완할 점 — 도서관에 오는 까닭은 여러 가지라 이유가 많은 사람이 받아들이기에 부족하고, 근거가 새 책 냄새를 좋아한다는 느낌과 사람이 많아 보였다는 짐작이다. 고친 근거 — 우리 학교 도서관에서 새 책이 들어온 달과 그렇지 않은 달의 대출 수를 견주어 정리한 표를 보여 준다.","scoring_points":["타당한 점을 먼저 썼는가","이유와 근거의 보완할 점을 까닭과 함께 썼는가","확인할 수 있는 자료로 근거를 고치고 출처를 밝혔는가"]},"explanation":["살릴 것을 먼저 찾아요.","고칠 것은 까닭과 함께 써요.","느낌을 확인할 수 있는 자료로 바꾸어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#10','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',4,'essay','teacher','다경이의 발표를 평가 기준표 세 항목(주장 · 이유 · 근거)에 ◎ · ○ · △로 판단하고, 각 판단마다 까닭을 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"다경이의 발표를 평가 기준표 세 항목(주장 · 이유 · 근거)에 ◎ · ○ · △로 판단하고, 각 판단마다 까닭을 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 주장 ◎ — 점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있어 도움이 되고 학교가 바로 해 볼 수 있다. 이유 ◎ — 수업이 끝난 뒤에는 책을 볼 시간이 있는 학생이 적다는 것은 주장과 이어지고 많은 학생이 겪는 일이다. 근거 ◎ — 학교 도서관에서 조사한 표와 학교 소식지에 실린 이웃 학교 사례로 출처가 밝혀진 객관적인 자료이다.","scoring_points":["세 항목 모두에 판단을 표시했는가","판단마다 기준에 맞는 까닭을 썼는가","근거의 객관성과 출처를 짚었는가"]},"explanation":["표시만 하고 끝내지 않아요.","기준에 대어 까닭을 써요.","다경이는 출처도 밝혔어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#1','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'mc','auto','영상의 주장을 파악할 때 살펴볼 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X17','K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"영상의 주장을 파악할 때 살펴볼 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"제목 · 제시한 자료 · 강조하는 장면이나 표현","correct":true},{"t":"영상 길이 · 나오는 사람 수","mis":"K6-2-u3-X15"},{"t":"배경 음악의 크기 하나만","mis":"K6-2-u3-X17"},{"t":"조회 수 · 댓글 수","mis":"K6-2-u3-X03"}],"explanation":["제목에는 만든 사람의 눈이 담겨요.","자료와 강조된 장면도 함께 보아요.","셋을 합치면 주장이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#2','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'sa','auto','무엇을 하자거나 하지 말자고 설득하는 영상을 「○○하는 영상」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C9","difficulty":1,"kind":"sa","stem":"무엇을 하자거나 하지 말자고 설득하는 영상을 「○○하는 영상」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["주장"],"explanation":["알려 주는 영상은 사실이나 방법을 전해요.","보여 주는 영상은 겪은 일을 담아요.","설득하는 영상은 주장하는 영상이에요."],"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#3','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C10',1,'ox','auto','음악이 커지고 자막이 되풀이될수록 그 영상의 주장은 타당해요.',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":3,"concept":"K6-2-u3-C10","difficulty":1,"kind":"ox","stem":"음악이 커지고 자막이 되풀이될수록 그 영상의 주장은 타당해요.","answer":"X","reason_options":[{"t":"강조는 하고 싶은 말을 알려 줄 뿐 그 말이 타당한지는 알려 주지 못하기 때문에","correct":true},{"t":"강조가 셀수록 만든 사람이 확신하고 있기 때문에","mis":"K6-2-u3-X17"}],"mis":"K6-2-u3-X17","explanation":["강조는 주장을 찾는 실마리예요.","타당한지는 자료로 따로 따져요.","센 강조는 마음을 먼저 움직일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#4','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'mc','auto','주장을 담은 영상의 제목은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":4,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"주장을 담은 영상의 제목은 어느 것인가요?","options":[{"t":"늦게 자는 습관, 오늘부터 바꿉시다","correct":true},{"t":"우리나라 사람들은 몇 시에 잠들까","mis":"K6-2-u3-X15"},{"t":"하루 동안 낮잠을 자 본 결과","mis":"K6-2-u3-X15"},{"t":"잠에 대한 열 가지 사실","mis":"K6-2-u3-X15"}],"explanation":["「바꿉시다」는 무엇을 하라고 이끄는 말이에요.","「몇 시에 잠들까」·「열 가지 사실」은 알려 주는 제목이에요.","「자 본 결과」는 겪은 일을 보여 주는 제목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#5','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'mc','auto','영상 「걸으면 보이는 것」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":5,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"영상 「걸으면 보이는 것」의 주장은 무엇인가요?","options":[{"t":"가까운 곳은 걸어서 다니자","correct":true},{"t":"동네에 나무를 더 심자","mis":"K6-2-u3-X15"},{"t":"날마다 오래 달리기를 하자","mis":"K6-2-u3-X15"},{"t":"차를 타면 빨리 갈 수 있다","mis":"K6-2-u3-X15"}],"explanation":["제목은 걸을 때만 보이는 것이 있다고 말해요.","조사 화면은 가까운 길도 차로 다니는 문제를 보여 줘요.","마지막 자막이 「가까운 길은, 걸어서」예요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#6','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'match','auto','영상의 요소와 그 요소를 볼 때 던질 물음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C9","difficulty":2,"kind":"match","stem":"영상의 요소와 그 요소를 볼 때 던질 물음을 알맞게 이으세요.","pairs":[{"l":"제목","r":"왜 이렇게 이름을 붙였을까"},{"l":"제시한 자료","r":"무엇을 보여 주려고 이 자료를 넣었을까"},{"l":"강조하는 장면이나 표현","r":"왜 하필 여기에서 크게 · 되풀이해서 보여 줄까"}],"mis":"K6-2-u3-X15","explanation":["제목에는 이름을 붙인 까닭을 물어요.","자료에는 넣은 까닭을 물어요.","강조에는 그 자리를 고른 까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#7','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'mc','auto','「걸으면 보이는 것」에 장면 3의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"「걸으면 보이는 것」에 장면 3의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가까운 거리도 차로 다니는 문제가 실제로 있다는 것을 보여 주려고","correct":true},{"t":"도시가 얼마나 큰지 알려 주려고","mis":"K6-2-u3-X15"},{"t":"차가 편하다는 것을 알리려고","mis":"K6-2-u3-X15"},{"t":"영상을 길게 만들려고","mis":"K6-2-u3-X15"}],"explanation":["자료를 넣은 자리에는 까닭이 있어요.","조사 화면은 문제가 있다는 것을 보여 줘요.","장면 4는 바꾸면 좋아진다는 것을 보여 줘요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#8','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'ox','auto','영상은 대부분 「저는 ~해야 한다고 생각합니다.」처럼 주장을 직접 말해요.',ARRAY['K6-2-u3-X16']::text[],false,'{"seq":8,"concept":"K6-2-u3-C9","difficulty":2,"kind":"ox","stem":"영상은 대부분 「저는 ~해야 한다고 생각합니다.」처럼 주장을 직접 말해요.","answer":"X","reason_options":[{"t":"자료와 장면을 보여 주고 보는 사람이 스스로 알아채게 만드는 경우가 많기 때문에","correct":true},{"t":"영상도 주장하는 말처럼 주장을 문장으로 밝히기 때문에","mis":"K6-2-u3-X16"}],"mis":"K6-2-u3-X16","explanation":["영상은 주장을 말로 밝히지 않는 경우가 많아요.","자료와 장면을 이어 붙여 알아채게 해요.","「그래서 나더러 무엇을 하라는 걸까」를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#9','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C10',2,'mc','auto','영상을 바르게 보는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X22','K6-2-u3-X17','K6-2-u3-X12']::text[],false,'{"seq":9,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"영상을 바르게 보는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"처음에는 끝까지 한 번 보고, 두 번째에는 제목 · 자료 · 강조된 표현을 적으며 본다","correct":true},{"t":"처음부터 장면마다 멈추며 마음에 드는 것만 본다","mis":"K6-2-u3-X22"},{"t":"음악이 좋은 부분만 골라 본다","mis":"K6-2-u3-X17"},{"t":"보고 나서 느낌만 말한다","mis":"K6-2-u3-X12"}],"explanation":["처음에는 멈추지 않고 끝까지 보아요.","두 번째에 적으며 보아요.","본 뒤에는 알아낸 것과 궁금한 것을 나누어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#10','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C10',3,'error','auto','「멈추면 들리는 소리」를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":10,"concept":"K6-2-u3-C10","difficulty":3,"kind":"error","stem":"「멈추면 들리는 소리」를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「마지막에 음악이 멈추고 자막만 남으니, 이 주장은 틀림없이 옳아.」","correct":true,"mis_target":"K6-2-u3-X17"},{"t":"하준 — 「자막 ‘끄면’이 되풀이되며 커지는 걸 보니, 화면을 끄라는 말이 하고 싶은 거야.」","mis":"K6-2-u3-X15"},{"t":"지안 — 「주장을 찾았으니 이제 타당한지는 자료로 따져 봐야 해.」","mis":"K6-2-u3-X17"}],"explanation":["하준은 강조를 주장을 찾는 실마리로 썼어요.","지안은 찾는 일과 따지는 일을 갈랐어요.","소율은 강조를 타당성으로 여겼어요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#1','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',2,'sa','auto','「걸으면 보이는 것」 마지막 화면에 글자만 남은 자막은 「○○○ 길은, 걸어서」예요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C9","difficulty":2,"kind":"sa","stem":"「걸으면 보이는 것」 마지막 화면에 글자만 남은 자막은 「○○○ 길은, 걸어서」예요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["가까운"],"explanation":["마지막에 음악이 멈춰요.","검은 바탕에 글자만 남아요.","가장 하고 싶은 말을 마지막에 크게 두었어요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"},"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#2','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',2,'mc','auto','강조하는 장면이나 표현이 알려 주는 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X03']::text[],false,'{"seq":2,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"강조하는 장면이나 표현이 알려 주는 것은 어느 것인가요?","options":[{"t":"만든 사람이 무엇을 가장 하고 싶은 말로 여기는지","correct":true},{"t":"그 말이 사실인지","mis":"K6-2-u3-X17"},{"t":"그 말이 타당한지","mis":"K6-2-u3-X17"},{"t":"영상이 얼마나 인기 있는지","mis":"K6-2-u3-X03"}],"explanation":["강조는 하고 싶은 말을 가리켜요.","사실인지·타당한지는 알려 주지 못해요.","그것은 자료로 따로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#3','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'mc','auto','제목을 「걷기의 좋은 점 세 가지」가 아니라 「걸으면 보이는 것」으로 정했을 때 달라지는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":3,"concept":"K6-2-u3-C9","difficulty":3,"kind":"mc","stem":"제목을 「걷기의 좋은 점 세 가지」가 아니라 「걸으면 보이는 것」으로 정했을 때 달라지는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"알려 주는 영상이 아니라, 차로 지나갈 때는 못 보던 것이 있다는 생각을 먼저 심어 준다","correct":true},{"t":"달라지는 것이 없다 — 제목은 주장과 관계없다","mis":"K6-2-u3-X15"},{"t":"걷기에 대한 사실만 알려 주게 된다","mis":"K6-2-u3-X15"},{"t":"영상이 더 짧아진다","mis":"K6-2-u3-X15"}],"explanation":["「좋은 점 세 가지」는 알려 주는 제목처럼 보여요.","「걸으면 보이는 것」은 생각을 먼저 심어요.","제목의 낱말 하나에 만든 사람의 눈이 담겨요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#4','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'mc','auto','「멈추면 들리는 소리」의 주장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":4,"concept":"K6-2-u3-C9","difficulty":3,"kind":"mc","stem":"「멈추면 들리는 소리」의 주장으로 알맞은 것은 어느 것인가요?","options":[{"t":"켜 둔 화면을 끄고 멈추어 주변의 소리를 들어 보자","correct":true},{"t":"방 안에 화면을 여러 개 켜 두자","mis":"K6-2-u3-X15"},{"t":"집에서 새를 기르자","mis":"K6-2-u3-X15"},{"t":"비 오는 날에는 밖에 나가지 말자","mis":"K6-2-u3-X15"}],"explanation":["「끄면」이 되풀이되며 커져요.","새소리·빗소리는 끄면 들리는 소리예요.","마지막 자막이 「멈추면, 들립니다」예요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#5','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'match','auto','「멈추면 들리는 소리」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C9","difficulty":3,"kind":"match","stem":"「멈추면 들리는 소리」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.","pairs":[{"l":"제목","r":"멈추면 들리는 소리"},{"l":"제시한 자료","r":"십 분씩 소리를 들어 본 사람들이 겪은 일"},{"l":"강조하는 표현","r":"되풀이되며 커지는 자막 「끄면」"}],"mis":"K6-2-u3-X15","explanation":["제목은 영상의 이름이에요.","사람들이 겪은 일은 자료예요.","되풀이되며 커지는 자막은 강조예요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#6','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'ox','auto','「멈추면 들리는 소리」의 주장을 파악하는 데 영상에 나오는 방의 벽 색깔이 도움이 돼요.',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":6,"concept":"K6-2-u3-C9","difficulty":3,"kind":"ox","stem":"「멈추면 들리는 소리」의 주장을 파악하는 데 영상에 나오는 방의 벽 색깔이 도움이 돼요.","answer":"X","reason_options":[{"t":"제목 · 자료 · 강조하는 장면이나 표현 세 갈래에 들지 않기 때문에","correct":true},{"t":"영상에 나오는 것은 모두 주장을 알려 주기 때문에","mis":"K6-2-u3-X15"}],"mis":"K6-2-u3-X15","explanation":["주장을 찾는 실마리는 세 갈래예요.","벽 색깔이나 영상 길이는 들지 않아요.","세 갈래만 모아 한 문장으로 만들어요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#7','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'error','auto','영상의 주장을 파악하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X16']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":3,"kind":"error","stem":"영상의 주장을 파악하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「제목만 보면 주장을 알 수 있으니 영상은 안 봐도 돼.」","correct":true,"mis_target":"K6-2-u3-X15"},{"t":"다인 — 「제목 · 자료 · 강조된 표현을 합쳐 한 문장으로 만들어.」","mis":"K6-2-u3-X15"},{"t":"루아 — 「‘그래서 나더러 무엇을 하라는 걸까’를 스스로 물어 봐.」","mis":"K6-2-u3-X16"}],"explanation":["다인은 세 갈래를 합쳤어요.","루아는 스스로 묻는 방법을 말했어요.","태오는 한 갈래만 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#8','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',4,'mc','auto','「주장을 찾는 일」과 「주장이 타당한지 따지는 일」을 바르게 설명한 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X16']::text[],false,'{"seq":8,"concept":"K6-2-u3-C10","difficulty":4,"kind":"mc","stem":"「주장을 찾는 일」과 「주장이 타당한지 따지는 일」을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"강조된 장면은 주장을 찾는 실마리가 되고, 타당한지는 자료가 이유를 뒷받침하는지로 따로 따진다","correct":true},{"t":"두 일은 같다 — 강조가 센 주장이 타당하다","mis":"K6-2-u3-X17"},{"t":"강조된 장면이 없으면 주장도 없다","mis":"K6-2-u3-X16"},{"t":"타당한지는 음악과 자막의 세기로 잰다","mis":"K6-2-u3-X17"}],"explanation":["찾는 일은 제목·자료·강조로 해요.","따지는 일은 세 기준으로 해요.","강조의 세기와 타당성은 아무 관계가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#9','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',4,'essay','teacher','「멈추면 들리는 소리」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고, 셋을 합쳐 이 영상의 주장을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C9","difficulty":4,"kind":"essay","stem":"「멈추면 들리는 소리」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고, 셋을 합쳐 이 영상의 주장을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 제목 — 「멈추면 들리는 소리」로, 멈추어야 들리는 것이 있다는 생각을 심어 준다. 자료 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면이다. 강조 — 화면을 끌 때마다 커지는 자막 「끄면」과, 음악이 멈추고 남는 자막 「멈추면, 들립니다」이다. 주장 — 켜 둔 화면을 끄고 잠깐 멈추어 주변의 소리를 들어 보자.","scoring_points":["제목·자료·강조하는 표현을 하나씩 바르게 찾았는가","셋을 합쳐 주장을 한 문장으로 썼는가","주장이 무엇을 하자는 말로 되어 있는가"]},"explanation":["세 갈래를 하나씩 찾아요.","따로 보면 흩어져 보여요.","합치면 한 문장이 돼요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#10','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',4,'essay','teacher','「강조가 세다고 주장이 타당한 것은 아니다.」라는 말을 「걸으면 보이는 것」의 장면을 들어 설명하세요. 강조가 알려 주는 것과 알려 주지 못하는 것을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C10","difficulty":4,"kind":"essay","stem":"「강조가 세다고 주장이 타당한 것은 아니다.」라는 말을 「걸으면 보이는 것」의 장면을 들어 설명하세요. 강조가 알려 주는 것과 알려 주지 못하는 것을 함께 쓰세요.","answer_guide":{"answer":"예: 장면 5에서 음악이 멈추고 「가까운 길은, 걸어서」만 남는다. 이 강조는 만든 사람이 「가까운 곳은 걸어서 다니자」를 가장 하고 싶은 말로 여긴다는 것을 알려 준다. 그러나 이 주장이 타당한지는 알려 주지 못한다. 타당한지는 장면 3의 조사 화면이 믿을 만한 자료인지, 그 자료가 이유를 뒷받침하는지를 따져 보아야 알 수 있다.","scoring_points":["영상의 강조된 장면을 들었는가","강조가 알려 주는 것(하고 싶은 말)을 썼는가","강조가 알려 주지 못하는 것(타당성)과 따지는 방법을 썼는가"]},"explanation":["강조는 「무엇을」 말하고 싶은지 알려 줘요.","「옳은지」는 알려 주지 못해요.","타당성은 자료로 따져요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#1','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'mc','auto','카드 뉴스를 볼 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X02']::text[],false,'{"seq":1,"concept":"K6-2-u3-C11","difficulty":1,"kind":"mc","stem":"카드 뉴스를 볼 때 알맞은 태도는 어느 것인가요?","options":[{"t":"주장하는 내용이 있다면 그 타당성을 평가하며 본다","correct":true},{"t":"그림이 예쁜지만 보고 넘긴다","mis":"K6-2-u3-X03"},{"t":"카드 뉴스는 짧으니 믿지 않고 넘긴다","mis":"K6-2-u3-X02"},{"t":"장 수가 많으면 그대로 믿는다","mis":"K6-2-u3-X03"}],"explanation":["카드 뉴스도 주장을 담아요.","그림이 보기 좋은 것과 내용이 타당한 것은 달라요.","믿거나 안 믿거나가 아니라 따져 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#2','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'sa','auto','카드 뉴스 「밤이 너무 밝습니다」의 주장은 「필요 없는 밤 ○○을 줄입시다.」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C11","difficulty":1,"kind":"sa","stem":"카드 뉴스 「밤이 너무 밝습니다」의 주장은 「필요 없는 밤 ○○을 줄입시다.」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["불빛"],"explanation":["주장은 첫째 장에 있어요.","제목과 굵은 글씨를 보아요.","「필요 없는 밤 불빛을 줄입시다」예요."],"asset":{"type":"passage","lines":["첫째 장 — 밤이 너무 밝습니다. 필요 없는 밤 불빛을 줄입시다.","둘째 장 — 밤 불빛은 해가 진 뒤에 사람이 켜 두는 빛입니다.","가로등, 가게 간판, 건물 안팎의 불빛이 모두 여기에 듭니다.","꼭 있어야 하는 빛도 있지만, 아무도 쓰지 않는데 켜져 있는 빛도 있습니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 첫째 · 둘째 장"},"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#3','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'ox','auto','카드 뉴스는 글이 짧으니 따져 볼 것이 적어요.',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":3,"concept":"K6-2-u3-C11","difficulty":1,"kind":"ox","stem":"카드 뉴스는 글이 짧으니 따져 볼 것이 적어요.","answer":"X","reason_options":[{"t":"짧을수록 빠진 것이 잘 보이지 않아 오히려 따져 볼 것이 많기 때문에","correct":true},{"t":"짧은 글에는 주장 · 이유 · 근거가 들어가지 않기 때문에","mis":"K6-2-u3-X03"}],"mis":"K6-2-u3-X03","explanation":["카드 뉴스는 핵심만 빠르게 전해요.","짧으면 빠진 것이 눈에 잘 띄지 않아요.","그래서 더 따져 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#4','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'mc','auto','카드 뉴스에서 주장이 대개 들어 있는 자리는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C11","difficulty":1,"kind":"mc","stem":"카드 뉴스에서 주장이 대개 들어 있는 자리는 어느 것인가요?","options":[{"t":"첫 장의 제목과 굵은 글씨","correct":true},{"t":"마지막 장의 그림","mis":"K6-2-u3-X01"},{"t":"가운데 장의 근거","mis":"K6-2-u3-X01"},{"t":"카드 뉴스에는 주장이 없다","mis":"K6-2-u3-X03"}],"explanation":["첫 장에 제목과 주장이 들어가요.","가운데 장에는 이유와 근거가 한 쌍씩 놓여요.","주장은 첫 장부터 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#5','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'match','auto','「밤이 너무 밝습니다」에서 각 이유와 그 이유를 받쳐 준 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C11","difficulty":2,"kind":"match","stem":"「밤이 너무 밝습니다」에서 각 이유와 그 이유를 받쳐 준 근거를 알맞게 이으세요.","pairs":[{"l":"① 잠을 방해한다","r":"잠드는 데 걸리는 시간이 길어진다는 연구 결과"},{"l":"② 해마다 늘고 있다","r":"밤 밝기를 해마다 조사한 그래프"},{"l":"③ 곤충과 새의 생활을 어지럽힌다","r":"지나친 빛을 막기 위한 우리나라의 제도"}],"mis":"K6-2-u3-X01","explanation":["같은 장에 함께 놓인 것끼리 이어요.","이유와 근거를 한 쌍씩 갈라내요.","그래야 하나씩 따져 볼 수 있어요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#6','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'mc','auto','「필요 없는 밤 불빛을 줄입시다」가 가치 있고 중요한 주장인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X07']::text[],false,'{"seq":6,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"「필요 없는 밤 불빛을 줄입시다」가 가치 있고 중요한 주장인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람의 잠과 주변 생물의 생활과 이어져 있고, 불빛 하나를 끄는 일은 오늘 바로 할 수 있어서","correct":true},{"t":"카드 뉴스의 그림이 보기 좋아서","mis":"K6-2-u3-X03"},{"t":"카드가 모두 여섯 장이어서","mis":"K6-2-u3-X03"},{"t":"밤이 무섭다는 사람이 많아서","mis":"K6-2-u3-X07"}],"explanation":["문제 해결에 도움이 되는지 보아요.","실천 가능한지 보아요.","그림이나 장 수는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#7','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',2,'mc','auto','「밤이 너무 밝습니다」에서 주장을 뒷받침하는 힘이 가장 약한 이유는 어느 것인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X02']::text[],false,'{"seq":7,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"「밤이 너무 밝습니다」에서 주장을 뒷받침하는 힘이 가장 약한 이유는 어느 것인가요?","options":[{"t":"밤에 켜 두는 불빛이 해마다 늘고 있기 때문이다","correct":true},{"t":"지나친 밤 불빛은 잠을 방해하기 때문이다","mis":"K6-2-u3-X18"},{"t":"곤충과 새의 생활을 어지럽히기 때문이다","mis":"K6-2-u3-X18"},{"t":"세 이유가 모두 똑같이 약하다","mis":"K6-2-u3-X02"}],"explanation":["세 이유에 「그래서 왜 줄여야 하는데?」를 물어요.","①과 ③은 무엇이 나빠지는지 말해요.","②는 얼마나 많은지만 말해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#8','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',2,'ox','auto','이유 하나와 근거 하나가 약하니 「밤 불빛을 줄이자」는 틀린 주장이에요.',ARRAY['K6-2-u3-X20']::text[],false,'{"seq":8,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"이유 하나와 근거 하나가 약하니 「밤 불빛을 줄이자」는 틀린 주장이에요.","answer":"X","reason_options":[{"t":"주장은 가치 있고 튼튼한 근거도 있어, 약한 자리만 고치면 되기 때문에","correct":true},{"t":"약한 데가 하나라도 있으면 그 카드 뉴스는 믿을 수 없기 때문에","mis":"K6-2-u3-X20"}],"mis":"K6-2-u3-X20","explanation":["주장은 가치 있고 실천 가능해요.","근거 ①과 ②는 확인할 수 있는 자료예요.","약한 자리는 고칠 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#9','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'mc','auto','카드 뉴스의 이유마다 던져 보면 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X03']::text[],false,'{"seq":9,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"카드 뉴스의 이유마다 던져 보면 좋은 물음은 어느 것인가요?","options":[{"t":"「그래서 왜 그래야 하는데?」","correct":true},{"t":"「이 이유는 몇 글자일까?」","mis":"K6-2-u3-X12"},{"t":"「이 이유를 쓴 사람은 유명할까?」","mis":"K6-2-u3-X03"},{"t":"「이 이유 옆에 그림이 있을까?」","mis":"K6-2-u3-X03"}],"explanation":["이유는 주장의 까닭을 말해야 해요.","「그래서 왜?」에 답하는지 보아요.","글자 수나 그림은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#10','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',3,'mc','auto','근거 ③이 이유 ③을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X08']::text[],false,'{"seq":10,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"근거 ③이 이유 ③을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"제도는 문제에 대한 해결 방안이지 생활이 어지럽혀진다는 것을 보여 주지 못해서","correct":true},{"t":"제도라는 낱말이 어려워서","mis":"K6-2-u3-X19"},{"t":"우리나라만 다루고 다른 나라는 다루지 않아서","mis":"K6-2-u3-X19"},{"t":"근거는 많을수록 좋은데 하나뿐이어서","mis":"K6-2-u3-X08"}],"explanation":["이유 ③은 「생활을 어지럽힌다」예요.","근거 ③은 그 뒤에 나선 해결 방안이에요.","이유를 보여 주는 자료가 아니에요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#1','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',2,'sa','auto','이유 ②는 밤 불빛이 얼마나 많은지, 곧 문제의 ○○만 말해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C12","difficulty":2,"kind":"sa","stem":"이유 ②는 밤 불빛이 얼마나 많은지, 곧 문제의 ○○만 말해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["규모"],"explanation":["규모는 일이 벌어진 크기나 범위예요.","많다는 것만으로는 나쁜 것이 되지 않아요.","무엇이 어떻게 나빠지는지까지 말해야 해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"},"mis":"K6-2-u3-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#2','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',2,'mc','auto','카드 뉴스의 근거마다 던져 보면 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X17','K6-2-u3-X01']::text[],false,'{"seq":2,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"카드 뉴스의 근거마다 던져 보면 좋은 물음은 어느 것인가요?","options":[{"t":"「이게 그 이유를 보여 주나?」","correct":true},{"t":"「이 근거는 길까?」","mis":"K6-2-u3-X08"},{"t":"「이 근거가 마음을 세게 움직이나?」","mis":"K6-2-u3-X17"},{"t":"「이 근거는 몇 번째 장에 있나?」","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주어야 해요.","그 이유를 정말 보여 주는지 물어요.","길이나 마음의 세기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#3','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'mc','auto','이유 ②를 주장을 뒷받침하는 이유로 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X01','K6-2-u3-X07']::text[],false,'{"seq":3,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"이유 ②를 주장을 뒷받침하는 이유로 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"늘어난 밤 불빛 때문에 잠을 설치거나 생활이 어지럽혀지는 생물이 함께 늘기 때문이다","correct":true},{"t":"밤 불빛이 아주아주 많이 늘고 있기 때문이다","mis":"K6-2-u3-X18"},{"t":"밤 불빛이 늘고 있다는 그래프가 있기 때문이다","mis":"K6-2-u3-X01"},{"t":"밤 불빛이 늘어서 속상하기 때문이다","mis":"K6-2-u3-X07"}],"explanation":["늘고 있다는 것은 규모예요.","늘어서 무엇이 나빠지는지 말해야 이유가 서요.","더 크게 말하거나 근거를 이유 자리에 넣으면 안 돼요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#4','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'mc','auto','근거 ③ 대신 이유 ③을 뒷받침할 근거로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X08']::text[],false,'{"seq":4,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"근거 ③ 대신 이유 ③을 뒷받침할 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"밤 불빛 둘레에 곤충이 모여들어 맴도는 모습을 관찰한 기록","correct":true},{"t":"지나친 빛을 막는 다른 나라의 규칙","mis":"K6-2-u3-X19"},{"t":"밤 불빛을 줄이자는 행사 소식","mis":"K6-2-u3-X19"},{"t":"나는 밤에 새소리를 좋아한다는 말","mis":"K6-2-u3-X08"}],"explanation":["이유 ③은 생활이 어지럽혀진다는 것이에요.","그 모습을 보여 주는 관찰 기록이 근거가 돼요.","규칙이나 행사는 해결 방안이에요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#5','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',3,'ox','auto','카드 뉴스를 평가할 때에는 약한 자리부터 찾아야 해요.',ARRAY['K6-2-u3-X11']::text[],false,'{"seq":5,"concept":"K6-2-u3-C11","difficulty":3,"kind":"ox","stem":"카드 뉴스를 평가할 때에는 약한 자리부터 찾아야 해요.","answer":"X","reason_options":[{"t":"잘 세워진 자리를 먼저 세고 나서 약한 자리를 찾아야 무엇을 살리고 고칠지 보이기 때문에","correct":true},{"t":"평가는 고칠 곳을 찾는 일이니 약한 곳부터 찾아야 하기 때문에","mis":"K6-2-u3-X11"}],"mis":"K6-2-u3-X11","explanation":["이 카드 뉴스에는 잘 세워진 자리가 더 많아요.","그것부터 세요.","그다음 약한 자리를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#6','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'match','auto','「밤이 너무 밝습니다」의 자리와 그 자리를 판단한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C12","difficulty":3,"kind":"match","stem":"「밤이 너무 밝습니다」의 자리와 그 자리를 판단한 내용을 알맞게 이으세요.","pairs":[{"l":"주장","r":"가치 있고 실천 가능하다"},{"l":"이유 ②","r":"문제의 규모만 말해 힘이 약하다"},{"l":"근거 ③","r":"해결 방안이라 이유를 보여 주지 못한다"},{"l":"근거 ①","r":"확인할 수 있는 자료로 이유를 잘 받쳐 준다"}],"mis":"K6-2-u3-X18","explanation":["주장과 근거 ①은 튼튼해요.","이유 ②는 규모만 말해요.","근거 ③은 해결 방안이에요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#7','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'error','auto','「밤이 너무 밝습니다」를 평가한 말이에요. 지나치게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X11']::text[],false,'{"seq":7,"concept":"K6-2-u3-C12","difficulty":3,"kind":"error","stem":"「밤이 너무 밝습니다」를 평가한 말이에요. 지나치게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「약한 데가 있으니 이 카드 뉴스는 믿을 수 없어.」","correct":true,"mis_target":"K6-2-u3-X20"},{"t":"하랑 — 「주장은 가치 있고 근거 두 개는 튼튼해. 다만 이유 ②와 근거 ③은 고치면 좋겠어.」","mis":"K6-2-u3-X20"},{"t":"주원 — 「이유 ①과 ③은 왜 줄여야 하는지를 곧바로 말해 줘.」","mis":"K6-2-u3-X11"}],"explanation":["하랑은 타당한 점과 고칠 자리를 함께 말했어요.","주원은 잘 세워진 자리를 짚었어요.","서아는 하나가 약하다고 전체를 버렸어요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#8','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',4,'mc','auto','이유 ②와 근거 ③의 약한 점을 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X08','K6-2-u3-X02']::text[],false,'{"seq":8,"concept":"K6-2-u3-C12","difficulty":4,"kind":"mc","stem":"이유 ②와 근거 ③의 약한 점을 바르게 가른 것은 어느 것인가요?","options":[{"t":"이유 ②는 문제의 규모만 말하고 까닭을 말하지 않으며, 근거 ③은 이유를 보여 주지 않고 해결 방안을 말한다","correct":true},{"t":"이유 ②는 해결 방안을 말하고, 근거 ③은 문제의 규모를 말한다","mis":"K6-2-u3-X19"},{"t":"둘 다 말한 사람의 느낌이라 주관적이다","mis":"K6-2-u3-X08"},{"t":"둘 다 주장과 관련이 없어 지워야 한다","mis":"K6-2-u3-X02"}],"explanation":["이유 ②의 약함은 규모예요.","근거 ③의 약함은 해결 방안이에요.","약한 갈래가 서로 달라요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#9','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',4,'essay','teacher','「밤이 너무 밝습니다」를 평가 기준표 세 항목에 ◎ · ○ · △로 판단하고 까닭을 한 문장씩 쓰세요. 타당한 점을 먼저 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C11","difficulty":4,"kind":"essay","stem":"「밤이 너무 밝습니다」를 평가 기준표 세 항목에 ◎ · ○ · △로 판단하고 까닭을 한 문장씩 쓰세요. 타당한 점을 먼저 쓰세요.","answer_guide":{"answer":"예: 주장 ◎ — 사람의 잠과 생물의 생활에 도움이 되고 불빛 하나를 끄는 일은 오늘 바로 할 수 있다. 이유 ○ — 이유 ①과 ③은 왜 줄여야 하는지를 곧바로 말하지만 이유 ②는 늘고 있다는 규모만 말해 보통이다. 근거 ○ — 근거 ①과 ②는 확인할 수 있는 자료이지만 근거 ③은 해결 방안이라 이유 ③을 보여 주지 못한다.","scoring_points":["세 항목에 판단을 표시했는가","타당한 점을 먼저 쓰고 약한 자리를 까닭과 함께 썼는가","이유 ②(규모)와 근거 ③(해결 방안)의 약한 까닭을 바르게 썼는가"]},"explanation":["잘 세워진 자리부터 세요.","약한 자리는 까닭과 함께 써요.","표시마다 한 문장씩 붙여요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#10','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',4,'essay','teacher','근거 ③이 이유 ③을 뒷받침하지 못하는 까닭을 쓰고, 이유 ③을 뒷받침할 근거를 새로 생각해 쓰세요. 숫자를 지어내지 말고, 그 근거가 사실인지 확인할 방법도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C12","difficulty":4,"kind":"essay","stem":"근거 ③이 이유 ③을 뒷받침하지 못하는 까닭을 쓰고, 이유 ③을 뒷받침할 근거를 새로 생각해 쓰세요. 숫자를 지어내지 말고, 그 근거가 사실인지 확인할 방법도 함께 쓰세요.","answer_guide":{"answer":"예: 근거 ③의 제도는 문제를 막으려고 마련한 해결 방안이어서, 밤 불빛이 곤충과 새의 생활을 어지럽힌다는 것을 보여 주지 못한다. 새 근거 — 밤 불빛 둘레에 곤충이 모여들어 맴도는 모습을 관찰한 기록. 확인 방법 — 밤 불빛과 생물에 대해 다룬 책이나 기사를 찾아보고, 생물을 연구하는 기관의 누리집에서 출처를 확인한다.","scoring_points":["근거 ③이 해결 방안이라 이유를 보여 주지 못한다는 것을 썼는가","이유 ③을 보여 주는 새 근거를 썼는가","숫자를 지어내지 않고 확인 방법을 썼는가"]},"explanation":["근거는 이유를 보여 주어야 해요.","해결 방안은 그 뒤의 일이에요.","확인할 방법까지 생각해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#1','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',1,'mc','auto','주제와 관련된 영상을 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u3-X22','K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C13","difficulty":1,"kind":"mc","stem":"주제와 관련된 영상을 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"주제와 관련된 구체적인 말로 찾고, 끝에 「어린이 · 교육용」 같은 말을 붙인다","correct":true},{"t":"두루뭉술한 한 낱말로만 찾는다","mis":"K6-2-u3-X22"},{"t":"자동으로 뜨는 자극적인 말을 눌러 본다","mis":"K6-2-u3-X22"},{"t":"조회 수가 가장 많은 영상만 고른다","mis":"K6-2-u3-X03"}],"explanation":["구체적인 말로 찾아야 엉뚱한 영상이 덜 나와요.","「어린이·교육용·뉴스」를 붙이면 볼 만한 영상이 나와요.","자극적인 말은 무시해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#2','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',1,'sa','auto','「넣고」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C14","difficulty":1,"kind":"sa","stem":"「넣고」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.","answer":["너코","[너코]"],"explanation":["받침 ㅎ 뒤에 ㄱ이 왔어요.","ㅎ과 ㄱ이 합쳐 ㅋ이 돼요.","그래서 [너코]로 소리 나요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#3','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',1,'ox','auto','주장이 없는 영상은 평가표로 잴 수 없어요.',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":3,"concept":"K6-2-u3-C13","difficulty":1,"kind":"ox","stem":"주장이 없는 영상은 평가표로 잴 수 없어요.","answer":"O","reason_options":[{"t":"평가표는 주장 · 이유 · 근거를 재는 것이라 주장이 없으면 잴 것이 없기 때문에","correct":true},{"t":"영상이라면 모두 평가표로 잴 수 있기 때문에","mis":"K6-2-u3-X21"}],"mis":"K6-2-u3-X21","explanation":["평가표의 세 항목은 주장·이유·근거예요.","주장이 없으면 잴 것이 없어요.","먼저 평가할 수 있는 영상인지 가려내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#4','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',1,'mc','auto','「좋아」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":4,"concept":"K6-2-u3-C14","difficulty":1,"kind":"mc","stem":"「좋아」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[조아]","correct":true},{"t":"[조하]","mis":"K6-2-u3-X23"},{"t":"[존아]","mis":"K6-2-u3-X23"},{"t":"[조타]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 모음이 왔어요.","모음 앞에서는 ㅎ 소리를 내지 않아요.","그래서 [조아]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#5','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'mc','auto','「물 아껴 쓰기」를 다룬 세 영상 가운데 주장이 가장 뚜렷한 영상은 어느 것인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X21']::text[],false,'{"seq":5,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"「물 아껴 쓰기」를 다룬 세 영상 가운데 주장이 가장 뚜렷한 영상은 어느 것인가요?","options":[{"t":"수도꼭지 삼십 초","correct":true},{"t":"물이 오는 길","mis":"K6-2-u3-X15"},{"t":"우리 집 물 쓰기 도전","mis":"K6-2-u3-X21"},{"t":"셋 다 똑같이 뚜렷하다","mis":"K6-2-u3-X21"}],"explanation":["「수도꼭지 삼십 초」는 언제 무엇을 할지 또렷하게 말해요.","「물이 오는 길」은 알려 주는 영상이에요.","「물 쓰기 도전」의 주장은 넓고 근거가 소감이에요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#6','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'match','auto','각 영상과 그 영상에서 살펴야 할 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C13","difficulty":2,"kind":"match","stem":"각 영상과 그 영상에서 살펴야 할 자리를 알맞게 이으세요.","pairs":[{"l":"수도꼭지 삼십 초","r":"주장 · 이유 · 근거가 모두 갖추어져 있다"},{"l":"물이 오는 길","r":"주장이 없어서 평가표로 잴 수 없다"},{"l":"우리 집 물 쓰기 도전","r":"근거가 만든 사람의 느낌에 머물러 있다"}],"mis":"K6-2-u3-X21","explanation":["약한 자리의 갈래가 서로 달라요.","주장이 없는 영상은 평가 대상이 아니에요.","근거가 소감이면 객관적이지 않아요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#7','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'mc','auto','영상을 보는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":7,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"영상을 보는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"자세히 보기 → 알아낸 것 말하기 → 무슨 일이 일어나는지 생각하기 → 궁금한 것 묻기","correct":true},{"t":"생각하기 → 자세히 보기 → 궁금한 것 묻기 → 알아낸 것 말하기","mis":"K6-2-u3-X22"},{"t":"궁금한 것 묻기 → 생각하기 → 자세히 보기","mis":"K6-2-u3-X22"},{"t":"자세히 보기 → 생각하기 → 궁금한 것 묻기","mis":"K6-2-u3-X22"}],"explanation":["먼저 말하지 않고 끝까지 보아요.","본 것만 말한 뒤에 생각해요.","마지막에 남은 물음을 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#8','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',2,'mc','auto','「빨갛다」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":2,"kind":"mc","stem":"「빨갛다」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[빨가타]","correct":true},{"t":"[빨갇다]","mis":"K6-2-u3-X23"},{"t":"[빨가다]","mis":"K6-2-u3-X23"},{"t":"[빨각따]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐 ㅌ이 돼요.","그래서 [빨가타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#9','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'ox','auto','영상을 평가할 때에는 말투 · 편집 · 음악을 먼저 보고 그다음에 주장 · 이유 · 근거를 봐요.',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":9,"concept":"K6-2-u3-C13","difficulty":2,"kind":"ox","stem":"영상을 평가할 때에는 말투 · 편집 · 음악을 먼저 보고 그다음에 주장 · 이유 · 근거를 봐요.","answer":"X","reason_options":[{"t":"내용의 타당성을 먼저 평가하고 표현은 그다음에 살펴야 하기 때문에","correct":true},{"t":"재미있는 영상이 곧 타당한 영상이기 때문에","mis":"K6-2-u3-X21"}],"mis":"K6-2-u3-X21","explanation":["말투·편집·음악도 살필 수 있어요.","그러나 차례가 있어요.","차례를 바꾸면 재미있는 영상이 곧 타당한 영상이 돼 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#10','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',3,'error','auto','가장 타당한 영상을 고른 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":10,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"가장 타당한 영상을 고른 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예린 — 「‘우리 집 물 쓰기 도전’은 음악이 신나서 가장 타당해.」","correct":true,"mis_target":"K6-2-u3-X21"},{"t":"도겸 — 「‘수도꼭지 삼십 초’는 누가 보아도 확인할 수 있는 자료로 이유를 받쳤어.」","mis":"K6-2-u3-X21"},{"t":"하율 — 「‘물이 오는 길’은 주장이 없어서 평가에서 뺐어.」","mis":"K6-2-u3-X21"}],"explanation":["도겸은 근거의 객관성을 까닭으로 들었어요.","하율은 평가할 수 있는 영상을 먼저 가려냈어요.","예린은 표현으로 타당성을 판단했어요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#1','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',2,'sa','auto','「그렇지」를 소리 나는 대로 쓰세요. 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C14","difficulty":2,"kind":"sa","stem":"「그렇지」를 소리 나는 대로 쓰세요. 세 글자로 쓰세요.","answer":["그러치","[그러치]"],"explanation":["받침 ㅎ 뒤에 ㅈ이 왔어요.","ㅎ과 ㅈ이 합쳐 ㅊ이 돼요.","그래서 [그러치]예요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#2','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',2,'mc','auto','친구에게 영상을 설명할 때 넣어야 할 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X12']::text[],false,'{"seq":2,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"친구에게 영상을 설명할 때 넣어야 할 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"제목 · 주장 · 이유 · 근거 · 세 기준으로 판단한 결과 · 그렇게 판단한 까닭","correct":true},{"t":"영상을 몇 번 보았는지 · 나온 사람의 옷차림","mis":"K6-2-u3-X21"},{"t":"제목과 판단 결과만","mis":"K6-2-u3-X12"},{"t":"영상이 재미있었다는 느낌만","mis":"K6-2-u3-X12"}],"explanation":["듣는 친구가 내 판단을 따라올 수 있어야 해요.","주장·이유·근거와 판단을 넣어요.","왜 그렇게 판단했는지 까닭도 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#3','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'mc','auto','「우리 집 물 쓰기 도전」의 근거를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X17','K6-2-u3-X08']::text[],false,'{"seq":3,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"「우리 집 물 쓰기 도전」의 근거를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"도전하기 전과 도전한 뒤에 쓴 물의 양을 재어 견주어 보여 준다","correct":true},{"t":"도전이 얼마나 뿌듯했는지 더 크게 말한다","mis":"K6-2-u3-X14"},{"t":"신나는 음악을 더 넣는다","mis":"K6-2-u3-X17"},{"t":"도전한 사람을 더 많이 보여 준다","mis":"K6-2-u3-X08"}],"explanation":["지금 근거는 만든 사람의 소감이에요.","누가 보아도 확인할 수 있는 자료로 바꾸어요.","전과 뒤를 견주면 객관적인 근거가 돼요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#4','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',3,'mc','auto','「넣는」의 바른 발음과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":4,"concept":"K6-2-u3-C14","difficulty":3,"kind":"mc","stem":"「넣는」의 바른 발음과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"[넌는] — 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ을 ㄴ으로 발음해서","correct":true},{"t":"[너는] — 받침 ㅎ은 소리를 내지 않아서","mis":"K6-2-u3-X23"},{"t":"[너흔] — ㅎ을 그대로 뒤로 넘겨서","mis":"K6-2-u3-X23"},{"t":"[넏는] — ㅎ을 ㄷ으로 끊어 발음해서","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄴ이 왔어요.","이때는 ㅎ을 ㄴ으로 발음해요.","그래서 [넌는]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#5','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'ox','auto','영상을 볼 때 「알아낸 것 말하기」와 「생각하기」를 한꺼번에 해도 돼요.',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":5,"concept":"K6-2-u3-C13","difficulty":3,"kind":"ox","stem":"영상을 볼 때 「알아낸 것 말하기」와 「생각하기」를 한꺼번에 해도 돼요.","answer":"X","reason_options":[{"t":"한꺼번에 하면 본 것과 짐작한 것이 섞이기 때문에","correct":true},{"t":"본 것과 짐작한 것은 같은 것이기 때문에","mis":"K6-2-u3-X22"}],"mis":"K6-2-u3-X22","explanation":["알아낸 것은 본 것만 말해요.","생각하기는 무슨 일이 일어나는지 말해요.","둘을 나누어야 섞이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#6','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',3,'match','auto','받침 ㅎ 뒤에 오는 소리와 그 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C14","difficulty":3,"kind":"match","stem":"받침 ㅎ 뒤에 오는 소리와 그 발음을 알맞게 이으세요.","pairs":[{"l":"ㄱ · ㄷ · ㅈ이 올 때","r":"합쳐서 ㅋ · ㅌ · ㅊ으로 발음한다"},{"l":"ㄴ이 올 때","r":"ㄴ으로 발음한다"},{"l":"모음이 올 때","r":"ㅎ 소리를 내지 않는다"}],"mis":"K6-2-u3-X23","explanation":["넣고[너코] — ㄱ과 합쳐요.","넣는[넌는] — ㄴ으로 소리 나요.","좋아[조아] — ㅎ 소리가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#7','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'error','auto','평가할 수 있는 영상인지 가려내는 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X08']::text[],false,'{"seq":7,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"평가할 수 있는 영상인지 가려내는 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「‘물이 오는 길’은 근거가 약하니 △로 표시하면 돼.」","correct":true,"mis_target":"K6-2-u3-X21"},{"t":"아린 — 「‘물이 오는 길’은 무엇을 하자는 말이 없으니 평가표에서 빼야 해.」","mis":"K6-2-u3-X21"},{"t":"서준 — 「‘우리 집 물 쓰기 도전’은 주장은 있지만 근거가 느낌이야.」","mis":"K6-2-u3-X08"}],"explanation":["「물이 오는 길」은 알려 주는 영상이에요.","주장이 없으니 평가표로 잴 수 없어요.","△는 평가할 수 있는 영상에 쓰는 표시예요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#8','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',4,'mc','auto','친구와 가장 타당한 영상을 다르게 골랐을 때 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X02']::text[],false,'{"seq":8,"concept":"K6-2-u3-C13","difficulty":4,"kind":"mc","stem":"친구와 가장 타당한 영상을 다르게 골랐을 때 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「나는 근거가 객관적인지를 가장 무겁게 보았어. 너는 어떤 기준을 무겁게 보았니?」","correct":true},{"t":"「내 생각이 맞으니까 너도 바꿔.」","mis":"K6-2-u3-X12"},{"t":"「둘 다 틀렸으니 다른 영상을 찾자.」","mis":"K6-2-u3-X02"},{"t":"「그냥 그 영상이 좋았어.」","mis":"K6-2-u3-X12"}],"explanation":["판단은 갈릴 수 있어요.","어떤 기준을 무겁게 보았는지 서로 말해요.","까닭이 있어야 이야기가 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#9','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',4,'essay','teacher','「물 아껴 쓰기」를 다룬 세 영상 가운데 가장 타당한 영상을 골라, 제목 → 주장 → 이유 → 근거 → 판단 → 까닭 차례로 친구에게 설명하는 말을 쓰세요. 다른 두 영상을 고르지 않은 까닭도 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"「물 아껴 쓰기」를 다룬 세 영상 가운데 가장 타당한 영상을 골라, 제목 → 주장 → 이유 → 근거 → 판단 → 까닭 차례로 친구에게 설명하는 말을 쓰세요. 다른 두 영상을 고르지 않은 까닭도 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 제가 고른 영상은 「수도꼭지 삼십 초」입니다. 주장은 이를 닦는 동안 수도꼭지를 잠그자는 것이고, 이유는 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문입니다. 근거로 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 주었습니다. 세 기준 모두 ◎로 판단했는데, 누가 보아도 확인할 수 있는 자료로 이유를 받쳤기 때문입니다. 「물이 오는 길」은 주장이 없어 평가에서 뺐고, 「우리 집 물 쓰기 도전」은 근거가 만든 사람의 소감이라 고르지 않았습니다.","scoring_points":["제목·주장·이유·근거·판단·까닭을 차례대로 썼는가","판단한 까닭이 세 기준에 맞는가","다른 두 영상을 고르지 않은 까닭을 바르게 썼는가"]},"explanation":["설명의 차례를 지켜요.","판단에는 까닭을 붙여요.","주장이 없는 영상은 먼저 가려내요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#10','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',4,'essay','teacher','「놓고」 · 「놓는」 · 「놓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C14","difficulty":4,"kind":"essay","stem":"「놓고」 · 「놓는」 · 「놓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「책상 위에 가방을 놓고 앉았다.」에서 「놓고」는 [노코], 「꽃병을 놓는 자리를 찾았다.」에서 「놓는」은 [논는], 「컵을 식탁에 놓아 두었다.」에서 「놓아」는 [노아]로 소리 난다. 받침 ㅎ 뒤에 ㄱ이 오면 합쳐서 ㅋ으로, ㄴ이 오면 ㄴ으로 소리 나고, 모음이 오면 ㅎ 소리를 내지 않기 때문이다.","scoring_points":["세 낱말을 넣어 문장을 하나씩 만들었는가","[노코]·[논는]·[노아]로 바르게 썼는가","뒤에 오는 소리에 따른 까닭을 썼는가"]},"explanation":["ㄱ 앞 — 합쳐서 ㅋ.","ㄴ 앞 — ㄴ으로.","모음 앞 — 소리 없음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#1','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',1,'mc','auto','윤채가 한 말의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"윤채가 한 말의 주장은 무엇인가요?","options":[{"t":"쉬는 시간마다 교실 창문을 열자","correct":true},{"t":"창문을 닫아 두면 교실 공기가 탁해진다","mis":"K6-2-u3-X01"},{"t":"창문을 연 날 수업 시간에 덜 졸렸다","mis":"K6-2-u3-X01"},{"t":"교실에 공기 측정기를 더 사자","mis":"K6-2-u3-X01"}],"explanation":["윤채가 하자고 한 일이 주장이에요.","「탁해지기 때문」은 이유예요.","덜 졸렸다는 것은 근거로 든 경험이에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#2','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C2',1,'mc','auto','비판적으로 본다는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"비판적으로 본다는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"옳고 그른지를 제대로 따져 보는 것","correct":true},{"t":"무조건 믿지 않는 것","mis":"K6-2-u3-X02"},{"t":"말한 사람을 깎아내리는 것","mis":"K6-2-u3-X02"},{"t":"어디든 잘못이 있다고 미리 정해 두는 것","mis":"K6-2-u3-X02"}],"explanation":["비판은 의심과 달라요.","까닭을 들어 따져요.","맞는 것은 맞다고도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#3','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C3',1,'mc','auto','주장하는 말은 한 번 듣고 지나가요. 그래서 어떻게 들어야 할까요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말은 한 번 듣고 지나가요. 그래서 어떻게 들어야 할까요?","options":[{"t":"이유나 근거를 놓치지 않도록 메모하며 듣는다","correct":true},{"t":"한 번 들었으니 느낌만 기억한다","mis":"K6-2-u3-X04"},{"t":"말하는 사람의 목소리만 기억한다","mis":"K6-2-u3-X04"},{"t":"끝까지 듣지 않고 결론을 정한다","mis":"K6-2-u3-X04"}],"explanation":["글은 다시 읽지만 말은 되감을 수 없어요.","이유와 근거를 적으며 들어요.","그래야 평가할 거리가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#4','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C4',1,'mc','auto','주장이 가치 있고 중요한지 판단하는 물음은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"mc","stem":"주장이 가치 있고 중요한지 판단하는 물음은 어느 것인가요?","options":[{"t":"문제를 해결하거나 생활하는 데 도움이 되는가?","correct":true},{"t":"말이 멋있는가?","mis":"K6-2-u3-X05"},{"t":"주장이 긴가?","mis":"K6-2-u3-X05"},{"t":"말한 사람이 유명한가?","mis":"K6-2-u3-X03"}],"explanation":["주장은 도움이 되는지 보아요.","실천 가능한지도 보아요.","멋·길이·유명함은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#5','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C6',1,'match','auto','근거 자료의 이름과 그 자료가 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"match","stem":"근거 자료의 이름과 그 자료가 하는 일을 알맞게 이으세요.","pairs":[{"l":"그래프","r":"늘고 주는 흐름을 한눈에 보여 준다"},{"l":"면담 자료","r":"그 일을 겪은 사람의 말을 그대로 옮긴다"},{"l":"표","r":"여러 값을 나란히 놓아 견주게 해 준다"}],"mis":"K6-2-u3-X10","explanation":["그래프는 흐름이에요.","면담 자료는 사람의 말이에요.","표는 나란히 견주게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#6','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',1,'mc','auto','주장하는 말을 평가하는 일은 어떤 일인가요?',ARRAY['K6-2-u3-X11','K6-2-u3-X03']::text[],false,'{"seq":6,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"주장하는 말을 평가하는 일은 어떤 일인가요?","options":[{"t":"더 나아지게 하는 일","correct":true},{"t":"이긴 쪽을 고르는 일","mis":"K6-2-u3-X11"},{"t":"흠을 찾아내는 일","mis":"K6-2-u3-X11"},{"t":"말한 사람을 칭찬만 하는 일","mis":"K6-2-u3-X03"}],"explanation":["평가는 겨루기가 아니에요.","살릴 것과 고칠 것을 함께 찾아요.","그래서 더 나아지게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#7','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C9',1,'mc','auto','영상 「걸을 땐, 고개를 들어요」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X17']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"영상 「걸을 땐, 고개를 들어요」의 주장은 무엇인가요?","options":[{"t":"걸을 때는 화면을 보지 말고 고개를 들자","correct":true},{"t":"횡단보도를 더 넓히자","mis":"K6-2-u3-X15"},{"t":"자전거를 타지 말자","mis":"K6-2-u3-X15"},{"t":"북소리를 크게 듣자","mis":"K6-2-u3-X17"}],"explanation":["제목과 마지막 자막이 같은 말을 해요.","장면들은 걸으며 화면을 볼 때의 문제를 보여 줘요.","셋을 합치면 이 주장이 돼요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#8','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C11',1,'mc','auto','카드 뉴스에서 이유와 근거가 대개 놓이는 자리는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C11","difficulty":1,"kind":"mc","stem":"카드 뉴스에서 이유와 근거가 대개 놓이는 자리는 어느 것인가요?","options":[{"t":"가운데 장에 한 장에 한 쌍씩","correct":true},{"t":"첫 장의 제목 자리","mis":"K6-2-u3-X01"},{"t":"마지막 장의 그림 안","mis":"K6-2-u3-X01"},{"t":"카드 뉴스에는 근거가 없다","mis":"K6-2-u3-X03"}],"explanation":["첫 장에는 제목과 주장이 들어가요.","가운데 장에 이유와 근거가 한 쌍씩 놓여요.","마지막 장은 대개 실천을 권해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#9','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',2,'mc','auto','윤채의 첫째 이유를 뒷받침하는 근거는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"윤채의 첫째 이유를 뒷받침하는 근거는 어느 것인가요?","options":[{"t":"우리 반 공기 측정기로 잰 수치가 창문을 연 뒤 내려간 것","correct":true},{"t":"창문을 열면 기분이 상쾌해진다는 것","mis":"K6-2-u3-X01"},{"t":"창문을 연 날 덜 졸렸다는 것","mis":"K6-2-u3-X08"},{"t":"창가에 앉은 사람부터 열자는 것","mis":"K6-2-u3-X01"}],"explanation":["첫째 이유는 「공기가 탁해진다」예요.","그것을 보여 주는 것은 측정기로 잰 수치예요.","상쾌함은 둘째 이유예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#10','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C8',2,'mc','auto','윤채의 근거 가운데 객관적인 것은 어느 것인가요?',ARRAY['K6-2-u3-X08']::text[],false,'{"seq":10,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"윤채의 근거 가운데 객관적인 것은 어느 것인가요?","options":[{"t":"공기 측정기로 잰 수치","correct":true},{"t":"창문을 연 날 덜 졸렸다는 경험","mis":"K6-2-u3-X08"},{"t":"창문을 열면 상쾌하다는 느낌","mis":"K6-2-u3-X08"},{"t":"창가 자리가 좋다는 생각","mis":"K6-2-u3-X08"}],"explanation":["측정기로 잰 수치는 누가 보아도 같아요.","덜 졸렸다는 것은 윤채 한 사람의 경험이에요.","느낌과 생각은 주관적이에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#11','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C6',2,'mc','auto','근거가 사실인지 확인하는 방법을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X09','K6-2-u3-X03']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"mc","stem":"근거가 사실인지 확인하는 방법을 바르게 모은 것은 어느 것인가요?","options":[{"t":"책이나 기사 찾아보기 · 그 일을 맡은 기관의 누리집 확인하기 · 아는 어른께 여쭙기","correct":true},{"t":"검색해서 맨 위에 나온 것 믿기","mis":"K6-2-u3-X09"},{"t":"말한 사람에게 맞는지만 묻기","mis":"K6-2-u3-X09"},{"t":"친구들이 다 믿으면 사실로 보기","mis":"K6-2-u3-X03"}],"explanation":["확인하는 방법은 여러 가지예요.","찾은 기사도 출처를 한 번 더 살펴요.","많이 믿는다고 사실이 되지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#12','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C9',2,'match','auto','「걸을 땐, 고개를 들어요」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"match","stem":"「걸을 땐, 고개를 들어요」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.","pairs":[{"l":"제목","r":"걸을 땐, 고개를 들어요"},{"l":"제시한 자료","r":"학교 앞에서 조사한 화면"},{"l":"강조하는 표현","r":"되풀이되는 빨간 자막 「멈춰!」"}],"mis":"K6-2-u3-X15","explanation":["제목은 영상의 이름이에요.","조사 화면은 자료예요.","되풀이 자막은 강조예요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#13','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C5',2,'mc','auto','「가까운 층은 계단으로」의 이유 가운데 타당하지 않은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X02']::text[],false,'{"seq":13,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「가까운 층은 계단으로」의 이유 가운데 타당하지 않은 것은 어느 것인가요?","options":[{"t":"계단으로 다니는 사람이 더 멋있어 보이기 때문이다","correct":true},{"t":"꼭 필요한 사람이 오래 기다리게 되기 때문이다","mis":"K6-2-u3-X07"},{"t":"몸을 움직일 좋은 기회이기 때문이다","mis":"K6-2-u3-X07"},{"t":"세 이유 모두 타당하지 않다","mis":"K6-2-u3-X02"}],"explanation":["주장과 관련 있는지, 많은 사람이 받아들일 만한지 보아요.","멋있어 보이는 것은 사람마다 달라요.","이유 ①과 ②는 받아들일 만해요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#14','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C12',2,'mc','auto','「놀이터 쓰레기를 줄이자. 놀이터 쓰레기가 해마다 늘고 있기 때문이다.」의 이유가 약한 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X09','K6-2-u3-X12','K6-2-u3-X06']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"「놀이터 쓰레기를 줄이자. 놀이터 쓰레기가 해마다 늘고 있기 때문이다.」의 이유가 약한 까닭은 어느 것인가요?","options":[{"t":"늘고 있다는 것은 문제의 규모일 뿐 왜 줄여야 하는지는 말하지 않아서","correct":true},{"t":"늘고 있다는 것은 사실이 아니어서","mis":"K6-2-u3-X09"},{"t":"이유가 너무 짧아서","mis":"K6-2-u3-X12"},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"}],"explanation":["「그래서 왜 줄여야 하는데?」를 물어요.","늘고 있다는 것은 크기예요.","무엇이 나빠지는지 말해야 이유가 서요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#15','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C13',2,'mc','auto','영상을 찾을 주제를 고를 때 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X22']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"영상을 찾을 주제를 고를 때 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람이 함께 생각해 볼 만한 것으로 고른다","correct":true},{"t":"나만 좋아하는 것으로만 고른다","mis":"K6-2-u3-X07"},{"t":"자극적일수록 좋은 주제다","mis":"K6-2-u3-X22"},{"t":"처음 뜬 영상의 주제를 그대로 쓴다","mis":"K6-2-u3-X22"}],"explanation":["환경·건강·안전·우리 동네처럼 함께 생각할 주제가 좋아요.","좋아하는 것만으로 고르지 않아요.","자극적인 것은 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#16','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C14',2,'mc','auto','「좋다」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"mc","stem":"「좋다」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[조타]","correct":true},{"t":"[졷다]","mis":"K6-2-u3-X23"},{"t":"[조다]","mis":"K6-2-u3-X23"},{"t":"[존다]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐 ㅌ이 돼요.","그래서 [조타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#17','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C8',3,'mc','auto','윤채의 둘째 근거 「창문을 연 날 덜 졸렸다」를 객관적인 근거로 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X08']::text[],false,'{"seq":17,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"윤채의 둘째 근거 「창문을 연 날 덜 졸렸다」를 객관적인 근거로 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 연 날과 닫은 날, 수업 중에 졸렸다고 답한 사람 수를 우리 반에서 조사해 견준 표","correct":true},{"t":"나는 창문을 연 날 정말 정말 덜 졸렸다는 말","mis":"K6-2-u3-X14"},{"t":"상쾌한 바람 소리를 들려주는 것","mis":"K6-2-u3-X14"},{"t":"창문을 활짝 연 교실 사진","mis":"K6-2-u3-X08"}],"explanation":["한 사람의 경험은 주관적이에요.","반 전체에게 물어 견주면 확인할 수 있어요.","더 힘주어 말하는 것은 고치는 것이 아니에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#18','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C10',3,'mc','auto','「걸을 땐, 고개를 들어요」의 타당성을 따지려면 무엇을 살펴야 하나요?',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":18,"concept":"K6-2-u3-C10","difficulty":3,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」의 타당성을 따지려면 무엇을 살펴야 하나요?","options":[{"t":"장면 1 · 3과 조사 화면이 걸으며 화면을 보면 위험하다는 것을 정말 보여 주는지","correct":true},{"t":"북소리가 얼마나 큰지","mis":"K6-2-u3-X17"},{"t":"자막 색이 얼마나 빨간지","mis":"K6-2-u3-X17"},{"t":"자막이 몇 번 되풀이되는지","mis":"K6-2-u3-X17"}],"explanation":["강조는 주장을 찾는 데 썼어요.","타당성은 자료가 이유를 보여 주는지로 따져요.","소리·색·되풀이는 기준이 아니에요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#19','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C11',3,'mc','auto','「밤이 너무 밝습니다」의 근거 ①이 이유 ①을 잘 받쳐 주는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":19,"concept":"K6-2-u3-C11","difficulty":3,"kind":"mc","stem":"「밤이 너무 밝습니다」의 근거 ①이 이유 ①을 잘 받쳐 주는 까닭은 어느 것인가요?","options":[{"t":"잠드는 데 걸리는 시간이 길어진다는, 확인할 수 있는 연구 결과여서","correct":true},{"t":"연구라는 말이 어려워 보여서","mis":"K6-2-u3-X08"},{"t":"셋째 장에 놓여 있어서","mis":"K6-2-u3-X01"},{"t":"근거가 길어서","mis":"K6-2-u3-X08"}],"explanation":["이유 ①은 잠을 방해한다는 것이에요.","근거 ①은 잠드는 시간이 길어진다는 것을 보여 줘요.","확인할 수 있는 자료예요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#20','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C5',3,'mc','auto','「가까운 층은 계단으로」에서 이유 ③ 자리에 놓을 더 나은 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X06']::text[],false,'{"seq":20,"concept":"K6-2-u3-C5","difficulty":3,"kind":"mc","stem":"「가까운 층은 계단으로」에서 이유 ③ 자리에 놓을 더 나은 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"승강기를 덜 쓰면 전기를 아낄 수 있기 때문이다","correct":true},{"t":"계단에서 찍은 사진이 잘 나오기 때문이다","mis":"K6-2-u3-X07"},{"t":"승강기를 타면 지루하기 때문이다","mis":"K6-2-u3-X07"},{"t":"건물에 계단이 있기 때문이다","mis":"K6-2-u3-X06"}],"explanation":["주장과 관련 있어야 해요.","많은 사람이 받아들일 만해야 해요.","전기를 아끼는 일은 누구에게나 해당해요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#21','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',3,'mc','auto','친구와 판단이 갈렸을 때 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":21,"concept":"K6-2-u3-C7","difficulty":3,"kind":"mc","stem":"친구와 판단이 갈렸을 때 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 이유가 많은 사람에게 받아들여질 만한지를 가장 무겁게 보아 △로 했어.」","correct":true},{"t":"「그냥 그렇게 느꼈어.」","mis":"K6-2-u3-X12"},{"t":"「내 생각에는 그게 맞아.」","mis":"K6-2-u3-X12"},{"t":"「네가 ◎를 했으니 나는 △를 할래.」","mis":"K6-2-u3-X12"}],"explanation":["판단은 갈릴 수 있어요.","어떤 기준을 무겁게 보았는지 말해요.","느낌만으로는 까닭이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#22','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C2',3,'mc','auto','이 단원에서 배운 「비판적으로 보기」를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X17','K6-2-u3-X03']::text[],false,'{"seq":22,"concept":"K6-2-u3-C2","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 「비판적으로 보기」를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"타당한 점을 먼저 세고, 보완할 점을 까닭과 함께 말하는 것","correct":true},{"t":"약한 데를 빠짐없이 찾아내 그 자료를 버리는 것","mis":"K6-2-u3-X02"},{"t":"강조가 센 쪽을 믿는 것","mis":"K6-2-u3-X17"},{"t":"말 잘하는 사람을 따르는 것","mis":"K6-2-u3-X03"}],"explanation":["비판은 의심이 아니에요.","살릴 것을 먼저 세어요.","고칠 것은 까닭과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#23','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',4,'mc','auto','윤채의 발표를 더 낫게 고치는 조언으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X20','K6-2-u3-X08']::text[],false,'{"seq":23,"concept":"K6-2-u3-C7","difficulty":4,"kind":"mc","stem":"윤채의 발표를 더 낫게 고치는 조언으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 첫째 이유 · 측정 수치는 살리고, 둘째 이유와 졸린 경험은 우리 반 조사처럼 확인할 수 있는 자료로 바꾸자","correct":true},{"t":"둘째 이유를 더 힘주어 여러 번 말하자","mis":"K6-2-u3-X14"},{"t":"약한 데가 있으니 발표를 모두 새로 쓰자","mis":"K6-2-u3-X20"},{"t":"측정 수치는 빼고 느낌을 더 넣자","mis":"K6-2-u3-X08"}],"explanation":["살릴 것을 먼저 정해요.","약한 자리는 확인할 수 있는 자료로 바꾸어요.","전체를 버리거나 느낌을 키우지 않아요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#24','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',4,'essay','teacher','윤채의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 보완할 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"윤채의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 보완할 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 타당한 점 — 쉬는 시간 십 분에 창가에 앉은 사람부터 창문을 열자는 주장은 오늘 바로 할 수 있고, 공기가 탁해진다는 첫째 이유는 우리 반 공기 측정기로 잰 수치라는 확인할 수 있는 근거로 받쳐져 있다. 보완할 점 — 기분이 상쾌해진다는 둘째 이유와 덜 졸렸다는 근거는 윤채 한 사람의 느낌과 경험이라 많은 사람이 받아들이기 어렵다. 고칠 방법 — 창문을 연 날과 닫은 날 졸렸다고 답한 사람 수를 우리 반에서 조사해 견준 표로 바꾼다.","scoring_points":["타당한 점을 먼저 썼는가","보완할 점을 기준(받아들일 만함·객관성)에 대어 썼는가","확인할 수 있는 자료로 고치는 방법을 썼는가"]},"explanation":["살릴 것부터 써요.","고칠 것은 기준과 함께 써요.","느낌은 조사 자료로 바꾸어요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#25','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',4,'essay','teacher','우리 학교나 동네를 더 낫게 만들 주장을 하나 정해 주장 · 이유 · 근거로 쓰세요. 근거는 확인할 수 있는 자료로 쓰고 출처를 밝히되, 숫자를 지어내지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"우리 학교나 동네를 더 낫게 만들 주장을 하나 정해 주장 · 이유 · 근거로 쓰세요. 근거는 확인할 수 있는 자료로 쓰고 출처를 밝히되, 숫자를 지어내지 마세요.","answer_guide":{"answer":"예: 주장 — 학교 앞 횡단보도에서는 신호가 바뀌어도 좌우를 한 번 더 살피고 건너자. 이유 — 신호가 바뀐 뒤에도 미처 멈추지 못한 차나 자전거가 지나갈 수 있기 때문이다. 근거 — 우리 반이 지난주 아침에 학교 앞 횡단보도를 지켜보며 신호가 바뀐 뒤 지나간 자전거를 적은 기록이 있다.","scoring_points":["실천 가능한 주장을 썼는가","주장과 관련 있고 많은 사람이 받아들일 만한 이유를 썼는가","출처가 밝혀진 확인할 수 있는 근거를 썼는가"]},"explanation":["주장은 언제 무엇을 할지 분명하게.","이유는 누구에게나 해당하게.","근거는 확인할 수 있게, 출처와 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#1','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',1,'sa','auto','어떤 주제에 대한 자신의 의견을 드러내는 말을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"어떤 주제에 대한 자신의 의견을 드러내는 말을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["주장"],"explanation":["이유는 까닭을 설명해요.","근거는 이유를 뒷받침해요.","의견을 드러내는 말은 주장이에요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#2','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C2',1,'ox','auto','비판적으로 보면 다른 사람의 의견과 내 의견을 견주어 볼 수 있어요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"비판적으로 보면 다른 사람의 의견과 내 의견을 견주어 볼 수 있어요.","answer":"O","reason_options":[{"t":"주장 · 이유 · 근거를 따져 보면 내 생각과 어디가 같고 다른지 보이기 때문에","correct":true},{"t":"비판적으로 보면 내 의견만 옳다는 것을 알게 되기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["따져 보면 내용을 제대로 이해해요.","내 생각과 견주어 볼 수 있어요.","내 의견만 옳다는 뜻은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#3','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C3',1,'ox','auto','주장하는 말을 들을 때 지나치게 감정에 호소하지는 않는지도 살펴요.',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"ox","stem":"주장하는 말을 들을 때 지나치게 감정에 호소하지는 않는지도 살펴요.","answer":"O","reason_options":[{"t":"말하는 사람의 표현이나 태도도 살펴 들어야 하기 때문에","correct":true},{"t":"감정에 호소하는 말일수록 타당하기 때문에","mis":"K6-2-u3-X04"}],"mis":"K6-2-u3-X04","explanation":["내용뿐 아니라 태도도 살펴요.","감정에 호소하면 마음이 먼저 움직여요.","그럴수록 이유와 근거를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#4','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',1,'mc','auto','이유의 타당성을 판단하는 물음은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X10','K6-2-u3-X06']::text[],false,'{"seq":4,"concept":"K6-2-u3-C5","difficulty":1,"kind":"mc","stem":"이유의 타당성을 판단하는 물음은 어느 것인가요?","options":[{"t":"이유가 주장과 관련 있는가?","correct":true},{"t":"이유가 말한 사람의 마음에 드는가?","mis":"K6-2-u3-X07"},{"t":"이유가 조사한 표로 되어 있는가?","mis":"K6-2-u3-X10"},{"t":"이유가 짧은가?","mis":"K6-2-u3-X06"}],"explanation":["이유는 주장과 관련 있어야 해요.","많은 사람이 받아들일 만해야 해요.","표는 근거의 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#5','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C6',1,'sa','auto','늘고 주는 흐름을 한눈에 보여 주는 근거 자료를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"sa","stem":"늘고 주는 흐름을 한눈에 보여 주는 근거 자료를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["그래프"],"explanation":["표는 값을 나란히 놓아요.","흐름을 보여 주는 것은 그래프예요.","「밤 밝기를 해마다 조사한」 자료가 그래프였어요."],"mis":"K6-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#6','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C8',1,'sa','auto','자기 혼자만의 생각이나 느낌에 치우친 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":1,"kind":"sa","stem":"자기 혼자만의 생각이나 느낌에 치우친 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["주관적"],"explanation":["누가 보아도 그러한 것은 객관적이에요.","혼자만의 느낌에 치우친 것은 주관적이에요.","근거는 객관적이어야 해요."],"mis":"K6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#7','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',1,'sa','auto','영상의 주장을 파악할 때 살피는 세 가지는 제목 · 제시한 ○○ · 강조하는 장면이나 표현이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":1,"kind":"sa","stem":"영상의 주장을 파악할 때 살피는 세 가지는 제목 · 제시한 ○○ · 강조하는 장면이나 표현이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["자료"],"explanation":["제목을 정한 까닭을 생각해요.","제시한 자료의 내용을 파악해요.","강조된 장면과 표현을 찾아요."],"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#8','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C14',1,'mc','auto','「쌓고」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"mc","stem":"「쌓고」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[싸코]","correct":true},{"t":"[싸고]","mis":"K6-2-u3-X23"},{"t":"[싿고]","mis":"K6-2-u3-X23"},{"t":"[쌋꼬]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄱ이 왔어요.","ㅎ과 ㄱ이 합쳐 ㅋ이 돼요.","그래서 [싸코]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#9','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',2,'match','auto','윤채가 한 말의 자리와 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"match","stem":"윤채가 한 말의 자리와 그 내용을 알맞게 이으세요.","pairs":[{"l":"주장","r":"쉬는 시간마다 교실 창문을 열자"},{"l":"첫째 이유","r":"닫아 두면 공기가 탁해져 머리가 무거워진다"},{"l":"첫째 근거","r":"공기 측정기로 잰 수치가 내려갔다"}],"mis":"K6-2-u3-X01","explanation":["하자는 말이 주장이에요.","「~ 때문입니다」가 이유예요.","측정한 수치가 근거예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#10','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',2,'mc','auto','윤채의 둘째 이유 「창문을 열면 기분이 상쾌해지기 때문입니다」를 평가한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X08','K6-2-u3-X20']::text[],false,'{"seq":10,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"윤채의 둘째 이유 「창문을 열면 기분이 상쾌해지기 때문입니다」를 평가한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 관련은 있지만 느낌이라 사람마다 달라 많은 사람이 받아들이기에 약하다","correct":true},{"t":"주장과 아무 관련이 없다","mis":"K6-2-u3-X06"},{"t":"누가 보아도 그러한 사실이라 아주 튼튼하다","mis":"K6-2-u3-X08"},{"t":"이유가 약하니 주장 전체가 틀렸다","mis":"K6-2-u3-X20"}],"explanation":["창문을 여는 일과 이어지니 관련은 있어요.","그러나 상쾌함은 사람마다 달라요.","하나만 통과한 이유예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#11','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C8',2,'ox','auto','남이 만든 자료를 출처 없이 쓰면 그 자료를 내 것처럼 쓰게 돼요.',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":11,"concept":"K6-2-u3-C8","difficulty":2,"kind":"ox","stem":"남이 만든 자료를 출처 없이 쓰면 그 자료를 내 것처럼 쓰게 돼요.","answer":"O","reason_options":[{"t":"누가 만든 자료인지 밝히지 않으면 듣는 사람은 내가 만든 것으로 알기 때문에","correct":true},{"t":"자료는 쓰는 사람의 것이 되기 때문에","mis":"K6-2-u3-X13"}],"mis":"K6-2-u3-X13","explanation":["가져다 쓴 자료는 어디에서 왔는지 밝혀요.","그래야 남의 것을 내 것처럼 쓰지 않아요.","듣는 사람도 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#12','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',2,'mc','auto','「걸을 땐, 고개를 들어요」에 장면 2의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」에 장면 2의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸으며 화면을 보는 문제가 우리 가까이에 실제로 있다는 것을 보여 주려고","correct":true},{"t":"학교가 얼마나 큰지 알려 주려고","mis":"K6-2-u3-X15"},{"t":"화면을 보는 것이 재미있다는 것을 알리려고","mis":"K6-2-u3-X15"},{"t":"영상을 길게 만들려고","mis":"K6-2-u3-X15"}],"explanation":["자료를 넣은 자리에는 까닭이 있어요.","조사 화면은 문제가 있다는 것을 보여 줘요.","우리 학교 앞이라 더 가깝게 느껴져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#13','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C11',2,'mc','auto','「가까운 층은 계단으로」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":13,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"「가까운 층은 계단으로」의 주장은 무엇인가요?","options":[{"t":"삼 층까지는 계단으로 다니자","correct":true},{"t":"승강기를 없애자","mis":"K6-2-u3-X01"},{"t":"계단을 새로 칠하자","mis":"K6-2-u3-X01"},{"t":"승강기를 기다린 시간을 재자","mis":"K6-2-u3-X01"}],"explanation":["첫머리의 「다닙시다」가 주장이에요.","승강기를 없애자는 말은 없어요.","시간을 잰 것은 근거예요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#14','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',2,'ox','auto','제도가 마련되어 있다는 것은 문제가 왜 생기는지를 보여 주는 근거예요.',ARRAY['K6-2-u3-X19']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"제도가 마련되어 있다는 것은 문제가 왜 생기는지를 보여 주는 근거예요.","answer":"X","reason_options":[{"t":"제도는 문제에 대한 해결 방안이라 문제가 왜 생기는지는 보여 주지 못하기 때문에","correct":true},{"t":"제도가 있다는 것은 문제가 생기는 까닭을 말해 주기 때문에","mis":"K6-2-u3-X19"}],"mis":"K6-2-u3-X19","explanation":["제도는 이미 나선 답이에요.","근거는 이유를 보여 주어야 해요.","해결 방안은 그 뒤의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#15','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',2,'ox','auto','가장 타당한 영상을 고르면 그 활동은 끝나요.',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"ox","stem":"가장 타당한 영상을 고르면 그 활동은 끝나요.","answer":"X","reason_options":[{"t":"왜 그것을 골랐는지 말로 세울 수 있을 때 끝나기 때문에","correct":true},{"t":"고르는 것이 평가의 끝이기 때문에","mis":"K6-2-u3-X12"}],"mis":"K6-2-u3-X12","explanation":["고르는 것이 끝이 아니에요.","판단한 까닭을 말로 세워야 해요.","그래야 친구가 따라올 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#16','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C14',2,'match','auto','낱말과 그 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"match","stem":"낱말과 그 발음을 알맞게 이으세요.","pairs":[{"l":"넣고","r":"[너코]"},{"l":"넣는","r":"[넌는]"},{"l":"넣어","r":"[너어]"}],"mis":"K6-2-u3-X23","explanation":["ㄱ 앞에서는 합쳐 ㅋ이 돼요.","ㄴ 앞에서는 ㄴ이 돼요.","모음 앞에서는 ㅎ 소리가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#17','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C7',3,'error','auto','윤채의 발표를 평가한 말이에요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X11','K6-2-u3-X14']::text[],false,'{"seq":17,"concept":"K6-2-u3-C7","difficulty":3,"kind":"error","stem":"윤채의 발표를 평가한 말이에요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"시온 — 「둘째 이유가 약하니 윤채의 주장은 틀렸어.」","correct":true,"mis_target":"K6-2-u3-X20"},{"t":"마루 — 「주장은 오늘 바로 해 볼 수 있고, 측정한 수치는 확인할 수 있는 근거야.」","mis":"K6-2-u3-X11"},{"t":"이든 — 「둘째 이유와 근거는 느낌이라 조사 자료로 바꾸면 좋겠어.」","mis":"K6-2-u3-X14"}],"explanation":["마루는 타당한 점을 먼저 짚었어요.","이든은 고칠 방법을 말했어요.","시온은 하나가 약하다고 전체를 버렸어요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#18','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',3,'mc','auto','장면 2 「걸으며 화면을 보는 학생이 생각보다 많다」는 무엇을 보여 주는 자료인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X19','K6-2-u3-X08']::text[],false,'{"seq":18,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"장면 2 「걸으며 화면을 보는 학생이 생각보다 많다」는 무엇을 보여 주는 자료인가요?","options":[{"t":"문제의 규모 — 그것만으로는 왜 위험한지를 보여 주지 못한다","correct":true},{"t":"위험한 까닭","mis":"K6-2-u3-X18"},{"t":"문제의 해결 방안","mis":"K6-2-u3-X19"},{"t":"만든 사람의 느낌","mis":"K6-2-u3-X08"}],"explanation":["많다는 것은 크기예요.","왜 위험한지는 장면 1·3이 보여 줘요.","규모만으로는 까닭이 되지 않아요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#19','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',3,'ox','auto','「밤이 너무 밝습니다」의 근거 ② 그래프는 이유 ②와 관련이 있어요.',ARRAY['K6-2-u3-X10']::text[],false,'{"seq":19,"concept":"K6-2-u3-C12","difficulty":3,"kind":"ox","stem":"「밤이 너무 밝습니다」의 근거 ② 그래프는 이유 ②와 관련이 있어요.","answer":"O","reason_options":[{"t":"밤 불빛이 해마다 늘고 있다는 이유 ②를 그래프가 그대로 보여 주기 때문에","correct":true},{"t":"그래프는 어떤 이유와도 관련이 없기 때문에","mis":"K6-2-u3-X10"}],"mis":"K6-2-u3-X10","explanation":["근거 ②는 이유 ②를 잘 보여 줘요.","약한 것은 이유 ② 자체예요.","근거와 이유를 따로 따져요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#20','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C6',3,'mc','auto','「층마다 승강기를 기다린 시간을 잰 표」가 뒷받침하는 이유는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X06']::text[],false,'{"seq":20,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"「층마다 승강기를 기다린 시간을 잰 표」가 뒷받침하는 이유는 어느 것인가요?","options":[{"t":"이유 ① — 꼭 필요한 사람이 오래 기다리게 된다","correct":true},{"t":"이유 ② — 몸을 움직일 좋은 기회이다","mis":"K6-2-u3-X01"},{"t":"이유 ③ — 더 멋있어 보인다","mis":"K6-2-u3-X01"},{"t":"어느 이유와도 관련이 없다","mis":"K6-2-u3-X06"}],"explanation":["기다린 시간은 오래 기다린다는 것을 보여 줘요.","그래서 이유 ①의 근거예요.","이유 ②는 안내 자료가 받쳐 줘요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#21','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',3,'mc','auto','「물이 오는 길」을 다루는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":21,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"「물이 오는 길」을 다루는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"주장이 없는 정보 영상이라 평가표에서 빼고, 물에 대해 알아보는 자료로 쓸 수 있다","correct":true},{"t":"근거가 약하니 △로 표시한다","mis":"K6-2-u3-X21"},{"t":"주장이 없으니 가장 타당한 영상이다","mis":"K6-2-u3-X21"},{"t":"재미있으니 ◎로 표시한다","mis":"K6-2-u3-X21"}],"explanation":["알려 주는 영상은 주장이 없어요.","평가표로 잴 수 없어요.","그래도 정보를 얻는 데는 쓸 수 있어요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#22','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C2',3,'ox','auto','「어떤 영상이든 잘못이 있게 마련이야.」라고 미리 정하고 보는 것이 비판적으로 보는 거예요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":22,"concept":"K6-2-u3-C2","difficulty":3,"kind":"ox","stem":"「어떤 영상이든 잘못이 있게 마련이야.」라고 미리 정하고 보는 것이 비판적으로 보는 거예요.","answer":"X","reason_options":[{"t":"잘못이 있다고 미리 정하는 것은 따져 보기 전에 판단한 것이기 때문에","correct":true},{"t":"어디든 잘못을 찾아야 비판한 것이기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["비판은 따져 본 뒤에 판단해요.","미리 정하면 의심이에요.","맞는 것은 맞다고 말할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#23','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',4,'mc','auto','「걸을 땐, 고개를 들어요」를 평가한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X18','K6-2-u3-X16']::text[],false,'{"seq":23,"concept":"K6-2-u3-C12","difficulty":4,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」를 평가한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장은 실천 가능하고 장면 1 · 3이 위험한 순간을 보여 주지만, 장면 2 조사는 규모만 보여 주며 북소리와 되풀이 자막은 타당성과 관계없다","correct":true},{"t":"북소리와 자막이 세서 가장 타당한 영상이다","mis":"K6-2-u3-X17"},{"t":"조사 화면이 있으니 모든 자리가 튼튼하다","mis":"K6-2-u3-X18"},{"t":"주장을 말로 하지 않으니 평가할 수 없다","mis":"K6-2-u3-X16"}],"explanation":["타당한 점을 먼저 세어요.","규모만 보여 주는 자료는 약한 자리예요.","강조의 세기는 타당성과 따로예요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#24','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',4,'essay','teacher','「걸을 땐, 고개를 들어요」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고 주장을 한 문장으로 쓰세요. 그리고 장면 4의 강조가 이 주장의 타당성을 알려 주지 못하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C9","difficulty":4,"kind":"essay","stem":"「걸을 땐, 고개를 들어요」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고 주장을 한 문장으로 쓰세요. 그리고 장면 4의 강조가 이 주장의 타당성을 알려 주지 못하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「걸을 땐, 고개를 들어요」. 자료 — 학교 앞에서 걸으며 화면을 보는 학생이 많다는 조사 화면. 강조 — 세 번 되풀이되는 빨간 자막 「멈춰!」와 점점 커지는 북소리. 주장 — 걸을 때는 화면을 보지 말고 고개를 들자. 장면 4의 강조는 만든 사람이 「멈춰」를 가장 하고 싶은 말로 여긴다는 것만 알려 줄 뿐이다. 주장이 타당한지는 장면 1·3과 조사 화면이 걸으며 화면을 보면 위험하다는 이유를 정말 보여 주는지로 따로 따져야 한다.","scoring_points":["제목·자료·강조를 하나씩 바르게 찾았는가","주장을 한 문장으로 썼는가","강조와 타당성이 다른 까닭과 따지는 방법을 썼는가"]},"explanation":["셋을 합쳐 주장을 세워요.","강조는 실마리예요.","타당성은 자료로 따져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#25','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',4,'essay','teacher','「밤이 너무 밝습니다」를 예로 들어, 이유나 근거 하나가 약하다고 주장 전체를 틀렸다고 하면 안 되는 까닭을 쓰고, 그 카드 뉴스를 평가하는 말을 「주장은 … 다만 …」의 꼴로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C12","difficulty":4,"kind":"essay","stem":"「밤이 너무 밝습니다」를 예로 들어, 이유나 근거 하나가 약하다고 주장 전체를 틀렸다고 하면 안 되는 까닭을 쓰고, 그 카드 뉴스를 평가하는 말을 「주장은 … 다만 …」의 꼴로 쓰세요.","answer_guide":{"answer":"예: 이유 ②와 근거 ③이 약해도 주장은 가치 있고 실천 가능하며, 이유 ①·③과 근거 ①·②는 튼튼하다. 약한 자리는 고칠 자리이지 주장 전체를 무너뜨리는 것이 아니다. 평가하는 말 — 「주장은 가치 있고 근거 두 개는 튼튼해. 다만 이유 ②는 늘어서 무엇이 나빠지는지 말하도록, 근거 ③은 생물이 어지럽혀지는 모습을 보여 주는 자료로 바꾸면 좋겠어.」","scoring_points":["튼튼한 자리와 약한 자리를 함께 짚었는가","약한 자리가 주장 전체를 틀리게 하지 않는 까닭을 썼는가","「주장은 … 다만 …」 꼴로 고칠 방법까지 썼는가"]},"explanation":["하나가 약하다고 전체가 틀린 것은 아니에요.","타당한 점을 먼저 말해요.","약한 자리는 고칠 방법과 함께 말해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#1','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C1',1,'ox','auto','근거는 이유를 뒷받침하는 자료나 사실이에요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"ox","stem":"근거는 이유를 뒷받침하는 자료나 사실이에요.","answer":"O","reason_options":[{"t":"근거가 있어야 이유가 사실인지 확인할 수 있기 때문에","correct":true},{"t":"근거는 주장을 다른 말로 한 번 더 말한 것이기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["근거는 이유를 받쳐 줘요.","자료나 사실이어야 해요.","주장을 되풀이한 말은 근거가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#2','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C2',1,'sa','auto','옳고 그른지를 제대로 따져 보며 보는 것을 「○○○으로 본다」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"sa","stem":"옳고 그른지를 제대로 따져 보며 보는 것을 「○○○으로 본다」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["비판적"],"explanation":["무조건 믿지 않는 것이 아니에요.","무조건 의심하는 것도 아니에요.","따져 보며 보는 것이에요."],"mis":"K6-2-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#3','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C3',1,'sa','auto','이유나 근거를 놓치지 않도록 적으며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"sa","stem":"이유나 근거를 놓치지 않도록 적으며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["메모"],"explanation":["적으며 들으면 메모하며 듣기예요.","간추리며 들으면 요약하며 듣기예요.","내 생각과 견주면 견주며 듣기예요."],"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#4','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C4',1,'ox','auto','「우리 모두 훌륭한 사람이 됩시다」는 실천하기 쉬운 주장이에요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"ox","stem":"「우리 모두 훌륭한 사람이 됩시다」는 실천하기 쉬운 주장이에요.","answer":"X","reason_options":[{"t":"말은 크지만 무엇부터 해야 할지 알 수 없기 때문에","correct":true},{"t":"누구나 바라는 일이기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["누구나 바라는 일이어도","언제 무엇을 할지 없으면 실천하기 어려워요.","실천 가능해야 가치 있는 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#5','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C6',1,'mc','auto','근거로 쓰기 어려운 것은 어느 것인가요?',ARRAY['K6-2-u3-X08']::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"mc","stem":"근거로 쓰기 어려운 것은 어느 것인가요?","options":[{"t":"말한 사람의 느낌이나 짐작","correct":true},{"t":"조사한 표","mis":"K6-2-u3-X08"},{"t":"그 일을 겪은 사람의 면담 자료","mis":"K6-2-u3-X08"},{"t":"실제로 있었던 사례","mis":"K6-2-u3-X08"}],"explanation":["표·면담 자료·사례는 근거 자료예요.","느낌이나 짐작은 근거가 되지 못해요.","근거는 객관적이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#6','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C8',1,'ox','auto','「나는 새 책 냄새를 좋아한다」는 객관적인 근거예요.',ARRAY['K6-2-u3-X08']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":1,"kind":"ox","stem":"「나는 새 책 냄새를 좋아한다」는 객관적인 근거예요.","answer":"X","reason_options":[{"t":"말한 사람 혼자만의 느낌이라 누가 보아도 그러한 것이 아니기 때문에","correct":true},{"t":"말한 사람이 직접 겪은 것이라 언제나 객관적이기 때문에","mis":"K6-2-u3-X08"}],"mis":"K6-2-u3-X08","explanation":["좋아하는 것은 사람마다 달라요.","혼자만의 느낌은 주관적이에요.","확인할 수 있는 자료로 바꾸어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#7','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C10',1,'ox','auto','빨간 자막 「멈춰!」가 세 번 되풀이되니 「걸을 땐, 고개를 들어요」의 주장은 틀림없이 타당해요.',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":7,"concept":"K6-2-u3-C10","difficulty":1,"kind":"ox","stem":"빨간 자막 「멈춰!」가 세 번 되풀이되니 「걸을 땐, 고개를 들어요」의 주장은 틀림없이 타당해요.","answer":"X","reason_options":[{"t":"되풀이는 하고 싶은 말을 알려 줄 뿐 타당한지는 자료로 따로 따져야 하기 때문에","correct":true},{"t":"되풀이가 많을수록 주장이 옳기 때문에","mis":"K6-2-u3-X17"}],"mis":"K6-2-u3-X17","explanation":["되풀이 자막은 강조예요.","강조는 주장을 찾는 실마리예요.","타당성은 자료로 따져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#8','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',1,'sa','auto','「좋아」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"sa","stem":"「좋아」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.","answer":["조아","[조아]"],"explanation":["받침 ㅎ 뒤에 모음이 왔어요.","모음 앞에서는 ㅎ 소리를 내지 않아요.","그래서 [조아]예요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#9','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C3',2,'mc','auto','윤채의 말을 요약하며 들은 메모로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":9,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"윤채의 말을 요약하며 들은 메모로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장 — 쉬는 시간마다 창문 열기 / 이유 — 공기가 탁해짐, 기분이 상쾌해짐 / 근거 — 측정 수치, 덜 졸린 경험","correct":true},{"t":"윤채는 목소리가 또렷했다","mis":"K6-2-u3-X04"},{"t":"창문 · 공기 · 졸림","mis":"K6-2-u3-X04"},{"t":"창문을 열자는 말에 나는 반대한다","mis":"K6-2-u3-X04"}],"explanation":["요약하며 듣기는 주장·이유·근거로 간추리는 것이에요.","낱말만 적으면 무엇이 무엇인지 몰라요.","목소리나 내 찬반은 요약이 아니에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#10','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C7',2,'ox','auto','윤채의 발표는 둘째 이유가 약하니 평가할 때 그것부터 짚어야 해요.',ARRAY['K6-2-u3-X11']::text[],false,'{"seq":10,"concept":"K6-2-u3-C7","difficulty":2,"kind":"ox","stem":"윤채의 발표는 둘째 이유가 약하니 평가할 때 그것부터 짚어야 해요.","answer":"X","reason_options":[{"t":"주장이 실천 가능하고 첫째 이유와 근거가 튼튼하다는 타당한 점을 먼저 찾아야 하기 때문에","correct":true},{"t":"평가는 약한 곳을 찾는 일이기 때문에","mis":"K6-2-u3-X11"}],"mis":"K6-2-u3-X11","explanation":["타당한 점을 먼저 찾아요.","그다음 보완할 점을 찾아요.","그래야 무엇을 살릴지 보여요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#11','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C8',2,'mc','auto','근거를 말할 때 「○○ 소식지에 실린 내용입니다.」처럼 덧붙이는 것을 무엇이라고 하나요?',ARRAY['K6-2-u3-X14','K6-2-u3-X01']::text[],false,'{"seq":11,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"근거를 말할 때 「○○ 소식지에 실린 내용입니다.」처럼 덧붙이는 것을 무엇이라고 하나요?","options":[{"t":"출처를 밝히기","correct":true},{"t":"감정에 호소하기","mis":"K6-2-u3-X14"},{"t":"주장을 되풀이하기","mis":"K6-2-u3-X01"},{"t":"이유를 바꾸기","mis":"K6-2-u3-X01"}],"explanation":["어디에서 나온 자료인지 말하는 것이에요.","출처를 밝히면 확인할 수 있어요.","근거를 믿을 수 있게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#12','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C10',2,'mc','auto','장면 4의 북소리와 되풀이 자막이 알려 주는 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X21']::text[],false,'{"seq":12,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"장면 4의 북소리와 되풀이 자막이 알려 주는 것은 어느 것인가요?","options":[{"t":"만든 사람이 「멈춰」를 가장 하고 싶은 말로 여긴다는 것","correct":true},{"t":"주장이 사실이라는 것","mis":"K6-2-u3-X17"},{"t":"주장이 타당하다는 것","mis":"K6-2-u3-X17"},{"t":"영상이 재미있다는 것","mis":"K6-2-u3-X21"}],"explanation":["강조는 하고 싶은 말을 가리켜요.","사실인지·타당한지는 알려 주지 못해요.","재미와 타당성도 달라요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#13','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',2,'ox','auto','「가까운 층은 계단으로」에서 타당하지 않은 이유 ③을 지우면 할 일이 끝나요.',ARRAY['K6-2-u3-X11']::text[],false,'{"seq":13,"concept":"K6-2-u3-C5","difficulty":2,"kind":"ox","stem":"「가까운 층은 계단으로」에서 타당하지 않은 이유 ③을 지우면 할 일이 끝나요.","answer":"X","reason_options":[{"t":"그 자리에 주장을 더 잘 뒷받침하는 이유를 놓아 보아야 하기 때문에","correct":true},{"t":"타당하지 않은 이유는 지우기만 하면 되기 때문에","mis":"K6-2-u3-X11"}],"mis":"K6-2-u3-X11","explanation":["지우는 것으로 끝내지 않아요.","더 나은 이유를 생각해 보아요.","예: 승강기를 덜 쓰면 전기를 아낄 수 있다."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#14','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C12',2,'mc','auto','카드 뉴스에서 약한 자리를 찾았을 때 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X03']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"카드 뉴스에서 약한 자리를 찾았을 때 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「주장은 가치 있어. 다만 이 근거는 이렇게 바꾸면 좋겠어.」","correct":true},{"t":"「약한 데가 있으니 다 믿을 수 없어.」","mis":"K6-2-u3-X20"},{"t":"「처음부터 틀린 카드 뉴스야.」","mis":"K6-2-u3-X20"},{"t":"「약한 데는 그냥 모른 척하자.」","mis":"K6-2-u3-X03"}],"explanation":["평가는 고칠 자리를 짚어 주는 일이에요.","타당한 점은 살려요.","약한 자리는 고칠 방법과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#15','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',2,'mc','auto','손 씻기에 대한 영상을 찾을 때 알맞은 찾는 말은 어느 것인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"손 씻기에 대한 영상을 찾을 때 알맞은 찾는 말은 어느 것인가요?","options":[{"t":"「손 씻기 방법 어린이 교육용」","correct":true},{"t":"「손」","mis":"K6-2-u3-X22"},{"t":"「충격 손 세균 실화」","mis":"K6-2-u3-X22"},{"t":"「아무거나 재밌는 거」","mis":"K6-2-u3-X22"}],"explanation":["구체적인 말로 찾아요.","「어린이·교육용」을 붙이면 볼 만한 영상이 나와요.","자극적인 말은 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#16','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',2,'ox','auto','「놓아」는 [노하]로 발음해요.',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"ox","stem":"「놓아」는 [노하]로 발음해요.","answer":"X","reason_options":[{"t":"받침 ㅎ 뒤에 모음이 오면 ㅎ 소리를 내지 않아 [노아]로 발음하기 때문에","correct":true},{"t":"받침 ㅎ은 언제나 그대로 소리 내기 때문에","mis":"K6-2-u3-X23"}],"mis":"K6-2-u3-X23","explanation":["받침 ㅎ 뒤에 모음이 왔어요.","이때는 ㅎ 소리를 내지 않아요.","그래서 [노아]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#17','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',3,'ox','auto','윤채의 둘째 이유는 주장과 관련이 없어서 약해요.',ARRAY['K6-2-u3-X06']::text[],false,'{"seq":17,"concept":"K6-2-u3-C5","difficulty":3,"kind":"ox","stem":"윤채의 둘째 이유는 주장과 관련이 없어서 약해요.","answer":"X","reason_options":[{"t":"관련은 있지만 느낌이라 많은 사람이 받아들이기 어려워 약하기 때문에","correct":true},{"t":"기분은 창문을 여는 일과 아무 관련이 없기 때문에","mis":"K6-2-u3-X06"}],"mis":"K6-2-u3-X06","explanation":["창문을 열면 상쾌하다는 것은 창문 열기와 이어져요.","그러니 관련은 있어요.","약한 까닭은 받아들일 만하지 않다는 것이에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#18','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C9',3,'ox','auto','「걸을 땐, 고개를 들어요」는 「화면을 보지 맙시다」라고 직접 말하지 않으니 주장이 없는 영상이에요.',ARRAY['K6-2-u3-X16']::text[],false,'{"seq":18,"concept":"K6-2-u3-C9","difficulty":3,"kind":"ox","stem":"「걸을 땐, 고개를 들어요」는 「화면을 보지 맙시다」라고 직접 말하지 않으니 주장이 없는 영상이에요.","answer":"X","reason_options":[{"t":"제목과 자료와 강조된 장면을 합치면 주장이 드러나기 때문에","correct":true},{"t":"주장은 문장으로 말해야만 있는 것이기 때문에","mis":"K6-2-u3-X16"}],"mis":"K6-2-u3-X16","explanation":["영상은 주장을 직접 말하지 않는 경우가 많아요.","보는 사람이 스스로 이어 붙여요.","제목과 마지막 자막이 주장을 가리켜요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#19','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C12',3,'mc','auto','이유 ②는 약한데 근거 ②는 튼튼하다고 볼 수 있는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X03','K6-2-u3-X12']::text[],false,'{"seq":19,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"이유 ②는 약한데 근거 ②는 튼튼하다고 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"근거 ②는 이유 ②를 잘 보여 주지만, 이유 ② 자체가 왜 줄여야 하는지를 말하지 못해서","correct":true},{"t":"둘은 같은 것이라 함께 약하다","mis":"K6-2-u3-X01"},{"t":"근거 ②가 그래프라서 무조건 옳다","mis":"K6-2-u3-X03"},{"t":"이유 ②가 짧아서","mis":"K6-2-u3-X12"}],"explanation":["근거는 이유와의 관계로 재요.","이유는 주장과의 관계로 재요.","재는 자가 달라서 판단도 달라요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#20','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C7',3,'ox','auto','「가까운 층은 계단으로」는 이유 ③이 약하니 평가할 가치가 없어요.',ARRAY['K6-2-u3-X20']::text[],false,'{"seq":20,"concept":"K6-2-u3-C7","difficulty":3,"kind":"ox","stem":"「가까운 층은 계단으로」는 이유 ③이 약하니 평가할 가치가 없어요.","answer":"X","reason_options":[{"t":"이유 ①·②와 두 근거는 확인할 수 있어 타당한 점이 많기 때문에","correct":true},{"t":"이유 하나가 약하면 카드 뉴스 전체를 버려야 하기 때문에","mis":"K6-2-u3-X20"}],"mis":"K6-2-u3-X20","explanation":["타당한 점을 먼저 세어요.","이유 ①·②와 두 근거는 튼튼해요.","이유 ③만 고치면 돼요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#21','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',3,'ox','auto','영상 평가표에 「거친 말이 없는가」 같은 기준을 더하고 싶으면, 내용의 타당성을 먼저 평가한 뒤에 더해요.',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":21,"concept":"K6-2-u3-C13","difficulty":3,"kind":"ox","stem":"영상 평가표에 「거친 말이 없는가」 같은 기준을 더하고 싶으면, 내용의 타당성을 먼저 평가한 뒤에 더해요.","answer":"O","reason_options":[{"t":"표현의 문제는 내용의 타당성을 충분히 평가한 다음에 살펴야 하기 때문에","correct":true},{"t":"표현이 알맞으면 내용도 저절로 타당하기 때문에","mis":"K6-2-u3-X21"}],"mis":"K6-2-u3-X21","explanation":["표현도 살필 수 있어요.","그러나 내용이 먼저예요.","차례를 바꾸면 재미가 타당성을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#22','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',3,'error','auto','단원을 마치며 다짐한 말이에요. 지키기 어려운 다짐을 한 친구는 누구인가요?',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":22,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"단원을 마치며 다짐한 말이에요. 지키기 어려운 다짐을 한 친구는 누구인가요?","options":[{"t":"하늘 — 「앞으로 열심히 따져 보겠다.」","correct":true,"mis_target":"K6-2-u3-X12"},{"t":"지율 — 「오늘 저녁에 본 영상 하나를 골라 주장과 근거를 적어 보겠다.」","mis":"K6-2-u3-X12"},{"t":"로하 — 「내일 학급 회의에서 친구 주장의 이유를 메모하며 듣겠다.」","mis":"K6-2-u3-X12"}],"explanation":["지율과 로하는 언제·어디에서·무엇을 할지 정했어요.","하늘의 다짐은 무엇부터 할지 알 수 없어요.","다짐도 실천 가능해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#23','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C11',4,'mc','auto','윤채의 말 · 「걸을 땐, 고개를 들어요」 · 「가까운 층은 계단으로」를 함께 평가할 때 공통으로 쓰는 기준은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X21','K6-2-u3-X03']::text[],false,'{"seq":23,"concept":"K6-2-u3-C11","difficulty":4,"kind":"mc","stem":"윤채의 말 · 「걸을 땐, 고개를 들어요」 · 「가까운 층은 계단으로」를 함께 평가할 때 공통으로 쓰는 기준은 어느 것인가요?","options":[{"t":"주장은 가치 있고 중요한가 · 이유는 주장을 뒷받침하는가 · 근거는 이유를 뒷받침하는가","correct":true},{"t":"말은 목소리, 영상은 음악, 카드 뉴스는 그림","mis":"K6-2-u3-X17"},{"t":"말의 길이 · 영상 길이 · 카드 장 수","mis":"K6-2-u3-X21"},{"t":"누가 만들었는가 하나만","mis":"K6-2-u3-X03"}],"explanation":["담는 그릇은 셋이에요.","따지는 기준은 하나예요.","목소리·음악·그림은 표현일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#24','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',4,'essay','teacher','「가까운 층은 계단으로」의 이유 ③이 왜 타당하지 않은지 이유를 재는 두 물음에 대어 쓰고, 이유 ③ 자리에 놓을 더 나은 이유를 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「가까운 층은 계단으로」의 이유 ③이 왜 타당하지 않은지 이유를 재는 두 물음에 대어 쓰고, 이유 ③ 자리에 놓을 더 나은 이유를 두 가지 쓰세요.","answer_guide":{"answer":"예: 이유 ③은 계단으로 다니자는 주장과 관련은 있지만, 멋있어 보이는 것은 사람마다 달라 많은 사람이 받아들이기 어렵다. 그래서 두 물음 가운데 하나만 통과한다. 더 나은 이유 — 승강기를 덜 쓰면 전기를 아낄 수 있기 때문이다. 가까운 층은 승강기를 기다리는 것보다 계단이 오히려 빠르기 때문이다.","scoring_points":["주장과 관련 있는지 따졌는가","많은 사람이 받아들일 만한지 따졌는가","두 물음을 통과하는 이유를 두 가지 썼는가"]},"explanation":["관련은 있어요.","받아들일 만하지 않아요.","지우지 말고 더 나은 이유를 놓아요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#25','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',4,'essay','teacher','「쌓고」 · 「쌓는」 · 「쌓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C14","difficulty":4,"kind":"essay","stem":"「쌓고」 · 「쌓는」 · 「쌓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「블록을 높이 쌓고 사진을 찍었다.」에서 「쌓고」는 [싸코], 「모래성을 쌓는 아이들이 있다.」에서 「쌓는」은 [싼는], 「돌을 차곡차곡 쌓아 올렸다.」에서 「쌓아」는 [싸아]로 소리 난다. 받침 ㅎ 뒤에 ㄱ이 오면 합쳐서 ㅋ으로, ㄴ이 오면 ㄴ으로 소리 나고, 모음이 오면 ㅎ 소리를 내지 않기 때문이다.","scoring_points":["세 낱말을 넣어 문장을 하나씩 만들었는가","[싸코]·[싼는]·[싸아]로 바르게 썼는가","뒤에 오는 소리에 따른 까닭을 썼는가"]},"explanation":["ㄱ 앞 — 합쳐서 ㅋ.","ㄴ 앞 — ㄴ으로.","모음 앞 — 소리 없음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#1','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',1,'mc','auto','「이유」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X07']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"「이유」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 주장하는지를 설명하는 말","correct":true},{"t":"어떤 주제에 대한 자신의 의견을 드러내는 말","mis":"K6-2-u3-X01"},{"t":"이유를 뒷받침하는 자료나 사실","mis":"K6-2-u3-X01"},{"t":"말한 사람이 좋아하는 것","mis":"K6-2-u3-X07"}],"explanation":["주장은 의견이에요.","이유는 그 의견의 까닭이에요.","근거는 이유를 받쳐 주는 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#2','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C2',1,'mc','auto','주장을 따져 보며 들었을 때 좋은 점은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X04']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"주장을 따져 보며 들었을 때 좋은 점은 어느 것인가요?","options":[{"t":"믿을 만한 정보를 골라 쓸 수 있다","correct":true},{"t":"말한 사람과 다툴 수 있다","mis":"K6-2-u3-X02"},{"t":"모든 주장이 틀렸다는 것을 알게 된다","mis":"K6-2-u3-X02"},{"t":"듣는 시간이 짧아진다","mis":"K6-2-u3-X04"}],"explanation":["따져 보면 사실인 것과 아닌 것을 가를 수 있어요.","그래서 믿을 만한 정보를 골라 써요.","따지는 것은 다투는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#3','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C3',1,'mc','auto','주장하는 말을 들을 때 하지 않아야 할 일은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말을 들을 때 하지 않아야 할 일은 어느 것인가요?","options":[{"t":"말이 끝나기 전에 결론을 미리 정해 둔다","correct":true},{"t":"주장 · 이유 · 근거로 나누어 간추린다","mis":"K6-2-u3-X04"},{"t":"내 생각과 견주어 본다","mis":"K6-2-u3-X04"},{"t":"이유와 근거를 적는다","mis":"K6-2-u3-X04"}],"explanation":["간추리기·견주기·적기는 모두 알맞은 방법이에요.","결론은 다 듣고 따진 뒤에 내려요.","미리 정하면 따질 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#4','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C4',1,'sa','auto','주장이 가치 있으려면 문제 해결에 도움이 되고 ○○ 가능해야 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"sa","stem":"주장이 가치 있으려면 문제 해결에 도움이 되고 ○○ 가능해야 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["실천"],"explanation":["주장을 재는 물음은 두 가지예요.","도움이 되는가, 실천 가능한가.","「잠자기 전에 열 쪽씩」처럼 바로 할 수 있어야 해요."],"mis":"K6-2-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#5','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',1,'ox','auto','근거로 나온 기사도 어디에서 나온 자료인지 한 번 더 살펴야 해요.',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"ox","stem":"근거로 나온 기사도 어디에서 나온 자료인지 한 번 더 살펴야 해요.","answer":"O","reason_options":[{"t":"찾은 기사도 출처가 믿을 만한지 다시 따져 보아야 하기 때문에","correct":true},{"t":"기사에 나온 내용은 모두 사실이기 때문에","mis":"K6-2-u3-X09"}],"mis":"K6-2-u3-X09","explanation":["근거가 사실인지 따로 확인해요.","찾은 기사도 그대로 믿지 않아요.","어디에서 나온 자료인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#6','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C8',1,'mc','auto','근거의 출처를 밝혀 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":1,"kind":"mc","stem":"근거의 출처를 밝혀 말한 것은 어느 것인가요?","options":[{"t":"「우리 학교 도서관에서 지난달에 조사한 표입니다.」","correct":true},{"t":"「어디서 봤는데 다들 그렇대요.」","mis":"K6-2-u3-X13"},{"t":"「누가 그러던데 맞대요.」","mis":"K6-2-u3-X13"},{"t":"「제가 알기로는 그래요.」","mis":"K6-2-u3-X13"}],"explanation":["어디에서 언제 나온 자료인지 밝혀요.","그래야 듣는 사람이 확인할 수 있어요.","「어디서 봤는데」는 출처가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#7','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C9',1,'mc','auto','알려 주는 영상의 제목은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"알려 주는 영상의 제목은 어느 것인가요?","options":[{"t":"우리 동네 버스는 하루에 몇 번 다닐까","correct":true},{"t":"가까운 길은 걸어서 다닙시다","mis":"K6-2-u3-X15"},{"t":"오늘부터 휴대 전화를 내려놓읍시다","mis":"K6-2-u3-X15"},{"t":"쓰지 않는 불은 끕시다","mis":"K6-2-u3-X15"}],"explanation":["「~ㅂ시다」는 무엇을 하자고 이끄는 제목이에요.","「몇 번 다닐까」는 사실을 알려 주는 제목이에요.","영상마다 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#8','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C11',1,'ox','auto','카드 뉴스는 그림과 짧은 글을 여러 장으로 이어 핵심만 빠르게 전해요.',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C11","difficulty":1,"kind":"ox","stem":"카드 뉴스는 그림과 짧은 글을 여러 장으로 이어 핵심만 빠르게 전해요.","answer":"O","reason_options":[{"t":"그래서 빠진 것이 잘 보이지 않아 따져 보며 보아야 하기 때문에","correct":true},{"t":"그래서 따져 볼 필요 없이 빠르게 믿으면 되기 때문에","mis":"K6-2-u3-X03"}],"mis":"K6-2-u3-X03","explanation":["카드 뉴스는 짧고 빨라요.","짧을수록 빠진 것이 숨어요.","그래서 따져 보며 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#9','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',2,'sa','auto','윤채의 주장은 「쉬는 시간마다 교실 ○○을 열자」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"sa","stem":"윤채의 주장은 「쉬는 시간마다 교실 ○○을 열자」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["창문"],"explanation":["윤채가 하자고 한 일을 찾아요.","첫 줄과 마지막 줄에 있어요.","「창문을 열자」예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"},"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#10','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C4',2,'mc','auto','윤채의 주장이 실천 가능하다고 볼 수 있는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X03']::text[],false,'{"seq":10,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"윤채의 주장이 실천 가능하다고 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"쉬는 시간 십 분에 창가에 앉은 사람부터 열자고 언제 · 누가 · 무엇을 할지 정했다","correct":true},{"t":"공기가 좋아지면 모두에게 좋기 때문이다","mis":"K6-2-u3-X05"},{"t":"윤채가 말을 잘하기 때문이다","mis":"K6-2-u3-X03"},{"t":"교실 창문이 크기 때문이다","mis":"K6-2-u3-X05"}],"explanation":["실천 가능하려면 언제 무엇을 할지 정해져 있어야 해요.","윤채는 쉬는 시간·창가 사람·창문 열기를 말했어요.","오늘 바로 할 수 있어요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#11','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',2,'error','auto','근거를 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"error","stem":"근거를 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「누리 소통망에서 많이 퍼진 글이면 사실이야.」","correct":true,"mis_target":"K6-2-u3-X09"},{"t":"겸 — 「그 내용을 다룬 책을 찾아볼래.」","mis":"K6-2-u3-X09"},{"t":"나래 — 「찾은 기사도 어디에서 나온 건지 살펴볼래.」","mis":"K6-2-u3-X09"}],"explanation":["겸은 책을 찾아보았어요.","나래는 출처를 다시 살폈어요.","많이 퍼졌다고 사실인 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#12','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C9',2,'sa','auto','「걸을 땐, 고개를 들어요」 마지막 화면에 남은 자막은 「걸을 땐, ○○를 들어요」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"sa","stem":"「걸을 땐, 고개를 들어요」 마지막 화면에 남은 자막은 「걸을 땐, ○○를 들어요」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["고개"],"explanation":["마지막에 소리가 멈춰요.","글자만 남아요.","가장 하고 싶은 말을 마지막에 두었어요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"},"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#13','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C4',2,'match','auto','판단 기준과 그 기준이 재는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K6-2-u3-C4","difficulty":2,"kind":"match","stem":"판단 기준과 그 기준이 재는 것을 알맞게 이으세요.","pairs":[{"l":"실천 가능한가","r":"주장"},{"l":"많은 사람이 받아들일 만한가","r":"이유"},{"l":"객관적인 사실이나 정보인가","r":"근거"}],"mis":"K6-2-u3-X01","explanation":["실천 가능성은 주장을 재요.","받아들일 만함은 이유를 재요.","객관성은 근거를 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#14','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C11',2,'sa','auto','카드 뉴스의 근거마다 「이게 그 ○○를 보여 주나?」를 물어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K6-2-u3-C11","difficulty":2,"kind":"sa","stem":"카드 뉴스의 근거마다 「이게 그 ○○를 보여 주나?」를 물어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["이유"],"explanation":["근거는 이유를 받쳐 줘요.","그 이유를 정말 보여 주는지 물어요.","보여 주지 못하면 약한 근거예요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#15','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',2,'mc','auto','평가할 수 있는 영상인지 먼저 가려내는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X15']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"평가할 수 있는 영상인지 먼저 가려내는 까닭은 어느 것인가요?","options":[{"t":"주장이 없는 영상은 주장 · 이유 · 근거를 재는 평가표로 잴 수 없어서","correct":true},{"t":"긴 영상은 평가할 수 없어서","mis":"K6-2-u3-X21"},{"t":"음악이 없는 영상은 평가할 수 없어서","mis":"K6-2-u3-X21"},{"t":"모든 영상에는 주장이 있어서","mis":"K6-2-u3-X15"}],"explanation":["평가표는 주장·이유·근거를 재요.","알려 주는 영상에는 주장이 없어요.","그래서 먼저 가려내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#16','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C14',2,'sa','auto','「쌓는」을 소리 나는 대로 쓰세요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"sa","stem":"「쌓는」을 소리 나는 대로 쓰세요. 두 글자로 쓰세요.","answer":["싼는","[싼는]"],"explanation":["받침 ㅎ 뒤에 ㄴ이 왔어요.","이때 ㅎ은 ㄴ으로 소리 나요.","그래서 [싼는]이에요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#17','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C7',3,'mc','auto','윤채의 발표를 평가 기준표로 판단한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X20','K6-2-u3-X05']::text[],false,'{"seq":17,"concept":"K6-2-u3-C7","difficulty":3,"kind":"mc","stem":"윤채의 발표를 평가 기준표로 판단한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장 ◎ — 실천 가능 / 이유 ○ — 첫째는 튼튼하나 둘째는 느낌 / 근거 ○ — 측정 수치는 객관적이나 졸린 경험은 주관적","correct":true},{"t":"모두 ◎ — 창문을 열자는 말이 마음에 든다","mis":"K6-2-u3-X12"},{"t":"모두 △ — 약한 데가 있다","mis":"K6-2-u3-X20"},{"t":"주장 △ — 창문은 누구나 열 수 있어 시시하다","mis":"K6-2-u3-X05"}],"explanation":["주장은 오늘 바로 할 수 있어요.","이유와 근거는 하나씩 튼튼하고 하나씩 약해요.","표시마다 까닭이 있어야 해요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#18','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C10',3,'error','auto','「걸을 땐, 고개를 들어요」를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":18,"concept":"K6-2-u3-C10","difficulty":3,"kind":"error","stem":"「걸을 땐, 고개를 들어요」를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"한결 — 「북소리가 커서 무서웠어. 그러니 이 영상은 옳아.」","correct":true,"mis_target":"K6-2-u3-X17"},{"t":"소이 — 「장면 1과 3이 위험한 순간을 보여 주니 이유를 받쳐 줘.」","mis":"K6-2-u3-X15"},{"t":"재아 — 「마지막 자막을 보니 걸을 땐 고개를 들자는 주장이야.」","mis":"K6-2-u3-X15"}],"explanation":["소이는 자료가 이유를 받치는지 보았어요.","재아는 강조로 주장을 찾았어요.","한결은 강조의 세기를 타당성으로 여겼어요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#19','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C12',3,'error','auto','근거 ③을 고치자는 의견이에요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X13']::text[],false,'{"seq":19,"concept":"K6-2-u3-C12","difficulty":3,"kind":"error","stem":"근거 ③을 고치자는 의견이에요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다올 — 「다른 나라의 제도도 덧붙이면 근거 ③이 튼튼해져.」","correct":true,"mis_target":"K6-2-u3-X19"},{"t":"리안 — 「곤충이 불빛 둘레를 맴도는 모습을 관찰한 기록으로 바꾸자.」","mis":"K6-2-u3-X19"},{"t":"하민 — 「새가 불빛 때문에 길을 헤맨다는 연구를 찾아 출처를 밝히자.」","mis":"K6-2-u3-X13"}],"explanation":["리안과 하민은 이유 ③을 보여 주는 자료를 골랐어요.","다올은 해결 방안을 하나 더 보탰어요.","해결 방안은 몇 개를 보태도 이유를 보여 주지 못해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#20','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C5',3,'sa','auto','「가까운 층은 계단으로」의 세 이유 가운데 많은 사람이 받아들이기 어려운 이유는 몇 번인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"K6-2-u3-C5","difficulty":3,"kind":"sa","stem":"「가까운 층은 계단으로」의 세 이유 가운데 많은 사람이 받아들이기 어려운 이유는 몇 번인가요? 숫자로 쓰세요.","answer":["3","③"],"explanation":["멋있어 보이는 것은 사람마다 달라요.","많은 사람이 고개를 끄덕이기 어려워요.","그래서 이유 ③이 타당하지 않아요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"},"mis":"K6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#21','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C3',3,'mc','auto','주장하는 말을 듣는 방법과 하는 일을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":21,"concept":"K6-2-u3-C3","difficulty":3,"kind":"mc","stem":"주장하는 말을 듣는 방법과 하는 일을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"메모하며 듣기 — 이유 · 근거 적기 / 요약하며 듣기 — 주장 · 이유 · 근거로 간추리기 / 견주며 듣기 — 내 생각과 견주기","correct":true},{"t":"메모하며 듣기 — 내 생각과 견주기 / 요약하며 듣기 — 이유 적기","mis":"K6-2-u3-X04"},{"t":"견주며 듣기 — 목소리 크기 견주기 / 메모하며 듣기 — 느낌 적기","mis":"K6-2-u3-X04"},{"t":"요약하며 듣기 — 말한 사람의 옷차림 간추리기","mis":"K6-2-u3-X04"}],"explanation":["메모는 적는 것이에요.","요약은 세 자리로 간추리는 것이에요.","견주기는 내 생각과 견주는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#22','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C10',3,'mc','auto','주장하는 말 · 영상 · 카드 뉴스를 평가하는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X03','K6-2-u3-X15']::text[],false,'{"seq":22,"concept":"K6-2-u3-C10","difficulty":3,"kind":"mc","stem":"주장하는 말 · 영상 · 카드 뉴스를 평가하는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"담는 그릇은 달라도 주장 · 이유 · 근거를 세 기준으로 따지는 방법은 같다","correct":true},{"t":"영상은 강조의 세기로 평가한다","mis":"K6-2-u3-X17"},{"t":"카드 뉴스는 짧아서 평가하지 않는다","mis":"K6-2-u3-X03"},{"t":"주장하는 말만 평가할 수 있다","mis":"K6-2-u3-X15"}],"explanation":["세 자리에서 같은 기준을 썼어요.","영상은 제목·자료·강조로 주장을 찾았어요.","찾은 뒤 따지는 방법은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#23','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',4,'mc','auto','「급식을 남기지 맙시다. 남은 음식을 버리는 데 수고와 돈이 들기 때문입니다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X19','K6-2-u3-X18']::text[],false,'{"seq":23,"concept":"K6-2-u3-C6","difficulty":4,"kind":"mc","stem":"「급식을 남기지 맙시다. 남은 음식을 버리는 데 수고와 돈이 들기 때문입니다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"영양 선생님께 여쭈어 받은, 한 주 동안 우리 학교에서 남은 음식의 양과 처리 방법 기록","correct":true},{"t":"나는 급식이 맛있다는 말","mis":"K6-2-u3-X08"},{"t":"음식물 쓰레기를 줄이려고 다른 학교가 만든 규칙","mis":"K6-2-u3-X19"},{"t":"남은 음식이 해마다 늘고 있다는 말 하나만","mis":"K6-2-u3-X18"}],"explanation":["이유는 버리는 데 수고와 돈이 든다는 것이에요.","그것을 보여 주는 기록이 근거예요.","규칙은 해결 방안, 늘고 있다는 말은 규모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#24','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',4,'essay','teacher','관심 있는 주제를 하나 정해, 그 주제의 영상을 찾을 때 쓸 찾는 말을 쓰고, 찾은 영상을 볼 때와 친구에게 설명할 때 지킬 차례를 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"관심 있는 주제를 하나 정해, 그 주제의 영상을 찾을 때 쓸 찾는 말을 쓰고, 찾은 영상을 볼 때와 친구에게 설명할 때 지킬 차례를 각각 쓰세요.","answer_guide":{"answer":"예: 주제 — 자전거 안전. 찾는 말 — 「자전거 안전모 쓰는 방법 어린이 교육용」. 볼 때의 차례 — 말하지 않고 끝까지 자세히 보기 → 본 것만 말하기 → 무슨 일이 일어나는지 생각하기 → 궁금한 것 묻기. 설명할 때의 차례 — 제목 → 주장 → 이유 → 근거 → 세 기준으로 판단한 결과 → 그렇게 판단한 까닭.","scoring_points":["여러 사람이 함께 생각할 주제와 구체적인 찾는 말을 썼는가","영상을 보는 네 단계를 차례대로 썼는가","설명할 때 넣을 것을 차례대로 썼는가"]},"explanation":["구체적인 말로 찾아요.","본 것과 생각을 섞지 않아요.","판단에는 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#25','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C2',4,'essay','teacher','이 단원에서 배운 말로 「비판적으로 본다는 것」을 설명하고, 생활 속에서 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 말로 「비판적으로 본다는 것」을 설명하고, 생활 속에서 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 비판적으로 본다는 것은 무조건 믿거나 무조건 의심하는 것이 아니라, 주장 · 이유 · 근거가 타당한지 제대로 따져 보고 타당한 점을 먼저 세운 뒤 보완할 점을 까닭과 함께 말하는 것이다. 다짐 — 이번 주 토요일 저녁에 집에서 본 광고 영상 하나를 골라 제목 · 자료 · 강조된 표현으로 주장을 찾고 근거가 객관적인지 공책에 적어 보겠다.","scoring_points":["비판적으로 보기와 무조건 의심하기를 갈라 설명했는가","타당한 점을 먼저 세운다는 점을 썼는가","언제·어디에서·무엇을 할지 담은 다짐을 썼는가"]},"explanation":["비판은 의심이 아니에요.","살릴 것을 먼저 세어요.","다짐도 실천 가능해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C1','kor',6,2,'u4',1,'낱말의 세 갈래 — 고유어는 우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말, 한자어는 한자로 이루어진 낱말, 외래어는 다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말이며, 세 갈래가 어울려 우리말을 이룬다',ARRAY['6국04 문법(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C2','kor',6,2,'u4',1,'우리말을 바르게 쓴다는 것 — 고유어만 쓰거나 한자어·외래어를 몰아내는 것이 아니라, 듣는 사람이 알아들을 수 있게, 낱말의 뜻에 맞게, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰고, 누구에게 어디에서 말하느냐에 따라 상황에 맞게 골라 쓰는 것',ARRAY['6국04 문법(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C3','kor',6,2,'u4',1,'말이 잘 통하지 않을 때 — 지나치게 줄인 말(아는 사람끼리만 통함)·뜻을 알기 어려운 새말(뜻이 서로 다르게 통함)·기분을 상하게 하는 말(뜻은 통해도 마음이 다침)·굳이 어렵게 쓴 외국어(쉬운 우리말을 두고 알아듣기 어려움)는 되묻기·대화에서 밀려나기·다툼을 낳는다',ARRAY['6국04 문법(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C4','kor',6,2,'u4',2,'국어사전으로 갈래 가리기 — 낱말 뒤에 아무것도 붙지 않고 한글 표기만 있으면 고유어, 한자가 함께 있으면 한자어, 영어 등의 외국어가 함께 있으면 외래어이며, 헷갈리는 낱말은 소리나 모양으로 짐작하지 말고 사전에서 확인한다(종이 사전·스마트 기기 사전 모두 같은 방법)',ARRAY['6국04 문법(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C5','kor',6,2,'u4',2,'고유어의 두 모습과 가치 — 고유어는 처음부터 있던 낱말(이슬·호미)과 그것을 바탕으로 만들어진 낱말(나들이·마중물)이 있어 지금도 새로 만들어질 수 있고, 우리말의 기본 바탕을 이루며, 뜻을 쉽게 짐작할 수 있고 느낌을 살려 표현할 수 있고(싱긋·껄껄) 우리 문화와 정서를 담는다',ARRAY['6국04 문법(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C6','kor',6,2,'u4',2,'갈래에 등수 없음 · 다듬은 말 — 세 갈래는 하는 일이 다를 뿐 좋고 나쁨이 없으며, 쉬운 우리말이 있는데도 굳이 어렵게 쓴 말은 다듬고(노견→갓길·익일→다음 날·회람→돌려보기·다운로드→내려받기) 바꿀 말이 마땅치 않거나 바꾸면 오히려 통하지 않는 말(컴퓨터·버스·학교·수학)은 그대로 쓴다 — 다듬기의 목적은 몰아내기가 아니라 누구나 알아듣게 하기',ARRAY['6국04 문법(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C7','kor',6,2,'u4',2,'고유어로 이루어진 관용 표현 — 둘 이상의 낱말이 어울려 새로운 뜻을 만드는 표현(손이 크다=씀씀이가 넉넉하다 · 입이 짧다=음식을 심하게 가리거나 적게 먹다 · 낯을 가리다=낯선 사람을 어려워하다)으로, 낱말 뜻을 하나씩 더해서는 뜻이 나오지 않으며 우리 문화와 정서를 담는다',ARRAY['6국04 문법(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C8','kor',6,2,'u4',4,'고유어를 활용한 사례 찾기 — 동네·길·가게·음식 이름에는 고유어를 살려 지은 것이 많으며(너른들·나루터길·새참·수제비), 여러 낱말로 이루어진 이름은 낱말을 나누어(나루터 + 길) 그 낱말이 고유어인지 사전에서 확인한다',ARRAY['6국01 듣기·말하기(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C9','kor',6,2,'u4',4,'조사 계획과 정리 · 확인과 짐작 가르기 — 조사 대상·범위(손이 닿는 곳으로 좁게)·방법(국어사전·믿을 만한 누리집·어른께 여쭙기)을 먼저 정하고, 유형·사례·고유어·고유어의 뜻 네 칸으로 정리하며, 사전에서 찾은 것·짐작한 것·아직 확인하지 못한 것을 갈라 말하고 지어내지 않는다',ARRAY['6국01 듣기·말하기(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C10','kor',6,2,'u4',4,'매체를 활용한 발표와 듣기 — 알릴 내용을 정한 뒤 그에 맞는 매체(사진·그림·지도·표·종이 자료)를 고르고, 출처가 믿을 만한가·양이 시간에 알맞은가·매체가 도움이 되는가를 점검하며, 발표하는 사람은 유형·사례·뜻을 차례대로 말하고 출처를 밝히고, 듣는 사람은 정리하며 듣고 궁금한 점을 까닭과 함께 묻는다(묻고 답하기까지가 발표)',ARRAY['6국01 듣기·말하기(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C11','kor',6,2,'u4',6,'우리말을 지키기 위한 노력 — 말은 저절로 남지 않으며, 우리말을 마음껏 쓰지 못하던 때에도 흩어진 낱말과 고장마다 다른 말까지 모아 우리말 사전을 만들려던 사람들이 있었고 그 기록이 오늘 국어사전의 바탕이 되었다 — 사전에서 확인하기·쉬운 말로 바꾸기·고장 말을 여쭈어 적기·다른 고장 말을 웃음거리로 삼지 않기도 지키는 일',ARRAY['6국04 문법(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C12','kor',6,2,'u4',6,'생략된 내용 추론하며 읽기 — 글쓴이가 적지 않은 부분을 글의 단서(인물의 말과 행동·때와 곳·되풀이되거나 눈에 띄는 부분)와 내가 가진 경험·지식으로 메우는 일이며, 까닭은 반드시 글 안에 있어야 하고(마음대로 상상하기와 다름), 글에 적힌 것과 추론한 것을 가르고, 처음 보는 낱말은 앞뒤 문맥으로 뜻을 짐작한다',ARRAY['6국02 읽기(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C13','kor',6,2,'u4',6,'표준어와 방언 — 표준어는 온 나라 사람이 두루 통하게 쓰도록 정한 말로 사는 곳이 달라도 서로 통하게 해 주고, 방언은 어느 고장에서 주로 쓰는 표준어가 아닌 말로 그 고장의 정과 역사를 담아 전하며(부엌-정지 · 무-무시 · 김치-짐치), 둘 사이에 등수는 없고 공식적인 자리에서는 표준어로, 고장 사람과는 고장 말로 상황에 맞게 쓴다',ARRAY['6국04 문법(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C14','kor',6,2,'u4',8,'언어생활 점검하기 — 여러 사람에게 전하는 글일수록 누구나 알아듣게 써야 하며, 굳이 외국어로 쓴 말·지나치게 줄인 말·기분을 상하게 하는 말·즐겨 쓰는 고유어를 스스로 표시해 우리 반의 실태로 정리하고, 점검은 친구를 흠잡는 일이 아니라 먼저 내가 쓴 말부터 적고 함께 고치려는 일이다',ARRAY['6국04 문법(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C15','kor',6,2,'u4',8,'실천 다짐문 쓰기와 고쳐 쓰기 — 목적·구체적인 실천 약속(언제·어디에서·무엇을)·전하고 싶은 말·날짜와 쓴 사람 네 부분을 갖추고, 크게 말하는 다짐보다 지킬 수 있는 다짐을 쓰며, 친구 다짐문은 잘 쓴 부분 먼저·고칠 점은 내용에서·바꾸어 볼 문장과 함께 말하고, 나누고 실천한 뒤 되돌아본다',ARRAY['6국03 쓰기(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C16','kor',6,2,'u4',11,'우리말 지킴이 활동 — 알릴 내용에 맞는 방법(알림 영상·인쇄물·만화·우리말 일기·지킴이 도전)을 고르고, 주제·내용·역할·시간을 정해 계획하며, 홍보 문구는 읽는 사람이 알아들을 수 있고 할 일이 보이게 쓰고(어려운 외국어·탓하는 말·꾸밈에 가려진 내용 금지), 하루 행사로 끝내지 않고 이어서 실천한다',ARRAY['6국03 쓰기(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C17','kor',6,2,'u4',11,'교과 학습에 자주 나오는 낱말 — 증발(액체가 그 표면에서 기체로 변하는 현상)·지형(땅의 생긴 모양)·분포(일정한 범위에 흩어져 퍼져 있음)·관측(자연 현상을 살펴 재거나 헤아리는 일)은 모두 한자어이며, 뜻만 외우기보다 문장으로 한 번 써 보면 오래 남는다(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X01','kor',6,'u4',ARRAY['K6-2-u4-C1','K6-2-u4-C4','K6-2-u4-C8']::text[],'낱말의 갈래를 헷갈린다(한자어·외래어를 자주 쓰거나 익숙하다는 까닭으로 고유어로 여기는 등)','처음부터 있던 말? 한자? 다른 나라에서 온 말?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X02','kor',6,'u4',ARRAY['K6-2-u4-C2','K6-2-u4-C6','K6-2-u4-C16']::text[],'우리말을 바르게 쓰는 것을 고유어만 쓰는 것, 한자어와 외래어를 몰아내는 것으로 여긴다','알아들을 수 있게 · 뜻에 맞게 · 바꿀 수 있는 말만 쉽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X03','kor',6,'u4',ARRAY['K6-2-u4-C2','K6-2-u4-C3','K6-2-u4-C14']::text[],'어려운 말·외국어·줄인 말을 많이 쓰면 더 많이 알거나 멋있어 보인다고 여겨, 듣는 사람이 알아듣지 못하는 문제를 보지 않는다','말은 뜻을 주고받으려고 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X04','kor',6,'u4',ARRAY['K6-2-u4-C3','K6-2-u4-C14']::text[],'말이 잘 통하지 않는 네 경우와 그 결과를 헷갈리거나, 뜻만 통하면 마음이 다쳐도 괜찮다고 여긴다','줄인 말 · 새말 · 기분 상하는 말 · 어려운 외국어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X05','kor',6,'u4',ARRAY['K6-2-u4-C4']::text[],'국어사전의 표시를 보지 않고 소리나 글자 모양으로 갈래를 짐작한다','낱말 뒤에 무엇이 붙어 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X06','kor',6,'u4',ARRAY['K6-2-u4-C5']::text[],'고유어를 옛날에만 쓰던 말로 여기거나, 고유어를 바탕으로 새로 만든 낱말은 고유어가 아니라고 여긴다','처음부터 있던 말 + 그것으로 만든 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X07','kor',6,'u4',ARRAY['K6-2-u4-C5','K6-2-u4-C6','K6-2-u4-C13']::text[],'낱말의 갈래나 표준어·방언에 등수를 매겨 고유어(표준어)는 훌륭한 말, 다른 말은 못한 말로 여긴다','하는 일이 다를 뿐, 등수는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X08','kor',6,'u4',ARRAY['K6-2-u4-C6']::text[],'다듬기의 목적을 글자 수 줄이기나 모든 한자어·외래어 바꾸기로 여겨, 바꿀 말이 마땅치 않은 말까지 바꾸려 한다','다듬기 = 누구나 알아듣게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X09','kor',6,'u4',ARRAY['K6-2-u4-C7']::text[],'관용 표현을 낱말 뜻을 하나씩 더해 글자 그대로 풀이한다','둘 이상이 어울려 새로운 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X10','kor',6,'u4',ARRAY['K6-2-u4-C8']::text[],'이름을 낱말로 나누어 보지 않거나, 외국어·한자어로 지은 이름을 고유어 활용 사례로 든다','이름을 낱말로 나누고 사전에서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X11','kor',6,'u4',ARRAY['K6-2-u4-C9']::text[],'조사 대상과 범위를 너무 넓게 잡거나 방법을 정하지 않아 뜻까지 알아볼 시간이 없다','손이 닿는 곳으로 좁게, 방법 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X12','kor',6,'u4',ARRAY['K6-2-u4-C9','K6-2-u4-C10']::text[],'확인한 것·짐작한 것·모르는 것을 섞어 지어내 말하거나, 출처를 밝히지 않고 친구 말을 그대로 옮긴다','「찾은 뜻」·「짐작」·「아직 확인 못 함」 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X13','kor',6,'u4',ARRAY['K6-2-u4-C10','K6-2-u4-C16']::text[],'알릴 내용보다 매체나 꾸밈을 먼저 정하거나, 화려하고 많은 자료가 좋은 자료라고 여긴다','내용 먼저, 매체와 꾸밈은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X14','kor',6,'u4',ARRAY['K6-2-u4-C10']::text[],'듣는 사람의 할 일(정리하며 듣기·까닭 있는 질문)을 하지 않거나 묻고 답하기를 발표가 아니라고 여긴다','궁금한 점 + 그것이 궁금한 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X15','kor',6,'u4',ARRAY['K6-2-u4-C11']::text[],'말은 쓰는 사람이 있으면 저절로 남는다고 여기거나, 사전 만들기를 낱말을 모으는 일로만 보고 말을 지키는 일과 잇지 못한다','적어 두고 이어 주어야 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X16','kor',6,'u4',ARRAY['K6-2-u4-C12']::text[],'추론을 글에 없는 일을 마음대로 상상하는 것으로 여기거나, 까닭 없이 「그냥 그럴 것 같아서」라고 말한다','글의 어느 부분을 보고 그렇게 생각했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X17','kor',6,'u4',ARRAY['K6-2-u4-C12']::text[],'글에 그대로 적힌 것과 단서로 추론한 것을 가르지 못하거나, 글에 적혀 있지 않으면 아무것도 알 수 없다고 여긴다','적힌 것 → 단서 → 메운 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X18','kor',6,'u4',ARRAY['K6-2-u4-C12','K6-2-u4-C5']::text[],'처음 보는 낱말의 뜻을 앞뒤 문맥을 살피지 않고 글자 모양이나 느낌만으로 짐작한다','앞뒤 말에서 실마리 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X19','kor',6,'u4',ARRAY['K6-2-u4-C13','K6-2-u4-C11']::text[],'방언을 고쳐야 할 틀린 말·배우지 못한 사람의 말·웃음거리로 여기거나, 표준어와 방언의 뜻을 헷갈린다','방언도 소중한 우리말 — 쓰이는 자리가 다를 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X20','kor',6,'u4',ARRAY['K6-2-u4-C13','K6-2-u4-C2']::text[],'상황과 듣는 사람을 살피지 않고 어디에서나 한 가지 말만 쓰려 한다(공식적인 자리에서도 고장 말만, 고장 사람과도 표준어만)','누구에게 · 어디에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X21','kor',6,'u4',ARRAY['K6-2-u4-C14']::text[],'언어생활 점검을 친구를 흠잡거나 누가 더 많이 썼는지 세어 견주는 일로 여긴다','내가 쓴 말부터, 우리 반의 일로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X22','kor',6,'u4',ARRAY['K6-2-u4-C15']::text[],'실천 다짐문의 네 부분(목적·실천 약속·전하고 싶은 말·날짜와 쓴 사람)을 빠뜨리거나 하는 일을 헷갈린다','무엇을 위해 · 무엇을 · 부탁 · 누가 언제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X23','kor',6,'u4',ARRAY['K6-2-u4-C15','K6-2-u4-C16']::text[],'「열심히」·「하나도」·「다들」처럼 무엇을 할지 없거나 지킬 수 없을 만큼 크거나 내가 할 일이 없는 다짐을 좋은 다짐으로 여긴다','언제 · 어디에서 · 무엇을 — 내가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X24','kor',6,'u4',ARRAY['K6-2-u4-C15']::text[],'고쳐 쓸 점을 글씨·종이 같은 겉모습에서 찾거나, 잘 쓴 부분은 말하지 않고 흠만 말한다(또는 반대로 고칠 점을 말하지 않는다)','잘 쓴 곳 먼저, 고칠 점은 내용에서, 바꿀 문장과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X25','kor',6,'u4',ARRAY['K6-2-u4-C16']::text[],'우리말 홍보물을 어려운 외국어 문구·누군가를 탓하는 말·꾸밈으로 채우거나 역할·계획 없이 꾸미기부터 한다','알릴 것이 한눈에, 할 일이 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X26','kor',6,'u4',ARRAY['K6-2-u4-C16','K6-2-u4-C15']::text[],'홍보물을 만들거나 다짐문을 쓴 날 하루로 실천이 끝났다고 여긴다','행사가 아니라 실천 — 이어서 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X27','kor',6,'u4',ARRAY['K6-2-u4-C16']::text[],'알릴 내용과 맞지 않는 활동 방법을 고른다(여러 번 보게 할 낱말을 한 번 틀고 마는 영상으로 등)','이 방법이 잘 살리는 점은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X28','kor',6,'u4',ARRAY['K6-2-u4-C17']::text[],'교과 학습 낱말(증발·지형·분포·관측)의 뜻을 서로 헷갈리거나 뜻만 외우고 쓰임을 모른다','낱말을 넣어 문장으로 써 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#1','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'mc','auto','「고유어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"「고유어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말","correct":true},{"t":"한자로 이루어진 낱말","mis":"K6-2-u4-X01"},{"t":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말","mis":"K6-2-u4-X01"},{"t":"어느 고장에서만 주로 쓰는 낱말","mis":"K6-2-u4-X19"}],"explanation":["한자로 이루어진 낱말은 한자어예요.","다른 나라에서 들어온 낱말은 외래어예요.","처음부터 있던 말과 그것으로 만든 말이 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#2','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'sa','auto','다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C1","difficulty":1,"kind":"sa","stem":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["외래어"],"explanation":["고유어는 처음부터 있던 말이에요.","한자어는 한자로 된 말이에요.","다른 나라에서 들어와 널리 쓰이면 외래어예요."],"mis":"K6-2-u4-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#3','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',1,'ox','auto','우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이에요.',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":3,"concept":"K6-2-u4-C2","difficulty":1,"kind":"ox","stem":"우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이에요.","answer":"X","reason_options":[{"t":"듣는 사람이 알아들을 수 있게, 뜻에 맞게 쓰는 것이기 때문에","correct":true},{"t":"한자어와 외래어는 우리말을 해치기 때문에","mis":"K6-2-u4-X02"}],"mis":"K6-2-u4-X02","explanation":["우리말에는 세 갈래가 모두 들어 있어요.","바르게 쓰기는 알아들을 수 있게, 뜻에 맞게 쓰는 것이에요.","다른 갈래를 몰아내는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#4','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',1,'mc','auto','지나치게 줄인 말을 쓰면 어떤 일이 생길 수 있나요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"지나치게 줄인 말을 쓰면 어떤 일이 생길 수 있나요?","options":[{"t":"아는 사람끼리만 통해서 옆 사람이 알아듣지 못한다","correct":true},{"t":"누구나 더 빨리 알아듣는다","mis":"K6-2-u4-X03"},{"t":"낱말의 뜻이 저절로 바뀐다","mis":"K6-2-u4-X04"},{"t":"아무 일도 생기지 않는다","mis":"K6-2-u4-X04"}],"explanation":["줄인 말은 짧아서 편해 보여요.","그러나 아는 사람끼리만 통해요.","함께 있는 사람이 대화에서 밀려나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#5','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'mc','auto','할머니가 말한 「해거름」은 어떤 때를 가리키나요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":5,"concept":"K6-2-u4-C1","difficulty":2,"kind":"mc","stem":"할머니가 말한 「해거름」은 어떤 때를 가리키나요?","options":[{"t":"해가 서쪽으로 넘어갈 무렵","correct":true},{"t":"해가 막 떠오르는 이른 아침","mis":"K6-2-u4-X18"},{"t":"해가 지고 한참 지난 깊은 밤","mis":"K6-2-u4-X18"},{"t":"해가 하늘 한가운데 있는 낮","mis":"K6-2-u4-X18"}],"explanation":["할머니가 「산 너머로 넘어가려고 붉어질 때」라고 다시 말해 주었어요.","해솔이도 「저녁이 되기 조금 전」이라고 짐작했어요.","앞뒤 말을 살피면 처음 듣는 낱말도 뜻을 짐작할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"해솔아, 해거름 전에 텃밭 좀 둘러보고 오렴."},{"who":"해솔","text":"네? 해거름이요? 그게 언제인데요?"},{"who":"할머니","text":"저 해가 산 너머로 넘어가려고 붉어질 때 있잖니. 그때 말이다."},{"who":"해솔","text":"아, 저녁이 되기 조금 전이요? 처음 들어 본 말이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#6','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'match','auto','낱말과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C1","difficulty":2,"kind":"match","stem":"낱말과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"나들이","r":"고유어"},{"l":"체육","r":"한자어"},{"l":"버튼","r":"외래어"}],"mis":"K6-2-u4-X01","explanation":["나들이는 처음부터 있던 우리말이에요.","체육은 한자로 된 말이에요.","버튼은 다른 나라에서 들어와 널리 쓰이는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#7','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',2,'mc','auto','우리말을 바르게 사용하는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X03','K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C2","difficulty":2,"kind":"mc","stem":"우리말을 바르게 사용하는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 알아들을 수 있는 말로 뜻에 맞게 쓴다","correct":true},{"t":"한자어와 외래어는 하나도 쓰지 않는다","mis":"K6-2-u4-X02"},{"t":"어려운 말을 많이 써서 많이 아는 것처럼 보인다","mis":"K6-2-u4-X03"},{"t":"고장의 말을 쓰는 친구를 틀렸다고 고쳐 준다","mis":"K6-2-u4-X19"}],"explanation":["말은 뜻을 주고받으려고 써요.","알아들을 수 있게, 뜻에 맞게 쓰는 것이 바르게 쓰는 거예요.","다른 갈래나 고장 말을 몰아내는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#8','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',2,'mc','auto','기분을 상하게 하는 말이 문제가 되는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":8,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"기분을 상하게 하는 말이 문제가 되는 까닭은 어느 것인가요?","options":[{"t":"뜻은 통해도 듣는 사람의 마음이 다치기 때문에","correct":true},{"t":"뜻이 통하니 아무 문제가 없기 때문에","mis":"K6-2-u4-X04"},{"t":"아는 사람끼리만 통하기 때문에","mis":"K6-2-u4-X04"},{"t":"국어사전에 실려 있지 않기 때문에","mis":"K6-2-u4-X04"}],"explanation":["기분을 상하게 하는 말은 뜻은 잘 통해요.","그래도 듣는 사람의 마음이 다쳐요.","아는 사람끼리만 통하는 것은 줄인 말의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#9','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'ox','auto','「체육」은 고유어예요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":9,"concept":"K6-2-u4-C1","difficulty":2,"kind":"ox","stem":"「체육」은 고유어예요.","answer":"X","reason_options":[{"t":"한자로 이루어진 한자어이기 때문에","correct":true},{"t":"우리가 날마다 쓰는 말이기 때문에","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["날마다 쓴다고 고유어가 되는 것은 아니에요.","체육은 한자로 이루어진 말이에요.","그래서 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_basic#10','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',3,'error','auto','이 단원의 약속에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02']::text[],false,'{"seq":10,"concept":"K6-2-u4-C2","difficulty":3,"kind":"error","stem":"이 단원의 약속에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「고유어를 쓰는 사람이 우리말을 더 잘 쓰는 사람이야.」","correct":true,"mis_target":"K6-2-u4-X07"},{"t":"서하 — 「바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰면 좋아.」","mis":"K6-2-u4-X02"},{"t":"윤아 — 「우리말에는 고유어 · 한자어 · 외래어가 모두 들어 있어.」","mis":"K6-2-u4-X02"}],"explanation":["서하와 윤아는 약속을 바르게 말했어요.","도윤은 갈래에 등수를 매겼어요.","고유어를 쓴 사람이 더 낫다고 여기는 것은 약속과 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#1','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',2,'mc','auto','「굳이 어렵게 쓴 외국어」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X19','K6-2-u4-X01']::text[],false,'{"seq":1,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"「굳이 어렵게 쓴 외국어」에 해당하는 것은 어느 것인가요?","options":[{"t":"쉬운 우리말이 있는데도 외국어를 그대로 쓴 말","correct":true},{"t":"바꿀 말이 마땅히 없어 널리 쓰는 외래어","mis":"K6-2-u4-X08"},{"t":"어느 고장에서 주로 쓰는 말","mis":"K6-2-u4-X19"},{"t":"오래전부터 쓰던 고유어","mis":"K6-2-u4-X01"}],"explanation":["버스처럼 바꿀 말이 없는 외래어는 그대로 써요.","문제는 쉬운 우리말이 있는데도 어렵게 쓴 말이에요.","그러면 알아듣기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#2','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C11',2,'sa','auto','우리말을 마음껏 쓰지 못하던 때, 흩어진 낱말을 모아 우리말 무엇을 만들려고 애쓴 사람들이 있었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C11","difficulty":2,"kind":"sa","stem":"우리말을 마음껏 쓰지 못하던 때, 흩어진 낱말을 모아 우리말 무엇을 만들려고 애쓴 사람들이 있었나요? 두 글자로 쓰세요.","answer":["사전"],"explanation":["온 나라에서 쓰이는 낱말을 모아 적었어요.","고장마다 다른 말도 함께 모았어요.","그 기록이 오늘 국어사전의 바탕이 되었어요."],"mis":"K6-2-u4-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#3','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',3,'mc','auto','해솔이와 할머니의 대화에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X03','K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"해솔이와 할머니의 대화에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"처음 듣는 고유어도 앞뒤 말로 뜻을 짐작할 수 있다","correct":true},{"t":"「해거름」은 틀린 말이라 쓰면 안 된다","mis":"K6-2-u4-X19"},{"t":"할머니는 일부러 어려운 말을 골라 썼다","mis":"K6-2-u4-X03"},{"t":"고유어는 옛날 사람만 쓰는 말이다","mis":"K6-2-u4-X06"}],"explanation":["할머니가 다시 풀어 말해 주었어요.","해솔이는 앞뒤 말로 뜻을 짐작했어요.","해거름은 지금도 쓰는 우리말이에요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"해솔아, 해거름 전에 텃밭 좀 둘러보고 오렴."},{"who":"해솔","text":"네? 해거름이요? 그게 언제인데요?"},{"who":"할머니","text":"저 해가 산 너머로 넘어가려고 붉어질 때 있잖니. 그때 말이다."},{"who":"해솔","text":"아, 저녁이 되기 조금 전이요? 처음 들어 본 말이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#4','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'mc','auto','새로 전학 온 친구가 우리 반 아이들끼리 쓰는 줄인 말을 못 알아들어 대화에 끼지 못했어요. 무엇이 문제인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":3,"kind":"mc","stem":"새로 전학 온 친구가 우리 반 아이들끼리 쓰는 줄인 말을 못 알아들어 대화에 끼지 못했어요. 무엇이 문제인가요?","options":[{"t":"아는 사람끼리만 통하는 말을 써서 함께 있는 사람이 대화에서 밀려났다","correct":true},{"t":"전학 온 친구가 우리말을 잘 몰라서","mis":"K6-2-u4-X03"},{"t":"줄인 말은 사전에 없어 모두 틀린 말이라서","mis":"K6-2-u4-X04"},{"t":"대화하는 목소리가 작아서","mis":"K6-2-u4-X04"}],"explanation":["문제는 친구가 아니라 말에 있어요.","줄인 말은 아는 사람끼리만 통해요.","그래서 함께 있는 사람이 밀려나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#5','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C11',3,'ox','auto','우리말 사전을 만들려던 사람들은 서울에서 쓰는 말만 모았어요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":5,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"우리말 사전을 만들려던 사람들은 서울에서 쓰는 말만 모았어요.","answer":"X","reason_options":[{"t":"고장마다 다르게 쓰는 말도 함께 모았기 때문에","correct":true},{"t":"서울 말만 바른 우리말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["서울에서 쓰는 말만 모으지 않았어요.","고장마다 다르게 쓰는 말도 모았어요.","고장 말도 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#6','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'match','auto','말이 잘 통하지 않는 경우와 생기는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C3","difficulty":3,"kind":"match","stem":"말이 잘 통하지 않는 경우와 생기는 일을 알맞게 이으세요.","pairs":[{"l":"지나치게 줄인 말","r":"아는 사람끼리만 통한다"},{"l":"뜻을 알기 어려운 새말","r":"뜻이 서로 다르게 통한다"},{"l":"기분을 상하게 하는 말","r":"뜻은 통해도 마음이 다친다"},{"l":"굳이 어렵게 쓴 외국어","r":"쉬운 말을 두고 알아듣기 어려워진다"}],"mis":"K6-2-u4-X04","explanation":["줄인 말은 끼리끼리만 통해요.","새말은 금방 생겼다 사라져 뜻이 엇갈려요.","기분 상하는 말은 마음을, 어려운 외국어는 알아듣기를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#7','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C1',3,'error','auto','낱말의 갈래를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X05']::text[],false,'{"seq":7,"concept":"K6-2-u4-C1","difficulty":3,"kind":"error","stem":"낱말의 갈래를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「‘버스’는 우리가 날마다 타니까 고유어야.」","correct":true,"mis_target":"K6-2-u4-X01"},{"t":"이안 — 「‘나들이’는 사전에 한글 표기만 있으니 고유어야.」","mis":"K6-2-u4-X05"},{"t":"채윤 — 「‘체육’은 사전에 한자가 함께 있으니 한자어야.」","mis":"K6-2-u4-X05"}],"explanation":["이안과 채윤은 사전 표시로 갈래를 가렸어요.","하율은 자주 쓴다는 까닭으로 갈래를 정했어요.","버스는 다른 나라에서 들어온 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#8','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'mc','auto','이 단원의 약속에 가장 가깝게 말한 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X03']::text[],false,'{"seq":8,"concept":"K6-2-u4-C2","difficulty":4,"kind":"mc","stem":"이 단원의 약속에 가장 가깝게 말한 것은 어느 것인가요?","options":[{"t":"「‘다운로드’는 ‘내려받기’로 바꾸어도 잘 통하니 바꾸어 쓰고, ‘버스’처럼 바꿀 말이 마땅치 않은 말은 그대로 쓰자.」","correct":true},{"t":"「‘버스’도 고유어로 바꾸어야 우리말을 지킬 수 있어.」","mis":"K6-2-u4-X08"},{"t":"「‘체육’ 같은 한자어는 쓰지 않는 것이 바른 거야.」","mis":"K6-2-u4-X02"},{"t":"「어려운 외국어를 섞어 써야 발표가 멋있어.」","mis":"K6-2-u4-X03"}],"explanation":["바꿀 수 있는 말은 쉬운 우리말로 바꾸어요.","바꿀 말이 마땅치 않은 말은 그대로 써요.","목적은 누구나 알아듣게 하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#9','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'essay','teacher','「우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 우리말을 바르게 쓴다는 것이 무엇인지 세 가지로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"「우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 우리말을 바르게 쓴다는 것이 무엇인지 세 가지로 쓰세요.","answer_guide":{"answer":"예: 우리말에는 고유어 · 한자어 · 외래어가 모두 들어 있고, 채소나 버스처럼 다른 갈래의 낱말이 없으면 말할 수 없는 것도 많다. 그래서 고유어만 쓰는 것이 바르게 쓰는 것은 아니다. 바르게 쓴다는 것은 듣는 사람이 알아들을 수 있게 쓰는 것, 낱말의 뜻에 맞게 쓰는 것, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰는 것이다.","scoring_points":["세 갈래가 함께 우리말을 이룬다는 점을 썼는가","고유어만 쓰는 것이 바르게 쓰는 것이 아닌 까닭을 썼는가","바르게 쓰기의 세 가지를 썼는가"]},"explanation":["우리말에는 세 갈래가 모두 있어요.","몰아내기가 아니라 알아듣게 쓰기예요.","뜻에 맞게, 바꿀 수 있는 말은 쉽게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L01_challenge#10','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',4,'essay','teacher','말이 잘 통하지 않는 경우를 두 가지 골라 그때 생기는 일을 쓰고, 그런 일이 생기지 않게 하려면 어떻게 말하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C3","difficulty":4,"kind":"essay","stem":"말이 잘 통하지 않는 경우를 두 가지 골라 그때 생기는 일을 쓰고, 그런 일이 생기지 않게 하려면 어떻게 말하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 지나치게 줄인 말을 쓰면 아는 사람끼리만 통해서 함께 있는 사람이 대화에서 밀려난다. 굳이 어렵게 쓴 외국어를 쓰면 쉬운 우리말이 있는데도 듣는 사람이 알아듣지 못해 되묻게 된다. 그러니 듣는 사람이 누구인지 살피고, 줄인 말은 풀어서, 어려운 외국어는 쉬운 우리말로 바꾸어 말한다.","scoring_points":["말이 잘 통하지 않는 경우를 두 가지 바르게 골랐는가","각 경우에 생기는 일을 썼는가","듣는 사람을 살펴 고쳐 말하는 방법을 썼는가"]},"explanation":["네 경우를 떠올려요.","그때 누가 어떻게 곤란한지 써요.","듣는 사람의 처지에서 고쳐 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#1','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',1,'mc','auto','국어사전에서 낱말 뒤에 한자가 함께 있으면 그 낱말은 어떤 갈래인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":1,"kind":"mc","stem":"국어사전에서 낱말 뒤에 한자가 함께 있으면 그 낱말은 어떤 갈래인가요?","options":[{"t":"한자어","correct":true},{"t":"고유어","mis":"K6-2-u4-X05"},{"t":"외래어","mis":"K6-2-u4-X05"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["아무것도 붙지 않으면 고유어예요.","외국어가 함께 있으면 외래어예요.","한자가 함께 있으면 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#2','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',1,'sa','auto','펌프에서 물이 나오지 않을 때 물을 끌어올리려고 위에서 붓는 물을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C5","difficulty":1,"kind":"sa","stem":"펌프에서 물이 나오지 않을 때 물을 끌어올리려고 위에서 붓는 물을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["마중물"],"explanation":["물을 마중 나간다는 말에서 왔어요.","두 낱말을 이어 보면 뜻에 가까이 갈 수 있어요.","그래서 고유어는 뜻을 짐작하기 쉬워요."],"mis":"K6-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#3','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',1,'ox','auto','고유어는 지금도 새로 만들어질 수 있어요.',ARRAY['K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C5","difficulty":1,"kind":"ox","stem":"고유어는 지금도 새로 만들어질 수 있어요.","answer":"O","reason_options":[{"t":"고유어를 이어 붙여 새 낱말을 만들 수 있기 때문에","correct":true},{"t":"고유어는 옛날에 있던 낱말만을 말하기 때문에","mis":"K6-2-u4-X06"}],"mis":"K6-2-u4-X06","explanation":["고유어에는 처음부터 있던 낱말이 있어요.","그것을 바탕으로 만든 낱말도 있어요.","그래서 지금도 새로 만들어질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#4','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',1,'mc','auto','「노견」을 쉬운 우리말로 다듬은 말은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X03']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"「노견」을 쉬운 우리말로 다듬은 말은 어느 것인가요?","options":[{"t":"갓길","correct":true},{"t":"노변","mis":"K6-2-u4-X08"},{"t":"사이드 로드","mis":"K6-2-u4-X03"},{"t":"고속 도로","mis":"K6-2-u4-X08"}],"explanation":["노견은 길의 가장자리를 말해요.","갓길이라고 하면 뜻이 바로 보여요.","그래서 누구나 알아들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#5','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'mc','auto','이 글에서 고유어를 살펴보아야 하는 까닭으로 든 것은 어느 것인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X06','K6-2-u4-X01']::text[],false,'{"seq":5,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"이 글에서 고유어를 살펴보아야 하는 까닭으로 든 것은 어느 것인가요?","options":[{"t":"고유어가 우리말의 기본 바탕을 이루기 때문에","correct":true},{"t":"다른 갈래의 낱말보다 훌륭한 말이기 때문에","mis":"K6-2-u4-X07"},{"t":"옛날에만 쓰던 말이라 이제는 쓰지 않기 때문에","mis":"K6-2-u4-X06"},{"t":"낱말의 수가 가장 적기 때문에","mis":"K6-2-u4-X01"}],"explanation":["글의 첫 문장에 까닭이 있어요.","고유어는 우리말의 기본 바탕이에요.","다른 갈래보다 훌륭하다는 말은 없어요."],"asset":{"type":"passage","lines":["고유어는 우리말의 기본 바탕을 이룬다.","오랫동안 많은 사람이 써 온 낱말이라 살아온 모습과 느낌이 함께 담겨 있다.","첫째, 고유어는 뜻을 쉽게 짐작할 수 있다. 「마중물」은 물을 마중 나간다는 말에서 왔다.","둘째, 고유어는 느낌을 살려 표현할 수 있다.","같은 웃음이라도 「싱긋」과 「껄껄」은 다른 모습을 떠올리게 한다.","셋째, 고유어로 이루어진 표현에는 우리 문화와 정서가 담겨 있다."],"title":"고유어에는 어떤 가치가 있을까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#6','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',2,'mc','auto','별하의 글에 나온 낱말 가운데 고유어가 아닌 것은 어느 것인가요?',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":6,"concept":"K6-2-u4-C4","difficulty":2,"kind":"mc","stem":"별하의 글에 나온 낱말 가운데 고유어가 아닌 것은 어느 것인가요?","options":[{"t":"채소","correct":true},{"t":"이슬","mis":"K6-2-u4-X01"},{"t":"호미","mis":"K6-2-u4-X01"},{"t":"두둑","mis":"K6-2-u4-X01"}],"explanation":["이슬 · 호미 · 두둑은 사전에 한글 표기만 있어요.","채소는 사전에 한자가 함께 있어요.","채소는 한자어예요."],"asset":{"type":"passage","lines":["토요일 아침, 별하는 할머니를 따라 텃밭에 나갔다.","밤새 내린 이슬이 잎마다 맺혀 있었다.","할머니는 호미를 하나 건네주시며 두둑 사이의 풀을 뽑으라고 하셨다.","별하는 채소가 이렇게 촘촘히 심겨 있는 줄 몰랐다.","붉게 익은 토마토를 따서 바구니에 담았다.","일을 마치고 마루에 앉으니 등이 뻐근했다.","할머니가 웃으셨다. 「오늘은 네 덕에 일이 수월했구나.」"],"title":"별하가 토요일 아침에 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#7','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'match','auto','고유어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C5","difficulty":2,"kind":"match","stem":"고유어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"여울","r":"물살이 세게 흐르는 얕은 곳"},{"l":"마중물","r":"물을 끌어올리려고 위에서 붓는 물"},{"l":"손사래","r":"아니라고 할 때 손을 펴서 휘젓는 일"}],"mis":"K6-2-u4-X18","explanation":["여울은 물살이 센 얕은 곳이에요.","마중물은 물을 마중 나가는 물이에요.","세 낱말 모두 눈에 보이는 모습을 담고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#8','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C7',2,'mc','auto','「손이 크다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":8,"concept":"K6-2-u4-C7","difficulty":2,"kind":"mc","stem":"「손이 크다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"씀씀이가 넉넉하다","correct":true},{"t":"손의 크기가 남보다 크다","mis":"K6-2-u4-X09"},{"t":"힘이 아주 세다","mis":"K6-2-u4-X09"},{"t":"손재주가 좋다","mis":"K6-2-u4-X09"}],"explanation":["관용 표현은 낱말 뜻을 그대로 더한 것이 아니에요.","둘 이상의 낱말이 어울려 새로운 뜻을 만들어요.","손이 크다는 씀씀이가 넉넉하다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#9','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',2,'ox','auto','「컴퓨터」도 고유어로 다듬어 써야 해요.',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":9,"concept":"K6-2-u4-C6","difficulty":2,"kind":"ox","stem":"「컴퓨터」도 고유어로 다듬어 써야 해요.","answer":"X","reason_options":[{"t":"바꿀 말이 마땅히 없어 그대로 쓰는 것이 더 잘 통하기 때문에","correct":true},{"t":"외래어는 모두 우리말로 바꾸어야 하기 때문에","mis":"K6-2-u4-X08"}],"mis":"K6-2-u4-X08","explanation":["다듬는 말은 쉬운 우리말이 이미 있는 말이에요.","컴퓨터는 바꿀 말이 마땅치 않아요.","그대로 쓰는 것이 오히려 잘 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_basic#10','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',3,'error','auto','낱말의 갈래에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02']::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":3,"kind":"error","stem":"낱말의 갈래에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「한자어를 쓰면 우리말을 해치는 거야.」","correct":true,"mis_target":"K6-2-u4-X07"},{"t":"로운 — 「세 갈래가 함께 우리말을 이루고 하는 일이 달라.」","mis":"K6-2-u4-X07"},{"t":"수아 — 「‘채소’나 ‘토마토’가 없으면 별하의 장면을 말할 수 없어.」","mis":"K6-2-u4-X02"}],"explanation":["로운과 수아는 세 갈래가 함께 쓰인다는 것을 알아요.","지안은 한자어를 나쁜 말로 여겼어요.","갈래에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#1','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',2,'sa','auto','국어사전에서 낱말 뒤에 영어 같은 외국어가 함께 있으면 그 낱말은 어떤 갈래인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":2,"kind":"sa","stem":"국어사전에서 낱말 뒤에 영어 같은 외국어가 함께 있으면 그 낱말은 어떤 갈래인가요? 세 글자로 쓰세요.","answer":["외래어"],"explanation":["토마토를 찾으면 뒤에 영어가 함께 있어요.","다른 나라에서 들어온 말이라는 표시예요.","그래서 외래어예요."],"mis":"K6-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#2','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',2,'mc','auto','고유어의 가치 세 가지를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X07','K6-2-u4-X06']::text[],false,'{"seq":2,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"고유어의 가치 세 가지를 바르게 모은 것은 어느 것인가요?","options":[{"t":"뜻을 쉽게 짐작할 수 있다 · 느낌을 살려 표현할 수 있다 · 우리 문화와 정서가 담겨 있다","correct":true},{"t":"글자 수가 적다 · 외국 사람도 쉽게 안다 · 사전에 없다","mis":"K6-2-u4-X01"},{"t":"다른 갈래보다 훌륭하다 · 한자어를 이긴다 · 등수가 높다","mis":"K6-2-u4-X07"},{"t":"옛날 말이라 귀하다 · 이제는 쓰지 않는다 · 새로 만들 수 없다","mis":"K6-2-u4-X06"}],"explanation":["뜻을 짐작하기 쉬워요.","느낌을 살려 표현해요.","우리 문화와 정서를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#3','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',3,'mc','auto','글쓴이가 「싱긋」과 「껄껄」을 예로 든 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X07']::text[],false,'{"seq":3,"concept":"K6-2-u4-C5","difficulty":3,"kind":"mc","stem":"글쓴이가 「싱긋」과 「껄껄」을 예로 든 까닭은 어느 것인가요?","options":[{"t":"고유어가 느낌을 살려 표현할 수 있다는 것을 보여 주려고","correct":true},{"t":"고유어는 뜻을 쉽게 짐작할 수 있다는 것을 보여 주려고","mis":"K6-2-u4-X18"},{"t":"웃음은 고유어로만 말할 수 있다는 것을 보여 주려고","mis":"K6-2-u4-X07"},{"t":"두 낱말의 뜻이 같다는 것을 보여 주려고","mis":"K6-2-u4-X18"}],"explanation":["「둘째」 문단에 나온 예예요.","같은 웃음도 다른 모습을 떠올리게 해요.","느낌을 살리는 가치를 보여 줘요."],"asset":{"type":"passage","lines":["고유어는 우리말의 기본 바탕을 이룬다.","오랫동안 많은 사람이 써 온 낱말이라 살아온 모습과 느낌이 함께 담겨 있다.","첫째, 고유어는 뜻을 쉽게 짐작할 수 있다. 「마중물」은 물을 마중 나간다는 말에서 왔다.","둘째, 고유어는 느낌을 살려 표현할 수 있다.","같은 웃음이라도 「싱긋」과 「껄껄」은 다른 모습을 떠올리게 한다.","셋째, 고유어로 이루어진 표현에는 우리 문화와 정서가 담겨 있다."],"title":"고유어에는 어떤 가치가 있을까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#4','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',3,'mc','auto','다듬으면 좋은 말과 그대로 쓰는 말을 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X01']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":3,"kind":"mc","stem":"다듬으면 좋은 말과 그대로 쓰는 말을 바르게 가른 것은 어느 것인가요?","options":[{"t":"다듬으면 좋은 말 — 익일 · 회람 / 그대로 쓰는 말 — 버스 · 수학","correct":true},{"t":"다듬으면 좋은 말 — 버스 · 학교 / 그대로 쓰는 말 — 익일 · 회람","mis":"K6-2-u4-X08"},{"t":"다듬으면 좋은 말 — 모든 한자어와 외래어 / 그대로 쓰는 말 — 고유어","mis":"K6-2-u4-X02"},{"t":"다듬으면 좋은 말 — 이슬 · 호미 / 그대로 쓰는 말 — 노견","mis":"K6-2-u4-X01"}],"explanation":["쉬운 우리말이 있는데도 어렵게 쓴 말은 다듬어요.","바꿀 말이 마땅치 않은 말은 그대로 써요.","익일 · 회람은 다음 날 · 돌려보기로 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#5','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',3,'ox','auto','「수월하다」는 소리가 한자어 같으니 한자어예요.',ARRAY['K6-2-u4-X05']::text[],false,'{"seq":5,"concept":"K6-2-u4-C4","difficulty":3,"kind":"ox","stem":"「수월하다」는 소리가 한자어 같으니 한자어예요.","answer":"X","reason_options":[{"t":"국어사전에 한자 없이 한글 표기만 있는 고유어이기 때문에","correct":true},{"t":"낱말의 갈래는 소리를 듣고 짐작하면 되기 때문에","mis":"K6-2-u4-X05"}],"mis":"K6-2-u4-X05","explanation":["소리로 갈래를 정하면 틀리기 쉬워요.","사전에서 확인해요.","수월하다는 한글 표기만 있는 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#6','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',3,'match','auto','어려운 말과 쉬운 우리말로 다듬은 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C6","difficulty":3,"kind":"match","stem":"어려운 말과 쉬운 우리말로 다듬은 말을 알맞게 이으세요.","pairs":[{"l":"노견","r":"갓길"},{"l":"익일","r":"다음 날"},{"l":"회람","r":"돌려보기"},{"l":"다운로드","r":"내려받기"}],"mis":"K6-2-u4-X08","explanation":["갓길은 길의 가장자리라는 뜻이 보여요.","다음 날은 언제인지 바로 알 수 있어요.","돌려보기 · 내려받기는 하는 일이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#7','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C7',3,'error','auto','관용 표현의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":7,"concept":"K6-2-u4-C7","difficulty":3,"kind":"error","stem":"관용 표현의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「‘입이 짧다’는 입의 길이가 짧다는 뜻이야.」","correct":true,"mis_target":"K6-2-u4-X09"},{"t":"나은 — 「‘낯을 가리다’는 낯선 사람을 어려워한다는 뜻이야.」","mis":"K6-2-u4-X09"},{"t":"승우 — 「‘손이 크다’는 씀씀이가 넉넉하다는 뜻이야.」","mis":"K6-2-u4-X09"}],"explanation":["나은과 승우는 어울려 생긴 새 뜻을 말했어요.","태오는 낱말 뜻을 그대로 풀었어요.","입이 짧다는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#8','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'mc','auto','어려운 말을 쉬운 우리말로 다듬는 일의 목적으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X08','K6-2-u4-X07']::text[],false,'{"seq":8,"concept":"K6-2-u4-C6","difficulty":4,"kind":"mc","stem":"어려운 말을 쉬운 우리말로 다듬는 일의 목적으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구나 알아들을 수 있게 하는 것","correct":true},{"t":"한자어와 외래어를 우리말에서 몰아내는 것","mis":"K6-2-u4-X02"},{"t":"글자 수를 줄여 빨리 쓰는 것","mis":"K6-2-u4-X08"},{"t":"고유어가 더 훌륭하다는 것을 보이는 것","mis":"K6-2-u4-X07"}],"explanation":["다듬은 말은 뜻이 바로 드러나요.","그래서 누구나 알아들을 수 있어요.","낱말을 몰아내려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#9','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',4,'essay','teacher','별하의 글에서 고유어를 세 개, 고유어가 아닌 낱말을 두 개 찾아 쓰세요. 그리고 고유어가 아닌 낱말도 이 글에 꼭 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"별하의 글에서 고유어를 세 개, 고유어가 아닌 낱말을 두 개 찾아 쓰세요. 그리고 고유어가 아닌 낱말도 이 글에 꼭 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 고유어 — 이슬 · 호미 · 두둑. 고유어가 아닌 낱말 — 채소(한자어) · 토마토(외래어). 채소와 토마토가 없으면 별하가 무엇을 보고 땄는지 그 장면을 말할 수 없다. 세 갈래가 함께 우리말을 이루고 각 갈래가 하는 일이 다르기 때문이다.","scoring_points":["고유어를 세 개 바르게 찾았는가","한자어 · 외래어를 바르게 찾았는가","세 갈래가 함께 쓰이는 까닭을 썼는가"]},"explanation":["사전 표시로 갈래를 가려요.","고유어가 아닌 말도 틀린 말이 아니에요.","갈래에는 등수가 없어요."],"asset":{"type":"passage","lines":["토요일 아침, 별하는 할머니를 따라 텃밭에 나갔다.","밤새 내린 이슬이 잎마다 맺혀 있었다.","할머니는 호미를 하나 건네주시며 두둑 사이의 풀을 뽑으라고 하셨다.","별하는 채소가 이렇게 촘촘히 심겨 있는 줄 몰랐다.","붉게 익은 토마토를 따서 바구니에 담았다.","일을 마치고 마루에 앉으니 등이 뻐근했다.","할머니가 웃으셨다. 「오늘은 네 덕에 일이 수월했구나.」"],"title":"별하가 토요일 아침에 겪은 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L02_challenge#10','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'essay','teacher','학교 안내문에 「익일까지 회람 후 반납」이라고 적혀 있어요. 이 문장을 쉬운 우리말로 다듬어 쓰고, 그렇게 다듬은 까닭을 쓰세요. 그리고 같은 안내문의 「컴퓨터실」은 왜 그대로 두어도 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":4,"kind":"essay","stem":"학교 안내문에 「익일까지 회람 후 반납」이라고 적혀 있어요. 이 문장을 쉬운 우리말로 다듬어 쓰고, 그렇게 다듬은 까닭을 쓰세요. 그리고 같은 안내문의 「컴퓨터실」은 왜 그대로 두어도 되는지 쓰세요.","answer_guide":{"answer":"예: 「다음 날까지 돌려본 뒤 돌려주세요.」로 다듬는다. 익일 · 회람은 쉬운 우리말이 있는데도 어렵게 쓴 말이라, 다듬으면 나이가 많은 분이나 동생들도 무엇을 언제까지 해야 하는지 바로 알 수 있다. 컴퓨터는 바꿀 말이 마땅히 없고 바꾸면 오히려 통하지 않으므로 그대로 둔다.","scoring_points":["어려운 말을 쉬운 우리말로 바르게 다듬었는가","누구나 알아듣게 하려는 까닭을 썼는가","그대로 쓰는 말의 까닭을 썼는가"]},"explanation":["뜻이 바로 보이게 다듬어요.","목적은 누구나 알아듣게 하기예요.","바꿀 말이 없는 말은 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#1','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',1,'mc','auto','고유어를 활용한 이름은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":1,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"고유어를 활용한 이름은 어느 것인가요?","options":[{"t":"너른들 마을","correct":true},{"t":"그린 아파트","mis":"K6-2-u4-X10"},{"t":"제일 상가","mis":"K6-2-u4-X10"},{"t":"센트럴 공원","mis":"K6-2-u4-X10"}],"explanation":["너른들은 넓은 들이라는 고유어로 지은 이름이에요.","그린 · 센트럴은 외국어예요.","제일은 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#2','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'sa','auto','조사한 내용은 유형 · 사례 · 고유어 · 고유어의 ○ 네 칸으로 정리해요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C9","difficulty":1,"kind":"sa","stem":"조사한 내용은 유형 · 사례 · 고유어 · 고유어의 ○ 네 칸으로 정리해요. ○에 알맞은 한 글자를 쓰세요.","answer":["뜻"],"explanation":["유형은 동네 · 길 · 가게 · 음식 이름 가운데 하나예요.","사례와 그 속의 고유어를 적어요.","마지막 칸에는 사전에서 확인한 뜻을 적어요."],"mis":"K6-2-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#3','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',1,'ox','auto','발표 자료는 화려할수록 좋아요.',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":3,"concept":"K6-2-u4-C10","difficulty":1,"kind":"ox","stem":"발표 자료는 화려할수록 좋아요.","answer":"X","reason_options":[{"t":"듣는 사람이 이해하는 데 도움이 되는 자료가 좋기 때문에","correct":true},{"t":"보기 좋은 자료가 내용보다 먼저이기 때문에","mis":"K6-2-u4-X13"}],"mis":"K6-2-u4-X13","explanation":["발표 자료는 꾸미기 대회가 아니에요.","화려하면 내용이 가려질 수 있어요.","이해에 도움이 되는 자료가 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#4','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'mc','auto','이름의 뜻을 알아볼 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":4,"concept":"K6-2-u4-C9","difficulty":1,"kind":"mc","stem":"이름의 뜻을 알아볼 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"국어사전에서 찾고 어른께도 여쭈어 본다","correct":true},{"t":"글자 모양을 보고 짐작해서 정한다","mis":"K6-2-u4-X12"},{"t":"친구가 그렇다고 하면 그대로 적는다","mis":"K6-2-u4-X12"},{"t":"가장 그럴듯한 뜻을 지어 쓴다","mis":"K6-2-u4-X12"}],"explanation":["짐작한 뒤에는 반드시 확인해요.","사전 · 믿을 만한 누리집 · 어른께 여쭙기가 방법이에요.","지어 쓰면 듣는 사람이 잘못 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#5','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'mc','auto','「나루터길」을 낱말로 바르게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":5,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"「나루터길」을 낱말로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"나루터 + 길","correct":true},{"t":"나 + 루터길","mis":"K6-2-u4-X10"},{"t":"나루 + 터길","mis":"K6-2-u4-X10"},{"t":"나눌 수 없는 한 낱말","mis":"K6-2-u4-X10"}],"explanation":["여러 낱말로 된 이름은 나누어 살펴요.","나루터는 배가 닿고 떠나는 곳이에요.","길과 이어서 나루터로 가는 길이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#6','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'match','auto','이름 속 고유어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C8","difficulty":2,"kind":"match","stem":"이름 속 고유어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"너르다","r":"공간이 두루 다 넓다"},{"l":"나루터","r":"배가 닿고 떠나는 곳"},{"l":"새참","r":"일을 하다가 잠시 쉬며 먹는 음식"}],"mis":"K6-2-u4-X10","explanation":["너른들의 「너른」은 너르다에서 왔어요.","나루터는 배가 오가는 곳이에요.","새참은 일하다 쉬며 먹는 음식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#7','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'mc','auto','「우리 동네 길 이름 속 고유어」를 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"「우리 동네 길 이름 속 고유어」를 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?","options":[{"t":"지도와 사진","correct":true},{"t":"글자만 빽빽하게 적은 종이","mis":"K6-2-u4-X13"},{"t":"아주 빠르게 넘기는 화면","mis":"K6-2-u4-X13"},{"t":"가사 없는 배경 음악","mis":"K6-2-u4-X13"}],"explanation":["길 이름은 어디에 있는지 함께 보여야 해요.","지도는 위치와 길의 흐름을 보여 줘요.","사진은 실제 모습을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#8','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',2,'mc','auto','조사 범위로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X11']::text[],false,'{"seq":8,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"조사 범위로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교에서 집까지 오는 길에 있는 가게 이름","correct":true},{"t":"우리나라에 있는 모든 가게 이름","mis":"K6-2-u4-X11"},{"t":"세계 여러 나라의 음식 이름","mis":"K6-2-u4-X11"},{"t":"정하지 않고 눈에 띄는 대로","mis":"K6-2-u4-X11"}],"explanation":["범위는 손이 닿는 곳으로 정해요.","범위를 좁게 잡을수록 뜻까지 알아볼 시간이 생겨요.","너무 넓으면 확인할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#9','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'ox','auto','묻고 답하는 시간까지가 발표예요.',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":9,"concept":"K6-2-u4-C10","difficulty":2,"kind":"ox","stem":"묻고 답하는 시간까지가 발표예요.","answer":"O","reason_options":[{"t":"듣는 사람이 궁금한 점을 까닭과 함께 묻고 답하며 이야기가 이어지기 때문에","correct":true},{"t":"발표하는 사람이 말을 마치면 발표가 끝나기 때문에","mis":"K6-2-u4-X14"}],"mis":"K6-2-u4-X14","explanation":["듣는 사람에게도 할 일이 있어요.","궁금한 점을 까닭과 함께 물어요.","묻고 답하기까지가 발표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_basic#10','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',3,'error','auto','조사하다가 뜻을 찾지 못한 이름이 나왔을 때 할 일을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":10,"concept":"K6-2-u4-C9","difficulty":3,"kind":"error","stem":"조사하다가 뜻을 찾지 못한 이름이 나왔을 때 할 일을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「모르겠으면 그럴듯한 뜻을 지어서 말하면 돼.」","correct":true,"mis_target":"K6-2-u4-X12"},{"t":"하린 — 「‘아직 확인하지 못했습니다’라고 말하면 돼.」","mis":"K6-2-u4-X12"},{"t":"준서 — 「짐작한 것은 ‘짐작했습니다’라고 밝혀서 말해.」","mis":"K6-2-u4-X12"}],"explanation":["하린과 준서는 확인 · 짐작 · 모름을 갈랐어요.","시후는 모르는 것을 아는 척했어요.","지어내지 말고 아직 확인하지 못했다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#1','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',2,'sa','auto','발표할 때는 그 내용을 어디에서 알아냈는지 밝혀요. 이것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C10","difficulty":2,"kind":"sa","stem":"발표할 때는 그 내용을 어디에서 알아냈는지 밝혀요. 이것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["사전인지, 누리집인지, 어른께 여쭌 것인지 말해요.","듣는 사람이 확인할 수 있어요.","그것을 출처라고 해요."],"mis":"K6-2-u4-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#2','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',2,'mc','auto','조사한 이름 여러 개를 한눈에 견주어 보여 주려면 어떤 매체가 알맞나요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":2,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"조사한 이름 여러 개를 한눈에 견주어 보여 주려면 어떤 매체가 알맞나요?","options":[{"t":"표","correct":true},{"t":"지도","mis":"K6-2-u4-X13"},{"t":"사진 한 장","mis":"K6-2-u4-X13"},{"t":"소리 내어 읽기만 하기","mis":"K6-2-u4-X13"}],"explanation":["지도는 위치를 보여 줘요.","사진은 실제 모습을 보여 줘요.","여러 사례를 견줄 때는 표가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#3','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C8',3,'mc','auto','「봄뜰 도서관」에서 찾을 수 있는 고유어를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X10']::text[],false,'{"seq":3,"concept":"K6-2-u4-C8","difficulty":3,"kind":"mc","stem":"「봄뜰 도서관」에서 찾을 수 있는 고유어를 바르게 모은 것은 어느 것인가요?","options":[{"t":"봄 · 뜰","correct":true},{"t":"도서관","mis":"K6-2-u4-X01"},{"t":"봄뜰 도서관 전체","mis":"K6-2-u4-X10"},{"t":"고유어가 없다","mis":"K6-2-u4-X10"}],"explanation":["이름을 낱말로 나누어요 — 봄 · 뜰 · 도서관.","봄과 뜰은 고유어예요.","도서관은 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#4','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',3,'mc','auto','짐작한 것을 짐작했다고 바르게 밝힌 말은 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":4,"concept":"K6-2-u4-C9","difficulty":3,"kind":"mc","stem":"짐작한 것을 짐작했다고 바르게 밝힌 말은 어느 것인가요?","options":[{"t":"「‘모퉁이 빵집’은 길이 꺾이는 자리에 있어서 붙인 이름이 아닐까 짐작했습니다.」","correct":true},{"t":"「‘모퉁이 빵집’은 주인이 모퉁이를 좋아해서 지은 이름입니다.」","mis":"K6-2-u4-X12"},{"t":"「잘 모르지만 아마 맞을 겁니다.」","mis":"K6-2-u4-X12"},{"t":"「친구가 알려 준 뜻을 사전에서 찾은 뜻이라고 적었습니다.」","mis":"K6-2-u4-X12"}],"explanation":["짐작은 짐작이라고 밝혀요.","확인하지 않은 것을 사실처럼 말하지 않아요.","친구 말을 사전 뜻이라고 옮기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#5','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'ox','auto','발표할 매체를 먼저 정하고 그다음에 알릴 내용을 끼워 맞추어요.',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":5,"concept":"K6-2-u4-C10","difficulty":3,"kind":"ox","stem":"발표할 매체를 먼저 정하고 그다음에 알릴 내용을 끼워 맞추어요.","answer":"X","reason_options":[{"t":"알릴 내용을 정한 뒤 그 내용에 맞는 매체를 고르기 때문에","correct":true},{"t":"멋진 매체가 정해져야 내용이 살아나기 때문에","mis":"K6-2-u4-X13"}],"mis":"K6-2-u4-X13","explanation":["내용이 먼저예요.","그 내용을 잘 보여 줄 매체를 골라요.","매체에 내용을 끼워 맞추지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#6','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'match','auto','매체와 그 매체가 알맞은 때를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C10","difficulty":3,"kind":"match","stem":"매체와 그 매체가 알맞은 때를 이으세요.","pairs":[{"l":"사진 · 그림","r":"실제 모습을 보여 줄 때"},{"l":"지도","r":"위치나 길의 흐름을 보여 줄 때"},{"l":"표","r":"여러 사례를 한눈에 견줄 때"},{"l":"종이 자료","r":"차례대로 자세히 설명할 때"}],"mis":"K6-2-u4-X13","explanation":["사진은 모습, 지도는 위치예요.","표는 견주기예요.","종이 자료는 차례대로 자세히 설명할 때 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#7','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'error','auto','발표 전에 점검할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X12']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":3,"kind":"error","stem":"발표 전에 점검할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"유나 — 「우리 모둠 자료가 가장 화려한지 살펴보자.」","correct":true,"mis_target":"K6-2-u4-X13"},{"t":"도하 — 「조사한 자료의 출처가 믿을 만한지 살펴보자.」","mis":"K6-2-u4-X12"},{"t":"은재 — 「자료의 양이 발표 시간에 알맞은지 살펴보자.」","mis":"K6-2-u4-X13"}],"explanation":["출처 · 양 · 매체가 점검할 세 가지예요.","도하와 은재는 그것을 살폈어요.","유나는 꾸밈을 기준으로 삼았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#8','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',4,'mc','auto','「너른들 마을」 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":8,"concept":"K6-2-u4-C10","difficulty":4,"kind":"mc","stem":"「너른들 마을」 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「‘너른들’이 넓은 들이라는 뜻이라면 지금 그 마을에도 들이 남아 있는지 궁금해요. 이름이 지금 모습과 맞는지 알고 싶어서요.」","correct":true},{"t":"「그냥 궁금해요.」","mis":"K6-2-u4-X14"},{"t":"「우리 모둠이 더 잘했지요?」","mis":"K6-2-u4-X14"},{"t":"「발표가 왜 이렇게 길어요?」","mis":"K6-2-u4-X14"}],"explanation":["발표 내용을 정리하며 들어요.","궁금한 점을 까닭과 함께 물어요.","그래야 이야기가 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#9','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',4,'essay','teacher','우리 동네에서 고유어를 활용한 이름을 하나 조사하려고 해요. 조사 대상 · 범위 · 방법을 정해 쓰고, 조사한 내용을 정리할 네 칸에 무엇을 적을지 쓰세요. 뜻을 확인하지 못하면 어떻게 말할지도 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C9","difficulty":4,"kind":"essay","stem":"우리 동네에서 고유어를 활용한 이름을 하나 조사하려고 해요. 조사 대상 · 범위 · 방법을 정해 쓰고, 조사한 내용을 정리할 네 칸에 무엇을 적을지 쓰세요. 뜻을 확인하지 못하면 어떻게 말할지도 쓰세요.","answer_guide":{"answer":"예: 조사 대상 — 가게 이름. 범위 — 학교에서 집까지 오는 길. 방법 — 국어사전에서 찾고 동네 어른께 여쭙기. 네 칸 — 유형(가게 이름) · 사례(실제 가게 이름) · 고유어(이름 속 고유어) · 고유어의 뜻(사전에서 확인한 뜻). 뜻을 찾지 못하면 지어내지 않고 「아직 확인하지 못했습니다」라고 말하고, 짐작한 것은 짐작했다고 밝힌다.","scoring_points":["대상 · 범위 · 방법을 알맞게 정했는가","네 칸을 바르게 썼는가","확인 · 짐작 · 모름을 가르는 방법을 썼는가"]},"explanation":["범위는 손이 닿는 곳으로.","네 칸으로 정리해요.","모르는 것은 모른다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L04_challenge#10','kor',6,2,'u4','L04','g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',4,'essay','teacher','「우리 동네 가게 이름 속 고유어」를 발표하려고 해요. 어떤 매체를 쓸지와 그 까닭을 쓰고, 발표 전에 점검할 세 가지와 듣는 사람이 할 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":4,"kind":"essay","stem":"「우리 동네 가게 이름 속 고유어」를 발표하려고 해요. 어떤 매체를 쓸지와 그 까닭을 쓰고, 발표 전에 점검할 세 가지와 듣는 사람이 할 일을 쓰세요.","answer_guide":{"answer":"예: 가게 이름 여러 개를 한눈에 견주도록 표를 쓰고, 가게의 실제 모습을 보여 주려고 사진을 함께 쓴다. 발표 전에 조사한 자료의 출처가 믿을 만한지, 자료의 양이 발표 시간에 알맞은지, 고른 매체가 발표에 도움이 되는지 점검한다. 듣는 사람은 발표 내용을 정리하며 듣고, 궁금한 점을 까닭과 함께 묻는다.","scoring_points":["알릴 내용에 맞는 매체와 까닭을 썼는가","점검할 세 가지를 썼는가","듣는 사람의 할 일을 썼는가"]},"explanation":["내용에 맞는 매체를 골라요.","출처 · 양 · 매체를 점검해요.","듣는 사람도 정리하고 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#1','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'mc','auto','「표준어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X06']::text[],false,'{"seq":1,"concept":"K6-2-u4-C13","difficulty":1,"kind":"mc","stem":"「표준어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"온 나라 사람이 두루 통하게 쓰도록 정한 말","correct":true},{"t":"어느 고장에서 주로 쓰는 말","mis":"K6-2-u4-X19"},{"t":"옛날에만 쓰던 말","mis":"K6-2-u4-X06"},{"t":"서울 사람만 쓰는 말","mis":"K6-2-u4-X19"}],"explanation":["표준어는 온 나라 사람이 함께 쓰도록 정한 말이에요.","책 · 방송 · 공공 안내에 주로 쓰여요.","고장에서 주로 쓰는 말은 방언이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#2','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'sa','auto','어느 고장에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C13","difficulty":1,"kind":"sa","stem":"어느 고장에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["방언"],"explanation":["표준어는 두루 통하게 정한 말이에요.","고장에서 주로 쓰는 말이 따로 있어요.","그 말을 방언이라고 해요."],"mis":"K6-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#3','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'ox','auto','방언은 고쳐야 할 틀린 말이에요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":3,"concept":"K6-2-u4-C13","difficulty":1,"kind":"ox","stem":"방언은 고쳐야 할 틀린 말이에요.","answer":"X","reason_options":[{"t":"그 고장의 정과 역사를 담은 소중한 우리말이고 쓰이는 자리가 다를 뿐이기 때문에","correct":true},{"t":"표준어만 진짜 우리말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["방언도 우리말이에요.","표준어와 쓰이는 자리가 다를 뿐이에요.","둘 사이에 등수는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#4','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',1,'mc','auto','「추론」에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":4,"concept":"K6-2-u4-C12","difficulty":1,"kind":"mc","stem":"「추론」에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에 적히지 않은 부분을 글의 단서와 내 경험 · 지식으로 메우는 일","correct":true},{"t":"글에 없는 일을 마음대로 상상하는 일","mis":"K6-2-u4-X16"},{"t":"글에 적힌 것을 그대로 옮겨 적는 일","mis":"K6-2-u4-X17"},{"t":"까닭 없이 그럴 것 같다고 말하는 일","mis":"K6-2-u4-X16"}],"explanation":["글쓴이는 모든 것을 다 적지 않아요.","적히지 않은 부분을 단서로 메워요.","까닭은 반드시 글 안에 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#5','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'mc','auto','할머니가 말한 「건사하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":5,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"할머니가 말한 「건사하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 잘 거두어 보호함","correct":true},{"t":"필요 없는 것을 골라 버림","mis":"K6-2-u4-X18"},{"t":"여러 사람에게 널리 알림","mis":"K6-2-u4-X18"},{"t":"새것으로 바꾸어 놓음","mis":"K6-2-u4-X18"}],"explanation":["「잘 건사해 두었으니 이만큼 남았지」라고 했어요.","오래된 공책이 남아 있었어요.","그러니 잘 거두어 보호했다는 뜻이에요."],"asset":{"type":"passage","lines":["「겨울마다 회관에 모여 앉아 한 사람이 한 낱말씩 적었단다.","같은 물건을 두고도 집집이 부르는 말이 달라서, 그때마다 둘 다 적어 두었지.」","「이 이름들은요?」 「그 말을 알려 준 사람이지.」","할머니는 「회관 아래 칸에 잘 건사해 두었으니 이만큼 남았지.」라고 덧붙이셨다.","「그런데 요즘은 이 말들을 쓰는 사람이 많이 줄었어.","젊은 사람들이 도시로 나가면서 말도 같이 나갔거든.」","할머니는 공책 뒤쪽 빈 장을 손바닥으로 가만히 쓸어 보이셨다.","그러고는 윤겸이를 한 번 바라보셨다."],"title":"마을 회관의 낡은 공책 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#6','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'mc','auto','글에 그대로 적혀 있는 것은 어느 것인가요?',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":6,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"글에 그대로 적혀 있는 것은 어느 것인가요?","options":[{"t":"공책 뒤쪽에는 아직 적히지 않은 장이 남아 있다","correct":true},{"t":"공책은 학교 숙제로 만든 것이다","mis":"K6-2-u4-X17"},{"t":"마을에서는 지금도 해마다 낱말을 적는다","mis":"K6-2-u4-X17"},{"t":"윤겸이는 공책을 이어 적기로 마음먹었다","mis":"K6-2-u4-X17"}],"explanation":["글에 적힌 것부터 정확히 붙잡아요.","빈 장이 남아 있었다는 것은 글에 있어요.","나머지는 글에 없는 내용이에요."],"asset":{"type":"passage","lines":["방학 동안 할머니 댁에 머물던 윤겸이는 마을 회관 책꽂이 맨 아래 칸에서","표지가 다 닳은 공책 한 권을 찾아냈다. 겉장에는 「우리 마을 말」이라고 적혀 있었다.","펼쳐 보니 낱말과 뜻이 줄줄이 적혀 있었다. 글씨체가 몇 가지나 되었다.","어떤 낱말 옆에는 이름과 날짜가 나란히 적혀 있었고,","어떤 낱말에는 두 가지 뜻이 나란히 적혀 있었다.","마지막 장을 펴 보니, 뒤쪽 여러 장이 아무것도 적히지 않은 채 남아 있었다."],"title":"마을 회관의 낡은 공책 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#7','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',2,'match','auto','표준어와 같은 뜻으로 쓰이는 고장 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":2,"kind":"match","stem":"표준어와 같은 뜻으로 쓰이는 고장 말을 알맞게 이으세요.","pairs":[{"l":"부엌","r":"정지"},{"l":"무","r":"무시"},{"l":"김치","r":"짐치"}],"mis":"K6-2-u4-X19","explanation":["같은 것을 다르게 부를 뿐이에요.","소리가 비슷하게 남은 말도 있어요.","둘 다 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#8','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C11',2,'mc','auto','우리말을 마음껏 쓰지 못하던 때에 어떤 노력이 있었나요?',ARRAY['K6-2-u4-X19','K6-2-u4-X15']::text[],false,'{"seq":8,"concept":"K6-2-u4-C11","difficulty":2,"kind":"mc","stem":"우리말을 마음껏 쓰지 못하던 때에 어떤 노력이 있었나요?","options":[{"t":"흩어진 낱말을 모아 우리말 사전을 만들려고 애썼다","correct":true},{"t":"표준어만 남기고 고장 말은 모두 지웠다","mis":"K6-2-u4-X19"},{"t":"외국어로 된 사전을 만들었다","mis":"K6-2-u4-X15"},{"t":"말은 저절로 남으니 아무것도 하지 않았다","mis":"K6-2-u4-X15"}],"explanation":["온 나라의 낱말을 모아 적었어요.","고장마다 다른 말도 함께 모았어요.","그 기록이 오늘 국어사전의 바탕이 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#9','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'ox','auto','추론한 내용은 사람마다 조금씩 다를 수 있어요.',ARRAY['K6-2-u4-X16']::text[],false,'{"seq":9,"concept":"K6-2-u4-C12","difficulty":2,"kind":"ox","stem":"추론한 내용은 사람마다 조금씩 다를 수 있어요.","answer":"O","reason_options":[{"t":"까닭이 글 안에 있다면 단서를 읽는 눈이 조금씩 다를 수 있기 때문에","correct":true},{"t":"추론은 아무렇게나 상상해도 되기 때문에","mis":"K6-2-u4-X16"}],"mis":"K6-2-u4-X16","explanation":["추론은 사람마다 조금씩 다를 수 있어요.","다만 까닭은 글 안에 있어야 해요.","다르면 서로 까닭을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_basic#10','kor',6,2,'u4','L06','g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',3,'error','auto','표준어와 방언에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":10,"concept":"K6-2-u4-C13","difficulty":3,"kind":"error","stem":"표준어와 방언에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민재 — 「할머니가 ‘정지’라고 하시면 ‘부엌’이라고 고쳐 드려야 해.」","correct":true,"mis_target":"K6-2-u4-X19"},{"t":"소율 — 「발표처럼 공식적인 자리에서는 표준어로 말해.」","mis":"K6-2-u4-X20"},{"t":"지오 — 「고장 말을 찾을 때는 어느 고장 말인지도 함께 살펴봐.」","mis":"K6-2-u4-X19"}],"explanation":["소율과 지오는 상황과 고장을 살폈어요.","민재는 방언을 고쳐야 할 말로 여겼어요.","고장 사람과는 고장 말로 이야기해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#1','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',2,'sa','auto','추론할 때 인물의 말과 행동, 일이 일어난 때와 곳처럼 글에서 찾는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C12","difficulty":2,"kind":"sa","stem":"추론할 때 인물의 말과 행동, 일이 일어난 때와 곳처럼 글에서 찾는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["단서"],"explanation":["추론은 글에서 실마리를 찾는 데서 시작해요.","인물의 말과 행동, 때와 곳이 실마리예요.","그 실마리를 단서라고 해요."],"mis":"K6-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#2','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',2,'mc','auto','표준어가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":2,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"표준어가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"사는 곳이 달라도 서로 통하게 해 준다","correct":true},{"t":"그 고장의 정과 역사를 담아 전한다","mis":"K6-2-u4-X19"},{"t":"고장 말을 없애 준다","mis":"K6-2-u4-X19"},{"t":"어디에서나 한 가지 말만 쓰게 한다","mis":"K6-2-u4-X20"}],"explanation":["표준어는 두루 통하게 해 줘요.","고장의 정과 역사를 담는 것은 방언이에요.","둘은 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#3','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'mc','auto','할머니가 공책 뒤쪽 빈 장을 쓸어 보이신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16']::text[],false,'{"seq":3,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"할머니가 공책 뒤쪽 빈 장을 쓸어 보이신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"윤겸이가 이어서 적어 주기를 바라셨을 것이다","correct":true},{"t":"공책에 쌓인 먼지를 털어 내려 하셨을 것이다","mis":"K6-2-u4-X16"},{"t":"남은 장을 뜯어 내려고 세어 보셨을 것이다","mis":"K6-2-u4-X16"},{"t":"공책을 버리려고 마지막으로 보셨을 것이다","mis":"K6-2-u4-X16"}],"explanation":["앞에서 쓰는 사람이 줄었다고 하셨어요.","빈 장을 쓸어 보이신 뒤 윤겸이를 바라보셨어요.","말과 행동과 시선이 같은 곳을 가리켜요."],"asset":{"type":"passage","lines":["「겨울마다 회관에 모여 앉아 한 사람이 한 낱말씩 적었단다.","같은 물건을 두고도 집집이 부르는 말이 달라서, 그때마다 둘 다 적어 두었지.」","「이 이름들은요?」 「그 말을 알려 준 사람이지.」","할머니는 「회관 아래 칸에 잘 건사해 두었으니 이만큼 남았지.」라고 덧붙이셨다.","「그런데 요즘은 이 말들을 쓰는 사람이 많이 줄었어.","젊은 사람들이 도시로 나가면서 말도 같이 나갔거든.」","할머니는 공책 뒤쪽 빈 장을 손바닥으로 가만히 쓸어 보이셨다.","그러고는 윤겸이를 한 번 바라보셨다."],"title":"마을 회관의 낡은 공책 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#4','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'mc','auto','「글씨체가 몇 가지나 되었다」를 단서로 추론할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":4,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"「글씨체가 몇 가지나 되었다」를 단서로 추론할 수 있는 것은 어느 것인가요?","options":[{"t":"여러 사람이 함께 적었을 것이다","correct":true},{"t":"공책을 산 가게가 여러 곳이었을 것이다","mis":"K6-2-u4-X16"},{"t":"글씨를 잘 쓰는 사람이 없었을 것이다","mis":"K6-2-u4-X16"},{"t":"공책이 아주 새것일 것이다","mis":"K6-2-u4-X17"}],"explanation":["글씨체가 여럿이면 쓴 사람이 여럿이에요.","뒷부분에서 한 사람이 한 낱말씩 적었다고 해요.","단서와 추론이 맞아떨어져요."],"asset":{"type":"passage","lines":["방학 동안 할머니 댁에 머물던 윤겸이는 마을 회관 책꽂이 맨 아래 칸에서","표지가 다 닳은 공책 한 권을 찾아냈다. 겉장에는 「우리 마을 말」이라고 적혀 있었다.","펼쳐 보니 낱말과 뜻이 줄줄이 적혀 있었다. 글씨체가 몇 가지나 되었다.","어떤 낱말 옆에는 이름과 날짜가 나란히 적혀 있었고,","어떤 낱말에는 두 가지 뜻이 나란히 적혀 있었다.","마지막 장을 펴 보니, 뒤쪽 여러 장이 아무것도 적히지 않은 채 남아 있었다."],"title":"마을 회관의 낡은 공책 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#5','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C11',3,'ox','auto','말은 쓰는 사람이 있으면 저절로 남으니 적어 둘 필요가 없어요.',ARRAY['K6-2-u4-X15']::text[],false,'{"seq":5,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"말은 쓰는 사람이 있으면 저절로 남으니 적어 둘 필요가 없어요.","answer":"X","reason_options":[{"t":"쓰는 사람이 줄면 사라질 수 있어 누군가 적어 두고 이어 주어야 남기 때문에","correct":true},{"t":"말은 한번 생기면 사라지지 않기 때문에","mis":"K6-2-u4-X15"}],"mis":"K6-2-u4-X15","explanation":["말은 저절로 남지 않아요.","쓰는 사람이 줄면 사라질 수 있어요.","적어 두고 이어 준 덕분에 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#6','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'match','auto','글에서 찾은 단서와 추론한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C12","difficulty":3,"kind":"match","stem":"글에서 찾은 단서와 추론한 내용을 알맞게 이으세요.","pairs":[{"l":"글씨체가 여러 가지다","r":"여러 사람이 함께 적었다"},{"l":"한 낱말에 두 가지 뜻이 나란히 적혀 있다","r":"집집이 다르게 쓰는 말을 있는 그대로 남겼다"},{"l":"쓰는 사람이 많이 줄었다고 하셨다","r":"적어 두지 않으면 사라질 수도 있었다"}],"mis":"K6-2-u4-X16","explanation":["단서마다 알 수 있는 것이 달라요.","그 단서 하나로 알 수 있는 것을 골라요.","까닭은 늘 글 안에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#7','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'error','auto','「마을 회관의 낡은 공책」을 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":7,"concept":"K6-2-u4-C12","difficulty":3,"kind":"error","stem":"「마을 회관의 낡은 공책」을 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?","options":[{"t":"라희 — 「할머니는 공책이 싫어서 빈 장을 쓸어 보셨을 거야. 그냥 그럴 것 같아.」","correct":true,"mis_target":"K6-2-u4-X16"},{"t":"건우 — 「쓰는 사람이 줄었다는 말 뒤에 윤겸이를 바라보셨으니 이어 적기를 바라셨을 거야.」","mis":"K6-2-u4-X16"},{"t":"다은 — 「이름 옆에 날짜가 있으니 알려 준 사람과 때를 남겼을 거야.」","mis":"K6-2-u4-X17"}],"explanation":["건우와 다은은 글에서 단서를 찾았어요.","라희는 까닭을 글에서 찾지 않았어요.","추론은 마음대로 지어내는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#8','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',4,'mc','auto','우리말을 상황에 맞게 쓴 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X20','K6-2-u4-X19']::text[],false,'{"seq":8,"concept":"K6-2-u4-C13","difficulty":4,"kind":"mc","stem":"우리말을 상황에 맞게 쓴 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학급 회의 사회를 볼 때는 표준어로, 할머니 댁 이웃 어른들과 이야기할 때는 그 고장 말로 이야기한다","correct":true},{"t":"어디에서든 표준어만 쓴다","mis":"K6-2-u4-X20"},{"t":"어디에서든 고장 말만 쓴다","mis":"K6-2-u4-X20"},{"t":"고장 말을 쓰는 친구를 따라 하며 웃는다","mis":"K6-2-u4-X19"}],"explanation":["공식적인 자리에서는 표준어로 말해요.","고장 사람과는 고장 말로 정답게 말해요.","자리에 맞게 골라 쓰는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#9','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',4,'essay','teacher','할머니가 공책 뒤쪽 빈 장을 쓸어 보이고 윤겸이를 바라보신 까닭을 추론해 쓰세요. 그렇게 추론한 단서를 글에서 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C12","difficulty":4,"kind":"essay","stem":"할머니가 공책 뒤쪽 빈 장을 쓸어 보이고 윤겸이를 바라보신 까닭을 추론해 쓰세요. 그렇게 추론한 단서를 글에서 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 할머니는 윤겸이가 마을 말을 이어서 적어 주기를 바라셨을 것이다. 단서 — 할머니가 요즘은 이 말들을 쓰는 사람이 많이 줄었다고 하셨다. 공책 뒤쪽 빈 장을 쓸어 보이신 뒤 윤겸이를 바라보셨다. 쓰는 사람이 줄어 사라질 수 있는 말을 빈 장에 이어 적어 주기를 바라신 것이다.","scoring_points":["할머니의 마음을 알맞게 추론했는가","글에서 단서를 두 가지 찾았는가","단서와 추론을 이어 설명했는가"]},"explanation":["말 · 행동 · 시선을 이어 봐요.","까닭은 글 안에서 찾아요.","적힌 것과 메운 생각을 갈라 써요."],"asset":{"type":"passage","lines":["「겨울마다 회관에 모여 앉아 한 사람이 한 낱말씩 적었단다.","같은 물건을 두고도 집집이 부르는 말이 달라서, 그때마다 둘 다 적어 두었지.」","「이 이름들은요?」 「그 말을 알려 준 사람이지.」","할머니는 「회관 아래 칸에 잘 건사해 두었으니 이만큼 남았지.」라고 덧붙이셨다.","「그런데 요즘은 이 말들을 쓰는 사람이 많이 줄었어.","젊은 사람들이 도시로 나가면서 말도 같이 나갔거든.」","할머니는 공책 뒤쪽 빈 장을 손바닥으로 가만히 쓸어 보이셨다.","그러고는 윤겸이를 한 번 바라보셨다."],"title":"마을 회관의 낡은 공책 (뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L06_challenge#10','kor',6,2,'u4','L06','g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',4,'essay','teacher','표준어와 방언이 각각 하는 일을 쓰고, 방언이 고쳐야 할 틀린 말이 아닌 까닭을 쓰세요. 그리고 우리말을 지키기 위해 내가 할 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C13","difficulty":4,"kind":"essay","stem":"표준어와 방언이 각각 하는 일을 쓰고, 방언이 고쳐야 할 틀린 말이 아닌 까닭을 쓰세요. 그리고 우리말을 지키기 위해 내가 할 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 표준어는 사는 곳이 달라도 서로 통하게 해 주고, 방언은 그 고장의 정과 역사를 담아 전해 준다. 방언은 쓰이는 자리가 다를 뿐 표준어처럼 소중한 우리말이므로 틀린 말이 아니다. 내가 할 수 있는 일 — 할머니께 고장 말을 여쭈어 적어 두기, 다른 고장의 말을 웃음거리로 삼지 않기.","scoring_points":["표준어와 방언이 하는 일을 각각 썼는가","방언이 틀린 말이 아닌 까닭을 썼는가","실천할 수 있는 일을 두 가지 썼는가"]},"explanation":["표준어는 두루 통하게, 방언은 정과 역사를.","둘 사이에 등수는 없어요.","여쭈어 적기, 웃음거리로 삼지 않기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#1','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',1,'mc','auto','언어생활 점검표를 만드는 목적은 무엇인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":1,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"언어생활 점검표를 만드는 목적은 무엇인가요?","options":[{"t":"우리 반의 말버릇을 살펴 함께 고치려고","correct":true},{"t":"말을 가장 바르게 쓰는 사람을 뽑으려고","mis":"K6-2-u4-X21"},{"t":"말을 함부로 쓰는 친구를 가려내려고","mis":"K6-2-u4-X21"},{"t":"누가 더 많이 썼는지 세어 견주려고","mis":"K6-2-u4-X21"}],"explanation":["점검은 고치기 위한 것이에요.","누구를 뽑거나 가려내려는 것이 아니에요.","우리 반이 함께 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#2','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',1,'sa','auto','실천 다짐문에서 무엇을 위해 다짐하는지 밝히는 부분을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C15","difficulty":1,"kind":"sa","stem":"실천 다짐문에서 무엇을 위해 다짐하는지 밝히는 부분을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["목적"],"explanation":["다짐문에는 네 부분이 들어가요.","맨 앞에서 무엇을 위해 다짐하는지 밝혀요.","그 부분이 목적이에요."],"mis":"K6-2-u4-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#3','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',1,'ox','auto','언어생활을 점검할 때는 먼저 내가 쓴 말부터 적어요.',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":3,"concept":"K6-2-u4-C14","difficulty":1,"kind":"ox","stem":"언어생활을 점검할 때는 먼저 내가 쓴 말부터 적어요.","answer":"O","reason_options":[{"t":"점검은 친구를 흠잡는 일이 아니라 우리 반이 함께 고치려는 일이기 때문에","correct":true},{"t":"내가 쓴 말이 가장 바르기 때문에","mis":"K6-2-u4-X21"}],"mis":"K6-2-u4-X21","explanation":["점검은 흠잡기가 아니에요.","먼저 내가 쓴 말부터 적어요.","고칠 점은 우리 반의 일로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#4','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',1,'mc','auto','지킬 수 있는 다짐으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":4,"concept":"K6-2-u4-C15","difficulty":1,"kind":"mc","stem":"지킬 수 있는 다짐으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠 활동에서 친구가 못 알아듣는 말을 쓰면 바로 풀어 말하겠습니다","correct":true},{"t":"앞으로 우리말을 아주 열심히 사랑하겠습니다","mis":"K6-2-u4-X23"},{"t":"오늘부터 한자어와 외래어를 하나도 쓰지 않겠습니다","mis":"K6-2-u4-X23"},{"t":"다들 바른 말을 쓰도록 합시다","mis":"K6-2-u4-X23"}],"explanation":["언제 무엇을 할지 드러나야 지킬 수 있어요.","「열심히」는 무엇을 할지 없어요.","「하나도」는 지킬 수 없는 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#5','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','알림장 · 안내문처럼 여러 사람에게 전하는 글을 쉬운 우리말로 써야 하는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X03']::text[],false,'{"seq":5,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"알림장 · 안내문처럼 여러 사람에게 전하는 글을 쉬운 우리말로 써야 하는 까닭은 어느 것인가요?","options":[{"t":"나이가 많은 분, 우리말을 배우는 중인 분까지 모두 읽는 글이라서","correct":true},{"t":"짧게 써야 종이를 아낄 수 있어서","mis":"K6-2-u4-X08"},{"t":"외국어는 모두 틀린 말이라서","mis":"K6-2-u4-X02"},{"t":"어려운 말을 쓰면 글쓴이가 혼나서","mis":"K6-2-u4-X03"}],"explanation":["여러 사람에게 전하는 글은 누구나 읽어요.","누구나 알아들을 수 있어야 해요.","그래서 쉬운 우리말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#6','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'match','auto','실천 다짐문의 부분과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C15","difficulty":2,"kind":"match","stem":"실천 다짐문의 부분과 하는 일을 알맞게 이으세요.","pairs":[{"l":"목적","r":"무엇을 위해 다짐하는지 밝혀 준다"},{"l":"구체적인 실천 약속","r":"언제 · 어디에서 · 무엇을 할지 알려 준다"},{"l":"전하고 싶은 말","r":"함께 하자고 부탁한다"},{"l":"날짜와 쓴 사람","r":"누가 언제 한 약속인지 남겨 준다"}],"mis":"K6-2-u4-X22","explanation":["목적은 왜, 실천 약속은 무엇을이에요.","전하고 싶은 말은 함께 하자는 부탁이에요.","날짜와 쓴 사람은 마지막에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#7','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','안내문의 말이 통하지 않을 때 실제로 생기는 일은 어느 것인가요?',ARRAY['K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":7,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"안내문의 말이 통하지 않을 때 실제로 생기는 일은 어느 것인가요?","options":[{"t":"필요한 도움을 받지 못하고 지나친다","correct":true},{"t":"글을 읽는 속도가 빨라진다","mis":"K6-2-u4-X04"},{"t":"낱말의 뜻이 저절로 바뀐다","mis":"K6-2-u4-X04"},{"t":"모두 그 말을 금방 배우게 된다","mis":"K6-2-u4-X03"}],"explanation":["안내문을 읽고도 무엇을 할지 몰라요.","되묻기를 부끄러워할 수도 있어요.","그래서 필요한 도움을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#8','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'mc','auto','다인이의 다짐문에 빠진 부분은 어느 것인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":8,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"다인이의 다짐문에 빠진 부분은 어느 것인가요?","options":[{"t":"날짜와 쓴 사람","correct":true},{"t":"목적","mis":"K6-2-u4-X22"},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"전하고 싶은 말","mis":"K6-2-u4-X22"}],"explanation":["둘째 줄에 목적이 있어요.","「하나,」 세 줄이 실천 약속, 마지막 줄이 전하고 싶은 말이에요.","누가 언제 쓴 약속인지가 빠졌어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 우리말을 아끼고 바르게 쓰기 위해 다음과 같이 다짐합니다.","하나, 모둠 활동에서 친구가 알아듣지 못하는 말을 쓰면 바로 풀어서 다시 말하겠습니다.","하나, 알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다.","하나, 다른 고장의 말을 웃음거리로 삼지 않겠습니다.","친구들도 모르는 말은 되묻고, 어려운 말은 풀어 말해 주세요."],"title":"다인이가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#9','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'ox','auto','「다들 줄인 말을 쓰지 맙시다」는 좋은 실천 약속이에요.',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":9,"concept":"K6-2-u4-C15","difficulty":2,"kind":"ox","stem":"「다들 줄인 말을 쓰지 맙시다」는 좋은 실천 약속이에요.","answer":"X","reason_options":[{"t":"내가 할 일이 드러나지 않아 지키는 사람이 없기 때문에","correct":true},{"t":"여러 사람에게 하는 약속일수록 잘 지켜지기 때문에","mis":"K6-2-u4-X23"}],"mis":"K6-2-u4-X23","explanation":["실천 약속은 내가 할 일이어야 해요.","「다들」에는 내가 할 일이 없어요.","「나는 ~하겠습니다」로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_basic#10','kor',6,2,'u4','L08','g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',3,'error','auto','친구의 다짐문을 읽고 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X23','K6-2-u4-X22']::text[],false,'{"seq":10,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"친구의 다짐문을 읽고 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"규리 — 「글씨가 반듯하지 않으니 그것부터 고치자.」","correct":true,"mis_target":"K6-2-u4-X24"},{"t":"하진 — 「언제 무엇을 할지가 드러나지 않으니 넣어 보자.」","mis":"K6-2-u4-X23"},{"t":"세나 — 「왜 그렇게 다짐하는지 목적을 덧붙이자.」","mis":"K6-2-u4-X22"}],"explanation":["고칠 점은 내용에서 찾아요.","하진과 세나는 다짐문이 하는 일을 살폈어요.","규리는 겉모습을 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#1','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',2,'sa','auto','아는 사람끼리만 통하는 말은 「지나치게 ○○ 말」이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C14","difficulty":2,"kind":"sa","stem":"아는 사람끼리만 통하는 말은 「지나치게 ○○ 말」이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["줄인"],"explanation":["말을 짧게 줄이면 편해 보여요.","그러나 아는 사람끼리만 통해요.","그래서 지나치게 줄인 말을 점검해요."],"mis":"K6-2-u4-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#2','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',2,'mc','auto','모은 것을 우리 반의 실태로 정리할 때 넣지 않는 것은 어느 것인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":2,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"모은 것을 우리 반의 실태로 정리할 때 넣지 않는 것은 어느 것인가요?","options":[{"t":"말을 가장 많이 틀린 친구의 이름","correct":true},{"t":"많이 쓰는 외국어 표현","mis":"K6-2-u4-X21"},{"t":"많이 쓰는 줄인 말","mis":"K6-2-u4-X21"},{"t":"바꿀 수 있는 쉬운 우리말","mis":"K6-2-u4-X21"}],"explanation":["실태는 우리 반의 모습이에요.","외국어 표현 · 줄인 말 · 어려웠던 말 · 바꿀 말을 정리해요.","친구 이름은 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#3','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'mc','auto','다인이의 다짐 「알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다」가 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X23','K6-2-u4-X24']::text[],false,'{"seq":3,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"다인이의 다짐 「알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다」가 좋은 까닭은 어느 것인가요?","options":[{"t":"언제 무엇을 할지 드러나 지킬 수 있어서","correct":true},{"t":"크고 멋진 다짐이라서","mis":"K6-2-u4-X23"},{"t":"다른 사람이 할 일을 정해 주어서","mis":"K6-2-u4-X23"},{"t":"글자 수가 많아서","mis":"K6-2-u4-X24"}],"explanation":["「알림장을 쓸 때」가 언제예요.","「바꿀 수 있는 말은 바꾸어 쓰기」가 무엇이에요.","그래서 지킬 수 있어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 우리말을 아끼고 바르게 쓰기 위해 다음과 같이 다짐합니다.","하나, 모둠 활동에서 친구가 알아듣지 못하는 말을 쓰면 바로 풀어서 다시 말하겠습니다.","하나, 알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말은 바꾸어 쓰겠습니다.","하나, 다른 고장의 말을 웃음거리로 삼지 않겠습니다.","친구들도 모르는 말은 되묻고, 어려운 말은 풀어 말해 주세요."],"title":"다인이가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#4','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'mc','auto','친구의 다짐문을 읽고 말해 주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X24']::text[],false,'{"seq":4,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"친구의 다짐문을 읽고 말해 주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘 쓴 부분을 먼저 말하고, 고칠 점은 내용에서 찾아 바꾸어 볼 문장과 함께 말한다","correct":true},{"t":"고칠 점만 빠짐없이 말한다","mis":"K6-2-u4-X24"},{"t":"글씨와 종이 색부터 말한다","mis":"K6-2-u4-X24"},{"t":"잘 쓴 부분만 말하고 고칠 점은 말하지 않는다","mis":"K6-2-u4-X24"}],"explanation":["잘 쓴 부분 먼저예요.","고칠 점은 내용에서 찾아요.","바꾸어 볼 문장도 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#5','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',3,'ox','auto','점검표를 친구가 잘못 쓴 말의 증거로 내밀어도 돼요.',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":5,"concept":"K6-2-u4-C14","difficulty":3,"kind":"ox","stem":"점검표를 친구가 잘못 쓴 말의 증거로 내밀어도 돼요.","answer":"X","reason_options":[{"t":"점검은 흠잡기가 아니라 우리 반이 함께 고치려는 일이기 때문에","correct":true},{"t":"증거가 있어야 친구가 말을 고치기 때문에","mis":"K6-2-u4-X21"}],"mis":"K6-2-u4-X21","explanation":["점검표는 증거가 아니에요.","함께 고치려고 만든 표예요.","바라는 점을 함께 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#6','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'match','auto','지키기 어려운 다짐과 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C15","difficulty":3,"kind":"match","stem":"지키기 어려운 다짐과 그 까닭을 알맞게 이으세요.","pairs":[{"l":"「앞으로 열심히 하겠다」","r":"무엇을 할지가 없다"},{"l":"「하나도 쓰지 않겠다」","r":"지킬 수 없을 만큼 크다"},{"l":"「다들 그렇게 하자」","r":"내가 할 일이 없다"}],"mis":"K6-2-u4-X23","explanation":["무엇을 할지 있어야 해요.","지킬 수 있는 크기여야 해요.","내가 할 일이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#7','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'error','auto','완성한 다짐문을 나누는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":7,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"완성한 다짐문을 나누는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태민 — 「다짐문은 써서 서랍에 넣어 두면 끝이야.」","correct":true,"mis_target":"K6-2-u4-X26"},{"t":"아린 — 「학급 알림판에 붙여 오가며 보자.」","mis":"K6-2-u4-X26"},{"t":"정우 — 「다짐문 아래에 이름을 적어 함께 약속하자.」","mis":"K6-2-u4-X26"}],"explanation":["여러 사람과 나눌수록 다짐이 생활로 옮겨져요.","아린과 정우는 나누는 방법을 말했어요.","서랍에 넣으면 다짐이 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#8','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',4,'mc','auto','실천한 뒤 스스로 되돌아본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X21','K6-2-u4-X23']::text[],false,'{"seq":8,"concept":"K6-2-u4-C14","difficulty":4,"kind":"mc","stem":"실천한 뒤 스스로 되돌아본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「알아듣기 쉬운 말로 바꾸어 말한 적이 있었지만 줄인 말을 쓰는 버릇은 남았다. 내일 모둠 활동에서 한 번 더 풀어 말해 보겠다.」","correct":true},{"t":"「한 번 했으니 다 바뀌었다.」","mis":"K6-2-u4-X26"},{"t":"「우리 반에서 줄인 말을 가장 많이 쓴 사람은 내 짝이다.」","mis":"K6-2-u4-X21"},{"t":"「잘 모르겠지만 열심히 했다.」","mis":"K6-2-u4-X23"}],"explanation":["변화한 점과 노력할 점을 함께 봐요.","내일 한 번 더 해 볼 일을 정해요.","되돌아보고 다시 해 보는 것까지가 학습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#9','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',4,'essay','teacher','우리말을 바르게 쓰기 위한 실천 다짐문을 네 부분을 모두 갖추어 쓰세요. 실천 약속은 언제 · 어디에서 · 무엇을 할지 드러나게 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C15","difficulty":4,"kind":"essay","stem":"우리말을 바르게 쓰기 위한 실천 다짐문을 네 부분을 모두 갖추어 쓰세요. 실천 약속은 언제 · 어디에서 · 무엇을 할지 드러나게 두 가지 쓰세요.","answer_guide":{"answer":"예: 목적 — 나는 우리 반 친구들이 서로의 말을 잘 알아들을 수 있도록 다음과 같이 다짐합니다. 실천 약속 — 하나, 나는 모둠 활동에서 줄인 말을 쓰면 바로 풀어서 다시 말하겠습니다. 하나, 나는 학급 알림판에 글을 쓸 때 어려운 외국어를 쉬운 우리말로 바꾸어 쓰겠습니다. 전하고 싶은 말 — 친구들도 모르는 말은 부끄러워하지 말고 되물어 주세요. 날짜와 쓴 사람 — 시월 셋째 주 월요일, 김하늘.","scoring_points":["목적 · 실천 약속 · 전하고 싶은 말 · 날짜와 쓴 사람을 갖추었는가","실천 약속에 언제 · 어디에서 · 무엇을이 드러나는가","내가 지킬 수 있는 크기의 다짐인가"]},"explanation":["네 부분을 빠뜨리지 않아요.","언제 · 어디에서 · 무엇을.","크게 말하기보다 지킬 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L08_challenge#10','kor',6,2,'u4','L08','g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',4,'essay','teacher','언어생활 점검이 친구를 흠잡는 일이 아닌 까닭을 쓰고, 점검할 때 해야 할 일을 세 가지 쓰세요. 그리고 점검한 것을 우리 반의 실태로 정리할 때 어떤 내용을 넣을지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C14","difficulty":4,"kind":"essay","stem":"언어생활 점검이 친구를 흠잡는 일이 아닌 까닭을 쓰고, 점검할 때 해야 할 일을 세 가지 쓰세요. 그리고 점검한 것을 우리 반의 실태로 정리할 때 어떤 내용을 넣을지 두 가지 쓰세요.","answer_guide":{"answer":"예: 점검은 우리 반의 말버릇을 살펴 함께 고치려는 일이므로 친구를 흠잡는 일이 아니다. 점검할 때는 먼저 내가 쓴 말부터 적고, 고칠 점을 우리 반의 일로 말하고, 바라는 점을 함께 이야기한다. 실태에는 많이 쓰는 줄인 말과, 그 말을 바꿀 수 있는 쉬운 우리말을 넣는다.","scoring_points":["점검의 목적을 바르게 썼는가","점검할 때 할 일 세 가지를 썼는가","실태로 정리할 내용을 두 가지 썼는가"]},"explanation":["점검은 고치려고 해요.","내가 쓴 말부터, 우리 반의 일로.","친구 이름은 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#1','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'mc','auto','고유어의 뜻을 하나씩 알려 주고 싶을 때 알맞은 활동 방법은 어느 것인가요?',ARRAY['K6-2-u4-X27']::text[],false,'{"seq":1,"concept":"K6-2-u4-C16","difficulty":1,"kind":"mc","stem":"고유어의 뜻을 하나씩 알려 주고 싶을 때 알맞은 활동 방법은 어느 것인가요?","options":[{"t":"복도 알림판에 낱말을 하나씩 붙이는 인쇄물","correct":true},{"t":"한 번만 틀고 마는 짧은 알림 영상","mis":"K6-2-u4-X27"},{"t":"가사 없이 소리만 나오는 배경 음악","mis":"K6-2-u4-X27"},{"t":"말로 한 번 알려 주고 끝내기","mis":"K6-2-u4-X27"}],"explanation":["낱말은 한 번 보고 외워지지 않아요.","여러 번 마주쳐야 해요.","붙여 두는 인쇄물이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#2','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'sa','auto','우리말 지킴이 활동을 계획할 때 주제 · 내용 · 역할 · ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C16","difficulty":1,"kind":"sa","stem":"우리말 지킴이 활동을 계획할 때 주제 · 내용 · 역할 · ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["시간"],"explanation":["무엇을 알릴지가 주제예요.","누가 무엇을 맡을지가 역할이에요.","언제까지 만들고 보여 줄지가 시간이에요."],"mis":"K6-2-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#3','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'ox','auto','우리말을 알리는 홍보물에는 어려운 외국어를 넣어야 눈에 띄어요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":3,"concept":"K6-2-u4-C16","difficulty":1,"kind":"ox","stem":"우리말을 알리는 홍보물에는 어려운 외국어를 넣어야 눈에 띄어요.","answer":"X","reason_options":[{"t":"알리려는 우리말과 앞뒤가 맞지 않고 읽는 사람이 알아듣기 어렵기 때문에","correct":true},{"t":"눈에 띄는 것이 알아듣는 것보다 중요하기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["우리말을 알리는 홍보물이에요.","문구가 어려우면 앞뒤가 맞지 않아요.","읽는 사람이 알아들을 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#4','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C17',1,'mc','auto','「증발」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":4,"concept":"K6-2-u4-C17","difficulty":1,"kind":"mc","stem":"「증발」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"액체가 그 표면에서 기체로 변하는 현상","correct":true},{"t":"땅의 생긴 모양","mis":"K6-2-u4-X28"},{"t":"일정한 범위에 흩어져 퍼져 있음","mis":"K6-2-u4-X28"},{"t":"자연 현상을 살펴 재거나 헤아리는 일","mis":"K6-2-u4-X28"}],"explanation":["땅의 생긴 모양은 지형이에요.","흩어져 퍼져 있음은 분포예요.","살펴 재거나 헤아리는 일은 관측이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#5','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'mc','auto','두 홍보 문구 가운데 더 알맞은 것과 그 까닭으로 바른 것은 어느 것인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":5,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"두 홍보 문구 가운데 더 알맞은 것과 그 까닭으로 바른 것은 어느 것인가요?","options":[{"t":"두 번째 — 읽는 사람이 무엇을 하면 되는지 바로 알 수 있어서","correct":true},{"t":"첫 번째 — 외국어가 섞여 멋있어서","mis":"K6-2-u4-X25"},{"t":"첫 번째 — 글자 수가 적어서","mis":"K6-2-u4-X25"},{"t":"두 번째 — 물음표가 있어서","mis":"K6-2-u4-X25"}],"explanation":["첫 번째 문구는 우리말을 알리면서 정작 어려워요.","두 번째 문구는 할 일이 보여요.","물음표 때문이 아니라 내용 때문이에요."],"asset":{"type":"passage","lines":["첫 번째 문구 — 「우리말 클린 데이에 조인해 주세요!」","두 번째 문구 — 「오늘 한 번, 쉬운 우리말로 바꾸어 말해 볼까요?」"],"title":"우리말 홍보 문구 두 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#6','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'match','auto','활동 방법과 그 방법이 잘 살리는 점을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C16","difficulty":2,"kind":"match","stem":"활동 방법과 그 방법이 잘 살리는 점을 이으세요.","pairs":[{"l":"알림 영상","r":"움직임과 목소리를 함께 전할 수 있다"},{"l":"인쇄물","r":"한자리에 붙여 두고 여러 번 보게 할 수 있다"},{"l":"만화","r":"짧은 이야기로 쉽게 이해시킬 수 있다"}],"mis":"K6-2-u4-X27","explanation":["영상은 움직임과 목소리예요.","인쇄물은 오래 붙여 두기예요.","만화는 짧은 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#7','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'mc','auto','우리말 홍보물에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"우리말 홍보물에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"보는 사람이 오늘 해 볼 수 있는 행동","correct":true},{"t":"말을 잘못 쓴 친구의 이름","mis":"K6-2-u4-X25"},{"t":"우리 모둠이 얼마나 애썼는지 적은 내용","mis":"K6-2-u4-X25"},{"t":"알릴 내용을 가리는 꾸밈 그림","mis":"K6-2-u4-X13"}],"explanation":["보는 사람이 무엇을 알게 될지 생각해요.","무엇을 하게 될지도 생각해요.","누구를 탓하거나 자랑하는 내용은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#8','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C17',2,'match','auto','교과 학습에 자주 나오는 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C17","difficulty":2,"kind":"match","stem":"교과 학습에 자주 나오는 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"지형","r":"땅의 생긴 모양"},{"l":"분포","r":"일정한 범위에 흩어져 퍼져 있음"},{"l":"관측","r":"자연 현상을 살펴 재거나 헤아리는 일"}],"mis":"K6-2-u4-X28","explanation":["지형은 사회 · 과학에서 자주 만나요.","분포는 흩어져 퍼진 모습이에요.","관측은 살펴 재는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#9','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'ox','auto','홍보물을 만든 날에만 우리말을 아껴도 실천했다고 할 수 있어요.',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":9,"concept":"K6-2-u4-C16","difficulty":2,"kind":"ox","stem":"홍보물을 만든 날에만 우리말을 아껴도 실천했다고 할 수 있어요.","answer":"X","reason_options":[{"t":"하루로 끝나면 행사일 뿐이고 이어서 해야 실천이 되기 때문에","correct":true},{"t":"홍보물을 만드는 일이 실천의 전부이기 때문에","mis":"K6-2-u4-X26"}],"mis":"K6-2-u4-X26","explanation":["하루로 끝나면 다짐이 남지 않아요.","우리말 일기 · 지킴이 도전처럼 이어서 해요.","그래야 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_basic#10','kor',6,2,'u4','L11','g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',3,'error','auto','우리말 지킴이 활동을 계획하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":10,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"우리말 지킴이 활동을 계획하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서준 — 「역할은 만들면서 정하고, 꾸미기부터 시작하자.」","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"이서 — 「역할을 먼저 나누어 빠지는 사람이 없게 하자.」","mis":"K6-2-u4-X25"},{"t":"하준 — 「언제까지 만들고 언제 보여 줄지 정하자.」","mis":"K6-2-u4-X25"}],"explanation":["계획은 주제 · 내용 · 역할 · 시간이에요.","이서와 하준은 계획을 먼저 세웠어요.","서준은 꾸밈을 앞세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#1','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',2,'sa','auto','「땅의 생긴 모양」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C17","difficulty":2,"kind":"sa","stem":"「땅의 생긴 모양」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["지형"],"explanation":["교과서에서 자주 만나는 한자어예요.","「이 고장은 지형이 험하다」처럼 써요.","정답은 지형이에요."],"mis":"K6-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#2','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',2,'mc','auto','하루에 한 낱말씩 새로 안 우리말을 적는 활동은 어느 것인가요?',ARRAY['K6-2-u4-X27']::text[],false,'{"seq":2,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하루에 한 낱말씩 새로 안 우리말을 적는 활동은 어느 것인가요?","options":[{"t":"우리말 일기","correct":true},{"t":"지킴이 도전","mis":"K6-2-u4-X27"},{"t":"교실 말 고치기","mis":"K6-2-u4-X27"},{"t":"알림 영상","mis":"K6-2-u4-X27"}],"explanation":["지킴이 도전은 한 주 동안 다짐 하나 지키기예요.","교실 말 고치기는 알림 글부터 바꾸기예요.","한 낱말씩 적는 것은 우리말 일기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#3','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'mc','auto','고유어로 지은 가게 이름이 많다는 것을 짧은 이야기로 동생들에게 쉽게 알리고 싶어요. 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X13']::text[],false,'{"seq":3,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"고유어로 지은 가게 이름이 많다는 것을 짧은 이야기로 동생들에게 쉽게 알리고 싶어요. 알맞은 방법은 어느 것인가요?","options":[{"t":"만화","correct":true},{"t":"표","mis":"K6-2-u4-X27"},{"t":"글자만 빽빽한 인쇄물","mis":"K6-2-u4-X13"},{"t":"가사 없는 배경 음악","mis":"K6-2-u4-X27"}],"explanation":["동생들에게는 쉽게 전해야 해요.","짧은 이야기로 전하기에는 만화가 알맞아요.","알릴 내용에 따라 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#4','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'mc','auto','친구 모둠이 만든 것을 볼 때 보는 사람이 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X24','K6-2-u4-X14']::text[],false,'{"seq":4,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"친구 모둠이 만든 것을 볼 때 보는 사람이 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"알릴 내용이 잘 드러났는지 살피고 느낀 점과 보충할 점을 까닭과 함께 말한다","correct":true},{"t":"가장 화려한 모둠을 뽑는다","mis":"K6-2-u4-X13"},{"t":"잘못된 점만 찾아 말한다","mis":"K6-2-u4-X24"},{"t":"아무 말도 하지 않는다","mis":"K6-2-u4-X14"}],"explanation":["먼저 알릴 내용이 드러났는지 봐요.","느낀 점과 보충할 점을 말해요.","까닭과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#5','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',3,'ox','auto','교과 낱말은 뜻만 외우는 것보다 문장으로 한 번 써 보는 것이 오래 남아요.',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":5,"concept":"K6-2-u4-C17","difficulty":3,"kind":"ox","stem":"교과 낱말은 뜻만 외우는 것보다 문장으로 한 번 써 보는 것이 오래 남아요.","answer":"O","reason_options":[{"t":"낱말이 쓰이는 자리를 함께 익히기 때문에","correct":true},{"t":"문장으로 쓰면 뜻을 몰라도 되기 때문에","mis":"K6-2-u4-X28"}],"mis":"K6-2-u4-X28","explanation":["뜻만 외우면 금방 잊어요.","문장으로 쓰면 쓰이는 자리가 남아요.","다른 과목 공부도 쉬워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#6','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'match','auto','하루로 끝내지 않는 활동과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C16","difficulty":3,"kind":"match","stem":"하루로 끝내지 않는 활동과 하는 일을 알맞게 이으세요.","pairs":[{"l":"우리말 일기","r":"하루에 한 낱말씩 새로 안 우리말 적기"},{"l":"지킴이 도전","r":"한 주 동안 정한 다짐 하나 지키기"},{"l":"교실 말 고치기","r":"우리 반 알림 글부터 쉬운 우리말로 바꾸기"}],"mis":"K6-2-u4-X26","explanation":["일기는 날마다 한 낱말이에요.","도전은 한 주 동안 다짐 하나예요.","교실 말 고치기는 알림 글부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#7','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'error','auto','홍보 문구를 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"홍보 문구를 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예준 — 「‘외래어를 쓰는 사람은 우리말을 해칩니다’가 가장 세서 좋아.」","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"채아 — 「‘모르는 말은 되묻고, 어려운 말은 풀어 말해요’는 할 일이 보여.」","mis":"K6-2-u4-X25"},{"t":"시아 — 「알릴 내용이 한눈에 보이는지 먼저 살펴보자.」","mis":"K6-2-u4-X13"}],"explanation":["채아와 시아는 읽는 사람의 할 일과 내용을 보았어요.","예준은 누군가를 탓하는 문구를 골랐어요.","탓하는 말은 홍보 문구로 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#8','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',4,'mc','auto','「날마다 같은 시각에 하늘을 ○○해 기록했다.」에서 ○○에 가장 알맞은 낱말은 어느 것인가요?',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":8,"concept":"K6-2-u4-C17","difficulty":4,"kind":"mc","stem":"「날마다 같은 시각에 하늘을 ○○해 기록했다.」에서 ○○에 가장 알맞은 낱말은 어느 것인가요?","options":[{"t":"관측","correct":true},{"t":"증발","mis":"K6-2-u4-X28"},{"t":"지형","mis":"K6-2-u4-X28"},{"t":"분포","mis":"K6-2-u4-X28"}],"explanation":["하늘을 살펴 재거나 헤아리는 일이에요.","날마다 같은 시각에 기록했어요.","그래서 관측이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#9','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',4,'essay','teacher','우리 반에서 할 우리말 지킴이 활동을 계획하세요. 알릴 내용과 그에 맞는 방법을 고른 까닭, 주제 · 내용 · 역할 · 시간, 홍보 문구 한 줄, 하루로 끝내지 않고 이어 할 일을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"우리 반에서 할 우리말 지킴이 활동을 계획하세요. 알릴 내용과 그에 맞는 방법을 고른 까닭, 주제 · 내용 · 역할 · 시간, 홍보 문구 한 줄, 하루로 끝내지 않고 이어 할 일을 쓰세요.","answer_guide":{"answer":"예: 알릴 내용 — 쉬운 우리말로 다듬은 말. 방법 — 복도 알림판 인쇄물(여러 번 보게 할 수 있어서). 주제 — 쉬운 우리말로 바꾸어 말하기. 내용 — 다운로드 → 내려받기처럼 다듬은 말 짝. 역할 — 둘은 낱말 찾기, 둘은 글씨 쓰기. 시간 — 수요일까지 만들고 목요일에 붙이기. 문구 — 「오늘 한 번, 쉬운 우리말로 바꾸어 말해 볼까요?」 이어 할 일 — 붙인 뒤 한 주 동안 지킴이 도전.","scoring_points":["알릴 내용에 맞는 방법과 까닭을 썼는가","주제 · 내용 · 역할 · 시간을 모두 정했는가","알아들을 수 있는 문구와 이어 할 일을 썼는가"]},"explanation":["내용에 맞는 방법을 골라요.","역할을 먼저 나누어요.","하루로 끝내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_L11_challenge#10','kor',6,2,'u4','L11','g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C17',4,'essay','teacher','증발 · 지형 · 분포 · 관측 가운데 두 낱말을 골라 각각의 뜻을 쓰고, 그 낱말을 넣어 문장을 하나씩 만드세요. 그리고 네 낱말이 어떤 갈래의 낱말인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C17","difficulty":4,"kind":"essay","stem":"증발 · 지형 · 분포 · 관측 가운데 두 낱말을 골라 각각의 뜻을 쓰고, 그 낱말을 넣어 문장을 하나씩 만드세요. 그리고 네 낱말이 어떤 갈래의 낱말인지 쓰세요.","answer_guide":{"answer":"예: 증발 — 액체가 그 표면에서 기체로 변하는 현상. 문장 — 「햇볕에 둔 물이 증발해서 컵이 비었다.」 분포 — 일정한 범위에 흩어져 퍼져 있음. 문장 — 「우리 동네에는 놀이터가 고르게 분포해 있다.」 네 낱말은 모두 한자로 이루어진 한자어이다.","scoring_points":["두 낱말의 뜻을 바르게 썼는가","낱말을 넣어 뜻에 맞는 문장을 만들었는가","네 낱말이 한자어라는 것을 썼는가"]},"explanation":["뜻을 정확히 알아 둬요.","문장으로 써 보면 오래 남아요.","모두 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#1','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C1',1,'mc','auto','「호미」는 어떤 갈래의 낱말인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"「호미」는 어떤 갈래의 낱말인가요?","options":[{"t":"고유어","correct":true},{"t":"한자어","mis":"K6-2-u4-X01"},{"t":"외래어","mis":"K6-2-u4-X01"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["호미는 사전에 한글 표기만 있어요.","처음부터 우리말에 있던 낱말이에요.","그래서 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#2','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C2',1,'mc','auto','우리말을 바르게 쓰는 것이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"mc","stem":"우리말을 바르게 쓰는 것이 아닌 것은 어느 것인가요?","options":[{"t":"한자어와 외래어를 하나도 쓰지 않는 것","correct":true},{"t":"듣는 사람이 알아들을 수 있게 쓰는 것","mis":"K6-2-u4-X02"},{"t":"낱말의 뜻에 맞게 쓰는 것","mis":"K6-2-u4-X02"},{"t":"바꿀 수 있는 말은 쉬운 우리말로 쓰는 것","mis":"K6-2-u4-X02"}],"explanation":["알아들을 수 있게 쓰기는 바르게 쓰기예요.","뜻에 맞게, 바꿀 수 있는 말은 쉽게도 그래요.","다른 갈래를 몰아내는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#3','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C3',1,'mc','auto','「뜻을 알기 어려운 새말」을 쓰면 생기는 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"「뜻을 알기 어려운 새말」을 쓰면 생기는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"금방 생겼다 사라져서 뜻이 서로 다르게 통한다","correct":true},{"t":"뜻은 통해도 마음이 다친다","mis":"K6-2-u4-X04"},{"t":"쉬운 우리말이 있는데도 어렵게 쓴 것이다","mis":"K6-2-u4-X04"},{"t":"사전에 오래 실려 있어 낡았다","mis":"K6-2-u4-X04"}],"explanation":["새말은 금방 생겼다 사라져요.","사람마다 뜻을 다르게 알아요.","그래서 서로 다르게 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#4','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C4',1,'mc','auto','국어사전에서 「토마토(tomato)」처럼 낱말 뒤에 외국어가 함께 있으면 어떤 갈래인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X19']::text[],false,'{"seq":4,"concept":"K6-2-u4-C4","difficulty":1,"kind":"mc","stem":"국어사전에서 「토마토(tomato)」처럼 낱말 뒤에 외국어가 함께 있으면 어떤 갈래인가요?","options":[{"t":"외래어","correct":true},{"t":"고유어","mis":"K6-2-u4-X05"},{"t":"한자어","mis":"K6-2-u4-X05"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["한글 표기만 있으면 고유어예요.","한자가 있으면 한자어예요.","외국어가 있으면 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#5','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C6',1,'mc','auto','「익일」을 쉬운 우리말로 다듬은 말은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X03']::text[],false,'{"seq":5,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"「익일」을 쉬운 우리말로 다듬은 말은 어느 것인가요?","options":[{"t":"다음 날","correct":true},{"t":"명일","mis":"K6-2-u4-X08"},{"t":"넥스트 데이","mis":"K6-2-u4-X03"},{"t":"지난날","mis":"K6-2-u4-X08"}],"explanation":["익일은 그다음 날이라는 뜻이에요.","「다음 날」이라고 하면 바로 알 수 있어요.","다른 어려운 말로 바꾸면 다듬은 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#6','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C8',1,'mc','auto','고유어를 활용한 사례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":6,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"고유어를 활용한 사례로 알맞은 것은 어느 것인가요?","options":[{"t":"나루터길","correct":true},{"t":"센트럴 로드","mis":"K6-2-u4-X10"},{"t":"제일 빌딩","mis":"K6-2-u4-X10"},{"t":"스카이 아파트","mis":"K6-2-u4-X10"}],"explanation":["나루터길은 나루터 + 길로 나눌 수 있어요.","둘 다 고유어예요.","나머지는 외국어나 한자어로 지은 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#7','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C11',1,'mc','auto','우리말 사전을 만드는 일이 「함께 쓰는 말을 지키는 일」이었던 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X15','K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C11","difficulty":1,"kind":"mc","stem":"우리말 사전을 만드는 일이 「함께 쓰는 말을 지키는 일」이었던 까닭은 어느 것인가요?","options":[{"t":"흩어진 말을 모아 남겨 오늘 국어사전의 바탕이 되었기 때문에","correct":true},{"t":"외국어를 모두 우리말로 바꾸었기 때문에","mis":"K6-2-u4-X15"},{"t":"고장 말을 모두 지웠기 때문에","mis":"K6-2-u4-X19"},{"t":"낱말 수를 줄였기 때문에","mis":"K6-2-u4-X15"}],"explanation":["마음껏 쓰지 못하던 때에도 말을 모았어요.","고장 말까지 모아 남겼어요.","그 기록이 오늘 국어사전의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#8','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',1,'mc','auto','실천 다짐문의 네 부분에 들어가지 않는 것은 어느 것인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":8,"concept":"K6-2-u4-C15","difficulty":1,"kind":"mc","stem":"실천 다짐문의 네 부분에 들어가지 않는 것은 어느 것인가요?","options":[{"t":"내가 받고 싶은 칭찬","correct":true},{"t":"목적","mis":"K6-2-u4-X22"},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"날짜와 쓴 사람","mis":"K6-2-u4-X22"}],"explanation":["다짐문에는 목적과 실천 약속이 들어가요.","전하고 싶은 말, 날짜와 쓴 사람도 들어가요.","받고 싶은 칭찬은 들어가지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#9','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C8',2,'mc','auto','시우네 모둠이 고유어를 활용한 사례로 잘못 든 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":9,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"시우네 모둠이 고유어를 활용한 사례로 잘못 든 것은 어느 것인가요?","options":[{"t":"스마일 마트","correct":true},{"t":"솔바람길","mis":"K6-2-u4-X10"},{"t":"한아름 꽃집","mis":"K6-2-u4-X10"},{"t":"솔바람길과 한아름 꽃집 모두","mis":"K6-2-u4-X10"}],"explanation":["솔 · 바람 · 길, 한아름은 고유어예요.","스마일은 영어예요.","그래서 고유어 사례가 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#10','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C10',2,'mc','auto','시우네 모둠이 「솔바람길」을 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"시우네 모둠이 「솔바람길」을 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?","options":[{"t":"길이 어디에 있는지 보여 주는 지도와 길 사진","correct":true},{"t":"글자만 빽빽하게 적은 종이","mis":"K6-2-u4-X13"},{"t":"반짝이 장식을 붙인 표지","mis":"K6-2-u4-X13"},{"t":"발표 내내 틀어 둔 배경 음악","mis":"K6-2-u4-X13"}],"explanation":["길 이름은 위치와 함께 보여 줘요.","지도는 길의 흐름을 보여 줘요.","사진은 실제 모습을 보여 줘요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#11','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',2,'mc','auto','서윤이 이야기에서 「정구지」가 가리키는 것은 무엇일까요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":11,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"서윤이 이야기에서 「정구지」가 가리키는 것은 무엇일까요?","options":[{"t":"바구니에 담긴 초록 채소","correct":true},{"t":"서랍 속 가위","mis":"K6-2-u4-X18"},{"t":"손때 묻은 수첩","mis":"K6-2-u4-X18"},{"t":"연필 한 자루","mis":"K6-2-u4-X18"}],"explanation":["외할머니는 정구지를 씻어 오라고 하셨어요.","서윤이는 바구니의 초록 채소를 보았어요.","앞뒤 말이 채소를 가리켜요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#12','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',2,'mc','auto','서윤이 이야기에 그대로 적혀 있는 것은 어느 것인가요?',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":12,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"서윤이 이야기에 그대로 적혀 있는 것은 어느 것인가요?","options":[{"t":"수첩 맨 끝 장에 「다음은 누가?」라고 적혀 있었다","correct":true},{"t":"외할머니는 수첩을 서윤이에게 물려주겠다고 말씀하셨다","mis":"K6-2-u4-X17"},{"t":"서윤이는 수첩을 이어 적기로 마음먹었다","mis":"K6-2-u4-X17"},{"t":"수첩에는 다른 고장의 말도 적혀 있었다","mis":"K6-2-u4-X17"}],"explanation":["「다음은 누가?」는 글에 적혀 있어요.","물려주겠다는 말씀은 글에 없어요.","서윤이의 마음도 글에 적혀 있지 않아요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#13','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',2,'mc','auto','지후의 다짐문에서 빠진 부분은 어느 것인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"지후의 다짐문에서 빠진 부분은 어느 것인가요?","options":[{"t":"목적","correct":true},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"전하고 싶은 말","mis":"K6-2-u4-X22"},{"t":"날짜와 쓴 사람","mis":"K6-2-u4-X22"}],"explanation":["「하나,」 네 줄이 실천 약속이에요.","「모두 함께 …」가 전하고 싶은 말, 마지막 줄이 날짜와 쓴 사람이에요.","무엇을 위해 다짐하는지가 빠졌어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#14','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C16',2,'mc','auto','하람이네 홍보 문구를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하람이네 홍보 문구를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「쉬운 우리말로 한 번 바꾸어 말해 볼까요?」","correct":true},{"t":"「굿 워드 챌린지 스타트!」","mis":"K6-2-u4-X25"},{"t":"「우리말 안 쓰는 사람, 반성하세요!」","mis":"K6-2-u4-X25"},{"t":"「우리말, 우리말, 우리말!」","mis":"K6-2-u4-X25"}],"explanation":["우리말을 알리는 문구는 쉬운 우리말로 써요.","누군가를 탓하지 않아요.","읽는 사람의 할 일이 보이게 써요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#15','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C5',2,'match','auto','시에 나온 고유어와 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"match","stem":"시에 나온 고유어와 뜻을 알맞게 이으세요.","pairs":[{"l":"오솔길","r":"폭이 좁고 호젓한 길"},{"l":"어스름","r":"조금 어둑한 상태, 또는 그런 때"},{"l":"잔물결","r":"자잘하게 이는 물결"}],"mis":"K6-2-u4-X18","explanation":["오솔길은 좁고 호젓한 길이에요.","어스름은 조금 어둑한 때예요.","잔물결은 자잘한 물결이에요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#16','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C17',2,'mc','auto','「이 고장은 ○○이 험해 길이 굽어 있다.」에서 ○○에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-2-u4-X28']::text[],false,'{"seq":16,"concept":"K6-2-u4-C17","difficulty":2,"kind":"mc","stem":"「이 고장은 ○○이 험해 길이 굽어 있다.」에서 ○○에 알맞은 낱말은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"증발","mis":"K6-2-u4-X28"},{"t":"분포","mis":"K6-2-u4-X28"},{"t":"관측","mis":"K6-2-u4-X28"}],"explanation":["험하다는 것은 땅의 모양이에요.","땅의 생긴 모양은 지형이에요.","그래서 길이 굽어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#17','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',3,'error','auto','시우네 발표 자료를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X12','K6-2-u4-X10']::text[],false,'{"seq":17,"concept":"K6-2-u4-C9","difficulty":3,"kind":"error","stem":"시우네 발표 자료를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"보람 — 「‘다온 마을’은 뜻이 그럴듯하니 그대로 발표해도 돼.」","correct":true,"mis_target":"K6-2-u4-X12"},{"t":"지민 — 「‘스마일 마트’는 고유어가 아니니 다른 사례로 바꾸자.」","mis":"K6-2-u4-X10"},{"t":"현우 — 「‘솔바람길’은 낱말을 나누어 확인한 좋은 사례야.」","mis":"K6-2-u4-X10"}],"explanation":["지민과 현우는 갈래와 확인을 살폈어요.","보람은 출처 없는 뜻을 그대로 쓰자고 했어요.","그럴듯하다고 확인한 것은 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#18','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',3,'mc','auto','외할머니가 연필을 서윤이 쪽으로 밀어 주신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16']::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"외할머니가 연필을 서윤이 쪽으로 밀어 주신 까닭을 추론한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서윤이가 수첩에 동네 말을 이어 적어 주기를 바라셨을 것이다","correct":true},{"t":"책상 위 연필을 치우려 하셨을 것이다","mis":"K6-2-u4-X16"},{"t":"그림을 그려 보라고 하셨을 것이다","mis":"K6-2-u4-X16"},{"t":"수첩이 낡아 버리라고 하셨을 것이다","mis":"K6-2-u4-X16"}],"explanation":["끝 장에 「다음은 누가?」가 적혀 있었어요.","그 위에 연필을 올려 밀어 주셨어요.","두 단서가 같은 곳을 가리켜요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#19','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',3,'error','auto','지후의 다짐문을 읽고 말해 주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X22']::text[],false,'{"seq":19,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"지후의 다짐문을 읽고 말해 주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예서 — 「글씨가 비뚤어진 줄부터 다시 쓰자.」","correct":true,"mis_target":"K6-2-u4-X24"},{"t":"은호 — 「넷째 줄은 언제 무엇을 할지 있어서 좋아.」","mis":"K6-2-u4-X24"},{"t":"가온 — 「무엇을 위해 다짐하는지 목적 줄을 맨 앞에 넣자.」","mis":"K6-2-u4-X22"}],"explanation":["은호는 잘 쓴 부분을 먼저 말했어요.","가온은 빠진 부분을 내용에서 찾았어요.","예서는 겉모습을 보았어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#20','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C16',3,'error','auto','하람이네 계획을 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X26']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"하람이네 계획을 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"소은 — 「알림판을 반짝이 종이로 가득 꾸미면 홍보는 다 된 거야.」","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"윤호 — 「바꾸면 좋은 말 다섯 쌍이 한눈에 보이게 크게 쓰자.」","mis":"K6-2-u4-X25"},{"t":"해나 — 「붙인 뒤에도 한 주 동안 지킴이 도전을 이어 가자.」","mis":"K6-2-u4-X26"}],"explanation":["윤호는 알릴 내용을 앞세웠어요.","해나는 하루로 끝내지 않으려 했어요.","소은은 꾸밈을 홍보의 전부로 여겼어요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#21','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C13',3,'mc','auto','서윤이가 다른 고장 친구들 앞에서 방학 이야기를 발표할 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":21,"concept":"K6-2-u4-C13","difficulty":3,"kind":"mc","stem":"서윤이가 다른 고장 친구들 앞에서 방학 이야기를 발표할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"「정구지」 같은 고장 말을 소개하며 표준어 「부추」로 뜻을 함께 말한다","correct":true},{"t":"고장 말은 틀린 말이니 빼고 말한다","mis":"K6-2-u4-X19"},{"t":"친구들이 모를 고장 말로만 말한다","mis":"K6-2-u4-X20"},{"t":"외할머니 말투를 흉내 내어 웃음거리로 삼는다","mis":"K6-2-u4-X19"}],"explanation":["발표는 여러 사람이 듣는 자리예요.","고장 말도 소중하니 소개할 수 있어요.","표준어로 뜻을 함께 말하면 모두 알아들어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#22','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C2',3,'mc','auto','이 단원의 제목이 「소중한 우리말」인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X19']::text[],false,'{"seq":22,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"이 단원의 제목이 「소중한 우리말」인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리말에는 세 갈래도, 표준어도, 고장 말도 모두 들어 있어 모두 소중하기 때문에","correct":true},{"t":"고유어만 소중한 말이기 때문에","mis":"K6-2-u4-X02"},{"t":"표준어만 소중한 말이기 때문에","mis":"K6-2-u4-X19"},{"t":"외래어를 몰아내야 하기 때문에","mis":"K6-2-u4-X02"}],"explanation":["첫 시간의 약속을 떠올려요.","세 갈래와 표준어 · 고장 말이 모두 우리말이에요.","그래서 모두 소중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#23','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',4,'mc','auto','시우네 발표 자료를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X10','K6-2-u4-X12','K6-2-u4-X01']::text[],false,'{"seq":23,"concept":"K6-2-u4-C9","difficulty":4,"kind":"mc","stem":"시우네 발표 자료를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"솔바람길 · 한아름 꽃집은 낱말을 나누고 확인한 곳까지 밝혀 좋지만, 다온 마을은 확인인지 짐작인지 밝혀야 하고 스마일 마트는 고유어 사례로 바꾸어야 한다","correct":true},{"t":"네 사례 모두 이름이 예뻐 잘 조사했다","mis":"K6-2-u4-X10"},{"t":"다온 마을 하나가 확인되지 않았으니 발표 전체를 믿을 수 없다","mis":"K6-2-u4-X12"},{"t":"스마일 마트는 영어 사전에서 확인했으니 고유어 사례로 괜찮다","mis":"K6-2-u4-X01"}],"explanation":["잘된 점을 먼저 짚어요.","확인 · 짐작을 가르고 갈래를 살펴요.","고칠 자리만 고치면 돼요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#24','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',4,'essay','teacher','시우네 발표 자료를 잘한 점과 고칠 점으로 나누어 평가하고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C9","difficulty":4,"kind":"essay","stem":"시우네 발표 자료를 잘한 점과 고칠 점으로 나누어 평가하고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 솔바람길은 솔 · 바람 · 길로 낱말을 나누어 고유어를 찾았고, 솔바람길과 한아름 꽃집은 뜻을 어디에서 확인했는지 밝혔다. 고칠 점 — 다온 마을은 뜻의 출처가 없어 확인한 것인지 짐작한 것인지 알 수 없다. 스마일 마트의 스마일은 영어라 고유어 사례가 아니다. 고칠 방법 — 다온 마을은 사전에서 찾고 동네 어른께 여쭈어 보고, 그래도 모르면 「아직 확인하지 못했습니다」라고 밝힌다. 스마일 마트는 고유어가 들어간 다른 가게 이름으로 바꾼다.","scoring_points":["잘한 점을 먼저 썼는가","확인 · 짐작과 갈래를 기준으로 고칠 점을 썼는가","고칠 방법을 구체적으로 썼는가"]},"explanation":["잘한 점부터 써요.","확인과 짐작, 갈래를 살펴요.","고칠 방법까지 써요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_a#25','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C5',4,'essay','teacher','「비 그친 아침」에서 고유어를 두 개 골라 뜻을 쓰고, 그 낱말이 어떤 장면을 떠올리게 하는지 쓰세요. 그리고 이 시와 이어서 고유어의 가치를 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"「비 그친 아침」에서 고유어를 두 개 골라 뜻을 쓰고, 그 낱말이 어떤 장면을 떠올리게 하는지 쓰세요. 그리고 이 시와 이어서 고유어의 가치를 한 가지 쓰세요.","answer_guide":{"answer":"예: 여울 — 물살이 세게 흐르는 얕은 곳. 비에 불어난 개울물이 돌 사이로 소리를 내며 빠르게 흐르는 장면이 떠오른다. 잔물결 — 자잘하게 이는 물결. 바람이 불자 개울 위가 작게 반짝이는 장면이 떠오른다. 고유어는 눈에 보이는 모습과 느낌을 그대로 담고 있어서, 뜻을 알면 장면이 또렷이 보인다.","scoring_points":["고유어 두 개의 뜻을 바르게 썼는가","낱말이 떠올리게 하는 장면을 썼는가","고유어의 가치를 시와 이어 썼는가"]},"explanation":["뜻을 알면 장면이 보여요.","고유어는 느낌을 살려요.","시의 마지막 줄을 떠올려요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#1','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C1',1,'sa','auto','한자로 이루어진 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"sa","stem":"한자로 이루어진 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["한자어"],"explanation":["처음부터 있던 말은 고유어예요.","다른 나라에서 온 말은 외래어예요.","한자로 이루어진 말은 한자어예요."],"mis":"K6-2-u4-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#2','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C2',1,'ox','auto','어려운 말을 많이 쓸수록 우리말을 잘 쓰는 거예요.',ARRAY['K6-2-u4-X03']::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"ox","stem":"어려운 말을 많이 쓸수록 우리말을 잘 쓰는 거예요.","answer":"X","reason_options":[{"t":"듣는 사람이 알아들을 수 있게 쓰는 것이 바르게 쓰는 것이기 때문에","correct":true},{"t":"어려운 말을 쓰면 많이 아는 것처럼 보이기 때문에","mis":"K6-2-u4-X03"}],"mis":"K6-2-u4-X03","explanation":["어려운 말은 듣는 사람을 막아요.","말은 뜻을 주고받으려고 써요.","알아들을 수 있게 쓰는 것이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#3','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C3',1,'ox','auto','뜻만 통하면 기분을 상하게 하는 말을 써도 괜찮아요.',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":1,"kind":"ox","stem":"뜻만 통하면 기분을 상하게 하는 말을 써도 괜찮아요.","answer":"X","reason_options":[{"t":"뜻은 통해도 듣는 사람의 마음이 다치기 때문에","correct":true},{"t":"말은 뜻만 전하면 되기 때문에","mis":"K6-2-u4-X04"}],"mis":"K6-2-u4-X04","explanation":["말은 뜻만 전하는 것이 아니에요.","마음도 함께 전해져요.","기분 상하는 말은 마음을 다치게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#4','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C4',1,'sa','auto','갈래가 헷갈리는 낱말은 짐작하지 말고 무엇에서 확인하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u4-C4","difficulty":1,"kind":"sa","stem":"갈래가 헷갈리는 낱말은 짐작하지 말고 무엇에서 확인하나요? 네 글자로 쓰세요.","answer":["국어사전"],"explanation":["소리나 모양으로 짐작하면 틀리기 쉬워요.","종이 사전이든 스마트 기기 사전이든 좋아요.","국어사전에서 확인해요."],"mis":"K6-2-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#5','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C6',1,'sa','auto','「다운로드」를 쉬운 우리말로 다듬은 말을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u4-C6","difficulty":1,"kind":"sa","stem":"「다운로드」를 쉬운 우리말로 다듬은 말을 네 글자로 쓰세요.","answer":["내려받기"],"explanation":["다운로드는 무엇을 내려받는 일이에요.","「내려받기」라고 하면 동작이 그려져요.","누구나 알아들을 수 있어요."],"mis":"K6-2-u4-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#6','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C9',1,'sa','auto','조사 계획에서는 조사 대상 · 조사 범위 · 조사 ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C9","difficulty":1,"kind":"sa","stem":"조사 계획에서는 조사 대상 · 조사 범위 · 조사 ○○을 정해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["방법"],"explanation":["무엇을 조사할지가 대상이에요.","어디까지 조사할지가 범위예요.","어떻게 조사할지가 방법이에요."],"mis":"K6-2-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#7','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',1,'sa','auto','글쓴이가 적지 않은 부분을 단서와 경험으로 메우는 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C12","difficulty":1,"kind":"sa","stem":"글쓴이가 적지 않은 부분을 단서와 경험으로 메우는 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["추론"],"explanation":["글쓴이는 모든 것을 다 적지 않아요.","단서와 경험 · 지식으로 메워요.","그것을 추론이라고 해요."],"mis":"K6-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#8','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C17',1,'sa','auto','「일정한 범위에 흩어져 퍼져 있음」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C17","difficulty":1,"kind":"sa","stem":"「일정한 범위에 흩어져 퍼져 있음」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["분포"],"explanation":["지형은 땅의 생긴 모양이에요.","관측은 살펴 재는 일이에요.","흩어져 퍼져 있음은 분포예요."],"mis":"K6-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#9','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C9',2,'mc','auto','시우네 표에서 뜻을 어디에서 확인했는지 밝히지 않은 사례는 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":9,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우네 표에서 뜻을 어디에서 확인했는지 밝히지 않은 사례는 어느 것인가요?","options":[{"t":"다온 마을","correct":true},{"t":"솔바람길","mis":"K6-2-u4-X12"},{"t":"한아름 꽃집","mis":"K6-2-u4-X12"},{"t":"스마일 마트","mis":"K6-2-u4-X12"}],"explanation":["솔바람길 · 한아름 꽃집은 확인한 곳을 밝혔어요.","스마일 마트도 확인한 곳을 적었어요.","다온 마을만 출처가 없어요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#10','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C8',2,'ox','auto','시우네 모둠은 「솔바람길」을 솔 · 바람 · 길로 나누어 살펴 고유어를 찾았어요.',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":10,"concept":"K6-2-u4-C8","difficulty":2,"kind":"ox","stem":"시우네 모둠은 「솔바람길」을 솔 · 바람 · 길로 나누어 살펴 고유어를 찾았어요.","answer":"O","reason_options":[{"t":"여러 낱말로 이루어진 이름은 낱말을 나누어 살펴야 하기 때문에","correct":true},{"t":"이름은 나누지 않고 통째로 보아야 하기 때문에","mis":"K6-2-u4-X10"}],"mis":"K6-2-u4-X10","explanation":["이름을 낱말로 나누었어요.","솔 · 바람 · 길은 모두 고유어예요.","그래서 좋은 사례예요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#11','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',2,'mc','auto','외할머니가 말한 「갈무리하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":11,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"외할머니가 말한 「갈무리하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 잘 정리하여 간수함","correct":true},{"t":"물건을 버림","mis":"K6-2-u4-X18"},{"t":"물건을 새로 사 옴","mis":"K6-2-u4-X18"},{"t":"물건을 남에게 빌려줌","mis":"K6-2-u4-X18"}],"explanation":["「잘 갈무리해 두었더니 아직 멀쩡하구나」라고 하셨어요.","오래된 수첩이 멀쩡히 남았어요.","잘 정리하여 간수했다는 뜻이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#12','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',2,'mc','auto','외할머니가 「정구지」 · 「가새」라고 하신 말에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X16']::text[],false,'{"seq":12,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"외할머니가 「정구지」 · 「가새」라고 하신 말에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 고장에서 쓰는 말로, 고장 사람끼리 정답게 쓰는 소중한 우리말이다","correct":true},{"t":"고쳐 드려야 할 틀린 말이다","mis":"K6-2-u4-X19"},{"t":"배우지 못해서 쓰시는 말이다","mis":"K6-2-u4-X19"},{"t":"서윤이를 놀리려고 지어낸 말이다","mis":"K6-2-u4-X16"}],"explanation":["방언은 틀린 말이 아니에요.","그 고장의 정과 역사가 담겨 있어요.","쓰이는 자리가 다를 뿐이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#13','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C15',2,'mc','auto','지후의 다짐 가운데 지킬 수 있는 다짐은 어느 것인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"지후의 다짐 가운데 지킬 수 있는 다짐은 어느 것인가요?","options":[{"t":"쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠다는 다짐","correct":true},{"t":"우리말을 아주 열심히 사랑하겠다는 다짐","mis":"K6-2-u4-X23"},{"t":"외래어를 하나도 쓰지 않겠다는 다짐","mis":"K6-2-u4-X23"},{"t":"다들 줄인 말을 쓰지 말자는 다짐","mis":"K6-2-u4-X23"}],"explanation":["언제 · 무엇을 할지가 드러나야 해요.","「쉬는 시간에」 · 「풀어 주기」가 드러나요.","나머지는 막연하거나 너무 크거나 내 일이 없어요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#14','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',2,'mc','auto','하람이네가 인쇄물을 고른 것이 알맞은 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X13']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하람이네가 인쇄물을 고른 것이 알맞은 까닭은 어느 것인가요?","options":[{"t":"바꾸면 좋은 말을 붙여 두고 여러 번 보게 할 수 있어서","correct":true},{"t":"움직임과 목소리를 전할 수 있어서","mis":"K6-2-u4-X27"},{"t":"짧은 이야기로 이해시킬 수 있어서","mis":"K6-2-u4-X27"},{"t":"가장 화려하게 꾸밀 수 있어서","mis":"K6-2-u4-X13"}],"explanation":["바꾸면 좋은 말은 여러 번 보아야 익어요.","인쇄물은 한자리에 붙여 둘 수 있어요.","알릴 내용과 방법이 잘 맞아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#15','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C5',2,'mc','auto','시의 마지막 「이름을 알고 보니 / 모두 다르게 보인다」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X06','K6-2-u4-X16']::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"시의 마지막 「이름을 알고 보니 / 모두 다르게 보인다」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"고유어의 뜻을 알면 장면이 더 또렷이 보인다","correct":true},{"t":"이름은 몰라도 아무 상관이 없다","mis":"K6-2-u4-X06"},{"t":"비가 그치자 사물의 모양이 바뀌었다","mis":"K6-2-u4-X16"},{"t":"사물에 새 이름을 지어 주었다","mis":"K6-2-u4-X16"}],"explanation":["여울 · 오솔길 · 잔물결에는 장면이 담겨 있어요.","뜻을 알면 그 장면이 보여요.","고유어가 느낌과 장면을 살려요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#16','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',2,'mc','auto','전교 방송으로 학교 행사를 안내할 때 알맞은 말은 어느 것인가요?',ARRAY['K6-2-u4-X20','K6-2-u4-X03']::text[],false,'{"seq":16,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"전교 방송으로 학교 행사를 안내할 때 알맞은 말은 어느 것인가요?","options":[{"t":"온 학교 사람이 두루 알아듣도록 표준어로 말한다","correct":true},{"t":"내가 사는 고장 말로만 말한다","mis":"K6-2-u4-X20"},{"t":"줄인 말로 짧게 말한다","mis":"K6-2-u4-X03"},{"t":"외국어를 섞어 멋있게 말한다","mis":"K6-2-u4-X03"}],"explanation":["전교 방송은 공식적인 자리예요.","모두가 알아들어야 해요.","그래서 표준어로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#17','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C10',3,'mc','auto','시우네가 표와 지도를 함께 쓰려고 해요. 각 매체를 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":17,"concept":"K6-2-u4-C10","difficulty":3,"kind":"mc","stem":"시우네가 표와 지도를 함께 쓰려고 해요. 각 매체를 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"표로 네 사례를 한눈에 견주고, 지도로 길과 동네가 어디에 있는지 보여 준다","correct":true},{"t":"표는 화려하게, 지도는 크게 꾸며 눈길을 끈다","mis":"K6-2-u4-X13"},{"t":"표와 지도에 자료를 최대한 많이 넣는다","mis":"K6-2-u4-X13"},{"t":"매체는 아무것이나 골라 내용을 끼워 넣는다","mis":"K6-2-u4-X13"}],"explanation":["표는 견주기에 알맞아요.","지도는 위치를 보여 줘요.","알릴 내용에 맞추어 매체를 골라요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#18','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',3,'error','auto','서윤이 이야기를 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X18']::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"error","stem":"서윤이 이야기를 읽고 추론했어요. 알맞지 않게 추론한 친구는 누구인가요?","options":[{"t":"주원 — 「외할머니는 서윤이가 수첩을 팔기를 바라셨을 거야. 그냥 그럴 것 같아.」","correct":true,"mis_target":"K6-2-u4-X16"},{"t":"나린 — 「끝 장의 ‘다음은 누가?’와 연필을 이어 보면 이어 적기를 바라신 거야.」","mis":"K6-2-u4-X16"},{"t":"도겸 — 「씻어 오라고 하셨고 바구니에 채소가 있으니 정구지는 채소 이름일 거야.」","mis":"K6-2-u4-X18"}],"explanation":["나린과 도겸은 글에서 단서를 찾았어요.","주원은 까닭이 글에 없어요.","추론은 마음대로 지어내는 것이 아니에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#19','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C15',3,'mc','auto','지후의 「앞으로 우리말을 아주 열심히 사랑하겠습니다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":19,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"지후의 「앞으로 우리말을 아주 열심히 사랑하겠습니다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 알림장을 쓸 때 쉬운 우리말로 바꿀 수 있는 말을 하나씩 바꾸어 쓰겠습니다.」","correct":true},{"t":"「나는 우리말을 정말 정말 사랑하겠습니다.」","mis":"K6-2-u4-X23"},{"t":"「나는 영원히 우리말만 쓰겠습니다.」","mis":"K6-2-u4-X23"},{"t":"「우리 모두 우리말을 사랑합시다.」","mis":"K6-2-u4-X23"}],"explanation":["「열심히」에는 무엇을 할지가 없어요.","언제 · 무엇을 할지 넣어 고쳐요.","지킬 수 있는 크기로 써요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#20','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',3,'mc','auto','하람이네 계획에서 잘된 점은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X26']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"하람이네 계획에서 잘된 점은 어느 것인가요?","options":[{"t":"알릴 내용(바꾸면 좋은 말)과 방법(오래 붙여 두는 인쇄물)이 잘 맞는다","correct":true},{"t":"문구에 외국어가 있어 눈에 띈다","mis":"K6-2-u4-X25"},{"t":"하루 만에 끝나 부담이 없다","mis":"K6-2-u4-X26"},{"t":"역할을 정하지 않아 자유롭다","mis":"K6-2-u4-X25"}],"explanation":["잘된 점을 먼저 찾아요.","내용과 방법이 잘 맞아요.","문구 · 역할 · 시간은 고칠 점이에요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#21','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C11',3,'ox','auto','고장 말을 어른께 여쭈어 적어 두는 것도 우리말을 지키는 일이에요.',ARRAY['K6-2-u4-X15']::text[],false,'{"seq":21,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"고장 말을 어른께 여쭈어 적어 두는 것도 우리말을 지키는 일이에요.","answer":"O","reason_options":[{"t":"적어 두지 않으면 쓰는 사람이 줄면서 사라질 수 있기 때문에","correct":true},{"t":"표준어만 지키면 되기 때문에","mis":"K6-2-u4-X15"}],"mis":"K6-2-u4-X15","explanation":["말은 저절로 남지 않아요.","쓰는 사람이 줄면 사라질 수 있어요.","적어 두는 것이 지키는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#22','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C2',3,'ox','auto','듣는 사람이 누구든 늘 같은 말로만 말하는 것이 상황에 맞게 쓰는 거예요.',ARRAY['K6-2-u4-X20']::text[],false,'{"seq":22,"concept":"K6-2-u4-C2","difficulty":3,"kind":"ox","stem":"듣는 사람이 누구든 늘 같은 말로만 말하는 것이 상황에 맞게 쓰는 거예요.","answer":"X","reason_options":[{"t":"누구에게 어디에서 말하느냐에 따라 골라 써야 하기 때문에","correct":true},{"t":"말은 한 가지로 통일해야 하기 때문에","mis":"K6-2-u4-X20"}],"mis":"K6-2-u4-X20","explanation":["말은 누구에게, 어디에서 하느냐에 따라 달라져요.","공식적인 자리에서는 표준어로 말해요.","고장 사람과는 고장 말로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#23','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',4,'mc','auto','서윤이 이야기에서 외할머니의 마음을 추론한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17','K6-2-u4-X19']::text[],false,'{"seq":23,"concept":"K6-2-u4-C12","difficulty":4,"kind":"mc","stem":"서윤이 이야기에서 외할머니의 마음을 추론한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰는 사람이 줄어 사라질 수 있는 동네 말을 서윤이가 이어 적어 주기를 바라셨다 — 갈무리해 둔 수첩, 끝 장의 물음, 밀어 준 연필이 단서다","correct":true},{"t":"서윤이에게 연필을 선물하고 싶으셨을 뿐이다","mis":"K6-2-u4-X16"},{"t":"글에 적혀 있지 않으니 아무것도 알 수 없다","mis":"K6-2-u4-X17"},{"t":"표준어를 몰라서 수첩에 적어 두셨다","mis":"K6-2-u4-X19"}],"explanation":["단서를 여러 개 모아요.","수첩 · 물음 · 연필이 같은 곳을 가리켜요.","글에 없는 마음도 단서로 메울 수 있어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#24','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',4,'essay','teacher','서윤이 이야기에서 외할머니가 서윤이에게 바라신 것을 추론해 쓰고, 그렇게 추론한 단서를 두 가지 쓰세요. 그리고 서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C12","difficulty":4,"kind":"essay","stem":"서윤이 이야기에서 외할머니가 서윤이에게 바라신 것을 추론해 쓰고, 그렇게 추론한 단서를 두 가지 쓰세요. 그리고 서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서도 쓰세요.","answer_guide":{"answer":"예: 외할머니는 서윤이가 동네 말을 수첩에 이어 적어 주기를 바라셨을 것이다. 단서 — 수첩 맨 끝 장에 「다음은 누가?」라고 적혀 있었다. 외할머니가 연필을 수첩 위에 올려 서윤이 쪽으로 밀어 주셨다. 정구지의 단서 — 외할머니가 정구지를 씻어 오라고 하셨고, 바구니에 초록 채소가 담겨 있었다.","scoring_points":["외할머니의 바람을 알맞게 추론했는가","글에서 단서를 두 가지 찾았는가","낱말 뜻을 짐작한 문맥 단서를 썼는가"]},"explanation":["적힌 것과 메운 생각을 갈라요.","까닭은 글 안에서 찾아요.","앞뒤 말과 장면이 낱말의 단서예요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_b#25','kor',6,2,'u4','','g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',4,'essay','teacher','표준어와 방언이 각각 하는 일을 쓰고, 표준어로 말해야 할 상황과 고장 말로 말해도 좋은 상황을 하나씩 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C13","difficulty":4,"kind":"essay","stem":"표준어와 방언이 각각 하는 일을 쓰고, 표준어로 말해야 할 상황과 고장 말로 말해도 좋은 상황을 하나씩 들어 쓰세요.","answer_guide":{"answer":"예: 표준어는 사는 곳이 달라도 서로 통하게 해 주고, 방언은 그 고장의 정과 역사를 담아 전해 준다. 표준어로 말해야 할 상황 — 전교 방송으로 학교 행사를 안내할 때. 고장 말로 말해도 좋은 상황 — 외할머니 댁에서 이웃 어른들과 이야기를 나눌 때.","scoring_points":["표준어와 방언이 하는 일을 각각 썼는가","표준어로 말할 상황을 알맞게 들었는가","고장 말로 말해도 좋은 상황을 알맞게 들었는가"]},"explanation":["표준어는 두루 통하게.","방언은 정과 역사를.","누구에게 · 어디에서 말하는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#1','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C1',1,'ox','auto','「토마토」는 외래어예요.',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"ox","stem":"「토마토」는 외래어예요.","answer":"O","reason_options":[{"t":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말이기 때문에","correct":true},{"t":"고유어로 바꾸어 써야 하는 낱말이기 때문에","mis":"K6-2-u4-X08"}],"mis":"K6-2-u4-X08","explanation":["토마토는 다른 나라에서 들어온 말이에요.","우리 생활에서 널리 쓰여요.","그래서 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#2','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C2',1,'sa','auto','말은 뜻을 주고받으려고 써요. 그래서 바르게 쓴다는 것은 듣는 사람이 ○○○○ 수 있게 쓰는 것이에요. ○○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"sa","stem":"말은 뜻을 주고받으려고 써요. 그래서 바르게 쓴다는 것은 듣는 사람이 ○○○○ 수 있게 쓰는 것이에요. ○○○○에 알맞은 말을 쓰세요.","answer":["알아들을"],"explanation":["말이 통해야 뜻을 주고받아요.","듣는 사람의 처지에서 생각해요.","알아들을 수 있게 쓰는 것이 바르게 쓰기예요."],"mis":"K6-2-u4-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#3','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C14',1,'mc','auto','언어생활 점검표에서 늘려 가고 싶은 말은 어느 것인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":3,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"언어생활 점검표에서 늘려 가고 싶은 말은 어느 것인가요?","options":[{"t":"즐겨 쓰는 고유어","correct":true},{"t":"굳이 외국어로 쓴 말","mis":"K6-2-u4-X03"},{"t":"지나치게 줄인 말","mis":"K6-2-u4-X03"},{"t":"기분을 상하게 하는 말","mis":"K6-2-u4-X04"}],"explanation":["외국어 · 줄인 말 · 기분 상하는 말은 줄여 갈 말이에요.","즐겨 쓰는 고유어는 늘려 갈 말이에요.","점검표에 함께 표시해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#4','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C5',1,'ox','auto','「눈썰미」처럼 고유어를 이어 붙여 만든 낱말도 고유어예요.',ARRAY['K6-2-u4-X06']::text[],false,'{"seq":4,"concept":"K6-2-u4-C5","difficulty":1,"kind":"ox","stem":"「눈썰미」처럼 고유어를 이어 붙여 만든 낱말도 고유어예요.","answer":"O","reason_options":[{"t":"고유어를 바탕으로 만들어진 낱말도 고유어이기 때문에","correct":true},{"t":"처음부터 있던 낱말만 고유어이기 때문에","mis":"K6-2-u4-X06"}],"mis":"K6-2-u4-X06","explanation":["고유어에는 두 모습이 있어요.","처음부터 있던 낱말과 그것으로 만든 낱말이에요.","눈썰미는 만든 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#5','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C7',1,'mc','auto','「낯을 가리다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"mc","stem":"「낯을 가리다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"낯선 사람을 어려워하다","correct":true},{"t":"얼굴을 손으로 가리다","mis":"K6-2-u4-X09"},{"t":"음식을 가려 먹다","mis":"K6-2-u4-X09"},{"t":"부끄러워 화를 내다","mis":"K6-2-u4-X09"}],"explanation":["관용 표현은 낱말 뜻을 그대로 더하지 않아요.","두 낱말이 어울려 새 뜻을 만들어요.","낯을 가리다는 낯선 사람을 어려워한다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#6','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C10',1,'ox','auto','발표 자료는 정해진 시간에 전할 수 있는 만큼만 담아요.',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":6,"concept":"K6-2-u4-C10","difficulty":1,"kind":"ox","stem":"발표 자료는 정해진 시간에 전할 수 있는 만큼만 담아요.","answer":"O","reason_options":[{"t":"너무 많으면 듣는 사람이 이해하기 어렵기 때문에","correct":true},{"t":"자료가 많을수록 좋은 발표이기 때문에","mis":"K6-2-u4-X13"}],"mis":"K6-2-u4-X13","explanation":["발표 시간은 정해져 있어요.","너무 많으면 전하지 못해요.","이해에 도움이 되는 만큼 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#7','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',1,'ox','auto','표준어와 방언 사이에도 등수는 없어요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"ox","stem":"표준어와 방언 사이에도 등수는 없어요.","answer":"O","reason_options":[{"t":"둘 다 소중한 우리말이고 쓰이는 자리가 다를 뿐이기 때문에","correct":true},{"t":"표준어가 더 바른 말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["갈래에 등수가 없듯이 표준어와 방언도 그래요.","쓰이는 자리가 다를 뿐이에요.","둘 다 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#8','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',1,'ox','auto','우리말 홍보물에는 알릴 내용이 먼저이고 꾸밈은 그다음이에요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":8,"concept":"K6-2-u4-C16","difficulty":1,"kind":"ox","stem":"우리말 홍보물에는 알릴 내용이 먼저이고 꾸밈은 그다음이에요.","answer":"O","reason_options":[{"t":"보는 사람이 무엇을 알게 되고 무엇을 할지가 드러나야 하기 때문에","correct":true},{"t":"꾸밈이 화려해야 사람들이 내용을 읽기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["꾸미는 데 시간을 다 쓰면 내용이 가려져요.","알릴 것이 한눈에 보여야 해요.","꾸밈은 그다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#9','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C9',2,'ox','auto','시우네 모둠은 「다온 마을」의 뜻을 「짐작했습니다」나 「아직 확인하지 못했습니다」라고 밝혀야 해요.',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":9,"concept":"K6-2-u4-C9","difficulty":2,"kind":"ox","stem":"시우네 모둠은 「다온 마을」의 뜻을 「짐작했습니다」나 「아직 확인하지 못했습니다」라고 밝혀야 해요.","answer":"O","reason_options":[{"t":"확인한 것과 짐작한 것을 섞으면 듣는 사람이 잘못 알 수 있기 때문에","correct":true},{"t":"그럴듯한 뜻이면 확인한 것처럼 말해도 되기 때문에","mis":"K6-2-u4-X12"}],"mis":"K6-2-u4-X12","explanation":["다온 마을의 뜻에는 출처가 없어요.","확인한 것처럼 말하면 안 돼요.","짐작이면 짐작이라고 밝혀요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#10','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C10',2,'mc','auto','시우네 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"시우네 발표를 듣고 한 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「‘솔바람길’에 지금도 소나무가 많은지 궁금해요. 이름의 뜻이 지금 모습과 맞는지 알고 싶어서요.」","correct":true},{"t":"「그냥 물어봤어요.」","mis":"K6-2-u4-X14"},{"t":"「우리 모둠이 더 잘하지 않았나요?」","mis":"K6-2-u4-X14"},{"t":"「발표가 언제 끝나요?」","mis":"K6-2-u4-X14"}],"explanation":["발표 내용을 정리하며 들어요.","궁금한 점과 까닭을 함께 말해요.","그래야 묻고 답하며 이야기가 이어져요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#11','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',2,'sa','auto','외할머니가 말한 「가새」는 표준어로 무엇일까요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"K6-2-u4-C13","difficulty":2,"kind":"sa","stem":"외할머니가 말한 「가새」는 표준어로 무엇일까요? 두 글자로 쓰세요.","answer":["가위"],"explanation":["「가새는 저 서랍에 있다」고 하셨어요.","서윤이는 서랍 속 가위를 보았어요.","가새는 가위를 가리키는 고장 말이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"},"mis":"K6-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#12','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C11',2,'ox','auto','외할머니의 수첩은 우리말을 지키려는 노력과 닮았어요.',ARRAY['K6-2-u4-X15']::text[],false,'{"seq":12,"concept":"K6-2-u4-C11","difficulty":2,"kind":"ox","stem":"외할머니의 수첩은 우리말을 지키려는 노력과 닮았어요.","answer":"O","reason_options":[{"t":"사라질 수 있는 고장 말을 생각날 때마다 모아 적어 두었기 때문에","correct":true},{"t":"수첩이 오래되어 귀한 물건이기 때문에","mis":"K6-2-u4-X15"}],"mis":"K6-2-u4-X15","explanation":["외할머니는 동네 말을 적어 두셨어요.","적어 두어야 말이 남아요.","우리말 사전을 만든 노력과 닮았어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#13','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',2,'ox','auto','지후의 「오늘부터 외래어를 하나도 쓰지 않겠습니다」는 지킬 수 있는 다짐이에요.',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"ox","stem":"지후의 「오늘부터 외래어를 하나도 쓰지 않겠습니다」는 지킬 수 있는 다짐이에요.","answer":"X","reason_options":[{"t":"버스 · 컴퓨터처럼 바꿀 말이 마땅치 않은 외래어도 있어 지킬 수 없는 크기이기 때문에","correct":true},{"t":"외래어를 쓰지 않는 것이 우리말을 지키는 길이기 때문에","mis":"K6-2-u4-X02"}],"mis":"K6-2-u4-X02","explanation":["외래어도 우리말의 한 갈래예요.","바꿀 말이 없는 외래어도 많아요.","지킬 수 없는 크기의 다짐이에요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#14','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',2,'ox','auto','하람이네가 역할을 정하지 않고 꾸미기부터 시작한 것은 괜찮아요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"ox","stem":"하람이네가 역할을 정하지 않고 꾸미기부터 시작한 것은 괜찮아요.","answer":"X","reason_options":[{"t":"역할을 먼저 나누어야 빠지는 사람 없이 함께할 수 있기 때문에","correct":true},{"t":"꾸미기를 먼저 해야 알릴 내용이 정해지기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["계획은 주제 · 내용 · 역할 · 시간이에요.","역할을 먼저 나누어요.","꾸밈은 내용 다음이에요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#15','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C5',2,'sa','auto','「비 그친 아침」에서 물살이 세게 흐르는 얕은 곳을 가리키는 고유어를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"sa","stem":"「비 그친 아침」에서 물살이 세게 흐르는 얕은 곳을 가리키는 고유어를 두 글자로 쓰세요.","answer":["여울"],"explanation":["개울이 불어 생긴 곳이에요.","돌 사이로 소리를 내요.","그곳이 여울이에요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"},"mis":"K6-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#16','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C17',2,'ox','auto','「증발」 · 「지형」 · 「분포」 · 「관측」은 모두 고유어예요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":16,"concept":"K6-2-u4-C17","difficulty":2,"kind":"ox","stem":"「증발」 · 「지형」 · 「분포」 · 「관측」은 모두 고유어예요.","answer":"X","reason_options":[{"t":"모두 한자로 이루어진 한자어이기 때문에","correct":true},{"t":"교과서에 자주 나오기 때문에","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["네 낱말은 모두 한자로 되어 있어요.","그래서 한자어예요.","자주 나온다고 고유어가 되지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#17','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C8',3,'ox','auto','시우네 표에서 고유어를 활용한 사례라고 확실히 말할 수 있는 것은 솔바람길과 한아름 꽃집이에요.',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":17,"concept":"K6-2-u4-C8","difficulty":3,"kind":"ox","stem":"시우네 표에서 고유어를 활용한 사례라고 확실히 말할 수 있는 것은 솔바람길과 한아름 꽃집이에요.","answer":"O","reason_options":[{"t":"두 이름은 낱말을 나누어 고유어를 찾고 확인한 곳까지 밝혔기 때문에","correct":true},{"t":"다온 마을과 스마일 마트도 이름이 예뻐서 모두 고유어 사례이기 때문에","mis":"K6-2-u4-X10"}],"mis":"K6-2-u4-X10","explanation":["솔바람길 · 한아름 꽃집은 확인이 되었어요.","다온 마을은 뜻의 출처가 없어요.","스마일 마트는 고유어가 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#18','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C12',3,'ox','auto','「다음은 누가?」는 글에 적힌 단서이고, 「서윤이가 이어 적기를 바라셨다」는 추론한 내용이에요.',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"ox","stem":"「다음은 누가?」는 글에 적힌 단서이고, 「서윤이가 이어 적기를 바라셨다」는 추론한 내용이에요.","answer":"O","reason_options":[{"t":"글에 적힌 것과 단서로 메운 생각을 가를 수 있기 때문에","correct":true},{"t":"둘 다 글에 그대로 적혀 있기 때문에","mis":"K6-2-u4-X17"}],"mis":"K6-2-u4-X17","explanation":["「다음은 누가?」는 글에 있어요.","외할머니의 바람은 글에 없어요.","단서로 메운 것이 추론이에요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#19','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',3,'ox','auto','지후의 다짐문에는 잘 쓴 부분이 하나도 없어요.',ARRAY['K6-2-u4-X24']::text[],false,'{"seq":19,"concept":"K6-2-u4-C15","difficulty":3,"kind":"ox","stem":"지후의 다짐문에는 잘 쓴 부분이 하나도 없어요.","answer":"X","reason_options":[{"t":"넷째 줄은 지킬 수 있는 다짐이고 날짜와 쓴 사람도 갖추었기 때문에","correct":true},{"t":"고칠 점이 있으면 잘 쓴 부분은 말하지 않아도 되기 때문에","mis":"K6-2-u4-X24"}],"mis":"K6-2-u4-X24","explanation":["잘 쓴 부분을 먼저 찾아요.","넷째 줄과 마지막 줄은 잘 썼어요.","고칠 점은 그다음에 말해요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#20','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',3,'ox','auto','하람이네 홍보 문구는 알리려는 내용과 앞뒤가 맞아요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"ox","stem":"하람이네 홍보 문구는 알리려는 내용과 앞뒤가 맞아요.","answer":"X","reason_options":[{"t":"쉬운 우리말을 알리면서 문구는 외국어로 썼기 때문에","correct":true},{"t":"외국어를 섞어야 사람들이 관심을 갖기 때문에","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["주제는 쉬운 우리말로 바꾸어 말하기예요.","그런데 문구가 외국어예요.","앞뒤가 맞지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#21','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',3,'error','auto','방언에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X20']::text[],false,'{"seq":21,"concept":"K6-2-u4-C13","difficulty":3,"kind":"error","stem":"방언에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「‘가새’라고 하는 사람은 우리말을 잘못 배운 거야.」","correct":true,"mis_target":"K6-2-u4-X19"},{"t":"리아 — 「다른 고장의 말을 웃음거리로 삼지 말자.」","mis":"K6-2-u4-X19"},{"t":"선우 — 「공식적인 자리에서는 표준어로 말하자.」","mis":"K6-2-u4-X20"}],"explanation":["리아와 선우는 방언과 표준어의 자리를 알아요.","태윤은 방언을 잘못 배운 말로 여겼어요.","방언도 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#22','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C6',3,'error','auto','다듬은 말에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":22,"concept":"K6-2-u4-C6","difficulty":3,"kind":"error","stem":"다듬은 말에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하온 — 「‘학교’와 ‘수학’도 한자어니까 다듬어서 바꾸어야 해.」","correct":true,"mis_target":"K6-2-u4-X08"},{"t":"지유 — 「‘회람’은 ‘돌려보기’로 다듬으면 뜻이 잘 드러나.」","mis":"K6-2-u4-X08"},{"t":"준후 — 「다듬는 목적은 누구나 알아들을 수 있게 하는 거야.」","mis":"K6-2-u4-X08"}],"explanation":["지유와 준후는 다듬기를 바르게 말했어요.","하온은 모든 한자어를 바꾸려 했어요.","학교 · 수학은 그대로 쓰는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#23','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',4,'mc','auto','지후의 다짐문을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X23']::text[],false,'{"seq":23,"concept":"K6-2-u4-C15","difficulty":4,"kind":"mc","stem":"지후의 다짐문을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"목적 줄을 맨 앞에 넣고, 막연하거나 너무 크거나 내 일이 없는 줄은 언제 · 무엇을 할지 드러나게 고치고, 넷째 줄과 날짜 · 쓴 사람은 살린다","correct":true},{"t":"모두 지우고 처음부터 새로 쓴다","mis":"K6-2-u4-X24"},{"t":"글씨를 반듯하게 쓰고 종이를 바꾼다","mis":"K6-2-u4-X24"},{"t":"「다들」을 「꼭」으로 바꾸어 더 세게 쓴다","mis":"K6-2-u4-X23"}],"explanation":["살릴 것을 먼저 정해요.","빠진 목적을 넣어요.","고칠 줄은 지킬 수 있게 고쳐요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#24','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',4,'essay','teacher','지후의 다짐문에서 잘 쓴 부분과 고칠 부분을 하나씩 쓰고, 빠진 부분을 넣어 지킬 수 있는 다짐문으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C15","difficulty":4,"kind":"essay","stem":"지후의 다짐문에서 잘 쓴 부분과 고칠 부분을 하나씩 쓰고, 빠진 부분을 넣어 지킬 수 있는 다짐문으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 잘 쓴 부분 — 「쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다」는 언제 무엇을 할지가 드러나 지킬 수 있다. 고칠 부분 — 「다들 줄인 말을 쓰지 맙시다」는 내가 할 일이 없다. 고쳐 쓴 다짐문 — 나는 친구들과 서로 잘 알아듣는 말을 쓰기 위해 다음과 같이 다짐합니다. 하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다. 하나, 나는 모둠 활동에서 줄인 말을 쓰면 바로 풀어서 다시 말하겠습니다. 모두 함께 우리말을 지켜 주세요. 쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후.","scoring_points":["잘 쓴 부분을 먼저 찾았는가","고칠 부분을 내용에서 찾았는가","목적을 넣고 네 부분을 갖추어 지킬 수 있게 고쳐 썼는가"]},"explanation":["잘 쓴 곳 먼저.","빠진 목적을 넣어요.","언제 · 무엇을 · 내가."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_c#25','kor',6,2,'u4','','g6_2_kor_u4_review_c','unit_review','K6-2-u4-C2',4,'essay','teacher','이 단원에서 배운 말로 「우리말을 바르게 쓴다는 것」을 설명하고, 앞으로 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 말로 「우리말을 바르게 쓴다는 것」을 설명하고, 앞으로 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 우리말을 바르게 쓴다는 것은 고유어만 쓰거나 다른 갈래를 몰아내는 것이 아니라, 듣는 사람이 알아들을 수 있게, 뜻에 맞게, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어, 상황에 맞게 골라 쓰는 것이다. 다짐 — 나는 모둠 활동을 할 때 교실에서 친구가 못 알아들은 말을 한 번 더 풀어 말하겠다.","scoring_points":["고유어만 쓰는 것이 아님을 밝혔는가","바르게 쓰기의 뜻을 단원의 말로 설명했는가","언제 · 어디에서 · 무엇을이 담긴 다짐을 썼는가"]},"explanation":["몰아내기가 아니에요.","알아듣게, 뜻에 맞게, 상황에 맞게.","다짐은 지킬 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#1','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C1',1,'mc','auto','고유어끼리 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"고유어끼리 모은 것은 어느 것인가요?","options":[{"t":"이슬 · 두둑 · 나들이","correct":true},{"t":"채소 · 체육 · 학교","mis":"K6-2-u4-X01"},{"t":"버튼 · 버스 · 토마토","mis":"K6-2-u4-X01"},{"t":"이슬 · 체육 · 버튼","mis":"K6-2-u4-X01"}],"explanation":["채소 · 체육 · 학교는 한자어예요.","버튼 · 버스 · 토마토는 외래어예요.","이슬 · 두둑 · 나들이가 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#2','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C6',1,'mc','auto','낱말의 세 갈래에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K6-2-u4-X07']::text[],false,'{"seq":2,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"낱말의 세 갈래에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 갈래가 함께 우리말을 이루고 하는 일이 다르다","correct":true},{"t":"고유어는 좋은 말, 한자어와 외래어는 나쁜 말이다","mis":"K6-2-u4-X07"},{"t":"외래어가 가장 새롭고 좋은 말이다","mis":"K6-2-u4-X07"},{"t":"한자어가 가장 어려워 훌륭한 말이다","mis":"K6-2-u4-X07"}],"explanation":["갈래에는 등수가 없어요.","각 갈래가 하는 일이 달라요.","세 갈래가 함께 우리말을 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#3','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C3',1,'mc','auto','「모둠 회의 어젠다를 셰어할게.」라는 말의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"「모둠 회의 어젠다를 셰어할게.」라는 말의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"쉬운 우리말이 있는데도 어렵게 쓴 외국어라 알아듣기 어렵다","correct":true},{"t":"지나치게 줄인 말이다","mis":"K6-2-u4-X04"},{"t":"기분을 상하게 하는 말이다","mis":"K6-2-u4-X04"},{"t":"아무 문제가 없다","mis":"K6-2-u4-X03"}],"explanation":["「회의할 거리를 나눌게」라고 해도 통해요.","쉬운 말을 두고 외국어를 썼어요.","그래서 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#4','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C5',1,'mc','auto','고유어의 두 모습을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X06']::text[],false,'{"seq":4,"concept":"K6-2-u4-C5","difficulty":1,"kind":"mc","stem":"고유어의 두 모습을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"처음부터 있던 낱말 — 이슬 · 호미 / 바탕으로 만든 낱말 — 나들이 · 마중물","correct":true},{"t":"처음부터 있던 낱말 — 채소 · 토마토 / 바탕으로 만든 낱말 — 이슬","mis":"K6-2-u4-X01"},{"t":"처음부터 있던 낱말 — 마중물 / 바탕으로 만든 낱말 — 버튼","mis":"K6-2-u4-X01"},{"t":"고유어는 처음부터 있던 낱말 한 가지뿐이다","mis":"K6-2-u4-X06"}],"explanation":["이슬 · 호미는 처음부터 있던 말이에요.","나들이 · 마중물은 이어 붙여 만든 말이에요.","둘 다 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#5','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C7',1,'ox','auto','「입이 짧다」는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요.',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"ox","stem":"「입이 짧다」는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요.","answer":"O","reason_options":[{"t":"둘 이상의 낱말이 어울려 새로운 뜻을 만드는 관용 표현이기 때문에","correct":true},{"t":"입의 생김새를 그대로 말한 것이기 때문에","mis":"K6-2-u4-X09"}],"mis":"K6-2-u4-X09","explanation":["입의 길이를 말하는 것이 아니에요.","두 낱말이 어울려 새 뜻을 만들어요.","관용 표현에는 우리 문화와 정서가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#6','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C9',1,'mc','auto','「아직 확인하지 못했습니다」라고 말해야 할 때는 언제인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":6,"concept":"K6-2-u4-C9","difficulty":1,"kind":"mc","stem":"「아직 확인하지 못했습니다」라고 말해야 할 때는 언제인가요?","options":[{"t":"사전과 누리집을 찾아보고 어른께 여쭈어도 뜻을 알지 못했을 때","correct":true},{"t":"사전에서 뜻을 찾았을 때","mis":"K6-2-u4-X12"},{"t":"뜻을 짐작했을 때","mis":"K6-2-u4-X12"},{"t":"친구가 뜻을 알려 주었을 때","mis":"K6-2-u4-X12"}],"explanation":["찾은 뜻은 「찾은 뜻입니다」라고 말해요.","짐작은 「짐작했습니다」라고 말해요.","알아내지 못하면 「아직 확인하지 못했습니다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#7','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C13',1,'match','auto','고장에 따라 쓰는 말과 같은 뜻의 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"match","stem":"고장에 따라 쓰는 말과 같은 뜻의 표준어를 알맞게 이으세요.","pairs":[{"l":"정구지","r":"부추"},{"l":"가새","r":"가위"},{"l":"정지","r":"부엌"}],"mis":"K6-2-u4-X19","explanation":["같은 것을 고장마다 다르게 불러요.","정구지는 부추, 가새는 가위예요.","정지는 부엌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#8','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',1,'mc','auto','언어생활을 바르게 점검하는 모습은 어느 것인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":8,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"언어생활을 바르게 점검하는 모습은 어느 것인가요?","options":[{"t":"내가 쓴 말부터 적고, 고칠 점을 우리 반의 일로 말한다","correct":true},{"t":"친구가 쓴 말을 흉내 내며 적는다","mis":"K6-2-u4-X21"},{"t":"누가 더 많이 썼는지 세어 견준다","mis":"K6-2-u4-X21"},{"t":"점검표를 친구에게 증거처럼 내민다","mis":"K6-2-u4-X21"}],"explanation":["점검은 흠잡기가 아니에요.","내가 쓴 말부터 적어요.","바라는 점을 함께 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#9','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C8',2,'mc','auto','시우네 표의 「스마일 마트」를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X10','K6-2-u4-X12','K6-2-u4-X01']::text[],false,'{"seq":9,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"시우네 표의 「스마일 마트」를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"고유어가 들어간 다른 가게 이름을 찾아 바꾸어 넣는다","correct":true},{"t":"「스마일」을 고유어라고 그대로 둔다","mis":"K6-2-u4-X10"},{"t":"뜻 칸만 지운다","mis":"K6-2-u4-X12"},{"t":"영어 사전에서 확인했으니 그대로 둔다","mis":"K6-2-u4-X01"}],"explanation":["스마일은 고유어가 아니에요.","확인한 곳을 밝혀도 갈래는 바뀌지 않아요.","고유어가 들어간 이름으로 바꾸어요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#10','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C9',2,'mc','auto','시우네가 「한아름」의 뜻을 국어사전에서 확인한 것이 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X14','K6-2-u4-X12']::text[],false,'{"seq":10,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우네가 「한아름」의 뜻을 국어사전에서 확인한 것이 좋은 까닭은 어느 것인가요?","options":[{"t":"짐작이 아니라 확인한 뜻을 전할 수 있어서","correct":true},{"t":"사전 뜻은 꾸미기 좋아서","mis":"K6-2-u4-X13"},{"t":"다른 모둠보다 먼저 찾아서","mis":"K6-2-u4-X14"},{"t":"글자 모양을 보니 맞는 것 같아서","mis":"K6-2-u4-X12"}],"explanation":["확인한 뜻은 믿을 수 있어요.","출처도 함께 밝혔어요.","듣는 사람이 다시 확인할 수 있어요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#11','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',2,'ox','auto','외할머니가 연필을 서윤이 쪽으로 밀어 주신 것은 아무 뜻이 없어요.',ARRAY['K6-2-u4-X17']::text[],false,'{"seq":11,"concept":"K6-2-u4-C12","difficulty":2,"kind":"ox","stem":"외할머니가 연필을 서윤이 쪽으로 밀어 주신 것은 아무 뜻이 없어요.","answer":"X","reason_options":[{"t":"「다음은 누가?」라는 끝 장과 이어 보면 서윤이가 이어 적기를 바라셨다고 추론할 수 있기 때문에","correct":true},{"t":"글에 그렇게 적혀 있지 않으면 아무것도 알 수 없기 때문에","mis":"K6-2-u4-X17"}],"mis":"K6-2-u4-X17","explanation":["글쓴이는 모든 것을 다 적지 않아요.","끝 장의 물음과 연필을 이어 봐요.","적히지 않은 마음을 단서로 메워요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#12','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',2,'mc','auto','서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서는 어느 것인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X16']::text[],false,'{"seq":12,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"서윤이가 「정구지」의 뜻을 짐작할 수 있었던 단서는 어느 것인가요?","options":[{"t":"「씻어 오너라」라는 말과 바구니에 담긴 초록 채소","correct":true},{"t":"「정구지」라는 글자의 모양","mis":"K6-2-u4-X18"},{"t":"그냥 그럴 것 같은 느낌","mis":"K6-2-u4-X16"},{"t":"외할머니의 옷차림","mis":"K6-2-u4-X16"}],"explanation":["씻어 오라는 말은 먹을 것을 가리켜요.","눈앞에는 초록 채소가 있었어요.","앞뒤 말과 장면이 단서예요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#13','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C15',2,'mc','auto','지후의 「다들 줄인 말을 쓰지 맙시다」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u4-X23','K6-2-u4-X21']::text[],false,'{"seq":13,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"지후의 「다들 줄인 말을 쓰지 맙시다」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「나는 모둠 활동에서 줄인 말을 쓰면 바로 풀어서 다시 말하겠습니다.」","correct":true},{"t":"「모두 줄인 말을 절대로 쓰지 맙시다.」","mis":"K6-2-u4-X23"},{"t":"「줄인 말을 쓰는 친구를 알려 주세요.」","mis":"K6-2-u4-X21"},{"t":"「줄인 말은 나쁜 말입니다.」","mis":"K6-2-u4-X23"}],"explanation":["실천 약속은 내가 할 일이에요.","언제 · 무엇을 할지 넣어요.","친구를 가려내는 일이 아니에요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#14','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',2,'mc','auto','하람이네의 「금요일에 붙이고 그날로 마침」을 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":14,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"하람이네의 「금요일에 붙이고 그날로 마침」을 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"붙인 뒤에도 한 주 동안 지킴이 도전을 이어 한다","correct":true},{"t":"붙이는 날을 더 크게 꾸민다","mis":"K6-2-u4-X26"},{"t":"붙인 날 사진을 찍어 남기고 마친다","mis":"K6-2-u4-X26"},{"t":"붙인 홍보물을 다음 날 떼어 낸다","mis":"K6-2-u4-X26"}],"explanation":["하루로 끝나면 행사예요.","이어서 해야 실천이에요.","지킴이 도전처럼 이어 해요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#15','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C5',2,'ox','auto','「비 그친 아침」은 고유어를 써서 느낌과 장면을 살렸어요.',ARRAY['K6-2-u4-X07']::text[],false,'{"seq":15,"concept":"K6-2-u4-C5","difficulty":2,"kind":"ox","stem":"「비 그친 아침」은 고유어를 써서 느낌과 장면을 살렸어요.","answer":"O","reason_options":[{"t":"여울 · 오솔길 · 조롱조롱처럼 장면과 느낌을 그대로 담은 낱말을 썼기 때문에","correct":true},{"t":"고유어만 쓴 글이 가장 훌륭한 글이기 때문에","mis":"K6-2-u4-X07"}],"mis":"K6-2-u4-X07","explanation":["조롱조롱은 이슬 맺힌 모습을 그려요.","여울 · 오솔길은 장면을 담아요.","훌륭함의 등수를 말하는 것은 아니에요."],"asset":{"type":"passage","lines":["밤새 내린 비에 / 개울이 불었다.","어제는 없던 여울이 / 돌 사이로 소리를 낸다.","오솔길 풀잎마다 / 이슬이 조롱조롱.","어스름에 잠겼던 마을이 / 천천히 깨어난다.","바람 한 줄기에 / 잔물결이 반짝인다.","이름을 알고 보니 / 모두 다르게 보인다."],"title":"시 「비 그친 아침」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#16','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C17',2,'sa','auto','「자연 현상을 살펴 재거나 헤아리는 일」을 뜻하는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u4-C17","difficulty":2,"kind":"sa","stem":"「자연 현상을 살펴 재거나 헤아리는 일」을 뜻하는 낱말을 두 글자로 쓰세요.","answer":["관측"],"explanation":["하늘이나 날씨를 살펴 재는 일이에요.","과학 시간에 자주 나와요.","그 낱말이 관측이에요."],"mis":"K6-2-u4-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#17','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C9',3,'mc','auto','시우네가 「다온 마을」 칸을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X12','K6-2-u4-X11']::text[],false,'{"seq":17,"concept":"K6-2-u4-C9","difficulty":3,"kind":"mc","stem":"시우네가 「다온 마을」 칸을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사전에서 찾고 동네 어른께 여쭈어 확인하고, 그래도 모르면 「아직 확인하지 못했습니다」라고 밝힌다","correct":true},{"t":"더 그럴듯한 뜻으로 바꾸어 쓴다","mis":"K6-2-u4-X12"},{"t":"출처 칸에 「국어사전」이라고 적어 둔다","mis":"K6-2-u4-X12"},{"t":"동네 이름은 너무 많으니 조사하지 않는다","mis":"K6-2-u4-X11"}],"explanation":["짐작은 확인으로 이어 가요.","확인하지 못하면 그렇게 말해요.","찾지 않은 출처를 적지 않아요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#18','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',3,'match','auto','서윤이 이야기의 단서와 추론한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"K6-2-u4-C12","difficulty":3,"kind":"match","stem":"서윤이 이야기의 단서와 추론한 내용을 알맞게 이으세요.","pairs":[{"l":"「씻어 오너라」와 바구니의 초록 채소","r":"정구지는 채소 이름일 것이다"},{"l":"「서랍에 있다」와 서랍 속 가위","r":"가새는 가위를 가리킬 것이다"},{"l":"끝 장의 「다음은 누가?」와 밀어 준 연필","r":"이어 적기를 바라셨을 것이다"}],"mis":"K6-2-u4-X16","explanation":["말과 장면을 함께 봐요.","단서마다 알 수 있는 것이 달라요.","까닭은 늘 글 안에 있어요."],"asset":{"type":"passage","lines":["방학 첫날, 서윤이는 외할머니 댁 부엌에서 저녁 준비를 거들었다.","「서윤아, 정구지 좀 씻어 오너라. 가새는 저 서랍에 있다.」","서윤이는 바구니에 담긴 초록 채소와 서랍 속 가위를 번갈아 보았다.","저녁을 먹고 나서 외할머니는 서랍에서 손때 묻은 수첩을 꺼내셨다.","「이 동네 말을 생각날 때마다 적어 두었지. 잘 갈무리해 두었더니 아직 멀쩡하구나.」","수첩 맨 끝 장에는 「다음은 누가?」라고만 적혀 있었다.","외할머니는 연필 한 자루를 수첩 위에 올려놓고 서윤이 쪽으로 밀어 주셨다."],"title":"서윤이 이야기 「다음은 누가?」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#19','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C2',3,'mc','auto','지후의 셋째 줄 「오늘부터 외래어를 하나도 쓰지 않겠습니다」를 고쳐야 하는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X24','K6-2-u4-X07']::text[],false,'{"seq":19,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"지후의 셋째 줄 「오늘부터 외래어를 하나도 쓰지 않겠습니다」를 고쳐야 하는 까닭은 어느 것인가요?","options":[{"t":"외래어를 몰아내는 것은 단원의 약속과 맞지 않고 지킬 수도 없어서","correct":true},{"t":"외래어 대신 한자어만 쓰면 되어서","mis":"K6-2-u4-X02"},{"t":"줄이 너무 길어서","mis":"K6-2-u4-X24"},{"t":"외래어는 나쁜 말이라 더 세게 다짐해야 해서","mis":"K6-2-u4-X07"}],"explanation":["바르게 쓰기는 몰아내기가 아니에요.","바꿀 수 있는 말만 쉬운 말로 바꿔요.","버스 · 컴퓨터는 그대로 써요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","하나, 나는 앞으로 우리말을 아주 열심히 사랑하겠습니다.","하나, 나는 오늘부터 외래어를 하나도 쓰지 않겠습니다.","하나, 다들 줄인 말을 쓰지 맙시다.","하나, 나는 쉬는 시간에 친구가 모르는 말을 물으면 쉬운 말로 풀어 주겠습니다.","모두 함께 우리말을 지켜 주세요.","쓴 날 — 시월 둘째 주 월요일 · 쓴 사람 — 지후"],"title":"지후가 쓴 실천 다짐문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#20','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',3,'mc','auto','하람이네 계획에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":20,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"하람이네 계획에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 · 내용 · 시간은 정했지만 역할은 정하지 않았다","correct":true},{"t":"주제만 정하고 나머지는 정하지 않았다","mis":"K6-2-u4-X25"},{"t":"네 가지를 모두 빠짐없이 정했다","mis":"K6-2-u4-X25"},{"t":"역할만 정하고 나머지는 정하지 않았다","mis":"K6-2-u4-X25"}],"explanation":["주제 · 내용 · 시간 줄이 있어요.","역할은 「아직 정하지 않음」이에요.","역할을 먼저 정해야 해요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#21','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C11',3,'mc','auto','우리말을 지키기 위해 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X19','K6-2-u4-X15']::text[],false,'{"seq":21,"concept":"K6-2-u4-C11","difficulty":3,"kind":"mc","stem":"우리말을 지키기 위해 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻을 모르는 낱말은 사전에서 확인하고, 고장 말은 어른께 여쭈어 적어 둔다","correct":true},{"t":"외래어를 모두 고유어로 바꾼다","mis":"K6-2-u4-X02"},{"t":"고장 말을 모두 표준어로 고쳐 쓴다","mis":"K6-2-u4-X19"},{"t":"말은 저절로 남으니 그대로 둔다","mis":"K6-2-u4-X15"}],"explanation":["사전에서 확인하기는 지키는 일이에요.","고장 말을 여쭈어 적는 것도 그래요.","몰아내거나 내버려 두는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#22','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',3,'mc','auto','언어생활을 바꾸어 가는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X23','K6-2-u4-X26']::text[],false,'{"seq":22,"concept":"K6-2-u4-C14","difficulty":3,"kind":"mc","stem":"언어생활을 바꾸어 가는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 쓴 말 점검 → 지킬 수 있는 다짐 → 실천 뒤 변화한 점과 노력할 점 되돌아보기","correct":true},{"t":"친구 말 세기 → 가장 많이 쓴 친구 발표 → 끝","mis":"K6-2-u4-X21"},{"t":"크게 말하는 다짐 → 바로 끝","mis":"K6-2-u4-X23"},{"t":"홍보물 하루 붙이기 → 끝","mis":"K6-2-u4-X26"}],"explanation":["먼저 내 말을 살펴요.","지킬 수 있는 다짐을 해요.","되돌아보고 다시 해 보는 것까지가 실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#23','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',4,'mc','auto','하람이네 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X27','K6-2-u4-X26']::text[],false,'{"seq":23,"concept":"K6-2-u4-C16","difficulty":4,"kind":"mc","stem":"하람이네 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문구를 쉬운 우리말로 바꾸고, 꾸미기 전에 역할을 나누고, 붙인 뒤 한 주 동안 지킴이 도전을 이어 한다","correct":true},{"t":"문구는 그대로 두고 꾸밈을 더 화려하게 한다","mis":"K6-2-u4-X25"},{"t":"인쇄물 대신 한 번 틀고 마는 영상으로 바꾼다","mis":"K6-2-u4-X27"},{"t":"붙이는 날 하루만 우리말을 쓰기로 한다","mis":"K6-2-u4-X26"}],"explanation":["문구 · 역할 · 시간을 고쳐요.","내용과 방법은 그대로 살려요.","하루로 끝내지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#24','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',4,'essay','teacher','하람이네 홍보물 계획에서 잘된 점 하나와 고칠 점 세 가지를 쓰고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"하람이네 홍보물 계획에서 잘된 점 하나와 고칠 점 세 가지를 쓰고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 잘된 점 — 바꾸면 좋은 말을 알리려고 오래 붙여 두고 여러 번 보게 하는 인쇄물을 골라 내용과 방법이 잘 맞는다. 고칠 점 — 홍보 문구가 외국어라 알리려는 내용과 앞뒤가 맞지 않는다. 역할을 정하지 않고 꾸미기부터 시작했다. 붙인 날로 끝나 하루 행사가 된다. 고칠 방법 — 문구를 「쉬운 우리말로 한 번 바꾸어 말해 볼까요?」로 바꾸고, 낱말 찾기 · 글씨 쓰기 역할을 먼저 나누고, 붙인 뒤 한 주 동안 지킴이 도전을 이어 한다.","scoring_points":["잘된 점을 먼저 썼는가","문구 · 역할 · 시간의 고칠 점을 썼는가","고칠 방법을 구체적으로 썼는가"]},"explanation":["내용과 방법은 잘 맞아요.","문구 · 역할 · 시간을 고쳐요.","하루로 끝내지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u4_review_d#25','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C17',4,'essay','teacher','「관측」과 「증발」의 뜻을 쓰고, 두 낱말을 모두 넣어 과학 시간에 있을 법한 일을 두 문장으로 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C17","difficulty":4,"kind":"essay","stem":"「관측」과 「증발」의 뜻을 쓰고, 두 낱말을 모두 넣어 과학 시간에 있을 법한 일을 두 문장으로 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 관측 — 자연 현상을 살펴 재거나 헤아리는 일. 증발 — 액체가 그 표면에서 기체로 변하는 현상. 문장 — 「우리 모둠은 창가에 둔 물그릇을 날마다 같은 시각에 관측했다. 날이 갈수록 물이 증발해서 그릇 속 물이 줄어들었다.」","scoring_points":["두 낱말의 뜻을 바르게 썼는가","두 낱말을 뜻에 맞게 넣어 문장을 썼는가","숫자 없이 있을 법한 일로 썼는가"]},"explanation":["뜻을 정확히 알아 둬요.","문장으로 써 보면 오래 남아요.","교과서에서 다시 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C1','kor',6,2,'u5',1,'음성 언어와 문자 언어 — 음성 언어는 음성으로 나타내는 말로 듣는 사람 앞에서 바로 전해지고, 문자 언어는 글자로 나타내는 말로 적어 두면 다시 볼 수 있으며, 두 언어는 등수를 매기는 사이가 아니라 알맞은 곳이 서로 다를 뿐이다',ARRAY['6국04 문법(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C2','kor',6,2,'u5',1,'특성은 규칙이 아니라 기본 성질 — 말은 보통 그 자리에서 사라지고 글은 보통 오래 남지만 매체에 따라 달라져(녹음한 말은 남고, 빠르게 지나가는 대화 글·잠깐 뜨는 알림·넘기면 없어지는 자막은 흘러감) 「언제나」로 외우지 않고 이 매체에서는 어떻게 되는지를 그때그때 살핀다',ARRAY['6국04 문법(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C3','kor',6,2,'u5',1,'매체 자료의 세 갈래 — 인쇄 매체는 문자 언어를 바탕으로 표·그림·사진을, 음성 매체는 음성 언어를 바탕으로 소리·음악을, 영상 매체는 음성 언어·문자 언어·그림·소리·움직임을 어울러 쓰며, 더 나은 매체는 없고 전하려는 내용과 받는 사람에 따라 알맞은 매체가 달라진다',ARRAY['6국06 매체(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C4','kor',6,2,'u5',2,'문자 언어의 표현 특성 — 적은 내용이 그대로 남아 필요할 때 다시 볼 수 있고, 여러 사람이 똑같은 내용을 정확하게 나누어 가지며, 글자의 크기·굵기·문장 부호·줄 나눔으로 중요한 곳을 눈에 보이게 하고, 천천히 생각하며 읽고 쓴 뒤에 고칠 수 있다',ARRAY['6국04 문법(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C5','kor',6,2,'u5',2,'음성 언어의 표현 특성 — 그 자리에서 바로 전해지고 말이 끝나면 소리가 사라지며, 목소리의 크기·억양·속도·잠깐 쉬기로 감정과 의도를 함께 전하고, 듣는 사람의 반응을 보며 말을 바꾸거나 다시 설명하고, 모르는 곳을 그 자리에서 되물을 수 있다',ARRAY['6국04 문법(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C6','kor',6,2,'u5',2,'그 자리에 알맞은 방법 고르기 — 어느 쪽이 더 나은지가 아니라 전하려는 내용과 받는 사람의 처지를 함께 보아, 차례가 여럿이거나 다시 봐야 하면 글, 마음을 생생하게 전하거나 바로 주고받아야 하면 말, 어렵거나 헷갈리면 둘을 함께 쓰며, 고른 까닭을 언어의 특성과 이어 말하는 데까지가 답이다',ARRAY['6국04 문법(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C7','kor',6,2,'u5',2,'두 언어를 함께 써 서로 보완하기 — 말로 설명하면 생생하지만 놓치면 되돌릴 수 없고 같은 내용을 글로도 보여 주면 놓친 곳을 다시 확인할 수 있어, 어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓴다',ARRAY['6국04 문법(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C8','kor',6,2,'u5',4,'영상 매체를 이루는 요소 — 해설하는 말(흐름을 이어 줌)·자막(꼭 남겨야 할 내용을 다시 보여 줌)·장면과 움직임(어떤 일이 벌어지는지 한눈에)·소리와 음악(어디를 눈여겨볼지 알림)이 함께 내용을 전하며, 올린 날짜·만든 사람 이름·본 사람 수·화면 크기는 뜻을 나르는 요소가 아니다',ARRAY['6국06 매체(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C9','kor',6,2,'u5',4,'말과 자막의 보완 · 강조 방법 — 해설하는 말은 흐름을 이어 주지만 놓치면 되돌릴 수 없어, 어렵거나 헷갈리는 내용은 자막으로 정리해 눈으로 다시 확인하게 하고, 자막은 색·크기·모양으로, 말은 음악과 효과음으로 중요한 곳을 강조한다',ARRAY['6국06 매체(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C10','kor',6,2,'u5',4,'표현 효과는 무엇을 돕는가로 본다 — 자막을 화면 가득 채우거나 음악을 계속 크게 깔거나 장면을 쉴 새 없이 바꾸면 무엇이 중요한지 흐려지고, 꼭 남길 곳에만 자막을 두고 중요한 곳에서 소리를 바꾸면 또렷해지므로, 표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다',ARRAY['6국06 매체(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C11','kor',6,2,'u5',5,'장면마다 방법이 다른 까닭 — 같은 영상 안에서도 그 장면에서 해야 할 일이 달라 쓰는 방법이 다르다: 무엇을 다룰지 알릴 때 자막으로 제목, 처음 듣는 낱말을 정확히 남길 때 말과 자막을 함께, 느낌을 바꿀 때 음악의 빠르기를 바꾼다',ARRAY['6국06 매체(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C12','kor',6,2,'u5',5,'영상 감상의 세 걸음 — 찾기(이 장면에 말·글·그림·소리 가운데 무엇이 쓰였는가)·잇기(그것이 이해를 무엇으로 돕는가)·말하기(나는 어떻게 느꼈고 까닭은 무엇인가)이며, 어느 장면이 인상 깊었는가 같은 느낌은 사람마다 다를 수 있지만 무엇이 쓰였고 무엇을 돕는가는 영상 안에서 함께 확인할 수 있으므로, 감상은 좋았다·별로였다에서 멈추지 않고 어떤 표현 때문인지 까닭을 함께 말한다',ARRAY['6국06 매체(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C13','kor',6,2,'u5',5,'영상의 내용 파악하기 — 장면 차례로 무엇을 다루는지 짐작하고 낯선 낱말(밀물·썰물·퇴적·갯벌)을 먼저 익혀, 강물과 바닷물이 실어 온 고운 흙과 모래가 물살이 느린 얕은 바닥에 오랫동안 쌓여 갯벌이 만들어지고 그곳에 게·조개·갯지렁이가 산다는 내용을 정확히 확인하며 본다',ARRAY['6국06 매체(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C14','kor',6,2,'u5',7,'독자를 고려한다는 것 — 글을 읽는 사람(독자)의 처지에서 헤아려 보는 것으로, 독자의 흥미·배경지식·수준(알아들을 수 있는 낱말과 표현)·글을 읽는 매체를 살피고, 독자가 겪는 어려움과 독자가 할 수 있는 일까지 보이게 쓴다 — 같은 내용이라도 누가 읽느냐에 따라 낱말도 차례도 달라진다',ARRAY['6국03 쓰기(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C15','kor',6,2,'u5',7,'독자 고려는 비위 맞추기가 아니다 — 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리거나 낱말만 쉽게 바꾸면 끝나는 것이 아니라, 전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이며, 말하고 싶은 것을 줄이는 일이 아니라 그것이 독자에게 닿게 하는 일이다',ARRAY['6국03 쓰기(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C16','kor',6,2,'u5',7,'글 쓰는 세 단계와 고쳐 쓰기 — 계획 세우기(누가 읽을지·무엇을 왜 쓸지)·내용 생성하고 조직하기(쓸 거리를 모아 차례 짜기)·글 쓰고 고쳐 쓰기를 거치며 단계마다 독자를 다시 떠올리고, 고쳐 쓸 때에는 독자의 수준에 맞는가·주제가 드러나는가·낱말과 문장에 잘못이 없는가·오해할 만한 표현이 없는가를 본다 — 고쳐 쓰기는 틀린 곳을 벌하는 일이 아니라 독자에게 더 잘 닿게 하는 일',ARRAY['6국03 쓰기(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C17','kor',6,2,'u5',7,'글에 자료를 넣는 까닭 — 글만으로 잘 전해지지 않을 때 수를 견줄 때는 표나 그래프, 모습이나 차례는 사진이나 그림, 할 일은 기호와 줄 나눔을 함께 놓으며, 자료는 개수를 채우려고가 아니라 독자의 이해를 도우려고 넣고 글에서 말한 내용과 이어지는 것만 고른다',ARRAY['6국03 쓰기(초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C18','kor',6,2,'u5',9,'기사문의 특성 — 어떤 사실이나 사건을 여러 사람에게 알리는 글로, 직접 보고 듣고 조사한 내용을, 느낌이 아니라 사실로, 빠르고 정확하게, 객관적이고 간결한 표현으로 쓰며, 읽는 사람이 사실이라고 믿고 읽기 때문에 지어낼 수 없다',ARRAY['6국03 쓰기(초안)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C19','kor',6,2,'u5',9,'기사문의 짜임과 육하원칙 — 제목(표제는 내용을 간결하게 드러내고 부제는 필요할 때 표제를 보충)·전문(주요 내용을 누가·언제·어디에서·무엇을·어떻게·왜의 육하원칙으로 앞에서 요약)·본문(주된 내용을 자세히)으로 이루어진다',ARRAY['6국03 쓰기(초안)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C20','kor',6,2,'u5',9,'확인한 사실과 생각 가르기 — 직접 세어 본 수·직접 들은 말·눈으로 확인한 일·본인에게 물어 확인한 계획은 쓰고, 확인하지 못한 소문·그럴 것 같아 지어낸 숫자는 쓰지 않으며, 「모두 기뻐했다」처럼 쓴 사람의 생각을 사실처럼 쓰지 않고 생각을 쓰려면 누구의 생각인지 밝힌다',ARRAY['6국03 쓰기(초안)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C21','kor',6,2,'u5',9,'기사문 계획 · 자료 출처 · 제목 — 독자의 특성·기삿거리(독자가 관심 있고 내가 가서 확인할 수 있는 일)·필요한 자료·자료 수집 방법을 정한 뒤 개요를 짜고, 사진·표 같은 자료는 출처(내가 조사했으면 언제·누구에게·어떻게)를 밝히며, 제목은 내용을 담고 읽고 싶어지게 쓰되 본문에 없는 말로 부풀리지 않는다',ARRAY['6국03 쓰기(초안)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C22','kor',6,2,'u5',12,'편지의 짜임과 독자 — 받는 사람·첫인사(안부)·하고 싶은 말(쓴 목적)·끝인사·쓴 날짜와 보내는 사람의 다섯 부분으로 이루어지며, 독자가 받는 사람 한 사람이라 알맞은 높임말을 쓰고 목적이 뚜렷이 드러나게 하고 받는 사람이 모를 만한 일은 앞뒤를 설명해 준다',ARRAY['6국03 쓰기(초안)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C23','kor',6,2,'u5',12,'전하려는 마음에 맞는 내용 — 고마울 때는 무엇이 고마웠는지 그 일을 콕 집어, 미안할 때는 변명보다 무엇이 잘못이었는지를 먼저, 축하할 때는 그 사람이 애쓴 과정을 함께, 힘을 내라고 할 때는 섣부른 충고보다 곁에 있다는 말을 쓴다',ARRAY['6국03 쓰기(초안)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C24','kor',6,2,'u5',12,'편지의 매체 고르기와 건네기 — 손 편지(글씨와 종이가 남아 오래 간직)·영상 편지(목소리와 표정이 생생)·누리집이나 게시판 글(여러 사람이 함께 봄) 가운데 전하려는 마음과 받는 사람의 처지에 맞는 것을 고르며(매체에 등수 없음), 정말 전하고 싶은 사람에게 쓰고 실제로 건네 반응을 보아야 편지가 완성된다',ARRAY['6국03 쓰기(초안)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u5-C25','kor',6,2,'u5',12,'겹받침이 있는 낱말의 발음 — 받침에 자음자가 두 개 있는 겹받침은 받침에서 한 번에 한 소리만 낼 수 있어 뒤에 자음자가 오거나 낱말이 끝나면 하나만 소리 나고(붉다[북따]·얇다[얄따]·짧다[짤따]), 뒤에 모음이 오면 두 소리가 다 나며 뒤엣것이 뒷글자로 넘어간다(붉어요[불거요]·얇아요[얄바요]) (기초 다지기)',ARRAY['6국04 문법(초안)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X01','kor',6,'u5',ARRAY['K6-2-u5-C1']::text[],'음성 언어와 문자 언어의 뜻을 서로 바꾸어 알거나, 글로 옮겨 적은 말을 음성 언어로 여긴다','음성으로? 글자로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X02','kor',6,'u5',ARRAY['K6-2-u5-C2','K6-2-u5-C4','K6-2-u5-C5']::text[],'「말은 언제나 사라진다 · 글은 언제나 남는다」처럼 특성을 어떤 경우에도 맞는 규칙으로 외워, 녹음한 말이나 흘러가는 글을 설명하지 못한다','보통은 그렇지만 매체에 따라 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X03','kor',6,'u5',ARRAY['K6-2-u5-C1','K6-2-u5-C3','K6-2-u5-C24']::text[],'글이 말보다, 영상이 글보다 낫다처럼 언어나 매체에 등수를 매긴다','더 나은 쪽이 아니라 그 자리에 알맞은 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X04','kor',6,'u5',ARRAY['K6-2-u5-C3']::text[],'인쇄 · 음성 · 영상 매체가 주로 쓰는 방법을 헷갈린다','무엇을 바탕으로 무엇을 더하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X05','kor',6,'u5',ARRAY['K6-2-u5-C3','K6-2-u5-C8']::text[],'올린 날짜 · 만든 사람 이름 · 본 사람 수 · 화면 크기처럼 뜻을 나르지 않는 것을 매체 자료의 표현 방법으로 고른다','화면이나 지면에서 뜻을 나르는 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X06','kor',6,'u5',ARRAY['K6-2-u5-C4','K6-2-u5-C5']::text[],'글의 강조 방법(굵은 글씨 · 밑줄 · 문장 부호)과 말의 강조 방법(목소리 크기 · 억양 · 속도)을 뒤섞는다','글은 눈에, 말은 귀에 띄게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X07','kor',6,'u5',ARRAY['K6-2-u5-C4']::text[],'문자 언어의 장점(다시 보기 · 똑같이 나누어 갖기 · 천천히 읽고 고치기)을 모르거나 글은 쓰고 나면 고칠 수 없다고 여긴다','적어 두면 무엇이 좋을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X08','kor',6,'u5',ARRAY['K6-2-u5-C5']::text[],'음성 언어의 장점(목소리로 감정 전하기 · 반응 보고 바꾸기 · 그 자리에서 되묻기)을 모른다','마주 보고 말하면 무엇을 할 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X09','kor',6,'u5',ARRAY['K6-2-u5-C6']::text[],'알맞은 방법을 고르기만 하고 까닭을 말하지 않거나, 까닭을 언어의 특성과 잇지 못한다','고른 것 + 그 특성 때문에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X10','kor',6,'u5',ARRAY['K6-2-u5-C6','K6-2-u5-C24']::text[],'전하려는 내용과 받는 사람의 처지를 보지 않고 늘 한 가지 방법만 쓰거나 빠르고 편한 방법만 고른다','무엇을 · 누구에게?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X11','kor',6,'u5',ARRAY['K6-2-u5-C7','K6-2-u5-C9']::text[],'말한 내용을 글(자막)로도 보여 주면 겹쳐서 쓸모없다고 여겨, 두 언어가 서로 보완하는 것을 모른다','놓친 곳을 다시 확인하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X12','kor',6,'u5',ARRAY['K6-2-u5-C8','K6-2-u5-C9','K6-2-u5-C11']::text[],'해설하는 말 · 자막 · 장면 · 소리와 음악이 각각 하는 일을 헷갈린다','흐름 · 붙들기 · 한눈에 · 눈여겨볼 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X13','kor',6,'u5',ARRAY['K6-2-u5-C10','K6-2-u5-C17']::text[],'자막 · 음악 · 장면 · 자료를 많이 넣을수록 잘 전달되고 좋은 자료라고 여긴다','개수가 아니라 무엇을 돕는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X14','kor',6,'u5',ARRAY['K6-2-u5-C11']::text[],'장면마다 방법을 아무렇게나 골랐다고 여겨, 그 장면에서 해야 할 일과 방법을 잇지 못한다','이 장면에서 시청자가 알아야 할 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X15','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'감상을 「좋았다 · 재미있었다 · 별로였다」에서 멈추고 어떤 표현 때문인지 까닭을 말하지 않는다','찾기 · 잇기 · 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X16','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'느낌이 나와 다르면 잘못 본 것이라 여기거나, 사람마다 다를 수 있는 느낌과 영상 안에서 확인할 수 있는 것을 가르지 못한다','갈릴 수 있는 것 · 함께 확인할 수 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X17','kor',6,'u5',ARRAY['K6-2-u5-C13']::text[],'영상의 장면 차례를 이어 보지 않아 갯벌이 만들어지는 과정을 잘못 안다(솟아올라서 · 얼었다 녹아서 등)','무엇이 어디에 오래 쌓이나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X18','kor',6,'u5',ARRAY['K6-2-u5-C13']::text[],'영상에 나온 낱말(밀물 · 썰물 · 퇴적 · 갯벌)의 뜻을 서로 헷갈린다','들어오는 물 · 나가는 물 · 쌓이는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X19','kor',6,'u5',ARRAY['K6-2-u5-C14']::text[],'독자 고려를 낱말만 쉽게 바꾸는 일로 좁히거나, 독자의 흥미 · 배경지식 · 수준 · 매체 가운데 일부만 살핀다','흥미 · 배경지식 · 수준 · 매체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X20','kor',6,'u5',ARRAY['K6-2-u5-C15']::text[],'독자 고려를 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리는 비위 맞추기로 여긴다','전하려는 것은 그대로, 닿는 방법을 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X21','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'글 쓰는 세 단계와 그 단계에서 하는 일을 헷갈리거나, 독자는 처음 계획할 때만 떠올리면 된다고 여긴다','쓰기 전 · 쓰는 중 · 쓴 뒤, 단계마다 독자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X22','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'고쳐 쓸 곳을 글씨 · 길이 · 꾸밈 같은 겉모습에서 찾거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','독자에게 더 잘 닿게 하려고 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X23','kor',6,'u5',ARRAY['K6-2-u5-C17']::text[],'자료를 개수를 채우려고 넣거나, 글과 이어지지 않는 자료를 넣거나, 자료를 넣으면 글을 덜 써도 된다고 여긴다','글만으로 어려운 곳을 돕는 자료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X24','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C16']::text[],'어렵고 딱딱한 낱말을 많이 쓰면 글이 훌륭해 보인다고 여겨, 독자가 알아듣지 못하는 문제를 보지 않는다','독자가 아는 말인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X25','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C15']::text[],'글에서 독자가 무엇을 하면 되는지, 왜 그래야 하는지가 빠져도 괜찮다고 여긴다','까닭과 할 일이 함께 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X26','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'기사문에 쓴 사람의 느낌이나 생각을 사실처럼 쓴다(「모두 기뻐했다」 · 「가장 큰 변화」)','누구든 다시 확인할 수 있는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X27','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'확인하지 못한 소문이나 그럴 것 같아 지어낸 숫자를 기사문에 쓴다','세어 보거나 물어본 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X28','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'기사문의 짜임(표제 · 부제 · 전문 · 본문)과 하는 일을 헷갈리거나, 전문을 느낌이나 못다 한 말을 쓰는 곳으로 여긴다','전문 = 주요 내용 요약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X29','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'육하원칙(누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜)의 항목을 서로 헷갈리거나 빠뜨린다','여섯 가지 물음에 하나씩 답하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X30','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기삿거리를 독자의 관심이나 직접 확인할 수 있는지를 보지 않고 고른다','독자가 관심 있고, 내가 가서 확인할 수 있는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X31','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기사문 제목을 본문에 없는 말로 부풀리거나, 반대로 아무 내용도 담지 않은 제목을 쓴다','내용을 담되 부풀리지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X32','kor',6,'u5',ARRAY['K6-2-u5-C21','K6-2-u5-C17']::text[],'사진 · 표 같은 자료를 넣으면서 어디에서 얻었는지, 언제 누구에게 어떻게 조사했는지 출처를 밝히지 않는다','출처를 밝혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X33','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지의 다섯 부분(받는 사람 · 첫인사 · 하고 싶은 말 · 끝인사 · 쓴 날짜와 보내는 사람)을 빠뜨리거나 하는 일을 헷갈린다','누구에게 · 인사 · 목적 · 인사 · 언제 누가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X34','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지를 받는 사람에게 알맞은 높임말을 쓰지 않거나, 받는 사람이 모를 만한 일을 앞뒤 설명 없이 쓴다','받는 사람 한 사람을 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X35','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'전하려는 마음과 맞지 않는 내용을 쓴다(축하에 충고, 사과에 변명 먼저, 위로에 섣부른 충고)','이 마음에 맞는 말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X36','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'「고마워」 · 「잘했네」처럼 무엇이 그런지 없이 막연하게 써서 마음이 잘 닿지 않는다','그 일을 콕 집어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X37','kor',6,'u5',ARRAY['K6-2-u5-C24']::text[],'편지를 숙제로 아무에게나 쓰거나 꾸미기에 시간을 다 쓰고, 건네고 반응을 보는 것을 하지 않는다','건네고 나서 완성돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X38','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 뒤에 자음자가 오거나 낱말이 끝날 때에도 두 소리를 다 내거나, 뒤에 모음이 와도 하나만 소리 낸다','뒤에 오는 것이 자음자? 모음?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X39','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 낱말에서 어느 자음자가 소리 나는지, 뒤엣것이 어느 글자로 넘어가는지를 헷갈린다','소리 내어 천천히 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u5-X40','kor',6,'u5',ARRAY['K6-2-u5-C16','K6-2-u5-C24']::text[],'「앞으로 열심히 하겠다」처럼 언제 · 어디에서 · 무엇을 할지 없는 다짐을 실천 계획으로 여긴다','언제 · 어디에서 · 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#1','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'mc','auto','「음성 언어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"「음성 언어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"음성으로 나타내는 말","correct":true},{"t":"글자로 나타내는 말","mis":"K6-2-u5-X01"},{"t":"그림과 사진으로 나타내는 것","mis":"K6-2-u5-X04"},{"t":"어느 고장에서만 쓰는 말","mis":"K6-2-u5-X01"}],"explanation":["글자로 나타내는 말은 문자 언어예요.","그림과 사진은 언어가 아니라 함께 쓰는 자료예요.","음성으로 나타내는 말이 음성 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#2','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'sa','auto','글자로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C1","difficulty":1,"kind":"sa","stem":"글자로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["문자언어","문자 언어"],"explanation":["음성으로 나타내는 말은 음성 언어예요.","글자로 나타내는 말은 문자 언어예요.","적어 두면 다시 볼 수 있어요."],"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#3','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'ox','auto','음성 언어와 문자 언어 가운데 문자 언어가 더 좋은 언어예요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":3,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"음성 언어와 문자 언어 가운데 문자 언어가 더 좋은 언어예요.","answer":"X","reason_options":[{"t":"두 언어는 알맞은 곳이 서로 다를 뿐이기 때문에","correct":true},{"t":"글은 남고 말은 사라지기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["두 언어는 등수를 매기는 사이가 아니에요.","상황마다 알맞은 쪽이 달라요.","그래서 더 좋은 언어는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#4','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',1,'mc','auto','음성 언어를 바탕으로 소리와 음악을 함께 쓰는 매체는 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"음성 언어를 바탕으로 소리와 음악을 함께 쓰는 매체는 어느 것인가요?","options":[{"t":"음성 매체","correct":true},{"t":"인쇄 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"문자 매체","mis":"K6-2-u5-X04"}],"explanation":["인쇄 매체는 문자 언어를 바탕으로 해요.","영상 매체는 여러 방법이 어우러져요.","소리로 전하는 라디오 같은 것이 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#5','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',2,'mc','auto','시율이와 도아가 준비물을 다시 확인할 수 있었던 까닭은 무엇인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X09','K6-2-u5-X02']::text[],false,'{"seq":5,"concept":"K6-2-u5-C1","difficulty":2,"kind":"mc","stem":"시율이와 도아가 준비물을 다시 확인할 수 있었던 까닭은 무엇인가요?","options":[{"t":"같은 내용이 글로도 남아 있었기 때문에","correct":true},{"t":"선생님의 목소리가 아주 컸기 때문에","mis":"K6-2-u5-X08"},{"t":"두 사람의 기억력이 좋았기 때문에","mis":"K6-2-u5-X09"},{"t":"말은 언제나 남기 때문에","mis":"K6-2-u5-X02"}],"explanation":["두 사람은 앞부분만 기억났어요.","알림 게시글을 다시 읽어 보기로 했어요.","글로 남은 내용은 다시 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"시율","text":"도아야, 아까 선생님이 준비물 말씀하셨잖아. 뭐였지?"},{"who":"도아","text":"나도 앞부분만 기억나. 잠깐, 알림 게시글에도 올라와 있어."},{"who":"시율","text":"아, 글로도 올려 주셨구나. 그럼 다시 읽어 보면 되겠다."},{"who":"도아","text":"응. 말씀은 지나갔지만 글은 그대로 남아 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#6','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C6',2,'match','auto','상황과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C6","difficulty":2,"kind":"match","stem":"상황과 알맞은 방법을 이으세요.","pairs":[{"l":"여러 사람이 오래 기억해야 할 준비물 안내","r":"글로 적어 둡니다"},{"l":"다친 친구에게 지금 걱정하는 마음 전하기","r":"직접 말로 전합니다"},{"l":"실험 차례를 보여 주며 설명하기","r":"말과 글을 함께 씁니다"}],"mis":"K6-2-u5-X10","explanation":["다시 봐야 하는 안내는 글이 알맞아요.","지금 마음을 전할 때는 말이 알맞아요.","차례가 헷갈리는 설명은 둘을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#7','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',2,'mc','auto','다음 가운데 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":7,"concept":"K6-2-u5-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 알맞게 말한 것은 어느 것인가요?","options":[{"t":"음성 메모로 남기면 말도 다시 들을 수 있다","correct":true},{"t":"말은 어떤 경우에도 다시 확인할 수 없다","mis":"K6-2-u5-X02"},{"t":"글은 어떤 경우에도 사라지지 않는다","mis":"K6-2-u5-X02"},{"t":"남는 쪽이 언제나 더 좋은 방법이다","mis":"K6-2-u5-X03"}],"explanation":["말은 보통 그 자리에서 사라져요.","그래도 녹음하면 남아요.","특성은 규칙이 아니라 기본 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#8','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C8',2,'mc','auto','매체 자료가 내용을 전달할 때 쓰는 방법이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":8,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"매체 자료가 내용을 전달할 때 쓰는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"파일에 붙인 이름","correct":true},{"t":"말하는 사람의 목소리","mis":"K6-2-u5-X05"},{"t":"화면에 뜨는 자막","mis":"K6-2-u5-X05"},{"t":"배경에 깔리는 음악","mis":"K6-2-u5-X05"}],"explanation":["목소리 · 자막 · 음악은 뜻을 나르는 방법이에요.","파일 이름은 화면에서 뜻을 나르지 않아요.","뜻을 나르는 것만 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#9','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',2,'ox','auto','영상 매체는 음성 언어와 문자 언어에 그림 · 소리 · 움직임이 어우러진 매체예요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":9,"concept":"K6-2-u5-C3","difficulty":2,"kind":"ox","stem":"영상 매체는 음성 언어와 문자 언어에 그림 · 소리 · 움직임이 어우러진 매체예요.","answer":"O","reason_options":[{"t":"여러 방법을 함께 써서 내용을 전하기 때문에","correct":true},{"t":"글자만 써서 내용을 전하기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["영상에는 말도 글도 들어 있어요.","그림과 소리, 움직임도 함께 있어요.","그래서 여러 방법이 어우러진 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_basic#10','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',3,'error','auto','이 단원의 약속에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":10,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"이 단원의 약속에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「말은 언제나 없어지고 글은 언제나 남으니까 그대로 외우면 돼.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"리안 — 「녹음한 말은 남고, 빠르게 지나가는 대화 글은 흘러가기도 해.」","mis":"K6-2-u5-X02"},{"t":"하진 — 「그 자리에 무엇이 알맞은지를 살펴보면 돼.」","mis":"K6-2-u5-X03"}],"explanation":["리안과 하진은 약속을 바르게 말했어요.","태오는 특성을 규칙으로 외웠어요.","보통은 그렇지만 매체에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#1','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C14',2,'mc','auto','글을 읽는 사람을 무엇이라고 하나요?',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":1,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"글을 읽는 사람을 무엇이라고 하나요?","options":[{"t":"독자","correct":true},{"t":"작가","mis":"K6-2-u5-X19"},{"t":"기자","mis":"K6-2-u5-X19"},{"t":"화자","mis":"K6-2-u5-X19"}],"explanation":["글을 쓰는 사람은 글쓴이예요.","글을 읽는 사람은 독자예요.","같은 내용도 누가 읽느냐에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#2','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',2,'mc','auto','인쇄 매체가 주로 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04','K6-2-u5-X05']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":2,"kind":"mc","stem":"인쇄 매체가 주로 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"문자 언어를 바탕으로 표 · 그림 · 사진을 함께 쓴다","correct":true},{"t":"음성 언어를 바탕으로 소리와 음악을 함께 쓴다","mis":"K6-2-u5-X04"},{"t":"말 · 글 · 소리 · 움직임을 모두 어울러 쓴다","mis":"K6-2-u5-X04"},{"t":"파일 이름과 올린 날짜로 내용을 전한다","mis":"K6-2-u5-X05"}],"explanation":["책과 신문은 인쇄 매체예요.","글자를 바탕으로 해요.","표 · 그림 · 사진을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#3','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',3,'mc','auto','「글인데 흘러가는 경우」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X01']::text[],false,'{"seq":3,"concept":"K6-2-u5-C2","difficulty":3,"kind":"mc","stem":"「글인데 흘러가는 경우」로 알맞은 것은 어느 것인가요?","options":[{"t":"잠깐 떴다 사라지는 휴대 전화 알림","correct":true},{"t":"도서관에 꽂힌 책","mis":"K6-2-u5-X02"},{"t":"학급 게시판에 붙은 안내문","mis":"K6-2-u5-X02"},{"t":"녹음해 둔 음성 메모","mis":"K6-2-u5-X01"}],"explanation":["책과 게시판의 글은 오래 남아요.","음성 메모는 말인데 남는 경우예요.","잠깐 뜨고 사라지는 알림은 글인데 흘러가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#4','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C6',3,'mc','auto','내일 소풍 장소와 모일 시각을 반 전체에 알리려고 해요. 어떤 방법이 가장 알맞나요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03']::text[],false,'{"seq":4,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"내일 소풍 장소와 모일 시각을 반 전체에 알리려고 해요. 어떤 방법이 가장 알맞나요?","options":[{"t":"말로 알리고 같은 내용을 글로도 적어 둔다","correct":true},{"t":"말로만 한 번 크게 알린다","mis":"K6-2-u5-X10"},{"t":"가장 빨리 할 수 있는 방법이면 무엇이든 괜찮다","mis":"K6-2-u5-X10"},{"t":"글이 말보다 좋으니 글로만 알린다","mis":"K6-2-u5-X03"}],"explanation":["여러 사람이 오래 기억해야 하는 내용이에요.","말로 알리면 그 자리에서 되물을 수 있어요.","글로도 적어 두면 놓친 사람이 다시 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#5','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C8',3,'ox','auto','영상을 올린 날짜도 그 영상이 내용을 전하는 표현 방법이에요.',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":3,"kind":"ox","stem":"영상을 올린 날짜도 그 영상이 내용을 전하는 표현 방법이에요.","answer":"X","reason_options":[{"t":"화면에서 뜻을 나르는 요소가 아니기 때문에","correct":true},{"t":"영상에 관한 것은 모두 표현 방법이기 때문에","mis":"K6-2-u5-X05"}],"mis":"K6-2-u5-X05","explanation":["표현 방법은 화면이나 소리로 뜻을 나르는 것이에요.","올린 날짜는 영상 밖의 정보예요.","목소리 · 자막 · 음악 · 장면을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#6','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'match','auto','매체와 그 매체의 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C3","difficulty":3,"kind":"match","stem":"매체와 그 매체의 예를 알맞게 이으세요.","pairs":[{"l":"인쇄 매체","r":"신문과 책"},{"l":"음성 매체","r":"라디오 방송"},{"l":"영상 매체","r":"공익 안내 영상"}],"mis":"K6-2-u5-X04","explanation":["신문과 책은 글자를 바탕으로 해요.","라디오는 소리로 전해요.","영상은 말 · 글 · 그림 · 소리가 어우러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#7','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'error','auto','매체에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":7,"concept":"K6-2-u5-C3","difficulty":3,"kind":"error","stem":"매체에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서준 — 「여러 방법을 다 쓰니까 영상 매체가 언제나 제일 좋아.」","correct":true,"mis_target":"K6-2-u5-X03"},{"t":"나윤 — 「전하려는 내용에 따라 알맞은 매체가 달라.」","mis":"K6-2-u5-X03"},{"t":"은재 — 「받는 사람이 누구인지도 함께 봐야 해.」","mis":"K6-2-u5-X10"}],"explanation":["나윤과 은재는 바르게 말했어요.","서준은 매체에 등수를 매겼어요.","셋 가운데 더 나은 매체는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#8','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',4,'mc','auto','도아가 「말씀은 지나갔지만 글은 그대로 남아 있으니까.」라고 한 말과 이 단원의 약속을 함께 생각할 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":8,"concept":"K6-2-u5-C1","difficulty":4,"kind":"mc","stem":"도아가 「말씀은 지나갔지만 글은 그대로 남아 있으니까.」라고 한 말과 이 단원의 약속을 함께 생각할 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 상황에서는 글이 남아 도움이 되었지만, 녹음한 말처럼 말이 남는 경우도 있으니 매체마다 살펴야 한다","correct":true},{"t":"글은 언제나 남으니 앞으로 모든 안내는 글로만 하면 된다","mis":"K6-2-u5-X02"},{"t":"선생님이 말로 하신 것이 잘못이다","mis":"K6-2-u5-X03"},{"t":"도아의 말은 틀렸다. 글도 금방 사라진다","mis":"K6-2-u5-X02"}],"explanation":["이 상황에서는 글이 남아 다시 볼 수 있었어요.","그렇다고 언제나 그런 것은 아니에요.","매체에 따라 남고 사라지는 것이 달라져요."],"asset":{"type":"speech","turns":[{"who":"시율","text":"도아야, 아까 선생님이 준비물 말씀하셨잖아. 뭐였지?"},{"who":"도아","text":"나도 앞부분만 기억나. 잠깐, 알림 게시글에도 올라와 있어."},{"who":"시율","text":"아, 글로도 올려 주셨구나. 그럼 다시 읽어 보면 되겠다."},{"who":"도아","text":"응. 말씀은 지나갔지만 글은 그대로 남아 있으니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#9','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',4,'essay','teacher','「말은 언제나 사라지고 글은 언제나 남는다.」라는 말이 왜 알맞지 않은지 예를 두 가지 들어 쓰고, 어떻게 알아 두어야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C2","difficulty":4,"kind":"essay","stem":"「말은 언제나 사라지고 글은 언제나 남는다.」라는 말이 왜 알맞지 않은지 예를 두 가지 들어 쓰고, 어떻게 알아 두어야 하는지 쓰세요.","answer_guide":{"answer":"예: 음성 메모로 녹음한 말은 다시 들을 수 있어서 말인데도 남는다. 잠깐 떴다 사라지는 알림이나 넘기면 없어지는 자막은 글인데도 다시 보기 어렵다. 그래서 말은 보통 그 자리에서 사라지고 글은 보통 오래 남는다는 것은 기본 성질일 뿐이고, 매체에 따라 달라지므로 이 매체에서는 어떻게 되는지 그때그때 살펴야 한다.","scoring_points":["말인데 남는 예를 들었는가","글인데 흘러가는 예를 들었는가","기본 성질이며 매체에 따라 달라진다고 썼는가"]},"explanation":["녹음한 말을 떠올려요.","사라지는 알림을 떠올려요.","규칙이 아니라 기본 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L01_challenge#10','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C6',4,'essay','teacher','「멀리 이사 간 친구에게 생일 축하하는 마음 전하기」와 「모둠 과제의 차례 다섯 가지 알리기」 가운데 하나를 골라 알맞은 방법(말 · 글 · 둘 다)을 정하고, 그 까닭을 언어의 특성과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"「멀리 이사 간 친구에게 생일 축하하는 마음 전하기」와 「모둠 과제의 차례 다섯 가지 알리기」 가운데 하나를 골라 알맞은 방법(말 · 글 · 둘 다)을 정하고, 그 까닭을 언어의 특성과 이어 쓰세요.","answer_guide":{"answer":"예: 모둠 과제의 차례 다섯 가지를 알릴 때는 글로 적어 두는 것이 알맞다. 차례가 여러 개라 나중에 다시 봐야 하는데, 글은 그대로 남아 필요할 때 다시 볼 수 있고 모둠원이 똑같은 내용을 나누어 가질 수 있기 때문이다. (또는) 생일 축하는 영상 통화로 직접 말로 전하는 것이 알맞다. 목소리의 크기와 억양으로 반가운 마음을 생생하게 전할 수 있기 때문이다.","scoring_points":["상황 하나를 골라 방법을 정했는가","까닭을 썼는가","까닭을 언어의 특성과 이어 썼는가"]},"explanation":["고르는 것까지는 절반이에요.","왜 그런지를 써요.","특성과 이어야 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#1','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'mc','auto','안내 글에서 중요한 내용을 눈에 띄게 한 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":1,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"안내 글에서 중요한 내용을 눈에 띄게 한 방법은 어느 것인가요?","options":[{"t":"글자를 굵게 하고 줄을 나누었다","correct":true},{"t":"목소리를 크게 했다","mis":"K6-2-u5-X06"},{"t":"배경 음악을 넣었다","mis":"K6-2-u5-X06"},{"t":"말을 천천히 했다","mis":"K6-2-u5-X06"}],"explanation":["목소리 · 음악 · 말의 속도는 말로 할 때 쓰는 방법이에요.","글에서는 글자 굵기와 줄 나눔을 써요.","그래서 목장갑과 겉옷이 눈에 띄어요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#2','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',1,'mc','auto','방송하는 사람이 중요한 곳을 알린 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":2,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"방송하는 사람이 중요한 곳을 알린 방법은 어느 것인가요?","options":[{"t":"목소리를 크고 또박또박하게 하고 말을 천천히 했다","correct":true},{"t":"중요한 낱말에 밑줄을 그었다","mis":"K6-2-u5-X06"},{"t":"문장 끝에 느낌표를 붙였다","mis":"K6-2-u5-X06"},{"t":"글자를 크게 썼다","mis":"K6-2-u5-X06"}],"explanation":["밑줄 · 느낌표 · 글자 크기는 글의 방법이에요.","말에서는 목소리의 크기와 속도를 써요.","괄호 안을 다시 읽어 보세요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#3','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'ox','auto','문자 언어는 한 번 적으면 필요할 때 다시 볼 수 있어요.',ARRAY['K6-2-u5-X07']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":1,"kind":"ox","stem":"문자 언어는 한 번 적으면 필요할 때 다시 볼 수 있어요.","answer":"O","reason_options":[{"t":"적은 내용이 그대로 남기 때문에","correct":true},{"t":"글은 쓰고 나면 고칠 수 없기 때문에","mis":"K6-2-u5-X07"}],"mis":"K6-2-u5-X07","explanation":["글은 보통 오래 남아요.","그래서 다시 볼 수 있어요.","쓴 뒤에 고칠 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#4','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',1,'sa','auto','음성 언어에서 말소리의 높낮이를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u5-C5","difficulty":1,"kind":"sa","stem":"음성 언어에서 말소리의 높낮이를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["억양"],"explanation":["말은 목소리의 크기와 속도로도 뜻을 전해요.","말소리의 높낮이는 억양이에요.","억양으로 감정과 의도를 함께 전해요."],"mis":"K6-2-u5-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#5','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',2,'match','auto','같은 일을 하는 방법끼리 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C4","difficulty":2,"kind":"match","stem":"같은 일을 하는 방법끼리 이으세요.","pairs":[{"l":"글자를 굵게 합니다","r":"목소리를 크게 합니다"},{"l":"느낌표를 붙입니다","r":"억양을 올립니다"},{"l":"줄을 나누어 띄웁니다","r":"잠깐 쉬었다 말합니다"}],"mis":"K6-2-u5-X06","explanation":["글은 눈에, 말은 귀에 띄게 해요.","굵은 글씨와 큰 목소리는 강조예요.","줄 나눔과 쉬기는 나누어 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#6','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',2,'mc','auto','음성 언어의 특성으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X06']::text[],false,'{"seq":6,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"음성 언어의 특성으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 반응을 보며 다시 설명할 수 있다","correct":true},{"t":"적은 내용이 그대로 남는다","mis":"K6-2-u5-X01"},{"t":"글자의 굵기로 중요한 곳을 보인다","mis":"K6-2-u5-X06"},{"t":"쓴 뒤에 천천히 고칠 수 있다","mis":"K6-2-u5-X01"}],"explanation":["남기 · 굵기 · 고치기는 문자 언어의 특성이에요.","말은 마주 보고 해요.","그래서 반응을 보며 바꿀 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#7','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',2,'mc','auto','복잡한 차례를 글로도 적어 주면 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":7,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"복잡한 차례를 글로도 적어 주면 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글로 적으면 언제나 더 훌륭한 안내가 되기 때문에","correct":true},{"t":"잊어버렸을 때 다시 볼 수 있기 때문에","mis":"K6-2-u5-X09"},{"t":"차례를 눈으로 짚어 가며 따라 할 수 있기 때문에","mis":"K6-2-u5-X09"},{"t":"여러 사람이 똑같은 내용을 나누어 갖기 때문에","mis":"K6-2-u5-X09"}],"explanation":["세 까닭은 글의 특성과 이어져 있어요.","「언제나 더 훌륭하다」는 등수를 매긴 말이에요.","까닭은 특성과 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#8','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C7',2,'ox','auto','어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓰면 좋아요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":8,"concept":"K6-2-u5-C7","difficulty":2,"kind":"ox","stem":"어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓰면 좋아요.","answer":"O","reason_options":[{"t":"말로 놓친 곳을 글로 다시 확인할 수 있기 때문에","correct":true},{"t":"같은 내용을 두 번 쓰면 시간이 아깝기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["말은 생생하지만 놓치면 되돌릴 수 없어요.","글은 남아서 다시 볼 수 있어요.","둘을 함께 쓰면 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#9','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',2,'mc','auto','안내 글과 방송을 견주었을 때 안내 글만 할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X08']::text[],false,'{"seq":9,"concept":"K6-2-u5-C4","difficulty":2,"kind":"mc","stem":"안내 글과 방송을 견주었을 때 안내 글만 할 수 있는 것은 어느 것인가요?","options":[{"t":"집에 가서도 챙길 것을 다시 읽어 볼 수 있다","correct":true},{"t":"목소리로 「꼭」을 힘주어 말할 수 있다","mis":"K6-2-u5-X06"},{"t":"듣는 사람이 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"말을 천천히 해서 중요한 곳을 알린다","mis":"K6-2-u5-X06"}],"explanation":["힘주어 말하기와 되묻기, 천천히 말하기는 말의 특성이에요.","글은 남아 있어요.","그래서 나중에 다시 볼 수 있어요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_basic#10','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',3,'error','auto','「이 상황에는 문자 언어가 알맞다」를 말했어요. 까닭까지 바르게 말하지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":3,"kind":"error","stem":"「이 상황에는 문자 언어가 알맞다」를 말했어요. 까닭까지 바르게 말하지 않은 친구는 누구인가요?","options":[{"t":"민서 — 「글이 알맞아. 그냥 글이 좋으니까.」","correct":true,"mis_target":"K6-2-u5-X09"},{"t":"주원 — 「차례가 여러 개라 나중에 다시 봐야 하는데, 글은 그대로 남거든.」","mis":"K6-2-u5-X09"},{"t":"가은 — 「여러 사람이 똑같은 내용을 정확하게 나누어 가져야 해서야.」","mis":"K6-2-u5-X09"}],"explanation":["주원과 가은은 까닭을 글의 특성과 이었어요.","민서는 고르기만 하고 까닭이 없어요.","고른 까닭까지가 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#1','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',2,'mc','auto','방송에서 「모종은 학교에서 준비합니다」를 말을 천천히 하며 알린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X06']::text[],false,'{"seq":1,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"방송에서 「모종은 학교에서 준비합니다」를 말을 천천히 하며 알린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 놓치지 않고 「사 오지 않아도 된다」는 것을 알게 하려고","correct":true},{"t":"방송 시간을 늘리려고","mis":"K6-2-u5-X08"},{"t":"글자 수를 맞추려고","mis":"K6-2-u5-X06"},{"t":"목소리가 작아서","mis":"K6-2-u5-X08"}],"explanation":["천천히 말하면 귀에 또렷이 남아요.","사 오지 않아도 된다는 것은 중요한 내용이에요.","말의 속도도 강조 방법이에요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#2','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',2,'ox','auto','음성 언어로 말할 때에는 모르는 곳을 그 자리에서 되물을 수 있어요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":2,"concept":"K6-2-u5-C5","difficulty":2,"kind":"ox","stem":"음성 언어로 말할 때에는 모르는 곳을 그 자리에서 되물을 수 있어요.","answer":"O","reason_options":[{"t":"말하는 사람과 듣는 사람이 그 자리에서 주고받기 때문에","correct":true},{"t":"말은 글보다 언제나 정확하기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["말은 마주 보고 주고받아요.","모르면 바로 물을 수 있어요.","어느 쪽이 언제나 정확한 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#3','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C4',3,'mc','auto','안내 글에서 「모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다」를 따로 적은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X06','K6-2-u5-X25']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":3,"kind":"mc","stem":"안내 글에서 「모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다」를 따로 적은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽는 사람이 잘못 알고 모종을 사 오는 일이 없도록 하려고","correct":true},{"t":"글을 길게 보이게 하려고","mis":"K6-2-u5-X13"},{"t":"목소리로 강조할 수 없어서 아무 줄이나 더 적으려고","mis":"K6-2-u5-X06"},{"t":"모종 가게를 알리려고","mis":"K6-2-u5-X25"}],"explanation":["읽는 사람은 모종도 챙겨야 하는지 궁금할 수 있어요.","그래서 할 일과 하지 않아도 될 일을 함께 적었어요.","독자를 생각한 줄이에요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#4','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',3,'mc','auto','다음 가운데 음성 언어가 더 알맞은 상황은 어느 것인가요?',ARRAY['K6-2-u5-X10']::text[],false,'{"seq":4,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"다음 가운데 음성 언어가 더 알맞은 상황은 어느 것인가요?","options":[{"t":"처음 만난 전학생에게 반갑게 인사하며 우리 반을 소개할 때","correct":true},{"t":"일주일 동안 지킬 청소 당번표를 알릴 때","mis":"K6-2-u5-X10"},{"t":"도서관 책을 빌리는 다섯 가지 차례를 알릴 때","mis":"K6-2-u5-X10"},{"t":"학급 회의에서 정한 규칙을 오래 기억하게 할 때","mis":"K6-2-u5-X10"}],"explanation":["당번표 · 차례 · 규칙은 다시 봐야 해서 글이 알맞아요.","반가운 마음은 목소리로 생생하게 전해져요.","전학생도 그 자리에서 되물을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#5','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C5',3,'match','auto','음성 언어의 특성과 그 예를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C5","difficulty":3,"kind":"match","stem":"음성 언어의 특성과 그 예를 이으세요.","pairs":[{"l":"바로 전해지고 끝나면 사라진다","r":"방송을 놓친 친구가 내용을 모른다"},{"l":"목소리로 감정을 함께 전한다","r":"「축하해!」를 밝은 목소리로 말한다"},{"l":"반응을 보며 다시 설명한다","r":"친구 표정을 보고 더 쉽게 말해 준다"}],"mis":"K6-2-u5-X08","explanation":["놓치면 되돌릴 수 없어요.","목소리에 마음이 실려요.","마주 보면 반응을 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#6','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C2',3,'error','auto','「매체에 따라 특성이 달라지는 예」를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":6,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"「매체에 따라 특성이 달라지는 예」를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"수아 — 「말은 절대 남지 않고, 글은 절대 사라지지 않아.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"도윤 — 「녹음한 말은 남고, 빠르게 지나가는 대화 글은 흘러가.」","mis":"K6-2-u5-X02"},{"t":"라온 — 「화면을 넘기면 없어지는 자막은 글인데도 다시 보기 어려워.」","mis":"K6-2-u5-X02"}],"explanation":["도윤과 라온은 매체에 따라 달라지는 예를 들었어요.","수아는 「절대」로 규칙을 만들었어요.","특성은 기본 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#7','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C7',3,'mc','auto','선생님이 실험 차례를 말로 설명하면서 칠판에도 차례를 적었어요. 이렇게 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X08','K6-2-u5-X03']::text[],false,'{"seq":7,"concept":"K6-2-u5-C7","difficulty":3,"kind":"mc","stem":"선생님이 실험 차례를 말로 설명하면서 칠판에도 차례를 적었어요. 이렇게 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말로 생생하게 설명하고, 놓친 차례는 칠판을 보며 다시 확인하게 하려고","correct":true},{"t":"같은 내용을 두 번 해서 시간을 채우려고","mis":"K6-2-u5-X11"},{"t":"말만으로는 감정을 전할 수 없어서","mis":"K6-2-u5-X08"},{"t":"글이 말보다 언제나 정확해서","mis":"K6-2-u5-X03"}],"explanation":["말은 흐름을 이어 주지만 놓치면 사라져요.","칠판의 글은 남아요.","두 언어가 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#8','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C6',4,'mc','auto','「다음 주 목요일 텃밭 가꾸기」를 알리는 가장 알맞은 방법과 까닭을 함께 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":8,"concept":"K6-2-u5-C6","difficulty":4,"kind":"mc","stem":"「다음 주 목요일 텃밭 가꾸기」를 알리는 가장 알맞은 방법과 까닭을 함께 말한 것은 어느 것인가요?","options":[{"t":"방송으로 알리고 게시판에도 붙인다 — 말로는 중요한 곳을 힘주어 전하고, 글로는 여러 날 뒤에도 챙길 것을 다시 볼 수 있으니까","correct":true},{"t":"방송만 한다 — 목소리가 크면 누구나 기억하니까","mis":"K6-2-u5-X02"},{"t":"게시판에만 붙인다 — 글이 말보다 좋은 방법이니까","mis":"K6-2-u5-X03"},{"t":"아무 방법이나 괜찮다 — 어차피 내용은 같으니까","mis":"K6-2-u5-X10"}],"explanation":["여러 날 뒤의 일이라 다시 봐야 해요.","말은 귀에 띄게 강조할 수 있어요.","둘을 함께 쓰고 까닭을 특성과 이어요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#9','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C4',4,'essay','teacher','텃밭 안내 글과 방송을 견주어, 중요한 내용을 알리는 방법이 어떻게 다른지 쓰고, 각각의 방법이 어떤 언어의 특성 때문인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C4","difficulty":4,"kind":"essay","stem":"텃밭 안내 글과 방송을 견주어, 중요한 내용을 알리는 방법이 어떻게 다른지 쓰고, 각각의 방법이 어떤 언어의 특성 때문인지 쓰세요.","answer_guide":{"answer":"예: 안내 글은 목장갑과 겉옷을 굵은 글씨로 쓰고 줄을 나누어 눈에 띄게 했다. 문자 언어는 글자의 크기 · 굵기 · 줄 나눔으로 중요한 곳을 눈에 보이게 하기 때문이다. 방송은 목장갑 부분을 크고 또박또박하게, 모종 부분을 천천히 말해 귀에 띄게 했다. 음성 언어는 목소리의 크기 · 억양 · 속도로 강조하기 때문이다.","scoring_points":["안내 글의 강조 방법을 썼는가","방송의 강조 방법을 썼는가","각 방법을 해당 언어의 특성과 이었는가"]},"explanation":["글은 눈에 띄게.","말은 귀에 띄게.","방법마다 특성과 이어요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L02_challenge#10','kor',6,2,'u5','L02','g6_2_kor_u5_L02_challenge','lesson_challenge','K6-2-u5-C7',4,'essay','teacher','어렵거나 헷갈리는 내용을 알릴 때 말과 글을 함께 쓰면 좋은 까닭을 두 언어의 특성으로 설명하고, 우리 반에서 말과 글을 함께 쓰면 좋을 상황을 하나 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C7","difficulty":4,"kind":"essay","stem":"어렵거나 헷갈리는 내용을 알릴 때 말과 글을 함께 쓰면 좋은 까닭을 두 언어의 특성으로 설명하고, 우리 반에서 말과 글을 함께 쓰면 좋을 상황을 하나 들어 쓰세요.","answer_guide":{"answer":"예: 말로 설명하면 목소리와 억양으로 생생하게 전하고 그 자리에서 되물을 수 있지만, 놓치면 되돌릴 수 없다. 같은 내용을 글로도 보여 주면 남아 있어서 놓친 곳을 다시 확인할 수 있다. 그래서 둘을 함께 쓰면 서로 보완한다. 상황 — 학예회 무대 차례와 모이는 곳을 알릴 때 선생님이 말로 설명하고 칠판에도 적어 준다.","scoring_points":["음성 언어의 장점과 한계를 썼는가","문자 언어가 보완하는 점을 썼는가","알맞은 상황을 들었는가"]},"explanation":["말은 생생하지만 사라져요.","글은 남아요.","어렵고 헷갈릴수록 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#1','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',1,'mc','auto','영상에서 [자막]은 무엇을 가리키나요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":1,"concept":"K6-2-u5-C8","difficulty":1,"kind":"mc","stem":"영상에서 [자막]은 무엇을 가리키나요?","options":[{"t":"화면에 글자로 뜨는 말","correct":true},{"t":"해설하는 사람이 하는 말","mis":"K6-2-u5-X12"},{"t":"배경에 깔리는 음악","mis":"K6-2-u5-X12"},{"t":"그때 보이는 장면","mis":"K6-2-u5-X12"}],"explanation":["해설하는 말은 [말]이에요.","음악은 [소리], 장면은 [화면]이에요.","글자로 뜨는 말이 자막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#2','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',1,'mc','auto','이 영상이 전하려는 것은 무엇인가요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":2,"concept":"K6-2-u5-C8","difficulty":1,"kind":"mc","stem":"이 영상이 전하려는 것은 무엇인가요?","options":[{"t":"서로 잠깐 기다려 주면 다치는 일을 막을 수 있다","correct":true},{"t":"승강기는 되도록 타지 않는 것이 좋다","mis":"K6-2-u5-X12"},{"t":"승강기를 탈 때에는 빨리 움직여야 한다","mis":"K6-2-u5-X12"},{"t":"열림 단추는 누르면 안 된다","mis":"K6-2-u5-X12"}],"explanation":["장면 이에서 뛰어드는 위험을 보여 줘요.","장면 삼에서 열림 단추를 누르면 된다고 알려 줘요.","마지막에 「잠깐만 기다려 주세요」라고 부탁해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#3','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',1,'ox','auto','자막은 꼭 남겨야 할 내용을 눈에 보이게 붙들어 두는 일을 해요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":3,"concept":"K6-2-u5-C9","difficulty":1,"kind":"ox","stem":"자막은 꼭 남겨야 할 내용을 눈에 보이게 붙들어 두는 일을 해요.","answer":"O","reason_options":[{"t":"말은 지나가지만 글자는 화면에 남아 다시 볼 수 있기 때문에","correct":true},{"t":"자막은 영상을 꾸미는 장식일 뿐이기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["해설하는 말은 지나가요.","자막은 화면에 글자로 남아요.","그래서 놓친 내용을 다시 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#4','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C3',1,'mc','auto','책과 신문은 어떤 매체인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"책과 신문은 어떤 매체인가요?","options":[{"t":"인쇄 매체","correct":true},{"t":"음성 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"소리 매체","mis":"K6-2-u5-X04"}],"explanation":["책과 신문은 글자를 바탕으로 해요.","표 · 그림 · 사진을 함께 써요.","그래서 인쇄 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#5','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',2,'match','auto','장면과 그 장면에서 쓴 방법을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":2,"kind":"match","stem":"장면과 그 장면에서 쓴 방법을 이으세요.","pairs":[{"l":"장면 이 — 뛰어드는 순간","r":"음악을 그치고 자막으로 위험을 알림"},{"l":"장면 삼 — 열림 단추","r":"말과 자막으로 할 일을 함께 알림"},{"l":"장면 사 — 마지막 부탁","r":"장면과 말로 부탁을 남김"}],"mis":"K6-2-u5-X12","explanation":["장면 이에서는 음악이 뚝 그쳐요.","장면 삼에서는 말과 자막을 함께 써요.","장면 사에서는 웃는 장면과 말이 남아요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#6','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'mc','auto','말한 내용을 자막으로 함께 보여 주면 좋은 까닭은 무엇인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X13']::text[],false,'{"seq":6,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"말한 내용을 자막으로 함께 보여 주면 좋은 까닭은 무엇인가요?","options":[{"t":"놓치거나 헷갈리는 내용을 눈으로 다시 확인할 수 있어서","correct":true},{"t":"영상의 길이를 짧게 줄일 수 있어서","mis":"K6-2-u5-X11"},{"t":"화면에 들어가는 글자 수를 늘릴 수 있어서","mis":"K6-2-u5-X13"},{"t":"해설하는 말을 하지 않아도 되어서","mis":"K6-2-u5-X11"}],"explanation":["말은 지나가요.","자막은 화면에 남아요.","둘이 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#7','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C8',2,'mc','auto','장면 이에서 음악이 뚝 그친 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12']::text[],false,'{"seq":7,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"장면 이에서 음악이 뚝 그친 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"위험한 순간에 눈길을 모으려고","correct":true},{"t":"음악이 다 끝나서","mis":"K6-2-u5-X14"},{"t":"영상이 고장 나서","mis":"K6-2-u5-X14"},{"t":"해설하는 사람이 쉬려고","mis":"K6-2-u5-X12"}],"explanation":["조용한 음악이 흐르다 갑자기 그쳐요.","그 순간 화면도 멈춰요.","소리를 바꾸어 어디를 눈여겨볼지 알려요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#8','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C10',2,'ox','auto','자막을 화면 가득 채울수록 전하려는 것이 또렷해져요.',ARRAY['K6-2-u5-X13']::text[],false,'{"seq":8,"concept":"K6-2-u5-C10","difficulty":2,"kind":"ox","stem":"자막을 화면 가득 채울수록 전하려는 것이 또렷해져요.","answer":"X","reason_options":[{"t":"무엇이 중요한지 흐려지기 때문에","correct":true},{"t":"글자가 많을수록 많이 전해지기 때문에","mis":"K6-2-u5-X13"}],"mis":"K6-2-u5-X13","explanation":["자막이 너무 많으면 어디를 봐야 할지 몰라요.","꼭 남길 곳에만 자막을 둬요.","표현 효과는 개수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#9','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C9',2,'mc','auto','자막에서 중요한 곳을 강조하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X12']::text[],false,'{"seq":9,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"자막에서 중요한 곳을 강조하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"색 · 크기 · 모양을 달리한다","correct":true},{"t":"목소리의 억양을 올린다","mis":"K6-2-u5-X06"},{"t":"효과음을 크게 넣는다","mis":"K6-2-u5-X12"},{"t":"말을 천천히 한다","mis":"K6-2-u5-X06"}],"explanation":["억양 · 효과음 · 말의 속도는 소리로 하는 강조예요.","자막은 글자예요.","글자의 색 · 크기 · 모양으로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_basic#10','kor',6,2,'u5','L04','g6_2_kor_u5_L04_basic','lesson_basic','K6-2-u5-C10',3,'error','auto','매체 자료의 표현 효과에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X10']::text[],false,'{"seq":10,"concept":"K6-2-u5-C10","difficulty":3,"kind":"error","stem":"매체 자료의 표현 효과에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「자막 · 음악 · 장면을 많이 넣을수록 표현 효과가 좋은 영상이야.」","correct":true,"mis_target":"K6-2-u5-X13"},{"t":"연우 — 「중요한 곳에서 소리를 바꾸면 눈길이 모여.」","mis":"K6-2-u5-X10"},{"t":"지민 — 「그 요소가 무엇을 돕고 있는지를 봐야 해.」","mis":"K6-2-u5-X10"}],"explanation":["연우와 지민은 바르게 말했어요.","하율은 개수로 효과를 쟀어요.","표현 효과는 무엇을 돕는가로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#1','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C8',2,'mc','auto','영상에서 [화면] — 장면과 움직임이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X12','K6-2-u5-X05']::text[],false,'{"seq":1,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"영상에서 [화면] — 장면과 움직임이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 일이 벌어지는지 한눈에 보여 준다","correct":true},{"t":"꼭 남겨야 할 내용을 글자로 붙들어 둔다","mis":"K6-2-u5-X12"},{"t":"흐름을 말로 이어 준다","mis":"K6-2-u5-X12"},{"t":"영상을 만든 날짜를 알려 준다","mis":"K6-2-u5-X05"}],"explanation":["글자로 붙들기는 자막이 해요.","말로 잇기는 해설이 해요.","장면은 일이 벌어지는 모습을 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#2','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C8',2,'ox','auto','이 영상은 문자 언어 없이 음성 언어만 썼어요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":2,"concept":"K6-2-u5-C8","difficulty":2,"kind":"ox","stem":"이 영상은 문자 언어 없이 음성 언어만 썼어요.","answer":"X","reason_options":[{"t":"장면 이와 장면 삼에 자막이 있기 때문에","correct":true},{"t":"영상에는 글자를 넣을 수 없기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["[자막]이 문자 언어예요.","장면 이와 장면 삼에 자막이 있어요.","말과 자막을 함께 썼어요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#3','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',3,'mc','auto','장면 삼에서 「열림 단추」를 말로도 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X08','K6-2-u5-X13']::text[],false,'{"seq":3,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"장면 삼에서 「열림 단추」를 말로도 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해야 할 일을 놓치지 않고 눈으로도 확인하게 하려고","correct":true},{"t":"같은 말을 두 번 해서 영상을 길게 하려고","mis":"K6-2-u5-X11"},{"t":"말만으로는 감정을 전할 수 없어서","mis":"K6-2-u5-X08"},{"t":"자막이 많을수록 좋은 영상이라서","mis":"K6-2-u5-X13"}],"explanation":["열림 단추를 누르는 것이 시청자가 할 일이에요.","말은 지나가지만 자막은 남아요.","할 일을 두 언어로 붙들어 줬어요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#4','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C4',3,'mc','auto','매체마다 주로 쓰는 방법을 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":3,"kind":"mc","stem":"매체마다 주로 쓰는 방법을 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"라디오 — 음성 언어에 소리와 음악을 더한다","correct":true},{"t":"신문 — 음성 언어에 움직임을 더한다","mis":"K6-2-u5-X04"},{"t":"공익 영상 — 문자 언어만 쓴다","mis":"K6-2-u5-X04"},{"t":"책 — 소리와 음악을 바탕으로 한다","mis":"K6-2-u5-X04"}],"explanation":["신문과 책은 문자 언어가 바탕이에요.","영상은 여러 방법이 어우러져요.","라디오는 소리로 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#5','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C12',3,'error','auto','영상의 요소가 하는 일을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":5,"concept":"K6-2-u5-C12","difficulty":3,"kind":"error","stem":"영상의 요소가 하는 일을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「배경 음악은 꼭 남겨야 할 낱말을 글자로 보여 줘.」","correct":true,"mis_target":"K6-2-u5-X12"},{"t":"소윤 — 「해설하는 말은 장면과 장면 사이의 흐름을 이어 줘.」","mis":"K6-2-u5-X12"},{"t":"다인 — 「자막은 놓치기 쉬운 것을 붙들어 둬.」","mis":"K6-2-u5-X12"}],"explanation":["소윤과 다인은 바르게 말했어요.","글자로 보여 주는 것은 자막이에요.","음악은 어디를 눈여겨볼지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#6','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',3,'mc','auto','어떤 영상이 처음부터 끝까지 큰 음악을 깔고 장면을 쉴 새 없이 바꾸었어요. 어떤 문제가 생기나요?',ARRAY['K6-2-u5-X13','K6-2-u5-X04']::text[],false,'{"seq":6,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"어떤 영상이 처음부터 끝까지 큰 음악을 깔고 장면을 쉴 새 없이 바꾸었어요. 어떤 문제가 생기나요?","options":[{"t":"무엇이 중요한지 흐려져 전하려는 것이 잘 보이지 않는다","correct":true},{"t":"신나는 느낌이 나서 전하려는 것이 더 또렷해진다","mis":"K6-2-u5-X13"},{"t":"아무 문제가 없다. 요소가 많을수록 좋다","mis":"K6-2-u5-X13"},{"t":"자막을 하나도 쓰지 않았으니 영상이 아니다","mis":"K6-2-u5-X04"}],"explanation":["계속 크면 중요한 곳에서 소리를 바꿀 수 없어요.","장면이 쉴 새 없이 바뀌면 오래 볼 수 없어요.","요소가 많다고 잘 전달되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#7','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',3,'match','auto','강조하는 방법과 그 방법을 쓰는 것을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C9","difficulty":3,"kind":"match","stem":"강조하는 방법과 그 방법을 쓰는 것을 이으세요.","pairs":[{"l":"자막의 색과 크기를 달리한다","r":"문자 언어"},{"l":"목소리를 크고 또박또박하게 한다","r":"음성 언어"},{"l":"중요한 곳에서 음악을 그친다","r":"소리와 음악"}],"mis":"K6-2-u5-X06","explanation":["자막은 글자로 강조해요.","목소리는 말로 강조해요.","음악을 바꾸면 소리로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#8','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',4,'mc','auto','「잠깐만 기다려 주세요」 영상에 대한 평가로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X14','K6-2-u5-X15']::text[],false,'{"seq":8,"concept":"K6-2-u5-C10","difficulty":4,"kind":"mc","stem":"「잠깐만 기다려 주세요」 영상에 대한 평가로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면 이에서 음악을 그치고 자막을 쓴 것은 위험한 순간을 눈여겨보게 도와 표현 효과가 있다","correct":true},{"t":"자막이 두 번밖에 없어 표현 효과가 적다","mis":"K6-2-u5-X13"},{"t":"음악이 그친 것은 실수라서 고쳐야 한다","mis":"K6-2-u5-X14"},{"t":"그냥 좋은 영상이다","mis":"K6-2-u5-X15"}],"explanation":["자막 수로 효과를 재지 않아요.","음악이 그친 것은 까닭이 있어요.","그 요소가 무엇을 돕는지 말해야 평가가 돼요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#9','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C9',4,'essay','teacher','「잠깐만 기다려 주세요」 영상에서 말과 자막이 서로 어떻게 보완하는지 장면 하나를 골라 쓰고, 음악이 한 일도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C9","difficulty":4,"kind":"essay","stem":"「잠깐만 기다려 주세요」 영상에서 말과 자막이 서로 어떻게 보완하는지 장면 하나를 골라 쓰고, 음악이 한 일도 함께 쓰세요.","answer_guide":{"answer":"예: 장면 삼에서 해설하는 사람은 「안에서 열림 단추를 눌러 주면 됩니다.」라고 말하고, 자막으로 「열림 단추 ← 문 옆」을 보여 준다. 말은 흐름을 이어 주지만 지나가 버리는데, 자막은 단추가 어디에 있는지를 눈으로 다시 확인하게 해 준다. 음악은 장면 이에서 뚝 그쳐 뛰어드는 순간이 위험하다는 것을 눈여겨보게 했다.","scoring_points":["장면 하나를 골라 말과 자막을 찾았는가","말과 자막이 서로 보완하는 점을 썼는가","음악이 한 일을 썼는가"]},"explanation":["말은 흐름을 이어요.","자막은 붙들어 둬요.","음악은 눈여겨볼 곳을 알려요."],"asset":{"type":"passage","lines":["장면 일 [화면] 승강기 문이 서서히 닫힌다. [소리] 낮고 조용한 음악.","[말] 하루에도 여러 번 타는 승강기입니다.","장면 이 [화면] 닫히는 문으로 한 사람이 뛰어든다. 화면이 멈춘다.","[소리] 음악이 뚝 그친다. [자막] 손이나 옷이 끼일 수 있습니다","장면 삼 [화면] 안에 있던 사람이 문 옆의 열림 단추를 누른다.","[말] 안에서 열림 단추를 눌러 주면 됩니다. [자막] 열림 단추 ← 문 옆","장면 사 [화면] 두 사람이 나란히 서서 웃는다. [소리] 잔잔한 음악.","[말] 잠깐만 기다려 주세요."],"title":"공익 안내 영상 「잠깐만 기다려 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L04_challenge#10','kor',6,2,'u5','L04','g6_2_kor_u5_L04_challenge','lesson_challenge','K6-2-u5-C10',4,'essay','teacher','「표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다.」는 말을 예를 들어 설명하고, 둘레의 안내문이나 영상 하나를 떠올려 「이 ○○은 △△을 돕는다」 꼴로 한 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C10","difficulty":4,"kind":"essay","stem":"「표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다.」는 말을 예를 들어 설명하고, 둘레의 안내문이나 영상 하나를 떠올려 「이 ○○은 △△을 돕는다」 꼴로 한 문장을 쓰세요.","answer_guide":{"answer":"예: 자막을 화면 가득 채우거나 음악을 계속 크게 깔면 요소는 많아도 무엇이 중요한지 흐려진다. 꼭 남길 곳에만 자막을 두고 중요한 곳에서 소리를 바꾸면 요소가 적어도 전하려는 것이 또렷해진다. 문장 — 우리 학교 급식실 안내판의 빨간 글씨는 뜨거운 국 조심을 놓치지 않게 돕는다.","scoring_points":["많이 넣을 때의 문제를 예로 썼는가","알맞게 넣을 때의 효과를 썼는가","요소와 그것이 돕는 것을 이어 한 문장을 썼는가"]},"explanation":["개수로 재지 않아요.","무엇을 돕는지 봐요.","「이 ○○은 △△을 돕는다」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#1','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',1,'mc','auto','바닷물이 뭍 쪽으로 밀려 들어오는 것을 무엇이라고 하나요?',ARRAY['K6-2-u5-X18']::text[],false,'{"seq":1,"concept":"K6-2-u5-C13","difficulty":1,"kind":"mc","stem":"바닷물이 뭍 쪽으로 밀려 들어오는 것을 무엇이라고 하나요?","options":[{"t":"밀물","correct":true},{"t":"썰물","mis":"K6-2-u5-X18"},{"t":"퇴적","mis":"K6-2-u5-X18"},{"t":"갯벌","mis":"K6-2-u5-X18"}],"explanation":["바다 쪽으로 빠져나가는 것은 썰물이에요.","쌓이는 일은 퇴적이에요.","밀려 들어오는 것이 밀물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#2','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',1,'sa','auto','흙이나 모래 같은 것이 물이나 바람의 힘으로 쌓이는 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C13","difficulty":1,"kind":"sa","stem":"흙이나 모래 같은 것이 물이나 바람의 힘으로 쌓이는 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["퇴적"],"explanation":["강물이 흙과 모래를 실어 와요.","물살이 느려지면 가라앉아 쌓여요.","이렇게 쌓이는 일이 퇴적이에요."],"mis":"K6-2-u5-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#3','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',1,'mc','auto','이 영상은 무엇을 다루고 있나요?',ARRAY['K6-2-u5-X17']::text[],false,'{"seq":3,"concept":"K6-2-u5-C13","difficulty":1,"kind":"mc","stem":"이 영상은 무엇을 다루고 있나요?","options":[{"t":"갯벌이 만들어지는 과정","correct":true},{"t":"바닷물이 오염되는 까닭","mis":"K6-2-u5-X17"},{"t":"배가 항구에 드나드는 차례","mis":"K6-2-u5-X17"},{"t":"강물이 얼어붙는 과정","mis":"K6-2-u5-X17"}],"explanation":["장면 일의 자막이 다룰 내용을 알려 줘요.","장면 이에서 흙과 모래가 흘러가요.","갯벌이 어떻게 만들어지는지를 다뤄요."],"asset":{"type":"passage","lines":["장면 일 [화면] 물이 빠진 바닷가에 끝없는 흙벌판이 펼쳐진다.","[소리] 잔잔한 파도 소리와 낮은 음악. [자막] 갯벌은 어떻게 만들어질까","장면 이 [화면] 뿌연 강물을 따라 흙과 모래가 함께 흘러간다.","[말] 강물은 흙과 모래를 조금씩 싣고 바다로 흘러갑니다.","[자막] 강물이 실어 오는 것 · 고운 흙과 모래"],"title":"갯벌 영상 (장면 일~이)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#4','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',1,'ox','auto','장면 일에서는 자막으로 영상의 제목을 보여 주었어요.',ARRAY['K6-2-u5-X14']::text[],false,'{"seq":4,"concept":"K6-2-u5-C11","difficulty":1,"kind":"ox","stem":"장면 일에서는 자막으로 영상의 제목을 보여 주었어요.","answer":"O","reason_options":[{"t":"무엇을 다룰 영상인지 먼저 알리려고 썼기 때문에","correct":true},{"t":"자막은 아무 장면에나 넣는 것이기 때문에","mis":"K6-2-u5-X14"}],"mis":"K6-2-u5-X14","explanation":["장면 일의 자막은 「갯벌은 어떻게 만들어질까」예요.","무엇을 다룰지 먼저 알려 줘요.","장면마다 할 일이 있어요."],"asset":{"type":"passage","lines":["장면 일 [화면] 물이 빠진 바닷가에 끝없는 흙벌판이 펼쳐진다.","[소리] 잔잔한 파도 소리와 낮은 음악. [자막] 갯벌은 어떻게 만들어질까","장면 이 [화면] 뿌연 강물을 따라 흙과 모래가 함께 흘러간다.","[말] 강물은 흙과 모래를 조금씩 싣고 바다로 흘러갑니다.","[자막] 강물이 실어 오는 것 · 고운 흙과 모래"],"title":"갯벌 영상 (장면 일~이)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#5','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C13',2,'mc','auto','갯벌은 어떻게 만들어지나요?',ARRAY['K6-2-u5-X17','K6-2-u5-X18']::text[],false,'{"seq":5,"concept":"K6-2-u5-C13","difficulty":2,"kind":"mc","stem":"갯벌은 어떻게 만들어지나요?","options":[{"t":"강과 바다가 실어 온 고운 흙과 모래가 얕은 바닥에 오래 쌓여서","correct":true},{"t":"바다 밑에서 뜨거운 것이 솟아올라 굳어서","mis":"K6-2-u5-X17"},{"t":"바닷물이 얼었다 녹으면서 땅이 갈라져서","mis":"K6-2-u5-X17"},{"t":"밀물 때 물에 잠긴 땅이 깎여 나가서","mis":"K6-2-u5-X18"}],"explanation":["장면 이에서 흙과 모래가 흘러가요.","장면 삼에서 물살이 느린 곳에 쌓여요.","아주 오랜 시간이 걸려요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#6','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',2,'mc','auto','장면 사에서 음악이 밝고 빨라진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12']::text[],false,'{"seq":6,"concept":"K6-2-u5-C11","difficulty":2,"kind":"mc","stem":"장면 사에서 음악이 밝고 빨라진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생물이 사는 곳이라는 느낌을 살리려고","correct":true},{"t":"영상이 곧 끝난다는 것을 알리려고","mis":"K6-2-u5-X14"},{"t":"낯선 낱말을 정확하게 남기려고","mis":"K6-2-u5-X12"},{"t":"아무 까닭 없이 바꾼 것이다","mis":"K6-2-u5-X14"}],"explanation":["게와 조개가 움직이는 장면이에요.","느낌을 바꿀 때 음악의 빠르기를 바꿔요.","낱말을 남기는 것은 말과 자막이 해요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#7','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C11',2,'match','auto','장면과 그 방법을 쓴 까닭을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C11","difficulty":2,"kind":"match","stem":"장면과 그 방법을 쓴 까닭을 이으세요.","pairs":[{"l":"장면 일 — 자막으로 제목","r":"무엇을 다룰 영상인지 먼저 알리려고"},{"l":"장면 삼 — 말과 자막을 함께","r":"낯선 낱말을 정확하게 남기려고"},{"l":"장면 사 — 음악이 밝고 빨라짐","r":"생물이 사는 곳이라는 느낌을 살리려고"}],"mis":"K6-2-u5-X14","explanation":["제목은 처음에 알려요.","퇴적 같은 낱말은 말과 자막으로 남겨요.","느낌은 음악으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#8','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',2,'mc','auto','감상을 말한 것 가운데 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X16']::text[],false,'{"seq":8,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"감상을 말한 것 가운데 알맞은 것은 어느 것인가요?","options":[{"t":"장면 삼에서 말과 자막을 함께 써서 「퇴적」이라는 낱말이 잘 남았다","correct":true},{"t":"그냥 다 좋았다. 재미있었다","mis":"K6-2-u5-X15"},{"t":"별로였다","mis":"K6-2-u5-X15"},{"t":"자막을 좋아하지 않는 사람은 이 영상을 잘못 본 것이다","mis":"K6-2-u5-X16"}],"explanation":["느낌만 말하면 까닭이 없어요.","느낌이 다르다고 잘못 본 것은 아니에요.","어떤 표현 때문인지 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#9','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',2,'ox','auto','어느 장면이 가장 인상 깊었는지는 사람마다 다를 수 있어요.',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":9,"concept":"K6-2-u5-C12","difficulty":2,"kind":"ox","stem":"어느 장면이 가장 인상 깊었는지는 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"느낌은 사람마다 달라도 괜찮기 때문에","correct":true},{"t":"느낌은 정답이 하나뿐이기 때문에","mis":"K6-2-u5-X16"}],"mis":"K6-2-u5-X16","explanation":["인상 깊은 장면은 사람마다 달라요.","그 장면에 무엇이 쓰였는지는 함께 확인할 수 있어요.","느낌과 까닭을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_basic#10','kor',6,2,'u5','L05','g6_2_kor_u5_L05_basic','lesson_basic','K6-2-u5-C12',3,'error','auto','영상 감상의 세 걸음을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X15']::text[],false,'{"seq":10,"concept":"K6-2-u5-C12","difficulty":3,"kind":"error","stem":"영상 감상의 세 걸음을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「세 번째 걸음은 영상을 만든 사람의 이름을 찾는 거야.」","correct":true,"mis_target":"K6-2-u5-X05"},{"t":"나래 — 「먼저 장면에 말 · 글 · 그림 · 소리 가운데 무엇이 쓰였는지 찾아.」","mis":"K6-2-u5-X15"},{"t":"윤호 — 「그것이 이해를 무엇으로 돕는지 이어 보는 거야.」","mis":"K6-2-u5-X15"}],"explanation":["세 걸음은 찾기 · 잇기 · 말하기예요.","나래와 윤호는 바르게 말했어요.","마지막은 느낀 것과 까닭을 말하는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#1','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',2,'mc','auto','밀물 때 물에 잠기고 썰물 때 드러나는 넓고 평평한 바닷가 땅은 무엇인가요?',ARRAY['K6-2-u5-X18']::text[],false,'{"seq":1,"concept":"K6-2-u5-C13","difficulty":2,"kind":"mc","stem":"밀물 때 물에 잠기고 썰물 때 드러나는 넓고 평평한 바닷가 땅은 무엇인가요?","options":[{"t":"갯벌","correct":true},{"t":"모래섬","mis":"K6-2-u5-X18"},{"t":"강어귀","mis":"K6-2-u5-X18"},{"t":"여울","mis":"K6-2-u5-X18"}],"explanation":["하루에 두 번쯤 드러났다 잠겨요.","게 · 조개 · 갯지렁이가 살아요.","이 땅이 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#2','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',2,'ox','auto','갯벌은 뭍에서 흘러든 물을 걸러 주기도 해요.',ARRAY['K6-2-u5-X17']::text[],false,'{"seq":2,"concept":"K6-2-u5-C13","difficulty":2,"kind":"ox","stem":"갯벌은 뭍에서 흘러든 물을 걸러 주기도 해요.","answer":"O","reason_options":[{"t":"장면 오의 말과 자막에서 확인할 수 있기 때문에","correct":true},{"t":"영상에 나오지 않았지만 그럴 것 같기 때문에","mis":"K6-2-u5-X17"}],"mis":"K6-2-u5-X17","explanation":["장면 오에서 해설하는 말이 있어요.","자막에도 「물을 걸러 주는 곳」이 있어요.","영상 안에서 확인한 내용이에요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#3','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C11',3,'mc','auto','장면 삼에서 「퇴적」을 말로 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":3,"concept":"K6-2-u5-C11","difficulty":3,"kind":"mc","stem":"장면 삼에서 「퇴적」을 말로 하고 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음 듣는 낱말을 정확하게 남기려고","correct":true},{"t":"영상을 길게 만들려고","mis":"K6-2-u5-X14"},{"t":"생물이 사는 곳이라는 느낌을 살리려고","mis":"K6-2-u5-X12"},{"t":"자막이 많을수록 좋은 영상이라서","mis":"K6-2-u5-X13"}],"explanation":["퇴적은 낯선 낱말이에요.","말로만 하면 지나가 버려요.","자막으로 붙들어 정확히 남겨요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#4','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',3,'mc','auto','갈릴 수 있는 것과 함께 확인할 수 있는 것을 바르게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":4,"concept":"K6-2-u5-C12","difficulty":3,"kind":"mc","stem":"갈릴 수 있는 것과 함께 확인할 수 있는 것을 바르게 나눈 것은 어느 것인가요?","options":[{"t":"갈릴 수 있는 것 — 음악이 잘 어울렸는가 / 함께 확인할 수 있는 것 — 그 장면에 무엇이 쓰였는가","correct":true},{"t":"갈릴 수 있는 것 — 장면 삼에 자막이 있는가 / 함께 확인할 수 있는 것 — 가장 인상 깊은 장면","mis":"K6-2-u5-X16"},{"t":"모두 사람마다 다르니 확인할 수 있는 것은 없다","mis":"K6-2-u5-X16"},{"t":"모두 정답이 하나이니 느낌도 하나여야 한다","mis":"K6-2-u5-X16"}],"explanation":["어울렸는지는 느낌이라 갈려요.","무엇이 쓰였는지는 영상에서 찾을 수 있어요.","둘을 갈라 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#5','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C8',3,'mc','auto','이 영상이 내용을 전한 방법이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":3,"kind":"mc","stem":"이 영상이 내용을 전한 방법이 아닌 것은 어느 것인가요?","options":[{"t":"영상을 본 사람의 수","correct":true},{"t":"해설하는 사람의 말","mis":"K6-2-u5-X05"},{"t":"보여 주는 장면과 화면의 움직임","mis":"K6-2-u5-X05"},{"t":"배경 음악의 빠르기 바꾸기","mis":"K6-2-u5-X05"}],"explanation":["말 · 장면 · 음악은 영상 안에서 뜻을 날라요.","본 사람의 수는 영상 밖의 정보예요.","표시가 있는 것만 찾아요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#6','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',3,'error','auto','갯벌 영상의 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X18','K6-2-u5-X17']::text[],false,'{"seq":6,"concept":"K6-2-u5-C13","difficulty":3,"kind":"error","stem":"갯벌 영상의 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「썰물은 바닷물이 뭍 쪽으로 밀려 들어오는 거야.」","correct":true,"mis_target":"K6-2-u5-X18"},{"t":"채아 — 「물살이 느려지는 얕은 바닥에 고운 흙이 쌓여.」","mis":"K6-2-u5-X17"},{"t":"도하 — 「갯벌은 하루에 두 번쯤 드러났다 잠겨.」","mis":"K6-2-u5-X17"}],"explanation":["채아와 도하는 영상 내용을 바르게 말했어요.","밀려 들어오는 것은 밀물이에요.","썰물은 빠져나가는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#7','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',3,'mc','auto','다른 교과 시간에 본 영상으로 세 걸음 감상을 했어요. 차례가 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X05','K6-2-u5-X16']::text[],false,'{"seq":7,"concept":"K6-2-u5-C12","difficulty":3,"kind":"mc","stem":"다른 교과 시간에 본 영상으로 세 걸음 감상을 했어요. 차례가 알맞은 것은 어느 것인가요?","options":[{"t":"자막과 그래프를 찾기 → 그래프가 수의 변화를 한눈에 보여 준다고 잇기 → 그래서 이해가 쉬웠다고 까닭과 함께 말하기","correct":true},{"t":"재미있었다고 말하기 → 끝","mis":"K6-2-u5-X15"},{"t":"영상 길이 재기 → 본 사람 수 세기 → 말하기","mis":"K6-2-u5-X05"},{"t":"느낌이 나와 다른 친구 찾기 → 고쳐 주기","mis":"K6-2-u5-X16"}],"explanation":["찾기 · 잇기 · 말하기 차례예요.","영상 밖의 정보는 찾지 않아요.","느낌에는 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#8','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C11',4,'mc','auto','갯벌 영상의 다섯 장면에 대한 평가로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":8,"concept":"K6-2-u5-C11","difficulty":4,"kind":"mc","stem":"갯벌 영상의 다섯 장면에 대한 평가로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면마다 해야 할 일이 달라 제목에는 자막, 낯선 낱말에는 말과 자막, 생물이 사는 모습에는 밝은 음악을 골라 썼다","correct":true},{"t":"장면마다 방법이 달라 한 가지로 통일해야 한다","mis":"K6-2-u5-X14"},{"t":"음악이 바뀌는 것은 시청자를 헷갈리게 하니 빼야 한다","mis":"K6-2-u5-X12"},{"t":"자막이 많은 장면일수록 잘 만든 장면이다","mis":"K6-2-u5-X13"}],"explanation":["방법이 다른 데에는 까닭이 있어요.","장면에서 해야 할 일을 먼저 봐요.","그 일에 맞는 방법을 골랐어요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#9','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C12',4,'essay','teacher','갯벌 영상에서 한 장면을 골라 세 걸음(찾기 · 잇기 · 말하기)으로 감상한 내용을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C12","difficulty":4,"kind":"essay","stem":"갯벌 영상에서 한 장면을 골라 세 걸음(찾기 · 잇기 · 말하기)으로 감상한 내용을 쓰세요.","answer_guide":{"answer":"예: 찾기 — 장면 사에서는 게와 조개가 움직이는 장면, 밝고 빨라진 음악, 「게 · 조개 · 갯지렁이가 사는 곳」이라는 자막이 쓰였다. 잇기 — 음악은 생물이 살아 움직이는 느낌을 살리고, 자막은 어떤 생물이 사는지를 정확히 남겨 준다. 말하기 — 그래서 나는 갯벌이 그냥 흙벌판이 아니라 살아 있는 곳이라고 느꼈다. 밝아진 음악 때문에 그렇게 느꼈다.","scoring_points":["장면에 쓰인 요소를 찾았는가","요소가 이해를 무엇으로 돕는지 이었는가","느낌과 그 까닭을 표현 방법과 이어 말했는가"]},"explanation":["무엇이 쓰였나 찾아요.","무엇을 돕나 이어요.","느낌과 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["장면 삼 [화면] 물이 느려지는 얕은 바닥에 고운 흙이 겹겹이 쌓인다.","[말] 물살이 느려지면 고운 흙이 가라앉아 쌓입니다. [자막] 퇴적","장면 사 [화면] 게가 구멍에서 나오고 조개가 흙 속으로 들어간다.","[소리] 음악이 밝고 빨라진다. [자막] 게 · 조개 · 갯지렁이가 사는 곳","장면 오 [화면] 다시 물이 차오르며 벌판이 천천히 잠긴다.","[말] 갯벌은 하루에 두 번쯤 드러났다 잠깁니다.","[자막] 하루에 두 번 · 물을 걸러 주는 곳"],"title":"갯벌 영상 (장면 삼~오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L05_challenge#10','kor',6,2,'u5','L05','g6_2_kor_u5_L05_challenge','lesson_challenge','K6-2-u5-C13',4,'essay','teacher','갯벌이 만들어지는 과정을 장면 차례에 따라 쓰고, 「밀물」 · 「썰물」 · 「퇴적」 가운데 두 낱말을 넣어 갯벌을 소개하는 문장을 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C13","difficulty":4,"kind":"essay","stem":"갯벌이 만들어지는 과정을 장면 차례에 따라 쓰고, 「밀물」 · 「썰물」 · 「퇴적」 가운데 두 낱말을 넣어 갯벌을 소개하는 문장을 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 강물이 흙과 모래를 싣고 바다로 흘러가고, 밀물과 썰물의 차가 큰 얕은 바닷가에서 물살이 느려지면 고운 흙이 가라앉아 아주 오랫동안 쌓여 갯벌이 된다. 문장 — 갯벌은 고운 흙의 퇴적으로 만들어진 땅으로, 썰물 때 드러나면 게와 조개가 나와 움직인다.","scoring_points":["흘러감 → 느려짐 → 쌓임의 차례를 썼는가","두 낱말을 뜻에 맞게 넣었는가","숫자 없이 썼는가"]},"explanation":["장면 차례를 이어요.","낱말 뜻을 정확히 알아요.","영상에서 확인한 것으로 써요."],"asset":{"type":"passage","lines":["장면 일 [화면] 물이 빠진 바닷가에 끝없는 흙벌판이 펼쳐진다.","[소리] 잔잔한 파도 소리와 낮은 음악. [자막] 갯벌은 어떻게 만들어질까","장면 이 [화면] 뿌연 강물을 따라 흙과 모래가 함께 흘러간다.","[말] 강물은 흙과 모래를 조금씩 싣고 바다로 흘러갑니다.","[자막] 강물이 실어 오는 것 · 고운 흙과 모래"],"title":"갯벌 영상 (장면 일~이)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#1','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',1,'mc','auto','독자를 고려한다는 것은 어떤 뜻인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X25']::text[],false,'{"seq":1,"concept":"K6-2-u5-C14","difficulty":1,"kind":"mc","stem":"독자를 고려한다는 것은 어떤 뜻인가요?","options":[{"t":"읽는 사람의 처지에서 헤아려 보는 것","correct":true},{"t":"독자가 좋아할 내용만 고르는 것","mis":"K6-2-u5-X20"},{"t":"어려운 이야기는 모두 빼 버리는 것","mis":"K6-2-u5-X20"},{"t":"글쓴이가 쓰고 싶은 대로 쓰는 것","mis":"K6-2-u5-X25"}],"explanation":["비위를 맞추는 것과는 달라요.","내 마음대로 쓰는 것도 아니에요.","읽는 사람의 처지에서 헤아려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#2','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',1,'mc','auto','글을 쓰는 세 단계 가운데 가장 먼저 하는 것은 어느 것인가요?',ARRAY['K6-2-u5-X21','K6-2-u5-X22']::text[],false,'{"seq":2,"concept":"K6-2-u5-C16","difficulty":1,"kind":"mc","stem":"글을 쓰는 세 단계 가운데 가장 먼저 하는 것은 어느 것인가요?","options":[{"t":"계획 세우기","correct":true},{"t":"글 쓰고 고쳐 쓰기","mis":"K6-2-u5-X21"},{"t":"내용 생성하고 조직하기","mis":"K6-2-u5-X21"},{"t":"제목 꾸미기","mis":"K6-2-u5-X22"}],"explanation":["먼저 누가 읽을지, 무엇을 왜 쓸지 정해요.","그다음 쓸 거리를 모아 차례를 짜요.","마지막에 쓰고 고쳐 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#3','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C17',1,'ox','auto','글에 자료를 많이 넣을수록 좋은 글이 돼요.',ARRAY['K6-2-u5-X23']::text[],false,'{"seq":3,"concept":"K6-2-u5-C17","difficulty":1,"kind":"ox","stem":"글에 자료를 많이 넣을수록 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"자료는 독자의 이해를 도울 때 넣는 것이기 때문에","correct":true},{"t":"자료가 많으면 글을 덜 써도 되기 때문에","mis":"K6-2-u5-X23"}],"mis":"K6-2-u5-X23","explanation":["자료는 개수를 채우는 것이 아니에요.","글만으로 어려운 곳을 도와요.","글과 이어지는 자료만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#4','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',1,'mc','auto','두 친구가 세인이의 첫 글을 어려워한 까닭은 무엇인가요?',ARRAY['K6-2-u5-X22']::text[],false,'{"seq":4,"concept":"K6-2-u5-C14","difficulty":1,"kind":"mc","stem":"두 친구가 세인이의 첫 글을 어려워한 까닭은 무엇인가요?","options":[{"t":"낱말이 어렵고, 읽는 사람이 무엇을 하면 되는지 없어서","correct":true},{"t":"글의 길이가 너무 짧아서","mis":"K6-2-u5-X22"},{"t":"글씨 색깔이 알록달록해서","mis":"K6-2-u5-X22"},{"t":"제목이 없어서","mis":"K6-2-u5-X22"}],"explanation":["「적치」 같은 낱말을 몰랐어요.","우리가 무엇을 하면 되는지도 없었어요.","독자를 생각하지 않은 글이에요."],"asset":{"type":"passage","lines":["우산 보관 실태와 개선 방안","본교 현관의 우산 보관 시설은 수용 능력이 부족한 실정이다.","강우 시 우산의 무질서한 적치로 인해 통행에 지장이 초래되며,","이는 낙상의 위험을 증대시킨다.","이에 보관 방식의 전면적 재검토가 요구된다."],"title":"세인이가 처음 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#5','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',2,'mc','auto','세인이가 다시 쓴 글에서 달라진 점이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X19','K6-2-u5-X25','K6-2-u5-X23']::text[],false,'{"seq":5,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"세인이가 다시 쓴 글에서 달라진 점이 아닌 것은 어느 것인가요?","options":[{"t":"글쓴이의 이름을 크게 적었다","correct":true},{"t":"읽는 사람이 아는 쉬운 낱말로 바꾸었다","mis":"K6-2-u5-X19"},{"t":"할 일을 기호로 나누어 보여 주었다","mis":"K6-2-u5-X25"},{"t":"직접 세어 본 자료를 넣었다","mis":"K6-2-u5-X23"}],"explanation":["쉬운 낱말 · 할 일 · 세어 본 자료가 새로 생겼어요.","이름을 크게 적은 곳은 없어요.","모두 독자를 생각한 고침이에요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#6','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',2,'match','auto','단계와 그 단계에서 하는 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C16","difficulty":2,"kind":"match","stem":"단계와 그 단계에서 하는 일을 이으세요.","pairs":[{"l":"계획 세우기","r":"읽을 사람이 누구인지 알아봅니다"},{"l":"내용 생성하고 조직하기","r":"쓸 거리를 모아 차례를 짭니다"},{"l":"글 쓰고 고쳐 쓰기","r":"오해할 곳이 없는지 다시 읽습니다"}],"mis":"K6-2-u5-X21","explanation":["쓰기 전에는 독자를 알아봐요.","쓰는 중에는 쓸 거리와 차례를 짜요.","쓴 뒤에는 오해할 곳을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#7','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C17',2,'mc','auto','수를 견주어 보여 줄 때 넣으면 좋은 자료는 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13']::text[],false,'{"seq":7,"concept":"K6-2-u5-C17","difficulty":2,"kind":"mc","stem":"수를 견주어 보여 줄 때 넣으면 좋은 자료는 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"사진이나 그림","mis":"K6-2-u5-X23"},{"t":"기호와 줄 나눔","mis":"K6-2-u5-X23"},{"t":"화려한 꾸밈 그림","mis":"K6-2-u5-X13"}],"explanation":["모습이나 차례는 사진이나 그림이 좋아요.","할 일은 기호와 줄 나눔이 좋아요.","수를 견줄 때는 표나 그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#8','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C15',2,'ox','auto','독자를 고려한다는 것은 독자가 좋아할 이야기만 골라 쓰는 거예요.',ARRAY['K6-2-u5-X20']::text[],false,'{"seq":8,"concept":"K6-2-u5-C15","difficulty":2,"kind":"ox","stem":"독자를 고려한다는 것은 독자가 좋아할 이야기만 골라 쓰는 거예요.","answer":"X","reason_options":[{"t":"전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이기 때문에","correct":true},{"t":"독자의 마음을 기쁘게 하는 것이 글의 목적이기 때문에","mis":"K6-2-u5-X20"}],"mis":"K6-2-u5-X20","explanation":["좋아할 것만 고르면 전하려는 것이 사라져요.","전하려는 것은 그대로 둬요.","닿는 방법을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#9','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C14',2,'mc','auto','독자를 고려할 때 살피는 네 가지에 들지 않는 것은 어느 것인가요?',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":9,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"독자를 고려할 때 살피는 네 가지에 들지 않는 것은 어느 것인가요?","options":[{"t":"글쓴이가 좋아하는 낱말","correct":true},{"t":"독자의 흥미","mis":"K6-2-u5-X19"},{"t":"독자의 배경지식","mis":"K6-2-u5-X19"},{"t":"독자가 글을 읽는 매체","mis":"K6-2-u5-X19"}],"explanation":["흥미 · 배경지식 · 수준 · 매체를 살펴요.","모두 독자에 관한 것이에요.","글쓴이의 취향은 들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_basic#10','kor',6,2,'u5','L07','g6_2_kor_u5_L07_basic','lesson_basic','K6-2-u5-C16',3,'error','auto','고쳐 쓸 때 볼 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X22']::text[],false,'{"seq":10,"concept":"K6-2-u5-C16","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 볼 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"아린 — 「글씨가 예쁜지, 줄이 반듯한지부터 봐야 해.」","correct":true,"mis_target":"K6-2-u5-X22"},{"t":"태민 — 「독자가 오해할 만한 표현이 없는지 봐.」","mis":"K6-2-u5-X22"},{"t":"세아 — 「독자의 수준에 맞는 낱말인지 봐.」","mis":"K6-2-u5-X22"}],"explanation":["태민과 세아는 바르게 말했어요.","고쳐 쓰기는 겉모습을 다듬는 일이 아니에요.","독자에게 더 잘 닿게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#1','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C16',2,'mc','auto','글을 쓸 때 독자는 언제 떠올려야 하나요?',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":1,"concept":"K6-2-u5-C16","difficulty":2,"kind":"mc","stem":"글을 쓸 때 독자는 언제 떠올려야 하나요?","options":[{"t":"계획 · 내용 조직 · 쓰고 고치기의 세 단계마다","correct":true},{"t":"계획을 세울 때 한 번만","mis":"K6-2-u5-X21"},{"t":"글을 다 쓴 뒤에만","mis":"K6-2-u5-X21"},{"t":"제목을 정할 때만","mis":"K6-2-u5-X21"}],"explanation":["독자는 처음에만 떠올리는 것이 아니에요.","단계마다 다시 떠올려요.","그래야 끝까지 독자에게 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#2','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C17',2,'sa','auto','세인이는 다시 쓴 글에서 할 일을 무엇으로 나누어 보여 주었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C17","difficulty":2,"kind":"sa","stem":"세인이는 다시 쓴 글에서 할 일을 무엇으로 나누어 보여 주었나요? 두 글자로 쓰세요.","answer":["기호"],"explanation":["「·」를 앞에 붙였어요.","할 일이 하나씩 나뉘어 보여요.","할 일을 보여 줄 때는 기호와 줄 나눔이 좋아요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"},"mis":"K6-2-u5-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#3','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',3,'mc','auto','독자를 고려해 글을 쓴 사람은 어떻게 했을까요?',ARRAY['K6-2-u5-X20','K6-2-u5-X19']::text[],false,'{"seq":3,"concept":"K6-2-u5-C15","difficulty":3,"kind":"mc","stem":"독자를 고려해 글을 쓴 사람은 어떻게 했을까요?","options":[{"t":"전하려는 내용은 그대로 두고 독자가 알아들을 수 있게 썼다","correct":true},{"t":"어려워 보이는 내용은 모두 덜어 냈다","mis":"K6-2-u5-X20"},{"t":"독자가 좋아할 만한 이야기만 골라서 썼다","mis":"K6-2-u5-X20"},{"t":"낱말만 쉽게 바꾸고 차례는 그대로 두었다","mis":"K6-2-u5-X19"}],"explanation":["덜어 내거나 골라 쓰면 비위 맞추기예요.","낱말만 바꾸면 할 일이 여전히 안 보일 수 있어요.","전하려는 것은 두고 닿는 방법을 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#4','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C24',3,'mc','auto','세인이의 첫 글 「우산의 무질서한 적치로 통행에 지장이 초래된다」를 독자를 생각해 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X25','K6-2-u5-X22']::text[],false,'{"seq":4,"concept":"K6-2-u5-C24","difficulty":3,"kind":"mc","stem":"세인이의 첫 글 「우산의 무질서한 적치로 통행에 지장이 초래된다」를 독자를 생각해 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우산을 아무 데나 세워 두면 지나가다 걸려 넘어질 수 있습니다. 접어서 보관대에 꽂아 주세요.","correct":true},{"t":"우산의 무질서한 적치는 심각한 문제이다.","mis":"K6-2-u5-X24"},{"t":"우산 문제가 있다.","mis":"K6-2-u5-X25"},{"t":"우산을 정리하자! 정리하자! 정리하자!","mis":"K6-2-u5-X22"}],"explanation":["어려운 낱말을 그대로 두면 안 돼요.","까닭도 할 일도 없으면 독자가 움직이지 않아요.","까닭과 할 일이 함께 보이게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#5','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C17',3,'mc','auto','세인이가 다시 쓴 글에 「지난 비 오는 날 남은 우산이 여섯 자루」를 넣은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13']::text[],false,'{"seq":5,"concept":"K6-2-u5-C17","difficulty":3,"kind":"mc","stem":"세인이가 다시 쓴 글에 「지난 비 오는 날 남은 우산이 여섯 자루」를 넣은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"현관이 복잡하다는 것을 직접 세어 본 사실로 보여 주려고","correct":true},{"t":"글을 길게 만들려고","mis":"K6-2-u5-X23"},{"t":"숫자를 넣으면 무조건 좋은 글이라서","mis":"K6-2-u5-X13"},{"t":"우산 주인을 찾으려고","mis":"K6-2-u5-X23"}],"explanation":["글에서 말한 현관 문제와 이어진 자료예요.","직접 세어 본 것이라 믿을 수 있어요.","자료는 이해를 돕는 데 써요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#6','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C14',3,'match','auto','독자를 고려할 때 살피는 것과 묻는 말을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C14","difficulty":3,"kind":"match","stem":"독자를 고려할 때 살피는 것과 묻는 말을 이으세요.","pairs":[{"l":"흥미","r":"무엇에 관심이 있는가"},{"l":"배경지식","r":"이 주제를 이미 얼마나 아는가"},{"l":"수준","r":"어떤 낱말을 알아들을 수 있는가"},{"l":"매체","r":"어디에서 이 글을 읽게 되는가"}],"mis":"K6-2-u5-X19","explanation":["흥미는 관심이에요.","배경지식은 이미 아는 것이에요.","수준은 낱말, 매체는 읽는 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#7','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',3,'error','auto','「독자를 고려한 글」에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X19','K6-2-u5-X25']::text[],false,'{"seq":7,"concept":"K6-2-u5-C15","difficulty":3,"kind":"error","stem":"「독자를 고려한 글」에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준혁 — 「일학년이 읽을 글이면 어려운 내용은 다 빼고 재미있는 것만 쓰면 돼.」","correct":true,"mis_target":"K6-2-u5-X20"},{"t":"소이 — 「일학년이 읽을 글이면 같은 내용을 쉬운 낱말과 그림으로 풀어 써야 해.」","mis":"K6-2-u5-X19"},{"t":"하람 — 「일학년이 할 수 있는 일까지 보이게 써야 해.」","mis":"K6-2-u5-X25"}],"explanation":["소이와 하람은 전하려는 것을 두고 닿는 방법을 바꿨어요.","준혁은 내용을 덜어 냈어요.","독자 고려는 비위 맞추기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#8','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C16',4,'mc','auto','세인이의 두 글을 견주어 고쳐 쓰기를 평가한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X20','K6-2-u5-X21']::text[],false,'{"seq":8,"concept":"K6-2-u5-C16","difficulty":4,"kind":"mc","stem":"세인이의 두 글을 견주어 고쳐 쓰기를 평가한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전하려는 우산 문제는 그대로 두고, 쉬운 낱말 · 할 일 · 세어 본 자료로 독자에게 닿게 고쳤다","correct":true},{"t":"글이 길어졌으니 잘못 고쳤다","mis":"K6-2-u5-X22"},{"t":"어려운 낱말을 빼서 내용이 줄어들었다","mis":"K6-2-u5-X20"},{"t":"제목만 바꾸었으니 달라진 것이 없다","mis":"K6-2-u5-X21"}],"explanation":["길이는 기준이 아니에요.","내용은 줄지 않고 그대로예요.","독자에게 닿게 고친 것이 핵심이에요."],"asset":{"type":"passage","lines":["비 오는 날, 우산은 어디에 둘까","비가 오는 날 현관이 복잡합니다. 우산을 아무 데나 세워 두면","물이 고여 미끄럽고, 지나가다 걸려 넘어질 수도 있습니다.","이렇게 해 주세요 · 우산은 접어서 보관대에 꽂아 주세요.","· 보관대가 다 찼으면 현관 왼쪽 벽에 나란히 세워 주세요.","· 집에 갈 때 내 우산인지 확인하고 가져가세요.","우리 반에서 세어 보니 지난 비 오는 날 남은 우산이 여섯 자루였습니다."],"title":"세인이가 독자를 생각하며 다시 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#9','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C14',4,'essay','teacher','세인이의 첫 글과 다시 쓴 글을 견주어, 독자를 고려해 달라진 점을 세 가지 쓰고 각각 독자에게 어떤 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C14","difficulty":4,"kind":"essay","stem":"세인이의 첫 글과 다시 쓴 글을 견주어, 독자를 고려해 달라진 점을 세 가지 쓰고 각각 독자에게 어떤 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 「적치 · 초래」 같은 어려운 낱말을 「아무 데나 세워 두면」처럼 쉬운 말로 바꾸어 같은 반 친구가 알아들을 수 있다. 둘째, 할 일을 기호로 나누어 보여 주어 무엇을 하면 되는지 바로 안다. 셋째, 직접 세어 본 우산 수를 넣어 현관이 복잡하다는 것을 믿을 수 있게 했다.","scoring_points":["달라진 점을 세 가지 찾았는가","각각이 독자에게 주는 도움을 썼는가","전하려는 내용은 그대로임을 알고 썼는가"]},"explanation":["낱말 · 할 일 · 자료를 봐요.","독자에게 무엇이 좋아졌는지 써요.","내용은 줄지 않았어요."],"asset":{"type":"passage","lines":["우산 보관 실태와 개선 방안","본교 현관의 우산 보관 시설은 수용 능력이 부족한 실정이다.","강우 시 우산의 무질서한 적치로 인해 통행에 지장이 초래되며,","이는 낙상의 위험을 증대시킨다.","이에 보관 방식의 전면적 재검토가 요구된다."],"title":"세인이가 처음 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L07_challenge#10','kor',6,2,'u5','L07','g6_2_kor_u5_L07_challenge','lesson_challenge','K6-2-u5-C15',4,'essay','teacher','「독자를 고려하는 것은 비위를 맞추는 것이 아니다.」라는 말을 설명하고, 일학년 동생들에게 「복도에서 뛰지 않기」를 알리는 글을 쓸 때 어떻게 하면 좋을지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C15","difficulty":4,"kind":"essay","stem":"「독자를 고려하는 것은 비위를 맞추는 것이 아니다.」라는 말을 설명하고, 일학년 동생들에게 「복도에서 뛰지 않기」를 알리는 글을 쓸 때 어떻게 하면 좋을지 두 가지 쓰세요.","answer_guide":{"answer":"예: 독자를 고려한다는 것은 독자가 좋아할 것만 고르거나 어려운 이야기를 빼는 것이 아니라, 전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이다. 첫째, 「충돌」 대신 「부딪쳐 다칠 수 있어요」처럼 동생들이 아는 말로 까닭을 쓴다. 둘째, 「복도에서는 오른쪽으로 천천히 걸어요」처럼 할 일을 그림과 함께 보여 준다.","scoring_points":["비위 맞추기와 다른 점을 설명했는가","독자 수준에 맞춘 방법을 썼는가","전하려는 내용을 줄이지 않고 할 일이 보이게 했는가"]},"explanation":["전하려는 것은 그대로.","알아듣게, 할 일이 보이게.","덜어 내기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#1','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C18',1,'mc','auto','기사문은 어떤 글인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X28']::text[],false,'{"seq":1,"concept":"K6-2-u5-C18","difficulty":1,"kind":"mc","stem":"기사문은 어떤 글인가요?","options":[{"t":"어떤 사실이나 사건을 여러 사람에게 알리는 글","correct":true},{"t":"글쓴이의 느낌을 솔직하게 쓰는 글","mis":"K6-2-u5-X26"},{"t":"있을 법한 일을 꾸며 쓰는 글","mis":"K6-2-u5-X27"},{"t":"한 사람에게 마음을 전하는 글","mis":"K6-2-u5-X28"}],"explanation":["느낌을 쓰는 글은 기사문이 아니에요.","꾸며 쓰면 안 돼요.","사실을 여러 사람에게 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#2','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',1,'mc','auto','기사의 주요 내용을 앞에서 요약해 주는 부분은 어느 것인가요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":2,"concept":"K6-2-u5-C19","difficulty":1,"kind":"mc","stem":"기사의 주요 내용을 앞에서 요약해 주는 부분은 어느 것인가요?","options":[{"t":"전문","correct":true},{"t":"표제","mis":"K6-2-u5-X28"},{"t":"부제","mis":"K6-2-u5-X28"},{"t":"본문","mis":"K6-2-u5-X28"}],"explanation":["표제는 제목이에요.","부제는 표제를 보충해요.","전문이 주요 내용을 요약해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#3','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',1,'sa','auto','기사문의 제목에서 표제에 덧붙어 표제를 보충하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u5-C19","difficulty":1,"kind":"sa","stem":"기사문의 제목에서 표제에 덧붙어 표제를 보충하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["부제"],"explanation":["표제는 기사의 제목이에요.","부제는 필요할 때만 붙여요.","표제와 부제를 이어 읽으면 무슨 일인지 짐작돼요."],"mis":"K6-2-u5-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#4','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',1,'ox','auto','기사문에는 확인하지 못한 소문도 써도 돼요.',ARRAY['K6-2-u5-X27']::text[],false,'{"seq":4,"concept":"K6-2-u5-C20","difficulty":1,"kind":"ox","stem":"기사문에는 확인하지 못한 소문도 써도 돼요.","answer":"X","reason_options":[{"t":"읽는 사람이 사실이라고 믿고 읽는 글이기 때문에","correct":true},{"t":"많이 알릴수록 좋은 기사문이기 때문에","mis":"K6-2-u5-X27"}],"mis":"K6-2-u5-X27","explanation":["기사문은 사실이라고 믿고 읽어요.","확인하지 못한 것은 쓰지 않아요.","보고 듣고 세어 본 것만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#5','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',2,'match','auto','기사문의 부분과 하는 일을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C19","difficulty":2,"kind":"match","stem":"기사문의 부분과 하는 일을 이으세요.","pairs":[{"l":"표제","r":"기사 내용을 간결하게 드러냅니다"},{"l":"전문","r":"주요 내용을 앞에서 요약해 줍니다"},{"l":"본문","r":"주된 내용을 자세히 담습니다"}],"mis":"K6-2-u5-X28","explanation":["표제는 먼저 읽게 되는 제목이에요.","전문만 읽어도 무슨 일인지 알아요.","본문이 가장 길고 자세해요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#6','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C19',2,'mc','auto','본보기 기사문의 전문에서 「누가」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":6,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"본보기 기사문의 전문에서 「누가」에 해당하는 것은 어느 것인가요?","options":[{"t":"육학년 도서 도우미 여덟 명","correct":true},{"t":"우리 학교 도서관","mis":"K6-2-u5-X29"},{"t":"이번 달부터","mis":"K6-2-u5-X29"},{"t":"요일별로 당번을 나누어","mis":"K6-2-u5-X29"}],"explanation":["「도서관」은 어디에서예요.","「이번 달부터」는 언제예요.","「당번을 나누어」는 어떻게예요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#7','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',2,'mc','auto','본보기 기사문에서 기자단이 직접 확인한 사실은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":7,"concept":"K6-2-u5-C20","difficulty":2,"kind":"mc","stem":"본보기 기사문에서 기자단이 직접 확인한 사실은 어느 것인가요?","options":[{"t":"문을 연 첫 사흘 동안 온 사람 수","correct":true},{"t":"학생들이 모두 기뻐했다는 것","mis":"K6-2-u5-X26"},{"t":"다른 학교도 곧 따라 할 것이라는 이야기","mis":"K6-2-u5-X27"},{"t":"도서관이 학교에서 가장 큰 변화라는 것","mis":"K6-2-u5-X26"}],"explanation":["기쁨과 가장 큰 변화는 생각이에요.","다른 학교 이야기는 확인하지 못했어요.","사람 수는 직접 세어 본 사실이에요."],"asset":{"type":"passage","lines":["[본문] 그동안 도서관은 아침 시간과 방과 후에만 열려 있었다.","지난주 도서 도우미들이 모여 날마다 두 명씩 맡기로 당번을 정했다.","기자단이 문을 연 첫 사흘 동안 온 사람 수를 세어 보았다.","첫날은 열두 명, 둘째 날은 열아홉 명, 셋째 날은 스물여섯 명이었다.","하언 학생은 「쉬는 시간이 짧아 못 오던 친구들이 많이 온다」라고 말했다.","도우미들은 다음 달부터 새 책 알림 게시판도 만들 계획이라고 밝혔다."],"title":"본보기 기사문 (본문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#8','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C21',2,'mc','auto','우리 학교 신문에 실을 기삿거리로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X30','K6-2-u5-X27']::text[],false,'{"seq":8,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"우리 학교 신문에 실을 기삿거리로 알맞은 것은 어느 것인가요?","options":[{"t":"이번 학기부터 달라진 급식실 줄 서기 방법","correct":true},{"t":"먼 나라에서 일어났다는 확인하지 못한 이야기","mis":"K6-2-u5-X30"},{"t":"내가 어제 꾼 꿈과 그때 든 생각","mis":"K6-2-u5-X30"},{"t":"누구도 가서 볼 수 없는 소문","mis":"K6-2-u5-X27"}],"explanation":["독자인 우리 학교 학생이 관심을 가질 일이에요.","내가 직접 가서 확인할 수 있어요.","그래서 알맞은 기삿거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#9','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C21',2,'ox','auto','기사문에 사진이나 표를 넣을 때에는 출처를 밝혀야 해요.',ARRAY['K6-2-u5-X32']::text[],false,'{"seq":9,"concept":"K6-2-u5-C21","difficulty":2,"kind":"ox","stem":"기사문에 사진이나 표를 넣을 때에는 출처를 밝혀야 해요.","answer":"O","reason_options":[{"t":"어디에서 얻은 자료인지 알아야 읽는 사람이 믿을 수 있기 때문에","correct":true},{"t":"자료는 많을수록 좋은 기사문이 되기 때문에","mis":"K6-2-u5-X32"}],"mis":"K6-2-u5-X32","explanation":["자료는 이해를 높여 줘요.","출처가 있어야 믿을 수 있어요.","내가 조사했으면 언제 누구에게 어떻게 했는지 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_basic#10','kor',6,2,'u5','L09','g6_2_kor_u5_L09_basic','lesson_basic','K6-2-u5-C20',3,'error','auto','기사문 문장을 썼어요. 확인할 수 없는 생각을 사실처럼 쓴 친구는 누구인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":10,"concept":"K6-2-u5-C20","difficulty":3,"kind":"error","stem":"기사문 문장을 썼어요. 확인할 수 없는 생각을 사실처럼 쓴 친구는 누구인가요?","options":[{"t":"지율 — 「점심시간 도서관이 열리자 학생들은 모두 기뻐했다.」","correct":true,"mis_target":"K6-2-u5-X26"},{"t":"로아 — 「첫날 점심시간에 도서관에 온 사람은 열두 명이었다.」","mis":"K6-2-u5-X27"},{"t":"민재 — 「한 학생은 ‘점심때 많이 온다’라고 말했다.」","mis":"K6-2-u5-X27"}],"explanation":["로아는 세어 본 수를 썼어요.","민재는 들은 말을 그대로 옮겼어요.","「모두 기뻐했다」는 쓴 사람의 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#1','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',2,'mc','auto','본보기 기사문의 전문에서 「왜」에 해당하는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":1,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"본보기 기사문의 전문에서 「왜」에 해당하는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"점심시간에도 책을 빌릴 수 있게 하려고","correct":true},{"t":"요일별로 당번을 나누어","mis":"K6-2-u5-X29"},{"t":"이번 달부터","mis":"K6-2-u5-X29"},{"t":"도서 도우미 여덟 명이","mis":"K6-2-u5-X29"}],"explanation":["「당번을 나누어」는 어떻게예요.","「이번 달부터」는 언제예요.","「도우미 여덟 명이」는 누가예요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#2','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',2,'ox','auto','부제는 모든 기사문에 꼭 붙여야 해요.',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":2,"concept":"K6-2-u5-C19","difficulty":2,"kind":"ox","stem":"부제는 모든 기사문에 꼭 붙여야 해요.","answer":"X","reason_options":[{"t":"표제를 보충할 필요가 있을 때만 붙이기 때문에","correct":true},{"t":"표제만으로는 기사가 될 수 없기 때문에","mis":"K6-2-u5-X28"}],"mis":"K6-2-u5-X28","explanation":["부제는 표제를 보충해요.","필요할 때만 붙여요.","표제만 있는 기사문도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#3','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',3,'mc','auto','본보기 기사문의 제목으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31']::text[],false,'{"seq":3,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"본보기 기사문의 제목으로 알맞은 것은 어느 것인가요?","options":[{"t":"점심시간 도서관, 이제 문이 열립니다","correct":true},{"t":"온 학교가 뒤집혔다, 역사에 남을 대사건","mis":"K6-2-u5-X31"},{"t":"어떤 곳에서 어떤 일이 있었다","mis":"K6-2-u5-X31"},{"t":"도서관 도우미들이 학교를 구했다","mis":"K6-2-u5-X31"}],"explanation":["부풀린 제목은 본문에 없는 말이에요.","아무 내용도 없는 제목은 기사를 드러내지 못해요.","내용을 담되 부풀리지 않아요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#4','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C20',3,'mc','auto','「이 일은 우리 학교에서 가장 큰 변화다.」를 기사문에 쓰고 싶어요. 어떻게 고쳐야 하나요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X31']::text[],false,'{"seq":4,"concept":"K6-2-u5-C20","difficulty":3,"kind":"mc","stem":"「이 일은 우리 학교에서 가장 큰 변화다.」를 기사문에 쓰고 싶어요. 어떻게 고쳐야 하나요?","options":[{"t":"누구의 생각인지 밝혀 「한 학생은 ‘가장 큰 변화’라고 말했다」처럼 쓴다","correct":true},{"t":"그대로 쓴다. 기자가 그렇게 느꼈으니 사실이다","mis":"K6-2-u5-X26"},{"t":"「모든 학생이 가장 큰 변화라고 생각한다」로 바꾼다","mis":"K6-2-u5-X27"},{"t":"느낌표를 붙여 더 크게 쓴다","mis":"K6-2-u5-X31"}],"explanation":["「가장 큰 변화」는 생각이에요.","모든 학생에게 물어본 것도 아니에요.","생각을 쓰려면 누구의 생각인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#5','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',3,'match','auto','육하원칙과 본보기 기사문의 내용을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C19","difficulty":3,"kind":"match","stem":"육하원칙과 본보기 기사문의 내용을 이으세요.","pairs":[{"l":"누가","r":"도서 도우미 여덟 명이"},{"l":"언제","r":"이번 달부터"},{"l":"어디에서","r":"학교 도서관에서"},{"l":"어떻게","r":"요일별로 당번을 나누어"}],"mis":"K6-2-u5-X29","explanation":["사람은 누가예요.","때는 언제, 곳은 어디에서예요.","방법은 어떻게예요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#6','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C18',3,'mc','auto','기사문의 표현으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":6,"concept":"K6-2-u5-C18","difficulty":3,"kind":"mc","stem":"기사문의 표현으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「셋째 날은 스물여섯 명이 왔다.」","correct":true},{"t":"「셋째 날은 정말 엄청나게 많이 와서 깜짝 놀랐다!」","mis":"K6-2-u5-X26"},{"t":"「셋째 날은 아마 백 명쯤 왔을 것이다.」","mis":"K6-2-u5-X27"},{"t":"「셋째 날은 사람들이 바글바글, 북적북적!」","mis":"K6-2-u5-X26"}],"explanation":["놀람과 꾸밈은 객관적이지 않아요.","「아마 백 명쯤」은 지어낸 수예요.","세어 본 수를 간결하게 써요."],"asset":{"type":"passage","lines":["[본문] 그동안 도서관은 아침 시간과 방과 후에만 열려 있었다.","지난주 도서 도우미들이 모여 날마다 두 명씩 맡기로 당번을 정했다.","기자단이 문을 연 첫 사흘 동안 온 사람 수를 세어 보았다.","첫날은 열두 명, 둘째 날은 열아홉 명, 셋째 날은 스물여섯 명이었다.","하언 학생은 「쉬는 시간이 짧아 못 오던 친구들이 많이 온다」라고 말했다.","도우미들은 다음 달부터 새 책 알림 게시판도 만들 계획이라고 밝혔다."],"title":"본보기 기사문 (본문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#7','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C21',3,'error','auto','기사문 계획을 세웠어요. 알맞지 않은 계획은 누구의 것인가요?',ARRAY['K6-2-u5-X32','K6-2-u5-X30','K6-2-u5-X27']::text[],false,'{"seq":7,"concept":"K6-2-u5-C21","difficulty":3,"kind":"error","stem":"기사문 계획을 세웠어요. 알맞지 않은 계획은 누구의 것인가요?","options":[{"t":"서윤 — 「사진은 인터넷에서 아무거나 가져오고 어디서 났는지는 안 적을래.」","correct":true,"mis_target":"K6-2-u5-X32"},{"t":"건우 — 「독자는 우리 학교 학생이니 급식실 줄 서기 방법을 다룰래.」","mis":"K6-2-u5-X30"},{"t":"예린 — 「줄 선 사람 수는 내가 점심시간에 직접 세어 볼래.」","mis":"K6-2-u5-X27"}],"explanation":["건우와 예린은 독자와 확인을 생각했어요.","서윤은 출처를 밝히지 않았어요.","자료의 출처는 반드시 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#8','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C18',4,'mc','auto','본보기 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27','K6-2-u5-X31']::text[],false,'{"seq":8,"concept":"K6-2-u5-C18","difficulty":4,"kind":"mc","stem":"본보기 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세어 본 수와 들은 말, 물어 확인한 계획만 썼고, 하언 학생의 생각은 누구의 말인지 밝혀 옮겼다","correct":true},{"t":"느낌이 하나도 없어 재미없는 기사문이다","mis":"K6-2-u5-X26"},{"t":"사람 수를 세어 쓴 것은 지나친 일이다","mis":"K6-2-u5-X27"},{"t":"제목에 놀라운 말을 넣지 않아 실패한 기사문이다","mis":"K6-2-u5-X31"}],"explanation":["기사문은 느낌보다 사실이에요.","세어 본 수가 믿음을 줘요.","생각은 누구의 것인지 밝혔어요."],"asset":{"type":"passage","lines":["[본문] 그동안 도서관은 아침 시간과 방과 후에만 열려 있었다.","지난주 도서 도우미들이 모여 날마다 두 명씩 맡기로 당번을 정했다.","기자단이 문을 연 첫 사흘 동안 온 사람 수를 세어 보았다.","첫날은 열두 명, 둘째 날은 열아홉 명, 셋째 날은 스물여섯 명이었다.","하언 학생은 「쉬는 시간이 짧아 못 오던 친구들이 많이 온다」라고 말했다.","도우미들은 다음 달부터 새 책 알림 게시판도 만들 계획이라고 밝혔다."],"title":"본보기 기사문 (본문)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#9','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C19',4,'essay','teacher','본보기 기사문의 전문을 육하원칙에 따라 여섯 가지로 나누어 쓰고, 전문이 기사문에서 하는 일을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C19","difficulty":4,"kind":"essay","stem":"본보기 기사문의 전문을 육하원칙에 따라 여섯 가지로 나누어 쓰고, 전문이 기사문에서 하는 일을 쓰세요.","answer_guide":{"answer":"예: 누가 — 육학년 도서 도우미 여덟 명이. 언제 — 이번 달부터. 어디에서 — 학교 도서관에서. 무엇을 — 점심시간에 문을 여는 일을. 어떻게 — 요일별로 당번을 나누어. 왜 — 점심시간에도 책을 빌릴 수 있게 하려고. 전문은 기사의 주요 내용을 앞에서 요약해 주어 전문만 읽어도 무슨 일인지 알 수 있게 한다.","scoring_points":["육하원칙 여섯 가지를 바르게 나누었는가","각 항목에 맞는 내용을 찾았는가","전문이 하는 일을 썼는가"]},"explanation":["여섯 물음에 하나씩 답해요.","전문은 요약이에요.","본문이 자세히 풀어요."],"asset":{"type":"passage","lines":["[표제] 점심시간 도서관, 이제 문이 열립니다","[부제] ― 도서 도우미 여덟 명이 당번을 나누어 맡아 ―","[전문] 우리 학교 도서관이 이번 달부터 점심시간에도 문을 연다.","육학년 도서 도우미 여덟 명이 요일별로 당번을 나누어 맡기로 하면서","가능해졌다."],"title":"본보기 기사문 (앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L09_challenge#10','kor',6,2,'u5','L09','g6_2_kor_u5_L09_challenge','lesson_challenge','K6-2-u5-C20',4,'essay','teacher','기사문에 들어갈 수 있는 것과 들어갈 수 없는 것을 두 가지씩 쓰고, 그렇게 가른 까닭을 쓰세요. 그리고 쓴 사람의 생각을 기사문에 넣고 싶을 때 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C20","difficulty":4,"kind":"essay","stem":"기사문에 들어갈 수 있는 것과 들어갈 수 없는 것을 두 가지씩 쓰고, 그렇게 가른 까닭을 쓰세요. 그리고 쓴 사람의 생각을 기사문에 넣고 싶을 때 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 들어갈 수 있는 것 — 직접 세어 본 사람 수, 직접 들은 사람의 말. 들어갈 수 없는 것 — 확인하지 못한 소문, 그럴 것 같아서 지어낸 숫자. 까닭 — 기사문은 읽는 사람이 사실이라고 믿고 읽는 글이라 누구든 다시 확인할 수 있는 것만 써야 한다. 생각을 넣고 싶으면 「한 학생은 ~라고 말했다」처럼 누구의 생각인지 밝혀 쓴다.","scoring_points":["들어갈 수 있는 것을 두 가지 썼는가","들어갈 수 없는 것을 두 가지 썼는가","까닭과 생각을 넣는 방법을 썼는가"]},"explanation":["확인한 것만.","지어내지 않아요.","생각은 누구의 것인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#1','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',1,'mc','auto','편지의 짜임에서 편지를 쓴 목적이 담기는 부분은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":1,"concept":"K6-2-u5-C22","difficulty":1,"kind":"mc","stem":"편지의 짜임에서 편지를 쓴 목적이 담기는 부분은 어느 것인가요?","options":[{"t":"하고 싶은 말","correct":true},{"t":"첫인사","mis":"K6-2-u5-X33"},{"t":"끝인사","mis":"K6-2-u5-X33"},{"t":"쓴 날짜와 보내는 사람","mis":"K6-2-u5-X33"}],"explanation":["첫인사는 안부를 물어요.","끝인사는 마무리 인사예요.","목적은 하고 싶은 말에 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#2','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',1,'ox','auto','편지의 독자는 받는 사람 한 사람이에요.',ARRAY['K6-2-u5-X34']::text[],false,'{"seq":2,"concept":"K6-2-u5-C22","difficulty":1,"kind":"ox","stem":"편지의 독자는 받는 사람 한 사람이에요.","answer":"O","reason_options":[{"t":"편지는 받는 사람을 또렷하게 떠올리며 쓰는 글이기 때문에","correct":true},{"t":"편지는 누구나 읽어도 되는 글이기 때문에","mis":"K6-2-u5-X34"}],"mis":"K6-2-u5-X34","explanation":["편지는 한 사람에게 보내요.","그래서 그 사람에게 알맞은 말을 골라요.","독자를 가장 또렷하게 떠올리는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#3','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',1,'mc','auto','「붉다」는 어떻게 소리 나나요?',ARRAY['K6-2-u5-X39','K6-2-u5-X38']::text[],false,'{"seq":3,"concept":"K6-2-u5-C25","difficulty":1,"kind":"mc","stem":"「붉다」는 어떻게 소리 나나요?","options":[{"t":"[북따]","correct":true},{"t":"[불따]","mis":"K6-2-u5-X39"},{"t":"[붉따]","mis":"K6-2-u5-X38"},{"t":"[부르따]","mis":"K6-2-u5-X39"}],"explanation":["뒤에 자음자가 오면 하나만 소리 나요.","붉다는 ㄱ 소리가 나요.","그래서 [북따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#4','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',1,'mc','auto','고마운 마음을 전하는 편지에 쓰면 좋은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35']::text[],false,'{"seq":4,"concept":"K6-2-u5-C23","difficulty":1,"kind":"mc","stem":"고마운 마음을 전하는 편지에 쓰면 좋은 것은 어느 것인가요?","options":[{"t":"무엇이 고마웠는지 그 일을 콕 집어 쓴다","correct":true},{"t":"「고마워」 한 마디만 쓴다","mis":"K6-2-u5-X36"},{"t":"다음에는 이렇게 하라고 충고를 쓴다","mis":"K6-2-u5-X35"},{"t":"내 변명을 먼저 길게 쓴다","mis":"K6-2-u5-X35"}],"explanation":["막연하면 마음이 잘 닿지 않아요.","충고와 변명은 이 마음에 맞지 않아요.","고마운 일을 콕 집어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#5','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',2,'match','auto','편지의 부분과 하는 일을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C22","difficulty":2,"kind":"match","stem":"편지의 부분과 하는 일을 이으세요.","pairs":[{"l":"첫인사","r":"안부를 물으며 말문을 엽니다"},{"l":"하고 싶은 말","r":"편지를 쓴 목적을 담습니다"},{"l":"쓴 날짜와 보내는 사람","r":"언제 누가 썼는지 알려 줍니다"}],"mis":"K6-2-u5-X33","explanation":["첫인사로 말문을 열어요.","하고 싶은 말에 목적을 담아요.","끝에 날짜와 이름을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#6','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',2,'mc','auto','오래 준비한 발표를 잘 마친 친구에게 쓸 편지로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35']::text[],false,'{"seq":6,"concept":"K6-2-u5-C23","difficulty":2,"kind":"mc","stem":"오래 준비한 발표를 잘 마친 친구에게 쓸 편지로 알맞은 것은 어느 것인가요?","options":[{"t":"쉬는 시간마다 연습하던 걸 봤어. 정말 축하해","correct":true},{"t":"잘했네. 그럼 이만 줄일게","mis":"K6-2-u5-X36"},{"t":"다음에는 목소리를 더 크게 내는 게 좋을 것 같아","mis":"K6-2-u5-X35"},{"t":"나도 발표 잘하는데 다음엔 나랑 같이 하자","mis":"K6-2-u5-X35"}],"explanation":["막연한 칭찬은 잘 닿지 않아요.","축하할 때 충고는 마음에 맞지 않아요.","애쓴 과정을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#7','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C22',2,'mc','auto','시율이의 편지에서 첫인사에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":7,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"시율이의 편지에서 첫인사에 해당하는 것은 어느 것인가요?","options":[{"t":"요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","correct":true},{"t":"네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","mis":"K6-2-u5-X33"},{"t":"고마웠어. 내일 학교에서 보자.","mis":"K6-2-u5-X33"},{"t":"○○월 ○○일 시율이가","mis":"K6-2-u5-X33"}],"explanation":["고마웠던 일은 하고 싶은 말이에요.","「내일 보자」는 끝인사예요.","안부를 묻는 말이 첫인사예요."],"asset":{"type":"passage","lines":["도아에게","도아야, 요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","지난주에 내가 발표 자료를 잃어버려서 쩔쩔맬 때 네가 같이 찾아 줬잖아.","네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","다음에 네가 무언가를 잃어버리면 내가 꼭 같이 찾아 줄게.","이번 주 도서관 당번도 나랑 바꾸고 싶으면 말해 줘.","고마웠어. 내일 학교에서 보자.","○○월 ○○일 시율이가"],"title":"시율이가 도아에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#8','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C24',2,'mc','auto','편지를 전할 매체를 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10','K6-2-u5-X37']::text[],false,'{"seq":8,"concept":"K6-2-u5-C24","difficulty":2,"kind":"mc","stem":"편지를 전할 매체를 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"전하려는 마음과 받는 사람의 처지에 맞는 것을 고른다","correct":true},{"t":"영상으로 만들면 마음이 언제나 더 잘 전해진다","mis":"K6-2-u5-X03"},{"t":"가장 빨리 만들 수 있는 것을 고르면 된다","mis":"K6-2-u5-X10"},{"t":"가장 화려하게 꾸밀 수 있는 것을 고른다","mis":"K6-2-u5-X37"}],"explanation":["매체에는 등수가 없어요.","빠르기나 꾸밈이 기준은 아니에요.","마음과 받는 사람을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#9','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C25',2,'ox','auto','「얇아요」는 [얄바요]로 소리 나요.',ARRAY['K6-2-u5-X38']::text[],false,'{"seq":9,"concept":"K6-2-u5-C25","difficulty":2,"kind":"ox","stem":"「얇아요」는 [얄바요]로 소리 나요.","answer":"O","reason_options":[{"t":"뒤에 모음이 오면 겹받침의 두 소리가 다 나고 뒤엣것이 뒷글자로 넘어가기 때문에","correct":true},{"t":"겹받침은 언제나 앞의 것 하나만 소리 나기 때문에","mis":"K6-2-u5-X38"}],"mis":"K6-2-u5-X38","explanation":["얇다는 [얄따]로 하나만 소리 나요.","얇아요는 뒤에 모음이 와요.","ㅂ이 뒷글자로 넘어가 [얄바요]가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_basic#10','kor',6,2,'u5','L12','g6_2_kor_u5_L12_basic','lesson_basic','K6-2-u5-C23',3,'error','auto','마음에 맞는 편지 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X35']::text[],false,'{"seq":10,"concept":"K6-2-u5-C23","difficulty":3,"kind":"error","stem":"마음에 맞는 편지 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하엘 — 「미안한 마음을 전할 땐 내가 왜 그럴 수밖에 없었는지 변명부터 길게 써야 해.」","correct":true,"mis_target":"K6-2-u5-X35"},{"t":"규리 — 「힘을 내라는 마음은 섣부른 충고보다 곁에 있다는 말로 전해.」","mis":"K6-2-u5-X35"},{"t":"시안 — 「축하할 땐 그 친구가 애쓴 과정을 함께 써.」","mis":"K6-2-u5-X35"}],"explanation":["규리와 시안은 마음에 맞는 내용을 말했어요.","미안할 땐 무엇이 잘못이었는지 먼저 써요.","변명이 앞서면 사과가 닿지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#1','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',2,'sa','auto','「짧다」는 어떻게 소리 나나요? 대괄호 없이 소리 나는 대로 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C25","difficulty":2,"kind":"sa","stem":"「짧다」는 어떻게 소리 나나요? 대괄호 없이 소리 나는 대로 두 글자로 쓰세요.","answer":["짤따"],"explanation":["뒤에 자음자가 오면 하나만 소리 나요.","짧다는 ㄹ 소리가 나요.","그래서 [짤따]예요."],"mis":"K6-2-u5-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#2','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',2,'mc','auto','겹받침 뒤에 모음이 올 때 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-2-u5-X38','K6-2-u5-X39']::text[],false,'{"seq":2,"concept":"K6-2-u5-C25","difficulty":2,"kind":"mc","stem":"겹받침 뒤에 모음이 올 때 바르게 읽은 것은 어느 것인가요?","options":[{"t":"늙어요 → [늘거요]","correct":true},{"t":"늙어요 → [늑어요]","mis":"K6-2-u5-X38"},{"t":"늙어요 → [늘어요]","mis":"K6-2-u5-X39"},{"t":"늙어요 → [느거요]","mis":"K6-2-u5-X39"}],"explanation":["늙다는 [늑따]로 하나만 소리 나요.","뒤에 모음이 오면 두 소리가 다 나요.","ㄱ이 뒷글자로 넘어가 [늘거요]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#3','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C24',3,'mc','auto','편지를 쓴 뒤 하면 좋은 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X37']::text[],false,'{"seq":3,"concept":"K6-2-u5-C24","difficulty":3,"kind":"mc","stem":"편지를 쓴 뒤 하면 좋은 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실제로 건네고 받는 사람이 어떤 부분이 마음에 남았는지 들어 본다","correct":true},{"t":"숙제로 냈으니 다시 생각하지 않는다","mis":"K6-2-u5-X37"},{"t":"편지지를 더 예쁘게 꾸미는 데 시간을 쓴다","mis":"K6-2-u5-X37"},{"t":"받는 사람이 고칠 점을 말하면 다시는 쓰지 않는다","mis":"K6-2-u5-X37"}],"explanation":["편지는 건네고 나서 완성돼요.","꾸밈에 시간을 다 쓰지 않아요.","반응을 듣고 다음에 또 쓸 일을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#4','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',3,'mc','auto','시율이의 편지에서 독자를 고려한 곳이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X33','K6-2-u5-X34']::text[],false,'{"seq":4,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"시율이의 편지에서 독자를 고려한 곳이 아닌 것은 어느 것인가요?","options":[{"t":"편지의 글자 수를 정확히 맞추었다","correct":true},{"t":"둘이 함께 겪은 일을 콕 집어 적었다","mis":"K6-2-u5-X36"},{"t":"받는 사람의 안부를 먼저 물었다","mis":"K6-2-u5-X33"},{"t":"받는 사람이 고를 수 있게 당번을 바꾸자고 제안했다","mis":"K6-2-u5-X34"}],"explanation":["함께 겪은 일 · 안부 · 제안은 도아를 떠올린 흔적이에요.","글자 수는 독자와 상관없어요.","받는 사람을 떠올리며 쓴 곳을 찾아요."],"asset":{"type":"passage","lines":["도아에게","도아야, 요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","지난주에 내가 발표 자료를 잃어버려서 쩔쩔맬 때 네가 같이 찾아 줬잖아.","네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","다음에 네가 무언가를 잃어버리면 내가 꼭 같이 찾아 줄게.","이번 주 도서관 당번도 나랑 바꾸고 싶으면 말해 줘.","고마웠어. 내일 학교에서 보자.","○○월 ○○일 시율이가"],"title":"시율이가 도아에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#5','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C23',3,'match','auto','전하려는 마음과 쓰면 좋은 내용을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u5-C23","difficulty":3,"kind":"match","stem":"전하려는 마음과 쓰면 좋은 내용을 이으세요.","pairs":[{"l":"고마운 마음","r":"무엇이 고마웠는지 그 일을 콕 집어"},{"l":"미안한 마음","r":"무엇이 잘못이었는지 먼저"},{"l":"축하하는 마음","r":"그 사람이 애쓴 과정을 함께"},{"l":"힘을 내라는 마음","r":"곁에 있다는 말을"}],"mis":"K6-2-u5-X35","explanation":["고마움은 콕 집어요.","사과는 잘못부터, 축하는 과정과 함께예요.","위로는 충고보다 곁에 있다는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#6','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C24',3,'error','auto','편지 매체를 골랐어요. 까닭이 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":6,"concept":"K6-2-u5-C24","difficulty":3,"kind":"error","stem":"편지 매체를 골랐어요. 까닭이 알맞지 않은 친구는 누구인가요?","options":[{"t":"태린 — 「영상 편지가 손 편지보다 언제나 더 좋은 거니까 영상으로 할래.」","correct":true,"mis_target":"K6-2-u5-X03"},{"t":"유나 — 「할머니가 오래 간직하시게 손 편지로 쓸래.」","mis":"K6-2-u5-X10"},{"t":"민결 — 「멀리 있는 사촌에게 목소리와 표정을 보여 주려고 영상으로 할래.」","mis":"K6-2-u5-X10"}],"explanation":["유나와 민결은 마음과 받는 사람을 보고 골랐어요.","태린은 매체에 등수를 매겼어요.","매체에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#7','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',3,'mc','auto','할머니께 편지를 쓸 때 알맞은 첫 문장은 어느 것인가요?',ARRAY['K6-2-u5-X34','K6-2-u5-X36']::text[],false,'{"seq":7,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"할머니께 편지를 쓸 때 알맞은 첫 문장은 어느 것인가요?","options":[{"t":"할머니, 그동안 건강하게 잘 지내셨어요?","correct":true},{"t":"할머니, 잘 지냈어?","mis":"K6-2-u5-X34"},{"t":"안녕! 오랜만이야.","mis":"K6-2-u5-X34"},{"t":"그거 고마웠어.","mis":"K6-2-u5-X36"}],"explanation":["받는 사람은 웃어른이에요.","알맞은 높임말을 써요.","안부를 여쭈며 말문을 열어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#8','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C23',4,'mc','auto','시율이의 편지를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X33','K6-2-u5-X22']::text[],false,'{"seq":8,"concept":"K6-2-u5-C23","difficulty":4,"kind":"mc","stem":"시율이의 편지를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"함께 찾아 준 일과 「천천히 다시 찾아보자」라는 말을 콕 집어 고마운 까닭을 밝혀, 막연한 고마움보다 마음이 잘 닿는다","correct":true},{"t":"「고마웠어」를 여러 번 쓰지 않아서 고마움이 약하다","mis":"K6-2-u5-X36"},{"t":"당번을 바꾸자는 말은 편지와 상관없어 빼야 한다","mis":"K6-2-u5-X33"},{"t":"편지가 짧아서 마음이 잘 닿지 않는다","mis":"K6-2-u5-X22"}],"explanation":["고마움의 크기는 낱말의 개수가 아니에요.","제안은 받는 사람을 생각한 말이에요.","콕 집어 쓴 것이 마음을 전해요."],"asset":{"type":"passage","lines":["도아에게","도아야, 요즘 아침 공기가 제법 서늘하지. 감기 걸리지 않게 잘 지내지?","지난주에 내가 발표 자료를 잃어버려서 쩔쩔맬 때 네가 같이 찾아 줬잖아.","네가 「천천히 다시 찾아보자」라고 말해 준 게 제일 고마웠어.","다음에 네가 무언가를 잃어버리면 내가 꼭 같이 찾아 줄게.","이번 주 도서관 당번도 나랑 바꾸고 싶으면 말해 줘.","고마웠어. 내일 학교에서 보자.","○○월 ○○일 시율이가"],"title":"시율이가 도아에게 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#9','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C22',4,'essay','teacher','마음을 전하고 싶은 사람을 한 명 정해, 편지의 다섯 부분을 모두 갖춘 짧은 편지를 쓰세요. 받는 사람에게 알맞은 말을 쓰고, 전하려는 마음에 맞는 내용을 콕 집어 쓰세요. 날짜는 ○○월 ○○일로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C22","difficulty":4,"kind":"essay","stem":"마음을 전하고 싶은 사람을 한 명 정해, 편지의 다섯 부분을 모두 갖춘 짧은 편지를 쓰세요. 받는 사람에게 알맞은 말을 쓰고, 전하려는 마음에 맞는 내용을 콕 집어 쓰세요. 날짜는 ○○월 ○○일로 쓰세요.","answer_guide":{"answer":"예: 선생님께 / 선생님, 요즘 아침저녁으로 쌀쌀한데 감기 걸리지 않으셨어요? / 지난번 줄넘기 시험 날 제가 자꾸 걸려서 울상이었을 때, 선생님께서 「박자를 소리 내어 세어 봐」라고 알려 주셔서 끝까지 넘을 수 있었어요. 그 한마디가 정말 고마웠어요. / 늘 건강하세요. / ○○월 ○○일 제자 ○○ 올림","scoring_points":["다섯 부분을 모두 갖추었는가","받는 사람에게 알맞은 높임말을 썼는가","전하려는 마음에 맞는 내용을 콕 집어 썼는가"]},"explanation":["받는 사람 · 첫인사 · 하고 싶은 말 · 끝인사 · 날짜와 이름.","받는 사람에게 맞는 말.","그 일을 콕 집어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_L12_challenge#10','kor',6,2,'u5','L12','g6_2_kor_u5_L12_challenge','lesson_challenge','K6-2-u5-C25',4,'essay','teacher','겹받침이 있는 낱말이 소리 나는 두 가지 규칙을 쓰고, 「붉다 · 붉어요」와 「짧다 · 짧아요」가 어떻게 소리 나는지 규칙과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C25","difficulty":4,"kind":"essay","stem":"겹받침이 있는 낱말이 소리 나는 두 가지 규칙을 쓰고, 「붉다 · 붉어요」와 「짧다 · 짧아요」가 어떻게 소리 나는지 규칙과 이어 쓰세요.","answer_guide":{"answer":"예: 겹받침 뒤에 자음자가 오거나 낱말이 끝나면 하나만 소리 나고, 뒤에 모음이 오면 두 소리가 다 나며 뒤엣것이 뒷글자로 넘어간다. 붉다는 뒤에 자음자가 와서 [북따], 붉어요는 뒤에 모음이 와서 ㄱ이 넘어가 [불거요]로 소리 난다. 짧다는 [짤따], 짧아요는 ㅂ이 넘어가 [짤바요]로 소리 난다.","scoring_points":["두 가지 규칙을 바르게 썼는가","붉다 · 붉어요의 소리를 규칙과 이었는가","짧다 · 짧아요의 소리를 규칙과 이었는가"]},"explanation":["자음자 앞에서는 하나.","모음 앞에서는 둘.","뒤엣것이 뒷글자로 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#1','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C1',1,'mc','auto','「문자 언어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"「문자 언어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글자로 나타내는 말","correct":true},{"t":"음성으로 나타내는 말","mis":"K6-2-u5-X01"},{"t":"소리와 음악으로 나타내는 것","mis":"K6-2-u5-X04"},{"t":"표정과 몸짓으로 나타내는 것","mis":"K6-2-u5-X01"}],"explanation":["음성으로 나타내는 말은 음성 언어예요.","소리와 음악은 함께 쓰는 요소예요.","글자로 나타내는 말이 문자 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#2','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C2',1,'ox','auto','녹음해 둔 말은 다시 들을 수 있어요.',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":2,"concept":"K6-2-u5-C2","difficulty":1,"kind":"ox","stem":"녹음해 둔 말은 다시 들을 수 있어요.","answer":"O","reason_options":[{"t":"매체에 따라 말도 남을 수 있기 때문에","correct":true},{"t":"말은 언제나 사라지기 때문에","mis":"K6-2-u5-X02"}],"mis":"K6-2-u5-X02","explanation":["말은 보통 그 자리에서 사라져요.","녹음하면 남아요.","매체에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#3','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C3',1,'mc','auto','라디오는 어떤 매체인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"라디오는 어떤 매체인가요?","options":[{"t":"음성 매체","correct":true},{"t":"인쇄 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"문자 매체","mis":"K6-2-u5-X04"}],"explanation":["라디오는 소리로 전해요.","음성 언어에 소리와 음악을 더해요.","그래서 음성 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#4','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C4',1,'mc','auto','문자 언어에서 중요한 곳을 강조하는 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"문자 언어에서 중요한 곳을 강조하는 방법은 어느 것인가요?","options":[{"t":"글자를 굵게 한다","correct":true},{"t":"목소리를 크게 한다","mis":"K6-2-u5-X06"},{"t":"억양을 올린다","mis":"K6-2-u5-X06"},{"t":"잠깐 쉬었다 말한다","mis":"K6-2-u5-X06"}],"explanation":["목소리 · 억양 · 쉬기는 말의 방법이에요.","글에서는 글자 굵기를 써요.","눈에 띄게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#5','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C9',1,'mc','auto','말한 내용을 자막으로도 보여 주면 좋은 점은 어느 것인가요?',ARRAY['K6-2-u5-X11','K6-2-u5-X13']::text[],false,'{"seq":5,"concept":"K6-2-u5-C9","difficulty":1,"kind":"mc","stem":"말한 내용을 자막으로도 보여 주면 좋은 점은 어느 것인가요?","options":[{"t":"놓친 내용을 눈으로 다시 확인할 수 있다","correct":true},{"t":"영상을 짧게 줄일 수 있다","mis":"K6-2-u5-X11"},{"t":"해설하는 말을 없애도 된다","mis":"K6-2-u5-X11"},{"t":"글자가 많아 화려해진다","mis":"K6-2-u5-X13"}],"explanation":["말은 지나가요.","자막은 남아요.","둘이 서로 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#6','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C16',1,'mc','auto','「쓸 거리를 모아 차례를 짜는」 단계는 어느 것인가요?',ARRAY['K6-2-u5-X21']::text[],false,'{"seq":6,"concept":"K6-2-u5-C16","difficulty":1,"kind":"mc","stem":"「쓸 거리를 모아 차례를 짜는」 단계는 어느 것인가요?","options":[{"t":"내용 생성하고 조직하기","correct":true},{"t":"계획 세우기","mis":"K6-2-u5-X21"},{"t":"글 쓰고 고쳐 쓰기","mis":"K6-2-u5-X21"},{"t":"독자에게 건네기","mis":"K6-2-u5-X21"}],"explanation":["계획 세우기에서는 독자와 목적을 정해요.","고쳐 쓰기는 쓴 뒤에 해요.","쓸 거리와 차례는 내용 조직 단계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#7','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C19',1,'mc','auto','기사문의 제목을 무엇이라고 하나요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":7,"concept":"K6-2-u5-C19","difficulty":1,"kind":"mc","stem":"기사문의 제목을 무엇이라고 하나요?","options":[{"t":"표제","correct":true},{"t":"전문","mis":"K6-2-u5-X28"},{"t":"본문","mis":"K6-2-u5-X28"},{"t":"부록","mis":"K6-2-u5-X28"}],"explanation":["전문은 요약, 본문은 자세한 내용이에요.","기사의 제목은 표제예요.","부제는 표제를 보충해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#8','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C22',1,'mc','auto','편지의 짜임에서 가장 먼저 오는 것은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":8,"concept":"K6-2-u5-C22","difficulty":1,"kind":"mc","stem":"편지의 짜임에서 가장 먼저 오는 것은 어느 것인가요?","options":[{"t":"받는 사람","correct":true},{"t":"끝인사","mis":"K6-2-u5-X33"},{"t":"쓴 날짜와 보내는 사람","mis":"K6-2-u5-X33"},{"t":"하고 싶은 말","mis":"K6-2-u5-X33"}],"explanation":["편지는 누구에게 쓰는지부터 밝혀요.","그다음 첫인사, 하고 싶은 말, 끝인사가 와요.","마지막에 날짜와 보내는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#9','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C5',2,'mc','auto','지안이가 모이는 시각을 벌써 잊어버린 까닭과 가장 관계 깊은 음성 언어의 특성은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X06']::text[],false,'{"seq":9,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"지안이가 모이는 시각을 벌써 잊어버린 까닭과 가장 관계 깊은 음성 언어의 특성은 어느 것인가요?","options":[{"t":"말이 끝나면 소리가 사라진다","correct":true},{"t":"목소리로 감정을 함께 전한다","mis":"K6-2-u5-X08"},{"t":"그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"글자 굵기로 강조할 수 있다","mis":"K6-2-u5-X06"}],"explanation":["선생님 말씀은 이미 지나갔어요.","말은 보통 그 자리에서 사라져요.","그래서 지안이가 놓쳤어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#10','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',2,'match','auto','은솔이네 반 상황과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":2,"kind":"match","stem":"은솔이네 반 상황과 알맞은 방법을 이으세요.","pairs":[{"l":"모일 시각과 챙길 것","r":"알림장에 글로 적는다"},{"l":"비 오는 날 일정이 궁금함","r":"그 자리에서 말로 묻는다"},{"l":"여럿이 헷갈리는 내용","r":"말로 하고 글로도 보여 준다"}],"mis":"K6-2-u5-X10","explanation":["다시 봐야 하는 것은 글로 적어요.","궁금한 것은 말로 바로 물어요.","헷갈리는 것은 둘을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#11','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C8',2,'mc','auto','「한 번 더 헹궈요」가 전하려는 것은 무엇인가요?',ARRAY['K6-2-u5-X17']::text[],false,'{"seq":11,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"「한 번 더 헹궈요」가 전하려는 것은 무엇인가요?","options":[{"t":"우유갑은 헹구어 펼쳐 말린 뒤 종이로 내놓자","correct":true},{"t":"우유를 마시지 말자","mis":"K6-2-u5-X17"},{"t":"쓰레기는 모두 한 통에 버리자","mis":"K6-2-u5-X17"},{"t":"분리배출은 어려우니 하지 말자","mis":"K6-2-u5-X17"}],"explanation":["장면 이에서 할 일을 보여 줘요.","장면 사에서 종이 칸에 넣어요.","헹구고 펼치고 말리기를 알려요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#12','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C11',2,'match','auto','「한 번 더 헹궈요」의 장면과 그 장면에서 해야 할 일을 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u5-C11","difficulty":2,"kind":"match","stem":"「한 번 더 헹궈요」의 장면과 그 장면에서 해야 할 일을 이으세요.","pairs":[{"l":"장면 일 — 자막으로 제목","r":"무엇을 다룰지 먼저 알린다"},{"l":"장면 이 — 말과 자막을 함께","r":"해야 할 차례를 정확히 남긴다"},{"l":"장면 사 — 웃는 아이와 짧은 말","r":"해 보고 싶은 마음이 들게 한다"}],"mis":"K6-2-u5-X14","explanation":["처음에는 다룰 것을 알려요.","차례는 말과 자막으로 남겨요.","마지막 장면은 마음을 움직여요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#13','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C20',2,'mc','auto','하은이 기사문에서 확인한 사실로 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":13,"concept":"K6-2-u5-C20","difficulty":2,"kind":"mc","stem":"하은이 기사문에서 확인한 사실로 볼 수 있는 것은 어느 것인가요?","options":[{"t":"이번 달부터 운동장 동쪽에 선을 그어 공 놀이 구역이 생겼다","correct":true},{"t":"모든 학생이 정말 행복해졌다","mis":"K6-2-u5-X26"},{"t":"쉬는 시간마다 백 명도 넘게 온다","mis":"K6-2-u5-X27"},{"t":"다치는 학생이 하나도 없을 것이다","mis":"K6-2-u5-X26"}],"explanation":["행복과 앞날의 짐작은 생각이에요.","백 명은 세어 본 수가 아니에요.","눈으로 확인할 수 있는 것은 구역이 생긴 일이에요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#14','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C19',2,'mc','auto','하은이 기사문의 [전문]을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X28']::text[],false,'{"seq":14,"concept":"K6-2-u5-C19","difficulty":2,"kind":"mc","stem":"하은이 기사문의 [전문]을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이번 달부터 운동장 동쪽에 쉬는 시간 공 놀이 구역이 선을 그어 마련되었다.","correct":true},{"t":"공 놀이 구역이 생겨서 모두 너무너무 행복하다.","mis":"K6-2-u5-X28"},{"t":"기자는 이 구역이 정말 마음에 든다.","mis":"K6-2-u5-X28"},{"t":"공 놀이 구역, 대박!","mis":"K6-2-u5-X28"}],"explanation":["전문은 느낌을 쓰는 곳이 아니에요.","주요 내용을 육하원칙으로 요약해요.","언제 · 어디에서 · 무엇이 드러나게 써요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#15','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C22',2,'mc','auto','준서의 편지에서 빠진 부분이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X33']::text[],false,'{"seq":15,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"준서의 편지에서 빠진 부분이 아닌 것은 어느 것인가요?","options":[{"t":"첫인사","correct":true},{"t":"받는 사람","mis":"K6-2-u5-X33"},{"t":"쓴 날짜와 보내는 사람","mis":"K6-2-u5-X33"},{"t":"없다. 다섯 부분을 모두 갖추었다","mis":"K6-2-u5-X33"}],"explanation":["「잘 지내지?」는 첫인사예요.","받는 사람과 날짜 · 보내는 사람이 빠졌어요.","다섯 부분을 하나씩 확인해요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#16','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C5',2,'mc','auto','장면 ㉮에서 도아의 목소리가 밝고 빠른 것으로 전해지는 것은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X02','K6-2-u5-X06']::text[],false,'{"seq":16,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"장면 ㉮에서 도아의 목소리가 밝고 빠른 것으로 전해지는 것은 어느 것인가요?","options":[{"t":"내일을 기대하는 들뜬 마음","correct":true},{"t":"준비물의 정확한 개수","mis":"K6-2-u5-X08"},{"t":"나중에 다시 볼 수 있는 기록","mis":"K6-2-u5-X02"},{"t":"굵은 글씨로 강조한 낱말","mis":"K6-2-u5-X06"}],"explanation":["목소리에는 감정이 실려요.","밝고 빠르면 들뜬 마음이 전해져요.","이것이 음성 언어의 특성이에요."],"asset":{"type":"passage","lines":["장면 ㉮ 도아가 시율이를 만나 직접 말로 내일 준비물을 알려 준다.","목소리가 밝고 빠르다.","장면 ㉯ 도아가 학급 게시판에 글로 적어 내일 준비물을 알린다.","중요한 것에 굵은 글씨를 썼다."],"title":"같은 내용, 다른 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#17','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',3,'mc','auto','은솔이네 반 상황에서 문자 언어로 전할 내용과 음성 언어로 전할 내용을 알맞게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X09']::text[],false,'{"seq":17,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"은솔이네 반 상황에서 문자 언어로 전할 내용과 음성 언어로 전할 내용을 알맞게 나눈 것은 어느 것인가요?","options":[{"t":"모일 시각과 챙길 것은 글로 적고, 비 오는 날처럼 궁금한 것은 그 자리에서 말로 묻고 답한다","correct":true},{"t":"모두 말로만 하고 다시 묻지 않는다","mis":"K6-2-u5-X10"},{"t":"모두 글로만 하고 묻는 것은 받지 않는다","mis":"K6-2-u5-X03"},{"t":"아무렇게나 나누어도 된다","mis":"K6-2-u5-X09"}],"explanation":["다시 봐야 하는 것은 글로.","바로 주고받을 것은 말로.","나눈 까닭을 특성과 이어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#18','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C10',3,'mc','auto','「한 번 더 헹궈요」 영상을 평가한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X15']::text[],false,'{"seq":18,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"「한 번 더 헹궈요」 영상을 평가한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장면 이는 말과 자막으로 차례를 잘 붙들었지만, 장면 삼은 요소가 너무 많아 무엇이 중요한지 흐려졌다","correct":true},{"t":"요소가 가장 많은 장면 삼이 가장 잘 만든 장면이다","mis":"K6-2-u5-X13"},{"t":"자막이 있는 장면은 모두 좋은 장면이다","mis":"K6-2-u5-X13"},{"t":"재미있었으니 고칠 것이 없다","mis":"K6-2-u5-X15"}],"explanation":["잘된 장면과 고칠 장면을 갈라요.","요소의 개수가 기준이 아니에요.","무엇을 돕는지로 평가해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#19','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C21',3,'mc','auto','하은이 기사문의 표제를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31']::text[],false,'{"seq":19,"concept":"K6-2-u5-C21","difficulty":3,"kind":"mc","stem":"하은이 기사문의 표제를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"운동장에 쉬는 시간 공 놀이 구역 생겨","correct":true},{"t":"운동장 대혁명, 모두가 환호했다","mis":"K6-2-u5-X31"},{"t":"무슨 일이 생겼다","mis":"K6-2-u5-X31"},{"t":"하은이의 운동장 이야기","mis":"K6-2-u5-X31"}],"explanation":["부풀린 말은 빼요.","내용이 없는 제목도 안 돼요.","무슨 일인지 간결하게 드러내요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#20','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C23',3,'mc','auto','준서의 편지를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X36','K6-2-u5-X35']::text[],false,'{"seq":20,"concept":"K6-2-u5-C23","difficulty":3,"kind":"mc","stem":"준서의 편지를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여름에 할머니께서 자전거 타는 법을 끝까지 잡아 주셔서 혼자 탈 수 있게 되었어요. 정말 고마웠어요.」","correct":true},{"t":"「저번에 그거 진짜 진짜 고마웠어.」","mis":"K6-2-u5-X36"},{"t":"「김치는 짰지만 고마웠어.」","mis":"K6-2-u5-X35"},{"t":"「고마움.」","mis":"K6-2-u5-X36"}],"explanation":["「그거」를 콕 집어 써요.","높임말을 써요.","충고는 빼요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#21','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C14',3,'mc','auto','「학교 둘레 쓰레기 줍기 행사」 안내 글을 일학년 동생들이 읽게 돼요. 가장 알맞게 쓴 것은 어느 것인가요?',ARRAY['K6-2-u5-X24','K6-2-u5-X25','K6-2-u5-X22']::text[],false,'{"seq":21,"concept":"K6-2-u5-C14","difficulty":3,"kind":"mc","stem":"「학교 둘레 쓰레기 줍기 행사」 안내 글을 일학년 동생들이 읽게 돼요. 가장 알맞게 쓴 것은 어느 것인가요?","options":[{"t":"「목요일 아침, 학교 둘레를 함께 걸으며 쓰레기를 주워요. 장갑은 학교에서 줘요.」","correct":true},{"t":"「환경 정화 활동의 일환으로 교내외 쓰레기 수거를 실시함」","mis":"K6-2-u5-X24"},{"t":"「쓰레기 줍기 행사가 있다.」","mis":"K6-2-u5-X25"},{"t":"「쓰레기를 줍자!!! 꼭!!!」","mis":"K6-2-u5-X22"}],"explanation":["어려운 한자어는 동생들이 몰라요.","언제 무엇을 하는지 없으면 할 수 없어요.","쉬운 말로 까닭과 할 일을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#22','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C2',3,'mc','auto','이 단원을 마친 학생의 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X02','K6-2-u5-X10']::text[],false,'{"seq":22,"concept":"K6-2-u5-C2","difficulty":3,"kind":"mc","stem":"이 단원을 마친 학생의 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"보통은 이렇지만 매체에 따라 달라요. 그래서 그때그때 살펴요","correct":true},{"t":"글이 말보다 낫고, 영상이 글보다 나아요. 그렇게 외웠어요","mis":"K6-2-u5-X03"},{"t":"말은 절대 남지 않으니까 중요한 건 늘 글로만 해야 해요","mis":"K6-2-u5-X02"},{"t":"매체는 아무거나 골라도 상관없어요","mis":"K6-2-u5-X10"}],"explanation":["특성을 규칙으로 굳히지 않아요.","매체에 등수를 붙이지 않아요.","그 자리에 알맞은 것을 까닭과 함께 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#23','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',4,'mc','auto','은솔이네 반 안내를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10','K6-2-u5-X08']::text[],false,'{"seq":23,"concept":"K6-2-u5-C6","difficulty":4,"kind":"mc","stem":"은솔이네 반 안내를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말로 안내해 은솔이가 바로 물을 수 있었던 것은 좋았지만, 챙길 것이 여럿이라 글로도 남겨야 지안이처럼 놓치는 사람이 없다","correct":true},{"t":"말로 했으니 처음부터 잘못된 안내다","mis":"K6-2-u5-X03"},{"t":"지안이가 집중하지 않은 것이 문제일 뿐 안내 방법은 고칠 것이 없다","mis":"K6-2-u5-X10"},{"t":"은솔이가 질문해서 안내가 길어졌으니 질문을 받지 말아야 한다","mis":"K6-2-u5-X08"}],"explanation":["말의 장점을 먼저 봐요.","놓친 사람이 생긴 까닭을 특성으로 봐요.","글로도 남기면 서로 보완돼요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#24','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C6',4,'essay','teacher','은솔이네 반 대화를 보고, 선생님의 안내에서 음성 언어의 좋은 점이 드러난 곳과 아쉬운 점이 드러난 곳을 하나씩 찾아 쓰고, 더 잘 전하는 방법을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"은솔이네 반 대화를 보고, 선생님의 안내에서 음성 언어의 좋은 점이 드러난 곳과 아쉬운 점이 드러난 곳을 하나씩 찾아 쓰고, 더 잘 전하는 방법을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 은솔이가 비 오는 날 도시락을 묻자 선생님이 바로 답해 주셨다. 음성 언어는 그 자리에서 되묻고 답할 수 있다. 아쉬운 점 — 지안이는 모이는 시각을 벌써 잊어버렸다. 말은 끝나면 소리가 사라지기 때문이다. 방법 — 말로 안내하면서 알림장에 시각과 챙길 것을 적어 주면 좋다. 글은 남아서 놓친 사람이 다시 볼 수 있으니 두 언어가 서로 보완한다.","scoring_points":["음성 언어의 좋은 점을 대화에서 찾았는가","아쉬운 점을 특성과 이어 썼는가","두 언어를 함께 쓰는 방법과 까닭을 썼는가"]},"explanation":["되묻기는 말의 힘이에요.","사라지는 것은 말의 한계예요.","글로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_a#25','kor',6,2,'u5','','g6_2_kor_u5_review_a','unit_review','K6-2-u5-C3',4,'essay','teacher','「글이 말보다 낫고, 영상이 글보다 낫다.」는 말이 왜 알맞지 않은지 이 단원에서 배운 것으로 설명하고, 어떻게 알맞은 방법을 골라야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C3","difficulty":4,"kind":"essay","stem":"「글이 말보다 낫고, 영상이 글보다 낫다.」는 말이 왜 알맞지 않은지 이 단원에서 배운 것으로 설명하고, 어떻게 알맞은 방법을 골라야 하는지 쓰세요.","answer_guide":{"answer":"예: 글은 남아서 다시 볼 수 있지만, 말은 목소리로 감정을 생생하게 전하고 그 자리에서 되물을 수 있다. 영상은 여러 방법을 어울러 쓰지만, 책은 오래 두고 천천히 읽을 수 있고 라디오는 일하면서도 들을 수 있다. 이렇게 언어와 매체는 하는 일이 달라 더 나은 것은 없다. 그래서 전하려는 내용과 받는 사람의 처지를 보고, 그 자리에 알맞은 방법을 까닭과 함께 고른다.","scoring_points":["언어 사이에 등수가 없는 까닭을 특성으로 설명했는가","매체 사이에 등수가 없는 까닭을 설명했는가","내용과 받는 사람을 보고 까닭과 함께 고른다고 썼는가"]},"explanation":["하는 일이 달라요.","등수가 없어요.","그 자리에 알맞은 것을."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#1','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C1',1,'sa','auto','음성으로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"sa","stem":"음성으로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["음성언어","음성 언어"],"explanation":["글자로 나타내는 말은 문자 언어예요.","음성으로 나타내는 말은 음성 언어예요.","바로 전해지고 보통 그 자리에서 사라져요."],"mis":"K6-2-u5-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#2','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C2',1,'mc','auto','「말인데 남는 경우」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02']::text[],false,'{"seq":2,"concept":"K6-2-u5-C2","difficulty":1,"kind":"mc","stem":"「말인데 남는 경우」로 알맞은 것은 어느 것인가요?","options":[{"t":"소리를 담아 보낸 생일 인사","correct":true},{"t":"빠르게 지나가는 대화 글","mis":"K6-2-u5-X02"},{"t":"화면을 넘기면 없어지는 자막","mis":"K6-2-u5-X02"},{"t":"수업 시간에 선생님이 한 번 하신 말씀","mis":"K6-2-u5-X02"}],"explanation":["대화 글과 자막은 글인데 흘러가요.","한 번 하신 말씀은 지나가요.","소리를 담아 보내면 말인데도 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#3','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C8',1,'mc','auto','영상에서 [말]은 무엇을 가리키나요?',ARRAY['K6-2-u5-X12','K6-2-u5-X05']::text[],false,'{"seq":3,"concept":"K6-2-u5-C8","difficulty":1,"kind":"mc","stem":"영상에서 [말]은 무엇을 가리키나요?","options":[{"t":"해설하는 사람이 하는 말","correct":true},{"t":"화면에 글자로 뜨는 말","mis":"K6-2-u5-X12"},{"t":"배경에 깔리는 효과음","mis":"K6-2-u5-X12"},{"t":"영상을 올린 사람의 이름","mis":"K6-2-u5-X05"}],"explanation":["글자로 뜨는 말은 자막이에요.","효과음은 소리예요.","해설하는 사람의 말이 [말]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#4','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C5',1,'ox','auto','음성 언어는 목소리로 감정과 의도를 함께 전할 수 있어요.',ARRAY['K6-2-u5-X08']::text[],false,'{"seq":4,"concept":"K6-2-u5-C5","difficulty":1,"kind":"ox","stem":"음성 언어는 목소리로 감정과 의도를 함께 전할 수 있어요.","answer":"O","reason_options":[{"t":"목소리의 크기 · 억양 · 속도가 마음을 실어 나르기 때문에","correct":true},{"t":"음성 언어는 글자로 나타내기 때문에","mis":"K6-2-u5-X08"}],"mis":"K6-2-u5-X08","explanation":["밝은 목소리와 가라앉은 목소리는 느낌이 달라요.","억양과 속도도 마음을 전해요.","이것이 음성 언어의 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#5','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C13',1,'mc','auto','바닷물이 바다 쪽으로 빠져나가는 것을 무엇이라고 하나요?',ARRAY['K6-2-u5-X18']::text[],false,'{"seq":5,"concept":"K6-2-u5-C13","difficulty":1,"kind":"mc","stem":"바닷물이 바다 쪽으로 빠져나가는 것을 무엇이라고 하나요?","options":[{"t":"썰물","correct":true},{"t":"밀물","mis":"K6-2-u5-X18"},{"t":"퇴적","mis":"K6-2-u5-X18"},{"t":"여울","mis":"K6-2-u5-X18"}],"explanation":["밀려 들어오는 것은 밀물이에요.","쌓이는 일은 퇴적이에요.","빠져나가는 것이 썰물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#6','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C14',1,'ox','auto','같은 내용이라도 누가 읽느냐에 따라 낱말과 차례가 달라져요.',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":6,"concept":"K6-2-u5-C14","difficulty":1,"kind":"ox","stem":"같은 내용이라도 누가 읽느냐에 따라 낱말과 차례가 달라져요.","answer":"O","reason_options":[{"t":"독자가 아는 것과 알아들을 수 있는 말이 다르기 때문에","correct":true},{"t":"글은 누가 읽든 똑같이 써야 하기 때문에","mis":"K6-2-u5-X19"}],"mis":"K6-2-u5-X19","explanation":["독자마다 배경지식과 수준이 달라요.","그래서 낱말과 차례를 맞춰요.","이것이 독자를 고려하는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#7','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C18',1,'ox','auto','기사문은 느낌이 아니라 사실을 쓰는 글이에요.',ARRAY['K6-2-u5-X26']::text[],false,'{"seq":7,"concept":"K6-2-u5-C18","difficulty":1,"kind":"ox","stem":"기사문은 느낌이 아니라 사실을 쓰는 글이에요.","answer":"O","reason_options":[{"t":"여러 사람에게 사실이나 사건을 알리는 글이기 때문에","correct":true},{"t":"기사문은 재미있게 꾸며 쓰는 글이기 때문에","mis":"K6-2-u5-X26"}],"mis":"K6-2-u5-X26","explanation":["기사문은 사실을 알려요.","직접 보고 듣고 조사한 것을 써요.","느낌을 사실처럼 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#8','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C25',1,'mc','auto','「얇다」는 어떻게 소리 나나요?',ARRAY['K6-2-u5-X39','K6-2-u5-X38']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"mc","stem":"「얇다」는 어떻게 소리 나나요?","options":[{"t":"[얄따]","correct":true},{"t":"[얍따]","mis":"K6-2-u5-X39"},{"t":"[얇따]","mis":"K6-2-u5-X38"},{"t":"[야르따]","mis":"K6-2-u5-X39"}],"explanation":["뒤에 자음자가 오면 하나만 소리 나요.","얇다는 ㄹ 소리가 나요.","그래서 [얄따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#9','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C5',2,'mc','auto','은솔이가 비 오는 날의 도시락을 물어 바로 답을 들을 수 있었던 까닭은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X09','K6-2-u5-X06']::text[],false,'{"seq":9,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"은솔이가 비 오는 날의 도시락을 물어 바로 답을 들을 수 있었던 까닭은 어느 것인가요?","options":[{"t":"음성 언어는 모르는 곳을 그 자리에서 되물을 수 있어서","correct":true},{"t":"글로 적힌 안내를 다시 읽어서","mis":"K6-2-u5-X01"},{"t":"은솔이가 기억력이 좋아서","mis":"K6-2-u5-X09"},{"t":"선생님 목소리가 커서","mis":"K6-2-u5-X06"}],"explanation":["은솔이는 그 자리에서 물었어요.","선생님이 바로 답해 주셨어요.","되묻기는 말의 특성이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#10','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C9',2,'error','auto','선생님의 안내 방법에 대해 말했어요. 까닭 없이 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":10,"concept":"K6-2-u5-C9","difficulty":2,"kind":"error","stem":"선생님의 안내 방법에 대해 말했어요. 까닭 없이 말한 친구는 누구인가요?","options":[{"t":"현우 — 「글로 써야 해. 글이 좋으니까.」","correct":true,"mis_target":"K6-2-u5-X09"},{"t":"예나 — 「챙길 것이 넷이라 글로 적어 두면 집에서 다시 볼 수 있어.」","mis":"K6-2-u5-X09"},{"t":"준기 — 「말로 해 주셔서 은솔이가 바로 물어볼 수 있었어.」","mis":"K6-2-u5-X09"}],"explanation":["예나와 준기는 언어의 특성과 이어 말했어요.","현우는 까닭 없이 좋다고만 했어요.","고른 까닭까지 말해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#11','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C9',2,'mc','auto','장면 이에서 「헹구기 → 펼치기 → 말리기」를 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X11','K6-2-u5-X12']::text[],false,'{"seq":11,"concept":"K6-2-u5-C9","difficulty":2,"kind":"mc","stem":"장면 이에서 「헹구기 → 펼치기 → 말리기」를 자막으로도 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해야 할 차례를 눈으로 다시 확인하게 하려고","correct":true},{"t":"화면을 글자로 가득 채우려고","mis":"K6-2-u5-X13"},{"t":"말을 하지 않아도 되게 하려고","mis":"K6-2-u5-X11"},{"t":"음악을 대신하려고","mis":"K6-2-u5-X12"}],"explanation":["차례는 말로만 하면 놓치기 쉬워요.","자막은 남아 있어요.","말과 자막이 서로 보완해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#12','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C12',2,'mc','auto','이 영상을 보고 감상을 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X15','K6-2-u5-X16']::text[],false,'{"seq":12,"concept":"K6-2-u5-C12","difficulty":2,"kind":"mc","stem":"이 영상을 보고 감상을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"장면 이에서 자막으로 차례를 보여 줘서 따라 하기 쉬웠다","correct":true},{"t":"그냥 좋았다","mis":"K6-2-u5-X15"},{"t":"별로였다. 재미없었다","mis":"K6-2-u5-X15"},{"t":"장면 삼이 좋았다는 친구는 잘못 본 것이다","mis":"K6-2-u5-X16"}],"explanation":["느낌만 말하면 까닭이 없어요.","다른 느낌이 틀린 것은 아니에요.","어떤 표현 때문인지 함께 말해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#13','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C21',2,'mc','auto','하은이 기사문의 표제에 대한 평가로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X28']::text[],false,'{"seq":13,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"하은이 기사문의 표제에 대한 평가로 알맞은 것은 어느 것인가요?","options":[{"t":"「완전히 바뀌었다」 · 「온 학교가 환호」는 본문에서 확인되지 않아 부풀린 제목이다","correct":true},{"t":"놀라운 말이 많아 읽고 싶어지니 잘 쓴 제목이다","mis":"K6-2-u5-X31"},{"t":"제목은 아무렇게나 써도 된다","mis":"K6-2-u5-X31"},{"t":"표제가 있으니 부제도 꼭 붙여야 한다","mis":"K6-2-u5-X28"}],"explanation":["제목은 내용을 담아야 해요.","본문에 없는 말을 넣으면 안 돼요.","부풀리지 않아요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#14','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C20',2,'error','auto','하은이 기사문의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X26']::text[],false,'{"seq":14,"concept":"K6-2-u5-C20","difficulty":2,"kind":"error","stem":"하은이 기사문의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"다올 — 「‘백 명도 넘게’를 ‘이백 명쯤’으로 바꾸면 더 정확해.」","correct":true,"mis_target":"K6-2-u5-X27"},{"t":"세빈 — 「점심시간에 직접 세어 본 수로 바꾸고, 언제 셌는지 밝혀.」","mis":"K6-2-u5-X27"},{"t":"주하 — 「‘다치는 학생이 없을 것’은 확인할 수 없으니 빼.」","mis":"K6-2-u5-X26"}],"explanation":["세빈과 주하는 확인한 사실로 고쳤어요.","다올은 또 다른 수를 지어냈어요.","숫자는 세어 보거나 물어본 것만 써요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#15','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C22',2,'mc','auto','준서의 편지에서 받는 사람을 고려하지 않은 점은 어느 것인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X37']::text[],false,'{"seq":15,"concept":"K6-2-u5-C22","difficulty":2,"kind":"mc","stem":"준서의 편지에서 받는 사람을 고려하지 않은 점은 어느 것인가요?","options":[{"t":"웃어른인 할머니께 높임말을 쓰지 않았다","correct":true},{"t":"편지가 너무 짧다","mis":"K6-2-u5-X22"},{"t":"글씨를 예쁘게 쓰지 않았다","mis":"K6-2-u5-X22"},{"t":"편지지를 꾸미지 않았다","mis":"K6-2-u5-X37"}],"explanation":["길이나 꾸밈은 기준이 아니에요.","받는 사람은 할머니예요.","알맞은 높임말을 써야 해요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#16','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C4',2,'mc','auto','장면 ㉯가 장면 ㉮보다 나은 점은 어느 것인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X03']::text[],false,'{"seq":16,"concept":"K6-2-u5-C4","difficulty":2,"kind":"mc","stem":"장면 ㉯가 장면 ㉮보다 나은 점은 어느 것인가요?","options":[{"t":"반 친구 모두가 똑같은 내용을 다시 볼 수 있다","correct":true},{"t":"들뜬 마음이 목소리로 생생하게 전해진다","mis":"K6-2-u5-X08"},{"t":"시율이가 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"글이 말보다 언제나 좋은 언어다","mis":"K6-2-u5-X03"}],"explanation":["들뜬 목소리와 되묻기는 ㉮의 장점이에요.","㉯는 글로 남아요.","더 좋은 언어가 아니라 알맞은 곳이 달라요."],"asset":{"type":"passage","lines":["장면 ㉮ 도아가 시율이를 만나 직접 말로 내일 준비물을 알려 준다.","목소리가 밝고 빠르다.","장면 ㉯ 도아가 학급 게시판에 글로 적어 내일 준비물을 알린다.","중요한 것에 굵은 글씨를 썼다."],"title":"같은 내용, 다른 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#17','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C2',3,'error','auto','은솔이네 반 상황을 보고 말했어요. 이 단원의 약속과 다르게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X08']::text[],false,'{"seq":17,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"은솔이네 반 상황을 보고 말했어요. 이 단원의 약속과 다르게 말한 친구는 누구인가요?","options":[{"t":"라희 — 「말은 언제나 잊어버리니까 중요한 건 절대 말로 하면 안 돼.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"도윤 — 「말로 해서 은솔이가 바로 물어볼 수 있었어.」","mis":"K6-2-u5-X08"},{"t":"채원 — 「녹음해 두면 말도 다시 들을 수 있어.」","mis":"K6-2-u5-X02"}],"explanation":["도윤과 채원은 바르게 말했어요.","라희는 「언제나」 · 「절대」로 규칙을 만들었어요.","특성은 기본 성질이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#18','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C11',3,'mc','auto','장면 일에서 조용한 음악을 깔고 자막으로 제목만 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X14','K6-2-u5-X12','K6-2-u5-X13']::text[],false,'{"seq":18,"concept":"K6-2-u5-C11","difficulty":3,"kind":"mc","stem":"장면 일에서 조용한 음악을 깔고 자막으로 제목만 보여 준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 다룰 영상인지 차분히 먼저 알리려고","correct":true},{"t":"만들 시간이 모자라서","mis":"K6-2-u5-X14"},{"t":"생물이 사는 곳이라는 느낌을 살리려고","mis":"K6-2-u5-X12"},{"t":"자막은 많을수록 좋아서","mis":"K6-2-u5-X13"}],"explanation":["첫 장면은 다룰 것을 알려요.","조용한 음악은 집중하게 해요.","장면마다 해야 할 일이 달라요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#19','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C20',3,'mc','auto','하은이 기사문에서 「쉬는 시간마다 백 명도 넘게 온다고 한다」를 고치려면 무엇을 해야 하나요?',ARRAY['K6-2-u5-X26','K6-2-u5-X27']::text[],false,'{"seq":19,"concept":"K6-2-u5-C20","difficulty":3,"kind":"mc","stem":"하은이 기사문에서 「쉬는 시간마다 백 명도 넘게 온다고 한다」를 고치려면 무엇을 해야 하나요?","options":[{"t":"쉬는 시간에 직접 세어 보고, 언제 몇 번 셌는지 함께 쓴다","correct":true},{"t":"「아주 많이 온다」로 바꾼다","mis":"K6-2-u5-X26"},{"t":"「이백 명」으로 늘려 쓴다","mis":"K6-2-u5-X27"},{"t":"그대로 둔다. 들은 말이니까","mis":"K6-2-u5-X27"}],"explanation":["「~한다고 한다」는 누가 셌는지 몰라요.","숫자를 바꾸어도 지어낸 수예요.","직접 세어 보고 출처를 밝혀요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#20','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C22',3,'mc','auto','준서가 「그때 같이 그거 또 하자」를 고쳐 쓸 때 생각할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X34','K6-2-u5-X36','K6-2-u5-X33']::text[],false,'{"seq":20,"concept":"K6-2-u5-C22","difficulty":3,"kind":"mc","stem":"준서가 「그때 같이 그거 또 하자」를 고쳐 쓸 때 생각할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니가 무엇인지 알 수 있게 그 일을 밝히고 높임말로 여쭌다","correct":true},{"t":"그대로 둔다. 할머니는 다 아신다","mis":"K6-2-u5-X34"},{"t":"「그거」를 「그것」으로만 바꾼다","mis":"K6-2-u5-X36"},{"t":"문장을 지운다","mis":"K6-2-u5-X33"}],"explanation":["받는 사람이 헷갈리지 않게 밝혀요.","웃어른께는 높임말로 여쭈어요.","받는 사람을 떠올려요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#21','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C16',3,'error','auto','글 쓰는 과정에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X21','K6-2-u5-X22']::text[],false,'{"seq":21,"concept":"K6-2-u5-C16","difficulty":3,"kind":"error","stem":"글 쓰는 과정에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세온 — 「독자는 계획 세울 때 한 번 생각했으면 고쳐 쓸 때는 안 봐도 돼.」","correct":true,"mis_target":"K6-2-u5-X21"},{"t":"하빈 — 「고쳐 쓸 때 독자가 오해할 만한 표현이 없는지 다시 읽어.」","mis":"K6-2-u5-X22"},{"t":"준우 — 「쓸 거리를 모을 때도 독자가 궁금해할 것을 떠올려.」","mis":"K6-2-u5-X21"}],"explanation":["하빈과 준우는 단계마다 독자를 떠올렸어요.","세온은 처음에만 독자를 생각했어요.","세 단계마다 독자를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#22','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C16',3,'ox','auto','「앞으로 열심히 하겠다」는 지키기 좋은 실천 다짐이에요.',ARRAY['K6-2-u5-X40']::text[],false,'{"seq":22,"concept":"K6-2-u5-C16","difficulty":3,"kind":"ox","stem":"「앞으로 열심히 하겠다」는 지키기 좋은 실천 다짐이에요.","answer":"X","reason_options":[{"t":"언제 · 어디에서 · 무엇을 할지가 없어 막연하기 때문에","correct":true},{"t":"열심히라는 말이 들어가면 다짐이 크기 때문에","mis":"K6-2-u5-X40"}],"mis":"K6-2-u5-X40","explanation":["막연한 다짐은 지키기 어려워요.","언제 · 어디에서 · 무엇을 할지 정해요.","한 문장으로 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#23','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C12',4,'mc','auto','「한 번 더 헹궈요」를 세 걸음으로 감상한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X05','K6-2-u5-X13','K6-2-u5-X15']::text[],false,'{"seq":23,"concept":"K6-2-u5-C12","difficulty":4,"kind":"mc","stem":"「한 번 더 헹궈요」를 세 걸음으로 감상한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"찾기 — 장면 이에 말과 차례 자막 / 잇기 — 자막이 차례를 붙들어 줌 / 말하기 — 그래서 따라 하기 쉽다고 느꼈다","correct":true},{"t":"찾기 — 영상 길이 / 잇기 — 짧아서 좋음 / 말하기 — 재미있었다","mis":"K6-2-u5-X05"},{"t":"찾기 — 장면 삼 / 잇기 — 요소가 많음 / 말하기 — 많아서 최고다","mis":"K6-2-u5-X13"},{"t":"말하기 — 별로였다 / 찾기와 잇기는 하지 않음","mis":"K6-2-u5-X15"}],"explanation":["영상 안의 요소를 찾아요.","무엇을 돕는지 이어요.","느낌과 까닭을 함께 말해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#24','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C10',4,'essay','teacher','「한 번 더 헹궈요」 영상에서 표현 효과가 있는 장면과 고칠 장면을 하나씩 골라 까닭을 쓰고, 고칠 장면을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C10","difficulty":4,"kind":"essay","stem":"「한 번 더 헹궈요」 영상에서 표현 효과가 있는 장면과 고칠 장면을 하나씩 골라 까닭을 쓰고, 고칠 장면을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 표현 효과가 있는 장면 — 장면 이. 해설하는 말로 방법을 알려 주고 「헹구기 → 펼치기 → 말리기」 자막으로 차례를 붙들어 두어 따라 하기 쉽다. 고칠 장면 — 장면 삼. 자막이 화면 가득하고 큰 음악과 빠른 장면이 계속되어 무엇이 중요한지 흐려진다. 고칠 방법 — 헹군 우유갑 하나를 오래 보여 주고, 자막은 「종이 칸에!」 하나만 두고, 그 순간 음악을 낮춘다.","scoring_points":["표현 효과가 있는 장면과 까닭을 썼는가","고칠 장면과 문제를 썼는가","무엇을 돕는가를 기준으로 고칠 방법을 썼는가"]},"explanation":["좋은 장면 먼저.","개수가 아니라 돕는가.","고칠 방법까지."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_b#25','kor',6,2,'u5','','g6_2_kor_u5_review_b','unit_review','K6-2-u5-C14',4,'essay','teacher','독자를 고려해 글을 쓰는 방법을 쓰기 전 · 쓰는 중 · 쓴 뒤로 나누어 쓰고, 독자를 고려하는 것이 비위를 맞추는 것과 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C14","difficulty":4,"kind":"essay","stem":"독자를 고려해 글을 쓰는 방법을 쓰기 전 · 쓰는 중 · 쓴 뒤로 나누어 쓰고, 독자를 고려하는 것이 비위를 맞추는 것과 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 쓰기 전에는 독자의 흥미 · 배경지식 · 수준 · 매체와 독자가 겪는 어려움을 알아본다. 쓰는 중에는 독자가 관심을 가질 내용을 모아 알아듣기 쉬운 차례로 짜고 필요하면 자료를 넣는다. 쓴 뒤에는 독자 수준에 맞는지, 오해할 표현이 없는지 다시 읽고 고친다. 비위 맞추기는 좋아할 것만 고르거나 어려운 내용을 빼는 것이지만, 독자 고려는 전하려는 것은 그대로 두고 독자에게 닿게 하는 것이다.","scoring_points":["세 단계마다 독자를 고려하는 방법을 썼는가","자료와 고쳐 쓰기를 독자와 이었는가","비위 맞추기와의 차이를 썼는가"]},"explanation":["단계마다 독자.","자료는 이해를 돕게.","전하려는 것은 그대로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#1','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C1',1,'ox','auto','학급 게시판에 적은 안내 글은 문자 언어예요.',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"학급 게시판에 적은 안내 글은 문자 언어예요.","answer":"O","reason_options":[{"t":"글자로 나타낸 말이기 때문에","correct":true},{"t":"선생님이 말로 하신 내용을 옮겼으니 음성 언어이기 때문에","mis":"K6-2-u5-X01"}],"mis":"K6-2-u5-X01","explanation":["말로 한 내용이라도 글자로 적으면 문자 언어예요.","게시판 안내는 글자로 되어 있어요.","그래서 문자 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#2','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C3',1,'mc','auto','이 단원의 약속으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"이 단원의 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"더 나은 언어나 매체는 없고 그 자리에 알맞은 것이 있다","correct":true},{"t":"글이 말보다 나은 언어다","mis":"K6-2-u5-X03"},{"t":"영상이 가장 좋은 매체다","mis":"K6-2-u5-X03"},{"t":"남는 쪽이 언제나 더 좋은 방법이다","mis":"K6-2-u5-X03"}],"explanation":["언어에 등수가 없어요.","매체에도 등수가 없어요.","그 자리에 알맞은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#3','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C8',1,'ox','auto','화면의 크기도 매체 자료가 뜻을 나르는 방법이에요.',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":3,"concept":"K6-2-u5-C8","difficulty":1,"kind":"ox","stem":"화면의 크기도 매체 자료가 뜻을 나르는 방법이에요.","answer":"X","reason_options":[{"t":"화면 크기는 내용의 뜻을 나르지 않기 때문에","correct":true},{"t":"화면이 클수록 뜻이 잘 전해지기 때문에","mis":"K6-2-u5-X05"}],"mis":"K6-2-u5-X05","explanation":["뜻을 나르는 것은 말 · 자막 · 장면 · 소리예요.","화면 크기는 보는 기계의 일이에요.","뜻을 나르는 것만 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#4','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C5',1,'mc','auto','음성 언어의 특성이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X08']::text[],false,'{"seq":4,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"음성 언어의 특성이 아닌 것은 어느 것인가요?","options":[{"t":"적은 내용을 여러 사람이 똑같이 나누어 가진다","correct":true},{"t":"그 자리에서 바로 전해진다","mis":"K6-2-u5-X08"},{"t":"모르는 곳을 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"듣는 사람의 반응을 보며 말을 바꾼다","mis":"K6-2-u5-X08"}],"explanation":["바로 전해지고, 되묻고, 반응을 보는 것은 말의 특성이에요.","똑같이 나누어 갖는 것은 글의 특성이에요.","두 특성을 갈라 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#5','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C11',1,'ox','auto','영상에서 음악의 빠르기를 바꾸는 것은 느낌을 바꾸려고 쓰는 방법이에요.',ARRAY['K6-2-u5-X14']::text[],false,'{"seq":5,"concept":"K6-2-u5-C11","difficulty":1,"kind":"ox","stem":"영상에서 음악의 빠르기를 바꾸는 것은 느낌을 바꾸려고 쓰는 방법이에요.","answer":"O","reason_options":[{"t":"장면에서 해야 할 일에 맞추어 방법을 고르기 때문에","correct":true},{"t":"음악은 아무 때나 바꾸는 것이기 때문에","mis":"K6-2-u5-X14"}],"mis":"K6-2-u5-X14","explanation":["밝고 빠른 음악은 활기찬 느낌을 줘요.","느낌을 바꿀 때 음악을 바꿔요.","방법마다 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#6','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C17',1,'mc','auto','할 일을 나누어 보여 줄 때 쓰면 좋은 것은 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X25']::text[],false,'{"seq":6,"concept":"K6-2-u5-C17","difficulty":1,"kind":"mc","stem":"할 일을 나누어 보여 줄 때 쓰면 좋은 것은 어느 것인가요?","options":[{"t":"기호와 줄 나눔","correct":true},{"t":"그래프","mis":"K6-2-u5-X23"},{"t":"사진","mis":"K6-2-u5-X23"},{"t":"긴 문단 하나","mis":"K6-2-u5-X25"}],"explanation":["그래프는 수를 견줄 때 좋아요.","사진은 모습을 보여 줄 때 좋아요.","할 일은 기호와 줄 나눔으로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#7','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C19',1,'sa','auto','누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u5-C19","difficulty":1,"kind":"sa","stem":"누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["육하원칙"],"explanation":["여섯 가지 물음이에요.","전문은 이것으로 요약해요.","이것을 육하원칙이라고 해요."],"mis":"K6-2-u5-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#8','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C25',1,'ox','auto','「늙어요」는 [늘거요]로 소리 나요.',ARRAY['K6-2-u5-X38']::text[],false,'{"seq":8,"concept":"K6-2-u5-C25","difficulty":1,"kind":"ox","stem":"「늙어요」는 [늘거요]로 소리 나요.","answer":"O","reason_options":[{"t":"뒤에 모음이 와서 두 소리가 다 나고 ㄱ이 뒷글자로 넘어가기 때문에","correct":true},{"t":"겹받침은 언제나 하나만 소리 나기 때문에","mis":"K6-2-u5-X38"}],"mis":"K6-2-u5-X38","explanation":["늙다는 [늑따]예요.","늙어요는 뒤에 모음이 와요.","ㄱ이 넘어가 [늘거요]가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#9','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C6',2,'ox','auto','선생님의 안내는 말로만 했으니 충분해요.',ARRAY['K6-2-u5-X10']::text[],false,'{"seq":9,"concept":"K6-2-u5-C6","difficulty":2,"kind":"ox","stem":"선생님의 안내는 말로만 했으니 충분해요.","answer":"X","reason_options":[{"t":"모일 시각과 챙길 것이 여럿이라 다시 볼 수 있게 글로도 적어 두면 좋기 때문에","correct":true},{"t":"말은 언제나 정확히 기억되기 때문에","mis":"K6-2-u5-X10"}],"mis":"K6-2-u5-X10","explanation":["챙길 것이 넷이나 되고 시각도 있어요.","지안이처럼 놓친 사람이 생겨요.","글로도 적어 두면 다시 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#10','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C7',2,'ox','auto','은솔이네 반처럼 챙길 것이 많을 때에는 말과 글을 함께 쓰는 것이 좋아요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":10,"concept":"K6-2-u5-C7","difficulty":2,"kind":"ox","stem":"은솔이네 반처럼 챙길 것이 많을 때에는 말과 글을 함께 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"말로 놓친 것을 글로 다시 확인할 수 있기 때문에","correct":true},{"t":"같은 내용을 두 번 하면 겹쳐서 쓸모없기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["말은 생생하지만 놓칠 수 있어요.","글은 남아요.","함께 쓰면 서로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#11','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C10',2,'mc','auto','장면 삼의 문제점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X04']::text[],false,'{"seq":11,"concept":"K6-2-u5-C10","difficulty":2,"kind":"mc","stem":"장면 삼의 문제점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자막을 화면 가득 채우고 큰 음악과 빠른 장면을 계속 써서 무엇이 중요한지 흐려졌다","correct":true},{"t":"자막이 많아서 가장 잘 만든 장면이다","mis":"K6-2-u5-X13"},{"t":"음악이 있어서 문제가 없다","mis":"K6-2-u5-X13"},{"t":"말이 없으니 영상이 아니다","mis":"K6-2-u5-X04"}],"explanation":["요소가 많다고 잘 전해지지 않아요.","어디를 봐야 할지 흐려져요.","표현 효과는 무엇을 돕는가로 봐요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#12','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C10',2,'error','auto','장면 삼을 고치는 방법을 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X10']::text[],false,'{"seq":12,"concept":"K6-2-u5-C10","difficulty":2,"kind":"error","stem":"장면 삼을 고치는 방법을 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"소율 — 「자막을 더 많이 넣고 음악도 더 크게 하면 돼.」","correct":true,"mis_target":"K6-2-u5-X13"},{"t":"이준 — 「종이 하나만 오래 보여 주고 자막은 꼭 남길 말만 두면 돼.」","mis":"K6-2-u5-X10"},{"t":"하린 — 「중요한 곳에서 음악을 바꾸면 눈길이 모여.」","mis":"K6-2-u5-X10"}],"explanation":["이준과 하린은 무엇을 도울지 생각했어요.","소율은 개수만 늘렸어요.","많이 넣는다고 잘 전해지지 않아요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#13','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',2,'ox','auto','하은이가 「다음 달에 놀이 기구가 새로 들어온다는 소문」을 기사문에 쓴 것은 알맞아요.',ARRAY['K6-2-u5-X27']::text[],false,'{"seq":13,"concept":"K6-2-u5-C20","difficulty":2,"kind":"ox","stem":"하은이가 「다음 달에 놀이 기구가 새로 들어온다는 소문」을 기사문에 쓴 것은 알맞아요.","answer":"X","reason_options":[{"t":"확인하지 못한 소문은 기사문에 쓰지 않기 때문에","correct":true},{"t":"소문도 많은 사람이 알면 좋기 때문에","mis":"K6-2-u5-X27"}],"mis":"K6-2-u5-X27","explanation":["옆 반 친구 말을 들었을 뿐이에요.","누구에게 확인한 것이 아니에요.","확인하지 못한 것은 쓰지 않아요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#14','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',2,'ox','auto','「아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다」는 기사문에 알맞은 문장이에요.',ARRAY['K6-2-u5-X26']::text[],false,'{"seq":14,"concept":"K6-2-u5-C20","difficulty":2,"kind":"ox","stem":"「아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다」는 기사문에 알맞은 문장이에요.","answer":"X","reason_options":[{"t":"확인할 수 없는 쓴 사람의 짐작이기 때문에","correct":true},{"t":"좋은 일을 알리는 문장이기 때문에","mis":"K6-2-u5-X26"}],"mis":"K6-2-u5-X26","explanation":["「아마 ~ 것이다」는 짐작이에요.","누구도 다시 확인할 수 없어요.","생각을 사실처럼 쓰지 않아요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#15','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C23',2,'ox','auto','준서의 「저번에 그거 진짜 고마웠어」는 고마운 마음이 잘 닿는 문장이에요.',ARRAY['K6-2-u5-X36']::text[],false,'{"seq":15,"concept":"K6-2-u5-C23","difficulty":2,"kind":"ox","stem":"준서의 「저번에 그거 진짜 고마웠어」는 고마운 마음이 잘 닿는 문장이에요.","answer":"X","reason_options":[{"t":"무엇이 고마웠는지 콕 집어 쓰지 않아 막연하기 때문에","correct":true},{"t":"「진짜」를 넣어 아주 고마워 보이기 때문에","mis":"K6-2-u5-X36"}],"mis":"K6-2-u5-X36","explanation":["「그거」가 무엇인지 알 수 없어요.","할머니도 무슨 일인지 헷갈릴 수 있어요.","고마운 일을 콕 집어 써요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#16','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C25',2,'match','auto','낱말과 소리를 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u5-C25","difficulty":2,"kind":"match","stem":"낱말과 소리를 알맞게 이으세요.","pairs":[{"l":"붉어요","r":"[불거요]"},{"l":"짧아요","r":"[짤바요]"},{"l":"늙다","r":"[늑따]"}],"mis":"K6-2-u5-X38","explanation":["붉어요 · 짧아요는 뒤에 모음이 와 두 소리가 다 나요.","늙다는 뒤에 자음자가 와 하나만 나요.","뒤에 오는 것을 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#17','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C7',3,'mc','auto','선생님이 다음 날 아침 다시 알릴 때 가장 알맞은 방법과 까닭은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X10','K6-2-u5-X03']::text[],false,'{"seq":17,"concept":"K6-2-u5-C7","difficulty":3,"kind":"mc","stem":"선생님이 다음 날 아침 다시 알릴 때 가장 알맞은 방법과 까닭은 어느 것인가요?","options":[{"t":"칠판에 시각과 챙길 것을 적어 두고 말로도 짚어 준다 — 놓친 것을 글로 확인하고 궁금한 것은 말로 물을 수 있으니까","correct":true},{"t":"어제 말했으니 다시 알리지 않는다 — 한 번 말한 것은 모두 기억하니까","mis":"K6-2-u5-X02"},{"t":"방송으로 크게 한 번 더 말한다 — 크면 잊지 않으니까","mis":"K6-2-u5-X10"},{"t":"글로만 적는다 — 글이 말보다 낫니까","mis":"K6-2-u5-X03"}],"explanation":["놓친 친구가 있었어요.","글은 남고 말은 물을 수 있어요.","둘을 함께 쓰면 서로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#18','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C12',3,'error','auto','「한 번 더 헹궈요」를 감상했어요. 까닭 없이 느낌만 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X15']::text[],false,'{"seq":18,"concept":"K6-2-u5-C12","difficulty":3,"kind":"error","stem":"「한 번 더 헹궈요」를 감상했어요. 까닭 없이 느낌만 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「장면 사가 제일 좋았어. 그냥.」","correct":true,"mis_target":"K6-2-u5-X15"},{"t":"서아 — 「장면 사에서 아이가 웃는 장면과 짧은 말 때문에 나도 해 보고 싶었어.」","mis":"K6-2-u5-X15"},{"t":"민호 — 「장면 이의 자막 덕분에 차례를 잊지 않았어.」","mis":"K6-2-u5-X15"}],"explanation":["서아와 민호는 표현과 느낌을 이었어요.","태윤은 까닭이 없어요.","어떤 표현 때문인지 함께 말해요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#19','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C19',3,'error','auto','하은이 기사문의 전문을 육하원칙으로 고치려고 해요. 잘못 짝 지은 친구는 누구인가요?',ARRAY['K6-2-u5-X29']::text[],false,'{"seq":19,"concept":"K6-2-u5-C19","difficulty":3,"kind":"error","stem":"하은이 기사문의 전문을 육하원칙으로 고치려고 해요. 잘못 짝 지은 친구는 누구인가요?","options":[{"t":"하나 — 「‘왜’ — 운동장 동쪽에」","correct":true,"mis_target":"K6-2-u5-X29"},{"t":"지훈 — 「‘언제’ — 이번 달부터」","mis":"K6-2-u5-X29"},{"t":"수빈 — 「‘무엇을’ — 공 놀이 구역을」","mis":"K6-2-u5-X29"}],"explanation":["지훈과 수빈은 바르게 짝 지었어요.","「운동장 동쪽에」는 어디에서예요.","여섯 물음에 맞게 나눠요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#20','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C24',3,'mc','auto','준서가 할머니께 편지를 전할 매체를 고를 때 가장 알맞게 생각한 것은 어느 것인가요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X37']::text[],false,'{"seq":20,"concept":"K6-2-u5-C24","difficulty":3,"kind":"mc","stem":"준서가 할머니께 편지를 전할 매체를 고를 때 가장 알맞게 생각한 것은 어느 것인가요?","options":[{"t":"할머니가 두고두고 읽으실 수 있게 손 편지로 써서 방학 때 직접 건넨다","correct":true},{"t":"가장 빨리 보낼 수 있는 짧은 문자로 보낸다","mis":"K6-2-u5-X10"},{"t":"영상이 언제나 더 좋으니 영상으로 만든다","mis":"K6-2-u5-X03"},{"t":"예쁘게 꾸미는 데 시간을 다 쓰고 내용은 줄인다","mis":"K6-2-u5-X37"}],"explanation":["마음과 받는 사람의 처지를 봐요.","매체에 등수는 없어요.","건네고 반응을 들으면 완성이에요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#21','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C17',3,'mc','auto','「우리 반 아침 독서 시간에 읽은 책 수가 달마다 늘었다」를 알릴 때 가장 알맞은 자료는 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X13','K6-2-u5-X25']::text[],false,'{"seq":21,"concept":"K6-2-u5-C17","difficulty":3,"kind":"mc","stem":"「우리 반 아침 독서 시간에 읽은 책 수가 달마다 늘었다」를 알릴 때 가장 알맞은 자료는 어느 것인가요?","options":[{"t":"달마다 읽은 책 수를 견주는 그래프","correct":true},{"t":"책 표지 사진 여러 장","mis":"K6-2-u5-X23"},{"t":"화려한 꾸밈 그림","mis":"K6-2-u5-X13"},{"t":"자료 없이 「많이 늘었다」만 쓰기","mis":"K6-2-u5-X25"}],"explanation":["수의 변화를 보여 줘야 해요.","견줄 때는 표나 그래프가 좋아요.","자료는 글과 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#22','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C16',3,'mc','auto','배운 것을 실천하는 다짐으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X40']::text[],false,'{"seq":22,"concept":"K6-2-u5-C16","difficulty":3,"kind":"mc","stem":"배운 것을 실천하는 다짐으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「다음 주 학급 알림 글을 쓸 때, 읽을 사람이 할 일을 기호로 나누어 적겠다.」","correct":true},{"t":"「앞으로 글을 열심히 잘 쓰겠다.」","mis":"K6-2-u5-X40"},{"t":"「다들 독자를 생각합시다.」","mis":"K6-2-u5-X40"},{"t":"「매일매일 모든 글을 완벽하게 쓰겠다.」","mis":"K6-2-u5-X40"}],"explanation":["언제 · 어디에서 · 무엇을이 보여요.","내가 할 일이에요.","지킬 수 있는 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#23','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C18',4,'mc','auto','하은이 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X32','K6-2-u5-X30']::text[],false,'{"seq":23,"concept":"K6-2-u5-C18","difficulty":4,"kind":"mc","stem":"하은이 기사문을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기삿거리는 알맞지만, 제목이 부풀려졌고 전문에 느낌을 썼으며, 소문 · 지어낸 수 · 짐작이 사실처럼 들어갔고 자료 출처가 없다","correct":true},{"t":"흥미로운 말이 많아 잘 쓴 기사문이다","mis":"K6-2-u5-X31"},{"t":"사진이 있으니 믿을 만한 기사문이다","mis":"K6-2-u5-X32"},{"t":"운동장 이야기라서 기사문이 될 수 없다","mis":"K6-2-u5-X30"}],"explanation":["잘된 점을 먼저 짚어요.","사실 · 제목 · 출처를 하나씩 봐요.","고칠 곳을 정확히 짚어요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#24','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C20',4,'essay','teacher','하은이 기사문에서 고쳐야 할 곳을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 표제와 전문을 고쳐 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C20","difficulty":4,"kind":"essay","stem":"하은이 기사문에서 고쳐야 할 곳을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 표제와 전문을 고쳐 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 첫째, 「온 학교가 환호」는 본문에서 확인되지 않아 부풀린 제목이다. 둘째, 「백 명도 넘게 온다고 한다」는 세어 보지 않은 수이고, 놀이 기구 이야기는 확인하지 못한 소문이다. 셋째, 「다치는 학생이 하나도 없을 것」은 쓴 사람의 짐작이다. 또 사진의 출처가 없다. 고친 표제 — 운동장에 쉬는 시간 공 놀이 구역 생겨. 고친 전문 — 이번 달부터 운동장 동쪽에 쉬는 시간 공 놀이 구역이 선을 그어 마련되었다.","scoring_points":["고칠 곳을 세 가지 바르게 찾았는가","사실 · 확인 · 출처를 기준으로 까닭을 썼는가","부풀리지 않은 표제와 육하원칙에 맞는 전문을 썼는가"]},"explanation":["확인한 것만.","제목은 부풀리지 않게.","전문은 요약."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_c#25','kor',6,2,'u5','','g6_2_kor_u5_review_c','unit_review','K6-2-u5-C21',4,'essay','teacher','우리 학교에서 독자인 학생들이 관심을 가질 만하고 직접 확인할 수 있는 기삿거리를 하나 정해, 기사문 계획(독자 · 기삿거리 · 필요한 자료 · 자료 수집 방법)을 세우고 부풀리지 않은 표제를 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C21","difficulty":4,"kind":"essay","stem":"우리 학교에서 독자인 학생들이 관심을 가질 만하고 직접 확인할 수 있는 기삿거리를 하나 정해, 기사문 계획(독자 · 기삿거리 · 필요한 자료 · 자료 수집 방법)을 세우고 부풀리지 않은 표제를 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 독자 — 우리 학교 학생. 기삿거리 — 이번 달부터 바뀐 아침 등교 길 안전 도우미 활동. 필요한 자료 — 도우미가 서는 자리를 표시한 그림, 도우미 학생의 말. 수집 방법 — 아침에 직접 정문에 나가 보고, 도우미 학생에게 물어보고, 그림은 내가 그려 출처를 밝힌다. 표제 — 정문 앞 아침 길, 안전 도우미가 지킨다.","scoring_points":["독자가 관심 있고 확인할 수 있는 기삿거리를 골랐는가","계획의 네 가지를 모두 썼는가","출처를 생각하고 부풀리지 않은 표제를 썼는가"]},"explanation":["관심 있고 확인할 수 있게.","계획 네 가지.","부풀리지 않은 제목."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#1','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C1',1,'mc','auto','음성 언어의 예로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"음성 언어의 예로 알맞은 것은 어느 것인가요?","options":[{"t":"아침 조회 시간의 교장 선생님 말씀","correct":true},{"t":"교실 벽에 붙은 시간표","mis":"K6-2-u5-X01"},{"t":"알림장에 적은 준비물","mis":"K6-2-u5-X01"},{"t":"책에 인쇄된 이야기","mis":"K6-2-u5-X01"}],"explanation":["시간표 · 알림장 · 책은 글자로 되어 있어요.","조회 말씀은 음성으로 전해져요.","그래서 음성 언어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#2','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C3',1,'ox','auto','인쇄 매체는 이제 쓸모가 없는 매체예요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":1,"kind":"ox","stem":"인쇄 매체는 이제 쓸모가 없는 매체예요.","answer":"X","reason_options":[{"t":"매체마다 주로 쓰는 방법이 달라 알맞은 곳이 다르기 때문에","correct":true},{"t":"영상 매체가 모든 일을 더 잘하기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["책과 신문은 오래 두고 다시 볼 수 있어요.","매체마다 알맞은 곳이 달라요.","쓸모없는 매체는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#3','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C4',1,'mc','auto','영상 매체가 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":3,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"영상 매체가 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"음성 언어 · 문자 언어 · 그림 · 소리 · 움직임을 어울러 쓴다","correct":true},{"t":"문자 언어에 표와 사진만 더한다","mis":"K6-2-u5-X04"},{"t":"음성 언어에 음악만 더한다","mis":"K6-2-u5-X04"},{"t":"글자만 쓴다","mis":"K6-2-u5-X04"}],"explanation":["문자 언어에 표와 사진은 인쇄 매체예요.","음성 언어에 음악은 음성 매체예요.","영상은 여러 방법이 어우러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#4','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C4',1,'ox','auto','글은 한 번 쓰고 나면 고칠 수 없어요.',ARRAY['K6-2-u5-X07']::text[],false,'{"seq":4,"concept":"K6-2-u5-C4","difficulty":1,"kind":"ox","stem":"글은 한 번 쓰고 나면 고칠 수 없어요.","answer":"X","reason_options":[{"t":"천천히 생각하며 쓴 뒤에 고칠 수 있기 때문에","correct":true},{"t":"글은 그대로 남기 때문에","mis":"K6-2-u5-X07"}],"mis":"K6-2-u5-X07","explanation":["글은 쓴 뒤에 다시 읽을 수 있어요.","그래서 고칠 수도 있어요.","고쳐 쓰기도 글의 특성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#5','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',1,'mc','auto','영상 감상의 세 걸음을 차례대로 쓴 것은 어느 것인가요?',ARRAY['K6-2-u5-X15']::text[],false,'{"seq":5,"concept":"K6-2-u5-C12","difficulty":1,"kind":"mc","stem":"영상 감상의 세 걸음을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"찾기 → 잇기 → 말하기","correct":true},{"t":"말하기 → 찾기 → 잇기","mis":"K6-2-u5-X15"},{"t":"잇기 → 말하기 → 찾기","mis":"K6-2-u5-X15"},{"t":"보기 → 끄기 → 잊기","mis":"K6-2-u5-X15"}],"explanation":["먼저 무엇이 쓰였는지 찾아요.","그것이 무엇을 돕는지 이어요.","마지막에 느낌과 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#6','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C15',1,'mc','auto','독자를 고려한 글쓰기로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X24']::text[],false,'{"seq":6,"concept":"K6-2-u5-C15","difficulty":1,"kind":"mc","stem":"독자를 고려한 글쓰기로 알맞은 것은 어느 것인가요?","options":[{"t":"전하려는 것은 그대로 두고 알아들을 수 있게 짠다","correct":true},{"t":"독자가 좋아할 것만 골라 쓴다","mis":"K6-2-u5-X20"},{"t":"어려운 이야기는 모두 뺀다","mis":"K6-2-u5-X20"},{"t":"어려운 낱말을 많이 써서 훌륭해 보이게 한다","mis":"K6-2-u5-X24"}],"explanation":["좋아할 것만 고르면 비위 맞추기예요.","어려운 낱말은 독자에게 닿지 않아요.","전하려는 것은 두고 닿게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#7','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C20',1,'mc','auto','기사문에 쓸 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X27','K6-2-u5-X26']::text[],false,'{"seq":7,"concept":"K6-2-u5-C20","difficulty":1,"kind":"mc","stem":"기사문에 쓸 수 있는 것은 어느 것인가요?","options":[{"t":"직접 들은 사람의 말","correct":true},{"t":"확인하지 못한 소문","mis":"K6-2-u5-X27"},{"t":"그럴 것 같아서 지어낸 숫자","mis":"K6-2-u5-X27"},{"t":"「모두 기뻐했다」 같은 내 생각","mis":"K6-2-u5-X26"}],"explanation":["소문과 지어낸 수는 쓰지 않아요.","내 생각을 사실처럼 쓰지 않아요.","직접 들은 말은 옮겨 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#8','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C23',1,'mc','auto','힘든 일을 겪는 친구에게 힘을 내라는 마음을 전할 때 알맞은 말은 어느 것인가요?',ARRAY['K6-2-u5-X35','K6-2-u5-X36']::text[],false,'{"seq":8,"concept":"K6-2-u5-C23","difficulty":1,"kind":"mc","stem":"힘든 일을 겪는 친구에게 힘을 내라는 마음을 전할 때 알맞은 말은 어느 것인가요?","options":[{"t":"내가 곁에 있을게. 필요하면 언제든 말해 줘","correct":true},{"t":"그러게 내가 미리 조심하라고 했잖아","mis":"K6-2-u5-X35"},{"t":"힘내","mis":"K6-2-u5-X36"},{"t":"다음부터는 이렇게 해 봐","mis":"K6-2-u5-X35"}],"explanation":["섣부른 충고는 힘이 되지 않아요.","한 마디만으로는 막연해요.","곁에 있다는 말을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#9','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C6',2,'mc','auto','선생님이 안내를 더 잘 전하려면 어떻게 하면 좋을까요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03','K6-2-u5-X25']::text[],false,'{"seq":9,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"선생님이 안내를 더 잘 전하려면 어떻게 하면 좋을까요?","options":[{"t":"말로 안내하고 알림장에도 모일 시각과 챙길 것을 적어 준다","correct":true},{"t":"같은 말을 더 큰 목소리로 한 번 더 한다","mis":"K6-2-u5-X10"},{"t":"글로만 알리고 질문은 받지 않는다","mis":"K6-2-u5-X03"},{"t":"안내를 짧게 줄여 시각만 말한다","mis":"K6-2-u5-X25"}],"explanation":["말로 하면 질문을 받을 수 있어요.","글로 적으면 다시 볼 수 있어요.","두 언어를 함께 쓰면 서로 보완해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#10','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C5',2,'mc','auto','선생님이 「좋은 질문이에요」라고 답한 장면에서 알 수 있는 음성 언어의 특성은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X06','K6-2-u5-X07']::text[],false,'{"seq":10,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"선생님이 「좋은 질문이에요」라고 답한 장면에서 알 수 있는 음성 언어의 특성은 어느 것인가요?","options":[{"t":"듣는 사람의 반응을 보며 다시 설명할 수 있다","correct":true},{"t":"적은 내용이 오래 남는다","mis":"K6-2-u5-X02"},{"t":"글자의 크기로 강조한다","mis":"K6-2-u5-X06"},{"t":"천천히 생각하며 고칠 수 있다","mis":"K6-2-u5-X07"}],"explanation":["은솔이의 물음을 듣고 답을 더해 주셨어요.","듣는 사람의 반응에 맞춰 설명을 보탰어요.","마주 보고 말하기 때문이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#11','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C12',2,'ox','auto','장면 이의 말과 자막이 차례를 기억하는 데 도움이 되었다는 것은 영상 안에서 함께 확인할 수 있어요.',ARRAY['K6-2-u5-X16']::text[],false,'{"seq":11,"concept":"K6-2-u5-C12","difficulty":2,"kind":"ox","stem":"장면 이의 말과 자막이 차례를 기억하는 데 도움이 되었다는 것은 영상 안에서 함께 확인할 수 있어요.","answer":"O","reason_options":[{"t":"그 장면에 무엇이 쓰였고 무엇을 돕는지는 영상에서 찾을 수 있기 때문에","correct":true},{"t":"무엇을 돕는지는 사람마다 달라 확인할 수 없기 때문에","mis":"K6-2-u5-X16"}],"mis":"K6-2-u5-X16","explanation":["장면 이에 말과 자막이 있어요.","자막에 차례가 적혀 있어요.","이것은 함께 확인할 수 있는 거예요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#12','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C8',2,'ox','auto','장면 사의 웃는 아이 장면은 어떤 일이 벌어지는지 한눈에 보여 주는 일을 해요.',ARRAY['K6-2-u5-X12']::text[],false,'{"seq":12,"concept":"K6-2-u5-C8","difficulty":2,"kind":"ox","stem":"장면 사의 웃는 아이 장면은 어떤 일이 벌어지는지 한눈에 보여 주는 일을 해요.","answer":"O","reason_options":[{"t":"장면과 움직임은 말로 길게 할 것을 한눈에 보여 주기 때문에","correct":true},{"t":"장면은 영상의 장식일 뿐 뜻을 나르지 않기 때문에","mis":"K6-2-u5-X12"}],"mis":"K6-2-u5-X12","explanation":["아이가 우유갑을 종이 칸에 넣어요.","말로 길게 하지 않아도 알 수 있어요.","장면도 뜻을 날라요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#13','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C21',2,'mc','auto','하은이 기사문의 [자료]를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X23','K6-2-u5-X32','K6-2-u5-X13']::text[],false,'{"seq":13,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"하은이 기사문의 [자료]를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"사진을 누가 언제 찍었는지 출처를 밝힌다","correct":true},{"t":"사진을 세 장 더 넣는다","mis":"K6-2-u5-X23"},{"t":"사진은 그대로 두고 아무것도 적지 않는다","mis":"K6-2-u5-X32"},{"t":"사진 대신 화려한 그림을 넣는다","mis":"K6-2-u5-X13"}],"explanation":["자료는 개수가 중요하지 않아요.","어디에서 얻었는지 알아야 믿을 수 있어요.","출처를 밝혀요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#14','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C21',2,'mc','auto','하은이가 기삿거리를 고른 것에 대한 평가로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X30','K6-2-u5-X27']::text[],false,'{"seq":14,"concept":"K6-2-u5-C21","difficulty":2,"kind":"mc","stem":"하은이가 기삿거리를 고른 것에 대한 평가로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 학교 학생이 관심을 가질 만하고 직접 가서 확인할 수 있는 일이라 기삿거리는 알맞다","correct":true},{"t":"운동장 이야기는 아무도 관심이 없어 알맞지 않다","mis":"K6-2-u5-X30"},{"t":"먼 나라 이야기를 골랐어야 한다","mis":"K6-2-u5-X30"},{"t":"기삿거리가 좋으면 소문을 써도 된다","mis":"K6-2-u5-X27"}],"explanation":["독자는 우리 학교 학생이에요.","운동장은 가서 볼 수 있어요.","기삿거리는 좋지만 쓰는 방법을 고쳐야 해요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#15','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C23',2,'mc','auto','「근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.」가 이 편지에 알맞지 않은 까닭은 어느 것인가요?',ARRAY['K6-2-u5-X33','K6-2-u5-X22','K6-2-u5-X34']::text[],false,'{"seq":15,"concept":"K6-2-u5-C23","difficulty":2,"kind":"mc","stem":"「근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.」가 이 편지에 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"고마운 마음을 전하는 편지에 충고를 넣어 마음이 흐려졌다","correct":true},{"t":"김치 이야기는 편지에 쓰면 안 되는 낱말이라서","mis":"K6-2-u5-X33"},{"t":"문장이 짧아서","mis":"K6-2-u5-X22"},{"t":"할머니가 김치를 모르셔서","mis":"K6-2-u5-X34"}],"explanation":["편지의 목적은 고마움이에요.","충고는 이 마음과 맞지 않아요.","마음에 맞는 내용을 골라요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#16','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C25',2,'ox','auto','「짧다」는 [짭따]로 소리 나요.',ARRAY['K6-2-u5-X39']::text[],false,'{"seq":16,"concept":"K6-2-u5-C25","difficulty":2,"kind":"ox","stem":"「짧다」는 [짭따]로 소리 나요.","answer":"X","reason_options":[{"t":"짧다는 ㄹ이 소리 나서 [짤따]로 읽기 때문에","correct":true},{"t":"겹받침은 언제나 뒤의 것이 소리 나기 때문에","mis":"K6-2-u5-X39"}],"mis":"K6-2-u5-X39","explanation":["짧다는 ㄹ이 소리 나요.","그래서 [짤따]예요.","낱말마다 소리 나는 쪽을 소리 내어 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#17','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C9',3,'mc','auto','지안이에게 은솔이가 답해 주는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X25','K6-2-u5-X02','K6-2-u5-X07']::text[],false,'{"seq":17,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"지안이에게 은솔이가 답해 주는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여덟 시 사십 분까지 정문이야. 나도 헷갈릴까 봐 알림장에 적어 뒀어.」","correct":true},{"t":"「몰라. 그냥 일찍 와.」","mis":"K6-2-u5-X25"},{"t":"「말은 원래 다 잊어버리는 거야.」","mis":"K6-2-u5-X02"},{"t":"「글로 적는 건 쓸데없어.」","mis":"K6-2-u5-X07"}],"explanation":["정확한 시각을 알려 줘요.","글로 적어 두면 다시 볼 수 있어요.","두 언어의 특성을 함께 썼어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"내일 현장 체험 학습은 여덟 시 사십 분까지 정문에 모입니다."},{"who":"선생님","text":"도시락, 물, 모자, 갈아 신을 양말을 챙기세요. 비가 오면 실내 일정으로 바뀝니다."},{"who":"은솔","text":"선생님, 비가 오면 도시락도 가져오나요?"},{"who":"선생님","text":"좋은 질문이에요. 네, 비가 와도 도시락은 가져옵니다."},{"who":"지안","text":"(작은 목소리로) 은솔아, 정문 몇 시까지라고 하셨지? 벌써 잊었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#18','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C9',3,'mc','auto','장면 삼을 「한 번 더 헹궈요」에 맞게 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X11','K6-2-u5-X14']::text[],false,'{"seq":18,"concept":"K6-2-u5-C9","difficulty":3,"kind":"mc","stem":"장면 삼을 「한 번 더 헹궈요」에 맞게 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"헹군 우유갑 하나를 오래 보여 주고, 자막은 「종이 칸에!」만 두고, 그 순간 음악을 낮춘다","correct":true},{"t":"물건을 더 많이 더 빨리 보여 준다","mis":"K6-2-u5-X13"},{"t":"자막을 모두 지우고 음악만 크게 한다","mis":"K6-2-u5-X11"},{"t":"장면 삼을 처음으로 옮기기만 한다","mis":"K6-2-u5-X14"}],"explanation":["하나를 오래 보여 줘요.","꼭 남길 말만 자막으로.","중요한 곳에서 소리를 바꿔요."],"asset":{"type":"passage","lines":["장면 일 [화면] 빈 우유갑이 쓰레기통 앞에 놓여 있다. [소리] 조용한 음악.","[자막] 한 번 더 헹궈요","장면 이 [화면] 우유갑을 물로 헹구고 펼쳐 말린다.","[말] 헹구어 펼쳐 말리면 종이로 다시 쓸 수 있습니다.","[자막] 헹구기 → 펼치기 → 말리기","장면 삼 [화면] 여러 물건이 쉴 새 없이 바뀐다. [소리] 큰 음악이 계속된다.","[자막] 화면 가득 글자 — 병, 캔, 비닐, 종이, 스티로폼, 유리…","장면 사 [화면] 아이가 펼친 우유갑을 종이 칸에 넣고 웃는다. [말] 한 번 더요!"],"title":"분리배출 영상 「한 번 더 헹궈요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#19','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C18',3,'mc','auto','하은이 기사문 전체를 고칠 때 가장 먼저 지켜야 할 것은 어느 것인가요?',ARRAY['K6-2-u5-X31','K6-2-u5-X23','K6-2-u5-X26']::text[],false,'{"seq":19,"concept":"K6-2-u5-C18","difficulty":3,"kind":"mc","stem":"하은이 기사문 전체를 고칠 때 가장 먼저 지켜야 할 것은 어느 것인가요?","options":[{"t":"확인한 사실만 남기고, 생각은 누구의 생각인지 밝히고, 소문은 뺀다","correct":true},{"t":"놀라운 말을 더 넣어 읽고 싶게 만든다","mis":"K6-2-u5-X31"},{"t":"사진을 여러 장 더 넣는다","mis":"K6-2-u5-X23"},{"t":"기자의 느낌을 더 자세히 쓴다","mis":"K6-2-u5-X26"}],"explanation":["기사문은 사실이라고 믿고 읽어요.","자료와 꾸밈은 그다음이에요.","확인한 것만 남겨요."],"asset":{"type":"passage","lines":["[표제] 운동장이 완전히 바뀌었다, 온 학교가 환호!","[전문] 공 놀이 구역이 생겨서 모든 학생이 정말 행복해졌다.","[본문] 이번 달부터 운동장 동쪽에 공 놀이 구역이 선을 그어 생겼다.","쉬는 시간마다 백 명도 넘게 온다고 한다.","옆 반 친구 말로는 다음 달에 놀이 기구도 새로 들어온다는 소문이 있다.","아마 이 구역 덕분에 다치는 학생이 하나도 없을 것이다.","[자료] 공 놀이 구역 사진 한 장 (어디에서 얻었는지 적지 않음)"],"title":"하은이가 쓴 기사문 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#20','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C22',3,'error','auto','준서의 편지를 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X33','K6-2-u5-X34']::text[],false,'{"seq":20,"concept":"K6-2-u5-C22","difficulty":3,"kind":"error","stem":"준서의 편지를 고칠 점을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「편지지를 더 예쁜 것으로 바꾸면 돼.」","correct":true,"mis_target":"K6-2-u5-X22"},{"t":"도겸 — 「맨 앞에 ‘할머니께’를 쓰고 끝에 날짜와 ‘손자 준서 올림’을 써.」","mis":"K6-2-u5-X33"},{"t":"나은 — 「‘안녕!’ 대신 ‘할머니, 건강하게 지내셨어요?’로 써.」","mis":"K6-2-u5-X34"}],"explanation":["도겸과 나은은 빠진 부분과 높임말을 짚었어요.","윤서는 겉모습을 고치려 했어요.","고쳐 쓰기는 받는 사람에게 닿게 하는 일이에요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#21','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C15',3,'mc','auto','「놀이터 그네 순서 지키기」를 알리는 글을 쓸 때 독자 고려를 바르게 한 것은 어느 것인가요?',ARRAY['K6-2-u5-X20','K6-2-u5-X24','K6-2-u5-X23']::text[],false,'{"seq":21,"concept":"K6-2-u5-C15","difficulty":3,"kind":"mc","stem":"「놀이터 그네 순서 지키기」를 알리는 글을 쓸 때 독자 고려를 바르게 한 것은 어느 것인가요?","options":[{"t":"순서를 지켜야 하는 까닭(부딪쳐 다칠 수 있음)은 그대로 두고, 줄 서는 자리를 그림으로 보여 준다","correct":true},{"t":"동생들이 싫어할 수 있으니 순서 이야기는 빼고 그네가 재미있다고만 쓴다","mis":"K6-2-u5-X20"},{"t":"「안전 수칙 준수」처럼 짧고 어려운 말로 쓴다","mis":"K6-2-u5-X24"},{"t":"그림만 넣고 글은 쓰지 않는다","mis":"K6-2-u5-X23"}],"explanation":["까닭을 빼면 전하려는 것이 사라져요.","어려운 말은 닿지 않아요.","그림은 글을 돕는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#22','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C10',3,'mc','auto','이 단원의 약속 「표현 효과는 무엇을 돕는가로 본다」를 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-2-u5-X13','K6-2-u5-X15']::text[],false,'{"seq":22,"concept":"K6-2-u5-C10","difficulty":3,"kind":"mc","stem":"이 단원의 약속 「표현 효과는 무엇을 돕는가로 본다」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"이 자막은 낯선 낱말을 정확히 남기도록 돕는다","correct":true},{"t":"이 영상은 자막이 열 개라서 효과가 크다","mis":"K6-2-u5-X13"},{"t":"이 음악은 크니까 좋다","mis":"K6-2-u5-X15"},{"t":"이 장면은 그냥 멋있다","mis":"K6-2-u5-X15"}],"explanation":["개수로 재지 않아요.","크기나 멋은 까닭이 아니에요.","무엇을 돕는지로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#23','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C22',4,'mc','auto','준서의 편지를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X22','K6-2-u5-X36']::text[],false,'{"seq":23,"concept":"K6-2-u5-C22","difficulty":4,"kind":"mc","stem":"준서의 편지를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"받는 사람과 날짜 · 보내는 사람을 넣고, 높임말로 바꾸고, 「그거」를 콕 집어 밝히고, 김치 충고는 빼서 고마운 마음만 담는다","correct":true},{"t":"글씨를 더 크게 쓰고 편지지를 바꾼다","mis":"K6-2-u5-X22"},{"t":"「진짜」를 더 많이 넣어 고마움을 키운다","mis":"K6-2-u5-X36"},{"t":"모두 지우고 「고마워요」 한 줄만 쓴다","mis":"K6-2-u5-X36"}],"explanation":["빠진 부분을 채워요.","받는 사람에게 맞는 말로 바꿔요.","마음에 맞는 내용만 남겨요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#24','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C23',4,'essay','teacher','준서의 편지를 받는 사람과 전하려는 마음을 생각하며 다섯 부분을 갖추어 고쳐 쓰세요. 고마운 일은 그럴 법한 일을 하나 정해 콕 집어 쓰고, 날짜는 ○○월 ○○일로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u5-C23","difficulty":4,"kind":"essay","stem":"준서의 편지를 받는 사람과 전하려는 마음을 생각하며 다섯 부분을 갖추어 고쳐 쓰세요. 고마운 일은 그럴 법한 일을 하나 정해 콕 집어 쓰고, 날짜는 ○○월 ○○일로 쓰세요.","answer_guide":{"answer":"예: 할머니께 / 할머니, 그동안 건강하게 잘 지내셨어요? / 여름 방학 때 제가 자전거를 못 타서 속상해할 때 할머니께서 뒤에서 끝까지 잡아 주셔서 혼자 탈 수 있게 되었어요. 그때 「넘어져도 괜찮다」고 해 주신 말씀이 정말 고마웠어요. 겨울 방학에 또 찾아뵐게요. / 늘 건강하세요. / ○○월 ○○일 손자 준서 올림","scoring_points":["다섯 부분을 모두 갖추었는가","할머니께 알맞은 높임말을 썼는가","고마운 일을 콕 집고 충고를 빼 마음에 맞게 썼는가"]},"explanation":["빠진 부분을 채워요.","높임말로.","그 일을 콕 집어요."],"asset":{"type":"passage","lines":["안녕! 잘 지내지?","저번에 그거 진짜 고마웠어. 덕분에 다 잘됐어.","근데 할머니 김치는 좀 짰어. 다음엔 싱겁게 해.","방학 때 또 갈게. 그때 같이 그거 또 하자.","그럼 안녕."],"title":"준서가 할머니께 쓴 편지 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u5_review_d#25','kor',6,2,'u5','','g6_2_kor_u5_review_d','unit_review','K6-2-u5-C25',4,'essay','teacher','「붉다」, 「얇아요」, 「늙다」, 「짧아요」를 소리 나는 대로 쓰고, 왜 그렇게 소리 나는지 겹받침의 규칙으로 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u5-C25","difficulty":4,"kind":"essay","stem":"「붉다」, 「얇아요」, 「늙다」, 「짧아요」를 소리 나는 대로 쓰고, 왜 그렇게 소리 나는지 겹받침의 규칙으로 설명하세요.","answer_guide":{"answer":"예: 붉다 [북따], 얇아요 [얄바요], 늙다 [늑따], 짧아요 [짤바요]. 우리말은 받침에서 한 번에 한 소리만 낼 수 있어서, 붉다 · 늙다처럼 뒤에 자음자가 오면 겹받침 가운데 하나만 소리 난다. 얇아요 · 짧아요처럼 뒤에 모음이 오면 두 소리가 다 나고 뒤엣것인 ㅂ이 뒷글자로 넘어가 소리 난다.","scoring_points":["네 낱말을 바르게 썼는가","자음자 앞에서 하나만 나는 규칙을 썼는가","모음 앞에서 뒤엣것이 넘어가는 규칙을 썼는가"]},"explanation":["뒤에 무엇이 오나 봐요.","자음자 앞 하나.","모음 앞 둘, 뒤엣것이 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C1','kor',6,2,'u6',1,'경험을 글로 표현하면 좋은 점 — 그때 내 마음이 어땠는지 또렷하게 알게 되고, 말로는 잘 안 되던 것을 다른 사람에게 생생하게 전하며, 지나가 버릴 일이 오래 남는다 (글씨를 예쁘게 쓰거나 글을 길게 늘리는 것은 좋은 점이 아니다)',ARRAY['6국05 문학(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C2','kor',6,2,'u6',1,'날마다 겪는 작은 일도 글감 — 여행이나 대단한 일이 없어도 우유갑을 여느라 씨름한 일처럼 마음이 움직인 일이면 무엇이든 글감이 되며, 글감을 고르는 물음은 「그때 내 마음이 움직였는가」 하나다',ARRAY['6국05 문학(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C3','kor',6,2,'u6',1,'좋은 표현은 개수가 아니라 알맞음 — 빗댄 표현을 많이 넣거나 어려운 말을 쓸수록 좋은 시가 되는 것이 아니라 그 마음에 알맞은 표현이 좋은 표현이며, 빗댄 표현이 하나뿐이거나 하나도 없는 짧고 쉬운 시도 마음이 잘 전해지면 좋은 시다',ARRAY['6국05 문학(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C4','kor',6,2,'u6',1,'이야기의 세 요소 — 인물(이야기에 나오는 사람이나 대상)·배경(일이 일어난 때와 곳)·사건(이야기 속에서 일어난 일)이 모여 이야기가 되며, 셋은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직인다',ARRAY['6국05 문학(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C5','kor',6,2,'u6',2,'시가 담은 경험과 장면 떠올리기 — 말하는 이가 실제로 한 일을 찾아 시가 어떤 경험을 담았는지 알고, 장면을 머릿속에 그리며 읽으며, 빗댄 말(벌써 백 번은 미끄러졌다)은 실제로 일어난 일이 아니라 말하는 이의 마음(놓칠까 걱정함)을 나타낸 것으로 읽는다',ARRAY['6국05 문학(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C6','kor',6,2,'u6',2,'겪은 일을 시로 옮기는 일 — 겪은 일을 전부 쓰지 않고 인상 깊었던 부분만 고르고, 장면이 바뀔 때 연과 행을 나누고, 마음을 다른 사물이나 비슷한 상황에 빗대고, 본 것·들은 것·만진 것을 그대로 살린다',ARRAY['6국05 문학(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C7','kor',6,2,'u6',2,'비유적 표현과 빗댄 까닭 — 비슷한 점이 있는 두 대상을 이어 나타내는 것을 비유적 표현이라 하며, 빗댈 때에는 반드시 비슷한 점이 있어(아침 집 = 끓는 주전자: 바쁘고 뜨거운 기운 · 낮 집 = 빈 운동장: 텅 빔 · 저녁 집 = 난롯가: 따뜻하게 둘러앉음) 그 점을 말로 옮길 수 있어야 한다',ARRAY['6국05 문학(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C8','kor',6,2,'u6',2,'직유법과 은유법 — 직유법은 「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법(주전자처럼 끓는다)이고, 은유법은 「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법(낮 우리 집은 빈 운동장이다)이다',ARRAY['6국05 문학(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C9','kor',6,2,'u6',2,'감각적 표현 — 보고·듣고·맡고·만지고·맛본 것을 그대로 살려 쓴 표현으로(들은 것 — 김이 푹푹 · 본 것 — 시계 초침), 다른 것에 빗대는 비유적 표현과 달리 느낀 감각을 그대로 옮겨 장면을 생생하게 한다',ARRAY['6국05 문학(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C10','kor',6,2,'u6',2,'시의 특성은 규칙이 아니라 방법 — 연과 행으로 나누어 노래하는 듯한 리듬이 느껴지고, 생각이나 느낌을 짧은 글로 눌러 담으며, 비유적 표현과 감각적 표현으로 대상을 생생하게 나타내지만, 이 셋은 지켜야 할 규칙이 아니라 쓸 수 있는 방법이다',ARRAY['6국05 문학(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C11','kor',6,2,'u6',4,'시 쓰기 준비와 묻고 답하기 — 시로 쓸 경험 고르기 → 묻고 답하며 자세히 떠올리기 → 생각그물로 모으기 → 남길 것과 버릴 것 고르기의 차례로 준비하며, 「가장 기억에 남는 순간은? · 그때 본 것과 들은 것은? · 무엇에 빗댈 수 있을까? · 마음이 어떻게 움직였나?」처럼 그 경험 속으로 다시 들어가게 하는 물음이 기억을 또렷하게 한다',ARRAY['6국05 문학(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C12','kor',6,2,'u6',4,'생각그물로 갈래 나누어 모으기 — 가운데에 경험을 두고 둘레에 본 것(지나가는 줄)·들은 것(탁, 탁 소리)·만진 것(미끄러운 손잡이)·생각이나 느낌(드디어 되었다)·빗댈 것(떠 있는 몸 → 새)을 갈래별로 적어 두면 시로 옮기기 쉬워진다',ARRAY['6국05 문학(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C13','kor',6,2,'u6',4,'시는 넣는 일보다 버리는 일 — 생각그물을 다 넣으면 빠뜨린 것은 없어도 어느 순간이 중요한지 알 수 없는 목록이 되고, 인상 깊은 순간만 골라 남기면 그 마음이 또렷해진다 (짧아서 좋은 것이 아니라 고르고 버려서 또렷해진 것이다)',ARRAY['6국05 문학(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C14','kor',6,2,'u6',4,'마음이 드러나는 제목 — 제목은 겪은 일 그대로(줄넘기를 한 날)·가장 인상 깊은 것으로·빗댄 표현으로(백한 번째 새) 붙일 수 있고, 맨 처음에 붙여도 다 쓴 뒤에 붙여도 되지만 시를 읽고 나서 고개가 끄덕여지게 시에 담긴 마음이 드러나면 좋다',ARRAY['6국05 문학(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C15','kor',6,2,'u6',4,'시 고쳐 쓰기 — 다 쓴 시는 전하려던 마음이 드러나는가 · 장면이 바뀌는 곳에서 연이 나뉘었는가 · 없어도 되는 줄이 남아 있지 않은가 · 소리 내어 읽었을 때 걸리는 곳이 없는가를 보며 고치고, 고쳐 쓰기는 벌이 아니라 시를 자라게 하는 단계다 (빗댄 표현의 개수나 글씨 모양은 볼 것이 아니다)',ARRAY['6국03 쓰기(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C16','kor',6,2,'u6',6,'낭송 계획 — 마음에 맞는 목소리와 속도 — 듣는 사람에게 꼭 전하고 싶은 마음을 먼저 정하고, 그 마음에 맞게 부분마다 목소리와 속도를 정하며(숨을 참듯 낮고 느리게 · 또렷하고 빠르게 · 한 음절씩 힘을 실어 천천히), 여러 번 연습해 걸리는 곳을 고친다 — 목소리는 그 부분의 마음을 따라간다',ARRAY['6국01 듣기·말하기(초안)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C17','kor',6,2,'u6',6,'효과음 · 배경 음악 · 영상은 돕는 만큼 — 효과음은 시의 장면과 맞닿은 소리를 아주 짧게, 배경 음악은 시의 분위기와 어울리는 것을 낭송하는 목소리보다 작게, 영상이나 그림은 장면을 떠올리는 데 도움이 될 만큼만 쓰며, 셋 다 낭송을 돕는 것이지 대신하거나 덮는 것이 아니다',ARRAY['6국01 듣기·말하기(초안)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C18','kor',6,2,'u6',6,'낭송을 듣는 사람과 구체적인 조언 — 낭송회는 낭송하는 사람과 듣는 사람이 함께 만들어, 듣는 사람은 낭송하는 사람을 바라보며 시와 관련 있는 내 경험을 떠올리며 듣고, 끝난 뒤 「잘했어」가 아니라 어느 부분을 어떻게 하면 좋을지까지 말해 준다',ARRAY['6국01 듣기·말하기(초안)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C19','kor',6,2,'u6',6,'낭송을 잘한다는 것 — 들리지 않을 만큼 읽어도, 마음과 상관없이 무조건 크게 읽어도, 음악과 영상으로 화려하게 꾸며도 안 되고, 뒤에 앉은 사람까지 들릴 만큼 부분마다 마음에 맞는 크기로 읽어 멋있게 들리는 것이 아니라 그 시의 마음이 건너가게 하는 것이다',ARRAY['6국01 듣기·말하기(초안)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C20','kor',6,2,'u6',7,'패러디와 표절 — 널리 알려진 이야기를 원래 이야기를 밝히고 일부러 비틀어 바뀐 곳에서 새로운 뜻이 생기게 하는 것이 패러디이고, 남의 것을 그대로 옮기고 자기 것인 척해 새로운 뜻이 생기지 않는 것이 표절이다',ARRAY['6국05 문학(초안)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C21','kor',6,2,'u6',7,'성격이 바뀌면 하는 일이 바뀐다 — 「금도끼 은도끼」의 나무꾼은 제 것이 아닌 것을 제 것이라 하지 않고 주는 것을 고맙게 받지만, 「마르지 않는 샘」의 나무꾼은 받기 전에 마을에 무슨 일이 생길지 먼저 생각해 상을 거절하듯, 인물의 성격이 바뀌면 그 인물이 하는 일도 바뀐다',ARRAY['6국05 문학(초안)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C22','kor',6,2,'u6',7,'배경이 바뀌면 할 수 있는 일이 바뀐다 — 그저 「옛날」이던 때를 「몇 해째 비가 오지 않아 우물이 말라 가던 해」로 바꾸자 나무꾼이 물을 걱정하는 것이 자연스러워졌듯, 때와 곳을 바꾸면 인물이 할 수 있는 일과 일어날 사건이 함께 달라진다',ARRAY['6국05 문학(초안)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C23','kor',6,2,'u6',7,'앞의 일이 뒤의 일을 부른다 — 이야기는 바뀌어도 원인과 결과로 이어져야 해서(가뭄이 든 해였으므로 → 물을 먼저 걱정했고 → 그래서 상을 거절했고 → 그래서 샘이 생겼다) 이어 쓸 때에도 앞에서 생긴 일이 뒤의 일을 불러오게 쓴다',ARRAY['6국05 문학(초안)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C24','kor',6,2,'u6',7,'잘 바꾼 이야기는 많이 바꾼 이야기가 아니다 — 갑자기 우주선이 내려오는 것처럼 놀랍기만 하고 앞의 일과 이어지지 않는 바꾸기는 잘 바꾼 것이 아니며, 바꾸어 쓰기는 기발한 생각을 얼마나 많이 넣었는가가 아니라 바뀐 것에 따라 뒤가 자연스럽게 이어지는가로 가늠한다',ARRAY['6국05 문학(초안)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C25','kor',6,2,'u6',7,'바꾸어 쓸 때 생각할 점과 경험 — 인물을 어떤 성격으로 · 때와 곳을 어떻게 바꿀지 · 앞의 일이 뒤의 일을 부르는지 · 내가 잘 아는 경험을 살릴 수 있는지를 생각하며, 경험을 바탕으로 쓴 이야기는 실제로 있었던 일만 적는 일기와 달리 겪은 일에서 출발하되 인물·배경·사건을 지어낸다 (겪어 본 것에서 출발하면 더 자세히 쓸 수 있다)',ARRAY['6국05 문학(초안)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C26','kor',6,2,'u6',9,'바꾸어 쓰면 새로운 뜻이 생긴다 — 「정직하면 상을 받는다」던 이야기가 상을 거절하고 마을에 샘이 생기는 이야기로 바뀌면 「정직함은 나 혼자의 일이 아니다」라는 새로운 뜻이 생기며, 그것이 이야기를 바꾸어 쓰는 까닭이다',ARRAY['6국05 문학(초안)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C27','kor',6,2,'u6',9,'인물의 성격과 사건의 차례 정리하기 — 인물의 성격은 그 인물이 한 말과 행동에서 드러나고(놀라지 않은 척 둘러대는 토끼 · 혼자 뭍까지 올라간 자라 · 들은 말을 그대로 믿는 용왕), 사건은 보통 발단(일이 시작됨)·전개(일이 커짐)·절정(가장 긴장되는 순간)을 거쳐 마지막에 일이 마무리되는 차례로 흘러가므로, 바꾸기 전에 이 둘을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보인다',ARRAY['6국05 문학(초안)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C28','kor',6,2,'u6',9,'바꾸기 계획 — 하나를 바꾸면 함께 손볼 곳 — 인물·배경·사건 가운데 하나만 골라 바꾸어도 충분하며(나머지가 따라 움직이므로), 바꿀 것 · 그 때문에 달라지는 것 · 그대로 둘 것을 적고, 성격을 바꾸었으면 행동도 함께 바꾸어야 한다 (자라가 따져 보는 성격이 되면 토끼에게 하는 말 · 토끼의 행동 · 이야기의 끝이 함께 바뀐다)',ARRAY['6국05 문학(초안)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C29','kor',6,2,'u6',9,'바꾼 이야기의 첫 문장과 제목 — 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 읽는 사람이 금방 알아채고, 제목은 새로 바꾼 인물의 성격·배경·사건이 드러나게 붙이며(「자라가 입을 열었다」), 맨 처음에 붙여도 다 쓴 뒤에 붙여도 된다',ARRAY['6국05 문학(초안)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C30','kor',6,2,'u6',9,'칭찬 쪽지 — 어느 부분이 왜 — 글은 읽어 주는 사람이 있을 때 완성되며, 친구의 이야기를 읽고 「잘 썼어 · 재미있어」에서 멈추지 않고 어느 부분이 좋았는지 짚고 왜 좋았는지 까닭을 붙여 쓴다 (글씨처럼 이야기와 상관없는 겉모습만 칭찬하지 않는다)',ARRAY['6국05 문학(초안)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C31','kor',6,2,'u6',12,'책의 형태와 독자 — 종이책(교실에 두고 아무 때나 넘겨 봄)·소리로 담는 책(낭송의 목소리와 속도를 그대로 남김)·화면으로 보는 책(멀리 있는 사람에게도 보냄)은 더 나은 것 없이 알맞은 자리가 서로 다를 뿐이고, 누가 읽을지와 무엇을 전하고 싶은지를 먼저 정하면 형태가 따라 정해진다',ARRAY['6국03 쓰기(초안)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C32','kor',6,2,'u6',12,'실을 글을 쓰기 전에 정할 것 — 중심 사건 · 등장인물의 이름과 성격 · 일이 일어난 때와 곳 · 사건이 이어지는 차례를 정해 두면 글이 빨리 써지며, 겪은 일에서 출발하되 일기를 옮겨 적는 것이 아니라 인물과 배경을 지어내도 된다 (표지 색이나 글자 수는 먼저 정할 것이 아니다)',ARRAY['6국03 쓰기(초안)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C33','kor',6,2,'u6',12,'꾸미기가 이야기를 덮지 않게 함께 만들기 — 이야기를 먼저 완성하고 꾸미기는 읽기 좋게 돕는 만큼만 하며, 함께 만들 때에는 누구와 · 무엇을 맡을지 · 언제까지를 정하고 다 만든 뒤 글에서 잘한 점부터 이야기한다 — 목적은 멋진 결과물이 아니라 쓰고 나누는 즐거움을 겪어 보는 것',ARRAY['6국03 쓰기(초안)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u6-C34','kor',6,2,'u6',12,'소리가 같고 뜻이 다른 낱말 — 읽을 때 소리는 같지만 쓰는 글자와 뜻이 다른 낱말(바치다 = 웃어른께 정중히 올리다 · 받치다 = 밑에서 괴어 기울지 않게 하다 / 메다 = 어깨에 걸쳐 지다 · 매다 = 끈이나 줄을 묶다 / 부치다 = 편지나 물건을 보내다 · 붙이다 = 맞닿아 떨어지지 않게 하다)은 앞뒤 문장을 보고 쓰이는 자리에 맞게 골라 쓴다 (기초 다지기)',ARRAY['6국04 문법(초안)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X01','kor',6,'u6',ARRAY['K6-2-u6-C1']::text[],'경험을 글로 쓰는 좋은 점을 글씨를 예쁘게 쓰기 · 글을 길게 늘리기 같은 겉모습에서 찾는다','나에게, 읽는 사람에게 무엇이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X02','kor',6,'u6',ARRAY['K6-2-u6-C2','K6-2-u6-C25']::text[],'여행이나 대단한 일을 겪어야 글감이 된다고 여겨, 날마다 겪는 작은 일을 글감으로 보지 않는다','그때 마음이 움직였는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X03','kor',6,'u6',ARRAY['K6-2-u6-C3','K6-2-u6-C7','K6-2-u6-C10']::text[],'빗댄 표현을 많이 넣을수록 좋은 시라고 여긴다','개수가 아니라 그 마음에 알맞은가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X04','kor',6,'u6',ARRAY['K6-2-u6-C3','K6-2-u6-C10']::text[],'어렵고 멋있어 보이는 말을 쓸수록 좋은 시라고 여긴다','짧고 쉬운 말도 좋은 시가 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X05','kor',6,'u6',ARRAY['K6-2-u6-C4','K6-2-u6-C27']::text[],'인물 · 배경 · 사건의 뜻을 서로 헷갈린다','누가 · 언제 어디서 · 무슨 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X06','kor',6,'u6',ARRAY['K6-2-u6-C4','K6-2-u6-C21','K6-2-u6-C22']::text[],'이야기의 세 요소가 따로 움직인다고 여겨, 하나를 바꾸어도 나머지는 그대로라고 생각한다','하나를 바꾸면 나머지도 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X07','kor',6,'u6',ARRAY['K6-2-u6-C5']::text[],'시가 담은 경험을 말하는 이가 실제로 한 일에서 찾지 않고 시에 없는 사건으로 짐작한다','말하는 이가 실제로 한 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X08','kor',6,'u6',ARRAY['K6-2-u6-C5','K6-2-u6-C7']::text[],'빗댄 말을 실제로 일어난 일로 읽어, 그 말이 나타낸 마음을 놓친다','실제 일인가, 마음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X09','kor',6,'u6',ARRAY['K6-2-u6-C6','K6-2-u6-C13']::text[],'겪은 일을 시로 옮길 때 하나도 빠뜨리지 않고 차례대로 다 적어야 한다고 여긴다','인상 깊은 부분만 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X10','kor',6,'u6',ARRAY['K6-2-u6-C7']::text[],'빗댄 두 대상 사이의 비슷한 점을 찾지 못하거나, 비슷한 점이 없는 것끼리 아무렇게나 빗댄다','어떤 점에서 닮았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X11','kor',6,'u6',ARRAY['K6-2-u6-C8']::text[],'직유법과 은유법을 서로 헷갈린다','「처럼 · 같이 · 듯이」가 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X12','kor',6,'u6',ARRAY['K6-2-u6-C9','K6-2-u6-C12']::text[],'감각적 표현과 비유적 표현을 헷갈리거나, 본 것 · 들은 것 · 만진 것을 갈래대로 가르지 못한다','느낀 그대로? 다른 것에 빗댐?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X13','kor',6,'u6',ARRAY['K6-2-u6-C10','K6-2-u6-C3']::text[],'연과 행 · 비유 같은 시의 특성을 꼭 지켜야 할 규칙으로 여겨, 빗댄 표현이 없으면 시가 아니라고 생각한다','규칙이 아니라 쓸 수 있는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X14','kor',6,'u6',ARRAY['K6-2-u6-C6','K6-2-u6-C15']::text[],'장면이 바뀌어도 연을 나누지 않거나, 장면과 상관없이 아무 데서나 연과 행을 나눈다','장면이 바뀌는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X15','kor',6,'u6',ARRAY['K6-2-u6-C11']::text[],'경험을 자세히 떠올리는 물음 대신 몇 시 몇 분 · 몇 줄로 쓸지 같은 겉 물음을 고른다','그 경험 속으로 다시 들어가게 하는 물음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X16','kor',6,'u6',ARRAY['K6-2-u6-C12','K6-2-u6-C13']::text[],'생각그물에 모은 것을 다 넣어야 빠짐없는 좋은 시가 된다고 여긴다','넣는 일보다 버리는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X17','kor',6,'u6',ARRAY['K6-2-u6-C13']::text[],'고른 시가 더 나은 까닭을 「짧아서 · 빗댄 표현이 많아서」로 여겨, 고르고 버려서 마음이 또렷해진 것을 보지 못한다','읽고 나서 무엇이 남나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X18','kor',6,'u6',ARRAY['K6-2-u6-C14','K6-2-u6-C29']::text[],'제목을 담긴 마음이나 바뀐 것과 상관없이 붙이거나, 제목은 반드시 맨 처음에 정해야 한다고 여긴다','읽고 나서 고개가 끄덕여지는 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X19','kor',6,'u6',ARRAY['K6-2-u6-C15']::text[],'시를 고쳐 쓸 때 빗댄 표현의 개수나 글씨 모양 같은 겉모습을 보거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','전하려던 마음 · 연 · 없어도 되는 줄 · 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X20','kor',6,'u6',ARRAY['K6-2-u6-C16']::text[],'전할 마음을 정하지 않고 낭송하거나, 시의 모든 부분을 같은 목소리와 속도로 읽는다','목소리는 그 부분의 마음을 따라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X21','kor',6,'u6',ARRAY['K6-2-u6-C19','K6-2-u6-C16']::text[],'낭송을 잘한다는 것을 마음과 상관없이 무조건 크게 읽는 것으로 여긴다','크게가 아니라 마음에 맞는 크기로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X22','kor',6,'u6',ARRAY['K6-2-u6-C17','K6-2-u6-C19']::text[],'효과음 · 배경 음악 · 영상을 많이, 크게, 화려하게 쓸수록 낭송이 좋아진다고 여긴다','돕는 만큼만, 목소리보다 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X23','kor',6,'u6',ARRAY['K6-2-u6-C19']::text[],'마음만 담으면 들리지 않을 만큼 작게 읽어도 괜찮다고 여긴다','뒤에 앉은 사람까지 들리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X24','kor',6,'u6',ARRAY['K6-2-u6-C18']::text[],'친구의 낭송을 들을 때 옆 친구와 이야기하거나 틀린 글자만 찾는 것을 잘 듣는 것으로 여긴다','바라보며, 내 경험을 떠올리며') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X25','kor',6,'u6',ARRAY['K6-2-u6-C18','K6-2-u6-C30']::text[],'조언이나 칭찬을 「잘했어 · 재미있어」처럼 어느 부분이 왜 그런지 없이 막연하게 하거나, 글씨 같은 겉모습만 칭찬한다','어느 부분을 · 왜 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X26','kor',6,'u6',ARRAY['K6-2-u6-C20']::text[],'패러디와 표절을 같은 것으로 여기거나, 원래 이야기를 밝히지 않고 그대로 옮겨도 패러디라고 생각한다','밝히고 일부러 바꾸어 새 뜻이 생기나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X27','kor',6,'u6',ARRAY['K6-2-u6-C21','K6-2-u6-C28']::text[],'인물의 성격을 바꾸어 놓고 그 인물의 말과 행동은 그대로 둔다','성격이 바뀌면 하는 일도 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X28','kor',6,'u6',ARRAY['K6-2-u6-C22']::text[],'배경을 바꾼 것이 인물이 할 수 있는 일이나 사건과 어떻게 이어지는지 보지 못한다','그 때와 곳이라서 할 수 있는 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X29','kor',6,'u6',ARRAY['K6-2-u6-C23','K6-2-u6-C24']::text[],'앞의 일과 이어지지 않는 갑작스러운 사건(하늘에서 우주선이 내려옴 · 갑자기 병이 나음)을 이어 쓴다','앞의 일이 뒤의 일을 부르나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X30','kor',6,'u6',ARRAY['K6-2-u6-C24']::text[],'많이 · 놀랍게 · 기발하게 바꿀수록 잘 바꾼 이야기라고 여긴다','놀라움이 아니라 이어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X31','kor',6,'u6',ARRAY['K6-2-u6-C25','K6-2-u6-C32']::text[],'경험을 바탕으로 쓴 이야기를 일기처럼 겪은 일 그대로만 써야 한다고 여기거나, 반대로 일기에 지어낸 일을 적어도 된다고 여긴다','일기는 사실, 이야기는 지어냄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X32','kor',6,'u6',ARRAY['K6-2-u6-C26']::text[],'이야기를 바꾸어 쓰는 까닭을 글을 길게 늘리기나 재미만으로 여겨, 바뀐 곳에서 새로운 뜻이 생기는 것을 모른다','바꾸면 무엇이 생기나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X33','kor',6,'u6',ARRAY['K6-2-u6-C27']::text[],'인물의 성격을 그 인물이 한 말과 행동과 잇지 못한다','그 인물이 실제로 한 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X34','kor',6,'u6',ARRAY['K6-2-u6-C27']::text[],'발단 · 전개 · 절정의 차례와 각 단계에서 일어나는 일을 헷갈린다','시작 · 커짐 · 가장 긴장되는 순간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X35','kor',6,'u6',ARRAY['K6-2-u6-C28']::text[],'하나를 바꾸어도 다른 곳은 손볼 필요가 없다고 여기거나, 이야기와 상관없는 글자 수 · 공간 같은 것을 손볼 곳으로 고른다','바꾼 것에 닿아 있던 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X36','kor',6,'u6',ARRAY['K6-2-u6-C28','K6-2-u6-C24']::text[],'인물 · 배경 · 사건을 모두 한꺼번에 바꾸어야 제대로 바꾼 것이라고 여긴다','하나만 바꾸어도 충분해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X37','kor',6,'u6',ARRAY['K6-2-u6-C29']::text[],'바꾼 이야기의 첫 문장을 바뀐 것과 상관없이 원래 이야기 그대로 시작해, 읽는 사람이 무엇이 바뀌었는지 알아채기 어렵게 한다','바뀐 것이 드러나는 곳에서 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X38','kor',6,'u6',ARRAY['K6-2-u6-C31']::text[],'책의 형태에 등수를 매기거나, 가장 새롭고 멋있어 보이는 형태 · 가장 빨리 끝나는 형태를 고른다','더 나은 형태는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X39','kor',6,'u6',ARRAY['K6-2-u6-C31']::text[],'누가 읽을지와 무엇을 전하고 싶은지를 정하지 않고 책의 형태부터 고른다','독자가 정해지면 형태가 따라와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X40','kor',6,'u6',ARRAY['K6-2-u6-C32']::text[],'글을 쓰기 전에 정할 것을 표지 색깔 · 글자 수 같은 겉모습에서 찾는다','중심 사건 · 인물 · 때와 곳 · 차례') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X41','kor',6,'u6',ARRAY['K6-2-u6-C33']::text[],'표지와 그림이 화려한 것을 잘한 것으로 여겨 꾸미기에 시간을 다 쓰고 글은 급히 쓴다','이야기가 먼저, 꾸미기는 돕는 만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X42','kor',6,'u6',ARRAY['K6-2-u6-C33']::text[],'함께 만들 때 누가 무엇을 언제까지 맡을지 정하지 않거나, 다 만든 뒤 잘한 점이 아니라 고칠 점부터 말한다','누구와 · 무엇을 · 언제까지 · 잘한 점부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u6-X43','kor',6,'u6',ARRAY['K6-2-u6-C34']::text[],'소리가 같은 낱말(바치다 · 받치다, 메다 · 매다, 부치다 · 붙이다)을 앞뒤 문장의 뜻과 상관없이 섞어 쓴다','앞뒤 문장을 보고 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#1','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C5',1,'mc','auto','시 「우유갑」은 어떤 경험을 시로 표현했나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C5","difficulty":1,"kind":"mc","stem":"시 「우유갑」은 어떤 경험을 시로 표현했나요?","options":[{"t":"급식 우유갑을 여느라 애쓴 경험","correct":true},{"t":"아침에 늦잠을 자 학교에 뛰어간 경험","mis":"K6-2-u6-X07"},{"t":"집 대문이 고장 나 고쳐 본 경험","mis":"K6-2-u6-X07"},{"t":"우유를 쏟아 옷을 버린 경험","mis":"K6-2-u6-X07"}],"explanation":["말하는 이가 실제로 한 일을 찾아요.","손톱으로 모서리를 톡, 톡 두드렸어요.","우유갑을 여는 작은 경험이 시가 되었어요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#2','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',1,'match','auto','이야기의 요소와 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C4","difficulty":1,"kind":"match","stem":"이야기의 요소와 알맞은 설명을 이으세요.","pairs":[{"l":"인물","r":"이야기에 나오는 사람이나 대상"},{"l":"배경","r":"일이 일어난 때와 곳"},{"l":"사건","r":"이야기 속에서 일어난 일"}],"mis":"K6-2-u6-X05","explanation":["누가 나오는지가 인물이에요.","언제 어디인지가 배경이에요.","무슨 일이 일어나는지가 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#3','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C2',1,'ox','auto','대단한 일을 겪어야만 시의 글감이 될 수 있어요.',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":3,"concept":"K6-2-u6-C2","difficulty":1,"kind":"ox","stem":"대단한 일을 겪어야만 시의 글감이 될 수 있어요.","answer":"X","reason_options":[{"t":"마음이 움직인 일이면 작은 일도 글감이 되기 때문에","correct":true},{"t":"특별한 일이어야 읽는 사람이 놀라기 때문에","mis":"K6-2-u6-X02"}],"mis":"K6-2-u6-X02","explanation":["우유갑 하나도 시가 되었어요.","글감을 고르는 물음은 하나예요.","그때 내 마음이 움직였는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#4','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',1,'mc','auto','「비가 오지 않던 해, 산속 연못」은 이야기의 세 요소 가운데 무엇인가요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":4,"concept":"K6-2-u6-C4","difficulty":1,"kind":"mc","stem":"「비가 오지 않던 해, 산속 연못」은 이야기의 세 요소 가운데 무엇인가요?","options":[{"t":"배경","correct":true},{"t":"인물","mis":"K6-2-u6-X05"},{"t":"사건","mis":"K6-2-u6-X05"},{"t":"제목","mis":"K6-2-u6-X05"}],"explanation":["때와 곳이 들어 있어요.","일이 일어난 때와 곳은 배경이에요.","인물은 누가, 사건은 무슨 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#5','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C1',2,'mc','auto','경험을 시나 이야기로 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X04']::text[],false,'{"seq":5,"concept":"K6-2-u6-C1","difficulty":2,"kind":"mc","stem":"경험을 시나 이야기로 표현하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"그때 내 마음이 어땠는지 또렷하게 알게 된다","correct":true},{"t":"글씨를 예쁘게 쓰는 법을 익힌다","mis":"K6-2-u6-X01"},{"t":"글의 길이를 길게 늘릴 수 있다","mis":"K6-2-u6-X01"},{"t":"어려운 낱말을 많이 외우게 된다","mis":"K6-2-u6-X04"}],"explanation":["글씨와 길이는 겉모습이에요.","쓰는 동안 내 마음이 정리돼요.","읽는 사람에게도 생생하게 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#6','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C3',2,'mc','auto','이 단원의 약속으로 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":6,"concept":"K6-2-u6-C3","difficulty":2,"kind":"mc","stem":"이 단원의 약속으로 알맞게 말한 것은 어느 것인가요?","options":[{"t":"빗댄 표현은 그 마음에 알맞을 때 힘이 있다","correct":true},{"t":"빗댄 표현이 많은 시가 언제나 더 좋은 시다","mis":"K6-2-u6-X03"},{"t":"어려운 말을 쓸수록 좋은 시다","mis":"K6-2-u6-X04"},{"t":"특별한 일을 겪은 사람만 시를 쓸 수 있다","mis":"K6-2-u6-X02"}],"explanation":["「우유갑」에는 빗댄 표현이 하나뿐이에요.","그래도 마음이 잘 전해져요.","개수가 아니라 알맞음이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#7','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C5',2,'mc','auto','「우유갑」의 말하는 이가 「꼭 이만큼만 열렸으면」 하고 바라는 것은 무엇인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":7,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「우유갑」의 말하는 이가 「꼭 이만큼만 열렸으면」 하고 바라는 것은 무엇인가요?","options":[{"t":"엄마한테 삐친 자기 마음","correct":true},{"t":"우유갑의 작은 문","mis":"K6-2-u6-X08"},{"t":"교실의 창문","mis":"K6-2-u6-X07"},{"t":"엄마가 닫아 둔 대문","mis":"K6-2-u6-X07"}],"explanation":["우유갑이 겨우 열린 모습을 보았어요.","그 모습에 삐친 마음을 견주었어요.","마음도 조금은 풀리기를 바란 거예요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#8','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C4',2,'ox','auto','이야기에서 인물을 바꾸면 사건도 함께 달라질 수 있어요.',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":8,"concept":"K6-2-u6-C4","difficulty":2,"kind":"ox","stem":"이야기에서 인물을 바꾸면 사건도 함께 달라질 수 있어요.","answer":"O","reason_options":[{"t":"세 요소는 서로 붙어 있어 하나를 바꾸면 나머지도 움직이기 때문에","correct":true},{"t":"세 요소는 따로따로라서 바꾸어도 상관없기 때문에","mis":"K6-2-u6-X06"}],"mis":"K6-2-u6-X06","explanation":["겁 많은 나무꾼과 용감한 나무꾼은 하는 일이 달라요.","하는 일이 달라지면 사건이 달라져요.","셋은 서로 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#9','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C2',2,'error','auto','글감에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":9,"concept":"K6-2-u6-C2","difficulty":2,"kind":"error","stem":"글감에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지오 — 「나는 여행도 안 갔고 특별한 일도 없어서 쓸 게 없어.」","correct":true,"mis_target":"K6-2-u6-X02"},{"t":"채아 — 「우유갑이 안 열려 씨름했던 일도 글감이야.」","mis":"K6-2-u6-X02"},{"t":"세윤 — 「마음이 움직인 일이면 뭐든 돼.」","mis":"K6-2-u6-X02"}],"explanation":["채아와 세윤은 바르게 말했어요.","지오는 대단한 일만 글감이라고 여겼어요.","날마다 겪는 작은 일도 글감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_basic#10','kor',6,2,'u6','L01','g6_2_kor_u6_L01_basic','lesson_basic','K6-2-u6-C3',3,'mc','auto','「우유갑」을 두고 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":3,"kind":"mc","stem":"「우유갑」을 두고 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빗댄 표현이 하나뿐이지만 삐친 마음이 잘 전해진다","correct":true},{"t":"빗댄 표현이 하나뿐이라 좋은 시라고 할 수 없다","mis":"K6-2-u6-X03"},{"t":"어려운 말이 없어 시답지 않다","mis":"K6-2-u6-X04"},{"t":"우유갑은 대단한 일이 아니라 글감이 되지 않는다","mis":"K6-2-u6-X02"}],"explanation":["빗댄 표현의 개수로 시를 재지 않아요.","짧고 쉬운 말도 좋은 시가 돼요.","그 마음에 알맞으면 힘이 있어요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#1','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C4',2,'mc','auto','「도끼를 물에 빠뜨렸다」는 이야기의 세 요소 가운데 무엇인가요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":1,"concept":"K6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「도끼를 물에 빠뜨렸다」는 이야기의 세 요소 가운데 무엇인가요?","options":[{"t":"사건","correct":true},{"t":"인물","mis":"K6-2-u6-X05"},{"t":"배경","mis":"K6-2-u6-X05"},{"t":"주제","mis":"K6-2-u6-X05"}],"explanation":["누가 나오는지는 인물이에요.","때와 곳은 배경이에요.","일어난 일은 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#2','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',2,'mc','auto','「우유갑」에서 경험을 시로 쓴 덕분에 읽는 사람에게까지 전해진 것은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X01']::text[],false,'{"seq":2,"concept":"K6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「우유갑」에서 경험을 시로 쓴 덕분에 읽는 사람에게까지 전해진 것은 무엇인가요?","options":[{"t":"우유갑을 여는 모습과 함께 삐친 마음","correct":true},{"t":"우유갑을 만든 회사 이름","mis":"K6-2-u6-X07"},{"t":"시를 쓴 날의 날씨","mis":"K6-2-u6-X07"},{"t":"글씨를 쓴 모양","mis":"K6-2-u6-X01"}],"explanation":["우유갑 하나로 장면이 떠올라요.","삐친 마음까지 함께 전해져요.","말로 하기 어려운 것을 전할 수 있어요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#3','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C2',3,'mc','auto','지오가 「쓸 게 없다」고 할 때 글감을 찾도록 돕는 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X15']::text[],false,'{"seq":3,"concept":"K6-2-u6-C2","difficulty":3,"kind":"mc","stem":"지오가 「쓸 게 없다」고 할 때 글감을 찾도록 돕는 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「오늘 마음이 조금이라도 움직인 일이 있었어?」","correct":true},{"t":"「이번 방학에 어디로 여행 갔어?」","mis":"K6-2-u6-X02"},{"t":"「남들이 놀랄 만한 일을 겪은 적 있어?」","mis":"K6-2-u6-X02"},{"t":"「시를 몇 줄로 쓸 거야?」","mis":"K6-2-u6-X15"}],"explanation":["여행이나 놀랄 일을 물으면 글감이 줄어들어요.","줄 수는 글감과 상관없어요.","마음이 움직였는지를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#4','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',3,'ox','auto','빗댄 표현이 다섯 개 넘게 들어간 시가 하나만 들어간 시보다 언제나 더 좋아요.',ARRAY['K6-2-u6-X03']::text[],false,'{"seq":4,"concept":"K6-2-u6-C3","difficulty":3,"kind":"ox","stem":"빗댄 표현이 다섯 개 넘게 들어간 시가 하나만 들어간 시보다 언제나 더 좋아요.","answer":"X","reason_options":[{"t":"표현은 개수가 아니라 그 마음에 알맞은지로 고르기 때문에","correct":true},{"t":"빗댄 표현이 많을수록 시가 화려해지기 때문에","mis":"K6-2-u6-X03"}],"mis":"K6-2-u6-X03","explanation":["많이 넣는다고 마음이 더 잘 전해지지 않아요.","알맞지 않은 표현은 오히려 흐리게 해요.","그 마음에 알맞은지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#5','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C4',3,'match','auto','이야기 속 내용과 요소를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C4","difficulty":3,"kind":"match","stem":"이야기 속 내용과 요소를 알맞게 이으세요.","pairs":[{"l":"겁이 많은 나무꾼","r":"인물"},{"l":"비가 오지 않던 해, 산속 연못","r":"배경"},{"l":"도끼를 물에 빠뜨렸다","r":"사건"}],"mis":"K6-2-u6-X05","explanation":["나무꾼은 이야기에 나오는 사람이에요.","해와 연못은 때와 곳이에요.","빠뜨린 일은 사건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#6','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',3,'error','auto','좋은 시에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X04','K6-2-u6-X03']::text[],false,'{"seq":6,"concept":"K6-2-u6-C3","difficulty":3,"kind":"error","stem":"좋은 시에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준하 — 「어려운 말을 많이 써야 시가 멋있어져.」","correct":true,"mis_target":"K6-2-u6-X04"},{"t":"하진 — 「짧고 쉬운 말로도 마음이 잘 전해질 수 있어.」","mis":"K6-2-u6-X04"},{"t":"세윤 — 「그 마음에 알맞은 표현이면 좋은 표현이야.」","mis":"K6-2-u6-X03"}],"explanation":["하진과 세윤은 바르게 말했어요.","준하는 어려운 말을 좋은 시의 기준으로 삼았어요.","알맞음이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#7','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C1',3,'mc','auto','경험을 글로 남기면 「지나가 버릴 일이 오래 남는다」는 것은 어떤 뜻인가요?',ARRAY['K6-2-u6-X01']::text[],false,'{"seq":7,"concept":"K6-2-u6-C1","difficulty":3,"kind":"mc","stem":"경험을 글로 남기면 「지나가 버릴 일이 오래 남는다」는 것은 어떤 뜻인가요?","options":[{"t":"글로 적어 두면 그때의 일과 마음을 나중에도 다시 만날 수 있다","correct":true},{"t":"글로 적으면 그 일이 실제로 다시 일어난다","mis":"K6-2-u6-X01"},{"t":"글로 적은 일은 잊어버려도 괜찮다","mis":"K6-2-u6-X01"},{"t":"글을 길게 쓸수록 오래 기억된다","mis":"K6-2-u6-X01"}],"explanation":["일은 지나가도 글은 남아요.","다시 읽으면 그때 마음을 만나요.","길이와는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#8','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C4',4,'mc','auto','「겁이 많은 나무꾼」을 「겁이 없는 나무꾼」으로 바꾸면 어떤 일이 생길지 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":8,"concept":"K6-2-u6-C4","difficulty":4,"kind":"mc","stem":"「겁이 많은 나무꾼」을 「겁이 없는 나무꾼」으로 바꾸면 어떤 일이 생길지 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"나무꾼이 연못 앞에서 하는 말과 행동이 달라져 사건도 함께 바뀐다","correct":true},{"t":"인물만 바뀌고 사건과 배경은 그대로 둔다","mis":"K6-2-u6-X06"},{"t":"이야기의 제목만 바뀐다","mis":"K6-2-u6-X06"},{"t":"인물을 바꾸면 이야기가 이어질 수 없다","mis":"K6-2-u6-X06"}],"explanation":["성격이 바뀌면 하는 일이 바뀌어요.","하는 일이 바뀌면 사건이 바뀌어요.","셋은 서로 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#9','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C2',4,'essay','teacher','오늘 하루 가운데 마음이 조금이라도 움직인 작은 일을 하나 골라, 그 일이 왜 시의 글감이 될 수 있는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C2","difficulty":4,"kind":"essay","stem":"오늘 하루 가운데 마음이 조금이라도 움직인 작은 일을 하나 골라, 그 일이 왜 시의 글감이 될 수 있는지 쓰세요.","answer_guide":{"answer":"예: 아침에 신발 끈이 자꾸 풀려서 세 번이나 다시 맨 일. 아주 작은 일이지만 늦을까 봐 조마조마하고 짜증이 났던 마음이 또렷하게 기억난다. 글감은 대단한 일이 아니라 그때 내 마음이 움직였는가로 고르기 때문에, 이 일도 시의 글감이 될 수 있다.","scoring_points":["날마다 겪는 작은 일을 하나 골랐는가","그때 움직인 마음을 썼는가","「마음이 움직였는가」를 까닭으로 썼는가"]},"explanation":["작은 일이어도 좋아요.","그때 마음을 떠올려요.","마음이 움직였는가가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L01_challenge#10','kor',6,2,'u6','L01','g6_2_kor_u6_L01_challenge','lesson_challenge','K6-2-u6-C3',4,'essay','teacher','「빗댄 표현을 많이 넣을수록 좋은 시다.」라는 말이 왜 알맞지 않은지 「우유갑」을 예로 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":4,"kind":"essay","stem":"「빗댄 표현을 많이 넣을수록 좋은 시다.」라는 말이 왜 알맞지 않은지 「우유갑」을 예로 들어 쓰세요.","answer_guide":{"answer":"예: 「우유갑」에는 우유갑이 겨우 열린 모습에 삐친 마음을 견준 빗댄 표현이 딱 하나뿐이다. 그런데도 엄마한테 삐친 마음이 조금은 풀렸으면 하는 마음이 잘 전해진다. 좋은 표현은 개수가 아니라 그 마음에 알맞은지로 정해지기 때문에, 많이 넣는다고 좋은 시가 되는 것은 아니다.","scoring_points":["「우유갑」의 빗댄 표현이 하나뿐임을 썼는가","그런데도 마음이 전해진다고 썼는가","개수가 아니라 알맞음이 기준이라고 썼는가"]},"explanation":["빗댄 표현의 수를 세어 봐요.","마음이 전해지는지 봐요.","알맞음이 기준이에요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#1','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C5',1,'mc','auto','시 「바통」은 어떤 경험을 담았나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C5","difficulty":1,"kind":"mc","stem":"시 「바통」은 어떤 경험을 담았나요?","options":[{"t":"이어달리기에서 바통을 받기까지 기다린 경험","correct":true},{"t":"이어달리기에서 일 등을 한 경험","mis":"K6-2-u6-X07"},{"t":"달리다가 넘어져 다친 경험","mis":"K6-2-u6-X07"},{"t":"바통을 잃어버려 찾은 경험","mis":"K6-2-u6-X07"}],"explanation":["말하는 이는 아직 달리지 않았어요.","앞 주자를 기다리고 있어요.","짧은 기다림이 시 한 편이 되었어요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#2','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C7',1,'sa','auto','비슷한 점이 있는 두 대상을 이어 나타내는 것을 무엇이라고 하나요? 여섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u6-C7","difficulty":1,"kind":"sa","stem":"비슷한 점이 있는 두 대상을 이어 나타내는 것을 무엇이라고 하나요? 여섯 글자로 쓰세요.","answer":["비유적표현","비유적 표현"],"explanation":["다른 것에 빗대어 나타내요.","두 대상 사이에는 비슷한 점이 있어요.","이것을 비유적 표현이라고 해요."],"mis":"K6-2-u6-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#3','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C8',1,'mc','auto','「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법은 무엇인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12','K6-2-u6-X14']::text[],false,'{"seq":3,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"「같이 · 처럼 · 듯이」를 써서 두 대상을 바로 견주는 방법은 무엇인가요?","options":[{"t":"직유법","correct":true},{"t":"은유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"},{"t":"연 나누기","mis":"K6-2-u6-X14"}],"explanation":["「처럼」이 들어 있으면 직유법이에요.","「무엇은 무엇이다」는 은유법이에요.","주전자처럼 끓는다가 직유법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#4','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C9',1,'ox','auto','「김이 푹푹 난다」는 들은 것을 그대로 살린 감각적 표현이에요.',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C9","difficulty":1,"kind":"ox","stem":"「김이 푹푹 난다」는 들은 것을 그대로 살린 감각적 표현이에요.","answer":"O","reason_options":[{"t":"귀로 들은 소리를 그대로 옮겼기 때문에","correct":true},{"t":"다른 대상에 빗대어 나타냈기 때문에","mis":"K6-2-u6-X12"}],"mis":"K6-2-u6-X12","explanation":["푹푹은 김이 나는 소리예요.","들은 것을 그대로 살렸어요.","그래서 감각적 표현이에요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#5','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C5',2,'mc','auto','「내 손 안에서 / 벌써 백 번은 미끄러졌다」는 어떤 마음을 나타낸 말인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「내 손 안에서 / 벌써 백 번은 미끄러졌다」는 어떤 마음을 나타낸 말인가요?","options":[{"t":"바통을 놓칠까 봐 걱정하는 마음이 몇 번이나 되풀이된 것","correct":true},{"t":"바통에 물이 묻어 실제로 자꾸 떨어진 것","mis":"K6-2-u6-X08"},{"t":"이어달리기를 백 번 연습해 보았다는 것","mis":"K6-2-u6-X08"},{"t":"손이 다쳐서 바통을 쥐지 못한 것","mis":"K6-2-u6-X07"}],"explanation":["바통은 아직 손에 오지도 않았어요.","실제로 미끄러진 것이 아니에요.","마음속에서 걱정한 거예요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#6','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C8',2,'mc','auto','「낮 / 우리 집은 빈 운동장이다」는 어떤 방법을 썼나요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":6,"concept":"K6-2-u6-C8","difficulty":2,"kind":"mc","stem":"「낮 / 우리 집은 빈 운동장이다」는 어떤 방법을 썼나요?","options":[{"t":"은유법","correct":true},{"t":"직유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"},{"t":"흉내 내는 말","mis":"K6-2-u6-X12"}],"explanation":["「처럼 · 같이」가 없어요.","「무엇은 무엇이다」로 말해 버렸어요.","그래서 은유법이에요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#7','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C7',2,'match','auto','빗댄 표현과 그렇게 빗댄 까닭을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u6-C7","difficulty":2,"kind":"match","stem":"빗댄 표현과 그렇게 빗댄 까닭을 이으세요.","pairs":[{"l":"아침 집 — 주전자처럼 끓는다","r":"바쁘고 뜨거운 기운이 넘쳐서"},{"l":"낮 집 — 빈 운동장이다","r":"아무도 없이 텅 비어 있어서"},{"l":"저녁 집 — 난롯가처럼 둥글다","r":"따뜻하게 둘러앉아 있어서"}],"mis":"K6-2-u6-X10","explanation":["빗댈 때에는 비슷한 점이 있어요.","그 점을 말로 옮겨 봐요.","아침 · 낮 · 저녁의 집이 달라요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#8','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C6',2,'mc','auto','겪은 일을 그대로 적은 글 ㉮를 시 「바통」으로 옮기면서 한 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X04','K6-2-u6-X14']::text[],false,'{"seq":8,"concept":"K6-2-u6-C6","difficulty":2,"kind":"mc","stem":"겪은 일을 그대로 적은 글 ㉮를 시 「바통」으로 옮기면서 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 부분만 골라 남겼다","correct":true},{"t":"겪은 일을 하나도 빠뜨리지 않고 적었다","mis":"K6-2-u6-X09"},{"t":"어려운 낱말로 바꾸어 썼다","mis":"K6-2-u6-X04"},{"t":"장면이 바뀌어도 연을 나누지 않았다","mis":"K6-2-u6-X14"}],"explanation":["두 글은 같은 경험을 담았어요.","시는 인상 깊은 순간만 남겼어요.","연을 나누고 빗대어 나타냈어요."],"asset":{"type":"passage","lines":["오늘 운동회에서 이어달리기를 했다. 내 차례를 기다리는 동안","손에 땀이 많이 났다. 앞 주자가 달려오는 것을 보니","심장이 빨리 뛰었다. 바통을 놓칠까 봐 걱정이 되었다.","바통을 받고 달리니 걱정이 사라졌다."],"title":"㉮ 같은 경험을 그대로 적은 글 (㉯는 시 「바통」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#9','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C10',2,'ox','auto','시는 반드시 빗댄 표현이 있어야 시라고 할 수 있어요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":9,"concept":"K6-2-u6-C10","difficulty":2,"kind":"ox","stem":"시는 반드시 빗댄 표현이 있어야 시라고 할 수 있어요.","answer":"X","reason_options":[{"t":"시의 특성은 지켜야 할 규칙이 아니라 쓸 수 있는 방법이기 때문에","correct":true},{"t":"빗댄 표현이 시를 시답게 만드는 규칙이기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["「우산 하나」에는 빗댄 표현이 하나도 없어요.","그래도 마음이 전해져요.","특성은 쓸 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_basic#10','kor',6,2,'u6','L02','g6_2_kor_u6_L02_basic','lesson_basic','K6-2-u6-C3',3,'mc','auto','시 「우산 하나」를 읽고 알맞게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X13','K6-2-u6-X04']::text[],false,'{"seq":10,"concept":"K6-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「우산 하나」를 읽고 알맞게 말한 친구는 누구인가요?","options":[{"t":"세윤 — 「빗댄 표현이 없어도 마음이 그대로 전해져.」","correct":true},{"t":"하진 — 「빗댄 표현을 다섯 개 넘게 넣어야 좋은 시야.」","mis":"K6-2-u6-X03"},{"t":"준하 — 「빗댄 표현이 없으면 시라고 할 수 없어.」","mis":"K6-2-u6-X13"},{"t":"나은 — 「어려운 낱말이 없어서 시답지 않아.」","mis":"K6-2-u6-X04"}],"explanation":["「우산 하나」에는 빗댄 표현이 없어요.","젖은 어깨 하나로 마음이 전해져요.","표현은 알맞은지로 골라요."],"asset":{"type":"passage","lines":["우산이 하나뿐이어서 / 네 쪽으로 기울였다","집에 와서 보니 / 내 왼쪽 어깨만 / 다 젖어 있었다"],"title":"시 「우산 하나」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#1','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C9',2,'mc','auto','「우리 집 소리」에서 본 것을 그대로 살린 감각적 표현은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":1,"concept":"K6-2-u6-C9","difficulty":2,"kind":"mc","stem":"「우리 집 소리」에서 본 것을 그대로 살린 감각적 표현은 어느 것인가요?","options":[{"t":"시계 초침만 혼자 술래를 한다","correct":true},{"t":"서둘러, 서둘러","mis":"K6-2-u6-X12"},{"t":"김이 푹푹 난다","mis":"K6-2-u6-X12"},{"t":"우리 집은 주전자처럼 끓는다","mis":"K6-2-u6-X12"}],"explanation":["서둘러와 푹푹은 들은 것이에요.","주전자처럼은 빗댄 표현이에요.","혼자 도는 초침은 본 것이에요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#2','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C10',2,'mc','auto','시의 특성으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":2,"concept":"K6-2-u6-C10","difficulty":2,"kind":"mc","stem":"시의 특성으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"겪은 일을 빠짐없이 차례대로 길게 적는다","correct":true},{"t":"연과 행으로 나누어 리듬이 느껴진다","mis":"K6-2-u6-X13"},{"t":"생각이나 느낌을 짧은 글로 눌러 담는다","mis":"K6-2-u6-X13"},{"t":"비유적 표현과 감각적 표현으로 생생하게 나타낸다","mis":"K6-2-u6-X13"}],"explanation":["리듬 · 짧게 · 생생하게는 시의 특성이에요.","빠짐없이 길게 적는 것은 일기에 가까워요.","시는 인상 깊은 것을 골라 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#3','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C7',3,'mc','auto','「누구 하나 빠지면 / 동그라미가 찌그러진다」에서 「동그라미」가 빗댄 것은 무엇인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X10']::text[],false,'{"seq":3,"concept":"K6-2-u6-C7","difficulty":3,"kind":"mc","stem":"「누구 하나 빠지면 / 동그라미가 찌그러진다」에서 「동그라미」가 빗댄 것은 무엇인가요?","options":[{"t":"저녁에 둘러앉은 우리 가족","correct":true},{"t":"식탁 위에 놓인 둥근 접시","mis":"K6-2-u6-X08"},{"t":"밤하늘에 뜬 둥근 달","mis":"K6-2-u6-X10"},{"t":"난로에서 피어오르는 연기","mis":"K6-2-u6-X10"}],"explanation":["저녁 우리 집은 난롯가처럼 둥글어요.","가족이 둘러앉은 모습이 동그라미예요.","하나라도 빠지면 모양이 찌그러져요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#4','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C8',3,'error','auto','빗댄 표현을 가렸어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X11']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":3,"kind":"error","stem":"빗댄 표현을 가렸어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보람 — 「‘빈 운동장이다’는 ‘처럼’이 없으니 직유법이야.」","correct":true,"mis_target":"K6-2-u6-X11"},{"t":"도하 — 「‘주전자처럼 끓는다’는 ‘처럼’이 있으니 직유법이야.」","mis":"K6-2-u6-X11"},{"t":"이서 — 「‘난롯가처럼 둥글다’도 직유법이야.」","mis":"K6-2-u6-X11"}],"explanation":["도하와 이서는 바르게 가렸어요.","「처럼」이 없이 그것이라고 말하면 은유법이에요.","보람은 둘을 바꾸어 말했어요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#5','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C5',3,'ox','auto','「운동장이 앞으로 뛰어온다」는 운동장이 실제로 움직였다는 뜻이에요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":5,"concept":"K6-2-u6-C5","difficulty":3,"kind":"ox","stem":"「운동장이 앞으로 뛰어온다」는 운동장이 실제로 움직였다는 뜻이에요.","answer":"X","reason_options":[{"t":"달리기 시작하자 운동장이 밀려오듯 느껴진 마음을 나타냈기 때문에","correct":true},{"t":"시에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["운동장은 실제로 움직이지 않아요.","말하는 이가 힘껏 달리고 있어요.","그 느낌을 빗대어 나타냈어요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#6','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C9',3,'match','auto','「우리 집 소리」의 표현과 그것을 느낀 감각을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C9","difficulty":3,"kind":"match","stem":"「우리 집 소리」의 표현과 그것을 느낀 감각을 이으세요.","pairs":[{"l":"서둘러, 서둘러","r":"들은 것"},{"l":"시계 초침이 혼자 돈다","r":"본 것"},{"l":"난롯가처럼 따뜻하다","r":"빗댄 것"}],"mis":"K6-2-u6-X12","explanation":["서두르는 말소리는 들은 것이에요.","초침이 도는 모습은 본 것이에요.","난롯가는 다른 것에 빗댄 거예요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#7','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C6',3,'mc','auto','㉮와 시 「바통」을 견주었을 때, 「바통」에만 있는 것은 어느 것인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X12']::text[],false,'{"seq":7,"concept":"K6-2-u6-C6","difficulty":3,"kind":"mc","stem":"㉮와 시 「바통」을 견주었을 때, 「바통」에만 있는 것은 어느 것인가요?","options":[{"t":"걱정하는 마음을 「백 번은 미끄러졌다」로 빗댄 표현","correct":true},{"t":"「바통을 놓칠까 봐 걱정이 되었다」는 문장","mis":"K6-2-u6-X09"},{"t":"겪은 일을 처음부터 끝까지 차례대로 적은 것","mis":"K6-2-u6-X09"},{"t":"「심장이 빨리 뛰었다」는 문장","mis":"K6-2-u6-X12"}],"explanation":["걱정되었다 · 심장이 뛰었다는 ㉮에 있어요.","차례대로 다 적은 것도 ㉮예요.","시는 마음을 빗대어 나타냈어요."],"asset":{"type":"passage","lines":["오늘 운동회에서 이어달리기를 했다. 내 차례를 기다리는 동안","손에 땀이 많이 났다. 앞 주자가 달려오는 것을 보니","심장이 빨리 뛰었다. 바통을 놓칠까 봐 걱정이 되었다.","바통을 받고 달리니 걱정이 사라졌다."],"title":"㉮ 같은 경험을 그대로 적은 글 (㉯는 시 「바통」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#8','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C10',4,'mc','auto','「연과 행 · 짧게 눌러 담기 · 빗대기」를 두고 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X13','K6-2-u6-X03']::text[],false,'{"seq":8,"concept":"K6-2-u6-C10","difficulty":4,"kind":"mc","stem":"「연과 행 · 짧게 눌러 담기 · 빗대기」를 두고 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"시를 생생하게 하는 방법이지만, 지켜야 할 규칙은 아니어서 마음에 알맞게 골라 쓴다","correct":true},{"t":"셋 가운데 하나라도 빠지면 시가 아니다","mis":"K6-2-u6-X13"},{"t":"셋을 모두 많이 쓸수록 좋은 시다","mis":"K6-2-u6-X03"},{"t":"셋은 일기를 쓸 때 지키는 규칙이다","mis":"K6-2-u6-X13"}],"explanation":["셋 다 시의 특성이에요.","그래도 규칙이 아니라 방법이에요.","마음에 알맞게 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#9','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C7',4,'essay','teacher','「우리 집 소리」에서 빗댄 표현 하나를 골라 무엇을 무엇에 빗대었는지, 두 대상이 어떤 점에서 비슷한지 쓰고, 그 표현이 직유법인지 은유법인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C7","difficulty":4,"kind":"essay","stem":"「우리 집 소리」에서 빗댄 표현 하나를 골라 무엇을 무엇에 빗대었는지, 두 대상이 어떤 점에서 비슷한지 쓰고, 그 표현이 직유법인지 은유법인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「아침 / 우리 집은 주전자처럼 끓는다」는 아침의 우리 집을 끓는 주전자에 빗대었다. 아침에 모두 서두르느라 바쁘고 시끄러운 모습이 김을 내며 끓는 주전자처럼 뜨겁고 바쁜 기운이 넘친다는 점에서 비슷하다. 「처럼」을 써서 두 대상을 바로 견주었으므로 직유법이다.","scoring_points":["무엇을 무엇에 빗대었는지 썼는가","두 대상의 비슷한 점을 썼는가","직유법 · 은유법을 까닭과 함께 가렸는가"]},"explanation":["빗댄 두 대상을 찾아요.","닮은 점을 말로 옮겨요.","「처럼」이 있는지 봐요."],"asset":{"type":"passage","lines":["아침 / 우리 집은 주전자처럼 끓는다 / 서둘러, 서둘러 / 김이 푹푹 난다","낮 / 우리 집은 빈 운동장이다 / 시계 초침만 혼자 술래를 한다","저녁 / 우리 집은 난롯가처럼 둥글다","누구 하나 빠지면 / 동그라미가 찌그러진다"],"title":"시 「우리 집 소리」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L02_challenge#10','kor',6,2,'u6','L02','g6_2_kor_u6_L02_challenge','lesson_challenge','K6-2-u6-C5',4,'essay','teacher','시 「바통」에서 가장 인상 깊은 표현을 하나 골라 어떤 장면이 떠오르는지 쓰고, 그 표현이 말하는 이의 어떤 마음을 나타내는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C5","difficulty":4,"kind":"essay","stem":"시 「바통」에서 가장 인상 깊은 표현을 하나 골라 어떤 장면이 떠오르는지 쓰고, 그 표현이 말하는 이의 어떤 마음을 나타내는지 쓰세요.","answer_guide":{"answer":"예: 「호루라기 소리보다 / 내 심장이 먼저 울린다」. 출발 신호가 울리기도 전에 내 차례를 기다리며 가슴이 쿵쾅거리는 장면이 떠오른다. 실제로 심장이 소리를 낸 것이 아니라, 그만큼 떨리고 긴장된 마음을 나타낸 표현이다.","scoring_points":["표현을 하나 골랐는가","떠오르는 장면을 썼는가","실제 일이 아니라 마음으로 읽었는가"]},"explanation":["장면을 머릿속에 그려요.","실제로 일어난 일인지 따져요.","마음을 나타낸 말로 읽어요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#1','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C7',1,'mc','auto','시 「이단 뛰기」에서 「새가 된다」는 무엇을 나타낸 표현인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C7","difficulty":1,"kind":"mc","stem":"시 「이단 뛰기」에서 「새가 된다」는 무엇을 나타낸 표현인가요?","options":[{"t":"줄을 두 번 넘는 동안 몸이 잠깐 떠 있는 모습","correct":true},{"t":"말하는 이가 새를 기르고 있다는 뜻","mis":"K6-2-u6-X08"},{"t":"비행기를 타고 날아 본 경험","mis":"K6-2-u6-X07"},{"t":"창밖으로 새가 날아간 모습","mis":"K6-2-u6-X08"}],"explanation":["이단 뛰기를 할 때 몸을 떠올려요.","몸이 바닥에서 잠깐 떠요.","그 모습을 새에 빗대었어요."],"asset":{"type":"passage","lines":["줄이 발밑을 두 번 지나가는 / 그 짧은 사이","내 몸이 바닥에서 / 잠깐 새가 된다","탁, 탁 / 두 번째 소리가 나면 / 성공이다","백 번을 걸리고 / 백한 번째에 / 처음으로 새가 되었다"],"title":"또래가 쓴 시 「이단 뛰기」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#2','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C11',1,'mc','auto','시를 쓰기 전에 가장 먼저 할 일은 무엇인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X03','K6-2-u6-X15']::text[],false,'{"seq":2,"concept":"K6-2-u6-C11","difficulty":1,"kind":"mc","stem":"시를 쓰기 전에 가장 먼저 할 일은 무엇인가요?","options":[{"t":"시로 쓰고 싶은 경험 고르기","correct":true},{"t":"제목을 멋있게 정하기","mis":"K6-2-u6-X18"},{"t":"빗댄 표현을 다섯 개 정하기","mis":"K6-2-u6-X03"},{"t":"시를 몇 줄로 쓸지 정하기","mis":"K6-2-u6-X15"}],"explanation":["무엇을 쓸지부터 정해요.","그다음 묻고 답하며 자세히 떠올려요.","생각그물에 모으고 남길 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#3','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C13',1,'ox','auto','생각그물에 모은 것은 하나도 빠뜨리지 않고 시에 다 넣어야 해요.',ARRAY['K6-2-u6-X16']::text[],false,'{"seq":3,"concept":"K6-2-u6-C13","difficulty":1,"kind":"ox","stem":"생각그물에 모은 것은 하나도 빠뜨리지 않고 시에 다 넣어야 해요.","answer":"X","reason_options":[{"t":"다 넣으면 어느 순간이 중요한지 알 수 없는 목록이 되기 때문에","correct":true},{"t":"빠뜨린 것이 있으면 좋은 시가 될 수 없기 때문에","mis":"K6-2-u6-X16"}],"mis":"K6-2-u6-X16","explanation":["시는 넣는 일보다 버리는 일이 커요.","인상 깊은 순간만 남겨요.","그래야 마음이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#4','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',1,'mc','auto','생각그물에서 「탁, 탁 하는 두 번의 소리」는 어느 칸에 들어가나요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C12","difficulty":1,"kind":"mc","stem":"생각그물에서 「탁, 탁 하는 두 번의 소리」는 어느 칸에 들어가나요?","options":[{"t":"들은 것","correct":true},{"t":"본 것","mis":"K6-2-u6-X12"},{"t":"만진 것","mis":"K6-2-u6-X12"},{"t":"빗댈 것","mis":"K6-2-u6-X12"}],"explanation":["귀로 들은 소리예요.","줄이 지나가는 모습은 본 것이에요.","미끄러운 손잡이는 만진 것이에요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#5','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C11',2,'mc','auto','경험을 자세히 떠올리는 데 도움이 되는 물음은 어느 것인가요?',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":5,"concept":"K6-2-u6-C11","difficulty":2,"kind":"mc","stem":"경험을 자세히 떠올리는 데 도움이 되는 물음은 어느 것인가요?","options":[{"t":"「그 순간을 무엇에 빗댈 수 있을까?」","correct":true},{"t":"「그 일은 몇 시 몇 분에 일어났어?」","mis":"K6-2-u6-X15"},{"t":"「시를 몇 줄로 쓸 생각이야?」","mis":"K6-2-u6-X15"},{"t":"「줄넘기는 얼마에 샀어?」","mis":"K6-2-u6-X15"}],"explanation":["시각 · 줄 수 · 값은 경험 속으로 데려가지 않아요.","그 순간을 다시 떠올리게 하는 물음이 좋아요.","빗댈 것을 물으면 표현이 생겨요."],"asset":{"type":"speech","turns":[{"who":"하진","text":"나는 이단 뛰기 처음 성공한 날을 쓸래."},{"who":"준하","text":"그때 제일 기억에 남는 순간이 언제였어?"},{"who":"하진","text":"두 번째 탁 소리가 났을 때. 그 전까지는 계속 한 번만 났거든."},{"who":"준하","text":"그 순간 몸은 어땠는데? 무엇에 빗댈 수 있을 것 같아?"},{"who":"하진","text":"아, 잠깐 붕 떠 있었어. 새 같았던 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#6','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C12',2,'match','auto','생각그물의 칸과 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C12","difficulty":2,"kind":"match","stem":"생각그물의 칸과 알맞은 내용을 이으세요.","pairs":[{"l":"본 것","r":"빠르게 지나가는 줄"},{"l":"만진 것","r":"땀으로 미끄러운 손잡이"},{"l":"빗댈 것","r":"잠깐 떠 있는 몸 — 새"}],"mis":"K6-2-u6-X12","explanation":["눈으로 본 것을 가려요.","손으로 만진 것을 가려요.","다른 것에 빗댈 것을 가려요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#7','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C13',2,'mc','auto','㉯ 시 「이단 뛰기」가 ㉮보다 더 시답게 읽히는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X17','K6-2-u6-X16']::text[],false,'{"seq":7,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"㉯ 시 「이단 뛰기」가 ㉮보다 더 시답게 읽히는 까닭은 무엇인가요?","options":[{"t":"인상 깊은 순간만 남겨 그 마음이 또렷해졌기 때문에","correct":true},{"t":"빗댄 표현을 더 많이 넣었기 때문에","mis":"K6-2-u6-X17"},{"t":"시는 무조건 짧아야 하기 때문에","mis":"K6-2-u6-X17"},{"t":"생각그물을 빠짐없이 다 넣었기 때문에","mis":"K6-2-u6-X16"}],"explanation":["㉮는 빠뜨린 것이 없어요.","그런데 무엇이 중요한지 알 수 없어요.","㉯는 버렸기 때문에 남은 것이 또렷해요."],"asset":{"type":"passage","lines":["줄이 발밑을 지나가고 탁 탁 소리가 나고 손잡이가 미끄럽고","이마에 땀이 나고 친구들이 세어 주고 백한 번째에 되었고","몸이 새 같았고 가슴이 뻥 뚫렸다"],"title":"㉮ 생각그물을 다 넣은 것 (㉯는 시 「이단 뛰기」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#8','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C14',2,'ox','auto','시의 제목은 맨 처음에 붙여도 되고 다 쓴 뒤에 붙여도 돼요.',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":8,"concept":"K6-2-u6-C14","difficulty":2,"kind":"ox","stem":"시의 제목은 맨 처음에 붙여도 되고 다 쓴 뒤에 붙여도 돼요.","answer":"O","reason_options":[{"t":"언제 붙이든 시에 담긴 마음이 드러나면 되기 때문에","correct":true},{"t":"제목은 반드시 시를 쓰기 전에 정해야 하기 때문에","mis":"K6-2-u6-X18"}],"mis":"K6-2-u6-X18","explanation":["제목을 먼저 정해도 돼요.","다 쓰고 붙여도 돼요.","고개가 끄덕여지는 제목이면 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#9','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C15',2,'mc','auto','시를 고쳐 쓸 때 볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":9,"concept":"K6-2-u6-C15","difficulty":2,"kind":"mc","stem":"시를 고쳐 쓸 때 볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"없어도 되는 줄이 남아 있지는 않은가","correct":true},{"t":"빗댄 표현이 다섯 개를 넘는가","mis":"K6-2-u6-X19"},{"t":"글씨를 예쁘게 썼는가","mis":"K6-2-u6-X19"},{"t":"줄 수가 친구 시보다 많은가","mis":"K6-2-u6-X19"}],"explanation":["개수와 글씨는 볼 것이 아니에요.","전하려던 마음이 드러나는지 봐요.","없어도 되는 줄은 지워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_basic#10','kor',6,2,'u6','L04','g6_2_kor_u6_L04_basic','lesson_basic','K6-2-u6-C6',3,'mc','auto','「이단 뛰기」에서 장면이 바뀌는 곳에 연을 나눈 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X13','K6-2-u6-X14']::text[],false,'{"seq":10,"concept":"K6-2-u6-C6","difficulty":3,"kind":"mc","stem":"「이단 뛰기」에서 장면이 바뀌는 곳에 연을 나눈 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"줄이 지나가는 순간 · 소리가 난 순간 · 성공한 순간처럼 장면이 바뀔 때마다 나누어 읽는 사람이 따라가기 쉽게 하려고","correct":true},{"t":"연이 많을수록 좋은 시가 되기 때문에","mis":"K6-2-u6-X13"},{"t":"아무 데서나 나누어도 상관없기 때문에","mis":"K6-2-u6-X14"},{"t":"한 연에는 반드시 두 줄만 써야 하기 때문에","mis":"K6-2-u6-X13"}],"explanation":["연은 장면이 바뀌는 곳에서 나눠요.","읽는 사람이 장면을 따라가요.","정해진 줄 수 규칙은 없어요."],"asset":{"type":"passage","lines":["줄이 발밑을 두 번 지나가는 / 그 짧은 사이","내 몸이 바닥에서 / 잠깐 새가 된다","탁, 탁 / 두 번째 소리가 나면 / 성공이다","백 번을 걸리고 / 백한 번째에 / 처음으로 새가 되었다"],"title":"또래가 쓴 시 「이단 뛰기」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#1','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C14',2,'mc','auto','「이단 뛰기」의 마음이 가장 잘 드러나는 제목은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":1,"concept":"K6-2-u6-C14","difficulty":2,"kind":"mc","stem":"「이단 뛰기」의 마음이 가장 잘 드러나는 제목은 어느 것인가요?","options":[{"t":"백한 번째 새","correct":true},{"t":"줄넘기를 한 날","mis":"K6-2-u6-X18"},{"t":"체육 시간","mis":"K6-2-u6-X18"},{"t":"줄넘기 손잡이의 색깔","mis":"K6-2-u6-X18"}],"explanation":["겪은 일 그대로의 제목도 쓸 수 있어요.","그런데 마음이 잘 드러나지 않아요.","드디어 새가 된 순간이 담긴 제목이 좋아요."],"asset":{"type":"passage","lines":["줄이 발밑을 두 번 지나가는 / 그 짧은 사이","내 몸이 바닥에서 / 잠깐 새가 된다","탁, 탁 / 두 번째 소리가 나면 / 성공이다","백 번을 걸리고 / 백한 번째에 / 처음으로 새가 되었다"],"title":"또래가 쓴 시 「이단 뛰기」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#2','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',2,'mc','auto','시 쓰기를 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X16','K6-2-u6-X15']::text[],false,'{"seq":2,"concept":"K6-2-u6-C11","difficulty":2,"kind":"mc","stem":"시 쓰기를 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"경험 고르기 → 묻고 답하며 떠올리기 → 생각그물로 모으기 → 남길 것 고르기","correct":true},{"t":"제목 정하기 → 빗댄 표현 다섯 개 정하기 → 경험 고르기 → 쓰기","mis":"K6-2-u6-X18"},{"t":"생각그물 그리기 → 모두 넣기 → 경험 고르기 → 쓰기","mis":"K6-2-u6-X16"},{"t":"줄 수 정하기 → 쓰기 → 경험 고르기 → 고치기","mis":"K6-2-u6-X15"}],"explanation":["무엇을 쓸지 먼저 골라요.","묻고 답하며 자세히 떠올려요.","모은 것에서 남길 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#3','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C12',3,'mc','auto','하진이의 생각그물에서 다른 칸으로 잘못 옮기면 안 되는 것끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":3,"concept":"K6-2-u6-C12","difficulty":3,"kind":"mc","stem":"하진이의 생각그물에서 다른 칸으로 잘못 옮기면 안 되는 것끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"「땀으로 미끄러운 손잡이」 — 만진 것","correct":true},{"t":"「탁, 탁 하는 두 번의 소리」 — 본 것","mis":"K6-2-u6-X12"},{"t":"「발밑을 지나가는 줄」 — 들은 것","mis":"K6-2-u6-X12"},{"t":"「잠깐 떠 있는 몸 → 새」 — 만진 것","mis":"K6-2-u6-X12"}],"explanation":["소리는 들은 것이에요.","줄은 눈으로 본 것이에요.","손잡이는 손으로 만진 것이에요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#4','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',3,'ox','auto','「그때 마음이 어떻게 움직였니?」는 경험을 자세히 떠올리게 하는 좋은 물음이에요.',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":4,"concept":"K6-2-u6-C11","difficulty":3,"kind":"ox","stem":"「그때 마음이 어떻게 움직였니?」는 경험을 자세히 떠올리게 하는 좋은 물음이에요.","answer":"O","reason_options":[{"t":"그 경험 속으로 다시 들어가 마음을 떠올리게 하기 때문에","correct":true},{"t":"시를 몇 줄로 쓸지 정하게 해 주기 때문에","mis":"K6-2-u6-X15"}],"mis":"K6-2-u6-X15","explanation":["좋은 물음은 그 순간으로 데려가요.","마음이 움직인 곳을 찾게 해요.","흐릿한 기억이 또렷해져요."],"asset":{"type":"speech","turns":[{"who":"하진","text":"나는 이단 뛰기 처음 성공한 날을 쓸래."},{"who":"준하","text":"그때 제일 기억에 남는 순간이 언제였어?"},{"who":"하진","text":"두 번째 탁 소리가 났을 때. 그 전까지는 계속 한 번만 났거든."},{"who":"준하","text":"그 순간 몸은 어땠는데? 무엇에 빗댈 수 있을 것 같아?"},{"who":"하진","text":"아, 잠깐 붕 떠 있었어. 새 같았던 것 같아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#5','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',3,'error','auto','㉮와 ㉯를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X09']::text[],false,'{"seq":5,"concept":"K6-2-u6-C13","difficulty":3,"kind":"error","stem":"㉮와 ㉯를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하진 — 「㉮는 빠뜨린 것이 없으니까 ㉯보다 더 좋은 시야.」","correct":true,"mis_target":"K6-2-u6-X16"},{"t":"준하 — 「㉯는 버렸기 때문에 남은 것이 또렷해.」","mis":"K6-2-u6-X16"},{"t":"지오 — 「㉮는 어느 순간이 중요한지 알 수 없어.」","mis":"K6-2-u6-X09"}],"explanation":["준하와 지오는 바르게 말했어요.","하진은 다 넣어야 좋은 시라고 여겼어요.","시는 버리는 일이 더 커요."],"asset":{"type":"passage","lines":["줄이 발밑을 지나가고 탁 탁 소리가 나고 손잡이가 미끄럽고","이마에 땀이 나고 친구들이 세어 주고 백한 번째에 되었고","몸이 새 같았고 가슴이 뻥 뚫렸다"],"title":"㉮ 생각그물을 다 넣은 것 (㉯는 시 「이단 뛰기」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#6','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C15',3,'match','auto','고쳐 쓸 때 본 것과 그렇게 고친 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C15","difficulty":3,"kind":"match","stem":"고쳐 쓸 때 본 것과 그렇게 고친 방법을 이으세요.","pairs":[{"l":"전하려던 마음이 흐릿하다","r":"마음이 드러난 순간을 앞으로 옮긴다"},{"l":"장면이 바뀌는데 한 연에 붙어 있다","r":"장면이 바뀌는 곳에서 연을 나눈다"},{"l":"소리 내어 읽으니 걸리는 줄이 있다","r":"걸리는 줄을 고치거나 지운다"}],"mis":"K6-2-u6-X19","explanation":["마음이 드러나게 고쳐요.","연을 장면에 맞게 나눠요.","소리 내어 읽고 걸리는 곳을 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#7','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C14',3,'mc','auto','시 「우산 하나」의 제목에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X18']::text[],false,'{"seq":7,"concept":"K6-2-u6-C14","difficulty":3,"kind":"mc","stem":"시 「우산 하나」의 제목에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"우산이 하나뿐이어서 친구 쪽으로 기울인 마음이 제목에서부터 떠오른다","correct":true},{"t":"제목에 빗댄 표현이 없어서 아쉽다","mis":"K6-2-u6-X03"},{"t":"제목은 쓰기 전에 정해야 하는데 다 쓴 뒤 붙인 것 같아 잘못이다","mis":"K6-2-u6-X18"},{"t":"제목이 짧아서 좋은 제목이라고 할 수 없다","mis":"K6-2-u6-X18"}],"explanation":["제목에 빗댄 표현이 꼭 있어야 하지는 않아요.","언제 붙여도 괜찮아요.","시를 읽고 고개가 끄덕여지면 좋은 제목이에요."],"asset":{"type":"passage","lines":["우산이 하나뿐이어서 / 네 쪽으로 기울였다","집에 와서 보니 / 내 왼쪽 어깨만 / 다 젖어 있었다"],"title":"시 「우산 하나」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#8','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',4,'mc','auto','하진이가 생각그물에서 「이마에 땀이 났다」와 「친구들이 세어 주었다」를 시에서 뺀 것을 두고 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X17','K6-2-u6-X03']::text[],false,'{"seq":8,"concept":"K6-2-u6-C13","difficulty":4,"kind":"mc","stem":"하진이가 생각그물에서 「이마에 땀이 났다」와 「친구들이 세어 주었다」를 시에서 뺀 것을 두고 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"두 번째 소리가 나며 새가 된 순간이 또렷해지도록 덜 중요한 것을 버린 것이다","correct":true},{"t":"빠뜨린 것이 생겨 좋은 시가 될 수 없다","mis":"K6-2-u6-X16"},{"t":"시는 무조건 짧아야 하니 뺀 것이다","mis":"K6-2-u6-X17"},{"t":"빗댄 표현이 아니라서 뺀 것이다","mis":"K6-2-u6-X03"}],"explanation":["버린 것은 잘못 빠뜨린 것이 아니에요.","짧게 하려는 것이 목적도 아니에요.","남길 순간이 또렷해지도록 골랐어요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#9','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C11',4,'essay','teacher','내가 겪은 일 하나를 정해, 짝이 경험을 자세히 떠올리게 도와줄 물음 세 가지를 쓰고, 그 물음이 왜 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C11","difficulty":4,"kind":"essay","stem":"내가 겪은 일 하나를 정해, 짝이 경험을 자세히 떠올리게 도와줄 물음 세 가지를 쓰고, 그 물음이 왜 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 겪은 일 — 처음으로 혼자 김밥을 만 날. 물음 ① 「가장 기억에 남는 순간은 언제였어?」 ② 「그때 손에 무엇이 느껴졌어?」 ③ 「그 순간을 무엇에 빗댈 수 있을까?」 이런 물음은 그 경험 속으로 다시 들어가게 해 줘서, 흐릿하던 순간과 감각, 마음이 또렷하게 떠오르게 한다. 몇 시였는지나 몇 줄로 쓸지 같은 물음은 도움이 되지 않는다.","scoring_points":["겪은 일을 하나 정했는가","경험 속으로 들어가게 하는 물음을 세 가지 썼는가","물음이 도움이 되는 까닭을 썼는가"]},"explanation":["가장 기억에 남는 순간을 물어요.","본 것 · 들은 것 · 만진 것을 물어요.","빗댈 것과 마음을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L04_challenge#10','kor',6,2,'u6','L04','g6_2_kor_u6_L04_challenge','lesson_challenge','K6-2-u6-C13',4,'essay','teacher','㉮처럼 생각그물을 다 넣은 시와 ㉯처럼 인상 깊은 것만 고른 시는 읽는 사람에게 어떻게 다르게 읽히는지 쓰고, 시를 쓸 때 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C13","difficulty":4,"kind":"essay","stem":"㉮처럼 생각그물을 다 넣은 시와 ㉯처럼 인상 깊은 것만 고른 시는 읽는 사람에게 어떻게 다르게 읽히는지 쓰고, 시를 쓸 때 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: ㉮는 빠뜨린 것이 없지만 줄, 소리, 땀, 친구들이 모두 같은 무게로 늘어서 있어 어느 순간이 중요한지 알 수 없는 목록처럼 읽힌다. ㉯는 줄이 지나가는 사이, 두 번째 소리, 백한 번째에 새가 된 순간만 남겨 처음 성공했을 때의 마음이 또렷하게 읽힌다. 그래서 시를 쓸 때에는 생각그물에서 인상 깊은 것만 골라 남기고 나머지는 과감히 버려야 한다.","scoring_points":["㉮가 목록처럼 읽히는 까닭을 썼는가","㉯에서 마음이 또렷해진 까닭을 썼는가","고르고 버려야 한다고 썼는가"]},"explanation":["무엇이 남는지 견주어요.","버린 덕분에 또렷해져요.","넣는 일보다 버리는 일이에요."],"asset":{"type":"passage","lines":["줄이 발밑을 지나가고 탁 탁 소리가 나고 손잡이가 미끄럽고","이마에 땀이 나고 친구들이 세어 주고 백한 번째에 되었고","몸이 새 같았고 가슴이 뻥 뚫렸다"],"title":"㉮ 생각그물을 다 넣은 것 (㉯는 시 「이단 뛰기」)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#1','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',1,'mc','auto','낭송을 준비할 때 가장 먼저 정할 것은 무엇인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":1,"concept":"K6-2-u6-C16","difficulty":1,"kind":"mc","stem":"낭송을 준비할 때 가장 먼저 정할 것은 무엇인가요?","options":[{"t":"듣는 사람에게 꼭 전하고 싶은 마음","correct":true},{"t":"배경 음악으로 쓸 노래","mis":"K6-2-u6-X22"},{"t":"입고 나갈 옷","mis":"K6-2-u6-X20"},{"t":"시를 다 외웠는지","mis":"K6-2-u6-X20"}],"explanation":["전하고 싶은 마음을 먼저 정해요.","그 마음에 어울리는 목소리와 속도를 찾아요.","음악은 그다음에 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#2','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',1,'ox','auto','배경 음악은 낭송하는 목소리보다 크게 틀어야 해요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":2,"concept":"K6-2-u6-C17","difficulty":1,"kind":"ox","stem":"배경 음악은 낭송하는 목소리보다 크게 틀어야 해요.","answer":"X","reason_options":[{"t":"음악이 목소리를 덮으면 시의 마음이 들리지 않기 때문에","correct":true},{"t":"음악이 커야 낭송이 멋있게 들리기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["배경 음악은 작게 깔아요.","듣는 사람은 시를 끝까지 들어야 해요.","음악은 돕는 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#3','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C18',1,'mc','auto','친구의 낭송을 들을 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":3,"concept":"K6-2-u6-C18","difficulty":1,"kind":"mc","stem":"친구의 낭송을 들을 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"낭송하는 사람을 바라보며 듣는다","correct":true},{"t":"옆 친구와 감상을 그때그때 이야기한다","mis":"K6-2-u6-X24"},{"t":"틀린 글자를 찾아 두었다가 알려 준다","mis":"K6-2-u6-X24"},{"t":"내 차례에 읽을 시를 미리 읽어 둔다","mis":"K6-2-u6-X24"}],"explanation":["낭송회는 함께 만들어요.","바라보며 들어요.","시와 관련 있는 내 경험을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#4','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',1,'mc','auto','낭송의 목표로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X20']::text[],false,'{"seq":4,"concept":"K6-2-u6-C19","difficulty":1,"kind":"mc","stem":"낭송의 목표로 알맞은 것은 어느 것인가요?","options":[{"t":"그 시의 마음이 듣는 사람에게 건너가는 것","correct":true},{"t":"가장 큰 목소리로 읽는 것","mis":"K6-2-u6-X21"},{"t":"화려하게 꾸며 멋있게 들리는 것","mis":"K6-2-u6-X22"},{"t":"가장 빨리 끝까지 읽는 것","mis":"K6-2-u6-X20"}],"explanation":["크게 읽는 것이 목표가 아니에요.","화려한 꾸밈도 목표가 아니에요.","시의 마음이 건너가게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#5','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',2,'match','auto','「이단 뛰기」의 부분과 알맞은 낭송 방법을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C16","difficulty":2,"kind":"match","stem":"「이단 뛰기」의 부분과 알맞은 낭송 방법을 이으세요.","pairs":[{"l":"줄이 두 번 지나가는 그 짧은 사이","r":"숨을 참듯 낮고 느리게"},{"l":"탁, 탁 / 성공이다","r":"또렷하고 빠르게"},{"l":"백 번을 걸리고 백한 번째에","r":"한 음절씩 힘을 실어 천천히"}],"mis":"K6-2-u6-X20","explanation":["숨죽인 순간은 낮고 느리게 읽어요.","성공한 순간은 또렷하고 빠르게 읽어요.","버틴 마음은 힘을 실어 천천히 읽어요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#6','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C17',2,'mc','auto','낭송에 효과음을 쓸 때 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":6,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"낭송에 효과음을 쓸 때 알맞은 것은 어느 것인가요?","options":[{"t":"시의 장면과 맞닿은 소리를 아주 짧게 쓴다","correct":true},{"t":"여러 가지 소리를 쉬지 않고 계속 튼다","mis":"K6-2-u6-X22"},{"t":"시와 상관없이 재미있는 소리를 고른다","mis":"K6-2-u6-X22"},{"t":"목소리 대신 효과음으로 시를 들려준다","mis":"K6-2-u6-X22"}],"explanation":["효과음은 장면과 맞닿은 소리여야 해요.","아주 짧게 써요.","낭송을 대신하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#7','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C19',2,'ox','auto','마음만 담으면 들리지 않을 만큼 작게 읽어도 좋은 낭송이에요.',ARRAY['K6-2-u6-X23']::text[],false,'{"seq":7,"concept":"K6-2-u6-C19","difficulty":2,"kind":"ox","stem":"마음만 담으면 들리지 않을 만큼 작게 읽어도 좋은 낭송이에요.","answer":"X","reason_options":[{"t":"뒤에 앉은 사람까지 들려야 마음이 건너가기 때문에","correct":true},{"t":"작게 읽을수록 마음이 깊게 전해지기 때문에","mis":"K6-2-u6-X23"}],"mis":"K6-2-u6-X23","explanation":["들리지 않으면 마음도 건너가지 않아요.","뒤에 앉은 사람까지 들리게 읽어요.","부분마다 마음에 맞는 크기로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#8','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C18',2,'mc','auto','낭송을 들은 뒤 해 줄 조언으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X21','K6-2-u6-X24']::text[],false,'{"seq":8,"concept":"K6-2-u6-C18","difficulty":2,"kind":"mc","stem":"낭송을 들은 뒤 해 줄 조언으로 알맞은 것은 어느 것인가요?","options":[{"t":"「탁, 탁」 부분을 조금 더 빠르게 읽으면 그 순간이 더 살아날 것 같아","correct":true},{"t":"그냥 잘했어. 다음에도 그렇게 해","mis":"K6-2-u6-X25"},{"t":"목소리를 무조건 더 크게 내면 돼","mis":"K6-2-u6-X21"},{"t":"글자 하나 틀린 것만 고치면 돼","mis":"K6-2-u6-X24"}],"explanation":["잘했어만으로는 무엇을 바꿀지 몰라요.","무조건 크게는 알맞은 조언이 아니에요.","어느 부분을 어떻게 할지 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#9','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C16',2,'mc','auto','「이단 뛰기」 낭송 계획에서 전하고 싶은 마음은 무엇인가요?',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":9,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"「이단 뛰기」 낭송 계획에서 전하고 싶은 마음은 무엇인가요?","options":[{"t":"백 번을 걸리고도 다시 뛰었던 버티는 마음","correct":true},{"t":"줄넘기가 쉽다는 마음","mis":"K6-2-u6-X20"},{"t":"친구들보다 잘한다고 뽐내는 마음","mis":"K6-2-u6-X20"},{"t":"체육 시간이 지루했던 마음","mis":"K6-2-u6-X20"}],"explanation":["계획의 맨 위에 적혀 있어요.","백 번을 걸리고도 다시 뛰었어요.","그 마음에 맞춰 목소리를 정했어요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_basic#10','kor',6,2,'u6','L06','g6_2_kor_u6_L06_basic','lesson_basic','K6-2-u6-C21',3,'error','auto','낭송에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X23']::text[],false,'{"seq":10,"concept":"K6-2-u6-C21","difficulty":3,"kind":"error","stem":"낭송에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"태린 — 「처음부터 끝까지 가장 큰 목소리로 읽으면 잘하는 낭송이야.」","correct":true,"mis_target":"K6-2-u6-X21"},{"t":"하진 — 「부분마다 마음에 맞는 크기로 읽어야 해.」","mis":"K6-2-u6-X21"},{"t":"준하 — 「뒤에 앉은 사람까지는 들려야 해.」","mis":"K6-2-u6-X23"}],"explanation":["하진과 준하는 바르게 말했어요.","태린은 마음과 상관없이 크게만 읽으려 했어요.","크기는 마음을 따라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#1','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',2,'mc','auto','낭송할 때 영상이나 그림을 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":1,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"낭송할 때 영상이나 그림을 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"시의 장면을 떠올리는 데 도움이 될 만큼만 쓴다","correct":true},{"t":"화려한 영상을 쉬지 않고 바꾸어 눈을 사로잡는다","mis":"K6-2-u6-X22"},{"t":"영상만 보여 주고 낭송은 하지 않는다","mis":"K6-2-u6-X22"},{"t":"시와 상관없는 재미있는 그림을 고른다","mis":"K6-2-u6-X22"}],"explanation":["영상이 화려하면 낭송의 흐름을 방해해요.","낭송을 대신하지 않아요.","장면을 떠올리는 데 도움이 될 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#2','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',2,'mc','auto','「이단 뛰기」 낭송 계획에서 ㉮ 부분을 숨을 참듯 낮고 느리게 읽는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X20','K6-2-u6-X21']::text[],false,'{"seq":2,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"「이단 뛰기」 낭송 계획에서 ㉮ 부분을 숨을 참듯 낮고 느리게 읽는 까닭은 무엇인가요?","options":[{"t":"줄이 지나가는 짧은 사이, 숨죽인 긴장된 마음을 따라가기 때문에","correct":true},{"t":"모든 부분을 같은 목소리로 읽어야 하기 때문에","mis":"K6-2-u6-X20"},{"t":"낮게 읽어야 언제나 낭송이 멋있기 때문에","mis":"K6-2-u6-X21"},{"t":"㉮가 가장 긴 부분이기 때문에","mis":"K6-2-u6-X20"}],"explanation":["목소리는 그 부분의 마음을 따라가요.","숨죽인 순간이에요.","그래서 낮고 느리게 읽어요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#3','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',3,'ox','auto','「이단 뛰기」는 처음부터 끝까지 같은 목소리와 속도로 읽는 것이 가장 알맞아요.',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":3,"concept":"K6-2-u6-C16","difficulty":3,"kind":"ox","stem":"「이단 뛰기」는 처음부터 끝까지 같은 목소리와 속도로 읽는 것이 가장 알맞아요.","answer":"X","reason_options":[{"t":"부분마다 담긴 마음이 달라 목소리와 속도도 달라지기 때문에","correct":true},{"t":"같은 속도로 읽어야 듣는 사람이 헷갈리지 않기 때문에","mis":"K6-2-u6-X20"}],"mis":"K6-2-u6-X20","explanation":["숨죽인 순간과 성공한 순간은 마음이 달라요.","목소리는 그 마음을 따라가요.","부분마다 크기와 속도를 정해요."],"asset":{"type":"passage","lines":["전하고 싶은 마음 · 백 번을 걸리고도 다시 뛰었던 버티는 마음","㉮ 「줄이 발밑을 두 번 지나가는 / 그 짧은 사이」","   → 숨을 참듯 낮고 느리게","㉯ 「탁, 탁 / 두 번째 소리가 나면 / 성공이다」","   → 또렷하고 빠르게","㉰ 「백 번을 걸리고 / 백한 번째에」","   → 한 음절씩 힘을 실어 천천히"],"title":"「이단 뛰기」 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#4','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',3,'error','auto','친구의 낭송을 듣는 모습이에요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['K6-2-u6-X24','K6-2-u6-X25']::text[],false,'{"seq":4,"concept":"K6-2-u6-C18","difficulty":3,"kind":"error","stem":"친구의 낭송을 듣는 모습이에요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"나은 — 낭송하는 동안 옆 친구와 감상을 이야기했다","correct":true,"mis_target":"K6-2-u6-X24"},{"t":"도하 — 낭송하는 친구를 바라보며 들었다","mis":"K6-2-u6-X24"},{"t":"이서 — 끝난 뒤 좋았던 부분을 짚어 말해 주었다","mis":"K6-2-u6-X25"}],"explanation":["도하와 이서는 잘 들었어요.","나은이는 듣는 동안 이야기를 해 집중을 흐렸어요.","이야기는 끝난 뒤에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#5','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C19',3,'mc','auto','「낭송을 잘한다는 것」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X23']::text[],false,'{"seq":5,"concept":"K6-2-u6-C19","difficulty":3,"kind":"mc","stem":"「낭송을 잘한다는 것」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뒤에 앉은 사람까지 들리게, 부분마다 마음에 맞는 크기로 읽어 시의 마음이 건너가게 하는 것","correct":true},{"t":"마음과 상관없이 무조건 크게 읽는 것","mis":"K6-2-u6-X21"},{"t":"음악과 영상을 많이 넣어 화려하게 꾸미는 것","mis":"K6-2-u6-X22"},{"t":"마음만 담으면 작게 읽어도 되는 것","mis":"K6-2-u6-X23"}],"explanation":["작게도, 무조건 크게도 아니에요.","꾸밈이 시를 덮으면 안 돼요.","마음이 건너가는 것이 목표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#6','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',3,'match','auto','낭송을 돕는 것과 알맞은 쓰는 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C17","difficulty":3,"kind":"match","stem":"낭송을 돕는 것과 알맞은 쓰는 방법을 이으세요.","pairs":[{"l":"효과음","r":"시의 장면과 맞닿은 소리를 아주 짧게"},{"l":"배경 음악","r":"분위기에 어울리는 것을 목소리보다 작게"},{"l":"영상이나 그림","r":"장면을 떠올리는 데 도움이 될 만큼만"}],"mis":"K6-2-u6-X22","explanation":["효과음은 짧게 써요.","배경 음악은 작게 깔아요.","영상은 도움이 될 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#7','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',3,'mc','auto','낭송회를 「낭송하는 사람과 듣는 사람이 함께 만든다」고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X24','K6-2-u6-X25']::text[],false,'{"seq":7,"concept":"K6-2-u6-C18","difficulty":3,"kind":"mc","stem":"낭송회를 「낭송하는 사람과 듣는 사람이 함께 만든다」고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 바라보며 들어 주고 구체적으로 조언해야 낭송하는 사람의 마음이 건너가고 다음에 더 나아지기 때문에","correct":true},{"t":"듣는 사람도 한 줄씩 함께 소리 내어 읽어야 하기 때문에","mis":"K6-2-u6-X24"},{"t":"듣는 사람이 틀린 글자를 찾아 주어야 하기 때문에","mis":"K6-2-u6-X24"},{"t":"듣는 사람이 「잘했어」라고만 말해 주면 되기 때문에","mis":"K6-2-u6-X25"}],"explanation":["듣는 사람이 있어야 낭송회가 돼요.","바라보며 집중해서 들어요.","구체적인 조언이 다음을 키워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#8','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C17',4,'mc','auto','「우산 하나」를 낭송하며 쓸 배경 음악으로 가장 알맞은 계획은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":8,"concept":"K6-2-u6-C17","difficulty":4,"kind":"mc","stem":"「우산 하나」를 낭송하며 쓸 배경 음악으로 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"빗소리와 어울리는 잔잔한 음악을 목소리보다 작게 깔고, 마지막 연에서는 음악을 멈춘다","correct":true},{"t":"모두가 아는 신나는 유행 노래를 목소리보다 크게 튼다","mis":"K6-2-u6-X22"},{"t":"효과음 여러 개를 쉬지 않고 계속 튼다","mis":"K6-2-u6-X22"},{"t":"음악만 틀고 낭송은 하지 않는다","mis":"K6-2-u6-X22"}],"explanation":["분위기에 어울리는 음악을 골라요.","목소리보다 작게 깔아요.","젖은 어깨의 마음이 들리게 비워 두기도 해요."],"asset":{"type":"passage","lines":["우산이 하나뿐이어서 / 네 쪽으로 기울였다","집에 와서 보니 / 내 왼쪽 어깨만 / 다 젖어 있었다"],"title":"시 「우산 하나」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#9','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C16',4,'essay','teacher','「우유갑」을 낭송한다고 생각하고, 전하고 싶은 마음을 한 문장으로 쓴 뒤, 첫 연과 마지막 연을 각각 어떤 목소리와 속도로 읽을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C16","difficulty":4,"kind":"essay","stem":"「우유갑」을 낭송한다고 생각하고, 전하고 싶은 마음을 한 문장으로 쓴 뒤, 첫 연과 마지막 연을 각각 어떤 목소리와 속도로 읽을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 전하고 싶은 마음 — 엄마한테 삐친 마음이 조금은 풀리기를 바라는 마음. 첫 연 「우유갑 모서리를 / 손톱으로 톡, 톡」은 손끝으로 조심조심 두드리는 장면이라 작고 또렷하게, 톡, 톡을 끊어 읽는다. 마지막 연 「꼭 이만큼만 / 열렸으면」은 바라는 마음이 담겨 있어 천천히, 조금 낮추어 한 음절씩 힘을 실어 읽는다.","scoring_points":["전하고 싶은 마음을 한 문장으로 썼는가","두 연의 목소리와 속도를 정했는가","그 부분의 마음과 이어 까닭을 썼는가"]},"explanation":["마음을 먼저 정해요.","부분마다 목소리를 정해요.","까닭은 그 부분의 마음이에요."],"asset":{"type":"passage","lines":["우유갑 모서리를 / 손톱으로 톡, 톡","작은 문 하나가 / 겨우 열린다","오늘 아침 / 엄마한테 삐친 내 마음도","꼭 이만큼만 / 열렸으면"],"title":"시 「우유갑」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L06_challenge#10','kor',6,2,'u6','L06','g6_2_kor_u6_L06_challenge','lesson_challenge','K6-2-u6-C18',4,'essay','teacher','친구가 「바통」을 낭송했는데, 처음부터 끝까지 같은 속도로 빠르게 읽었어요. 이 친구에게 해 줄 조언을 잘한 점 하나와 고칠 점 하나를 넣어 구체적으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C18","difficulty":4,"kind":"essay","stem":"친구가 「바통」을 낭송했는데, 처음부터 끝까지 같은 속도로 빠르게 읽었어요. 이 친구에게 해 줄 조언을 잘한 점 하나와 고칠 점 하나를 넣어 구체적으로 쓰세요.","answer_guide":{"answer":"예: 뒤에 앉은 나에게도 또렷하게 들려서 좋았어. 그런데 「바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다」는 조마조마한 마음이 담긴 부분이니까, 거기서는 조금 느리게, 숨을 고르듯 읽으면 걱정하는 마음이 더 잘 건너올 것 같아. 마지막 연은 지금처럼 빠르게 읽으면 달려 나가는 느낌이 살아날 거야.","scoring_points":["잘한 점을 구체적으로 짚었는가","고칠 부분과 방법을 함께 썼는가","그 부분의 마음과 이어 조언했는가"]},"explanation":["잘한 점부터 말해요.","어느 부분을 어떻게 할지 말해요.","까닭은 그 부분의 마음이에요."],"asset":{"type":"passage","lines":["운동회 이어달리기 / 내 앞 주자가 달려온다 / 손바닥이 자꾸 젖는다","바통은 아직 저기 있는데 / 내 손 안에서 / 벌써 백 번은 미끄러졌다","호루라기 소리보다 / 내 심장이 먼저 울린다","바통을 쥐는 순간 / 젖은 손이 마르고 / 운동장이 앞으로 뛰어온다"],"title":"시 「바통」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#1','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C20',1,'mc','auto','널리 알려진 이야기를 일부러 비틀어 새로운 뜻을 담아내는 것을 무엇이라고 하나요?',ARRAY['K6-2-u6-X26','K6-2-u6-X31']::text[],false,'{"seq":1,"concept":"K6-2-u6-C20","difficulty":1,"kind":"mc","stem":"널리 알려진 이야기를 일부러 비틀어 새로운 뜻을 담아내는 것을 무엇이라고 하나요?","options":[{"t":"패러디","correct":true},{"t":"표절","mis":"K6-2-u6-X26"},{"t":"일기","mis":"K6-2-u6-X31"},{"t":"낭송","mis":"K6-2-u6-X26"}],"explanation":["원래 이야기를 밝히고 일부러 바꿔요.","바뀐 곳에서 새로운 뜻이 생겨요.","이것을 패러디라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#2','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C21',1,'mc','auto','㉮에서 나무꾼이 세 도끼를 모두 받게 된 까닭은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X33']::text[],false,'{"seq":2,"concept":"K6-2-u6-C21","difficulty":1,"kind":"mc","stem":"㉮에서 나무꾼이 세 도끼를 모두 받게 된 까닭은 무엇인가요?","options":[{"t":"제 것이 아닌 도끼를 제 것이라고 하지 않아서","correct":true},{"t":"산신령이 낸 힘겨루기에서 이겨서","mis":"K6-2-u6-X07"},{"t":"세 도끼를 모두 달라고 간절히 빌어서","mis":"K6-2-u6-X33"},{"t":"이웃보다 나무를 많이 해서","mis":"K6-2-u6-X07"}],"explanation":["산신령이 무엇을 칭찬했는지 봐요.","나무꾼은 금도끼도 은도끼도 제 것이 아니라고 했어요.","사건은 정직함에서 시작돼요."],"asset":{"type":"passage","lines":["옛날 어느 산 아래 마을에 나무꾼이 살았다. 하루는 나무를 하다가","하나뿐인 쇠도끼를 산속 연못에 빠뜨렸다. 물살이 갈라지며","산신령이 나타나 금도끼와 은도끼를 들어 보였지만,","나무꾼은 둘 다 제 것이 아니라고 했다. 쇠도끼를 보고서야","「예, 그것이 제 도끼입니다.」 하고 반가워했다.","산신령은 정직함을 칭찬하며 세 도끼를 모두 주었다. 소문을 들은 이웃이","일부러 도끼를 던지고 금도끼를 제 것이라 했다가 제 도끼마저 잃었다."],"title":"㉮ 금도끼 은도끼"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#3','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C20',1,'ox','auto','남의 이야기를 그대로 옮기고 자기 것인 척하는 것도 패러디예요.',ARRAY['K6-2-u6-X26']::text[],false,'{"seq":3,"concept":"K6-2-u6-C20","difficulty":1,"kind":"ox","stem":"남의 이야기를 그대로 옮기고 자기 것인 척하는 것도 패러디예요.","answer":"X","reason_options":[{"t":"그대로 옮기고 자기 것인 척하는 것은 표절이기 때문에","correct":true},{"t":"널리 알려진 이야기를 썼으니 패러디이기 때문에","mis":"K6-2-u6-X26"}],"mis":"K6-2-u6-X26","explanation":["표절은 새로운 뜻이 생기지 않아요.","패러디는 원래 이야기를 밝혀요.","일부러 바꾸어 새 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#4','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C22',1,'mc','auto','㉯에서 바뀐 배경 가운데 「때」는 어느 것인가요?',ARRAY['K6-2-u6-X28','K6-2-u6-X05']::text[],false,'{"seq":4,"concept":"K6-2-u6-C22","difficulty":1,"kind":"mc","stem":"㉯에서 바뀐 배경 가운데 「때」는 어느 것인가요?","options":[{"t":"몇 해째 비가 오지 않아 마을 우물이 말라 가던 해","correct":true},{"t":"그저 옛날","mis":"K6-2-u6-X28"},{"t":"산속 연못","mis":"K6-2-u6-X05"},{"t":"나무꾼이 도끼를 빠뜨린 일","mis":"K6-2-u6-X05"}],"explanation":["㉮의 때는 그저 옛날이었어요.","산속 연못은 곳이에요.","㉯의 때는 가뭄이 든 해예요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#5','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C21',2,'mc','auto','㉯에서 나무꾼이 금도끼를 받지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u6-X33','K6-2-u6-X07']::text[],false,'{"seq":5,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"㉯에서 나무꾼이 금도끼를 받지 않은 까닭은 무엇인가요?","options":[{"t":"사람들이 몰려들면 마을의 연못이 상할까 걱정해서","correct":true},{"t":"산신령에게 벌을 받을까 봐 무서워서","mis":"K6-2-u6-X33"},{"t":"금도끼와 은도끼가 가짜인 것을 알아서","mis":"K6-2-u6-X07"},{"t":"이웃이 도끼를 빼앗을까 봐 겁이 나서","mis":"K6-2-u6-X07"}],"explanation":["나무꾼이 되물은 말을 읽어요.","마을에 마실 물이 없다고 했어요.","마을까지 생각하는 성격이 되었어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#6','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C4',2,'match','auto','요소와 ㉯에서 그 요소가 달라진 점을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C4","difficulty":2,"kind":"match","stem":"요소와 ㉯에서 그 요소가 달라진 점을 이으세요.","pairs":[{"l":"인물","r":"마을까지 함께 생각하는 사람이 되었다"},{"l":"배경","r":"가뭄이 든 해로 때가 정해졌다"},{"l":"사건","r":"상을 받는 대신 마을에 샘이 생겼다"}],"mis":"K6-2-u6-X05","explanation":["나무꾼의 생각이 넓어졌어요.","때가 가뭄이 든 해로 바뀌었어요.","일어난 일이 달라졌어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#7','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C23',2,'mc','auto','㉯의 뒤에 이어 쓸 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X27']::text[],false,'{"seq":7,"concept":"K6-2-u6-C23","difficulty":2,"kind":"mc","stem":"㉯의 뒤에 이어 쓸 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"샘 앞에 물동이가 줄을 서고 나무꾼은 차례를 정하는 일을 맡게 되었다","correct":true},{"t":"그날 밤 용이 나타나 나무꾼을 임금으로 만들어 주었다","mis":"K6-2-u6-X29"},{"t":"나무꾼은 몰래 금도끼를 가져가 부자가 되었다","mis":"K6-2-u6-X27"},{"t":"마을 사람들이 모두 다른 별로 떠났다","mis":"K6-2-u6-X29"}],"explanation":["㉯에서 마지막으로 샘이 생겼어요.","샘이 뒤의 일을 불러와요.","갑작스러운 일은 이어지지 않아요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#8','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C25',2,'ox','auto','경험을 바탕으로 쓴 이야기는 일기처럼 실제로 있었던 일만 적어야 해요.',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":8,"concept":"K6-2-u6-C25","difficulty":2,"kind":"ox","stem":"경험을 바탕으로 쓴 이야기는 일기처럼 실제로 있었던 일만 적어야 해요.","answer":"X","reason_options":[{"t":"겪은 일에서 출발하되 인물 · 배경 · 사건을 지어내도 되기 때문에","correct":true},{"t":"지어낸 부분이 있으면 이야기가 될 수 없기 때문에","mis":"K6-2-u6-X31"}],"mis":"K6-2-u6-X31","explanation":["일기는 실제로 있었던 일만 적어요.","이야기는 지어낸 부분이 있어야 해요.","겪은 일에서 출발하면 더 자세히 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#9','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C25',2,'mc','auto','이야기를 바꾸어 쓸 때 생각할 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X29','K6-2-u6-X02']::text[],false,'{"seq":9,"concept":"K6-2-u6-C25","difficulty":2,"kind":"mc","stem":"이야기를 바꾸어 쓸 때 생각할 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"원래 이야기보다 몇 배 길게 쓸지","correct":true},{"t":"인물의 성격을 어떻게 바꿀지","mis":"K6-2-u6-X35"},{"t":"앞의 일이 뒤의 일을 부르는지","mis":"K6-2-u6-X29"},{"t":"내가 잘 아는 경험을 살릴 수 있는지","mis":"K6-2-u6-X02"}],"explanation":["성격 · 때와 곳 · 원인과 결과를 생각해요.","내 경험도 살려요.","길이는 생각할 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_basic#10','kor',6,2,'u6','L07','g6_2_kor_u6_L07_basic','lesson_basic','K6-2-u6-C24',3,'mc','auto','「나무꾼이 도끼를 빠뜨리자 갑자기 하늘에서 우주선이 내려와 마을을 다른 별로 옮겼다.」를 두고 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X26']::text[],false,'{"seq":10,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"「나무꾼이 도끼를 빠뜨리자 갑자기 하늘에서 우주선이 내려와 마을을 다른 별로 옮겼다.」를 두고 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"놀랍기는 하지만 앞의 일과 이어지지 않아 잘 바꾼 것이 아니다","correct":true},{"t":"가장 기발하게 바꾸었으니 가장 잘 바꾼 이야기다","mis":"K6-2-u6-X30"},{"t":"많이 바꿀수록 좋으니 배경도 더 바꾸면 된다","mis":"K6-2-u6-X36"},{"t":"옛이야기에 우주선이 나오면 패러디가 아니다","mis":"K6-2-u6-X26"}],"explanation":["놀라움으로 가늠하지 않아요.","앞의 일이 뒤의 일을 불러야 해요.","바뀐 것에서 다음 일이 나오는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#1','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C21',2,'mc','auto','㉮와 ㉯의 나무꾼이 같은 점은 무엇인가요?',ARRAY['K6-2-u6-X07','K6-2-u6-X27']::text[],false,'{"seq":1,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"㉮와 ㉯의 나무꾼이 같은 점은 무엇인가요?","options":[{"t":"둘 다 정직하다","correct":true},{"t":"둘 다 세 도끼를 모두 받았다","mis":"K6-2-u6-X07"},{"t":"둘 다 마을의 물을 걱정했다","mis":"K6-2-u6-X27"},{"t":"둘 다 이웃에게 도끼를 빼앗겼다","mis":"K6-2-u6-X07"}],"explanation":["둘 다 금도끼를 제 것이라 하지 않았어요.","정직하다는 점은 같아요.","달라진 것은 무엇까지 생각하는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#2','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C22',2,'mc','auto','㉯에서 때를 「가뭄이 든 해」로 바꾸자 자연스러워진 것은 무엇인가요?',ARRAY['K6-2-u6-X28']::text[],false,'{"seq":2,"concept":"K6-2-u6-C22","difficulty":2,"kind":"mc","stem":"㉯에서 때를 「가뭄이 든 해」로 바꾸자 자연스러워진 것은 무엇인가요?","options":[{"t":"나무꾼이 물을 걱정하는 것","correct":true},{"t":"나무꾼이 금도끼를 받는 것","mis":"K6-2-u6-X28"},{"t":"이웃이 도끼를 연못에 던지는 것","mis":"K6-2-u6-X28"},{"t":"산신령이 나타나는 것","mis":"K6-2-u6-X28"}],"explanation":["배경이 바뀌면 할 수 있는 일이 바뀌어요.","가뭄에는 물이 가장 걱정돼요.","그래서 상을 거절하는 것도 자연스러워요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#3','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C20',3,'error','auto','패러디에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X26','K6-2-u6-X32']::text[],false,'{"seq":3,"concept":"K6-2-u6-C20","difficulty":3,"kind":"error","stem":"패러디에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준하 — 「원래 이야기를 밝히지 않고 조금만 고쳐 내 것처럼 내도 패러디야.」","correct":true,"mis_target":"K6-2-u6-X26"},{"t":"채아 — 「원래 이야기를 밝히고 일부러 바꾸는 거야.」","mis":"K6-2-u6-X26"},{"t":"세윤 — 「바뀐 곳에서 새로운 뜻이 생겨야 해.」","mis":"K6-2-u6-X32"}],"explanation":["채아와 세윤은 바르게 말했어요.","밝히지 않고 내 것처럼 내면 표절이에요.","패러디는 새로운 뜻을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#4','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C23',3,'mc','auto','㉯의 사건 흐름을 원인과 결과로 바르게 이은 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X27']::text[],false,'{"seq":4,"concept":"K6-2-u6-C23","difficulty":3,"kind":"mc","stem":"㉯의 사건 흐름을 원인과 결과로 바르게 이은 것은 어느 것인가요?","options":[{"t":"가뭄이 든 해였으므로 → 물을 먼저 걱정했고 → 그래서 상을 거절했고 → 그래서 샘이 생겼다","correct":true},{"t":"상을 거절했으므로 → 가뭄이 들었고 → 그래서 도끼를 빠뜨렸다","mis":"K6-2-u6-X29"},{"t":"도끼를 빠뜨렸으므로 → 갑자기 부자가 되었다","mis":"K6-2-u6-X29"},{"t":"샘이 생겼으므로 → 나무꾼이 금도끼를 받았다","mis":"K6-2-u6-X27"}],"explanation":["앞의 일이 뒤의 일을 불러요.","가뭄 → 걱정 → 거절 → 샘이에요.","차례가 거꾸로면 이어지지 않아요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#5','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C4',3,'ox','auto','㉯에서 배경만 바꾸고 인물의 생각과 사건은 ㉮와 똑같이 두어도 자연스러운 이야기가 돼요.',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":5,"concept":"K6-2-u6-C4","difficulty":3,"kind":"ox","stem":"㉯에서 배경만 바꾸고 인물의 생각과 사건은 ㉮와 똑같이 두어도 자연스러운 이야기가 돼요.","answer":"X","reason_options":[{"t":"배경이 바뀌면 인물이 하는 일과 사건도 함께 움직이기 때문에","correct":true},{"t":"세 요소는 따로따로라서 하나만 바꾸어도 되기 때문에","mis":"K6-2-u6-X06"}],"mis":"K6-2-u6-X06","explanation":["가뭄이 든 해라면 물이 걱정돼요.","그 걱정이 하는 일을 바꿔요.","셋은 서로 붙어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#6','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C25',3,'match','auto','두 글과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C25","difficulty":3,"kind":"match","stem":"두 글과 알맞은 설명을 이으세요.","pairs":[{"l":"일기","r":"실제로 있었던 일만 적는다"},{"l":"경험을 바탕으로 쓴 이야기","r":"겪은 일에서 출발해 인물 · 배경 · 사건을 지어낸다"},{"l":"표절한 글","r":"남의 것을 그대로 옮기고 자기 것인 척한다"}],"mis":"K6-2-u6-X31","explanation":["일기는 사실만 적어요.","이야기는 지어낸 부분이 있어요.","표절은 새 뜻이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#7','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C24',3,'mc','auto','바꾸어 쓴 이야기를 가늠하는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X32']::text[],false,'{"seq":7,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"바꾸어 쓴 이야기를 가늠하는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바뀐 것에 따라 뒤가 자연스럽게 이어지는가","correct":true},{"t":"기발한 생각을 얼마나 많이 넣었는가","mis":"K6-2-u6-X30"},{"t":"얼마나 많은 곳을 바꾸었는가","mis":"K6-2-u6-X36"},{"t":"원래 이야기보다 얼마나 길어졌는가","mis":"K6-2-u6-X32"}],"explanation":["많이 · 기발하게가 기준이 아니에요.","길이도 기준이 아니에요.","이어짐이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#8','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C26',4,'mc','auto','㉮를 ㉯로 바꾸자 새로 생긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":8,"concept":"K6-2-u6-C26","difficulty":4,"kind":"mc","stem":"㉮를 ㉯로 바꾸자 새로 생긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정직함은 나 혼자의 일이 아니라 마을을 함께 생각하는 일이기도 하다","correct":true},{"t":"정직하면 반드시 금도끼를 받는다","mis":"K6-2-u6-X32"},{"t":"욕심을 부리면 제 것도 잃는다","mis":"K6-2-u6-X32"},{"t":"산신령은 무서운 존재다","mis":"K6-2-u6-X32"}],"explanation":["㉮는 정직하면 상을 받는다는 이야기예요.","㉯는 상을 거절하고 마을에 샘이 생겨요.","정직함이 마을로 넓어졌어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#9','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C21',4,'essay','teacher','㉮와 ㉯의 나무꾼을 견주어 성격이 어떻게 달라졌는지 쓰고, 성격이 달라지자 하는 일이 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C21","difficulty":4,"kind":"essay","stem":"㉮와 ㉯의 나무꾼을 견주어 성격이 어떻게 달라졌는지 쓰고, 성격이 달라지자 하는 일이 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: ㉮의 나무꾼은 제 것이 아닌 것을 제 것이라 하지 않는 정직한 사람이고, 산신령이 주는 세 도끼를 고맙게 받는다. ㉯의 나무꾼도 정직하지만, 받기 전에 마을에 무슨 일이 생길지 먼저 생각하는 사람이다. 그래서 금도끼를 얻으려고 사람들이 몰려오면 연못이 상할 것을 걱정해 상을 거절하고 쇠도끼만 받는다. 성격이 달라지자 하는 일이 달라졌다.","scoring_points":["두 나무꾼의 같은 점을 썼는가","성격이 어떻게 달라졌는지 썼는가","성격 때문에 하는 일이 달라졌다고 이어 썼는가"]},"explanation":["같은 점부터 찾아요.","무엇까지 생각하는지 견주어요.","성격이 바뀌면 하는 일이 바뀌어요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L07_challenge#10','kor',6,2,'u6','L07','g6_2_kor_u6_L07_challenge','lesson_challenge','K6-2-u6-C24',4,'essay','teacher','「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 우주선이 내려오는 이야기와 ㉯를 견주어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C24","difficulty":4,"kind":"essay","stem":"「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 우주선이 내려오는 이야기와 ㉯를 견주어 설명하세요.","answer_guide":{"answer":"예: 우주선이 내려와 마을을 다른 별로 옮기는 이야기는 놀랍기는 하지만 도끼를 빠뜨린 앞의 일과 아무 상관이 없어 이어지지 않는다. ㉯는 때를 가뭄이 든 해로 하나 바꾸었을 뿐인데, 그래서 나무꾼이 물을 걱정하고, 그래서 상을 거절하고, 그래서 샘이 생기는 일이 앞이 뒤를 부르며 자연스럽게 이어진다. 그러므로 이야기를 바꿀 때에는 얼마나 많이·놀랍게 바꾸었는가가 아니라 바뀐 것에서 다음 일이 자연스럽게 나오는가로 가늠해야 한다.","scoring_points":["우주선 이야기가 이어지지 않는 까닭을 썼는가","㉯에서 앞이 뒤를 부르는 흐름을 썼는가","가늠하는 기준을 이어짐으로 썼는가"]},"explanation":["놀라움은 기준이 아니에요.","앞이 뒤를 부르는지 봐요.","이어짐이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#1','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',1,'mc','auto','「토끼와 자라」에서 토끼가 살아서 돌아올 수 있었던 까닭은 무엇인가요?',ARRAY['K6-2-u6-X33','K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C27","difficulty":1,"kind":"mc","stem":"「토끼와 자라」에서 토끼가 살아서 돌아올 수 있었던 까닭은 무엇인가요?","options":[{"t":"간을 산에 두고 왔다고 둘러대어 용왕을 믿게 해서","correct":true},{"t":"자라보다 헤엄을 잘 쳐서","mis":"K6-2-u6-X33"},{"t":"용왕의 병을 고칠 다른 약을 찾아 주어서","mis":"K6-2-u6-X07"},{"t":"용궁의 신하들과 싸워 이겨서","mis":"K6-2-u6-X07"}],"explanation":["토끼가 용궁에서 한 말을 읽어요.","간을 볕에 말리려고 두고 왔다고 했어요.","토끼는 말로 자기를 지켰어요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#2','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C26',1,'mc','auto','이야기를 바꾸어 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":2,"concept":"K6-2-u6-C26","difficulty":1,"kind":"mc","stem":"이야기를 바꾸어 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바뀐 곳에서 새로운 뜻이 생기기 때문에","correct":true},{"t":"글을 원래보다 길게 늘리기 위해서","mis":"K6-2-u6-X32"},{"t":"원래 이야기를 그대로 외우기 위해서","mis":"K6-2-u6-X32"},{"t":"어려운 낱말을 많이 쓰기 위해서","mis":"K6-2-u6-X32"}],"explanation":["정직하면 상을 받는다던 이야기가 있었어요.","바꾸자 정직함이 마을로 넓어졌어요.","새로운 뜻이 생기는 것이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#3','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',1,'mc','auto','이야기에서 가장 긴장되는 순간을 무엇이라고 하나요?',ARRAY['K6-2-u6-X34','K6-2-u6-X05']::text[],false,'{"seq":3,"concept":"K6-2-u6-C27","difficulty":1,"kind":"mc","stem":"이야기에서 가장 긴장되는 순간을 무엇이라고 하나요?","options":[{"t":"절정","correct":true},{"t":"발단","mis":"K6-2-u6-X34"},{"t":"전개","mis":"K6-2-u6-X34"},{"t":"배경","mis":"K6-2-u6-X05"}],"explanation":["발단은 일이 시작되는 곳이에요.","전개는 일이 커지는 곳이에요.","가장 긴장되는 순간이 절정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#4','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',1,'ox','auto','이야기를 바꿀 때 인물 · 배경 · 사건 가운데 하나만 골라 바꾸어도 충분해요.',ARRAY['K6-2-u6-X36']::text[],false,'{"seq":4,"concept":"K6-2-u6-C28","difficulty":1,"kind":"ox","stem":"이야기를 바꿀 때 인물 · 배경 · 사건 가운데 하나만 골라 바꾸어도 충분해요.","answer":"O","reason_options":[{"t":"하나를 바꾸면 나머지가 따라 움직이기 때문에","correct":true},{"t":"셋을 모두 바꾸어야 제대로 바꾼 것이기 때문에","mis":"K6-2-u6-X36"}],"mis":"K6-2-u6-X36","explanation":["셋은 서로 붙어 있어요.","하나를 바꾸면 나머지도 움직여요.","그래서 하나만 바꾸어도 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#5','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',2,'match','auto','인물과 그 성격이 드러난 곳을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u6-C27","difficulty":2,"kind":"match","stem":"인물과 그 성격이 드러난 곳을 이으세요.","pairs":[{"l":"토끼","r":"놀라지 않은 척하며 둘러댄다"},{"l":"자라","r":"혼자 나서서 뭍까지 올라간다"},{"l":"용왕","r":"들은 말을 그대로 믿는다"}],"mis":"K6-2-u6-X33","explanation":["성격은 인물이 한 일에서 드러나요.","토끼는 급할수록 머리가 잘 돌아가요.","용왕은 낫고 싶은 마음이 앞서요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#6','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C27',2,'mc','auto','「토끼와 자라」의 발단으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":6,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「토끼와 자라」의 발단으로 알맞은 것은 어느 것인가요?","options":[{"t":"용왕이 병이 들고, 토끼의 간이 약이라는 말이 돈다","correct":true},{"t":"자라가 뭍에 올라 토끼를 꾀어 용궁으로 데려간다","mis":"K6-2-u6-X34"},{"t":"토끼가 간을 두고 왔다고 둘러댄다","mis":"K6-2-u6-X34"},{"t":"뭍에 내린 토끼가 달아난다","mis":"K6-2-u6-X34"}],"explanation":["발단은 일이 시작되는 곳이에요.","용왕의 병에서 모든 일이 시작돼요.","꾀어 데려가는 것은 전개예요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#7','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',2,'mc','auto','자라의 성격을 「스스로 따져 보는 성격」으로 바꾸면 함께 손봐야 할 것은 어느 것인가요?',ARRAY['K6-2-u6-X35']::text[],false,'{"seq":7,"concept":"K6-2-u6-C28","difficulty":2,"kind":"mc","stem":"자라의 성격을 「스스로 따져 보는 성격」으로 바꾸면 함께 손봐야 할 것은 어느 것인가요?","options":[{"t":"자라가 토끼에게 하는 말","correct":true},{"t":"바닷속이라는 공간","mis":"K6-2-u6-X35"},{"t":"이야기의 글자 수","mis":"K6-2-u6-X35"},{"t":"아무것도 손볼 필요가 없다","mis":"K6-2-u6-X35"}],"explanation":["자라가 사실대로 말하게 돼요.","그러면 토끼의 행동과 끝도 바뀌어요.","바꾼 것에 닿아 있던 곳을 손봐요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#8','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C29',2,'ox','auto','바꾼 이야기의 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 좋아요.',ARRAY['K6-2-u6-X37']::text[],false,'{"seq":8,"concept":"K6-2-u6-C29","difficulty":2,"kind":"ox","stem":"바꾼 이야기의 첫 문장은 바뀐 것이 드러나는 곳에서 시작하면 좋아요.","answer":"O","reason_options":[{"t":"읽는 사람이 무엇이 바뀌었는지 금방 알아채기 때문에","correct":true},{"t":"첫 문장은 원래 이야기와 똑같아야 하기 때문에","mis":"K6-2-u6-X37"}],"mis":"K6-2-u6-X37","explanation":["바뀐 것이 첫 문장에 보이면 좋아요.","읽는 사람이 금방 알아채요.","제목도 바뀐 것이 드러나게 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#9','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C30',2,'mc','auto','친구의 이야기에 붙일 칭찬 쪽지로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X25']::text[],false,'{"seq":9,"concept":"K6-2-u6-C30","difficulty":2,"kind":"mc","stem":"친구의 이야기에 붙일 칭찬 쪽지로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자라가 사실대로 말하는 부분에서 마음이 바뀐 것이 잘 드러나 인상 깊었어","correct":true},{"t":"잘 썼어. 다음에도 이렇게 써","mis":"K6-2-u6-X25"},{"t":"글씨를 또박또박 써서 읽기 편했어","mis":"K6-2-u6-X25"},{"t":"재미있어","mis":"K6-2-u6-X25"}],"explanation":["어느 부분이 좋았는지 짚어요.","왜 좋았는지 까닭을 붙여요.","잘 썼어에서 멈추지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_basic#10','kor',6,2,'u6','L09','g6_2_kor_u6_L09_basic','lesson_basic','K6-2-u6-C28',3,'mc','auto','자라를 「스스로 따져 보는 성격」으로 바꾼 계획으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X29','K6-2-u6-X36']::text[],false,'{"seq":10,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"자라를 「스스로 따져 보는 성격」으로 바꾼 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"데려가는 길에 마음이 걸려 토끼에게 사정을 사실대로 말한다","correct":true},{"t":"성격은 바뀌었지만 여전히 아무 말 없이 토끼를 속여 데려간다","mis":"K6-2-u6-X27"},{"t":"가는 길에 갑자기 벼락이 쳐 용왕의 병이 저절로 나았다","mis":"K6-2-u6-X29"},{"t":"자라는 그대로 두고 토끼와 용왕과 바다를 모두 바꾼다","mis":"K6-2-u6-X36"}],"explanation":["성격을 바꾸었으면 행동도 바뀌어야 해요.","갑작스러운 일은 이어지지 않아요.","하나를 바꾸고 따라 움직이게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#1','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C27',2,'mc','auto','「토끼와 자라」의 전개로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X34']::text[],false,'{"seq":1,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"「토끼와 자라」의 전개로 알맞은 것은 어느 것인가요?","options":[{"t":"자라가 뭍에 올라 토끼를 꾀어 용궁으로 데려간다","correct":true},{"t":"용왕이 병이 들고 토끼의 간이 약이라는 말이 돈다","mis":"K6-2-u6-X34"},{"t":"토끼가 간을 산에 두고 왔다고 둘러댄다","mis":"K6-2-u6-X34"},{"t":"뭍에 내린 토끼가 풀숲으로 달아난다","mis":"K6-2-u6-X34"}],"explanation":["발단은 용왕의 병이에요.","절정은 토끼가 둘러대는 순간이에요.","꾀어 데려가는 것이 전개예요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#2','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C29',2,'mc','auto','자라 바꾸기 계획에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":2,"concept":"K6-2-u6-C29","difficulty":2,"kind":"mc","stem":"자라 바꾸기 계획에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자라가 입을 열었다","correct":true},{"t":"토끼와 자라","mis":"K6-2-u6-X18"},{"t":"바닷속 이야기","mis":"K6-2-u6-X18"},{"t":"토끼의 간","mis":"K6-2-u6-X18"}],"explanation":["원래 제목은 바뀐 것을 드러내지 못해요.","자라가 사실대로 말한 것이 바뀐 곳이에요.","그것이 드러나는 제목이 좋아요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#3','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',3,'error','auto','자라 바꾸기 계획을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X36']::text[],false,'{"seq":3,"concept":"K6-2-u6-C28","difficulty":3,"kind":"error","stem":"자라 바꾸기 계획을 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"세윤 — 「자라 성격만 바꿨으니 토끼가 하는 일은 손볼 필요 없어.」","correct":true,"mis_target":"K6-2-u6-X35"},{"t":"채아 — 「자라가 사실대로 말하면 토끼는 달아날 까닭이 없어지니까 토끼 행동도 바뀌어.」","mis":"K6-2-u6-X35"},{"t":"지오 — 「배경이랑 용왕 성격은 그대로 두어도 돼.」","mis":"K6-2-u6-X36"}],"explanation":["채아와 지오는 바르게 말했어요.","하나를 바꾸면 거기에 닿아 있던 곳이 함께 움직여요.","세윤은 손볼 곳을 놓쳤어요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#4','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',3,'mc','auto','자라 바꾸기 계획에서 「그대로 두는 것」으로 정한 것은 무엇인가요?',ARRAY['K6-2-u6-X35']::text[],false,'{"seq":4,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"자라 바꾸기 계획에서 「그대로 두는 것」으로 정한 것은 무엇인가요?","options":[{"t":"배경(바닷속 용궁과 산)과 용왕의 성격","correct":true},{"t":"자라의 성격","mis":"K6-2-u6-X35"},{"t":"토끼가 하는 일","mis":"K6-2-u6-X35"},{"t":"이야기의 마지막","mis":"K6-2-u6-X35"}],"explanation":["자라의 성격은 바꿀 것이에요.","토끼의 행동과 마지막은 따라 바뀌어요.","배경과 용왕은 그대로 두었어요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#5','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C27',3,'ox','auto','「토끼와 자라」를 바꿀 때 인물의 성격을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보여요.',ARRAY['K6-2-u6-X33']::text[],false,'{"seq":5,"concept":"K6-2-u6-C27","difficulty":3,"kind":"ox","stem":"「토끼와 자라」를 바꿀 때 인물의 성격을 먼저 정리해 두면 무엇을 바꿀 수 있는지가 보여요.","answer":"O","reason_options":[{"t":"성격이 그 인물이 한 일을 낳으므로 바꿀 곳이 눈에 띄기 때문에","correct":true},{"t":"성격은 이야기와 상관없으니 아무렇게나 정해도 되기 때문에","mis":"K6-2-u6-X33"}],"mis":"K6-2-u6-X33","explanation":["성격은 인물이 한 일에서 드러나요.","성격을 바꾸면 한 일이 바뀌어요.","그래서 먼저 정리해 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#6','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C27',3,'match','auto','이야기의 차례와 「토끼와 자라」의 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C27","difficulty":3,"kind":"match","stem":"이야기의 차례와 「토끼와 자라」의 일을 이으세요.","pairs":[{"l":"발단","r":"용왕이 병이 들고 토끼의 간이 약이라는 말이 돈다"},{"l":"전개","r":"자라가 토끼를 꾀어 용궁으로 데려간다"},{"l":"절정","r":"토끼가 간을 두고 왔다고 둘러댄다"}],"mis":"K6-2-u6-X34","explanation":["일이 시작되는 곳이 발단이에요.","일이 커지는 곳이 전개예요.","가장 긴장되는 순간이 절정이에요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#7','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C30',3,'mc','auto','칭찬 쪽지를 「잘 썼어 · 재미있어」에서 멈추지 말아야 하는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X42']::text[],false,'{"seq":7,"concept":"K6-2-u6-C30","difficulty":3,"kind":"mc","stem":"칭찬 쪽지를 「잘 썼어 · 재미있어」에서 멈추지 말아야 하는 까닭은 무엇인가요?","options":[{"t":"어느 부분이 왜 좋았는지 알아야 친구가 무엇을 잘했는지 알 수 있기 때문에","correct":true},{"t":"칭찬 쪽지는 길게 써야 점수를 받기 때문에","mis":"K6-2-u6-X25"},{"t":"잘했다는 말은 하면 안 되기 때문에","mis":"K6-2-u6-X25"},{"t":"고칠 점만 써야 도움이 되기 때문에","mis":"K6-2-u6-X42"}],"explanation":["막연한 칭찬은 무엇을 잘했는지 알려 주지 않아요.","어느 부분인지 짚어요.","왜 좋았는지 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#8','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C23',4,'mc','auto','자라 바꾸기 계획의 흐름이 이어지는지 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X36','K6-2-u6-X27']::text[],false,'{"seq":8,"concept":"K6-2-u6-C23","difficulty":4,"kind":"mc","stem":"자라 바꾸기 계획의 흐름이 이어지는지 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"자라가 사실대로 말했으므로 토끼가 달아날 까닭이 없고, 그래서 함께 약을 찾고, 그래서 약초를 찾아내어 앞이 뒤를 부른다","correct":true},{"t":"토끼가 하늘을 날아 모두를 구해야 더 재미있게 이어진다","mis":"K6-2-u6-X29"},{"t":"바꾼 곳이 하나뿐이라 이어지지 않는다","mis":"K6-2-u6-X36"},{"t":"자라는 바꾸었지만 토끼는 여전히 거짓말로 달아나야 이어진다","mis":"K6-2-u6-X27"}],"explanation":["사실대로 말한 것이 원인이에요.","함께 약을 찾는 것이 결과예요.","앞이 뒤를 부르며 이어져요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#9','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C28',4,'essay','teacher','「토끼와 자라」에서 토끼의 성격을 「겁이 많은 성격」에서 「겁이 없는 성격」으로 바꾼다고 할 때, 그 때문에 달라질 전개 · 절정 · 마지막을 차례대로 쓰고, 그대로 둘 것을 하나 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C28","difficulty":4,"kind":"essay","stem":"「토끼와 자라」에서 토끼의 성격을 「겁이 많은 성격」에서 「겁이 없는 성격」으로 바꾼다고 할 때, 그 때문에 달라질 전개 · 절정 · 마지막을 차례대로 쓰고, 그대로 둘 것을 하나 쓰세요.","answer_guide":{"answer":"예: 바꿀 것 — 토끼의 성격을 겁이 없는 성격으로. 전개 — 자라를 따라 용궁에 간 토끼는 사정을 듣고도 떨지 않는다. 절정 — 토끼는 둘러대는 대신 용왕 앞에서 「제 간을 내놓으면 저는 죽습니다. 다른 약을 함께 찾아봅시다.」 하고 당당하게 말한다. 마지막 — 용왕은 토끼의 말에 부끄러워하고, 토끼와 자라가 함께 바닷속 약초를 찾는다. 그대로 둘 것 — 배경(바닷속 용궁과 산).","scoring_points":["바꿀 것을 하나 정했는가","성격 때문에 달라질 일을 차례대로 이어 썼는가","그대로 둘 것을 썼는가"]},"explanation":["하나만 바꿔요.","성격이 바뀌면 행동이 바뀌어요.","그대로 둘 것도 정해요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L09_challenge#10','kor',6,2,'u6','L09','g6_2_kor_u6_L09_challenge','lesson_challenge','K6-2-u6-C30',4,'essay','teacher','친구가 자라 바꾸기 계획대로 이야기를 썼어요. 이 이야기에 붙일 칭찬 쪽지를 어느 부분이 왜 좋았는지 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C30","difficulty":4,"kind":"essay","stem":"친구가 자라 바꾸기 계획대로 이야기를 썼어요. 이 이야기에 붙일 칭찬 쪽지를 어느 부분이 왜 좋았는지 드러나게 쓰세요.","answer_guide":{"answer":"예: 자라가 토끼를 등에 태우고 가다가 「사실은 너를 데려가는 까닭이 따로 있어.」 하고 입을 여는 부분이 가장 인상 깊었어. 맡은 일만 하던 자라가 스스로 따져 보는 자라로 바뀐 것이 그 한마디에 잘 드러났고, 그래서 토끼가 달아나지 않고 함께 약을 찾는 것도 자연스럽게 이어졌어.","scoring_points":["좋았던 부분을 콕 집었는가","왜 좋았는지 까닭을 붙였는가","겉모습이 아니라 이야기 내용을 칭찬했는가"]},"explanation":["어느 부분인지 짚어요.","왜 좋았는지 써요.","글씨가 아니라 이야기를 봐요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#1','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',1,'mc','auto','낭송한 목소리와 속도를 그대로 남길 수 있는 책의 형태는 어느 것인가요?',ARRAY['K6-2-u6-X38']::text[],false,'{"seq":1,"concept":"K6-2-u6-C31","difficulty":1,"kind":"mc","stem":"낭송한 목소리와 속도를 그대로 남길 수 있는 책의 형태는 어느 것인가요?","options":[{"t":"소리로 담는 책","correct":true},{"t":"종이책","mis":"K6-2-u6-X38"},{"t":"화면으로 보는 책","mis":"K6-2-u6-X38"},{"t":"표지만 있는 책","mis":"K6-2-u6-X38"}],"explanation":["종이책은 아무 때나 넘겨 봐요.","화면으로 보는 책은 멀리 보낼 수 있어요.","소리로 담는 책은 목소리를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#2','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',1,'ox','auto','책의 세 형태 가운데 가장 좋은 형태가 하나 정해져 있어요.',ARRAY['K6-2-u6-X38']::text[],false,'{"seq":2,"concept":"K6-2-u6-C31","difficulty":1,"kind":"ox","stem":"책의 세 형태 가운데 가장 좋은 형태가 하나 정해져 있어요.","answer":"X","reason_options":[{"t":"형태마다 알맞은 자리가 서로 다를 뿐이기 때문에","correct":true},{"t":"화면으로 보는 책이 언제나 가장 좋기 때문에","mis":"K6-2-u6-X38"}],"mis":"K6-2-u6-X38","explanation":["종이책 · 소리로 담는 책 · 화면으로 보는 책이 있어요.","형태마다 잘하는 일이 달라요.","더 나은 형태는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#3','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',1,'mc','auto','「끈이나 줄을 묶다」라는 뜻의 낱말은 어느 것인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":3,"concept":"K6-2-u6-C34","difficulty":1,"kind":"mc","stem":"「끈이나 줄을 묶다」라는 뜻의 낱말은 어느 것인가요?","options":[{"t":"매다","correct":true},{"t":"메다","mis":"K6-2-u6-X43"},{"t":"맺다","mis":"K6-2-u6-X43"},{"t":"바치다","mis":"K6-2-u6-X43"}],"explanation":["메다는 어깨에 걸쳐 지는 거예요.","바치다는 웃어른께 올리는 거예요.","끈을 묶는 것은 매다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#4','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C32',1,'mc','auto','실을 글을 쓰기 전에 정해 두어야 할 것은 어느 것인가요?',ARRAY['K6-2-u6-X40']::text[],false,'{"seq":4,"concept":"K6-2-u6-C32","difficulty":1,"kind":"mc","stem":"실을 글을 쓰기 전에 정해 두어야 할 것은 어느 것인가요?","options":[{"t":"일이 일어난 때와 곳","correct":true},{"t":"책 표지에 쓸 색깔","mis":"K6-2-u6-X40"},{"t":"글자를 몇 자나 쓸지","mis":"K6-2-u6-X40"},{"t":"그림을 몇 장 넣을지","mis":"K6-2-u6-X40"}],"explanation":["표지 색과 글자 수는 먼저 정할 것이 아니에요.","중심 사건 · 인물 · 때와 곳 · 차례를 정해요.","그러면 글이 빨리 써져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#5','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',2,'mc','auto','세윤이네 모둠이 책의 형태를 정할 때 가장 먼저 생각한 것은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":5,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"세윤이네 모둠이 책의 형태를 정할 때 가장 먼저 생각한 것은 무엇인가요?","options":[{"t":"누가 읽을지","correct":true},{"t":"가장 새롭고 멋있어 보이는 형태인지","mis":"K6-2-u6-X38"},{"t":"가장 빨리 끝낼 수 있는 형태인지","mis":"K6-2-u6-X38"},{"t":"표지를 어떻게 꾸밀지","mis":"K6-2-u6-X39"}],"explanation":["세윤이가 가장 먼저 물었어요.","읽을 사람을 독자라고 해요.","독자가 정해지면 형태가 따라와요."],"asset":{"type":"speech","turns":[{"who":"세윤","text":"우리 책은 누가 읽게 될까? 그것부터 정하자."},{"who":"채아","text":"우리 반 친구들이랑, 가정에 계신 분들께도 보여 드리면 좋겠어."},{"who":"지오","text":"그러면 집에서도 볼 수 있어야 하니까 화면으로 보는 책이 낫겠다."},{"who":"채아","text":"낭송한 시도 넣고 싶은데. 그럼 소리도 같이 담을 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#6','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C31',2,'match','auto','책의 형태와 그 형태가 잘하는 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C31","difficulty":2,"kind":"match","stem":"책의 형태와 그 형태가 잘하는 일을 이으세요.","pairs":[{"l":"종이책","r":"교실에 두고 아무 때나 넘겨 본다"},{"l":"소리로 담는 책","r":"낭송의 목소리와 속도를 그대로 남긴다"},{"l":"화면으로 보는 책","r":"멀리 있는 사람에게 바로 보낸다"}],"mis":"K6-2-u6-X38","explanation":["형태마다 잘하는 일이 따로 있어요.","등수가 아니라 자리가 달라요.","독자와 내용에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#7','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C33',2,'ox','auto','표지를 사흘 동안 꾸미고 글은 마지막 날 급히 쓰는 것이 좋은 방법이에요.',ARRAY['K6-2-u6-X41']::text[],false,'{"seq":7,"concept":"K6-2-u6-C33","difficulty":2,"kind":"ox","stem":"표지를 사흘 동안 꾸미고 글은 마지막 날 급히 쓰는 것이 좋은 방법이에요.","answer":"X","reason_options":[{"t":"이야기를 먼저 완성하고 꾸미기는 돕는 만큼만 해야 하기 때문에","correct":true},{"t":"책은 표지가 화려해야 잘한 책이기 때문에","mis":"K6-2-u6-X41"}],"mis":"K6-2-u6-X41","explanation":["책은 담긴 이야기로 남아요.","꾸미기는 읽기 좋게 돕는 만큼만 해요.","이야기가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#8','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C34',2,'mc','auto','빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「무거운 가방을 어깨에 (   ) 걸었다.」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":2,"kind":"mc","stem":"빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「무거운 가방을 어깨에 (   ) 걸었다.」","options":[{"t":"메고","correct":true},{"t":"매고","mis":"K6-2-u6-X43"},{"t":"받치고","mis":"K6-2-u6-X43"},{"t":"부치고","mis":"K6-2-u6-X43"}],"explanation":["어깨에 걸쳐 지는 것은 메다예요.","매다는 끈을 묶는 거예요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#9','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C32',2,'mc','auto','경험을 바탕으로 학급 이야기책에 실을 글을 쓸 때 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":9,"concept":"K6-2-u6-C32","difficulty":2,"kind":"mc","stem":"경험을 바탕으로 학급 이야기책에 실을 글을 쓸 때 알맞은 것은 어느 것인가요?","options":[{"t":"겪은 일에서 출발하되 인물과 배경은 지어내도 된다","correct":true},{"t":"일기를 그대로 옮겨 적어야 한다","mis":"K6-2-u6-X31"},{"t":"겪은 일과 상관없는 것만 써야 한다","mis":"K6-2-u6-X31"},{"t":"인물의 이름은 꼭 실제 친구 이름이어야 한다","mis":"K6-2-u6-X31"}],"explanation":["일기를 옮겨 적는 것이 아니에요.","겪은 일에서 출발해요.","인물과 배경은 지어내도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_basic#10','kor',6,2,'u6','L12','g6_2_kor_u6_L12_basic','lesson_basic','K6-2-u6-C33',3,'error','auto','학급 이야기책을 만들며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X42']::text[],false,'{"seq":10,"concept":"K6-2-u6-C33","difficulty":3,"kind":"error","stem":"학급 이야기책을 만들며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지오 — 「글은 짧아도 되니까 그림에 시간을 다 쓰자.」","correct":true,"mis_target":"K6-2-u6-X41"},{"t":"세윤 — 「이야기를 먼저 끝내고 남는 시간에 꾸미자.」","mis":"K6-2-u6-X41"},{"t":"채아 — 「잘한 점은 글에서 찾아 말해 주자.」","mis":"K6-2-u6-X42"}],"explanation":["세윤과 채아는 바르게 말했어요.","지오는 꾸미기가 이야기를 덮게 했어요.","이야기가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#1','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',2,'mc','auto','빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「흔들리는 책상 밑에 종이를 (   ).」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":1,"concept":"K6-2-u6-C34","difficulty":2,"kind":"mc","stem":"빈칸에 들어갈 알맞은 낱말은 어느 것인가요? 「흔들리는 책상 밑에 종이를 (   ).」","options":[{"t":"받쳤다","correct":true},{"t":"바쳤다","mis":"K6-2-u6-X43"},{"t":"부쳤다","mis":"K6-2-u6-X43"},{"t":"맸다","mis":"K6-2-u6-X43"}],"explanation":["바치다는 웃어른께 올리는 거예요.","밑에서 괴어 기울지 않게 하는 것은 받치다예요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#2','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C33',2,'mc','auto','함께 책을 만들 때 먼저 정할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X42']::text[],false,'{"seq":2,"concept":"K6-2-u6-C33","difficulty":2,"kind":"mc","stem":"함께 책을 만들 때 먼저 정할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 무엇을 언제까지 맡을지","correct":true},{"t":"누구 그림이 가장 화려한지","mis":"K6-2-u6-X41"},{"t":"다 만든 뒤 누구 글이 가장 못했는지","mis":"K6-2-u6-X42"},{"t":"표지에 누구 이름을 가장 크게 쓸지","mis":"K6-2-u6-X42"}],"explanation":["누구와 · 무엇을 · 언제까지를 정해요.","다 만든 뒤에는 잘한 점부터 이야기해요.","목적은 함께 쓰고 나누는 즐거움이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#3','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',3,'mc','auto','채아가 「낭송한 시도 넣고 싶다」고 할 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":3,"concept":"K6-2-u6-C31","difficulty":3,"kind":"mc","stem":"채아가 「낭송한 시도 넣고 싶다」고 할 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"소리를 함께 담을 수 있는 형태를 고르거나, 화면으로 보는 책에 낭송 소리를 덧붙인다","correct":true},{"t":"화면으로 보는 책이 제일 좋으니 소리는 빼자","mis":"K6-2-u6-X38"},{"t":"종이책이 가장 좋은 형태니까 종이책으로 하자","mis":"K6-2-u6-X38"},{"t":"누가 읽을지는 상관없으니 아무 형태나 고르자","mis":"K6-2-u6-X39"}],"explanation":["전하고 싶은 것이 낭송한 소리예요.","형태는 독자와 내용에 맞게 골라요.","형태에 등수는 없어요."],"asset":{"type":"speech","turns":[{"who":"세윤","text":"우리 책은 누가 읽게 될까? 그것부터 정하자."},{"who":"채아","text":"우리 반 친구들이랑, 가정에 계신 분들께도 보여 드리면 좋겠어."},{"who":"지오","text":"그러면 집에서도 볼 수 있어야 하니까 화면으로 보는 책이 낫겠다."},{"who":"채아","text":"낭송한 시도 넣고 싶은데. 그럼 소리도 같이 담을 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#4','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',3,'ox','auto','「고마운 마음을 담은 편지를 우체통에 붙였다.」는 바르게 쓴 문장이에요.',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":4,"concept":"K6-2-u6-C34","difficulty":3,"kind":"ox","stem":"「고마운 마음을 담은 편지를 우체통에 붙였다.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"편지를 보내는 것은 「부치다」이기 때문에","correct":true},{"t":"「붙이다」와 「부치다」는 뜻이 같기 때문에","mis":"K6-2-u6-X43"}],"mis":"K6-2-u6-X43","explanation":["붙이다는 맞닿아 떨어지지 않게 하는 거예요.","편지를 보내는 것은 부치다예요.","「부쳤다」로 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#5','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C32',3,'error','auto','실을 글을 준비하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X40']::text[],false,'{"seq":5,"concept":"K6-2-u6-C32","difficulty":3,"kind":"error","stem":"실을 글을 준비하며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"루아 — 「글자를 몇 자나 쓸지부터 정해야 글이 빨리 써져.」","correct":true,"mis_target":"K6-2-u6-X40"},{"t":"나래 — 「중심 사건이랑 인물 성격부터 정하자.」","mis":"K6-2-u6-X40"},{"t":"시후 — 「일이 일어난 때와 곳도 정해 두자.」","mis":"K6-2-u6-X40"}],"explanation":["나래와 시후는 바르게 말했어요.","글자 수는 먼저 정할 것이 아니에요.","중심 사건 · 인물 · 때와 곳 · 차례를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#6','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',3,'match','auto','낱말과 알맞은 뜻을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u6-C34","difficulty":3,"kind":"match","stem":"낱말과 알맞은 뜻을 이으세요.","pairs":[{"l":"바치다","r":"웃어른께 정중히 올리다"},{"l":"받치다","r":"밑에서 괴어 기울지 않게 하다"},{"l":"메다","r":"어깨에 걸쳐 지다"}],"mis":"K6-2-u6-X43","explanation":["소리는 같아도 뜻이 달라요.","쓰이는 자리를 떠올려요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#7','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C33',3,'mc','auto','학급 이야기책 만들기의 목적으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X42']::text[],false,'{"seq":7,"concept":"K6-2-u6-C33","difficulty":3,"kind":"mc","stem":"학급 이야기책 만들기의 목적으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰고 나누는 즐거움을 겪어 보는 것","correct":true},{"t":"가장 화려한 결과물을 만드는 것","mis":"K6-2-u6-X41"},{"t":"다른 모둠보다 빨리 끝내는 것","mis":"K6-2-u6-X42"},{"t":"친구 글의 잘못을 많이 찾는 것","mis":"K6-2-u6-X42"}],"explanation":["멋진 결과물이 목적이 아니에요.","빨리 끝내는 것도 목적이 아니에요.","쓰고 나누는 즐거움이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#8','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',4,'mc','auto','「멀리 이사 간 친구에게 우리 반 시를 들려주고 싶다」는 목적에 가장 알맞은 책의 형태와 까닭은 어느 것인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39','K6-2-u6-X41']::text[],false,'{"seq":8,"concept":"K6-2-u6-C31","difficulty":4,"kind":"mc","stem":"「멀리 이사 간 친구에게 우리 반 시를 들려주고 싶다」는 목적에 가장 알맞은 책의 형태와 까닭은 어느 것인가요?","options":[{"t":"낭송 소리를 담은 화면으로 보는 책 — 멀리 있는 친구에게 바로 보내고 목소리도 함께 전할 수 있어서","correct":true},{"t":"종이책 — 종이책이 언제나 가장 좋은 형태라서","mis":"K6-2-u6-X38"},{"t":"아무 형태나 — 누가 읽을지는 상관없어서","mis":"K6-2-u6-X39"},{"t":"표지만 화려한 책 — 꾸미기가 가장 중요해서","mis":"K6-2-u6-X41"}],"explanation":["독자는 멀리 있는 친구예요.","전하려는 것은 시의 목소리예요.","그래서 보내기 쉽고 소리를 담는 형태가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#9','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C31',4,'essay','teacher','우리 반이 만들 이야기책의 독자를 한 가지 정하고, 그 독자에게 알맞은 책의 형태를 골라 까닭을 쓰세요. 형태에 등수가 없다는 것도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u6-C31","difficulty":4,"kind":"essay","stem":"우리 반이 만들 이야기책의 독자를 한 가지 정하고, 그 독자에게 알맞은 책의 형태를 골라 까닭을 쓰세요. 형태에 등수가 없다는 것도 함께 쓰세요.","answer_guide":{"answer":"예: 독자 — 우리 학교 일학년 동생들. 형태 — 종이책. 동생들이 도서관에 두고 아무 때나 손으로 넘겨 그림과 함께 볼 수 있기 때문이다. 만약 독자가 멀리 계신 할머니라면 화면으로 보는 책이 알맞고, 눈이 불편한 분이라면 소리로 담는 책이 알맞다. 이렇게 형태에는 등수가 없고, 독자와 전하고 싶은 것에 따라 알맞은 형태가 달라진다.","scoring_points":["독자를 한 가지 정했는가","독자에게 맞는 형태와 까닭을 썼는가","형태에 등수가 없다는 것을 썼는가"]},"explanation":["독자부터 정해요.","형태가 잘하는 일과 이어요.","등수가 아니라 알맞음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_L12_challenge#10','kor',6,2,'u6','L12','g6_2_kor_u6_L12_challenge','lesson_challenge','K6-2-u6-C34',4,'essay','teacher','「바치다 · 받치다」, 「부치다 · 붙이다」 가운데 한 짝을 골라 두 낱말이 모두 들어간 짧은 글을 쓰고, 각 낱말을 그 자리에 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u6-C34","difficulty":4,"kind":"essay","stem":"「바치다 · 받치다」, 「부치다 · 붙이다」 가운데 한 짝을 골라 두 낱말이 모두 들어간 짧은 글을 쓰고, 각 낱말을 그 자리에 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니께 드릴 편지를 우체국에서 부치고, 집에 와서 편지에 넣었던 사진 한 장을 내 방 벽에 붙였다. 「부치다」는 편지나 물건을 보낼 때 쓰므로 편지를 보낸 자리에 썼고, 「붙이다」는 맞닿아 떨어지지 않게 할 때 쓰므로 사진을 벽에 댄 자리에 썼다. 소리는 같지만 뜻이 달라 앞뒤 문장을 보고 골라 써야 한다.","scoring_points":["한 짝의 두 낱말을 모두 넣었는가","각 낱말을 뜻에 맞는 자리에 썼는가","고른 까닭을 뜻으로 설명했는가"]},"explanation":["두 낱말을 다 써요.","뜻에 맞는 자리에 써요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#1','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C1',1,'mc','auto','경험을 글로 표현하면 좋은 점이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u6-X01']::text[],false,'{"seq":1,"concept":"K6-2-u6-C1","difficulty":1,"kind":"mc","stem":"경험을 글로 표현하면 좋은 점이 아닌 것은 어느 것인가요?","options":[{"t":"글씨를 예쁘게 쓰는 법을 익힐 수 있다","correct":true},{"t":"지나간 일을 오래 간직할 수 있다","mis":"K6-2-u6-X01"},{"t":"읽는 사람에게 생생하게 전해진다","mis":"K6-2-u6-X01"},{"t":"그때의 마음을 또렷하게 알게 된다","mis":"K6-2-u6-X01"}],"explanation":["간직 · 전함 · 또렷해짐은 좋은 점이에요.","글씨는 겉모습이에요.","경험을 쓰는 까닭과 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#2','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C3',1,'ox','auto','짧고 쉬운 말로 쓴 시도 좋은 시가 될 수 있어요.',ARRAY['K6-2-u6-X04']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":1,"kind":"ox","stem":"짧고 쉬운 말로 쓴 시도 좋은 시가 될 수 있어요.","answer":"O","reason_options":[{"t":"그 마음에 알맞은 표현이 좋은 표현이기 때문에","correct":true},{"t":"짧을수록 언제나 더 좋은 시이기 때문에","mis":"K6-2-u6-X04"}],"mis":"K6-2-u6-X04","explanation":["어려운 말이 기준이 아니에요.","짧다고 무조건 좋은 것도 아니에요.","마음에 알맞은지가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#3','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C4',1,'mc','auto','이야기에서 「일이 일어난 때와 곳」을 무엇이라고 하나요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"mc","stem":"이야기에서 「일이 일어난 때와 곳」을 무엇이라고 하나요?","options":[{"t":"배경","correct":true},{"t":"인물","mis":"K6-2-u6-X05"},{"t":"사건","mis":"K6-2-u6-X05"},{"t":"주제","mis":"K6-2-u6-X05"}],"explanation":["인물은 나오는 사람이나 대상이에요.","사건은 일어난 일이에요.","때와 곳은 배경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#4','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C8',1,'mc','auto','직유법을 쓴 표현은 어느 것인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"직유법을 쓴 표현은 어느 것인가요?","options":[{"t":"우리 집은 난롯가처럼 둥글다","correct":true},{"t":"우리 집은 빈 운동장이다","mis":"K6-2-u6-X11"},{"t":"김이 푹푹 난다","mis":"K6-2-u6-X12"},{"t":"서둘러, 서둘러","mis":"K6-2-u6-X12"}],"explanation":["「처럼」이 있으면 직유법이에요.","빈 운동장이다는 은유법이에요.","푹푹 · 서둘러는 들은 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#5','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C9',1,'mc','auto','보고 · 듣고 · 맡고 · 만지고 · 맛본 것을 그대로 살려 쓴 표현을 무엇이라고 하나요?',ARRAY['K6-2-u6-X12','K6-2-u6-X11']::text[],false,'{"seq":5,"concept":"K6-2-u6-C9","difficulty":1,"kind":"mc","stem":"보고 · 듣고 · 맡고 · 만지고 · 맛본 것을 그대로 살려 쓴 표현을 무엇이라고 하나요?","options":[{"t":"감각적 표현","correct":true},{"t":"비유적 표현","mis":"K6-2-u6-X12"},{"t":"은유법","mis":"K6-2-u6-X11"},{"t":"제목","mis":"K6-2-u6-X12"}],"explanation":["느낀 감각을 그대로 옮겨요.","빗대는 것은 비유적 표현이에요.","이것을 감각적 표현이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#6','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C12',1,'mc','auto','생각그물에서 「땀으로 미끄러운 손잡이」는 어느 칸에 들어가나요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":6,"concept":"K6-2-u6-C12","difficulty":1,"kind":"mc","stem":"생각그물에서 「땀으로 미끄러운 손잡이」는 어느 칸에 들어가나요?","options":[{"t":"만진 것","correct":true},{"t":"들은 것","mis":"K6-2-u6-X12"},{"t":"본 것","mis":"K6-2-u6-X12"},{"t":"빗댈 것","mis":"K6-2-u6-X12"}],"explanation":["손으로 느낀 감각이에요.","소리는 들은 것이에요.","그래서 만진 것이에요."],"asset":{"type":"passage","lines":["가운데 · 이단 뛰기를 처음 성공한 날","본 것 · 발밑을 빠르게 지나가는 줄","들은 것 · 탁, 탁 하는 두 번의 소리","만진 것 · 땀으로 미끄러운 손잡이","생각이나 느낌 · 백한 번째에 드디어 되었다","빗댈 것 · 잠깐 떠 있는 몸 → 새"],"title":"하진이의 생각그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#7','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C17',1,'ox','auto','효과음은 시의 장면과 맞닿은 소리를 아주 짧게 쓰는 것이 좋아요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":7,"concept":"K6-2-u6-C17","difficulty":1,"kind":"ox","stem":"효과음은 시의 장면과 맞닿은 소리를 아주 짧게 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"효과음은 낭송을 돕는 것이지 대신하는 것이 아니기 때문에","correct":true},{"t":"효과음이 많을수록 낭송이 멋있어지기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["효과음은 짧게 써요.","장면과 맞닿은 소리를 골라요.","돕는 만큼만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#8','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C20',1,'mc','auto','원래 이야기를 밝히고 일부러 바꾸어 새로운 뜻이 생기게 하는 것은 무엇인가요?',ARRAY['K6-2-u6-X26']::text[],false,'{"seq":8,"concept":"K6-2-u6-C20","difficulty":1,"kind":"mc","stem":"원래 이야기를 밝히고 일부러 바꾸어 새로운 뜻이 생기게 하는 것은 무엇인가요?","options":[{"t":"패러디","correct":true},{"t":"표절","mis":"K6-2-u6-X26"},{"t":"베껴 쓰기","mis":"K6-2-u6-X26"},{"t":"줄거리 외우기","mis":"K6-2-u6-X26"}],"explanation":["표절은 그대로 옮기고 자기 것인 척해요.","패러디는 밝히고 바꿔요.","새로운 뜻이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#9','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C5',2,'mc','auto','시 「물수제비」는 어떤 경험을 담았나요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"시 「물수제비」는 어떤 경험을 담았나요?","options":[{"t":"강가에서 납작한 돌을 던져 물수제비를 뜬 경험","correct":true},{"t":"강에서 수영을 배운 경험","mis":"K6-2-u6-X07"},{"t":"돌을 모아 탑을 쌓은 경험","mis":"K6-2-u6-X07"},{"t":"배를 타고 강을 건넌 경험","mis":"K6-2-u6-X07"}],"explanation":["말하는 이가 실제로 한 일을 찾아요.","납작한 돌을 낮게 던졌어요.","물수제비를 뜬 경험이에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#10','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C9',2,'mc','auto','「물수제비」에서 들은 것을 살린 감각적 표현은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":10,"concept":"K6-2-u6-C9","difficulty":2,"kind":"mc","stem":"「물수제비」에서 들은 것을 살린 감각적 표현은 어느 것인가요?","options":[{"t":"톡, 톡, 톡","correct":true},{"t":"돌이 물 위를 걸어간다","mis":"K6-2-u6-X12"},{"t":"강물 속으로 숨어도","mis":"K6-2-u6-X12"},{"t":"내 어깨가 강둑까지 올라간다","mis":"K6-2-u6-X12"}],"explanation":["걸어간다 · 숨어도는 빗댄 표현이에요.","어깨가 올라간다도 빗댄 거예요.","톡, 톡, 톡은 들은 소리예요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#11','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',2,'mc','auto','도윤이의 시 「소풍」이 시보다 목록처럼 읽히는 까닭은 무엇인가요?',ARRAY['K6-2-u6-X13','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":11,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"도윤이의 시 「소풍」이 시보다 목록처럼 읽히는 까닭은 무엇인가요?","options":[{"t":"겪은 일을 다 넣어 어느 순간이 중요한지 알 수 없기 때문에","correct":true},{"t":"빗댄 표현이 하나도 없기 때문에","mis":"K6-2-u6-X13"},{"t":"어려운 낱말이 없기 때문에","mis":"K6-2-u6-X04"},{"t":"글감이 대단한 일이 아니기 때문에","mis":"K6-2-u6-X02"}],"explanation":["빗댄 표현이 없어도 시가 돼요.","쉬운 말도 괜찮아요.","다 넣어서 중요한 순간이 흐려졌어요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#12','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C15',2,'mc','auto','시를 고쳐 쓸 때 볼 것이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":12,"concept":"K6-2-u6-C15","difficulty":2,"kind":"mc","stem":"시를 고쳐 쓸 때 볼 것이 아닌 것은 어느 것인가요?","options":[{"t":"빗댄 표현이 친구 시보다 많은가","correct":true},{"t":"전하려던 마음이 드러나는가","mis":"K6-2-u6-X19"},{"t":"없어도 되는 줄이 남아 있지는 않은가","mis":"K6-2-u6-X19"},{"t":"소리 내어 읽었을 때 걸리는 곳이 없는가","mis":"K6-2-u6-X19"}],"explanation":["마음 · 연 · 줄 · 소리를 봐요.","빗댄 표현의 개수는 볼 것이 아니에요.","고쳐 쓰기는 시를 자라게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#13','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C16',2,'mc','auto','서하의 낭송 계획에서 가장 먼저 채워야 할 곳은 어느 것인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X21']::text[],false,'{"seq":13,"concept":"K6-2-u6-C16","difficulty":2,"kind":"mc","stem":"서하의 낭송 계획에서 가장 먼저 채워야 할 곳은 어느 것인가요?","options":[{"t":"전하고 싶은 마음","correct":true},{"t":"배경 음악","mis":"K6-2-u6-X22"},{"t":"영상","mis":"K6-2-u6-X22"},{"t":"모든 연의 목소리 크기","mis":"K6-2-u6-X21"}],"explanation":["마음이 아직 정해지지 않았어요.","마음이 정해져야 목소리와 속도가 정해져요.","마음부터 채워요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#14','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C21',2,'mc','auto','인물의 성격이 바뀌면 함께 바뀌는 것은 무엇인가요?',ARRAY['K6-2-u6-X35','K6-2-u6-X06']::text[],false,'{"seq":14,"concept":"K6-2-u6-C21","difficulty":2,"kind":"mc","stem":"인물의 성격이 바뀌면 함께 바뀌는 것은 무엇인가요?","options":[{"t":"그 인물이 하는 말과 행동","correct":true},{"t":"이야기의 글자 수","mis":"K6-2-u6-X35"},{"t":"아무것도 바뀌지 않는다","mis":"K6-2-u6-X06"},{"t":"책의 형태","mis":"K6-2-u6-X35"}],"explanation":["성격은 하는 일로 드러나요.","성격이 바뀌면 하는 일이 바뀌어요.","그래서 사건도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#15','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C27',2,'mc','auto','지안이의 계획에서 바뀐 요소는 무엇인가요?',ARRAY['K6-2-u6-X33','K6-2-u6-X05']::text[],false,'{"seq":15,"concept":"K6-2-u6-C27","difficulty":2,"kind":"mc","stem":"지안이의 계획에서 바뀐 요소는 무엇인가요?","options":[{"t":"베짱이의 성격","correct":true},{"t":"개미의 성격","mis":"K6-2-u6-X33"},{"t":"이야기의 배경","mis":"K6-2-u6-X05"},{"t":"이야기의 제목","mis":"K6-2-u6-X05"}],"explanation":["바꿀 것 칸을 봐요.","게으름에서 남을 위해 연습하는 성격으로 바꾸었어요.","인물의 성격을 바꾸었어요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#16','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C31',2,'mc','auto','학급 이야기책 회의에서 루아의 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X41']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"mc","stem":"학급 이야기책 회의에서 루아의 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"책의 형태에는 등수가 없고 독자에 따라 알맞은 형태가 달라지기 때문에","correct":true},{"t":"화면으로 보는 책은 만들 수 없기 때문에","mis":"K6-2-u6-X38"},{"t":"종이책이 언제나 가장 좋기 때문에","mis":"K6-2-u6-X38"},{"t":"형태는 표지 다음에 정하기 때문에","mis":"K6-2-u6-X41"}],"explanation":["형태마다 잘하는 일이 달라요.","등수가 없어요.","독자에 따라 골라요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#17','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C5',3,'mc','auto','「내 어깨가 강둑까지 올라간다」는 말하는 이의 어떤 마음을 나타내나요?',ARRAY['K6-2-u6-X08','K6-2-u6-X07']::text[],false,'{"seq":17,"concept":"K6-2-u6-C5","difficulty":3,"kind":"mc","stem":"「내 어깨가 강둑까지 올라간다」는 말하는 이의 어떤 마음을 나타내나요?","options":[{"t":"아빠보다 한 걸음 더 가서 뿌듯하고 자랑스러운 마음","correct":true},{"t":"어깨가 아파 들어 올린 것","mis":"K6-2-u6-X08"},{"t":"강둑에 올라가 쉬고 싶은 마음","mis":"K6-2-u6-X08"},{"t":"돌이 가라앉아 속상한 마음","mis":"K6-2-u6-X07"}],"explanation":["어깨가 실제로 강둑까지 가지 않아요.","아빠 돌보다 한 걸음 더 갔어요.","으쓱한 마음을 빗대었어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#18','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',3,'mc','auto','도윤이의 「소풍」을 시답게 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X04','K6-2-u6-X03']::text[],false,'{"seq":18,"concept":"K6-2-u6-C13","difficulty":3,"kind":"mc","stem":"도윤이의 「소풍」을 시답게 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"보물찾기 쪽지를 찾은 순간만 남기고, 그때 본 것과 마음을 짧게 나누어 쓴다","correct":true},{"t":"빠진 일이 없도록 점심 메뉴와 공원 이름까지 더 넣는다","mis":"K6-2-u6-X16"},{"t":"어려운 낱말로 바꾸어 쓴다","mis":"K6-2-u6-X04"},{"t":"빗댄 표현을 다섯 개 넘게 넣는다","mis":"K6-2-u6-X03"}],"explanation":["더 넣으면 더 목록이 돼요.","어려운 말이나 개수는 기준이 아니에요.","인상 깊은 순간만 남겨요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#19','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C19',3,'mc','auto','서하의 낭송 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22']::text[],false,'{"seq":19,"concept":"K6-2-u6-C19","difficulty":3,"kind":"mc","stem":"서하의 낭송 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마음을 정하지 않았고 음악과 영상이 낭송을 덮어, 멋있게 들리려다 시의 마음이 건너가지 못한다","correct":true},{"t":"목소리가 가장 크니 잘한 계획이다","mis":"K6-2-u6-X21"},{"t":"음악과 영상이 화려하니 잘한 계획이다","mis":"K6-2-u6-X22"},{"t":"목소리를 줄이고 음악만 크게 하면 된다","mis":"K6-2-u6-X22"}],"explanation":["크기와 화려함이 목표가 아니에요.","음악과 영상이 낭송을 덮으면 안 돼요.","마음이 건너가게 해요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#20','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C24',3,'mc','auto','지안이의 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X27','K6-2-u6-X36']::text[],false,'{"seq":20,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"지안이의 계획을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"성격을 바꾼 생각은 좋지만 행동이 그대로이고 로봇이 갑자기 나와, 바뀐 것에서 다음 일이 이어지지 않는다","correct":true},{"t":"로봇이 나와 가장 기발하니 잘 바꾼 계획이다","mis":"K6-2-u6-X30"},{"t":"성격을 바꾸었으니 행동은 그대로여도 된다","mis":"K6-2-u6-X27"},{"t":"하나만 바꾸었으니 잘못 바꾼 계획이다","mis":"K6-2-u6-X36"}],"explanation":["잘한 점을 먼저 짚어요.","성격과 행동이 어긋났어요.","갑작스러운 일은 이어지지 않아요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#21','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C33',3,'mc','auto','학급 이야기책 회의에서 다온이의 말을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41']::text[],false,'{"seq":21,"concept":"K6-2-u6-C33","difficulty":3,"kind":"mc","stem":"학급 이야기책 회의에서 다온이의 말을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이야기를 먼저 완성하고, 꾸미기는 읽기 좋게 돕는 만큼만 하자.」","correct":true},{"t":"「표지를 나흘 동안 꾸미자.」","mis":"K6-2-u6-X41"},{"t":"「글은 빼고 그림만 넣자.」","mis":"K6-2-u6-X41"},{"t":"「꾸미기를 가장 잘한 모둠이 이긴 거야.」","mis":"K6-2-u6-X41"}],"explanation":["표지가 이야기를 덮으면 안 돼요.","책은 담긴 이야기로 남아요.","이야기가 먼저예요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#22','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C24',3,'mc','auto','이 단원에서 배운 것과 맞는 말은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X02','K6-2-u6-X09']::text[],false,'{"seq":22,"concept":"K6-2-u6-C24","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 것과 맞는 말은 어느 것인가요?","options":[{"t":"표현은 마음에 알맞은지로 고르고, 바꾸기는 뒤가 이어지는지로 본다","correct":true},{"t":"빗댄 표현이 많을수록 좋은 시이고, 놀랍게 바꿀수록 좋은 이야기다","mis":"K6-2-u6-X30"},{"t":"시는 특별한 경험으로만 쓰고, 이야기는 그대로 옮겨야 한다","mis":"K6-2-u6-X02"},{"t":"시와 이야기는 길게 쓸수록 좋다","mis":"K6-2-u6-X09"}],"explanation":["개수가 아니라 알맞음이에요.","놀라움이 아니라 이어짐이에요.","시도 이야기도 같은 눈으로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#23','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C13',4,'mc','auto','도윤이의 「소풍」과 「물수제비」를 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X03','K6-2-u6-X02']::text[],false,'{"seq":23,"concept":"K6-2-u6-C13","difficulty":4,"kind":"mc","stem":"도윤이의 「소풍」과 「물수제비」를 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「소풍」은 겪은 일을 다 넣어 마음이 흐리지만, 「물수제비」는 돌을 던진 순간만 골라 뿌듯한 마음이 또렷하다","correct":true},{"t":"「소풍」이 빠뜨린 것이 없어 더 좋은 시다","mis":"K6-2-u6-X16"},{"t":"「물수제비」가 빗댄 표현이 많아서 더 좋은 시다","mis":"K6-2-u6-X03"},{"t":"「소풍」은 대단한 일이 아니라서 시가 될 수 없다","mis":"K6-2-u6-X02"}],"explanation":["빠짐없이 다 넣는 것이 장점이 아니에요.","개수로 견주지 않아요.","고르고 버려 또렷해졌는지 봐요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#24','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C15',4,'essay','teacher','도윤이의 「소풍」에서 고쳐야 할 점을 세 가지 찾아 까닭과 함께 쓰고, 가장 인상 깊은 순간만 남겨 연을 나눈 짧은 시로 고쳐 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C15","difficulty":4,"kind":"essay","stem":"도윤이의 「소풍」에서 고쳐야 할 점을 세 가지 찾아 까닭과 함께 쓰고, 가장 인상 깊은 순간만 남겨 연을 나눈 짧은 시로 고쳐 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 첫째, 세수 · 버스 · 김밥처럼 겪은 일을 다 넣어 어느 순간이 중요한지 알 수 없다. 둘째, 장면이 바뀌어도 연을 나누지 않아 따라가기 어렵다. 셋째, 제목 「소풍」에는 쪽지를 찾은 기쁨이 드러나지 않는다. 고쳐 쓴 시 — 「쪽지 한 장」 / 돌 틈에 접힌 / 하얀 쪽지 하나 // 손끝이 먼저 / 알아챘다 // 오늘 공원은 / 내 것이었다","scoring_points":["고칠 점 세 가지와 까닭을 썼는가","인상 깊은 순간만 남겼는가","장면에 맞게 연을 나누고 마음이 드러나는 제목을 붙였는가"]},"explanation":["다 넣은 것을 골라내요.","장면에 맞게 연을 나눠요.","마음이 드러나는 제목을 붙여요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_a#25','kor',6,2,'u6','','g6_2_kor_u6_review_a','unit_review','K6-2-u6-C3',4,'essay','teacher','「좋은 시는 비유를 많이 넣은 시가 아니다.」라는 약속을 이 단원에서 읽은 시 두 편을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C3","difficulty":4,"kind":"essay","stem":"「좋은 시는 비유를 많이 넣은 시가 아니다.」라는 약속을 이 단원에서 읽은 시 두 편을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 「우유갑」에는 빗댄 표현이 하나뿐이고, 「우산 하나」에는 빗댄 표현이 하나도 없다. 그런데도 「우유갑」은 삐친 마음이 조금은 풀렸으면 하는 마음을, 「우산 하나」는 친구 쪽으로 우산을 기울여 내 어깨가 젖은 마음을 잘 전한다. 그러므로 좋은 시는 빗댄 표현의 개수로 정해지지 않고, 그 마음에 알맞은 표현을 골랐는가로 정해진다.","scoring_points":["시 두 편을 예로 들었는가","빗댄 표현이 적어도 마음이 전해짐을 썼는가","개수가 아니라 알맞음이 기준이라고 썼는가"]},"explanation":["빗댄 표현을 세어 봐요.","마음이 전해지는지 봐요.","알맞음이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#1','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C2',1,'ox','auto','교실에서 우유갑을 여느라 애쓴 일도 시의 글감이 될 수 있어요.',ARRAY['K6-2-u6-X02']::text[],false,'{"seq":1,"concept":"K6-2-u6-C2","difficulty":1,"kind":"ox","stem":"교실에서 우유갑을 여느라 애쓴 일도 시의 글감이 될 수 있어요.","answer":"O","reason_options":[{"t":"그때 마음이 움직였다면 작은 일도 글감이 되기 때문에","correct":true},{"t":"우유갑은 누구나 아는 물건이기 때문에","mis":"K6-2-u6-X02"}],"mis":"K6-2-u6-X02","explanation":["「우유갑」이 바로 그런 시예요.","대단한 일이 아니어도 돼요.","마음이 움직였는가가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#2','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C3',1,'mc','auto','좋은 표현을 고르는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":1,"kind":"mc","stem":"좋은 표현을 고르는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 마음에 알맞은가","correct":true},{"t":"빗댄 표현이 몇 개인가","mis":"K6-2-u6-X03"},{"t":"낱말이 얼마나 어려운가","mis":"K6-2-u6-X04"},{"t":"시가 얼마나 긴가","mis":"K6-2-u6-X03"}],"explanation":["개수로 세지 않아요.","어려운 말도 기준이 아니에요.","알맞음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#3','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C4',1,'mc','auto','「토끼와 자라」에서 인물에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u6-X05']::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"mc","stem":"「토끼와 자라」에서 인물에 해당하는 것은 어느 것인가요?","options":[{"t":"자라","correct":true},{"t":"바닷속 용궁","mis":"K6-2-u6-X05"},{"t":"토끼가 달아난 일","mis":"K6-2-u6-X05"},{"t":"뭍에 있는 산","mis":"K6-2-u6-X05"}],"explanation":["용궁과 산은 곳이라 배경이에요.","달아난 일은 사건이에요.","자라는 이야기에 나오는 인물이에요."],"asset":{"type":"passage","lines":["바닷속 용왕이 오래 앓아누웠다. 뭍에 사는 토끼의 간을 먹어야","낫는다는 말이 돌자 신하 가운데 자라가 나서서 뭍으로 올라갔다.","자라는 바닷속에는 먹을 것이 넘치고 사냥꾼도 없다고 토끼를 꾀었다.","용궁에 이르러서야 토끼는 제 간을 내놓아야 한다는 것을 알았다.","토끼는 놀라지 않은 척하며 「간은 볕에 말리려고 산에 두고 왔습니다.」","하고 둘러댔다. 용왕은 그 말을 믿고 토끼를 다시 뭍으로 보냈다.","자라의 등에서 내린 토끼는 뒤도 돌아보지 않고 풀숲으로 달아났다."],"title":"옛이야기 「토끼와 자라」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#4','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C8',1,'mc','auto','「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법은 무엇인가요?',ARRAY['K6-2-u6-X11','K6-2-u6-X12']::text[],false,'{"seq":4,"concept":"K6-2-u6-C8","difficulty":1,"kind":"mc","stem":"「무엇은 무엇이다」처럼 그것이라고 말해 버리는 방법은 무엇인가요?","options":[{"t":"은유법","correct":true},{"t":"직유법","mis":"K6-2-u6-X11"},{"t":"감각적 표현","mis":"K6-2-u6-X12"},{"t":"흉내 내는 말","mis":"K6-2-u6-X12"}],"explanation":["직유법은 「처럼 · 같이」를 써요.","은유법은 그것이라고 말해 버려요.","「빈 운동장이다」가 은유법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#5','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C9',1,'mc','auto','「지우개 가루」에서 만진 것을 살린 표현은 어느 것인가요?',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":5,"concept":"K6-2-u6-C9","difficulty":1,"kind":"mc","stem":"「지우개 가루」에서 만진 것을 살린 표현은 어느 것인가요?","options":[{"t":"손날로 쓱","correct":true},{"t":"틀린 답이 눈처럼 쌓여 있다","mis":"K6-2-u6-X12"},{"t":"털어 내면 사라지지만","mis":"K6-2-u6-X12"},{"t":"공책 위에","mis":"K6-2-u6-X12"}],"explanation":["손날로 가루를 쓸어 내는 감각이에요.","눈처럼은 빗댄 것이에요.","만진 느낌을 그대로 살렸어요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#6','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C13',1,'ox','auto','시는 넣는 일보다 버리는 일이 더 커요.',ARRAY['K6-2-u6-X17']::text[],false,'{"seq":6,"concept":"K6-2-u6-C13","difficulty":1,"kind":"ox","stem":"시는 넣는 일보다 버리는 일이 더 커요.","answer":"O","reason_options":[{"t":"인상 깊은 순간만 남겨야 그 마음이 또렷해지기 때문에","correct":true},{"t":"시는 무조건 짧아야 하기 때문에","mis":"K6-2-u6-X17"}],"mis":"K6-2-u6-X17","explanation":["다 넣으면 목록이 돼요.","짧게 하려는 것이 목적이 아니에요.","골라서 또렷하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#7','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C19',1,'mc','auto','낭송하는 목소리의 크기로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X23','K6-2-u6-X22']::text[],false,'{"seq":7,"concept":"K6-2-u6-C19","difficulty":1,"kind":"mc","stem":"낭송하는 목소리의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"뒤에 앉은 사람까지 들릴 만큼, 부분마다 마음에 맞는 크기로","correct":true},{"t":"처음부터 끝까지 가장 큰 목소리로","mis":"K6-2-u6-X21"},{"t":"옆 사람에게만 들릴 만큼 작게","mis":"K6-2-u6-X23"},{"t":"배경 음악보다 작게","mis":"K6-2-u6-X22"}],"explanation":["무조건 크게도 아니에요.","들리지 않으면 안 돼요.","마음에 맞는 크기로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#8','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C31',1,'mc','auto','교실에 두고 아무 때나 손으로 넘겨 볼 수 있는 책의 형태는 어느 것인가요?',ARRAY['K6-2-u6-X38']::text[],false,'{"seq":8,"concept":"K6-2-u6-C31","difficulty":1,"kind":"mc","stem":"교실에 두고 아무 때나 손으로 넘겨 볼 수 있는 책의 형태는 어느 것인가요?","options":[{"t":"종이책","correct":true},{"t":"소리로 담는 책","mis":"K6-2-u6-X38"},{"t":"화면으로 보는 책","mis":"K6-2-u6-X38"},{"t":"어느 형태도 할 수 없다","mis":"K6-2-u6-X38"}],"explanation":["소리로 담는 책은 귀로 들어요.","화면으로 보는 책은 멀리 보내요.","종이책은 넘겨 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#9','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C5',2,'mc','auto','「물수제비」를 읽고 떠오르는 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「물수제비」를 읽고 떠오르는 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"돌이 물 위를 톡, 톡, 톡 튀어 가는 모습","correct":true},{"t":"돌이 하늘 높이 날아가는 모습","mis":"K6-2-u6-X07"},{"t":"아빠가 강에 빠지는 모습","mis":"K6-2-u6-X07"},{"t":"강물이 꽁꽁 언 모습","mis":"K6-2-u6-X07"}],"explanation":["톡, 톡, 톡 소리가 들려요.","돌이 물 위를 걸어가요.","물 위를 튀어 가는 장면이에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#10','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C7',2,'mc','auto','「세 걸음 만에 / 강물 속으로 숨어도」에서 「숨어도」는 무엇을 빗댄 것인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X10']::text[],false,'{"seq":10,"concept":"K6-2-u6-C7","difficulty":2,"kind":"mc","stem":"「세 걸음 만에 / 강물 속으로 숨어도」에서 「숨어도」는 무엇을 빗댄 것인가요?","options":[{"t":"돌이 물속으로 가라앉아 보이지 않게 된 것","correct":true},{"t":"돌이 바위 뒤에 숨어 있는 것","mis":"K6-2-u6-X08"},{"t":"말하는 이가 부끄러워 숨은 것","mis":"K6-2-u6-X08"},{"t":"강물이 마른 것","mis":"K6-2-u6-X10"}],"explanation":["돌이 실제로 숨은 것이 아니에요.","가라앉아 보이지 않게 되었어요.","그 모습을 숨는 것에 빗대었어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#11','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C13',2,'mc','auto','도윤이가 「소풍」에서 남기면 좋을 가장 인상 깊은 순간은 어느 것인가요?',ARRAY['K6-2-u6-X09']::text[],false,'{"seq":11,"concept":"K6-2-u6-C13","difficulty":2,"kind":"mc","stem":"도윤이가 「소풍」에서 남기면 좋을 가장 인상 깊은 순간은 어느 것인가요?","options":[{"t":"보물찾기에서 쪽지를 찾은 순간","correct":true},{"t":"아침에 세수를 한 일","mis":"K6-2-u6-X09"},{"t":"버스를 탄 일","mis":"K6-2-u6-X09"},{"t":"집에 돌아온 일","mis":"K6-2-u6-X09"}],"explanation":["세수와 버스는 누구나 한 일이에요.","「너무 좋았다」는 마음이 움직인 곳이에요.","그 순간을 남겨요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#12','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C15',2,'ox','auto','고쳐 쓰기는 틀린 곳을 벌하는 일이에요.',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":12,"concept":"K6-2-u6-C15","difficulty":2,"kind":"ox","stem":"고쳐 쓰기는 틀린 곳을 벌하는 일이에요.","answer":"X","reason_options":[{"t":"고쳐 쓰기는 시가 마음을 더 잘 전하도록 자라게 하는 단계이기 때문에","correct":true},{"t":"고칠 곳이 있으면 처음부터 잘못 쓴 것이기 때문에","mis":"K6-2-u6-X19"}],"mis":"K6-2-u6-X19","explanation":["누구나 고쳐 써요.","지운 줄은 다음 시에 써도 돼요.","고쳐 쓰기는 시를 자라게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#13','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C17',2,'mc','auto','서하의 계획에서 배경 음악을 고칠 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":13,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"서하의 계획에서 배경 음악을 고칠 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"시의 분위기와 어울리는 음악을 목소리보다 작게 깐다","correct":true},{"t":"더 신나는 노래로 바꾸어 더 크게 튼다","mis":"K6-2-u6-X22"},{"t":"노래를 두 곡 겹쳐 튼다","mis":"K6-2-u6-X22"},{"t":"음악만 틀고 낭송은 하지 않는다","mis":"K6-2-u6-X22"}],"explanation":["목소리보다 크면 시가 덮여요.","분위기와 어울려야 해요.","작게 깔아 낭송을 도와요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#14','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C22',2,'mc','auto','「개미와 베짱이」의 때를 「겨울이 오지 않는 섬」으로 바꾸면 달라질 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X28','K6-2-u6-X29']::text[],false,'{"seq":14,"concept":"K6-2-u6-C22","difficulty":2,"kind":"mc","stem":"「개미와 베짱이」의 때를 「겨울이 오지 않는 섬」으로 바꾸면 달라질 일로 알맞은 것은 어느 것인가요?","options":[{"t":"먹이를 모아 두지 않아도 굶지 않으니 베짱이가 개미를 찾아갈 까닭이 사라진다","correct":true},{"t":"아무것도 달라지지 않는다","mis":"K6-2-u6-X28"},{"t":"개미의 이름이 바뀐다","mis":"K6-2-u6-X28"},{"t":"하늘에서 갑자기 로봇이 내려온다","mis":"K6-2-u6-X29"}],"explanation":["배경이 바뀌면 할 수 있는 일이 바뀌어요.","겨울이 없으면 굶을 걱정이 없어요.","그래서 사건도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#15','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C28',2,'mc','auto','지안이의 계획에서 바꾼 성격과 맞지 않는 곳은 어느 것인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X35']::text[],false,'{"seq":15,"concept":"K6-2-u6-C28","difficulty":2,"kind":"mc","stem":"지안이의 계획에서 바꾼 성격과 맞지 않는 곳은 어느 것인가요?","options":[{"t":"전개 — 베짱이가 여름 내내 낮잠만 잔다","correct":true},{"t":"바꿀 것 — 남을 위해 노래를 연습하는 성격","mis":"K6-2-u6-X27"},{"t":"원래 이야기 — 베짱이가 개미를 찾아간다","mis":"K6-2-u6-X27"},{"t":"맞지 않는 곳은 없다","mis":"K6-2-u6-X35"}],"explanation":["남을 위해 연습하는 성격으로 바꾸었어요.","그런데 하는 일은 낮잠이에요.","성격과 행동이 어긋나요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#16','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C32',2,'mc','auto','학급 이야기책 회의에서 알맞게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X39','K6-2-u6-X42']::text[],false,'{"seq":16,"concept":"K6-2-u6-C32","difficulty":2,"kind":"mc","stem":"학급 이야기책 회의에서 알맞게 말한 친구는 누구인가요?","options":[{"t":"나래","correct":true},{"t":"다온","mis":"K6-2-u6-X41"},{"t":"시후","mis":"K6-2-u6-X39"},{"t":"하람","mis":"K6-2-u6-X42"}],"explanation":["다온은 표지부터, 시후는 독자를 나중에 정하자고 했어요.","하람은 고칠 점부터 말하자고 했어요.","나래는 중심 사건과 인물부터 정하자고 했어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#17','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C8',3,'error','auto','「물수제비」의 표현을 가렸어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X12','K6-2-u6-X11']::text[],false,'{"seq":17,"concept":"K6-2-u6-C8","difficulty":3,"kind":"error","stem":"「물수제비」의 표현을 가렸어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다인 — 「‘톡, 톡, 톡’은 다른 것에 빗댄 은유법이야.」","correct":true,"mis_target":"K6-2-u6-X12"},{"t":"도하 — 「‘돌이 물 위를 걸어간다’는 돌을 걷는 것에 빗댔어.」","mis":"K6-2-u6-X12"},{"t":"이서 — 「‘처럼’이 없으니 직유법은 아니야.」","mis":"K6-2-u6-X11"}],"explanation":["도하와 이서는 바르게 말했어요.","톡, 톡, 톡은 들은 소리를 살린 감각적 표현이에요.","다인은 감각과 빗댐을 헷갈렸어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#18','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C15',3,'error','auto','도윤이의 시를 함께 고쳐 썼어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X19','K6-2-u6-X14','K6-2-u6-X16']::text[],false,'{"seq":18,"concept":"K6-2-u6-C15","difficulty":3,"kind":"error","stem":"도윤이의 시를 함께 고쳐 썼어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「글씨를 더 예쁘게 쓰면 좋은 시가 될 거야.」","correct":true,"mis_target":"K6-2-u6-X19"},{"t":"서아 — 「장면이 바뀌는 곳에서 연을 나누자.」","mis":"K6-2-u6-X14"},{"t":"민재 — 「세수한 줄은 없어도 되니 지우자.」","mis":"K6-2-u6-X16"}],"explanation":["서아와 민재는 시를 고쳐 쓸 때 볼 것을 봤어요.","글씨는 시의 마음과 상관없어요.","하율은 겉모습을 봤어요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#19','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C18',3,'error','auto','서하의 낭송을 듣고 조언했어요. 알맞지 않게 조언한 친구는 누구인가요?',ARRAY['K6-2-u6-X25','K6-2-u6-X22']::text[],false,'{"seq":19,"concept":"K6-2-u6-C18","difficulty":3,"kind":"error","stem":"서하의 낭송을 듣고 조언했어요. 알맞지 않게 조언한 친구는 누구인가요?","options":[{"t":"하린 — 「그냥 잘했어. 다음에도 그렇게 해.」","correct":true,"mis_target":"K6-2-u6-X25"},{"t":"도하 — 「마지막 연은 조금 천천히 읽으면 뿌듯한 마음이 더 살아날 것 같아.」","mis":"K6-2-u6-X25"},{"t":"나은 — 「음악을 작게 하면 네 목소리가 더 또렷이 들릴 거야.」","mis":"K6-2-u6-X22"}],"explanation":["도하와 나은은 어느 부분을 어떻게 할지 말했어요.","하린의 말로는 무엇을 바꿀지 몰라요.","조언은 구체적으로 해요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#20','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C28',3,'mc','auto','지안이의 계획에서 바꾼 성격에 맞게 전개를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X27','K6-2-u6-X29','K6-2-u6-X36']::text[],false,'{"seq":20,"concept":"K6-2-u6-C28","difficulty":3,"kind":"mc","stem":"지안이의 계획에서 바꾼 성격에 맞게 전개를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"베짱이가 여름 내내 개미들이 힘들 때 들을 노래를 연습한다","correct":true},{"t":"베짱이가 여름 내내 낮잠을 더 오래 잔다","mis":"K6-2-u6-X27"},{"t":"베짱이가 갑자기 하늘을 날 수 있게 된다","mis":"K6-2-u6-X29"},{"t":"개미의 성격도 바꾸고 배경도 우주로 바꾼다","mis":"K6-2-u6-X36"}],"explanation":["남을 위해 연습하는 성격으로 바꾸었어요.","그러면 하는 일도 연습이 되어야 해요.","하나를 바꾸고 따라 움직이게 해요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#21','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C31',3,'mc','auto','회의에서 독자를 「우리 반 친구들과 가정에 계신 분들」로 정했다면 형태를 고르는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":21,"concept":"K6-2-u6-C31","difficulty":3,"kind":"mc","stem":"회의에서 독자를 「우리 반 친구들과 가정에 계신 분들」로 정했다면 형태를 고르는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"집에서도 볼 수 있어야 하니 화면으로 보는 책이 알맞고, 교실용 종이책을 함께 두어도 된다","correct":true},{"t":"독자와 상관없이 가장 새로운 형태를 고른다","mis":"K6-2-u6-X38"},{"t":"가장 빨리 끝나는 형태를 고른다","mis":"K6-2-u6-X38"},{"t":"독자는 나중에 다시 정한다","mis":"K6-2-u6-X39"}],"explanation":["독자가 정해지면 형태가 따라와요.","집에서도 보려면 화면이 알맞아요.","형태에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#22','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C34',3,'mc','auto','두 문장의 빈칸에 들어갈 낱말을 차례대로 바르게 짝 지은 것은 어느 것인가요? 「우체국에서 소포를 (   ). / 게시판에 그림을 (   ).」',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":22,"concept":"K6-2-u6-C34","difficulty":3,"kind":"mc","stem":"두 문장의 빈칸에 들어갈 낱말을 차례대로 바르게 짝 지은 것은 어느 것인가요? 「우체국에서 소포를 (   ). / 게시판에 그림을 (   ).」","options":[{"t":"부쳤다 · 붙였다","correct":true},{"t":"붙였다 · 부쳤다","mis":"K6-2-u6-X43"},{"t":"부쳤다 · 부쳤다","mis":"K6-2-u6-X43"},{"t":"붙였다 · 붙였다","mis":"K6-2-u6-X43"}],"explanation":["소포를 보내는 것은 부치다예요.","그림을 떨어지지 않게 대는 것은 붙이다예요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#23','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C19',4,'mc','auto','서하가 낭송 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X21','K6-2-u6-X22','K6-2-u6-X23']::text[],false,'{"seq":23,"concept":"K6-2-u6-C19","difficulty":4,"kind":"mc","stem":"서하가 낭송 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마음 — 아빠를 이긴 뿌듯함 / 셋째 연은 조금 느리게, 넷째 연은 힘 있게 / 물소리를 작게 깔고 영상은 쓰지 않는다","correct":true},{"t":"마음 — 정하지 않음 / 모든 연 더 크게 / 음악 두 곡","mis":"K6-2-u6-X21"},{"t":"마음 — 뿌듯함 / 모든 연 똑같이 / 음악을 목소리보다 크게","mis":"K6-2-u6-X22"},{"t":"마음 — 뿌듯함 / 아주 작게 속삭이듯 / 음악 없음","mis":"K6-2-u6-X23"}],"explanation":["마음부터 정해요.","연마다 목소리를 달리해요.","음악은 작게, 돕는 만큼만 써요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#24','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C16',4,'essay','teacher','서하의 낭송 계획에서 고쳐야 할 점을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 「물수제비」에 알맞은 낭송 계획을 다시 세우세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C16","difficulty":4,"kind":"essay","stem":"서하의 낭송 계획에서 고쳐야 할 점을 세 가지 찾아 왜 고쳐야 하는지 쓰고, 「물수제비」에 알맞은 낭송 계획을 다시 세우세요.","answer_guide":{"answer":"예: 첫째, 전하고 싶은 마음을 정하지 않아 목소리와 속도를 정할 기준이 없다. 둘째, 모든 연을 가장 큰 목소리로 똑같이 빠르게 읽으면 연마다 다른 마음이 살지 않는다. 셋째, 신나는 노래를 목소리보다 크게 틀고 영상을 쉬지 않고 바꾸면 시를 덮어 버린다. 다시 세운 계획 — 마음: 아빠보다 한 걸음 더 간 뿌듯함. 첫째 · 둘째 연은 가볍고 또렷하게, 톡, 톡, 톡은 끊어서. 셋째 연은 조금 느리게. 넷째 연은 힘을 실어 천천히. 물 흐르는 소리를 목소리보다 작게 깔고 영상은 쓰지 않는다.","scoring_points":["고칠 점 세 가지와 까닭을 썼는가","전하고 싶은 마음을 정했는가","연마다 목소리와 속도, 음악을 돕는 만큼 정했는가"]},"explanation":["마음부터 정해요.","연마다 달리 읽어요.","음악은 작게, 돕는 만큼."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_b#25','kor',6,2,'u6','','g6_2_kor_u6_review_b','unit_review','K6-2-u6-C24',4,'essay','teacher','「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 「금도끼 은도끼」를 바꾼 「마르지 않는 샘」을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C24","difficulty":4,"kind":"essay","stem":"「잘 바꾼 이야기는 많이 바꾼 이야기가 아니다.」라는 말을 「금도끼 은도끼」를 바꾼 「마르지 않는 샘」을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 「마르지 않는 샘」은 때를 가뭄이 든 해로 하나만 바꾸었다. 그러자 나무꾼이 마을의 물을 걱정하게 되고, 그래서 금도끼를 거절하고, 그래서 마을에 샘이 생기는 일이 앞이 뒤를 부르며 자연스럽게 이어졌다. 이야기에 우주선이 내려오는 것처럼 많이 · 놀랍게 바꾸면 이어지지 않는다. 그러므로 바꾸어 쓰기는 얼마나 많이 바꾸었는가가 아니라 바뀐 것에서 다음 일이 자연스럽게 나오는가로 가늠한다.","scoring_points":["바꾼 것이 하나임을 썼는가","앞이 뒤를 부르는 흐름을 썼는가","많이 · 놀랍게가 아니라 이어짐이 기준이라고 썼는가"]},"explanation":["무엇을 바꾸었는지 봐요.","앞이 뒤를 부르는지 봐요.","이어짐이 기준이에요."],"asset":{"type":"passage","lines":["몇 해째 비가 오지 않아 마을 우물이 말라 가던 해였다.","나무꾼은 쇠도끼를 연못에 빠뜨렸고, 금도끼와 은도끼는 제 것이 아니라고 했다.","산신령이 세 도끼를 모두 주겠다고 하자 나무꾼은 고개를 저었다.","「금도끼를 얻겠다고 사람들이 몰려오면 이 연못이 어떻게 되겠습니까.","마을에는 지금 마실 물이 없습니다.」","산신령은 쇠도끼만 돌려주었다. 이튿날 마을 어귀 바위 밑에서","물이 솟았고, 그 샘은 그 뒤로 한 번도 마르지 않았다."],"title":"㉯ 마르지 않는 샘 (㉮를 바꾸어 쓴 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#1','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C2',1,'mc','auto','글감을 고를 때 스스로에게 던질 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X02','K6-2-u6-X04']::text[],false,'{"seq":1,"concept":"K6-2-u6-C2","difficulty":1,"kind":"mc","stem":"글감을 고를 때 스스로에게 던질 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"그때 내 마음이 움직였는가","correct":true},{"t":"남들이 놀랄 만한 일인가","mis":"K6-2-u6-X02"},{"t":"멀리 여행을 가서 겪은 일인가","mis":"K6-2-u6-X02"},{"t":"어려운 낱말을 쓸 수 있는 일인가","mis":"K6-2-u6-X04"}],"explanation":["놀랄 일이나 여행이 아니어도 돼요.","어려운 낱말도 기준이 아니에요.","마음이 움직였는가 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#2','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C13',1,'ox','auto','빗댄 표현이 하나도 없으면 시라고 할 수 없어요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":2,"concept":"K6-2-u6-C13","difficulty":1,"kind":"ox","stem":"빗댄 표현이 하나도 없으면 시라고 할 수 없어요.","answer":"X","reason_options":[{"t":"「우산 하나」처럼 빗댄 표현이 없어도 마음이 전해지는 시가 있기 때문에","correct":true},{"t":"시에는 반드시 빗댄 표현이 들어가야 하기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["비유는 규칙이 아니에요.","쓸 수 있는 방법이에요.","마음이 전해지면 시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#3','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C4',1,'sa','auto','이야기 속에서 일어난 일을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"sa","stem":"이야기 속에서 일어난 일을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["사건"],"explanation":["인물은 누가예요.","배경은 언제 어디예요.","일어난 일은 사건이에요."],"mis":"K6-2-u6-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#4','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C7',1,'ox','auto','빗댈 때에는 두 대상 사이에 비슷한 점이 있어야 해요.',ARRAY['K6-2-u6-X10']::text[],false,'{"seq":4,"concept":"K6-2-u6-C7","difficulty":1,"kind":"ox","stem":"빗댈 때에는 두 대상 사이에 비슷한 점이 있어야 해요.","answer":"O","reason_options":[{"t":"비슷한 점이 있어야 빗댄 까닭을 말로 옮길 수 있기 때문에","correct":true},{"t":"아무것에나 빗대어도 마음이 전해지기 때문에","mis":"K6-2-u6-X10"}],"mis":"K6-2-u6-X10","explanation":["주전자와 아침 집은 바쁘고 뜨거워요.","닮은 점이 있어야 빗대요.","그 점을 말로 옮길 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#5','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C10',1,'ox','auto','시는 연과 행으로 나누어 읽으면 노래하는 듯한 리듬이 느껴져요.',ARRAY['K6-2-u6-X13']::text[],false,'{"seq":5,"concept":"K6-2-u6-C10","difficulty":1,"kind":"ox","stem":"시는 연과 행으로 나누어 읽으면 노래하는 듯한 리듬이 느껴져요.","answer":"O","reason_options":[{"t":"연과 행이 나뉘는 곳에서 쉬어 읽게 되기 때문에","correct":true},{"t":"연과 행은 꼭 지켜야 하는 규칙이기 때문에","mis":"K6-2-u6-X13"}],"mis":"K6-2-u6-X13","explanation":["연과 행이 리듬을 만들어요.","그래도 규칙은 아니에요.","쓸 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#6','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C11',1,'mc','auto','짝의 경험을 자세히 떠올리도록 도우려고 해요. 알맞은 물음은 어느 것인가요?',ARRAY['K6-2-u6-X15']::text[],false,'{"seq":6,"concept":"K6-2-u6-C11","difficulty":1,"kind":"mc","stem":"짝의 경험을 자세히 떠올리도록 도우려고 해요. 알맞은 물음은 어느 것인가요?","options":[{"t":"「그때 본 것과 들은 것은 무엇이었어?」","correct":true},{"t":"「그 일은 몇 시에 일어났어?」","mis":"K6-2-u6-X15"},{"t":"「시를 몇 줄로 쓸 거야?」","mis":"K6-2-u6-X15"},{"t":"「누가 제일 잘했어?」","mis":"K6-2-u6-X15"}],"explanation":["시각과 줄 수는 도움이 되지 않아요.","그 순간으로 다시 들어가게 해요.","본 것과 들은 것을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#7','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',1,'mc','auto','낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22','K6-2-u6-X21','K6-2-u6-X20']::text[],false,'{"seq":7,"concept":"K6-2-u6-C16","difficulty":1,"kind":"mc","stem":"낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"전하고 싶은 마음 정하기 → 목소리와 속도 찾기 → 효과음 · 음악 살펴보기 → 연습하기","correct":true},{"t":"배경 음악 고르기 → 영상 꾸미기 → 낭송하기","mis":"K6-2-u6-X22"},{"t":"가장 큰 목소리 정하기 → 낭송하기","mis":"K6-2-u6-X21"},{"t":"연습 없이 바로 낭송하기","mis":"K6-2-u6-X20"}],"explanation":["마음을 먼저 정해요.","그 마음에 어울리는 목소리와 속도를 찾아요.","여러 번 연습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#8','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C34',1,'mc','auto','「웃어른께 정중히 올리다」라는 뜻의 낱말은 어느 것인가요?',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"mc","stem":"「웃어른께 정중히 올리다」라는 뜻의 낱말은 어느 것인가요?","options":[{"t":"바치다","correct":true},{"t":"받치다","mis":"K6-2-u6-X43"},{"t":"부치다","mis":"K6-2-u6-X43"},{"t":"붙이다","mis":"K6-2-u6-X43"}],"explanation":["받치다는 밑에서 괴는 거예요.","부치다는 보내는 거예요.","웃어른께 올리는 것은 바치다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#9','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C5',2,'ox','auto','「물수제비」에서 돌은 실제로 다리가 있어 물 위를 걸었어요.',ARRAY['K6-2-u6-X08']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"ox","stem":"「물수제비」에서 돌은 실제로 다리가 있어 물 위를 걸었어요.","answer":"X","reason_options":[{"t":"물 위를 튀어 가는 돌의 모습을 걸어가는 것에 빗대었기 때문에","correct":true},{"t":"시에 쓰인 말은 모두 실제로 일어난 일이기 때문에","mis":"K6-2-u6-X08"}],"mis":"K6-2-u6-X08","explanation":["돌에는 다리가 없어요.","튀어 가는 모습이 걸음 같아요.","빗댄 표현으로 읽어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#10','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C8',2,'ox','auto','「돌이 물 위를 걸어간다」는 「처럼」이 없으니 직유법이 아니에요.',ARRAY['K6-2-u6-X11']::text[],false,'{"seq":10,"concept":"K6-2-u6-C8","difficulty":2,"kind":"ox","stem":"「돌이 물 위를 걸어간다」는 「처럼」이 없으니 직유법이 아니에요.","answer":"O","reason_options":[{"t":"직유법은 「같이 · 처럼 · 듯이」를 써서 바로 견주는 방법이기 때문에","correct":true},{"t":"「처럼」이 없어도 모든 빗댄 표현은 직유법이기 때문에","mis":"K6-2-u6-X11"}],"mis":"K6-2-u6-X11","explanation":["「처럼 · 같이 · 듯이」가 없어요.","그래서 직유법이 아니에요.","돌을 걷는 것처럼 바로 말해 버렸어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#11','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C6',2,'mc','auto','「소풍」을 고쳐 쓸 때 연을 나누는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X14']::text[],false,'{"seq":11,"concept":"K6-2-u6-C6","difficulty":2,"kind":"mc","stem":"「소풍」을 고쳐 쓸 때 연을 나누는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"장면이 바뀌는 곳","correct":true},{"t":"아무 데서나 세 줄마다","mis":"K6-2-u6-X14"},{"t":"문장이 끝날 때마다 빠짐없이","mis":"K6-2-u6-X14"},{"t":"연은 나누지 않는다","mis":"K6-2-u6-X14"}],"explanation":["연은 줄 수로 나누지 않아요.","장면이 바뀔 때 나눠요.","읽는 사람이 장면을 따라가요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#12','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C14',2,'mc','auto','「지우개 가루」의 제목에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X18']::text[],false,'{"seq":12,"concept":"K6-2-u6-C14","difficulty":2,"kind":"mc","stem":"「지우개 가루」의 제목에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"시 속 장면이 담겨 있어 읽고 나면 여러 번 틀리며 애쓴 마음이 떠오른다","correct":true},{"t":"빗댄 표현이 없어서 좋은 제목이 아니다","mis":"K6-2-u6-X03"},{"t":"맨 처음에 붙였는지 알 수 없으니 잘못된 제목이다","mis":"K6-2-u6-X18"},{"t":"제목은 반드시 길어야 한다","mis":"K6-2-u6-X18"}],"explanation":["제목에 꼭 빗댄 표현이 있어야 하지 않아요.","언제 붙였는지는 상관없어요.","읽고 나서 고개가 끄덕여지면 좋아요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#13','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',2,'ox','auto','서하처럼 모든 연을 똑같이 가장 큰 목소리로 빠르게 읽는 것이 알맞아요.',ARRAY['K6-2-u6-X20']::text[],false,'{"seq":13,"concept":"K6-2-u6-C16","difficulty":2,"kind":"ox","stem":"서하처럼 모든 연을 똑같이 가장 큰 목소리로 빠르게 읽는 것이 알맞아요.","answer":"X","reason_options":[{"t":"연마다 담긴 마음이 달라 목소리와 속도도 달라져야 하기 때문에","correct":true},{"t":"같은 목소리로 읽어야 마음이 잘 건너가기 때문에","mis":"K6-2-u6-X20"}],"mis":"K6-2-u6-X20","explanation":["「물수제비」의 연마다 마음이 달라요.","목소리는 그 마음을 따라가요.","부분마다 정해요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#14','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',2,'ox','auto','이야기를 바꾸어도 앞의 일이 뒤의 일을 불러오도록 이어져야 해요.',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":14,"concept":"K6-2-u6-C23","difficulty":2,"kind":"ox","stem":"이야기를 바꾸어도 앞의 일이 뒤의 일을 불러오도록 이어져야 해요.","answer":"O","reason_options":[{"t":"원인과 결과로 이어져야 이야기가 자연스럽기 때문에","correct":true},{"t":"바꾼 이야기는 앞뒤가 이어지지 않아도 되기 때문에","mis":"K6-2-u6-X29"}],"mis":"K6-2-u6-X29","explanation":["바뀌었지만 끊기지 않아야 해요.","앞이 뒤를 불러요.","그래야 자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#15','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',2,'ox','auto','지안이의 계획에서 절정의 「하늘에서 로봇이 내려온다」는 앞의 일과 자연스럽게 이어져요.',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":15,"concept":"K6-2-u6-C23","difficulty":2,"kind":"ox","stem":"지안이의 계획에서 절정의 「하늘에서 로봇이 내려온다」는 앞의 일과 자연스럽게 이어져요.","answer":"X","reason_options":[{"t":"앞에서 로봇이 나올 까닭이 없어 갑작스럽기 때문에","correct":true},{"t":"놀라운 일은 언제나 앞의 일과 이어지기 때문에","mis":"K6-2-u6-X29"}],"mis":"K6-2-u6-X29","explanation":["앞의 일에 로봇은 없었어요.","갑자기 나타나면 이어지지 않아요.","앞이 뒤를 불러야 해요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#16','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C31',2,'ox','auto','시후의 말처럼 누가 읽을지는 책을 다 만든 뒤에 정해도 괜찮아요.',ARRAY['K6-2-u6-X39']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"ox","stem":"시후의 말처럼 누가 읽을지는 책을 다 만든 뒤에 정해도 괜찮아요.","answer":"X","reason_options":[{"t":"독자가 정해져야 책의 형태와 내용이 따라 정해지기 때문에","correct":true},{"t":"독자는 책의 내용과 상관없기 때문에","mis":"K6-2-u6-X39"}],"mis":"K6-2-u6-X39","explanation":["세윤이도 독자부터 정하자고 했어요.","독자가 형태를 정해요.","먼저 정해요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#17','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C7',3,'mc','auto','「물수제비」에서 돌이 튀어 가는 모습을 「걸어간다」에 빗댄 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X08','K6-2-u6-X03','K6-2-u6-X10']::text[],false,'{"seq":17,"concept":"K6-2-u6-C7","difficulty":3,"kind":"mc","stem":"「물수제비」에서 돌이 튀어 가는 모습을 「걸어간다」에 빗댄 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"돌이 물 위에 한 번씩 닿았다 떨어지는 모습이 한 걸음씩 내딛는 발걸음과 닮아서","correct":true},{"t":"돌에 다리가 달려 있어서","mis":"K6-2-u6-X08"},{"t":"빗댄 표현을 많이 넣어야 좋은 시가 되어서","mis":"K6-2-u6-X03"},{"t":"돌과 사람은 아무 비슷한 점이 없어서","mis":"K6-2-u6-X10"}],"explanation":["빗댈 때에는 비슷한 점이 있어요.","물에 닿는 모습이 걸음과 닮았어요.","많이 넣으려고 빗댄 것이 아니에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#18','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C14',3,'mc','auto','도윤이가 「소풍」의 제목을 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":18,"concept":"K6-2-u6-C14","difficulty":3,"kind":"mc","stem":"도윤이가 「소풍」의 제목을 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쪽지 한 장이 내 것이 된 날","correct":true},{"t":"소풍 간 날 있었던 모든 일","mis":"K6-2-u6-X18"},{"t":"공원","mis":"K6-2-u6-X18"},{"t":"버스","mis":"K6-2-u6-X18"}],"explanation":["겪은 일 그대로의 제목은 마음이 흐려요.","버스와 공원은 인상 깊은 순간이 아니에요.","쪽지를 찾은 기쁨이 담기면 좋아요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#19','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C16',3,'mc','auto','「물수제비」의 넷째 연을 낭송하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X23','K6-2-u6-X20','K6-2-u6-X21']::text[],false,'{"seq":19,"concept":"K6-2-u6-C16","difficulty":3,"kind":"mc","stem":"「물수제비」의 넷째 연을 낭송하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아빠를 이긴 뿌듯함이 살아나게 조금 힘을 주어 또렷하게 읽고, 「강둑까지」에서 한 박자 쉬어 준다","correct":true},{"t":"가장 작은 목소리로 들리지 않게 읽는다","mis":"K6-2-u6-X23"},{"t":"앞 연과 똑같은 속도와 크기로 읽는다","mis":"K6-2-u6-X20"},{"t":"가장 큰 목소리로 소리치듯 읽는다","mis":"K6-2-u6-X21"}],"explanation":["넷째 연에는 뿌듯함이 담겨 있어요.","목소리는 그 마음을 따라가요.","들리게, 마음에 맞게 읽어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#20','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',3,'error','auto','지안이의 계획을 고칠 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":20,"concept":"K6-2-u6-C23","difficulty":3,"kind":"error","stem":"지안이의 계획을 고칠 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"로하 — 「로봇 말고 용이 내려오게 하면 더 자연스러워.」","correct":true,"mis_target":"K6-2-u6-X29"},{"t":"서진 — 「겨울에 베짱이가 노래로 개미들을 위로하고 개미가 먹이를 나누어 주게 하자.」","mis":"K6-2-u6-X29"},{"t":"하늬 — 「앞에서 연습한 노래가 뒤에서 쓰이게 이어 보자.」","mis":"K6-2-u6-X29"}],"explanation":["서진과 하늬는 앞이 뒤를 부르게 고쳤어요.","로봇을 용으로 바꾸어도 갑작스러워요.","로하는 이어짐을 보지 않았어요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#21','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C32',3,'error','auto','실을 글을 쓰기 전에 정할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u6-X40']::text[],false,'{"seq":21,"concept":"K6-2-u6-C32","difficulty":3,"kind":"error","stem":"실을 글을 쓰기 전에 정할 것을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다온 — 「표지 색깔부터 정하면 글이 빨리 써져.」","correct":true,"mis_target":"K6-2-u6-X40"},{"t":"나래 — 「중심 사건부터 정하자.」","mis":"K6-2-u6-X40"},{"t":"시후 — 「사건이 이어지는 차례를 간단히 적어 두자.」","mis":"K6-2-u6-X40"}],"explanation":["나래와 시후는 바르게 말했어요.","표지 색은 글을 쓰기 전에 정할 것이 아니에요.","중심 사건 · 인물 · 때와 곳 · 차례를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#22','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C25',3,'ox','auto','이단 뛰기를 처음 성공한 경험에서 출발해, 주인공을 줄넘기 대회에 나간 다람쥐로 지어내 이야기를 써도 돼요.',ARRAY['K6-2-u6-X31']::text[],false,'{"seq":22,"concept":"K6-2-u6-C25","difficulty":3,"kind":"ox","stem":"이단 뛰기를 처음 성공한 경험에서 출발해, 주인공을 줄넘기 대회에 나간 다람쥐로 지어내 이야기를 써도 돼요.","answer":"O","reason_options":[{"t":"경험을 바탕으로 쓴 이야기는 겪은 일에서 출발하되 인물 · 배경 · 사건을 지어내기 때문에","correct":true},{"t":"이야기는 겪은 일 그대로만 써야 하기 때문에","mis":"K6-2-u6-X31"}],"mis":"K6-2-u6-X31","explanation":["일기는 사실만 적어요.","이야기는 지어내도 돼요.","겪어 본 것에서 출발하면 자세해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#23','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C28',4,'mc','auto','지안이의 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X29','K6-2-u6-X30','K6-2-u6-X36']::text[],false,'{"seq":23,"concept":"K6-2-u6-C28","difficulty":4,"kind":"mc","stem":"지안이의 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전개 — 베짱이가 개미들을 위해 노래를 연습한다 / 절정 — 추운 겨울 개미 굴에 노래를 들려준다 / 마지막 — 개미들이 먹이를 나누고 함께 겨울을 난다 / 제목 — 겨울을 노래로 데우는 베짱이","correct":true},{"t":"전개 — 낮잠 / 절정 — 로봇이 먹이를 줌 / 마지막 — 행복해짐 / 제목 — 개미와 베짱이","mis":"K6-2-u6-X29"},{"t":"전개 — 연습 / 절정 — 갑자기 하늘을 남 / 마지막 — 왕이 됨 / 제목 — 하늘을 나는 베짱이","mis":"K6-2-u6-X30"},{"t":"바꿀 것을 성격 · 배경 · 사건 모두로 늘린다","mis":"K6-2-u6-X36"}],"explanation":["성격에 맞게 행동을 바꿔요.","앞이 뒤를 부르게 이어요.","바뀐 것이 드러나는 제목을 붙여요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#24','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C28',4,'essay','teacher','지안이의 바꾸기 계획에서 이어지지 않는 곳을 두 군데 찾아 까닭을 쓰고, 바꾼 성격이 살아나도록 전개 · 절정 · 마지막 · 제목을 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C28","difficulty":4,"kind":"essay","stem":"지안이의 바꾸기 계획에서 이어지지 않는 곳을 두 군데 찾아 까닭을 쓰고, 바꾼 성격이 살아나도록 전개 · 절정 · 마지막 · 제목을 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 베짱이를 남을 위해 노래를 연습하는 성격으로 바꾸고도 전개에서 낮잠만 자게 해 성격과 행동이 어긋난다. 둘째, 절정에서 로봇이 갑자기 내려와 앞의 일과 이어지지 않는다. 고친 계획 — 전개: 베짱이는 여름 내내 개미들이 힘들 때 들을 노래를 연습한다. 절정: 추운 겨울, 지친 개미들이 굴 속에서 웅크리고 있을 때 베짱이가 찾아가 노래를 들려준다. 마지막: 기운을 얻은 개미들이 먹이를 나누고 모두 함께 겨울을 난다. 제목: 겨울을 노래로 데우는 베짱이.","scoring_points":["어긋난 곳 두 군데와 까닭을 썼는가","바꾼 성격에 맞게 행동을 고쳤는가","앞이 뒤를 부르게 잇고 바뀐 것이 드러나는 제목을 붙였는가"]},"explanation":["성격과 행동을 맞춰요.","갑작스러운 일을 빼요.","앞이 뒤를 부르게 이어요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_c#25','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C25',4,'essay','teacher','내가 겪은 작은 일 하나를 골라, 그 경험을 시로 쓸 때와 그 경험을 바탕으로 이야기를 쓸 때 각각 어떻게 다르게 쓸지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C25","difficulty":4,"kind":"essay","stem":"내가 겪은 작은 일 하나를 골라, 그 경험을 시로 쓸 때와 그 경험을 바탕으로 이야기를 쓸 때 각각 어떻게 다르게 쓸지 설명하세요.","answer_guide":{"answer":"예: 겪은 일 — 짝과 우산 하나를 함께 쓰고 집에 온 일. 시로 쓸 때에는 어깨가 젖은 순간처럼 가장 인상 깊은 장면만 골라 짧게 쓰고, 장면이 바뀌는 곳에서 연을 나누며, 마음에 알맞으면 빗대거나 감각을 살린다. 이야기로 쓸 때에는 겪은 일에서 출발하되 인물 · 배경 · 사건을 지어낼 수 있다. 예를 들어 비가 그치지 않는 마을에 사는 두 친구로 인물과 배경을 바꾸고, 우산 하나를 나누어 쓰다 생긴 일이 앞뒤로 이어지게 발단부터 마지막까지 쓴다.","scoring_points":["겪은 작은 일을 하나 골랐는가","시로 쓸 때의 방법(고르기 · 연 · 표현)을 썼는가","이야기로 쓸 때 지어내고 이어지게 쓴다고 썼는가"]},"explanation":["작은 일도 글감이에요.","시는 고르고 짧게.","이야기는 지어내고 이어지게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#1','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C1',1,'mc','auto','「지우개 가루」를 쓴 사람이 경험을 시로 남겨 얻은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X01','K6-2-u6-X07']::text[],false,'{"seq":1,"concept":"K6-2-u6-C1","difficulty":1,"kind":"mc","stem":"「지우개 가루」를 쓴 사람이 경험을 시로 남겨 얻은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 번 틀리며 애쓴 마음을 오래 간직하게 되었다","correct":true},{"t":"글씨를 또박또박 쓰게 되었다","mis":"K6-2-u6-X01"},{"t":"시를 길게 늘이는 법을 알게 되었다","mis":"K6-2-u6-X01"},{"t":"지우개를 아껴 쓰게 되었다","mis":"K6-2-u6-X07"}],"explanation":["털어 낸 가루는 사라져요.","그런데 애쓴 마음은 시로 남았어요.","손끝이 알고 있다는 마음이에요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#2','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C3',1,'mc','auto','이 단원의 약속과 맞는 말은 어느 것인가요?',ARRAY['K6-2-u6-X03','K6-2-u6-X04','K6-2-u6-X02']::text[],false,'{"seq":2,"concept":"K6-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 단원의 약속과 맞는 말은 어느 것인가요?","options":[{"t":"빗댄 표현은 마음에 알맞을 때 힘이 있다","correct":true},{"t":"빗댄 표현을 많이 넣을수록 좋은 시다","mis":"K6-2-u6-X03"},{"t":"어려운 말을 쓸수록 좋은 시다","mis":"K6-2-u6-X04"},{"t":"대단한 일을 겪어야 시가 된다","mis":"K6-2-u6-X02"}],"explanation":["많이 넣는다고 좋아지지 않아요.","어려운 말이 기준이 아니에요.","작은 일도 시가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#3','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C4',1,'ox','auto','인물 · 배경 · 사건은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직여요.',ARRAY['K6-2-u6-X06']::text[],false,'{"seq":3,"concept":"K6-2-u6-C4","difficulty":1,"kind":"ox","stem":"인물 · 배경 · 사건은 서로 붙어 있어 하나를 바꾸면 나머지도 함께 움직여요.","answer":"O","reason_options":[{"t":"셋이 모여 하나의 이야기를 이루기 때문에","correct":true},{"t":"셋은 서로 아무 상관이 없기 때문에","mis":"K6-2-u6-X06"}],"mis":"K6-2-u6-X06","explanation":["성격이 바뀌면 하는 일이 바뀌어요.","배경이 바뀌면 할 수 있는 일이 바뀌어요.","셋은 함께 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#4','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C7',1,'mc','auto','「틀린 답이 / 눈처럼 쌓여 있다」에서 지우개 가루를 무엇에 빗대었나요?',ARRAY['K6-2-u6-X10']::text[],false,'{"seq":4,"concept":"K6-2-u6-C7","difficulty":1,"kind":"mc","stem":"「틀린 답이 / 눈처럼 쌓여 있다」에서 지우개 가루를 무엇에 빗대었나요?","options":[{"t":"눈","correct":true},{"t":"공책","mis":"K6-2-u6-X10"},{"t":"손날","mis":"K6-2-u6-X10"},{"t":"틀린 답","mis":"K6-2-u6-X10"}],"explanation":["지우개 가루가 하얗게 쌓였어요.","그 모습이 눈과 닮았어요.","「처럼」으로 눈에 빗대었어요."],"asset":{"type":"passage","lines":["공책 위에 쌓인 / 지우개 가루를 / 손날로 쓱","틀린 답이 / 눈처럼 쌓여 있다","털어 내면 사라지지만 / 내가 몇 번 틀렸는지는 / 손끝이 알고 있다"],"title":"시 「지우개 가루」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#5','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C10',1,'mc','auto','시의 특성으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X09','K6-2-u6-X04','K6-2-u6-X14']::text[],false,'{"seq":5,"concept":"K6-2-u6-C10","difficulty":1,"kind":"mc","stem":"시의 특성으로 알맞은 것은 어느 것인가요?","options":[{"t":"생각이나 느낌을 짧은 글로 눌러 담는다","correct":true},{"t":"겪은 일을 빠짐없이 길게 적는다","mis":"K6-2-u6-X09"},{"t":"반드시 어려운 낱말을 쓴다","mis":"K6-2-u6-X04"},{"t":"연과 행을 나누지 않고 이어 쓴다","mis":"K6-2-u6-X14"}],"explanation":["빠짐없이 길게는 시의 특성이 아니에요.","어려운 낱말도 아니에요.","짧게 눌러 담는 것이 시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#6','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C13',1,'mc','auto','시를 쓸 때 생각그물에서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X16','K6-2-u6-X17']::text[],false,'{"seq":6,"concept":"K6-2-u6-C13","difficulty":1,"kind":"mc","stem":"시를 쓸 때 생각그물에서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 것만 골라 남기고 나머지는 버린다","correct":true},{"t":"모은 것을 하나도 빠짐없이 다 넣는다","mis":"K6-2-u6-X16"},{"t":"모은 것 가운데 가장 긴 것만 넣는다","mis":"K6-2-u6-X17"},{"t":"생각그물은 그리지 않는다","mis":"K6-2-u6-X16"}],"explanation":["다 넣으면 목록이 돼요.","길이가 기준이 아니에요.","인상 깊은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#7','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C18',1,'mc','auto','친구의 낭송을 들을 때 알맞은 모습은 어느 것인가요?',ARRAY['K6-2-u6-X24']::text[],false,'{"seq":7,"concept":"K6-2-u6-C18","difficulty":1,"kind":"mc","stem":"친구의 낭송을 들을 때 알맞은 모습은 어느 것인가요?","options":[{"t":"시와 관련 있는 내 경험을 떠올리며 듣는다","correct":true},{"t":"틀린 글자를 찾아 적어 둔다","mis":"K6-2-u6-X24"},{"t":"옆 친구와 그때그때 이야기한다","mis":"K6-2-u6-X24"},{"t":"내 시를 속으로 읽어 본다","mis":"K6-2-u6-X24"}],"explanation":["낭송하는 사람을 바라봐요.","내 경험을 떠올리며 들어요.","끝난 뒤 잘한 점을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#8','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C34',1,'ox','auto','「운동화 끈을 단단히 매었다.」는 바르게 쓴 문장이에요.',ARRAY['K6-2-u6-X43']::text[],false,'{"seq":8,"concept":"K6-2-u6-C34","difficulty":1,"kind":"ox","stem":"「운동화 끈을 단단히 매었다.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"끈을 묶는 것은 「매다」이기 때문에","correct":true},{"t":"어깨에 걸치는 것도 「매다」이기 때문에","mis":"K6-2-u6-X43"}],"mis":"K6-2-u6-X43","explanation":["끈을 묶는 것은 매다예요.","어깨에 걸치는 것은 메다예요.","바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#9','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C5',2,'mc','auto','「물수제비」에서 말하는 이와 함께 돌을 던진 사람은 누구인가요?',ARRAY['K6-2-u6-X07']::text[],false,'{"seq":9,"concept":"K6-2-u6-C5","difficulty":2,"kind":"mc","stem":"「물수제비」에서 말하는 이와 함께 돌을 던진 사람은 누구인가요?","options":[{"t":"아빠","correct":true},{"t":"선생님","mis":"K6-2-u6-X07"},{"t":"짝꿍","mis":"K6-2-u6-X07"},{"t":"동생","mis":"K6-2-u6-X07"}],"explanation":["넷째 연을 읽어요.","아빠 돌보다 한 걸음 더 갔어요.","아빠와 함께 던졌어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#10','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C10',2,'mc','auto','「물수제비」에 담긴 시의 특성으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u6-X14','K6-2-u6-X12','K6-2-u6-X10']::text[],false,'{"seq":10,"concept":"K6-2-u6-C10","difficulty":2,"kind":"mc","stem":"「물수제비」에 담긴 시의 특성으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"겪은 일을 처음부터 끝까지 빠짐없이 적었다","correct":true},{"t":"장면이 바뀌는 곳에서 연을 나누었다","mis":"K6-2-u6-X14"},{"t":"들은 소리를 그대로 살렸다","mis":"K6-2-u6-X12"},{"t":"돌의 움직임을 다른 것에 빗대었다","mis":"K6-2-u6-X10"}],"explanation":["연을 나누고 소리를 살렸어요.","돌의 움직임을 빗대었어요.","빠짐없이 다 적지는 않았어요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#11','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C14',2,'ox','auto','「소풍」이라는 제목은 도윤이의 마음이 잘 드러나는 제목이에요.',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":11,"concept":"K6-2-u6-C14","difficulty":2,"kind":"ox","stem":"「소풍」이라는 제목은 도윤이의 마음이 잘 드러나는 제목이에요.","answer":"X","reason_options":[{"t":"겪은 일 그대로의 제목이라 보물 쪽지를 찾은 기쁨이 드러나지 않기 때문에","correct":true},{"t":"제목은 짧을수록 마음이 잘 드러나기 때문에","mis":"K6-2-u6-X18"}],"mis":"K6-2-u6-X18","explanation":["겪은 일 그대로의 제목도 쓸 수 있어요.","그런데 마음은 잘 드러나지 않아요.","인상 깊은 순간이 담기면 좋아요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#12','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C15',2,'mc','auto','시를 소리 내어 읽어 보며 고쳐 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X19']::text[],false,'{"seq":12,"concept":"K6-2-u6-C15","difficulty":2,"kind":"mc","stem":"시를 소리 내어 읽어 보며 고쳐 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸리는 줄을 찾아 고치거나 지우기 위해서","correct":true},{"t":"글씨를 예쁘게 다시 쓰기 위해서","mis":"K6-2-u6-X19"},{"t":"빗댄 표현의 개수를 세기 위해서","mis":"K6-2-u6-X19"},{"t":"친구 시보다 길게 늘리기 위해서","mis":"K6-2-u6-X19"}],"explanation":["귀로 들으면 걸리는 곳이 보여요.","걸리는 줄을 고치거나 지워요.","글씨나 개수는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#13','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C17',2,'mc','auto','서하의 계획에서 영상을 고칠 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":13,"concept":"K6-2-u6-C17","difficulty":2,"kind":"mc","stem":"서하의 계획에서 영상을 고칠 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"강물 위를 튀는 돌처럼 시의 장면을 떠올리게 하는 그림을 조용히 보여 준다","correct":true},{"t":"더 반짝이는 꾸밈으로 바꾼다","mis":"K6-2-u6-X22"},{"t":"영상을 더 빠르게 바꾼다","mis":"K6-2-u6-X22"},{"t":"영상만 보여 주고 낭송은 하지 않는다","mis":"K6-2-u6-X22"}],"explanation":["화려하면 낭송의 흐름을 방해해요.","장면을 떠올리는 데 도움이 될 만큼만 써요.","낭송을 대신하지 않아요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#14','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C24',2,'mc','auto','잘 바꾼 이야기를 가늠하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X30','K6-2-u6-X36','K6-2-u6-X32']::text[],false,'{"seq":14,"concept":"K6-2-u6-C24","difficulty":2,"kind":"mc","stem":"잘 바꾼 이야기를 가늠하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"바뀐 것에서 다음 일이 자연스럽게 나오는가","correct":true},{"t":"얼마나 놀라운 일이 일어나는가","mis":"K6-2-u6-X30"},{"t":"얼마나 많은 곳을 바꾸었는가","mis":"K6-2-u6-X36"},{"t":"원래 이야기와 얼마나 다르게 길어졌는가","mis":"K6-2-u6-X32"}],"explanation":["놀라움이 기준이 아니에요.","많이 바꾸는 것도 아니에요.","이어짐이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#15','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C29',2,'mc','auto','지안이의 계획에서 제목을 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18','K6-2-u6-X30']::text[],false,'{"seq":15,"concept":"K6-2-u6-C29","difficulty":2,"kind":"mc","stem":"지안이의 계획에서 제목을 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겨울을 노래로 데우는 베짱이","correct":true},{"t":"개미와 베짱이","mis":"K6-2-u6-X18"},{"t":"로봇 대소동","mis":"K6-2-u6-X30"},{"t":"여름","mis":"K6-2-u6-X18"}],"explanation":["원래 제목은 바뀐 것을 드러내지 못해요.","로봇은 이어지지 않는 사건이에요.","바뀐 성격이 드러나게 붙여요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#16','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',2,'mc','auto','하람이의 말을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-2-u6-X42','K6-2-u6-X41']::text[],false,'{"seq":16,"concept":"K6-2-u6-C33","difficulty":2,"kind":"mc","stem":"하람이의 말을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「다 만들면 서로의 글에서 잘한 점부터 말해 주자.」","correct":true},{"t":"「다 만들면 가장 못한 사람을 뽑자.」","mis":"K6-2-u6-X42"},{"t":"「다 만들면 표지가 가장 화려한 모둠을 뽑자.」","mis":"K6-2-u6-X41"},{"t":"「다 만들면 아무 말도 하지 말자.」","mis":"K6-2-u6-X42"}],"explanation":["잘한 점에 초점을 맞춰요.","글에서 잘한 점을 찾아요.","나누는 즐거움이 목적이에요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#17','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C3',3,'ox','auto','「물수제비」는 빗댄 표현이 몇 개 들어 있느냐에 따라 좋은 시인지가 정해져요.',ARRAY['K6-2-u6-X03']::text[],false,'{"seq":17,"concept":"K6-2-u6-C3","difficulty":3,"kind":"ox","stem":"「물수제비」는 빗댄 표현이 몇 개 들어 있느냐에 따라 좋은 시인지가 정해져요.","answer":"X","reason_options":[{"t":"표현은 개수가 아니라 그 마음에 알맞은지로 가늠하기 때문에","correct":true},{"t":"빗댄 표현이 많을수록 좋은 시가 되기 때문에","mis":"K6-2-u6-X03"}],"mis":"K6-2-u6-X03","explanation":["개수를 세지 않아요.","으쓱한 마음이 잘 전해지는지 봐요.","알맞음이 기준이에요."],"asset":{"type":"passage","lines":["납작한 돌 하나 골라 / 강물 위로 낮게 던진다","톡, 톡, 톡 / 돌이 물 위를 걸어간다","세 걸음 만에 / 강물 속으로 숨어도","아빠 돌보다 한 걸음 더 갔다 / 내 어깨가 강둑까지 올라간다"],"title":"새 시 「물수제비」 (줄 하나가 한 연, / 는 행이 바뀌는 곳)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#18','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C6',3,'ox','auto','도윤이가 「소풍」을 고칠 때 「너무 좋았다」를 그때 본 것이나 만진 것으로 바꾸어 쓰면 더 생생해져요.',ARRAY['K6-2-u6-X12']::text[],false,'{"seq":18,"concept":"K6-2-u6-C6","difficulty":3,"kind":"ox","stem":"도윤이가 「소풍」을 고칠 때 「너무 좋았다」를 그때 본 것이나 만진 것으로 바꾸어 쓰면 더 생생해져요.","answer":"O","reason_options":[{"t":"본 것 · 들은 것 · 만진 것을 그대로 살리면 장면이 떠오르기 때문에","correct":true},{"t":"마음을 나타내는 말은 시에 쓰면 안 되기 때문에","mis":"K6-2-u6-X12"}],"mis":"K6-2-u6-X12","explanation":["「너무 좋았다」만으로는 장면이 떠오르지 않아요.","쪽지를 펼친 손끝을 살려 봐요.","감각을 살리면 생생해져요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#19','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C17',3,'ox','auto','서하가 배경 음악을 「물 흐르는 소리」로 바꾸고 낭송보다 작게 틀면 낭송을 도울 수 있어요.',ARRAY['K6-2-u6-X22']::text[],false,'{"seq":19,"concept":"K6-2-u6-C17","difficulty":3,"kind":"ox","stem":"서하가 배경 음악을 「물 흐르는 소리」로 바꾸고 낭송보다 작게 틀면 낭송을 도울 수 있어요.","answer":"O","reason_options":[{"t":"시의 장면과 어울리고 목소리를 덮지 않기 때문에","correct":true},{"t":"음악은 무엇이든 틀기만 하면 낭송을 돕기 때문에","mis":"K6-2-u6-X22"}],"mis":"K6-2-u6-X22","explanation":["강물 장면과 어울려요.","목소리보다 작아요.","돕는 만큼만 써요."],"asset":{"type":"passage","lines":["시 · 「물수제비」","전하고 싶은 마음 · 아직 정하지 않음","모든 연 · 처음부터 끝까지 가장 큰 목소리로, 똑같이 빠르게","배경 음악 · 신나는 노래를 목소리보다 크게 계속 틀기","영상 · 반짝이는 꾸밈 화면을 쉬지 않고 바꾸기"],"title":"서하의 낭송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#20','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C27',3,'ox','auto','지안이의 계획에서 인물의 성격을 정리할 때, 베짱이가 「남을 위해 연습하는 성격」이라는 것은 베짱이가 한 일에서 드러나야 해요.',ARRAY['K6-2-u6-X33']::text[],false,'{"seq":20,"concept":"K6-2-u6-C27","difficulty":3,"kind":"ox","stem":"지안이의 계획에서 인물의 성격을 정리할 때, 베짱이가 「남을 위해 연습하는 성격」이라는 것은 베짱이가 한 일에서 드러나야 해요.","answer":"O","reason_options":[{"t":"인물의 성격은 그 인물이 한 말과 행동에서 드러나기 때문에","correct":true},{"t":"성격은 바꿀 것 칸에 적기만 하면 되기 때문에","mis":"K6-2-u6-X33"}],"mis":"K6-2-u6-X33","explanation":["성격은 적어 두는 것으로 끝나지 않아요.","하는 일에서 드러나야 해요.","그래야 읽는 사람이 알아요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#21','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',3,'ox','auto','함께 책을 만들 때 누가 무엇을 언제까지 맡을지 정하지 않아도 저절로 잘 만들어져요.',ARRAY['K6-2-u6-X42']::text[],false,'{"seq":21,"concept":"K6-2-u6-C33","difficulty":3,"kind":"ox","stem":"함께 책을 만들 때 누가 무엇을 언제까지 맡을지 정하지 않아도 저절로 잘 만들어져요.","answer":"X","reason_options":[{"t":"맡을 일과 마칠 때를 정해야 함께 만드는 일이 이어지기 때문에","correct":true},{"t":"함께 만들면 정하지 않아도 모두 알아서 하기 때문에","mis":"K6-2-u6-X42"}],"mis":"K6-2-u6-X42","explanation":["누구와 · 무엇을 · 언제까지 정해요.","정하지 않으면 빠지는 일이 생겨요.","다 만든 뒤 잘한 점부터 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#22','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C26',3,'mc','auto','「토끼와 자라」를 자라 바꾸기 계획대로 바꾸면 새로 생길 수 있는 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":22,"concept":"K6-2-u6-C26","difficulty":3,"kind":"mc","stem":"「토끼와 자라」를 자라 바꾸기 계획대로 바꾸면 새로 생길 수 있는 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"속이지 않고 사정을 털어놓으면 함께 길을 찾을 수 있다","correct":true},{"t":"꾀가 많은 사람이 언제나 이긴다","mis":"K6-2-u6-X32"},{"t":"용왕의 말은 무조건 따라야 한다","mis":"K6-2-u6-X32"},{"t":"바닷속은 위험한 곳이다","mis":"K6-2-u6-X32"}],"explanation":["원래는 토끼가 꾀로 살아남는 이야기예요.","바꾸자 자라가 사실대로 말하고 함께 약을 찾아요.","정직하게 털어놓는 뜻이 새로 생겨요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#23','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',4,'mc','auto','학급 이야기책 회의를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":23,"concept":"K6-2-u6-C33","difficulty":4,"kind":"mc","stem":"학급 이야기책 회의를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나래의 말처럼 중심 사건과 인물부터 정하고, 독자를 먼저 정해 형태를 고르며, 꾸미기는 이야기 뒤에, 나눌 때는 잘한 점부터 해야 한다","correct":true},{"t":"다온의 말처럼 표지를 먼저 꾸미면 된다","mis":"K6-2-u6-X41"},{"t":"루아의 말처럼 화면으로 보는 책이 언제나 정답이다","mis":"K6-2-u6-X38"},{"t":"시후의 말처럼 독자는 나중에 정해도 된다","mis":"K6-2-u6-X39"}],"explanation":["나래의 말이 알맞아요.","독자부터 정해요.","이야기가 먼저, 잘한 점부터 나눠요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#24','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C31',4,'essay','teacher','학급 이야기책 회의에서 알맞지 않은 말을 세 가지 골라 왜 알맞지 않은지 쓰고, 우리 반 책을 만드는 차례를 바르게 다시 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C31","difficulty":4,"kind":"essay","stem":"학급 이야기책 회의에서 알맞지 않은 말을 세 가지 골라 왜 알맞지 않은지 쓰고, 우리 반 책을 만드는 차례를 바르게 다시 정리하세요.","answer_guide":{"answer":"예: 첫째, 다온이가 표지부터 사흘 동안 꾸미자고 했는데, 꾸미기가 이야기를 덮으면 안 되므로 이야기를 먼저 완성해야 한다. 둘째, 루아가 화면으로 보는 책이 제일 좋다고 했는데, 형태에는 등수가 없고 독자에 따라 달라진다. 셋째, 시후가 독자를 나중에 정하자고 했는데, 독자가 정해져야 형태가 정해진다. 바른 차례 — 독자 정하기 → 독자에게 맞는 형태 고르기 → 중심 사건 · 인물 · 때와 곳 · 차례 정하고 글 쓰기 → 누가 무엇을 언제까지 맡을지 나누어 만들기 → 꾸미기는 돕는 만큼 → 다 만든 뒤 잘한 점부터 나누기.","scoring_points":["알맞지 않은 말 세 가지와 까닭을 썼는가","독자를 먼저 정하고 형태를 고르는 차례를 썼는가","이야기 먼저 · 꾸미기는 돕는 만큼 · 잘한 점부터를 썼는가"]},"explanation":["독자부터 정해요.","이야기가 먼저예요.","잘한 점부터 나눠요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u6_review_d#25','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C34',4,'essay','teacher','「메다 · 매다」를 모두 넣어 오늘 겪은 일을 짧은 글로 쓰고, 두 낱말을 어떻게 가려 썼는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C34","difficulty":4,"kind":"essay","stem":"「메다 · 매다」를 모두 넣어 오늘 겪은 일을 짧은 글로 쓰고, 두 낱말을 어떻게 가려 썼는지 설명하세요.","answer_guide":{"answer":"예: 아침에 운동화 끈을 단단히 매고, 무거운 가방을 어깨에 메고 학교까지 뛰어갔다. 「매다」는 끈이나 줄을 묶을 때 쓰므로 운동화 끈 자리에 썼고, 「메다」는 어깨에 걸쳐 질 때 쓰므로 가방 자리에 썼다. 두 낱말은 소리가 같지만 뜻이 달라 앞뒤 문장을 보고 골라 써야 한다.","scoring_points":["두 낱말을 모두 넣어 겪은 일을 썼는가","각 낱말을 뜻에 맞는 자리에 썼는가","가려 쓴 까닭을 뜻으로 설명했는가"]},"explanation":["겪은 일 가운데 떠올려요.","뜻에 맞는 자리에 써요.","앞뒤 문장을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C1','math',6,2,'u1',2,'나누는 수가 분수인 나눗셈의 뜻 — 같은 종류의 양을 얼마씩 몇 번 덜어 낼 수 있는지 묻는 자리임을 알고, (자연수)÷(자연수)·(분수)÷(자연수)를 바탕으로 식을 세우기',ARRAY['6수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C2','math',6,2,'u1',2,'분모가 같은 (분수)÷(분수) — 두 분수가 같은 단위분수 몇 개인지 세어 분자끼리 나누고, 분모는 답에 남지 않음을 알기',ARRAY['6수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C3','math',6,2,'u1',3,'분모가 같은 (분수)÷(분수) — 분자끼리 나누어떨어지지 않으면 몫을 분수로 나타내고, 몫의 분수 부분은 남은 양이 아니라 한 몫의 얼마인지를 뜻함을 알기',ARRAY['6수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C4','math',6,2,'u1',4,'분모가 다른 (분수)÷(분수) — 두 분수를 같은 크기의 조각으로 다시 세는 통분을 한 뒤 분자끼리 나누기',ARRAY['6수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C5','math',6,2,'u1',5,'(자연수)÷(단위분수) — 단위분수가 1 안에 분모만큼 들어감을 알고 자연수에 분모를 곱해 구하며, 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커짐을 알기',ARRAY['6수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C6','math',6,2,'u1',6,'(자연수)÷(진분수) — 분자로 나누고 분모를 곱하는 두 걸음을 한 줄로 적어 나누는 분수의 분모와 분자를 바꾸어 곱하기',ARRAY['6수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C7','math',6,2,'u1',7,'(분수)÷(분수)를 분수의 곱셈으로 — 나누는 분수만 분모와 분자를 바꾸어 곱하고, 나누어지는 분수는 그대로 두어야 함을 알기',ARRAY['6수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C8','math',6,2,'u1',8,'대분수의 나눗셈 — 대분수를 먼저 가분수로 고친 뒤 통분해 분자끼리 나누거나 곱셈으로 바꾸어 계산하기(두 길의 답은 같다)',ARRAY['6수01-10']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C9','math',6,2,'u1',9,'문제 해결 — 길이 ÷ 타일 한 변으로 가로·세로에 들어가는 개수를 구하고, 가로 수 × 세로 수로 필요한 타일 수를 구하기(조건을 바꾸어도 방법은 같다)',ARRAY['6수01-10']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X01','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C6','M6-2-u1-C7']::text[],'나눗셈식을 거꾸로 세운다 — 나누어지는 양과 나누는 양을 바꾸어 (나누는 양)÷(나누어지는 양)으로 쓴다','「무엇을 얼마씩」 — 무엇이 앞, 얼마씩이 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X02','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3']::text[],'분모가 같은 나눗셈에서 분모를 답에 남기거나 분모끼리도 나눈다(⟨3/4⟩ ÷ ⟨1/4⟩ = ⟨3/4⟩, 분모끼리 4 ÷ 4)','같은 조각이면 개수만 — 분모는 답에 안 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X03','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C5','M6-2-u1-C6']::text[],'나눗셈 대신 분자끼리 빼거나 더한다(연산을 바꾼다)','「몇 번 덜어 낼 수 있나」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X04','math',6,'u1',ARRAY['M6-2-u1-C3']::text[],'몫의 분수 부분을 「남은 양」으로 읽는다(⟨5/6⟩ ÷ ⟨2/6⟩ = 2⟨1/2⟩에서 ⟨1/2⟩이 남았다고 본다)','몫은 컵의 수 — 분수 부분은 컵 하나의 얼마') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X05','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'나누어떨어지지 않을 때 몫을 거꾸로 적는다(4 ÷ 7을 ⟨7/4⟩로)','나누어지는 수가 분자, 나누는 수가 분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X06','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'분모가 다른데 통분하지 않고 분자끼리 바로 나눈다','조각 크기가 다르면 먼저 같은 조각으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X07','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'통분을 한쪽만 하거나 분모만 바꾸고 분자를 그대로 둔다','분모를 바꾼 만큼 분자도 같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X08','math',6,'u1',ARRAY['M6-2-u1-C5']::text[],'(자연수)÷(단위분수)에서 분모로 나누거나 분모만 답으로 쓴다(5 ÷ ⟨1/3⟩ = ⟨5/3⟩)','⟨1/3⟩은 1 안에 3번 — 분모를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X09','math',6,'u1',ARRAY['M6-2-u1-C5','M6-2-u1-C6']::text[],'「나눗셈을 하면 몫은 늘 작아진다」고 여겨 몫이 커지는 것을 틀렸다고 본다','1보다 작은 수로 나누면 몫이 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X10','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C9']::text[],'나누는 분수를 뒤집지 않고 그대로 곱한다(4 ÷ ⟨2/3⟩ = 4 × ⟨2/3⟩)','나누는 분수의 분모와 분자를 바꾸어 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X11','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C9']::text[],'두 걸음의 순서를 거꾸로 한다 — 분모로 나누고 분자를 곱한다','분자로 나누고(÷2) 분모를 곱해요(×3)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X12','math',6,'u1',ARRAY['M6-2-u1-C7','M6-2-u1-C8']::text[],'두 분수를 다 뒤집거나 앞 분수를 뒤집는다(또는 아무것도 안 뒤집고 곱한다)','뒤집는 것은 나누는 분수 하나뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X13','math',6,'u1',ARRAY['M6-2-u1-C8','M6-2-u1-C9']::text[],'대분수를 가분수로 고치지 않고 자연수 부분과 분수 부분을 따로 나누거나 대분수 그대로 뒤집는다','대분수는 먼저 가분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X14','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 분모를 곱하지 않는다)','자연수 × 분모 + 분자가 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X15','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'계산 마무리 실수 — 약분하지 않거나 가분수·대분수로 잘못 고친다','몫은 약분해서 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X16','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7']::text[],'몫을 견줄 때 나누는 수가 클수록 몫도 크다고 여긴다','나누는 수가 작을수록 몫이 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X17','math',6,'u1',ARRAY['M6-2-u1-C9']::text[],'가로에 들어가는 수와 세로에 들어가는 수를 더해 전체 타일 수로 본다(곱해야 한다)','가로 줄이 세로 줄 수만큼 늘어선 것 — 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X18','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C5','M6-2-u1-C9']::text[],'무엇을 묻는지 놓친다 — 개수를 묻는데 양을 쓰거나 나누어지는 양을 그대로 답으로 쓴다','묻는 것이 「몇 개」인지 「얼마」인지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X19','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'어떤 수 문제에서 거꾸로 계산을 잘못한다 — 곱한 결과를 다시 곱하거나 결과를 그대로 어떤 수로 본다','곱했으면 거꾸로 나누어 어떤 수를 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X20','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C8','M6-2-u1-C9']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 큰↔작은, 가능↔불가능','물음의 「잘못·가장·없는」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#1','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨3/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈으로 구해요.","나누어지는 양 ⟨3/5⟩이 앞, 얼마씩인 ⟨1/5⟩이 뒤 — ⟨3/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1,"label":"⟨3/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨4/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/5⟩ + ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩ m에서 ⟨1/5⟩ m씩 덜어 내는 거예요.","몇 번 덜어 낼 수 있는지는 나눗셈이에요.","⟨4/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1,"label":"⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]}},{"stem":"물 ⟨8/9⟩ L를 한 컵에 ⟨2/9⟩ L씩 나누어 담아요. 필요한 컵의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨8/9⟩ ÷ ⟨2/9⟩","correct":true},{"t":"⟨2/9⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X01"},{"t":"⟨8/9⟩ × ⟨2/9⟩","mis":"M6-2-u1-X03"},{"t":"⟨8/9⟩ − ⟨2/9⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨8/9⟩ L에서 ⟨2/9⟩ L씩 덜어 내요.","같은 양을 몇 번 덜어 낼 수 있는지 — 나눗셈이에요.","⟨8/9⟩ ÷ ⟨2/9⟩예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2,"label":"⟨8/9⟩에서 ⟨2/9⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#2','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'mc','auto','⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":2,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?","explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨1/4⟩은 ⟨1/4⟩이 1개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 3 ÷ 1 = 3.","분모 4는 답에 남지 않아요. 몫은 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"3","correct":true},{"t":"⟨3/4⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"},{"t":"2","mis":"M6-2-u1-X03"}],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨3/4⟩에서 ⟨1/4⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#3','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'sa','auto','⟨12/13⟩ ÷ ⟨3/13⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"⟨12/13⟩ ÷ ⟨3/13⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개, ⟨3/13⟩은 ⟨1/13⟩이 3개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 12 ÷ 3 = 4.","분모 13은 답에 남지 않아요. 몫은 4예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#4','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03']::text[],true,'{"seq":4,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"9개","mis":"M6-2-u1-X02"},{"t":"7개","mis":"M6-2-u1-X03"},{"t":"18개","mis":"M6-2-u1-X02"}],"explanation":["⟨2/9⟩는 ⟨1/9⟩ 조각을 2개 모은 수예요.","분모 9는 조각의 크기, 분자 2는 조각의 개수예요.","그래서 ⟨1/9⟩이 2개예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":2,"grp":1}]},"variant_rule":{"alt":[{"stem":"⟨3/5⟩은 ⟨1/5⟩이 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"5개","mis":"M6-2-u1-X02"},{"t":"2개","mis":"M6-2-u1-X03"},{"t":"15개","mis":"M6-2-u1-X02"}],"explanation":["⟨3/5⟩은 ⟨1/5⟩ 조각 3개예요.","분자가 조각의 개수예요.","⟨1/5⟩이 3개예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1}]}},{"stem":"⟨7/10⟩은 ⟨1/10⟩이 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"10개","mis":"M6-2-u1-X02"},{"t":"3개","mis":"M6-2-u1-X03"},{"t":"70개","mis":"M6-2-u1-X02"}],"explanation":["⟨7/10⟩은 ⟨1/10⟩ 조각 7개예요.","분자가 조각의 개수예요.","⟨1/10⟩이 7개예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":7,"grp":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#5','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'sa','auto','색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.","explanation":["⟨10/20⟩을 ⟨2/20⟩씩 나누는 식은 ⟨10/20⟩ ÷ ⟨2/20⟩예요.","분모가 같으니 분자끼리 나눠요 — 10 ÷ 2 = 5.","친구는 5명 필요해요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["5","5명"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#6','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'ox','auto','⟨6/7⟩ ÷ ⟨2/7⟩ = ⟨3/7⟩이에요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨6/7⟩ ÷ ⟨2/7⟩ = ⟨3/7⟩이에요.","answer":"X","reason_options":[{"t":"같은 조각의 개수끼리 나누는 것이라 6 ÷ 2 = 3, 분모는 답에 남지 않아서","correct":true},{"t":"분자끼리 나누고 분모는 그대로 두어야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","같은 크기의 조각이니 6 ÷ 2 = 3이에요.","몫은 3 — 분모 7은 답에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":6,"grp":2,"label":"⟨6/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#7','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C2","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨8/9⟩ ÷ ⟨2/9⟩","r":"4"},{"l":"⟨9/10⟩ ÷ ⟨3/10⟩","r":"3"},{"l":"⟨10/11⟩ ÷ ⟨5/11⟩","r":"2"}],"mis":"M6-2-u1-X02","explanation":["분모가 같으면 분자끼리 나눠요.","8 ÷ 2 = 4, 9 ÷ 3 = 3, 10 ÷ 5 = 2예요.","분모는 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨6/7⟩ ÷ ⟨3/7⟩","r":"2"},{"l":"⟨12/13⟩ ÷ ⟨2/13⟩","r":"6"},{"l":"⟨15/16⟩ ÷ ⟨3/16⟩","r":"5"}],"explanation":["분자끼리 나눠요.","6 ÷ 3 = 2, 12 ÷ 2 = 6, 15 ÷ 3 = 5예요.","분모는 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#8','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',2,'mc','auto','6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3의 몫은 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X10','M6-2-u1-X02']::text[],true,'{"seq":8,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3의 몫은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M6-2-u1-X03"},{"t":"⟨18/7⟩","mis":"M6-2-u1-X10"},{"t":"2","mis":"M6-2-u1-X02"}],"explanation":["분자 6을 3으로 나눌 수 있어요 — 6 ÷ 3 = 2.","분모는 그대로 7이에요.","그래서 ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"6학년 1학기에 배운 (자연수)÷(자연수)예요. 4 ÷ 5의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/5⟩","mis":"M6-2-u1-X05"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","4 ÷ 5 = ⟨4/5⟩예요.","⟨5/4⟩로 거꾸로 적지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#9','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'mc','auto','⟨14/15⟩ ÷ ⟨7/15⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":2,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨7/15⟩의 몫은 얼마인가요?","explanation":["⟨14/15⟩는 ⟨1/15⟩이 14개, ⟨7/15⟩은 ⟨1/15⟩이 7개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 14 ÷ 7 = 2.","분모 15는 답에 남지 않아요. 몫은 2예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"2","correct":true},{"t":"⟨2/15⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/2⟩","mis":"M6-2-u1-X05"},{"t":"7","mis":"M6-2-u1-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#10','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',3,'mc','auto','⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":10,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 14 ÷ □예요.","14를 나누어떨어지게 하는 수를 찾아요.","14 ÷ 2 = 7이라 □는 2예요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"2","correct":true},{"t":"11","mis":"M6-2-u1-X02"},{"t":"5","mis":"M6-2-u1-X02"},{"t":"12","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#1','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',2,'sa','auto','끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 쓰려고 해요. 편지는 몇 장 꾸밀 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 쓰려고 해요. 편지는 몇 장 꾸밀 수 있나요? 숫자로 쓰세요.","explanation":["⟨4/5⟩를 ⟨1/5⟩씩 나누는 식은 ⟨4/5⟩ ÷ ⟨1/5⟩이에요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 1 = 4.","편지는 4장 꾸밀 수 있어요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["4","4장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#2','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',2,'error','auto','잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 병에 담는 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X20']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"error","stem":"잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 병에 담는 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「나누는 수가 분수니까 나눗셈이 아니라 곱셈으로 풀어야 해.」","correct":true,"mis_target":"M6-2-u1-X03"},{"t":"도윤 — 「구슬 6개를 2개씩 담는 것과 똑같은 물음이야.」","mis":"M6-2-u1-X20"},{"t":"하린 — 「⟨3/5⟩은 ⟨1/5⟩이 3개니까 병은 3개야.」","mis":"M6-2-u1-X20"}],"explanation":["같은 양을 몇 번 덜어 낼 수 있는지 묻는 것은 늘 나눗셈이에요.","단위가 분수로 바뀌었을 뿐 묻는 방식은 6 ÷ 2와 같아요.","수아는 나누는 수가 분수라고 연산을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#3','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 9 ÷ □예요.","9를 나누어떨어지게 하는 수를 찾아요.","9 ÷ 3 = 3이라 □는 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"3","correct":true},{"t":"7","mis":"M6-2-u1-X02"},{"t":"2","mis":"M6-2-u1-X02"},{"t":"6","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#4','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["분모가 같으니 분자끼리 나누어 몫을 구해요.","⟨10/11⟩ ÷ ⟨9/11⟩ = ⟨1 1/9⟩, ⟨5/6⟩ ÷ ⟨4/6⟩ = ⟨1 1/4⟩, ⟨8/9⟩ ÷ ⟨5/9⟩ = ⟨1 3/5⟩, ⟨8/9⟩ ÷ ⟨7/9⟩ = ⟨1 1/7⟩이에요.","가장 큰 몫은 ⟨8/9⟩ ÷ ⟨5/9⟩예요."],"variant_rule":{"fd":{"ask":"cmp","kind":"same"}},"options":[{"t":"⟨8/9⟩ ÷ ⟨5/9⟩","correct":true},{"t":"⟨5/6⟩ ÷ ⟨4/6⟩","mis":"M6-2-u1-X16"},{"t":"⟨8/9⟩ ÷ ⟨7/9⟩","mis":"M6-2-u1-X16"},{"t":"⟨10/11⟩ ÷ ⟨9/11⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#5','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',3,'mc','auto','끈 ⟨8/9⟩ m로 한 장에 ⟨2/9⟩ m씩 쓰는 편지를 꾸며요. 다음 중 꾸밀 수 있는 편지 수를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],false,'{"seq":5,"concept":"M6-2-u1-C1","difficulty":3,"kind":"mc","stem":"끈 ⟨8/9⟩ m로 한 장에 ⟨2/9⟩ m씩 쓰는 편지를 꾸며요. 다음 중 꾸밀 수 있는 편지 수를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"⟨8/9⟩ − ⟨2/9⟩를 계산한다","correct":true},{"t":"⟨8/9⟩에서 ⟨2/9⟩를 몇 번 덜어 낼 수 있는지 센다","mis":"M6-2-u1-X20"},{"t":"⟨8/9⟩ ÷ ⟨2/9⟩를 계산한다","mis":"M6-2-u1-X20"},{"t":"⟨1/9⟩이 8개인 것을 ⟨1/9⟩ 2개씩 묶어 본다","mis":"M6-2-u1-X20"}],"explanation":["몇 장인지는 ⟨8/9⟩에서 ⟨2/9⟩를 몇 번 덜어 내는지 세는 거예요.","덜어 내기 · 나눗셈 · 조각 묶기는 모두 같은 생각이에요.","뺄셈 ⟨8/9⟩ − ⟨2/9⟩는 한 번 덜어 내고 남은 양일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#6','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 3이 되게 하려면 □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X02','M6-2-u1-X19']::text[],true,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 3이 되게 하려면 □에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M6-2-u1-X03"},{"t":"2","mis":"M6-2-u1-X02"},{"t":"27","mis":"M6-2-u1-X19"}],"explanation":["분모가 같으니 몫은 9 ÷ □예요.","9 ÷ □ = 3이 되는 □는 3이에요.","⟨9/11⟩ ÷ ⟨3/11⟩ = 3이에요."],"variant_rule":{"alt":[{"stem":"⟨10/13⟩ ÷ ⟨□/13⟩의 몫이 5가 되게 하려면 □에 알맞은 수는 얼마인가요?","options":[{"t":"2","correct":true},{"t":"5","mis":"M6-2-u1-X03"},{"t":"50","mis":"M6-2-u1-X19"},{"t":"8","mis":"M6-2-u1-X02"}],"explanation":["몫은 10 ÷ □예요.","10 ÷ □ = 5이면 □ = 2예요.","⟨10/13⟩ ÷ ⟨2/13⟩ = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#7','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','분모가 모두 13인 분수 ⟨12/13⟩ · ⟨3/13⟩ · ⟨4/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":7,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"분모가 모두 13인 분수 ⟨12/13⟩ · ⟨3/13⟩ · ⟨4/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?","explanation":["가장 큰 분수는 ⟨12/13⟩, 가장 작은 분수는 ⟨3/13⟩이에요.","분모가 같으니 분자끼리 나눠요 — 12 ÷ 3 = 4.","그래서 몫은 4예요."],"variant_rule":{"fd":{"ask":"maxmin"}},"options":[{"t":"4","correct":true},{"t":"⟨1/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨9/13⟩","mis":"M6-2-u1-X03"},{"t":"⟨12/39⟩","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#8','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',4,'essay','teacher','구슬 6개를 2개씩 담으면 6 ÷ 2 = 3봉지예요. 잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 담는 것도 왜 나눗셈으로 풀 수 있는지, 두 상황의 같은 점을 들어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C1","difficulty":4,"kind":"essay","stem":"구슬 6개를 2개씩 담으면 6 ÷ 2 = 3봉지예요. 잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 담는 것도 왜 나눗셈으로 풀 수 있는지, 두 상황의 같은 점을 들어 설명해 보세요.","answer_guide":{"answer":"예: 두 상황 모두 「전체를 같은 양씩 덜어 내면 몇 번(몇 개) 되는가」를 묻는다. 구슬은 2개씩, 잼은 ⟨1/5⟩ kg씩 덜어 낸다는 단위만 다를 뿐 묻는 방식이 같으므로 ⟨3/5⟩ ÷ ⟨1/5⟩ = 3으로 나눗셈이 된다.","scoring_points":["같은 양씩 덜어 내는 횟수를 묻는다는 공통점을 썼는가","단위만 다르다는 점을 밝혔는가","⟨3/5⟩ ÷ ⟨1/5⟩ = 3을 식으로 썼는가"]},"explanation":["두 상황 모두 같은 양씩 몇 번 덜어 내는지 물어요.","덜어 내는 단위가 2개에서 ⟨1/5⟩ kg으로 바뀌었을 뿐이에요.","그래서 ⟨3/5⟩ ÷ ⟨1/5⟩ = 3으로 나눗셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#9','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',4,'essay','teacher','⟨9/10⟩ ÷ ⟨3/10⟩을 계산하면 몫은 3이에요. 몫에 분모 10이 남지 않는 까닭을 ⟨1/10⟩ 조각의 개수를 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":4,"kind":"essay","stem":"⟨9/10⟩ ÷ ⟨3/10⟩을 계산하면 몫은 3이에요. 몫에 분모 10이 남지 않는 까닭을 ⟨1/10⟩ 조각의 개수를 들어 설명해 보세요.","answer_guide":{"answer":"예: ⟨9/10⟩는 ⟨1/10⟩ 조각 9개이고 ⟨3/10⟩은 ⟨1/10⟩ 조각 3개이다. 조각의 크기가 같으니 조각의 개수만 견주면 되어 9 ÷ 3 = 3이다. 분모 10은 조각의 크기를 나타낼 뿐 개수를 세는 데는 쓰이지 않으므로 답에 남지 않는다.","scoring_points":["두 분수를 ⟨1/10⟩ 조각의 개수로 바꾸었는가","9 ÷ 3 = 3을 썼는가","분모는 조각 크기라 답에 남지 않음을 설명했는가"]},"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개, ⟨3/10⟩은 ⟨1/10⟩이 3개예요.","같은 조각이라 개수끼리 9 ÷ 3 = 3이에요.","분모 10은 조각 크기일 뿐이라 답에 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#10','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',4,'mc','auto','⟨8/15⟩ ÷ ⟨□/15⟩의 몫이 4이고, ⟨12/15⟩ ÷ ⟨□/15⟩의 몫이 6이에요. 두 식의 □는 같은 수예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03']::text[],true,'{"seq":10,"concept":"M6-2-u1-C2","difficulty":4,"kind":"mc","stem":"⟨8/15⟩ ÷ ⟨□/15⟩의 몫이 4이고, ⟨12/15⟩ ÷ ⟨□/15⟩의 몫이 6이에요. 두 식의 □는 같은 수예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2","correct":true},{"t":"4","mis":"M6-2-u1-X02"},{"t":"3","mis":"M6-2-u1-X02"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["첫 식에서 8 ÷ □ = 4니 □ = 2예요.","둘째 식에서도 12 ÷ 2 = 6으로 맞아요.","그래서 □는 2예요."],"variant_rule":{"alt":[{"stem":"⟨9/14⟩ ÷ ⟨□/14⟩의 몫이 3이고, ⟨12/14⟩ ÷ ⟨□/14⟩의 몫이 4예요. 두 식의 □는 같은 수예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M6-2-u1-X02"},{"t":"6","mis":"M6-2-u1-X02"},{"t":"2","mis":"M6-2-u1-X03"}],"explanation":["9 ÷ □ = 3이니 □ = 3이에요.","12 ÷ 3 = 4로 둘째 식도 맞아요.","□는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#1','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨3/10⟩ ÷ ⟨7/10⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":1,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3/10⟩ ÷ ⟨7/10⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 3 ÷ 7.","나누어떨어지지 않으면 몫을 분수로 적어요 — 3 ÷ 7 = ⟨3/7⟩.","몫 ⟨3/7⟩은 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X05"},{"t":"⟨4/10⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/70⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":10,"num":3,"grp":7,"label":"⟨3/10⟩에서 ⟨7/10⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
